window.QUESTIONS=[{"id": "110-1-A-01", "exam": "110-1", "paper": "A", "q": 1, "unit": "一、會計基本概念", "topic": "法人資格", "stem": "下列有哪幾項不具有法人資格?\n①小明一人獨資所經營之「豐馥麵包烘培坊」\n②某導演想籌拍電影,故組成由導演擔任普通合夥人,找創投投資資金者擔任有限合夥人,約定電影行銷、製作與利益分配,當電影拍完,合夥關係就結束之「有限合夥組織」\n③蕭川與李頌兩位會計師合夥成立之「川頌聯合會計師事務所」\n④郭統所成立之「宏海股份有限公司」", "options": ["①③", "②③", "①②③", "①②③④"], "answer": "A", "figure": null, "official": "①獨資不具法人資格;②有限合夥組織具法人資格;③合夥不具法人資格;④股份有限公司為公司組織,具法人資格。", "explain": {"concept": "判斷企業組織型態是否具有法人資格。獨資、合夥(普通合夥)無法人資格;公司組織與有限合夥組織有法人資格。", "steps": ["獨資是一個人經營,事業與老闆在法律上是同一個人,所以①沒有法人資格。", "普通合夥是幾個人共同經營,法律上仍是合夥人自己負責,所以③會計師事務所(合夥)沒有法人資格。", "有限合夥組織依有限合夥法成立,有法人資格,所以②具有法人資格。", "股份有限公司是公司組織,依公司法成立,有法人資格,所以④具有。", "題目問「不具有」,答案是①③,選 A。"], "pitfalls": "看到「有限合夥」容易誤以為和合夥一樣沒有法人資格,其實有限合夥組織是有法人資格的。", "distractors": {"B": "誤以為有限合夥(②)不具法人資格,且漏掉獨資①。", "C": "把有限合夥②也算成不具法人資格。", "D": "以為全部都不具法人資格,沒有分辨公司組織有法人資格。"}}, "check": "逐項判斷:①無、②有、③無、④有,不具者為①③,與官方 A 相符。", "verified": true, "note": ""}, {"id": "110-1-A-02", "exam": "110-1", "paper": "A", "q": 2, "unit": "十、加值型營業稅會計實務", "topic": "營業稅基本規定", "stem": "有關我國營業稅的敘述,下列何者正確?", "options": ["加值型營業稅之稅率一律為 5%", "目前我國以加值型營業稅來課徵各行各業的營業稅", "當銷售貨物或勞務買受人為營業人需開立三聯式統一發票", "經營免營業稅項目之營業,其購進貨物或勞務亦免課營業稅"], "answer": "C", "figure": null, "official": "(A)稅率有一般5%、零稅率0%及免稅;(B)金融保險業、特種飲食業、小規模營業人等不適用加值型;(D)免稅營業之購進貨物或勞務仍應課營業稅。", "explain": {"concept": "認識加值型營業稅的稅率、適用範圍與發票開立規定。", "steps": ["(A)加值型營業稅除了一般稅率 5%,還有零稅率 0% 以及免稅,不是一律 5%,所以錯。", "(B)金融保險業、特種飲食業、小規模營業人等不適用加值型營業稅(用其他方式課徵),所以不是各行各業都用加值型,錯。", "(C)買受人是營業人時,賣方要開立三聯式統一發票(買方才能扣抵進項稅額),正確。", "(D)免稅是銷售時不收營業稅,但買進東西時付的進項稅額照付,不能退也不能扣抵,所以購進仍課稅,錯。", "答案選 C。"], "pitfalls": "免稅與零稅率不同:零稅率進項可退稅,免稅進項不可扣抵。", "distractors": {"A": "忽略零稅率與免稅的存在。", "B": "以為加值型適用所有行業,忽略金融保險業等例外。", "D": "把「免稅」誤解成連進貨都不用繳營業稅。"}}, "check": "概念題,與官方詳解及加值型營業稅法常識一致。", "verified": true, "note": ""}, {"id": "110-1-A-03", "exam": "110-1", "paper": "A", "q": 3, "unit": "一、會計基本概念", "topic": "商業會計法規定", "stem": "王大明出資經營大明商店,盈虧自負,並聘請小芳擔任會計人員,以下為王大明業主聘任小芳時告知之事項,依據商業會計法,下列敘述何者錯誤?", "options": ["各項會計憑證,除應永久保存或有關未結會計事項者外,應於年度決算程序辦理終了後,至少保存五年", "會計事項應按發生次序逐日登帳,至遲不得超過一個月", "故意遺漏會計事項不為登錄,致使財務報表發生不實之結果,處五年以下有期徒刑、拘役或科或併科新臺幣六十萬元以下罰金", "企業必須設置之會計帳簿,為普通序時帳簿及總分類帳簿,均應按其頁數順序編號,不得毀損"], "answer": "B", "figure": null, "official": "會計事項應按發生次序逐日登帳,至遲不得超過二個月。", "explain": {"concept": "商業會計法對登帳期限、憑證保存年限等的規定。", "steps": ["先逐項回想商業會計法的規定。", "(A)憑證於年度決算程序辦理終了後至少保存五年,正確。", "(B)會計事項應逐日登帳,「至遲不得超過二個月」,題目寫一個月,所以錯誤。", "(C)故意遺漏登錄致財務報表不實,處五年以下有期徒刑、拘役或科或併科六十萬元以下罰金,正確。", "(D)必須設置的帳簿為普通序時帳簿及總分類帳簿,應按頁數順序編號,不得毀損,正確。", "題目問「錯誤」,答案選 B。"], "pitfalls": "登帳期限是「二個月」,不要記成一個月。", "distractors": {"A": "此敘述正確(憑證至少保存五年)。", "C": "此敘述正確(罰則為五年以下有期徒刑、拘役或科或併科六十萬元以下罰金)。", "D": "此敘述正確。"}}, "check": "依商業會計法逐項核對,與官方 B 相符。", "verified": true, "note": ""}, {"id": "110-1-A-04", "exam": "110-1", "paper": "A", "q": 4, "unit": "一、會計基本概念", "topic": "會計事務委任", "stem": "張群欲委由他人代為處理其所經營群賢商店之會計事務,請問不得委由下列何者辦理?", "options": ["會計師", "記帳士", "記帳及報稅代理業務人", "其他代客記帳業者"], "answer": "D", "figure": null, "official": "依商業會計法第5條,商業會計事務得委由會計師或依法取得得處理會計事務資格之人處理之,故(D)其他代客記帳業者不符合相關規定。", "explain": {"concept": "商業會計法規定可受託處理會計事務的資格。", "steps": ["商業會計法第 5 條規定,會計事務可以自己的會計人員處理,也可以委託「會計師」或「依法取得處理會計事務資格的人」。", "依法取得資格者包括記帳士、記帳及報稅代理業務人。", "(D)「其他代客記帳業者」沒有依法取得資格,不得受託,所以題目要選 D。"], "pitfalls": "只看到「代客記帳」就以為都可以;關鍵是要「依法取得資格」。", "distractors": {"A": "會計師依法可以辦理,所以不是答案。", "B": "記帳士依法取得資格,可辦理。", "C": "記帳及報稅代理業務人依法取得資格,可辦理。"}}, "check": "概念題,與官方詳解一致。", "verified": true, "note": ""}, {"id": "110-1-A-05", "exam": "110-1", "paper": "A", "q": 5, "unit": "一、會計基本概念", "topic": "會計基本假設", "stem": "臺基股份有限公司的行銷總監對產品銷售策略頗有獨到之創意,為公司帶來許多收益,但其獨到創意之能力無法以貨幣量化,故無法記入帳冊中,請問此係依據何會計基本假設?", "options": ["企業個體假設", "應計基礎", "貨幣評價假設", "報導期間假設"], "answer": "C", "figure": null, "official": "貨幣評價假設,需能以貨幣為衡量單位方可記錄,故管理者的能力無法以貨幣衡量,無法以會計來傳達。", "explain": {"concept": "辨別會計基本假設:貨幣評價假設。", "steps": ["題目重點:創意能力「無法以貨幣量化」所以不能記帳。", "會計只記錄能用貨幣衡量的交易與事項,這就是貨幣評價(貨幣單位)假設。", "企業個體假設是指企業與業主分開;應計基礎是賺到就認列收入、發生就認列費用;報導期間假設是把企業生命分成一段段期間報導,都和「能否用貨幣衡量」無關。", "所以選 C。"], "pitfalls": "容易看到「公司」就選企業個體假設,但題目關鍵字是「無法以貨幣量化」。", "distractors": {"A": "企業個體假設是企業與業主分開,與能否量化無關。", "B": "應計基礎是認列時點的問題。", "D": "報導期間假設是把壽命分期報導。"}}, "check": "概念題,與官方詳解一致。", "verified": true, "note": ""}, {"id": "110-1-A-06", "exam": "110-1", "paper": "A", "q": 6, "unit": "一、會計基本概念", "topic": "對內外會計事項", "stem": "有關群賢商店會計事項之敘述,下列何者正確?", "options": ["支付員工薪資為對內會計事項", "與運貨公司簽訂送貨合約為對外會計事項", "向供應商訂購商品未付訂金,為對外會計事項", "群賢商店因豪大雨,致使放置於倉庫之商品泡水發生損失為對內會計事項"], "answer": "D", "figure": null, "official": "(A)支付員工薪資為對外會計事項;(B)與運貨公司簽訂送貨合約為非會計事項;(C)向供應商訂購商品未付訂金,為非會計事項。", "explain": {"concept": "區分會計事項(對內、對外)與非會計事項。", "steps": ["會計事項是指會使資產、負債、權益發生增減變動的事項;與外界發生交易的是對外,企業內部發生的是對內(如折舊、損失)。", "(A)付薪資是與員工之間的交易,屬對外,不是對內,錯。", "(B)簽訂送貨合約只是簽約,尚未使資產負債發生變動,屬非會計事項,錯。", "(C)訂購商品又沒付訂金,同樣沒有使資產負債變動,屬非會計事項,錯。", "(D)商品泡水損失使資產減少、損失發生,不涉及外部交易,屬對內會計事項,正確。"], "pitfalls": "簽約、訂購(未付款)只是承諾,不算會計事項。", "distractors": {"A": "以為付錢給員工是內部事項,其實對象是外部的員工。", "B": "把簽約當成交易,忽略資產負債並未變動。", "C": "同 B,訂購未付訂金不影響資產負債。"}}, "check": "概念題,與官方詳解一致。", "verified": true, "note": ""}, {"id": "110-1-A-07", "exam": "110-1", "paper": "A", "q": 7, "unit": "一、會計基本概念", "topic": "會計恆等式求損益", "stem": "群賢商店權益帳戶期初餘額$200,000,期末餘額$295,000,年度中商店曾代業主支付房租$30,000,因商店經營狀況良好,故業主於本期增資$50,000,請計算商店本期損益為何?", "options": ["淨利$5,000", "淨利$45,000", "淨利$75,000", "淨利$95,000"], "answer": "C", "figure": null, "official": "期初權益$200,000+本期增資$50,000-代付租金$30,000+本期損益=期末權益$295,000,本期損益=淨利$75,000。", "explain": {"concept": "權益變動公式:期末權益=期初權益+增資-提取+淨利(損)。", "steps": ["商店替業主支付房租,是業主私人的支出,等於業主從商店提取資產,會使權益減少 $30,000(不是商店費用)。", "列公式:期初權益 $200,000 + 增資 $50,000 - 提取 $30,000 + 本期損益 = 期末權益 $295,000。", "$200,000 + $50,000 - $30,000 = $220,000。", "本期損益 = $295,000 - $220,000 = $75,000(淨利)。"], "pitfalls": "代業主支付房租要當成「業主提取」減少權益,而不是商店的費用。", "distractors": {"B": "算成 $295,000-$200,000-$50,000=$45,000,漏掉代付房租 $30,000 是業主提取。", "D": "算成 $295,000-$200,000=$95,000,沒扣增資也沒處理提取。"}}, "check": "python:295000-(200000+50000-30000)=75000,與官方相符。", "verified": true, "note": ""}, {"id": "110-1-A-08", "exam": "110-1", "paper": "A", "q": 8, "unit": "二、會計循環及會計帳簿", "topic": "傳票", "stem": "下列敘述正確者為何?\n①償還貨欠並取得1%折讓,若採複式傳票四分法,應編製現金轉帳傳票\n②代傳票是指以記帳憑證代替原始憑證\n③單式傳票每一會計項目填製一張傳票\n④傳票為會計事項之記帳憑證", "options": ["①②③", "①③④", "②③④", "①②③④"], "answer": "B", "figure": null, "official": "②代傳票是指以原始憑證代替記帳憑證。", "explain": {"concept": "傳票制度的種類與定義。", "steps": ["①償還貨欠(現金付出)並取得折讓(折讓不是現金),部分現金、部分非現金,屬「部分轉帳」交易,四分法要編現金轉帳傳票,正確。", "②代傳票是用「原始憑證」代替「記帳憑證(傳票)」,題目說反了,錯。", "③單式傳票是每一個會計項目填一張傳票,正確。", "④傳票是記帳憑證,正確。", "正確為①③④,選 B。"], "pitfalls": "代傳票的方向容易記反:是原始憑證代替傳票。", "distractors": {"A": "誤以為②正確。", "C": "漏掉①,且誤把②當成正確。", "D": "全部都選,沒發現②說反了。"}}, "check": "概念題,與官方詳解一致。", "verified": true, "note": ""}, {"id": "110-1-A-09", "exam": "110-1", "paper": "A", "q": 9, "unit": "四、分錄與日記簿", "topic": "交易種類與日記簿", "stem": "下列敘述何者錯誤?", "options": ["銷售商品,半數收現、半數賒欠,此交易種類屬於轉帳交易", "日記簿是以交易為主體之原始記錄簿", "日記簿之類頁欄是記載分類帳之頁次", "銷售商品一批,簽發匯票請求承兌,應借記:應收帳款"], "answer": "A", "figure": null, "official": "(A)銷售商品,半數收現、半數賒欠,其分錄為「借:現金、應收帳款,貸:銷貨收入」,故為混合交易。", "explain": {"concept": "交易種類(現金、轉帳、混合)與日記簿基本認識。", "steps": ["現金交易:全部是現金收付;轉帳交易:完全不涉及現金;混合交易:部分現金、部分轉帳。", "(A)半數收現、半數賒欠,有現金也有應收帳款,是混合交易,不是轉帳交易,所以敘述錯誤。", "(B)日記簿以交易為主體,是原始記錄簿,正確。", "(C)類頁欄記載過入分類帳的頁次,正確。", "(D)銷貨後簽發匯票請求承兌,買方承兌前仍借記應收帳款,正確。", "題目問錯誤,選 A。"], "pitfalls": "轉帳交易是完全沒有現金收付;只要有一部分現金就是混合交易。", "distractors": {"B": "此敘述正確。", "C": "此敘述正確。", "D": "此敘述正確。"}}, "check": "概念題,與官方詳解一致。", "verified": true, "note": ""}, {"id": "110-1-A-10", "exam": "110-1", "paper": "A", "q": 10, "unit": "四、分錄與日記簿", "topic": "業主私用費用", "stem": "業主支付本月份電話費$5,000,其中半數應為業主自用,此筆交易之記載,下列何者正確?", "options": ["借:郵電費$5,000,貸:現金$5,000", "借:郵電費$5,000,貸:業主往來$5,000", "借:郵電費$2,500,貸:業主往來$2,500", "借:郵電費$2,500、業主往來$2,500,貸:現金$5,000"], "answer": "C", "figure": null, "official": "業主支付本月份電話費$5,000,其中半數應為業主自用,表示其中$2,500為業主代商店支付之費用,故交易之記載為借:郵電費$2,500,貸:業主往來$2,500。", "explain": {"concept": "業主代商店墊付費用的分錄。", "steps": ["題目是「業主」自己掏腰包付了 $5,000 電話費,不是商店付的,所以商店沒有付出現金。", "其中一半(2,500)是商店該負擔的費用:借記 郵電費 2,500。", "因為是業主墊的,商店欠業主,貸記 業主往來 2,500。", "另一半是業主自己的私事,與商店無關,不用記。", "分錄:借:郵電費 2,500;貸:業主往來 2,500,選 C。"], "pitfalls": "錢是業主付的,商店不能貸記現金;業主私用部分不入商店帳。", "distractors": {"A": "以為商店付現且全額列費用。", "B": "全額當費用,沒有扣除業主自用的一半。", "D": "以為是商店付現,並把業主自用部分借記業主往來(那是商店替業主付款才用的)。"}}, "check": "概念題,分錄借貸平衡,與官方相符。", "verified": true, "note": ""}, {"id": "110-1-A-11", "exam": "110-1", "paper": "A", "q": 11, "unit": "十三、存貨", "topic": "運費處理", "stem": "小芳為公司之會計人員,處理下列有關運費之交易事項,其會計處理何者錯誤?", "options": ["本公司銷售商品給臺北公司,買賣條件為起運點交貨,代付運費,借記應收帳款", "定期盤存制下,本公司向臺中公司購入商品,買賣條件為起運點交貨,支付運費,借記進貨費用", "永續盤存制下,本公司向臺南公司購入商品,買賣條件為起運點交貨,支付運費,借記存貨", "本公司向嘉義公司購入營業用運輸設備,另付運費,借記運費"], "answer": "D", "figure": null, "official": "(D)本公司向嘉義公司購入營業用運輸設備,另付運費,應借記運輸設備成本。", "explain": {"concept": "買賣運費處理與固定資產取得成本。", "steps": ["(A)起運點交貨,運費由買方負擔,賣方先代墊,借記應收帳款(向買方收回),正確。", "(B)定期盤存制,買方負擔的進貨運費借記「進貨費用」,正確。", "(C)永續盤存制,進貨運費直接計入存貨成本,借記存貨,正確。", "(D)購買設備時為使設備可供使用的運費,屬取得成本,應借記「運輸設備」,不是借記運費,所以錯誤。", "題目問錯誤,選 D。"], "pitfalls": "購入固定資產的運費要資本化(算進資產成本),不是當費用。", "distractors": {"A": "此處理正確。", "B": "此處理正確。", "C": "此處理正確。"}}, "check": "概念題,與官方詳解一致。", "verified": true, "note": ""}, {"id": "110-1-A-12", "exam": "110-1", "paper": "A", "q": 12, "unit": "五、過帳與分類帳", "topic": "統制帳戶與明細分類帳", "stem": "業主想了解本商店各客戶帳款明細狀況,故請會計人員根據客戶名稱設置應收帳款明細分類帳,目前查閱帳簿,應收帳款統制帳戶有借餘$150,000,明細內容有三帳戶,已知李君借餘$85,000,王君借餘$90,000,林君餘額若干,請判斷下列敘述何者錯誤?", "options": ["林君餘額為貸餘$25,000", "通常明細分類帳是根據傳票過帳", "應收帳款列示於「資產負債表」流動資產項下之金額為$150,000", "統制帳戶之餘額必等於其明細分類帳中各子項目餘額之和"], "answer": "C", "figure": null, "official": "應收帳款列示於「資產負債表」流動資產項下之金額為李君借餘$85,000+王君借餘$90,000=$175,000。", "explain": {"concept": "統制帳戶與明細分類帳的關係,及貸餘客戶的表達。", "steps": ["統制帳戶餘額 = 各明細帳戶餘額之和:$150,000 = $85,000 + $90,000 + 林君。", "林君 = $150,000 - $85,000 - $90,000 = -$25,000,負數表示貸餘 $25,000,所以(A)正確。", "(B)明細分類帳通常依傳票過帳,正確;(D)統制帳戶餘額等於明細帳戶之和,正確。", "(C)報表上,借餘的客戶才列為應收帳款:$85,000 + $90,000 = $175,000;林君貸餘 $25,000 是預收性質,應列為負債。所以列示 $150,000 是錯的。", "題目問錯誤,選 C。"], "pitfalls": "各客戶借餘、貸餘不能直接互相抵銷後列示,借餘列資產、貸餘列負債。", "distractors": {"A": "此敘述正確(林君貸餘 $25,000)。", "B": "此敘述正確。", "D": "此敘述正確。"}}, "check": "python:150000-85000-90000=-25000(貸餘25,000);85000+90000=175000。與官方相符。", "verified": true, "note": ""}, {"id": "110-1-A-13", "exam": "110-1", "paper": "A", "q": 13, "unit": "六、試算與試算表", "topic": "試算表概念", "stem": "有關試算表之敘述,下列何者錯誤?", "options": ["誤用會計原則將使試算表不平衡", "試算表的功能之一為編製財務報表之依據", "影響借貸平衡之錯誤,於過帳後方發現,應採用註銷更正", "餘額式試算表借貸合計相等,並不代表所有交易皆已正確處理"], "answer": "A", "figure": null, "official": "(A)誤用會計原則並不影響試算表平衡。", "explain": {"concept": "試算表的功能與限制。", "steps": ["試算表只檢查「借方合計 = 貸方合計」。", "(A)誤用會計原則(如把費用當資產),只要借貸金額相同,試算表仍平衡,所以敘述錯誤。", "(B)試算表可作為編製財務報表的依據,正確。", "(C)影響借貸平衡的錯誤(如借貸金額不等)過帳後才發現,用註銷更正法,正確。", "(D)試算表平衡不代表沒有錯誤(如漏記、重複記、科目記錯),正確。", "題目問錯誤,選 A。"], "pitfalls": "試算表平衡不等於記帳全正確,不影響借貸平衡的錯誤查不出來。", "distractors": {"B": "此敘述正確。", "C": "此敘述正確。", "D": "此敘述正確。"}}, "check": "概念題,與官方詳解一致。", "verified": true, "note": ""}, {"id": "110-1-A-14", "exam": "110-1", "paper": "A", "q": 14, "unit": "六、試算與試算表", "topic": "影響試算平衡的錯誤", "stem": "下列哪一錯誤事項會影響餘額式試算表借貸平衡?", "options": ["現銷商品$50,000,誤將該交易金額記成$5,000", "償還貨欠,過帳時誤將應付帳款項目過至貸方", "以現金支付水電費,整筆交易遺漏過帳", "賒購商品,貸方誤以應收帳款入帳"], "answer": "B", "figure": null, "official": "(B)償還貨欠,過帳時誤將應付帳款項目過至貸方,將使餘額式試算表貸方金額多計,借方餘額正確。", "explain": {"concept": "哪些錯誤會讓試算表不平衡。", "steps": ["借貸「金額」一邊對、一邊錯,才會使試算表不平衡。", "(A)借貸都記 $5,000,雙邊一樣,仍平衡。", "(B)應付帳款應借記卻過成貸方,只有一邊錯,貸方多計,不平衡,是答案。", "(C)整筆交易都遺漏過帳,借貸皆少,仍平衡。", "(D)貸方科目記錯(應付帳款記成應收帳款)但金額相同,借貸仍平衡。"], "pitfalls": "「科目記錯」「整筆漏記」「兩邊同金額記錯」都不影響平衡。", "distractors": {"A": "雖然金額錯,但借貸兩邊同為 $5,000,仍平衡。", "C": "整筆交易漏記,借貸同時少,仍平衡。", "D": "只是貸方科目錯,金額不變,仍平衡。"}}, "check": "概念題,與官方詳解一致。", "verified": true, "note": ""}, {"id": "110-1-A-15", "exam": "110-1", "paper": "A", "q": 15, "unit": "七、調整", "topic": "預付租金調整", "stem": "小川自行創業開立品川咖啡店,其會計帳務採權責發生基礎,X1 年 12 月 1 日承租店面,簽訂 5 年租約,並於 X1 年 12 月 1 日預付 2 年租金 600,000 元及兩個月押金。請計算品川咖啡店 X2 年之租金支出及 X2 年 12 月 31 日帳上預付租金餘額為何?", "options": ["租金支出 $300,000;預付租金 $275,000", "租金支出 $300,000;預付租金 $300,000", "租金支出 $325,000;預付租金 $275,000", "租金支出 $275,000;預付租金 $300,000"], "answer": "A", "figure": null, "official": "X2 年之租金支出=$600,000/2=$300,000;X2 年 12 月 31 日之預付租金餘額=$600,000/24×11=$275,000。", "explain": {"concept": "預付租金的攤銷(權責發生基礎):每月租金乘以經過月數。", "steps": ["先算每月租金:$600,000 ÷ 24 個月 = $25,000。(押金是將來要退還的,不是費用,不用攤銷)", "X2 年全年 12 個月,租金支出 = $25,000 × 12 = $300,000(也就是 $600,000 ÷ 2)。", "租期從 X1/12/1 起算 24 個月,到 X3/11/30 結束。X1 年已用 1 個月,X2 年用 12 個月,共用 13 個月。", "X2/12/31 剩下 24 - 13 = 11 個月,預付租金 = $25,000 × 11 = $275,000。", "選 A。"], "pitfalls": "押金不是費用;還要記得 X1 年 12 月已攤銷 1 個月,所以剩 11 個月不是 12 個月。", "distractors": {"B": "以為 X2 年底還剩 12 個月($300,000),忽略 X1 年 12 月已用掉 1 個月。", "C": "租金支出算成 13 個月 $325,000(把 X1 年 12 月也算入 X2 年)。", "D": "租金支出算成 11 個月、預付算成 12 個月,兩者顛倒。"}}, "check": "python:600000/24=25000;25000*12=300000;25000*11=275000,與官方相符。", "verified": true, "note": ""}, {"id": "110-1-A-16", "exam": "110-1", "paper": "A", "q": 16, "unit": "七、調整", "topic": "漏列調整的影響", "stem": "小川自行創業開設品川咖啡店,聘任一名員工協助店務,約定其薪資均於次月5日發放,品川咖啡店會計帳務採應計基礎,小川自行負責咖啡店之會計處理,因忙碌漏未將 X2 年 12 月份之員工薪資調整入帳,此錯誤對 X2 年底財務報表要素之影響,下列敘述何者正確?", "options": ["費損少計、負債多計、權益多計", "費損少計、負債少計、權益多計", "費損少計、負債少計、權益少計", "費損多計、負債少計、權益少計"], "answer": "B", "figure": null, "official": "應有之調整:薪資支出(費損+)、應付薪資(負債+);漏未調整:費損少計→權益多計、負債少計。", "explain": {"concept": "漏列應付費用調整對報表的影響。", "steps": ["12 月薪資次月才發,年底應調整:借:薪資支出 / 貸:應付薪資。", "漏調整 → 薪資支出(費用)少列了。", "應付薪資(負債)也少列了。", "費用少列 → 淨利多算 → 權益(業主權益)多計。", "綜合:費損少計、負債少計、權益多計,選 B。"], "pitfalls": "費用少記會讓淨利和權益多算,不是少算。", "distractors": {"A": "負債應是少計,不是多計。", "C": "費用少計會使權益多計,不是少計。", "D": "漏列調整是少列費用,不是多列。"}}, "check": "概念題,與官方詳解一致。", "verified": true, "note": ""}, {"id": "110-1-A-17", "exam": "110-1", "paper": "A", "q": 17, "unit": "十二、應收款項", "topic": "預期信用減損損失(帳齡分析法)", "stem": "群賢股份有限公司 X2 年 12 月 31 日應收帳款餘額$600,000,分析賒帳期間的長短及估計損失率如下,已知調整前「備抵損失-應收帳款」餘額為借餘$5,000,試以準備矩陣法(帳齡分析法)計算群賢股份有限公司應提列之「預期信用減損損失」金額為何?\n\n| 應收帳款賒欠期間 | 1-60 日 | 61-120 日 | 超過 120 日 |\n|---|---|---|---|\n| 應收帳款餘額 | $400,000 | $150,000 | $50,000 |\n| 估計損失率 | 2% | 5% | 10% |", "options": ["$15,500", "$20,500", "$21,000", "$25,500"], "answer": "D", "figure": null, "official": "$400,000×2%+$150,000×5%+$50,000×10%=$20,500;$20,500+$5,000=$25,500。", "explain": {"concept": "準備矩陣法:先算期末備抵損失應有餘額,再與調整前餘額比較。", "steps": ["先算期末備抵損失「應有」餘額 = 各期間餘額 × 估計損失率:", "$400,000×2% = $8,000;$150,000×5% = $7,500;$50,000×10% = $5,000。", "合計 $8,000 + $7,500 + $5,000 = $20,500(這是備抵損失期末應有的貸方餘額)。", "調整前備抵損失是「借餘」$5,000(不是貸餘),表示要先補足這 $5,000 才會歸零,再補到貸餘 $20,500。", "本期應提列 = $20,500 + $5,000 = $25,500。分錄:借:預期信用減損損失 25,500 / 貸:備抵損失-應收帳款 25,500。"], "pitfalls": "調整前餘額若是借餘,要用「加」;若是貸餘才用「減」。", "distractors": {"A": "$20,500 - $5,000 = $15,500,把借餘當成貸餘減掉。", "B": "只算 $20,500,忽略調整前借餘 $5,000。"}}, "check": "python:400000*.02+150000*.05+50000*.10=20500;+5000=25500,與官方相符。", "verified": true, "note": ""}, {"id": "110-1-A-18", "exam": "110-1", "paper": "A", "q": 18, "unit": "十五、長期營業用資產", "topic": "直線法折舊與帳面金額", "stem": "群賢股份有限公司 X2 年 7 月 1 日購入機器一部,成交價$1,500,000,安裝費及試車費共計$50,000,另因搬運途中不慎碰損支付$50,000 修理費,預估此機器可用 10 年,殘值估計$100,000,公司決定採直線法提列折舊,試算 X4 年底調整後該機器之帳面金額為何?", "options": ["$1,162,500", "$1,187,500", "$1,200,000", "$1,225,000"], "answer": "B", "figure": null, "official": "成本=$1,500,000+$50,000=$1,550,000;每年折舊=($1,550,000-$100,000)/10=$145,000;累計折舊=$145,000×2.5年=$362,500;帳面金額=$1,550,000-$362,500=$1,187,500。", "explain": {"concept": "固定資產成本的決定與直線法折舊。", "steps": ["先決定成本:成交價 + 使可供使用的必要支出(安裝費、試車費)= $1,500,000 + $50,000 = $1,550,000。", "搬運途中碰損的修理費是意外損失,不算成本(當期費用)。", "每年折舊 = (成本 - 殘值) ÷ 耐用年數 = ($1,550,000 - $100,000) ÷ 10 = $145,000。", "使用期間:X2/7/1 到 X4/12/31 = 2.5 年(X2 半年、X3 一年、X4 一年)。", "累計折舊 = $145,000 × 2.5 = $362,500。", "帳面金額 = $1,550,000 - $362,500 = $1,187,500。"], "pitfalls": "修理碰損的費用不能算進機器成本;使用期間是 2.5 年。", "distractors": {"D": "把修理費算入成本:成本 $1,600,000,折舊 $150,000×2.5=$375,000,帳面 $1,225,000。"}}, "check": "python:成本1550000;(1550000-100000)/10=145000;145000*2.5=362500;帳面=1187500,與官方相符。", "verified": true, "note": ""}, {"id": "110-1-A-19", "exam": "110-1", "paper": "A", "q": 19, "unit": "八、結帳", "topic": "結帳程序", "stem": "有關結帳會計程序之敘述,下列何者錯誤?", "options": ["在進行期末調整工作前,須先完成結帳工作", "結帳時本期損益產生貸方餘額,係代表本期有淨利", "將資產、負債及權益等實帳戶的餘額結轉下期繼續記錄", "將收益及費損等虛帳戶的餘額結清,轉入本期損益帳戶"], "answer": "A", "figure": null, "official": "(A)應先進行調整工作,再完成結帳工作。", "explain": {"concept": "結帳的順序與意義。", "steps": ["會計循環順序:先調整、再結帳。", "(A)說反了:應先調整,才能結帳,所以錯誤。", "(B)本期損益帳戶收益結入貸方、費損結入借方,貸餘表示收益大於費損,即淨利,正確。", "(C)實帳戶(資產、負債、權益)餘額留到下期繼續記錄,正確。", "(D)虛帳戶(收益、費損)餘額要結清,轉入本期損益,正確。"], "pitfalls": "順序是「調整 → 結帳」,不要記反。", "distractors": {"B": "此敘述正確。", "C": "此敘述正確。", "D": "此敘述正確。"}}, "check": "概念題,與官方詳解一致。", "verified": true, "note": ""}, {"id": "110-1-A-20", "exam": "110-1", "paper": "A", "q": 20, "unit": "九、財務報表", "topic": "流動性財務指標", "stem": "衡量企業短期償債能力通常會使用營運資金、流動比率與速動比率等流動性財務指標,而企業相關的交易活動常會造成指標的變動。假設群賢公司原來的流動比率為 1.5,速動比率為 0.8。若群賢公司收到客戶訂購商品之訂金$5,000,請問,此一交易會導致下列哪一種結果?", "options": ["營運資金上升", "速動比率上升", "流動比率上升", "速動資產不變"], "answer": "B", "figure": null, "official": "此交易導致:現金(流動資產、速動資產)增加、預收貨款(流動負債)增加。(A)營運資金不變;(C)流動比率下降;(D)速動資產增加。", "explain": {"concept": "同額增加流動資產與流動負債,對各指標的影響。", "steps": ["分錄:借:現金 5,000 / 貸:預收貨款 5,000。", "現金是流動資產也是速動資產,增加 $5,000;預收貨款是流動負債,增加 $5,000。", "營運資金 = 流動資產 - 流動負債,兩邊同加 $5,000,不變。", "流動比率原為 1.5(大於 1):分子分母同加同一數,比率會往 1 靠近,所以下降。", "速動比率原為 0.8(小於 1):同加後往 1 靠近,所以上升。", "答案選 B。"], "pitfalls": "分子分母同加同一金額,比率會趨近 1:大於 1 的下降、小於 1 的上升。", "distractors": {"A": "營運資金為流動資產減流動負債,同額增加互相抵銷,不變。", "C": "流動比率原為 1.5 > 1,同加後會下降。", "D": "現金是速動資產,收到訂金使速動資產增加。"}}, "check": "例:設流動負債 100、流動資產 150、速動資產 80 → 各加 5:流動比率 155/105=1.476(降),速動比率 85/105=0.81(升),與官方相符。", "verified": true, "note": ""}, {"id": "110-1-A-21", "exam": "110-1", "paper": "A", "q": 21, "unit": "十三、存貨", "topic": "可售商品成本", "stem": "群賢公司 X2 年度商品帳戶有關資料如下:銷貨收入$1,850,000、銷貨退回$50,000,期末存貨$150,000,進貨$1,300,000,進貨費用$40,000,進貨折讓$20,000,假設營業毛利率為 30%,則可售商品成本為何?", "options": ["$1,410,000", "$1,260,000", "$1,170,000", "$1,110,000"], "answer": "A", "figure": null, "official": "銷貨成本=($1,850,000-$50,000)×(1-30%)=$1,260,000;可售商品成本=$1,260,000+$150,000=$1,410,000。", "explain": {"concept": "用毛利率推算銷貨成本,再求可售商品成本。", "steps": ["銷貨淨額 = 銷貨收入 - 銷貨退回 = $1,850,000 - $50,000 = $1,800,000。", "毛利率 30%,表示成本占銷貨淨額 70%:銷貨成本 = $1,800,000 × 70% = $1,260,000。", "可售商品成本 = 銷貨成本 + 期末存貨 = $1,260,000 + $150,000 = $1,410,000。", "(進貨、進貨費用、進貨折讓等是干擾資料,這題不需要用到。)"], "pitfalls": "可售商品成本是「銷貨成本 + 期末存貨」,不是只有銷貨成本;也要先扣銷貨退回。", "distractors": {"B": "只算到銷貨成本 $1,260,000,忘了加期末存貨。"}}, "check": "python:(1850000-50000)*0.7=1260000;+150000=1410000,與官方相符。", "verified": true, "note": ""}, {"id": "110-1-A-22", "exam": "110-1", "paper": "A", "q": 22, "unit": "九、財務報表", "topic": "財務報表性質", "stem": "有關財務報表之敘述,下列何者錯誤?", "options": ["綜合損益表係表達企業於報導期間財務績效之動態報表", "資產負債表係表達企業於報導期間結束日財務狀況之靜態報表", "權益變動表係表達權益在報導期間內增減變動及其結果之動態報表", "現金流量表係表達企業因營業、投資及籌資所造成現金流動資訊之靜態報表"], "answer": "D", "figure": null, "official": "(D)現金流量表係表達企業因營業、投資及籌資所造成現金流動資訊之動態報表。", "explain": {"concept": "區分動態報表與靜態報表。", "steps": ["動態報表:表達一段期間的變動結果,包括綜合損益表、權益變動表、現金流量表。", "靜態報表:表達某一時點的狀況,只有資產負債表。", "(D)說現金流量表是靜態報表,錯;它記錄一段期間的現金流入流出,屬動態報表。", "選 D。"], "pitfalls": "只有資產負債表是靜態報表,其餘三張都是動態報表。", "distractors": {"A": "此敘述正確。", "B": "此敘述正確。", "C": "此敘述正確。"}}, "check": "概念題,與官方詳解一致。", "verified": true, "note": ""}, {"id": "110-1-A-23", "exam": "110-1", "paper": "A", "q": 23, "unit": "一、會計基本概念", "topic": "會計職業道德", "stem": "依據 106 年 9 月 27 日修正之「中華民國會計師職業道德規範」,會計師提供專業服務時應遵循本規範,其基本原則如下:正直、公正客觀、專業能力及專業上應有之注意、保密、專業態度。故會計人員亦應秉持專門學識、技能,以正直、公正、客觀態度,依相關法規及原則提供會計資訊。請問下列會計人員之行為,有哪幾項違反會計職業道德?\n①為達到向銀行借入營運用資金之目的,故將於 12 月 31 日尚在運送途中目的地交貨之賒銷先行入帳,期末存貨金額正確\n②客戶預購商品,約定三個月後收現,待實際收現時才開立發票予客戶\n③將購入供公司自用小客車,以公司之客貨兩用車認定,並將其進項稅額扣抵銷項稅額\n④因本公司為非公開發行公司,故選擇「企業會計準則公報」為一般公認會計原則\n⑤因本年營收狀況良好,為減輕營利事業所得稅負擔,故將本年度期初預付三年之租金,當時以租金支出入帳,期末未進行調整", "options": ["①②③⑤", "①③④⑤", "②③④⑤", "①②③④⑤"], "answer": "A", "figure": null, "official": "④公司為非公開發行公司,故選擇「企業會計準則公報」作為一般公認會計原則,正確。其餘①②③⑤皆違反會計職業道德。", "explain": {"concept": "辨別會計人員行為是否違反職業道德(誠實、公正、客觀)。", "steps": ["①目的地交貨的在途商品,所有權尚未移轉,先入帳會使應收帳款多計、影響流動比率與速動比率,誤導銀行授信,違反。", "②依營業稅法,營業人銷售貨物應依規定時限開立統一發票,拖到收現才開,違反。", "③自用小客車的進項稅額不得扣抵銷項稅額(客貨兩用車才可),硬說成客貨兩用車是少繳營業稅,違反。", "④非公開發行公司可選用「企業會計準則公報」作為一般公認會計原則,合法合理,不違反。", "⑤為減輕稅負,把預付三年租金一次當費用且期末不調整,是蓄意操縱利益,違反。", "違反的是①②③⑤,選 A。"], "pitfalls": "④是這題的「正常行為」,別被「非公開發行」嚇到;其餘都是為了達成某目的而操縱會計資訊。", "distractors": {"B": "把②誤認為沒違反,且把④誤認為違反。", "C": "漏掉①,且把④誤認為違反。", "D": "沒有發現④是合規的做法。"}}, "check": "概念題,與官方詳解及營業稅法、會計準則常識一致。", "verified": true, "note": ""}, {"id": "110-1-A-24", "exam": "110-1", "paper": "A", "q": 24, "unit": "十、加值型營業稅會計實務", "topic": "應退稅額計算", "stem": "【題組:閱讀下文,回答第 24-25 題】\n群賢股份有限公司原會計人員張大雄 X2 年 4 月底離職,離職前完成公司「銷售額與稅額申報書(401)」部分如下,謝小芳於同年 5 月初接任該職務,財務經理請謝小芳依據目前申報書資料於 X2 年 5 月 15 日前完成營業稅之申報,並請您從旁指導。您在陪同謝小芳會計人員檢查前任會計人員帳務處理及憑證過程中發現 X2 年 4 月份有經海關出口至美國一批商品,售價$1,000,000,尚未填入申報書中。\n\n(營業人銷售額與稅額申報書(401),所屬年月份 X2 年 3-4 月,金額單位新臺幣元。見附圖。重點資料:銷項稅額合計 $267,500;進項稅額(進貨及費用)$379,000、(固定資產)$75,000、退出折讓稅額 $18,500;上期累積留抵稅額 $50,000;進項總金額 進貨及費用 $8,580,000、固定資產 $1,500,000。)\n\n第 24 題:群賢股份有限公司謝小芳因初任會計人員,計算本期(月)應退稅額有以下四個答案,請您協助判斷下列何者金額正確?", "options": ["$50,000", "$75,000", "$111,500", "$125,000"], "answer": "D", "figure": "figs/110-1-A-q24.png", "official": "進項稅額=($454,000+$50,000)-$267,500=$236,500(溢付稅額);退稅限額=($1,000,000+$1,500,000)×5%=$125,000;應退稅額=$125,000(溢付稅額$236,500、退稅限額$125,000 選較小者)。", "explain": {"concept": "申報書計算溢付稅額、退稅限額,應退稅額取兩者較小。", "steps": ["先算得扣抵進項稅額合計(代號 7):進貨及費用 $379,000 + 固定資產 $75,000 = $454,000。", "加上上期累積留抵稅額 $50,000(代號 8),小計(代號 10)= $454,000 + $50,000 = $504,000。", "銷項稅額合計(代號 1)= $267,500(已扣退回折讓)。溢付稅額 = $504,000 - $267,500 = $236,500。", "退稅限額:外銷零稅率銷售額 $1,000,000(漏填的出口) × 5% = $50,000;購買固定資產 $1,500,000 × 5% = $75,000(採購固定資產可全額退),合計 $125,000。", "應退稅額取「溢付稅額」與「退稅限額」較小者:$236,500 與 $125,000,取 $125,000,選 D。"], "pitfalls": "忘了加入漏填的外銷 $1,000,000 的零稅率,以及忘記要取較小者。", "distractors": {"A": "只取上期留抵稅額 $50,000,不是應退稅額。", "B": "只看固定資產退稅 $75,000,漏掉零稅率外銷部分的退稅限額。", "C": "$111,500 是第 25 題累積留抵稅額,不是應退稅額。"}}, "check": "python:進項(379000+75000+50000)-267500=236500;退稅限額(1000000+1500000)*.05=125000;min=125000,與官方相符。", "verified": true, "note": ""}, {"id": "110-1-A-25", "exam": "110-1", "paper": "A", "q": 25, "unit": "十、加值型營業稅會計實務", "topic": "累積留抵稅額計算", "stem": "【題組:閱讀下文,回答第 24-25 題】\n群賢股份有限公司原會計人員張大雄 X2 年 4 月底離職,離職前完成公司「銷售額與稅額申報書(401)」部分如下,謝小芳於同年 5 月初接任該職務,財務經理請謝小芳依據目前申報書資料於 X2 年 5 月 15 日前完成營業稅之申報,並請您從旁指導。您在陪同謝小芳會計人員檢查前任會計人員帳務處理及憑證過程中發現 X2 年 4 月份有經海關出口至美國一批商品,售價$1,000,000,尚未填入申報書中。\n\n(營業人銷售額與稅額申報書(401),所屬年月份 X2 年 3-4 月,金額單位新臺幣元。見附圖。重點資料:銷項稅額合計 $267,500;進項稅額(進貨及費用)$379,000、(固定資產)$75,000、退出折讓稅額 $18,500;上期累積留抵稅額 $50,000;進項總金額 進貨及費用 $8,580,000、固定資產 $1,500,000。)\n\n第 25 題:請您再協助謝小芳會計人員就其所計算之本期(月)累積留抵稅額,判斷下列何者金額正確?", "options": ["$0", "$61,500", "$111,500", "$186,500"], "answer": "C", "figure": "figs/110-1-A-q24.png", "official": "溢付稅額$236,500-應退稅額$125,000=$111,500。", "explain": {"concept": "累積留抵稅額 = 溢付稅額 - 應退稅額。", "steps": ["承第 24 題:溢付稅額(代號 12)= $236,500。", "應退稅額(代號 14)= $125,000(已退還給公司)。", "還沒退掉的部分留到下期繼續扣抵,就是累積留抵稅額(代號 15)。", "累積留抵稅額 = $236,500 - $125,000 = $111,500,選 C。"], "pitfalls": "要先正確算出第 24 題的應退稅額,第 25 題才不會錯。", "distractors": {"A": "以為溢付稅額都被退完。", "D": "$236,500-$50,000=$186,500,誤以為只扣掉上期留抵稅額。"}}, "check": "python:236500-125000=111500,與官方相符。", "verified": true, "note": ""}, {"id": "110-2-A-01", "exam": "110-2", "paper": "A", "q": 1, "unit": "一、會計基本概念", "topic": "商業會計法規", "stem": "李雲以獨資方式設立飛雲商店,販售體育用品,聘任小芳為會計人員。下列敘述何者錯誤?", "options": ["(A) 飛雲商店的會計屬於營利事業會計,須計算損益", "(B) 若小芳編造不實的財務報表,是因聽從老闆的指示,就可免除刑責與罰金", "(C) 李雲享有或負擔商店的全部盈虧,對於商店的負債須負無限清償責任", "(D) 平時會計帳冊記載的依據,應優先適用商業會計法"], "answer": "B", "figure": null, "official": "編造不實財務報表,負責人與會計人員應處五年以下有期徒刑、拘役或科或併科新臺幣五十萬元以下罰金。", "explain": {"concept": "考商業會計法的刑責與獨資組織特性。題目問「錯誤」的敘述。", "steps": ["先看 (B):商業會計法規定,明知不實還編造財務報表,會計人員自己也要負刑責(五年以下有期徒刑、拘役,或科或併科罰金),不能用「老闆叫我做的」脫罪,所以 (B) 錯誤。", "(A) 商店以營利為目的,屬營利事業會計,要計算損益,正確。", "(C) 獨資的老闆享有全部盈虧,對債務負無限清償責任,正確。", "(D) 記帳依據優先適用商業會計法(商業會計法是商業會計的基本法),正確。", "所以「錯誤」的是 (B)。"], "pitfalls": "以為「聽命行事」可以免責;其實會計人員有專業責任。", "distractors": {"A": "以為獨資不算營利事業,其實獨資也是營利事業,要計算損益。", "C": "誤以為獨資負有限責任;實際上獨資負無限責任。", "D": "誤以為其他法規優先;商業會計事務以商業會計法為主。"}}, "check": "概念題:對照官方詳解與商業會計法第71條常識,一致。", "verified": true, "note": ""}, {"id": "110-2-A-02", "exam": "110-2", "paper": "A", "q": 2, "unit": "一、會計基本概念", "topic": "商業會計法規", "stem": "明星電腦公司是一家未公開發行公司,實收資本額為$50,000,000,平均每月營業額$300,000。試判斷明星電腦公司下列哪幾項符合我國法規?\n①設置會計帳簿:普通序時帳簿與總分類帳簿\n②境內銷售貨物免開立統一發票\n③新進會計人員的招聘,限定女性\n④購進辦公設備$1,200,000,立即以新台幣紙鈔支付,以便取得現金折扣", "options": ["(A) ①", "(B) ①②", "(C) ②③", "(D) ①②④"], "answer": "A", "figure": null, "official": "②營業人以開立發票為原則,除非是小規模營業人(平均每月營業額未達$200,000),經國稅局同意後才能免開統一發票;③違反勞基法、性別工作平等法;④支付金額超過$1,000,000,應使用匯票、本票、支票、劃撥或其他經主管機關核定之支付工具或方法。", "explain": {"concept": "考商業會計法(帳簿)、統一發票開立、性別平等與大額支付規定。", "steps": ["①:會計帳簿至少要設序時帳簿(普通序時帳簿)與分類帳簿(總分類帳簿),符合規定,對。", "②:免開統一發票的是「小規模營業人」,平均每月營業額要未達$200,000。本題每月$300,000,已超過,所以必須開發票,②錯。", "③:招聘限定女性,違反勞動基準法、性別工作平等法,③錯。", "④:支付金額超過$1,000,000,不能用現金,要用匯票、本票、支票等。本題用紙鈔付$1,200,000,④錯。", "只有 ① 正確,答案 (A)。"], "pitfalls": "容易忘記小規模營業人的門檻是月營業額$200,000;大額支付門檻是$1,000,000。", "distractors": {"B": "誤以為②對:把每月$300,000當成小規模營業人。", "C": "②③都不符合規定。", "D": "②④都不符合規定。"}}, "check": "概念題:月營業額 $300,000 > $200,000(門檻)、$1,200,000 > $1,000,000(門檻),與官方一致。", "verified": true, "note": ""}, {"id": "110-2-A-03", "exam": "110-2", "paper": "A", "q": 3, "unit": "十五、長期營業用資產", "topic": "折舊概念", "stem": "電視劇《三生三世十里桃花》片尾曲《涼涼》的部分歌詞:「涼涼天意潋灩一身花色,落入凡塵傷情著我,生劫易渡情劫難了,『折舊』的心,還有幾分前生的恨…」歌詞中的「折舊」,在會計範疇或人生應用上,與下列敘述何者意義不同?", "options": ["(A) 60 歲的美玲,發現容貌與身體機能逐漸衰退", "(B) 傳邦達買了一部機車,作為外送的交通工具,該機車因載貨產生破舊與損壞", "(C) 企業的員工宿舍,以合理有系統的方法,將宿舍成本攤提為費用", "(D) 林董收藏的大師畫作,經歷百年,拍賣價格仍然不斷升高"], "answer": "D", "figure": null, "official": "折舊是資產因使用、時間經過而價值減損,並將成本合理分攤為費用;(D) 價值上升,與折舊意義不同。", "explain": {"concept": "折舊的本質:資產因使用或時間而價值減損,並把成本有系統地分攤為費用。", "steps": ["先抓「折舊」的意思:資產隨時間或使用而逐漸耗損、價值下降,會計上再把成本合理分攤到各期。", "(A) 身體機能逐漸衰退 → 價值減損,和折舊意義相同。", "(B) 機車因使用而破舊損壞 → 耗損,相同。", "(C) 把宿舍成本有系統地攤提為費用 → 正是會計折舊的做法,相同。", "(D) 畫作越久價格越高,是「增值」,與折舊方向相反,所以意義不同,選 (D)。"], "pitfalls": "題目問「不同」,別誤選意義相同的選項。", "distractors": {"A": "A與折舊意義相同(逐漸衰退)。", "B": "B與折舊意義相同(使用耗損)。", "C": "C就是折舊的會計定義。"}}, "check": "概念題:與官方詳解一致。", "verified": true, "note": "單元歸類:折舊概念,歸十五;題目偏生活化,亦可視為一。"}, {"id": "110-2-A-04", "exam": "110-2", "paper": "A", "q": 4, "unit": "一、會計基本概念", "topic": "獨資會計處理", "stem": "志明除了有商業經營知識,同時也傳承阿嬤的好廚藝,於是在 X1 年 12 月初投資現金$500,000,獨資成立單身狗餐飲店。新創營運初期規模不大,交易又不複雜,為精簡人力,預計 2 年後營業成長到一定規模再聘任專職的會計人員。有關單身狗餐飲店的會計處理及財務報表,下列敘述何者錯誤?", "options": ["(A) 該店會計處理之一般公認會計原則適用「企業會計準則公報」", "(B) 會計事務得委由會計師、記帳士或記帳及報稅代理業務人處理", "(C) 該店的本期淨利扣除營利事業所得稅後,轉入「業主往來」帳戶", "(D) 為了解餐飲店的營運結果是賺錢或賠錢,要閱讀綜合損益表"], "answer": "C", "figure": null, "official": "獨資與合夥組織不須計算及繳納營利事業所得稅。", "explain": {"concept": "獨資組織不是納稅主體:盈餘歸業主個人,併入業主個人綜合所得稅,店本身不繳營利事業所得稅。", "steps": ["逐項判斷。(A) 未公開發行的小店,適用「企業會計準則公報」,正確。", "(B) 會計事務可委託會計師、記帳士或記帳及報稅代理業務人處理,正確。", "(C) 獨資組織不須計算及繳納營利事業所得稅,所以不會有「扣除營利事業所得稅」這個動作,且淨利是結轉到業主資本(題目所說的轉入「業主往來」不是正規做法),錯誤。", "(D) 要看賺錢或賠錢,要看綜合損益表,正確。", "答案 (C)。"], "pitfalls": "誤以為獨資跟公司一樣要繳營利事業所得稅。", "distractors": {"A": "A為正確敘述。", "B": "B為正確敘述。", "D": "D為正確敘述。"}}, "check": "概念題:與官方詳解及營利事業所得稅法對獨資課稅規定一致。", "verified": true, "note": "單元歸類可能有爭議:獨資組織特性(一)/ 財務報表(九)。"}, {"id": "110-2-A-05", "exam": "110-2", "paper": "A", "q": 5, "unit": "九、財務報表", "topic": "本期淨利計算", "stem": "承上題,單身狗餐飲店於 X1 年 12 月初開始營運,X1 年 12 月份的營運資料如下:\n(1) 1~31 日餐飲收入收現共計$500,000;僅有一客人老王賒欠餐費$1,200,X1 年底估計可能無法收回\n(2) 1 日購置並開始使用餐飲設備$240,000,預估可使用 10 年,無殘值,採直線法提列折舊\n(3) 11 日向銀行借入七年期長期借款$360,000,年底應付利息$240\n(4) 1~31 日餐飲食材全部付現共計$300,000,31 日餐飲食材剩餘$200\n(5) 支付 12 月份的租金、水電瓦斯費、薪資、其他費用等共計$100,000\n單身狗餐飲店 X1 年 12 月份的本期淨利(淨損)為多少?", "options": ["(A) 本期淨損$143,240", "(B) 本期淨利$96,640", "(C) 本期淨利$96,760", "(D) 本期淨利$97,960"], "answer": "D", "figure": null, "official": "收益=$500,000+應收帳款$1,200=$501,200;費損=預期信用減損損失$1,200+折舊$2,000+借款利息$240+(食材$300,000-期末存貨$200)+租金水電瓦斯費薪資$100,000=$403,240;本期淨利=$501,200-$403,240=$97,960。", "explain": {"concept": "淨利=收益-費損。要把賒銷也算收益、估計壞帳、折舊、應付利息、已耗用食材都列入費用。", "steps": ["先算收益:現金收入$500,000,另外老王賒欠$1,200也是本月提供餐飲的收益(權責發生制),合計$501,200。", "預期信用減損損失:老王的$1,200預計收不回,全額認列費用$1,200。", "折舊:$240,000 ÷ 10 年 ÷ 12 月 = $2,000(設備12月1日開始用,正好一個月)。", "利息費用:借款利息已應付未付$240,要認列費用$240。", "食材成本:買了$300,000,期末還剩$200沒用掉,所以本月耗用 $300,000 - $200 = $299,800。", "其他費用:租金、水電瓦斯、薪資等$100,000。", "總費損 = 1,200 + 2,000 + 240 + 299,800 + 100,000 = $403,240。", "本期淨利 = $501,200 - $403,240 = $97,960,選 (D)。"], "pitfalls": "忘了加賒銷收入$1,200、或食材沒扣掉期末存貨$200;也別把購買設備$240,000與借款$360,000本身當成費用或收益。", "distractors": {"A": "把購買設備$240,000之類資本支出當成費用,算出淨損。"}}, "check": "python 獨立計算:501,200 - (1,200+2,000+240+299,800+100,000)=97,960,與官方相符。", "verified": true, "note": ""}, {"id": "110-2-A-06", "exam": "110-2", "paper": "A", "q": 6, "unit": "三、會計基本法則", "topic": "會計科目分類", "stem": "下列會計項目之敘述,何者錯誤?", "options": ["(A)「交際費」屬於營業外支出,其進項稅額不得扣抵銷項稅額", "(B)「業主往來」屬於權益,其餘額可能為借餘、貸餘或零", "(C) 汽車銷售公司購入載貨卡車供營業使用,會計項目應列為「運輸設備成本」", "(D) 因應收帳款所產生的「預期信用減損利益」餘額為貸餘,應列為營業費用的減項"], "answer": "A", "figure": null, "official": "「交際費」屬於營業費用。", "explain": {"concept": "認識科目歸屬:交際費是營業費用,不是營業外支出。", "steps": ["(A) 交際費是為營業所發生的應酬費用,屬於「營業費用」(推銷或管理費用),不是營業外支出。進項稅額不得扣抵這句話是對的,但前半句分類錯,所以整句錯誤。", "(B) 業主往來是權益類(含業主資本的暫時調整),餘額可借可貸可為零,正確。", "(C) 汽車銷售公司買卡車是自用的營業設備,不是存貨,列為運輸設備(成本),正確。", "(D) 預期信用減損利益是貸餘,為營業費用減項,正確。", "答案 (A)。"], "pitfalls": "看到「交際費不得扣抵」就以為整句對,忽略前面的分類錯誤。", "distractors": {"B": "B為正確敘述。", "C": "C為正確敘述(自用才是設備,出售才是存貨)。", "D": "D為正確敘述。"}}, "check": "概念題:與官方詳解一致。", "verified": true, "note": ""}, {"id": "110-2-A-07", "exam": "110-2", "paper": "A", "q": 7, "unit": "一、會計基本概念", "topic": "會計基本假設", "stem": "有關「會計基本假設」之敘述,下列何者錯誤?", "options": ["(A) 基於「繼續經營假設」,負債依據到期時間的長短,區分為流動負債與非流動負債", "(B) 基於「企業個體假設」,業主私人經濟活動應與企業經濟活動分開處理", "(C) 基於「貨幣評量假設」,記帳應以貨幣為衡量單位,並假設幣值穩定", "(D) 基於「報導期間假設」,在每一相等的報導期間所發生之每項會計交易,僅會影響該期之財務報表"], "answer": "D", "figure": null, "official": "每項會計交易並非僅會影響該期之財務報表,例如應收收益、應付費用、預收收益、預付費用等,都會跨不同報導期間。", "explain": {"concept": "報導期間假設:把企業生命切成相等期間(如一年)報導,但交易的影響常跨期。", "steps": ["(A) 繼續經營假設:企業會持續營運,所以才能用「一年內到期」區分流動與非流動負債,正確。", "(B) 企業個體假設:企業與業主分開,私人活動不入帳,正確。", "(C) 貨幣評量假設:以貨幣衡量並假設幣值穩定,正確。", "(D) 報導期間假設是把期間切開報導,但像預付費用、預收收益、應收收益、應付費用都會影響多個期間,不是「僅影響該期」,所以錯誤。", "答案 (D)。"], "pitfalls": "以為分期報導就代表交易只影響當期。", "distractors": {"A": "A為正確敘述。", "B": "B為正確敘述。", "C": "C為正確敘述。"}}, "check": "概念題:與官方詳解及會計基本假設定義一致。", "verified": true, "note": ""}, {"id": "110-2-A-08", "exam": "110-2", "paper": "A", "q": 8, "unit": "四、分錄與日記簿", "topic": "賒銷與運費分錄", "stem": "開心公司賒銷商品$40,000 給平安公司,目的地交貨,9 月 1 日商品送達平安公司時開心公司另以現金支付運費$500。9 月 1 日商品送達當天開心公司的財務報表要素的增減變化為何?", "options": ["(A) 資產總額增加$40,000、收益總額增加$40,000", "(B) 資產總額增加$39,500、收益總額增加$39,500", "(C) 資產總額增加$39,500、營業成本增加$500、收益總額增加$40,000", "(D) 資產總額增加$39,500、營業費用增加$500、收益總額增加$40,000"], "answer": "D", "figure": null, "official": "借:應收帳款 40,000,運費 500;貸:銷貨收入 40,000,現金 500。應收帳款增加使資產增$40,000,運費$500為營業費用,現金減少$500,資產淨增$39,500。", "explain": {"concept": "目的地交貨:商品到達買方才算銷貨,賣方負擔運費,記為營業費用(運費)。", "steps": ["目的地交貨時,商品送達買方才移轉控制權,所以9月1日送達當天認列銷貨。", "賒銷分錄:借:應收帳款 40,000;貸:銷貨收入 40,000。資產增$40,000,收益增$40,000。", "賣方負擔運費$500,這是銷貨費用,記「運費」(營業費用),不是存貨成本:借:運費 500;貸:現金 500。資產(現金)減少$500。", "資產總額:+40,000 - 500 = +39,500。收益總額(銷貨收入)增加$40,000。營業費用增加$500。", "對照選項,答案是 (D)。"], "pitfalls": "把運費當成降低收益或營業成本;運費是賣方費用,不是收益的減項,也不是營業成本。", "distractors": {"A": "忘了運費$500使現金(資產)減少,也沒列費用。", "B": "把運費直接沖減收益(收益算成$39,500)。", "C": "把運費歸為營業成本;賣方送貨運費屬營業費用(運費)。"}}, "check": "逐筆分錄計算:資產 +40,000 -500 = 39,500;費用 500;收益 40,000,與選項 D 相符。", "verified": true, "note": "單元歸類可能有爭議:四(分錄)/ 十三(存貨,運費)/ 九。"}, {"id": "110-2-A-09", "exam": "110-2", "paper": "A", "q": 9, "unit": "二、會計循環及會計帳簿", "topic": "會計憑證", "stem": "有關會計憑證之處理,下列何者錯誤?", "options": ["(A) 進貨取得的發票是原始憑證,傳票屬於記帳憑證", "(B) 不印出紙本,將發票儲存在各種載具的電子發票,稱為雲端發票", "(C) 償還貨款並取得現金折扣的交易,採複式傳票三分法下應編製現金轉帳傳票", "(D) 各項會計憑證,除應永久保存或有關未結會計事項者外,應於年度決算程序辦理終了後,至少保存五年"], "answer": "C", "figure": null, "official": "該交易為混合交易,採複式傳票三分法下應編製「轉帳」傳票。", "explain": {"concept": "傳票三分法:全部現金交易→收入或支出傳票;全部轉帳→轉帳傳票;一部分現金、一部分轉帳(混合)→一般轉帳傳票處理(將其視為分開的現金與轉帳)。", "steps": ["先分辨交易性質:償還貨款並取得現金折扣,一部分付現金、一部分沖銷折扣(不是現金),屬混合交易(一部分現金、一部分轉帳)。", "在複式傳票三分法下,混合交易視為「轉帳交易」,編製「轉帳傳票」。", "所以說「編製現金轉帳傳票」是錯誤,沒有這種「現金轉帳傳票」。", "(A)(B)(D) 皆正確:發票是原始憑證、傳票是記帳憑證;雲端發票是儲存於載具的電子發票;憑證至少保存五年。", "答案 (C)。"], "pitfalls": "不熟傳票種類(收入、支出、轉帳),誤以為有「現金轉帳傳票」。", "distractors": {"A": "A為正確敘述。", "B": "B為正確敘述。", "D": "D為正確敘述(商業會計法:至少保存五年)。"}}, "check": "概念題:與官方詳解一致。", "verified": true, "note": ""}, {"id": "110-2-A-10", "exam": "110-2", "paper": "A", "q": 10, "unit": "五、過帳與分類帳", "topic": "會計項目級別", "stem": "萬興公司的會計項目採用證券交易所的「一般行業會計項目及代碼表」,則下列何者列為總分類帳的帳戶名稱?", "options": ["(A) 現金及約當現金", "(B) 應收票據", "(C) 流動負債", "(D) 應付帳款-聯電公司"], "answer": "B", "figure": null, "official": "總分類帳的帳戶名稱為第四級會計項目:(A)為第三級、(C)為第二級、(D)為第五級(子項目)。", "explain": {"concept": "會計項目代碼分級:第一級類(資產)、第二級(流動資產)、第三級(如現金及約當現金)、第四級(總分類帳帳戶,如應收票據)、第五級(明細分類帳/子項目)。", "steps": ["先記住:總分類帳的帳戶 = 第四級會計項目。", "(A) 現金及約當現金 → 第三級(彙總項目),不是總分類帳帳戶。", "(B) 應收票據 → 第四級,是總分類帳帳戶,符合。", "(C) 流動負債 → 第二級(大類)。", "(D) 應付帳款-聯電公司 → 第五級(明細/子項目)。", "答案 (B)。"], "pitfalls": "分不清「彙總項目」與「總分類帳戶」,看到熟悉科目就誤選。", "distractors": {"A": "A是第三級,不是總分類帳帳戶。", "C": "C是第二級大類。", "D": "D是明細分類帳(第五級子項目)。"}}, "check": "概念題:與官方詳解一致。", "verified": true, "note": "單元歸類可能有爭議:會計科目分級(三)/分類帳(五)。"}, {"id": "110-2-A-11", "exam": "110-2", "paper": "A", "q": 11, "unit": "六、試算與試算表", "topic": "借貸平衡", "stem": "會計帳務正確時,下列金額哪幾項一定會借貸平衡?\n①每一筆分錄 ②日記簿每頁的借貸合計 ③總分類帳個別帳戶的借貸總額 ④試算表的借貸合計", "options": ["(A) ①②", "(B) ②④", "(C) ①②④", "(D) ①②③④"], "answer": "C", "figure": null, "official": "複式簿記下,每筆分錄借貸相等,日記簿每頁借貸合計、試算表借貸合計也相等;個別帳戶的借貸總額不一定相等。", "explain": {"concept": "複式簿記的借貸平衡原理:分錄→日記簿→試算表整體平衡,但單一帳戶不必平衡。", "steps": ["①每一筆分錄,借方金額=貸方金額,一定平衡。", "②日記簿每頁是許多分錄的加總,所以也平衡。", "③總分類帳「個別帳戶」,例如現金帳戶,借方總額和貸方總額通常不相等(有餘額),所以不一定平衡。", "④試算表是把所有帳戶餘額(或總額)彙總,借貸合計一定相等。", "①②④ 一定平衡,答案 (C)。"], "pitfalls": "把「個別帳戶」跟「全部帳戶」搞混。", "distractors": {"A": "漏掉④,試算表也一定平衡。", "B": "漏掉①,每一筆分錄當然也平衡。", "D": "誤以為單一帳戶借貸總額也相等。"}}, "check": "概念題:複式簿記原理,與官方一致。", "verified": true, "note": ""}, {"id": "110-2-A-12", "exam": "110-2", "paper": "A", "q": 12, "unit": "六、試算與試算表", "topic": "過帳錯誤與試算表", "stem": "科南將下列交易「借:應收帳款$3,000、貸:銷貨收入$3,000」,過帳時發生借貸方向相反錯誤,則下列敘述何者錯誤?", "options": ["(A) 若採總額式試算表,借方總額合計等於貸方總額合計", "(B) 若採總額式試算表,應收帳款項目借方總額及銷貨收入項目貸方總額均少計$6,000", "(C) 若採餘額式試算表,應收帳款項目借方餘額少計$6,000", "(D) 若採餘額式試算表,銷貨收入項目貸方餘額少計$6,000"], "answer": "B", "figure": null, "official": "若採總額式試算表,應收帳款項目借方總額及銷貨收入項目貸方總額均少計「$3,000」(而非$6,000)。", "explain": {"concept": "方向相反的過帳錯誤:應過借方卻過貸方、應過貸方卻過借方。總額式看借貸「總額」;餘額式看「餘額」,方向錯誤會使餘額差兩倍。", "steps": ["正確應:應收帳款借方+3,000,銷貨收入貸方+3,000。", "錯誤過帳:應收帳款貸方+3,000,銷貨收入借方+3,000。", "總額式試算表:應收帳款借方總額少了$3,000(但貸方總額多$3,000);銷貨收入貸方總額少$3,000(借方多$3,000)。借方總額和貸方總額各多少$3,000+少$3,000,仍平衡,(A) 對。(B) 說少計$6,000,錯,應是$3,000。", "餘額式:應收帳款本應借餘+3,000,現變貸方 3,000,餘額差$6,000;銷貨收入同理貸方餘額少計$6,000,(C)(D) 對。", "所以選 (B)。"], "pitfalls": "誤以為總額式也差$6,000;其實只有「餘額」會因方向相反差兩倍。", "distractors": {"A": "A正確:借貸方向相反,總額仍平衡。", "C": "C正確:餘額式從借餘3,000變貸餘3,000,差6,000。", "D": "D正確:銷貨收入餘額同樣差6,000。"}}, "check": "逐項推演:總額式每邊少3,000;餘額式差 3,000-(-3,000)=6,000,與官方相符。", "verified": true, "note": ""}, {"id": "110-2-A-13", "exam": "110-2", "paper": "A", "q": 13, "unit": "七、調整", "topic": "估計項目", "stem": "下列調整事項何者屬於估計項目?", "options": ["(A) 提列預期信用減損損失", "(B) 應收收益之調整", "(C) 期末存貨之調整", "(D) 預付費用之調整"], "answer": "A", "figure": null, "official": "預期信用減損損失須以估計方式決定金額,屬估計項目。", "explain": {"concept": "調整分錄種類:遞延項目、應計項目、估計項目(折舊、預期信用減損損失)。", "steps": ["調整分錄分成:遞延(預付費用、預收收益)、應計(應收收益、應付費用)、估計(需要估計金額,如折舊、預期信用減損損失)。", "(A) 預期信用減損損失:要估計將來收不回多少,屬估計項目。", "(B) 應收收益 → 應計項目;(D) 預付費用 → 遞延項目;(C) 期末存貨 → 存貨盤點調整(定期盤存制),不是估計項目。", "答案 (A)。"], "pitfalls": "把應收收益誤以為是估計,但它有明確金額可算。", "distractors": {"B": "B屬應計項目。", "C": "C是依盤點結果調整的存貨項目。", "D": "D屬遞延項目。"}}, "check": "概念題:與官方一致。", "verified": true, "note": ""}, {"id": "110-2-A-14", "exam": "110-2", "paper": "A", "q": 14, "unit": "七、調整", "topic": "預付費用調整", "stem": "大雅公司於 X1 年 6 月 1 日預付二年保險費,屬於 X3 年度的「保險費」金額為$30,000,試計算 X1 年 12 月 31 日調整後的「預付保險費」餘額為多少?", "options": ["(A) $90,000", "(B) $102,000", "(C) $120,000", "(D) $144,000"], "answer": "B", "figure": null, "official": "X3 年的 5 個月保險費=$30,000,每月$6,000;X1 年 12 月 31 日調整後預付保險費=17 個月×$6,000=$102,000。", "explain": {"concept": "預付保險費期末餘額=尚未耗用月數 × 每月保險費。", "steps": ["先看期間:X1年6/1起預付二年,保險期間是 X1/6/1 ~ X3/5/31,共24個月。", "X3 年(1/1~5/31)只有5個月,金額$30,000,所以每月保險費 = $30,000 ÷ 5 = $6,000。", "到 X1/12/31,已耗用 6/1~12/31 共7個月,尚未耗用 24 - 7 = 17 個月。", "預付保險費餘額 = 17 × $6,000 = $102,000。", "(驗證:總保險費=24×6,000=$144,000,已耗用7×6,000=42,000,144,000-42,000=102,000)答案 (B)。"], "pitfalls": "把整年$30,000當成一年保費;其實$30,000只是 X3 年前 5 個月。", "distractors": {"A": "$90,000=15個月×6,000,算錯未耗用月數。", "C": "$120,000=20個月×6,000,算錯月數。", "D": "$144,000是兩年總保險費,沒扣已耗用部分。"}}, "check": "python 驗算:30000/5*17=102,000,與官方相符。", "verified": true, "note": ""}, {"id": "110-2-A-15", "exam": "110-2", "paper": "A", "q": 15, "unit": "八、結帳", "topic": "實虛帳戶", "stem": "下列有幾項帳戶結帳時,餘額應結轉下期?\n①累計折舊 ②職工福利 ③應收租金 ④預付郵電費", "options": ["(A) 一項", "(B) 二項", "(C) 三項", "(D) 四項"], "answer": "C", "figure": null, "official": "①③④為實帳戶,故應結轉下期。", "explain": {"concept": "實帳戶(資產、負債、權益)餘額結轉下期;虛帳戶(收益、費損)結清歸零。", "steps": ["實帳戶 = 資產、負債、權益帳戶,期末餘額帶到下期;虛帳戶 = 收益與費損,結帳時結清。", "①累計折舊:資產抵減帳戶,屬實帳戶,結轉。", "②職工福利:費用(虛帳戶),結清。", "③應收租金:資產,實帳戶,結轉。", "④預付郵電費:資產,實帳戶,結轉。", "共三項,答案 (C)。"], "pitfalls": "誤以為預付、應收類是費用或收益而結清。", "distractors": {"D": "把費用「職工福利」也算成實帳戶。"}}, "check": "概念題:實帳戶 = ①③④,共三項,與官方一致。", "verified": true, "note": ""}, {"id": "110-2-A-16", "exam": "110-2", "paper": "A", "q": 16, "unit": "八、結帳", "topic": "結帳程序", "stem": "有關結帳程序,下列敘述何者錯誤?", "options": ["(A) 利息收入有可能同時出現在調整後及結帳後試算表", "(B) 結帳後權益=結帳前權益+(收益-費損)", "(C) 將虛帳戶結清即可得出本期淨利(損)", "(D) 存貨採定期盤存制之公司,若採銷貨成本法結清商品帳戶,結帳分錄貸方可能出現進貨費用"], "answer": "A", "figure": null, "official": "利息收入屬於虛帳戶,不可能出現在結帳後試算表。", "explain": {"concept": "結帳後試算表只含實帳戶(資產、負債、權益),虛帳戶已結清為零。", "steps": ["結帳:把收益、費損等虛帳戶結清,轉入本期損益,再轉入權益(業主資本/保留盈餘)。", "(A) 利息收入是收益(虛帳戶),結帳後餘額為零,不會出現在結帳後試算表,所以錯誤。", "(B) 結帳後權益=結帳前權益+淨利(收益-費損),正確。", "(C) 虛帳戶結清後的結果就是本期淨利(損),正確。", "(D) 定期盤存制用銷貨成本法結清商品帳戶時,進貨費用(如進貨運費)可能出現在貸方,正確。", "答案 (A)。"], "pitfalls": "忘記虛帳戶結帳後歸零,不會出現在結帳後試算表。", "distractors": {"B": "B為正確敘述。", "C": "C為正確敘述。", "D": "D為正確敘述。"}}, "check": "概念題:與官方詳解一致。", "verified": true, "note": ""}, {"id": "110-2-A-17", "exam": "110-2", "paper": "A", "q": 17, "unit": "六、試算與試算表", "topic": "錯誤更正與營業收入淨額", "stem": "X2 年期末發現下列帳務錯誤:銷貨退回多計$2,000,租金收入少計$600,利息收入$3,000 誤列為銷貨收入$30,000,以上錯誤對 X2 年度營業收入淨額的影響為何?", "options": ["(A) 多計$25,000", "(B) 多計$28,000", "(C) 多計$31,000", "(D) 多計$32,000"], "answer": "B", "figure": null, "official": "銷貨退回多計$2,000,營業收入淨額少計$2,000;租金收入少計$600、利息收入少計$3,000為營業外收入,對營業收入淨額無影響;銷貨收入多計$30,000。合計多計 $30,000-$2,000=$28,000。", "explain": {"concept": "營業收入淨額=銷貨收入-銷貨退回與折讓。租金收入、利息收入是營業外收入,不在營業收入淨額內。", "steps": ["先釐清:營業收入淨額 = 銷貨收入 - 銷貨退回與折讓。", "銷貨退回多計$2,000 → 減項多扣,營業收入淨額少計$2,000。", "租金收入少計$600 → 營業外收入,對營業收入淨額無影響。", "利息收入$3,000 誤列為銷貨收入$30,000(題目所述):依官方,銷貨收入多計$30,000,利息收入(營業外)少計$3,000,不影響營業收入淨額。", "合計:+30,000(銷貨多計) - 2,000(銷貨退回多計) = 多計$28,000,答案 (B)。"], "pitfalls": "把營業外收入也算進營業收入淨額,或忘了銷貨退回是減項。", "distractors": {"D": "把銷貨退回誤當成加項:$30,000+$2,000。"}}, "check": "python 獨立計算:30,000 - 2,000 = 28,000,與官方相符。", "verified": true, "note": "題幹「利息收入$3,000 誤列為銷貨收入$30,000」原文如此,數字不一致(3,000 vs 30,000),已照官方詳解處理;單元歸類可能有爭議:六/九。"}, {"id": "110-2-A-18", "exam": "110-2", "paper": "A", "q": 18, "unit": "十、加值型營業稅會計實務", "topic": "進項稅額扣抵", "stem": "應稅營業人的下列交易,哪幾項之進項稅額可扣抵銷項稅額?\n①對我國政府捐贈防疫救護車\n②購入放置於營業場所供全體員工使用的茶葉、衛生紙、香皂\n③租賃房屋供員工住宿,所支付的水電、瓦斯、租金\n④因營業上之需要,所支付自用乘人小汽車之修理費、加油費", "options": ["(A) ④", "(B) ②④", "(C) ①②④", "(D) ①②③④"], "answer": "C", "figure": null, "official": "①②④之進項稅額可扣抵銷項稅額;③租賃房屋供員工住宿,係屬酬勞員工性質,其有關水電、瓦斯、租金等所支付之進項稅額,不得扣抵銷項稅額。", "explain": {"concept": "營業稅法:與營業無關或屬酬勞員工性質(如員工宿舍)的進項稅額不得扣抵;營業上需要的購買可扣抵。", "steps": ["①捐贈政府的物品,依法視同可扣抵(捐贈政府之貨物不視為銷售,進項仍可扣抵),可扣抵。", "②全體員工使用的茶葉、衛生紙、香皂,為營業上用,可扣抵。", "③租賃房屋供員工住宿,屬酬勞員工(福利)性質,進項稅額不得扣抵。", "④因營業需要,自用乘人小汽車的修理費、加油費,可扣抵(購買乘人小汽車本身不可扣抵,但修理與油料可)。", "可扣抵:①②④,答案 (C)。"], "pitfalls": "誤以為員工宿舍費用也能扣抵,或誤以為小汽車相關費用都不能扣。", "distractors": {"A": "只認可④,漏掉①②也可扣抵。", "B": "漏掉①,捐贈政府的救護車進項稅額仍可扣抵。", "D": "誤認③也可扣抵;員工宿舍屬酬勞員工性質,不得扣抵。"}}, "check": "概念題:對照官方詳解與營業稅法第19條常識,一致。", "verified": true, "note": ""}, {"id": "110-2-A-19", "exam": "110-2", "paper": "A", "q": 19, "unit": "十、加值型營業稅會計實務", "topic": "留抵稅額計算", "stem": "玉光公司為一般稅率營業人,以下為 X2 年連續月份的進銷資料,無外銷業務,各項金額均未包含 5%營業稅,X2 年初帳上無留抵稅額。\n(1) 1~2 月份購買商品$500,000,進貨退出$40,000,銷售商品$420,000,銷貨退回$20,000\n(2) 3~4 月份購買商品$340,000,交際費$2,000,支付水電費$40,000,銷售商品$420,000\n試以上述資料,計算 4 月底營業稅結算後之「留抵稅額」的餘額為何?", "options": ["(A) $1,000", "(B) $1,100", "(C) $2,000", "(D) $5,000"], "answer": "A", "figure": null, "official": "1~2 月份:進項($500,000-$40,000)×5%-銷項($420,000-$20,000)×5%=溢付稅額$3,000(留抵稅額);3~4 月份:進項($340,000+$40,000)×5%-銷項$420,000×5%=應納稅額$2,000;4 月底留抵稅額餘額=$3,000-$2,000=$1,000。", "explain": {"concept": "營業稅:應納(退)稅額=銷項稅額-進項稅額-上期留抵;交際費進項不得扣抵。", "steps": ["營業稅每兩個月申報一期。先算 1~2 月:進項 = (500,000 - 40,000)×5% = $23,000;銷項 = (420,000 - 20,000)×5% = $20,000。進項大於銷項,溢付$3,000,成為留抵稅額。", "再算 3~4 月:進項 = (340,000 + 40,000)×5% = $19,000(水電費可扣抵;交際費$2,000的進項稅額不得扣抵,所以不計);銷項 = 420,000×5% = $21,000。", "本期銷項 - 進項 = 21,000 - 19,000 = 應納$2,000,先用上期留抵$3,000抵減。", "留抵稅額剩 3,000 - 2,000 = $1,000,答案 (A)。"], "pitfalls": "把交際費的進項稅額也算入扣抵($100),或忘了進貨退出、銷貨退回要扣掉。", "distractors": {"B": "把交際費$2,000×5%=$100也扣抵,得$1,100。", "C": "$2,000 是 3~4 月份的本期應納稅額,忘了用上期留抵$3,000去抵減。"}}, "check": "python 獨立計算:期1 留抵 3,000;期2 應納 2,000;留抵 1,000,與官方相符。", "verified": true, "note": ""}, {"id": "110-2-A-20", "exam": "110-2", "paper": "A", "q": 20, "unit": "十、加值型營業稅會計實務", "topic": "外銷退稅", "stem": "美光公司為一般稅率營業人,營業稅稅率 5%,X2 年 9~10 月份之申報資料如下(未含稅):內銷$700,000,外銷$240,000,購置機器設備$60,000,一般進貨及費用支付$800,000,上期留抵稅額的餘額為$2,000。則本期應收退稅款為多少?", "options": ["(A) $8,000", "(B) $10,000", "(C) $12,000", "(D) $15,000"], "answer": "B", "figure": null, "official": "本期申報留抵稅額=[($800,000+$60,000)×5%+$2,000]-$700,000×5%=$10,000;得退稅限額=($240,000+$60,000)×5%=$15,000;本期應收退稅款選較小者$10,000。", "explain": {"concept": "外銷零稅率,銷項稅額為0。進項大於銷項時,可退稅額=min(溢付稅額, 零稅率銷售額進項限額)。", "steps": ["先算溢付稅額(進項扣抵銷項後多出的):進項 = ($800,000 + $60,000)×5% = $43,000,再加上期留抵$2,000 = $45,000。", "銷項 = 內銷 $700,000×5% = $35,000(外銷零稅率,銷項為0)。", "溢付 = 45,000 - 35,000 = $10,000。", "再算得退稅限額(外銷及購買固定資產可退):($240,000 + $60,000)×5% = $15,000。", "可退稅額取兩者較小:min(10,000, 15,000)= $10,000,答案 (B)。"], "pitfalls": "沒有比較「溢付稅額」與「得退稅限額」,直接取較大的$15,000。", "distractors": {"A": "可能漏算上期留抵$2,000(差$2,000)。", "D": "直接用限額$15,000,未取較小者。"}}, "check": "python 獨立計算:溢付 10,000;限額 15,000;取小者 10,000,與官方相符。", "verified": true, "note": ""}, {"id": "110-2-A-21", "exam": "110-2", "paper": "A", "q": 21, "unit": "十一、現金及內部控制", "topic": "現金及約當現金", "stem": "下列何者不屬於「現金及約當現金」?", "options": ["(A) 本公司儲存在銀行的活期存款", "(B) 持有投資日起三個月內到期的國庫券", "(C) 持有的零用金", "(D) 收到客戶交來發票日為一個月後的支票"], "answer": "D", "figure": null, "official": "收到客戶交來發票日為一個月後的支票,屬於「應收票據」。", "explain": {"concept": "現金及約當現金包含:庫存現金、銀行存款、零用金、可隨時兌現的票據,以及三個月內到期的短期投資(約當現金)。遠期支票屬應收票據。", "steps": ["(A) 活期存款:隨時可提領,是現金。", "(B) 投資日起三個月內到期的國庫券:屬約當現金。", "(C) 零用金:是現金。", "(D) 發票日為一個月後的支票(遠期支票),現在不能兌現,屬於應收票據,不是現金。", "答案 (D)。"], "pitfalls": "以為所有支票都是現金;必須是即期、可立即兌現的才算。", "distractors": {"A": "A為現金。", "B": "B為約當現金。", "C": "C為現金。"}}, "check": "概念題:與官方詳解一致。", "verified": true, "note": ""}, {"id": "110-2-A-22", "exam": "110-2", "paper": "A", "q": 22, "unit": "十一、現金及內部控制", "topic": "銀行存款調節表", "stem": "神爺公司 6 月底帳上銀行存款餘額$13,000,與銀行對帳單金額不符,差異原因如下:\n(1) 銀行代收票據存入帳戶$8,000,公司尚未入帳\n(2) 6 月底未兌現支票$9,600,其中銀行保付支票$2,000\n(3) 已存入客戶所開的支票$3,200,因存款不足遭退票\n(4) 銀行存款利息$2,800,公司尚未入帳\n(5) 公司所開立支票償付貨款金額$840,公司帳簿誤記為$540\n根據上述資料,試計算 6 月底銀行對帳單的存款餘額為何?", "options": ["(A) $20,300", "(B) $22,600", "(C) $27,900", "(D) $28,500"], "answer": "C", "figure": null, "official": "公司帳上餘額$13,000+代收票據$8,000+存款利息$2,800-存款不足退票$3,200-貨款金額誤記$300=正確餘額$20,300;銀行對帳單餘額-未兌現支票$7,600=$20,300,所以銀行對帳單餘額=$27,900。", "explain": {"concept": "銀行存款調節表:兩邊各自調整到「正確餘額」,相等。題目問的是銀行對帳單餘額,不是正確餘額。", "steps": ["先調整公司帳上餘額到正確餘額:", "公司帳 $13,000,加:銀行代收票據 $8,000(公司尚未入帳)、加:存款利息 $2,800;減:存款不足退票 $3,200;減:貨款誤記 $300(實際付840,帳上只記540,少扣了300)。", "正確餘額 = 13,000 + 8,000 + 2,800 - 3,200 - 300 = $20,300。", "再看銀行端:未兌現支票$9,600中,銀行保付的$2,000已由銀行先扣款,所以真正還在外面的是 9,600 - 2,000 = $7,600。", "銀行對帳單餘額 - 未兌現支票 7,600 = 正確餘額 20,300,所以銀行對帳單餘額 = 20,300 + 7,600 = $27,900。", "答案 (C)。(注意 (A) $20,300 是「正確餘額」,不是題目所問)"], "pitfalls": "算到$20,300就停了;題目問的是銀行對帳單餘額。另外保付支票不能算未兌現支票。", "distractors": {"A": "只算到「正確餘額」$20,300,沒有再回推銀行對帳單餘額。"}}, "check": "python 獨立計算:公司端 13,000+8,000+2,800-3,200-300=20,300;銀行端 20,300+9,600-2,000=27,900,與官方相符。", "verified": true, "note": ""}, {"id": "110-2-A-23", "exam": "110-2", "paper": "A", "q": 23, "unit": "十二、應收款項", "topic": "預期信用減損損失", "stem": "中平公司 X2 年期末調整前備抵損失貸餘$13,000,應收帳款明細帳戶餘額及帳齡分析表如下:\n\n| 賒欠時間 | 應收帳款餘額 | 估計損失率 |\n|---|---|---|\n| 31-60 天 | $200,000 | 1% |\n| 61-90 天 | 300,000 | 2% |\n| 91 天以上 | 100,000 | 3% |\n\nX2 年期末作預期信用減損損失的調整後,下列敘述何者正確?", "options": ["(A) 調整後「備抵損失」餘額$12,000", "(B) 期末提列「預期信用減損損失」$2,000", "(C) 期末應收帳款淨額$589,000", "(D) 作調整分錄後導致資產減少"], "answer": "C", "figure": null, "official": "調整後備抵損失=$200,000×1%+$300,000×2%+$100,000×3%=$11,000;應收帳款淨額=($200,000+$300,000+$100,000)-$11,000=$589,000。(B)(D) 調整分錄:借:備抵損失-應收帳款 2,000,貸:預期信用減損利益 2,000(營業費用減少,資產增加)。", "explain": {"concept": "帳齡分析法:期末備抵損失應有餘額=各帳齡應收帳款×損失率;調整數=應有餘額-調整前餘額。", "steps": ["先算期末「應有」的備抵損失:200,000×1% + 300,000×2% + 100,000×3% = 2,000 + 6,000 + 3,000 = $11,000。", "調整前備抵損失貸餘$13,000,比應有的$11,000多$2,000,所以要沖回$2,000。", "調整分錄:借:備抵損失-應收帳款 2,000;貸:預期信用減損利益 2,000。", "(A) 調整後餘額是$11,000,不是$12,000,錯。(B) 是「利益」$2,000,不是損失,錯。", "(C) 應收帳款總額 = 200,000+300,000+100,000 = $600,000,淨額 = 600,000 - 11,000 = $589,000,正確。", "(D) 備抵損失減少,淨資產(應收帳款淨額)反而增加,錯。答案 (C)。"], "pitfalls": "調整前備抵損失已有貸餘$13,000,不能直接提列$11,000;要算差額。", "distractors": {"A": "調整後餘額算成$12,000,與帳齡分析結果不符。", "B": "把應沖回的$2,000誤當成提列損失。", "D": "沒注意備抵損失減少使資產淨額增加。"}}, "check": "python 獨立計算:備抵 11,000;調整 -2,000(利益);淨額 589,000,與官方相符。", "verified": true, "note": ""}, {"id": "110-2-A-24", "exam": "110-2", "paper": "A", "q": 24, "unit": "十二、應收款項", "topic": "票據貼現與處分資產", "stem": "大鯨公司於 X1 年 6 月 1 日將營業用設備售予小蝦公司,該設備成本$200,000、累計折舊$40,000,收到小蝦公司開立面額$240,000、附息年利率 2%、X1 年 12 月 1 日到期之票據乙紙,當時市場利率(有效利率)為年利率 2%。X1 年 10 月 1 日大鯨公司將該票據持向銀行貼現,貼現率 3%。下列敘述何者正確?", "options": ["(A) 大鯨公司之票據貼現可取得現金$241,188", "(B) 大鯨公司因票據貼現產生利息費用$1,212", "(C) 大鯨公司 X1 年 6 月 1 日應認列處分不動產、廠房及設備利益$40,000", "(D) 大鯨公司 X1 年 10 月 1 日應除列該應收票據"], "answer": "A", "figure": null, "official": "到期值=$240,000+$240,000×2%×6/12=$242,400;貼現息=$242,400×3%×2/12=$1,212;貼現可得現金=$242,400-$1,212=$241,188。(B) 利息費用=$241,188-($240,000+$240,000×2%×4/12)=-$412(即損失$412);(C) 因票面利率=有效利率,票據現值=面額$240,000,處分利益=$240,000-($200,000-$40,000)=$80,000;(D) 於到期日 X1 年 12 月 1 日除列。", "explain": {"concept": "票據貼現:到期值-貼現息=貼現可得現金;票據現值=面額(票面利率=有效利率),處分資產利益=售價-帳面金額。", "steps": ["先算票據到期值:面額$240,000,年息2%,期間6/1~12/1共6個月,利息 = 240,000×2%×6/12 = $2,400,到期值 = $242,400。", "貼現10/1,距到期還有2個月(10/1~12/1),貼現息 = 242,400×3%×2/12 = $1,212。", "貼現可得現金 = 242,400 - 1,212 = $241,188,所以 (A) 正確。", "(B) $1,212是「貼現息」,不是利息費用;利息費用是貼現所得與票據帳面金額(面額240,000+已賺4個月利息1,600=241,600)的差:241,188 - 241,600 = -$412,即損失$412,不是$1,212。", "(C) 票面利率=有效利率,票據現值=面額$240,000;設備帳面金額=200,000-40,000=160,000;處分利益=240,000-160,000=$80,000,不是$40,000。", "(D) 依官方,應在到期日12/1才除列(貼現時負有或有負債/視為擔保借款),不是10/1。答案 (A)。"], "pitfalls": "把貼現息直接當利息費用;或把處分利益算成成本-累計折舊差額錯誤。", "distractors": {"B": "把貼現息$1,212當成利息費用,沒和票據帳面金額比較。", "C": "把處分利益誤算為$40,000(例如把累計折舊$40,000當成利益)。", "D": "以為貼現就除列;官方認為應於到期日除列。"}}, "check": "python 獨立計算:到期值 242,400;貼現息 1,212;現金 241,188;處分利益 80,000;與官方相符。", "verified": true, "note": "單元歸類可能有爭議:十二(票據貼現)/十五(處分設備)。(D) 與官方詳解一致但與常見「無追索權貼現即除列」觀念不同,僅照官方。"}, {"id": "110-2-A-25", "exam": "110-2", "paper": "A", "q": 25, "unit": "九、財務報表", "topic": "財務比率分析", "stem": "▲閱讀下文,回答第 25-26 題\n\n新冠肺炎(COVID-19)疫情影響各國經濟與生活,2020 年年初疫情迅速蔓延,民眾搶購醫療口罩導致口罩價格飆升,因此政府在 1 月底至 5 月底前實施醫療口罩「統一徵購、統一調控、統一售價」。到了 2021 年 5 月,臺灣疫情進入三級警戒,民眾因居家辦公與線上學習大幅增加,而大量購買筆電,由於禁止群聚,導致餐廳與觀光景點人潮大減,改以網絡購買家庭用品與食品。疫情也引發全球貨櫃航運的運價大漲,國內航運股獲利重現十多年不見的榮景。小明是個剛開始投資股票的股市小白,也想跟上這股「航海王」的熱潮,因此選了一家航運公司作為投資對象,透過公開資訊觀測站獲得其財務資料,分析該公司是否值得投資。該公司 2021 年第一季的流動資產及流動負債項目及金額如下表:\n\n| 項目 | 2021 年 3 月 31 日 | 項目 | 2021 年 3 月 31 日 |\n|---|---|---|---|\n| 現金及約當現金 | $53,000 | 合約負債 | $5,200 |\n| 應收票據 | 11,000 | 應付票據 | 10,200 |\n| 應收帳款 | 20,000 | 應付帳款 | 24,000 |\n| 存貨 | 5,000 | 其他應付款 | 8,200 |\n| 預付款項 | 1,000 | 本期所得稅負債 | 2,400 |\n| 流動資產合計 | $90,000 | 流動負債合計 | $50,000 |\n\n另知,該公司 2021 年第一季的綜合損益表相關資料:營業毛利率 52%、稅後純益率 45%、營業成本$43,200、營業費用$810。\n\n根據投資標的財務資料,下列敘述何者正確?", "options": ["(A) 流動比率可以用來判斷企業的長期償債能力", "(B) 速動比率為 1.70", "(C) 2021 年度綜合損益表的營業收入為$90,000", "(D) 2021 年第一季的稅後淨利為$40,500"], "answer": "D", "figure": null, "official": "(A) 流動比率可以用來判斷企業的短期償債能力;(B) 速動比率=($90,000-$5,000-$1,000)÷$50,000=1.68;(C)「第一季」的營業收入=$43,200÷(1-52%)=$90,000;(D) 第一季的稅後淨利=$90,000×45%=$40,500。", "explain": {"concept": "財務比率:流動比率與速動比率衡量短期償債能力;速動資產=流動資產-存貨-預付款項;毛利率=毛利÷營收;純益率=淨利÷營收。", "steps": ["(A) 流動比率是流動資產÷流動負債,衡量「短期」償債能力,不是長期,錯。", "(B) 速動比率 = 速動資產 ÷ 流動負債,速動資產 = 流動資產 - 存貨 - 預付款項 = 90,000 - 5,000 - 1,000 = $84,000,÷ 50,000 = 1.68,不是1.70,錯。", "(C) 先求營業收入:營業成本 = 營收 ×(1 - 毛利率),所以營收 = 43,200 ÷ (1 - 52%) = 43,200 ÷ 0.48 = $90,000。這是「第一季」的營收,不是「全年度」,而且$90,000剛好等於流動資產總額,是陷阱。", "所以 (C) 若說成「2021 年度」就是錯的,因為這個$90,000只是第一季的營業收入(官方詳解特別標註「第一季」)。", "(D) 稅後淨利 = 營收 × 稅後純益率 = 90,000 × 45% = $40,500,正確。", "答案 (D)。"], "pitfalls": "忘了速動資產要扣預付款項;或把「第一季」資料說成「全年度」。", "distractors": {"A": "把流動比率誤當作長期償債指標。", "B": "速動資產只扣存貨(85,000÷50,000=1.70),漏扣預付款項。", "C": "數字$90,000 正確,但題目說「2021年度」,資料只是第一季;官方視為錯誤選項。"}}, "check": "python 獨立計算:速動比率 1.68;營收 43,200/0.48=90,000;淨利 40,500,與官方相符。", "verified": true, "note": "題幹 25~26 題為題組,26 題為經濟學不處理。官方未對 (C) 作詳細說明(僅以「第一季」註記),本題解析已補充。"}, {"id": "110-3-A-01", "exam": "110-3", "paper": "A", "q": 1, "unit": "二、會計循環及會計帳簿", "topic": "傳票與憑證", "stem": "下列敘述何者正確?", "options": ["傳票是原始憑證,折舊分攤表為記帳憑證", "複式傳票係以會計項目為單位,每一會計項目填製一張傳票", "單式傳票係以交易為單位,每一交易填製一張傳票", "各項會計憑證,除須永久保存或有關未結會計事項者外,應於財務年度決算程序後,至少保存5年"], "answer": "D", "figure": null, "official": "傳票是記帳憑證,折舊分攤表為原始憑證(內部憑證);單式傳票以會計項目為單位,複式傳票以交易為單位。", "explain": {"concept": "考傳票與會計憑證的基本分類,以及商業會計法對憑證保存年限的規定。", "steps": ["先分清楚兩大類:原始憑證是交易發生的證明(如發票、收據、折舊分攤表),記帳憑證是會計人員據以記帳的傳票。", "所以選項 A 把兩者顛倒了:傳票是記帳憑證,折舊分攤表是原始憑證(屬內部憑證)。", "再記傳票的口訣:複式傳票「一個交易一張」,單式傳票「一個會計項目一張」。選項 B、C 剛好說反了。", "選項 D 符合商業會計法:會計憑證除永久保存或未結事項外,於年度決算程序後至少保存5年,故答案是 D。"], "pitfalls": "傳票種類最容易把「單式、複式」的單位記反,可用「複=複雜=整筆交易一起寫」幫助記憶。", "distractors": {"A": "把原始憑證與記帳憑證的定義顛倒。", "B": "把複式傳票的單位誤記成會計項目(那是單式傳票)。", "C": "把單式傳票的單位誤記成交易(那是複式傳票)。"}}, "check": "概念題:對照官方詳解與商業會計法常識,答案 D。", "verified": true, "note": ""}, {"id": "110-3-A-02", "exam": "110-3", "paper": "A", "q": 2, "unit": "一、會計基本概念", "topic": "會計資訊與準則", "stem": "下列敘述何者錯誤?", "options": ["投資人、債權人、客戶是會計資訊的外部使用者", "財務會計最主要目的是強化內部控制與防止舞弊", "國際財務報導準則正體中文版是由金管會認可發布", "公用事業會計是與一般人民生活有關事業之會計"], "answer": "B", "figure": null, "official": "財務會計的主要目的是提供對決策有用的財務資訊給外部使用者,而非強化內部控制。", "explain": {"concept": "考財務會計的目的、會計資訊使用者與準則制定機關。", "steps": ["財務會計的主要目的是「提供有用的財務資訊,幫助報導外部的人做決策」。", "強化內部控制與防止舞弊是內部控制制度(或管理會計)的功能,不是財務會計最主要的目的,所以 B 錯誤。", "其他選項:投資人、債權人、客戶屬外部使用者(A 對);IFRS 正體中文版由金管會認可發布(C 對);公用事業會計指與民生有關事業(如水電、瓦斯)的會計(D 對)。"], "pitfalls": "題目問「錯誤」,不要選成正確的敘述。", "distractors": {"A": "此敘述正確,不是答案。", "C": "此敘述正確,不是答案。", "D": "此敘述正確,不是答案。"}}, "check": "概念題:與官方詳解答案一致。", "verified": true, "note": ""}, {"id": "110-3-A-03", "exam": "110-3", "paper": "A", "q": 3, "unit": "二、會計循環及會計帳簿", "topic": "內部原始憑證", "stem": "下列既為原始憑證亦是內部憑證有哪幾項?\n①進貨發票  ②銷貨發票  ③水電費收據  ④薪資計算表\n⑤轉帳傳票  ⑥領料單  ⑦請購單  ⑧訂購單", "options": ["①②③", "④⑥⑦", "①②③⑥", "②④⑥⑦⑧"], "answer": "B", "figure": null, "official": "④薪資計算表、⑥領料單、⑦請購單為內部原始憑證。", "explain": {"concept": "原始憑證依來源分為外來、對外、內部三種,本題要找「內部憑證」。", "steps": ["內部憑證:企業內部自己製作、不對外的原始憑證。", "①進貨發票、③水電費收據是外來憑證(別人開給我們);②銷貨發票、⑧訂購單是對外憑證(我們開給別人)。", "⑤轉帳傳票是記帳憑證,不是原始憑證。", "④薪資計算表、⑥領料單、⑦請購單都是公司內部單據,故答案為 ④⑥⑦,選 B。"], "pitfalls": "容易把訂購單當成內部憑證,但它是送給供應商的,屬對外憑證。", "distractors": {"A": "①②③是外來或對外憑證,不屬內部。", "C": "①②③都不是內部憑證,只有⑥是。", "D": "②、⑧是對外憑證,混入了不屬內部的項目。"}}, "check": "概念題:與官方詳解一致(④⑥⑦)。", "verified": true, "note": ""}, {"id": "110-3-A-04", "exam": "110-3", "paper": "A", "q": 4, "unit": "九、財務報表", "topic": "財務報表與準則", "stem": "下列敘述哪些正確?\n①主要財務報表中,僅有現金流量表為動態,其餘均為靜態報表\n②「國際財務報導準則」正體中文版是公開發行公司應遵循的一般公認會計原則\n③「企業會計準則公報」是非公開發行公司應遵循的一般公認會計原則\n④權益變動表係表達企業在特定期間的權益項目增減變動情形\n⑤「國際財務報導準則」由我國會計研究發展基金會接受金管會委託負責翻譯成正體中文版", "options": ["①②③", "①②④⑤", "①③④⑤", "②③④⑤"], "answer": "D", "figure": null, "official": "①錯誤:主要財務報表中僅有資產負債表為靜態報表,其餘均為動態報表。", "explain": {"concept": "考財務報表的動靜態分類與我國會計準則體系。", "steps": ["靜態報表是表達「某一時點」的狀況,動態報表是表達「一段期間」的變動。", "資產負債表是某一日的狀況,為靜態;綜合損益表、權益變動表、現金流量表都是一段期間,為動態。所以①說「只有現金流量表是動態」是錯的。", "②③④⑤皆正確:公開發行公司適用 IFRS,非公開發行公司適用企業會計準則公報;權益變動表表達權益增減;IFRS 由會計研究發展基金會受託翻譯。", "①錯、其餘對,答案 D(②③④⑤)。"], "pitfalls": "記住「靜態只有資產負債表」,其他三大報表都是動態。", "distractors": {"A": "含錯誤的①,且漏掉④⑤。", "B": "含錯誤的①,且漏掉③。", "C": "含錯誤的①,且漏掉②。"}}, "check": "概念題:與官方詳解一致。", "verified": true, "note": ""}, {"id": "110-3-A-05", "exam": "110-3", "paper": "A", "q": 5, "unit": "一、會計基本概念", "topic": "會計恆等式求收益", "stem": "臺北商店 08 年初資產$330,000、負債$60,000,至年底時資產增加$24,000,負債減少至$42,000,當年業主曾提取商品$8,000,該店全年費損$224,000,08 年度之收益為何?", "options": ["$274,000", "$253,000", "$224,000", "$182,000"], "answer": "A", "figure": null, "official": "年初權益 $270,000;年底權益 $312,000;$312,000 = $270,000 − $8,000 + 收益 − $224,000,收益 = $274,000。", "explain": {"concept": "用「資產 − 負債 = 權益」及權益變動公式:期末權益 = 期初權益 − 提取 + 收益 − 費損。", "steps": ["先算年初權益:$330,000 − $60,000 = $270,000。", "年底資產 = $330,000 + $24,000 = $354,000;年底負債 = $42,000;年底權益 = $354,000 − $42,000 = $312,000。", "列權益變動式:期末權益 $312,000 = 期初 $270,000 − 提取 $8,000 + 收益 − 費損 $224,000。", "解得收益 = $312,000 − $270,000 + $8,000 + $224,000 = $274,000,選 A。"], "pitfalls": "業主提取要「減」權益;題目給的「費損」是要從收益中扣掉的,別漏掉。", "distractors": {"C": "直接拿費損 $224,000 當收益,沒有用權益公式。"}}, "check": "python:312000-270000+8000+224000 = 274000,與官方相符。", "verified": true, "note": ""}, {"id": "110-3-A-06", "exam": "110-3", "paper": "A", "q": 6, "unit": "一、會計基本概念", "topic": "會計恆等式求權益", "stem": "阿明在台中商店擔任會計工作,老闆在 08 年的年度工作會議上,宣布 08 年度獲利目標為$300,000,阿明看了一下 08 年初資產負債表,資產及負債分別為$900,000 及$400,000,一年很快過去了,阿明作完期末結帳分錄,將報表及帳簿送給財務主任,老闆卻打電話給阿明,問「我們商店 08 年有達到獲利目標嗎?」這時阿明手上只有多印的 08 年底資產負債表,阿明記得 08 年中老闆替商店償還貸款$30,000,此外,08 年無其他權益增減變化,因此阿明看 08 年底資產負債表中的「權益」應為多少,才能達到此獲利目標?", "options": ["$830,000", "$860,000", "$1,160,000", "$1,460,000"], "answer": "A", "figure": null, "official": "08 年底權益 = ($900,000 − $400,000) + $300,000 + $30,000 = $830,000。", "explain": {"concept": "期末權益 = 期初權益 + 本期損益 + 業主增資 − 業主提取。業主替商店還貸款等於業主投入資本。", "steps": ["期初權益 = 資產 − 負債 = $900,000 − $400,000 = $500,000。", "要達到獲利目標,本期純益至少 $300,000,使權益增加 $300,000。", "老闆用自己的錢替商店還貸款 $30,000,對商店而言是業主增資,權益再增加 $30,000。", "期末權益 = $500,000 + $300,000 + $30,000 = $830,000,選 A。"], "pitfalls": "替商店還款是「業主投資」,會讓權益增加,不是減少。", "distractors": {}}, "check": "python:(900000-400000)+300000+30000 = 830000,與官方相符。", "verified": true, "note": ""}, {"id": "110-3-A-07", "exam": "110-3", "paper": "A", "q": 7, "unit": "十三、存貨", "topic": "進貨折扣與現金折扣", "stem": "小華在臺北商店擔任會計工作,老闆說我們商店進貨的價格偏高,所以小華開始注意進貨價格,08 年 5 月 1 日商店賒購商品定價$400,000,八折成交,付款條件 2/10,1/20,n/30,小華希望進貨成本為$316,000,才不至於資金短缺,也可以取得適當的折扣,請問下列還款方式,哪一方式最接近小華評估的進貨成本?", "options": ["若 5 月 9 日支付四分之三貨款,5 月 18 日支付餘款", "若 5 月 9 日支付四分之一貨款,5 月 18 日支付餘款", "若 5 月 19 日支付四分之一貨款,5 月 28 日支付餘款", "若 5 月 19 日支付四分之三貨款,5 月 28 日支付餘款"], "answer": "B", "figure": null, "official": "$400,000×80% = $320,000;$320,000÷4×2% + $320,000÷4×3×1% = $4,000;$320,000 − $4,000 = $316,000。", "explain": {"concept": "商業折扣(八折)先扣,再依付款時間適用現金折扣:10 天內 2%,11~20 天內 1%,超過 20 天無折扣。", "steps": ["先算商業折扣後的發票價:$400,000 × 80% = $320,000。", "目標進貨成本 $316,000,表示現金折扣合計要 $320,000 − $316,000 = $4,000。", "試選項 B:5/9(10 天內)付 1/4 = $80,000,折扣 2% = $1,600;5/18(20 天內)付 3/4 = $240,000,折扣 1% = $2,400;合計 $4,000,符合。", "進貨成本 = $320,000 − $4,000 = $316,000,選 B。"], "pitfalls": "折扣期間:5/1 起算,2/10 到 5/11,1/20 到 5/21;5/19 仍在 1% 期間內,但 2% 已過。", "distractors": {"A": "先付 3/4 享 2%:$240,000×2%+$80,000×1% = $5,600,進貨成本 $314,400,低於目標。", "C": "5/19 已過 2% 期限,全部只能享 1%(最多 $3,200),無法達到 $4,000。", "D": "同樣全部只享 1%,折扣更少或相同於 C,無法達 $4,000。"}}, "check": "python 算 B=4000 折扣、進貨成本 316000,與官方相符;A=5600,C/D 皆 ≤3200。", "verified": true, "note": ""}, {"id": "110-3-A-08", "exam": "110-3", "paper": "A", "q": 8, "unit": "四、分錄與日記簿", "topic": "四分法傳票", "stem": "在複式傳票四分法下,下列敘述何者正確?", "options": ["與臺南公司簽訂銷貨合約,應編製現金收入傳票", "本店代業主支付租金,應編製分錄轉帳傳票", "銷售商品一批$40,000,半數收現、半數暫欠,應編製現金轉帳傳票", "購買機器設備半數簽發 20 天期票據,半數暫欠,應編製現金轉帳傳票"], "answer": "C", "figure": null, "official": "A 簽訂合約不是會計交易;B 業主代付租金應編現金支出傳票;D 全為轉帳,應編分錄轉帳傳票。", "explain": {"concept": "四分法把傳票分為現金收入、現金支出、現金轉帳、分錄轉帳四種,依交易是否涉及現金判斷。", "steps": ["四分法判斷口訣:收入全是現金→現金收入傳票;支出全是現金→現金支出傳票;一部分現金一部分轉帳→現金轉帳傳票;完全不涉及現金→分錄轉帳傳票。", "A:簽訂合約只是承諾,不是會計上的交易,不需編傳票。", "B:業主代付租金,視同商店收到業主投入的現金後支付,依官方詳解應編現金支出傳票,不是分錄轉帳。", "C:銷貨一半收現金、一半暫欠,有現金也有轉帳,屬現金轉帳傳票,正確。", "D:機器設備一半開票、一半暫欠,完全沒有現金,應編分錄轉帳傳票。"], "pitfalls": "「現金轉帳」代表一筆交易中「部分現金、部分轉帳」,若完全沒現金就是分錄轉帳。", "distractors": {"A": "合約簽訂不是交易,不需傳票。", "B": "忽略業主代付視同商店支付現金,應編現金支出傳票。", "D": "以為「簽發票據」就是現金,實際票據不是現金,全屬轉帳。"}}, "check": "概念題:與官方詳解一致。", "verified": true, "note": ""}, {"id": "110-3-A-09", "exam": "110-3", "paper": "A", "q": 9, "unit": "六、試算與試算表", "topic": "錯誤對試算表的影響", "stem": "台中公司 08 年 9 月 30 日查核試算表時發現下列錯誤:\n①現銷商品$6,000,誤記為$600\n②現購商品$5,000,誤記為賒購商品\n③償還應付帳款$19,000,誤記為借:現金$19,000,貸:應付帳款$19,000\n試問上述錯誤對餘額式試算表借貸方合計金額有何影響?", "options": ["借貸方合計均多計$48,400", "借貸方合計均多計$37,600", "借貸方合計均多計$27,600", "無影響"], "answer": "B", "figure": null, "official": "更正後借、貸方合計各減少 $37,600,故原試算表借貸方各多計 $37,600。", "explain": {"concept": "餘額式試算表是各帳戶「餘額」的合計,所以要把錯誤分錄與正確分錄比較,看各帳戶餘額差多少。", "steps": ["①現銷:正確應借現金 $6,000、貸銷貨收入 $6,000,誤記 $600,故現金(借方)與銷貨收入(貸方)餘額各少計 $5,400,借貸合計各少 $5,400。", "②現購誤為賒購:應貸記現金卻貸記應付帳款。更正:借應付帳款 $5,000、貸現金 $5,000,現金借餘減 $5,000、應付帳款貸餘減 $5,000。", "③還款誤記為借現金、貸應付帳款:正確應借應付帳款、貸現金。更正:借應付帳款 $38,000、貸現金 $38,000(要把錯記方向與少記的正確分錄都修正:$19,000×2),現金借餘減 $38,000、應付帳款貸餘減 $38,000。", "更正金額合計:借方 +5,400 −5,000 −38,000 = −37,600;貸方同為 −37,600。", "代表原試算表借貸方各多計 $37,600,選 B。"], "pitfalls": "餘額式試算表看的是帳戶餘額;①是少計,更正時要「加回」,其餘更正是「減少」,別把方向弄反。", "distractors": {"A": "把①的 5,400 方向弄反,例如 5,000+38,000+5,400 = 48,400。", "D": "以為每筆分錄借貸金額相等就不會影響試算表,忽略餘額式試算表看的是帳戶餘額。"}}, "check": "python:+5400−5000−38000 = −37600,與官方相符。", "verified": true, "note": ""}, {"id": "110-3-A-10", "exam": "110-3", "paper": "A", "q": 10, "unit": "六、試算與試算表", "topic": "過帳錯誤對試算表的影響", "stem": "臺北公司 12/2 帳列「應收帳款」借餘$50,000,12/3 發生收回帳款$35,000 之交易,過帳時貸方重複過帳,12/2 及 12/3 無其他「應收帳款」交易,則此錯誤對餘額式試算表借貸方合計金額有何影響?", "options": ["借方合計少計$35,000、貸方合計多計$20,000", "借方合計少計$35,000", "貸方合計多計$35,000", "借方合計少計$15,000、貸方合計多計$20,000"], "answer": "D", "figure": null, "official": "正確餘額為借餘 $15,000;錯誤時變成貸餘 $20,000,故借方少計 $15,000、貸方多計 $20,000。", "explain": {"concept": "餘額式試算表比較「正確餘額」與「錯誤餘額」,而不是比較重複過帳的金額。", "steps": ["正確情形:應收帳款借餘 $50,000,收回 $35,000 貸方記一次,餘額 = 借餘 $50,000 − $35,000 = 借餘 $15,000。", "錯誤情形:貸方重複過帳,貸方共 $70,000,餘額 = $50,000 − $70,000 = 貸餘 $20,000。", "與正確情形比:借方餘額 $15,000 變成沒有 → 借方合計少計 $15,000;貸方多出貸餘 $20,000 → 貸方合計多計 $20,000。", "答案選 D。"], "pitfalls": "因為帳戶餘額會由借餘變貸餘,所以不是只多算 $35,000,要分別看借方少計和貸方多計。", "distractors": {"A": "借方少計 $35,000 忽略餘額的轉變,只考慮重複金額。", "B": "只看借方,忽略貸方多計。", "C": "以為多計金額就是重複過帳的 $35,000,但餘額式要看帳戶餘額。"}}, "check": "python:正確借餘 15,000;錯誤貸餘 20,000,與官方相符。", "verified": true, "note": ""}, {"id": "110-3-A-11", "exam": "110-3", "paper": "A", "q": 11, "unit": "六、試算與試算表", "topic": "錯誤更正方法", "stem": "有關更正錯誤的敘述,下列何者錯誤?", "options": ["凡影響借貸平衡之分錄錯誤,其錯誤更正必採用註銷更正法", "不影響借貸平衡之分錄錯誤,其更正方法須視其過帳與否而有所差異", "不影響借貸平衡之過帳錯誤,其錯誤更正必採用註銷更正法", "不影響借貸平衡的試算錯誤,其錯誤更正必採用分錄更正法"], "answer": "D", "figure": null, "official": "官方詳解:不影響借貸平衡之試算錯誤,其錯誤更正必採用註銷更正法(故 D 錯誤)。", "explain": {"concept": "考錯誤更正法的選擇:註銷更正法與分錄更正法的適用情形。", "steps": ["註銷更正法:把錯誤分錄註銷後重新記入正確分錄,適用於影響借貸平衡的錯誤(分錄或過帳),以及過帳錯誤。", "分錄更正法:另作一筆更正分錄,適用於不影響借貸平衡、且分錄已過帳的錯誤。", "B:不影響平衡的分錄錯誤,若尚未過帳可用註銷更正法,已過帳則用分錄更正法,因此須視過帳與否,這句話正確。", "D:說「必」採分錄更正法太絕對,官方判定為錯誤,故選 D。"], "pitfalls": "出現「必」「均」「凡」這類絕對用語時,通常是陷阱,要先懷疑。", "distractors": {"A": "此敘述官方判定為正確。", "B": "此敘述官方判定為正確。", "C": "此敘述官方判定為正確。"}}, "check": "概念題:答案依官方為 D,但官方詳解對 D 的文字與題目選項不完全一致(詳解寫為「註銷更正法」),我無法獨立確認各選項細節。", "verified": false, "note": "官方詳解中 D 的敘述(註銷更正法)與題目選項 D(分錄更正法)文字不同,疑似詳解筆誤;答案依官方 D。"}, {"id": "110-3-A-12", "exam": "110-3", "paper": "A", "q": 12, "unit": "七、調整", "topic": "預付租金調整", "stem": "台中公司 08 年 6 月 1 日預付三年租金,採先實後虛法記帳,08 年底調整分錄為借記租金支出$56,000,則下列敘述何者錯誤?", "options": ["三年租金支出共$288,000", "09 年底調整分錄應借:預付租金$96,000", "09 年底預付租金餘額$136,000", "11 年度租金支出$40,000"], "answer": "B", "figure": null, "official": "每月租金 $8,000;09 年底調整應借記租金支出 $96,000,而非預付租金。", "explain": {"concept": "預付租金先記資產(預付租金),期末再把已過期的部分轉成租金支出。", "steps": ["08 年 6/1 到 12/31 共 7 個月,已過期租金 $56,000,所以每月租金 = $56,000 ÷ 7 = $8,000。", "三年共 36 個月,總租金 = $8,000 × 36 = $288,000(A 正確)。", "09 年全年 12 個月,已過期 = $8,000 × 12 = $96,000,調整分錄是借:租金支出 $96,000、貸:預付租金 $96,000,不是借預付租金,所以 B 錯誤。", "09 年底預付租金餘額 = $8,000 × (36 − 7 − 12) = $8,000 × 17 = $136,000(C 正確)。", "11 年度只剩 1~5 月(合約到 11/5/31),租金支出 = $8,000 × 5 = $40,000(D 正確)。"], "pitfalls": "題目問「錯誤」;調整分錄方向要看「過期部分轉為費用」,不是借記預付。", "distractors": {"A": "此敘述正確,不是答案。", "C": "此敘述正確,不是答案。", "D": "此敘述正確,不是答案。"}}, "check": "python:56000/7=8000; 8000*36=288000; 8000*17=136000; 8000*5=40000,與官方相符。", "verified": true, "note": ""}, {"id": "110-3-A-13", "exam": "110-3", "paper": "A", "q": 13, "unit": "九、財務報表", "topic": "綜合損益表比率分析", "stem": "臺北公司 08 年度綜合損益表顯示,銷貨毛利率 20%,營業利益率 10%,稅前純益率 8%,營業外收支項目只有租金收入$15,000 以及利息費用若干。已知本期營業利益為$90,000;所得稅費用依所得稅法規定課徵。依此下列何者錯誤?", "options": ["營業費用$180,000", "利息費用$33,000", "稅後純益率 8%", "銷貨淨額$900,000"], "answer": "A", "figure": null, "official": "銷貨淨額 $900,000;營業費用 = $900,000×(20%−10%) = $90,000,故 A 錯誤。", "explain": {"concept": "用損益表比率往回推:銷貨淨額 = 營業利益 ÷ 營業利益率;營業費用 = 毛利 − 營業利益。", "steps": ["銷貨淨額 = $90,000 ÷ 10% = $900,000(D 正確)。", "毛利 = $900,000 × 20% = $180,000;營業費用 = 毛利 − 營業利益 = $180,000 − $90,000 = $90,000,不是 $180,000,所以 A 錯誤。", "稅前純益 = $900,000 × 8% = $72,000;$90,000 + $15,000 − 利息費用 = $72,000,利息費用 = $33,000(B 正確)。", "稅前純益 $72,000 低於 $120,000,免稅,所得稅費用 $0,稅後純益率 = 8%(C 正確)。"], "pitfalls": "$180,000 其實是毛利,不是營業費用,小心把毛利與營業費用搞混。", "distractors": {"B": "此敘述正確,不是答案。", "C": "此敘述正確,不是答案。", "D": "此敘述正確,不是答案。"}}, "check": "python:銷貨 900000;營業費用 90000;利息 33000,與官方相符。", "verified": true, "note": ""}, {"id": "110-3-A-14", "exam": "110-3", "paper": "A", "q": 14, "unit": "十四、證券投資", "topic": "透過損益按公允價值衡量之金融資產", "stem": "高雄公司 08 年初以每股買價$28 購入臺中公司股票 10,000 股(每股面額$10),4 月 1 日收到現金股利$10,000,8 月 1 日收到股票股利 10%,年底該股票每股公允價值$26。若分類為透過損益按公允價值衡量之金融資產,則該投資對高雄公司 08 年的本期損益影響數為何?", "options": ["損$6,000", "損$16,000", "益$6,000", "益$16,000"], "answer": "D", "figure": null, "official": "$10,000 + ($26×11,000 − $28×10,000) = $16,000(益)。", "explain": {"concept": "FVTPL 金融資產:現金股利列為收益,股票股利只增加股數不入帳,期末按公允價值評價,評價損益列入當期損益。", "steps": ["原始成本 = $28 × 10,000 = $280,000。", "現金股利 $10,000 為股利收入(益 $10,000)。", "股票股利 10% = 1,000 股,只增加股數、不作分錄,期末股數 = 11,000 股。", "年底公允價值 = $26 × 11,000 = $286,000;評價利益 = $286,000 − $280,000 = $6,000。", "本期損益影響 = $10,000 + $6,000 = 益 $16,000,選 D。"], "pitfalls": "股票股利不是收益,只是股數增加、單位成本降低。別把它當作股利收入。", "distractors": {"A": "忽略現金股利並把評價方向弄反(−$6,000)。", "C": "只算評價利益 $6,000,漏了現金股利 $10,000。"}}, "check": "python:10000+26*11000-28*10000 = 16000,與官方相符。", "verified": true, "note": ""}, {"id": "110-3-A-15", "exam": "110-3", "paper": "A", "q": 15, "unit": "十、加值型營業稅會計實務", "topic": "留抵稅額", "stem": "臺北公司適用 5%加值型營業稅制,已知本期申報資料(未含稅):進貨及費用$6,000,000、購置房屋及建築$3,000,000、內銷$4,000,000、外銷$1,100,000、上期留抵稅額$25,000,則本期留抵稅額餘額為何?", "options": ["$0", "$45,000", "$70,000", "$100,000"], "answer": "C", "figure": null, "official": "進項稅額 $450,000;銷項稅額 $200,000;應退稅額 $205,000;本期留抵稅額 $275,000 − $205,000 = $70,000。", "explain": {"concept": "加值型營業稅:進項稅額 − 銷項稅額 = 留抵稅額;外銷零稅率,可申請退稅(以進項稅額占比限額)。", "steps": ["進項稅額 = ($6,000,000 + $3,000,000) × 5% = $450,000。", "銷項稅額 = 內銷 $4,000,000 × 5% = $200,000(外銷零稅率,銷項為 0)。", "本期申報留抵稅額 = $450,000 + 上期留抵 $25,000 − $200,000 = $275,000。", "應退稅額 = (外銷 $1,100,000 × 5% + 購置固定資產 $3,000,000 × 5%) = $55,000 + $150,000 = $205,000。", "本期留抵稅額餘額 = $275,000 − $205,000 = $70,000,選 C。"], "pitfalls": "外銷零稅率才有退稅;固定資產的進項稅額可全額申請退還(以不超過留抵稅額為限)。", "distractors": {}}, "check": "python:450000+25000−200000−(55000+150000) = 70000,與官方相符。", "verified": true, "note": ""}, {"id": "110-3-A-16", "exam": "110-3", "paper": "A", "q": 16, "unit": "九、財務報表", "topic": "資產負債表與流動、速動比率", "stem": "高雄商店 109 年 12 月 31 日資產負債表資料如下,已知流動比率為 2,速動比率為 1。\n\n| 項目 | 金額 | 項目 | 金額 |\n|---|---|---|---|\n| 資產 | | 負債及權益 | |\n| 流動資產: | | 流動負債: | |\n| 現金及約當現金 | 280,000 | 應付票據 | (   ) |\n| 應收帳款淨額 | 220,000 | 應付帳款 | 350,000 |\n| 存貨 | (   ) | 非流動負債: | |\n| 流動資產合計 | (   ) | 銀行長期借款 | 500,000 |\n| 非流動資產: | | 負債合計 | (   ) |\n| 不動產、廠房及設備 | 1,200,000 | 權益 | |\n| 非流動資產合計 | 1,200,000 | 業主資本 | 600,000 |\n| | | 業主往來 | (   ) |\n| | | 權益合計 | (   ) |\n| 資產總計 | (   ) | 負債及權益總計 | (   ) |\n\n則下列金額何者錯誤?", "options": ["流動負債$500,000", "應付票據$150,000", "流動資產$1,000,000", "存貨$400,000"], "answer": "D", "figure": null, "official": "存貨 = $1,000,000 − ($280,000 + $220,000) = $500,000,故 D 錯誤。", "explain": {"concept": "用速動比率求流動負債,再用流動比率求流動資產。", "steps": ["速動資產 = 現金 $280,000 + 應收帳款 $220,000 = $500,000。", "速動比率 = 速動資產 ÷ 流動負債 = 1,所以流動負債 = $500,000。", "流動負債 = 應付票據 + 應付帳款 $350,000 = $500,000,應付票據 = $150,000。", "流動比率 = 流動資產 ÷ 流動負債 = 2,流動資產 = $500,000 × 2 = $1,000,000。", "存貨 = 流動資產 − 速動資產 = $1,000,000 − $500,000 = $500,000,不是 $400,000,所以 D 錯誤。"], "pitfalls": "題目問「錯誤」;速動資產不含存貨。", "distractors": {"A": "此金額正確,不是答案。", "B": "此金額正確,不是答案。", "C": "此金額正確,不是答案。"}}, "check": "python:速動 500000;流動負債 500000;流動資產 1000000;存貨 500000,與官方相符。", "verified": true, "note": ""}, {"id": "110-3-A-17", "exam": "110-3", "paper": "A", "q": 17, "unit": "九、財務報表", "topic": "資產負債表(業主往來)", "stem": "同上題,則業主往來為何?", "options": ["$400,000", "$500,000", "$600,000", "$800,000"], "answer": "C", "figure": null, "official": "資產 $2,200,000 − 負債 $1,000,000 = 權益 $1,200,000;業主往來 = $1,200,000 − $600,000 = $600,000。", "explain": {"concept": "會計恆等式:資產 = 負債 + 權益。", "steps": ["資產總計 = 流動資產 $1,000,000 + 非流動資產 $1,200,000 = $2,200,000。", "負債合計 = 流動負債 $500,000 + 長期借款 $500,000 = $1,000,000。", "權益合計 = 資產 − 負債 = $2,200,000 − $1,000,000 = $1,200,000。", "權益 = 業主資本 $600,000 + 業主往來,所以業主往來 = $1,200,000 − $600,000 = $600,000,選 C。"], "pitfalls": "本題要用到上題算出的流動資產 $1,000,000(存貨是 $500,000),上題算錯會連帶錯。", "distractors": {"B": "若沿用上題錯誤的存貨 $400,000,資產 $2,100,000、權益 $1,100,000,業主往來變成 $500,000。"}}, "check": "python:2200000−1000000−600000 = 600000,與官方相符。", "verified": true, "note": ""}, {"id": "110-3-A-18", "exam": "110-3", "paper": "A", "q": 18, "unit": "十一、現金及內部控制", "topic": "銀行調節表", "stem": "臺北公司 08 年 4 月底之帳載銀行存款餘額與銀行結單餘額不符,經核對後發現差異如下:\n①4 月 30 日送存$10,000,銀行尚未入帳\n②請銀行託收票據$10,000,票據到期銀行已入帳\n③公司所開支票$13,000,公司誤記為$31,000\n④存款不足退票$10,000\n⑤未兌現支票$10,000(含保付支票$2,000)\n⑥銀行將其他公司所開立支票$10,000 兌現,誤扣公司存款\n上述差異,在由公司帳載餘額調至銀行結單餘額的銀行調節表,列為減項者有哪些?", "options": ["①②④", "①④⑥", "②③④⑤", "①③④⑤⑥"], "answer": "B", "figure": null, "official": "公司帳載 + ② + ③ − ④ = 銀行結單 + ① − ⑤ + ⑥;調至銀行結單時,減項為 ①④⑥。", "explain": {"concept": "調節表的原則:兩邊餘額各自加減,調整到同一個正確餘額。", "steps": ["先決定「由公司帳載餘額調至銀行結單餘額」要怎麼調:把帳載餘額調成正確餘額,再把正確餘額推回銀行結單餘額。", "公司帳載餘額需調整的項目:②託收票據入帳(+10,000)、③公司少記 $18,000(+18,000)、④退票(−10,000)。", "銀行結單需調整的項目:①在途存款(+10,000)、⑤未兌現支票(−8,000,保付支票 $2,000 銀行已扣)、⑥銀行誤扣(+10,000)。", "因此:公司帳載 + ② + ③ − ④ = 銀行結單 + ① − ⑤ + ⑥。", "由帳載調至銀行結單,方向要反過來看:銀行結單 = 公司帳載 + ② + ③ − ④ − ① + ⑤ − ⑥,所以列為減項的是 ①、④、⑥,選 B。"], "pitfalls": "保付支票銀行已先扣款,不屬未兌現支票;調節表由哪一邊調到哪一邊,加減號會相反。", "distractors": {"A": "把②(銀行已託收入帳,帳載應加)誤當減項。", "C": "②③⑤其實是加項,只有④是減項。", "D": "把③⑤兩個加項也當成減項。"}}, "check": "依官方詳解的調節式驗證:減項為 ①④⑥,與官方相符。", "verified": true, "note": ""}, {"id": "110-3-A-19", "exam": "110-3", "paper": "A", "q": 19, "unit": "十二、應收款項", "topic": "票據貼現與資金成本率", "stem": "大英在高雄商店擔任會計工作,高雄商店 2 月 1 日賒銷商品收到一張面額$120,000,6 個月期,附息 3%票據乙張,4 月 1 日因資金需求,擬持上述票據前往 A 銀行貼現,貼現率 7.5%,財務經理就問大英,我們合作的另一家 B 銀行,正在推廣貸款,聽說利率比較低。大英決定去了解 B 銀行的利率,若你是大英,要以下列何項四個月期借款年利率大小來判斷是否要轉向 B 銀行借款?", "options": ["3%", "7.5%", "7.69%", "7.87%"], "answer": "C", "figure": null, "official": "貼現實得 $118,755;$118,755 × 資金成本率 × 4/12 = $3,045,資金成本率 = 7.69%。", "explain": {"concept": "票據貼現相當於向銀行借款,實際資金成本率 = 貼現息 ÷ 實得款項 ÷ 期間(年化)。", "steps": ["到期值 = $120,000 + $120,000 × 3% × 6/12 = $121,800。", "貼現期間:4/1 到 8/1,共 4 個月;貼現息 = $121,800 × 7.5% × 4/12 = $3,045。", "貼現得款(貼現值)= $121,800 − $3,045 = $118,755。", "實際借了 $118,755、用了 4 個月,付出利息 $3,045,所以資金成本率 = $3,045 ÷ $118,755 ÷ (4/12) = 7.69%。", "要比較 B 銀行的借款年利率是否低於 7.69%,選 C。"], "pitfalls": "貼現率 7.5% 是以到期值計算,不等於實際資金成本率;實際借到的錢是貼現值,基數較小,所以成本率較高。", "distractors": {"A": "3% 是票據本身的票面利率,不是借款成本。", "B": "7.5% 是銀行的貼現率,未考慮實際得款較少。"}}, "check": "python:3045/118755*12/4 = 7.69%,與官方相符。", "verified": true, "note": ""}, {"id": "110-3-A-20", "exam": "110-3", "paper": "A", "q": 20, "unit": "十三、存貨", "topic": "存貨成本流動假設", "stem": "臺北公司於 02 年 7 月初成立,7 月份存貨相關資訊如下:\n7/5  進貨 500 單位,單位成本$10        7/26  出售 400 單位,單位售價$18\n7/25 進貨 300 單位,單位成本$11        7/31  盤點得知商品實際庫存量為 400 單位\n若 7/5 進貨另有進貨費用$1,000,則有關臺北公司 02 年 7 月底期末存貨之敘述,下列何者正確?", "options": ["存貨成本流動假設若採平均法,不論採永續盤存制或定期盤存制,期末存貨金額均相同", "存貨成本流動假設若採先進先出法,不論採永續盤存制或定期盤存制,期末存貨金額均相同", "在永續盤存制下,存貨成本流動假設若採平均法,期末存貨金額較採先進先出法為高", "在定期盤存制下,存貨成本流動假設若採平均法,其期末存貨金額較採先進先出法為高"], "answer": "C", "figure": null, "official": "官方:永續制下,7/5 因有進貨費用使單價上升(12)轉下跌(11),期末存貨先進先出法 < 移動平均法。", "explain": {"concept": "比較永續盤存制與定期盤存制、先進先出法與平均法的期末存貨金額,並注意進貨費用的處理。", "steps": ["先看進貨費用:官方詳解視為在永續制下計入 7/5 進貨成本(單位成本 $10 + $1,000 ÷ 500 = $12),在定期制下進貨費用另列、不計入單位成本。", "永續制、先進先出:7/26 出售 400 單位先出 7/5 的貨,剩 100@$12 + 300@$11 = $4,500。", "永續制、移動平均:7/5 後單位成本 $12,出售 400 後剩 100@$12 = $1,200,再進 300@$11 = $3,300,合計 $4,500。", "依官方答案 C 為正確,但我自己算永續制先進先出與移動平均都是 $4,500(相等),與官方「先進先出 < 移動平均」的說法不符,因此此題我無法獨立驗證。"], "pitfalls": "進貨費用要不要計入單位成本、永續與定期制的處理方式,是本題的關鍵陷阱。", "distractors": {}}, "check": "python:永續移動平均期末存貨 4,500;永續先進先出 100×12+300×11 = 4,500,兩者相等,與官方 C「先進先出 < 移動平均」不符。", "verified": false, "note": "我獨立算出永續制下先進先出與移動平均期末存貨皆為 $4,500(相等),無法支持官方 C;答案仍依官方為 C。"}, {"id": "110-3-A-21", "exam": "110-3", "paper": "A", "q": 21, "unit": "十三、存貨", "topic": "成本與淨變現價值孰低法", "stem": "高雄公司存貨評價採成本與淨變現價值孰低法,01、02、03 年底相關資料如下:\n\n| | 01 年 | 02 年 | 03 年 |\n|---|---|---|---|\n| 期末存貨成本 | $95,000 | $70,000 | $98,000 |\n| 淨變現價值 | $90,000 | $68,000 | $90,000 |\n\n03 年度調整前銷貨成本為$820,000,試問存貨評價調整後,03 年度銷貨成本和 03 年底備抵存貨跌價應有餘額,下列何者正確?", "options": ["銷貨成本$826,000,備抵存貨跌價$8,000", "銷貨成本$826,000,備抵存貨跌價$6,000", "銷貨成本$828,000,備抵存貨跌價$6,000", "銷貨成本$828,000,備抵存貨跌價$8,000"], "answer": "A", "figure": null, "official": "03 年底備抵存貨跌價 $8,000;應調整銷貨成本 $6,000;銷貨成本 $820,000 + $6,000 = $826,000。", "explain": {"concept": "成本與淨變現價值孰低法:存貨應以較低者表示,差額記入備抵存貨跌價(抵銷存貨)。", "steps": ["每年底的備抵存貨跌價 = 成本 − 淨變現價值(若淨變現價值較低)。01 年:$95,000 − $90,000 = $5,000;02 年:$70,000 − $68,000 = $2,000;03 年:$98,000 − $90,000 = $8,000。", "03 年底備抵存貨跌價餘額應為 $8,000。", "02 年底餘額是 $2,000,03 年要補到 $8,000,所以 03 年要再提列 $8,000 − $2,000 = $6,000(借:銷貨成本 $6,000,貸:備抵存貨跌價 $6,000)。", "03 年度銷貨成本 = $820,000 + $6,000 = $826,000,選 A。"], "pitfalls": "備抵存貨跌價是「餘額」概念,要看與前一年底餘額的差額來調整,不是直接加 $8,000。", "distractors": {"B": "備抵存貨跌價餘額只算 $6,000(把調整數當成餘額)。", "C": "調整數與餘額皆算錯,銷貨成本多加 $8,000 並誤把餘額當 $6,000。", "D": "把 $8,000 直接當成本期調整數,忘記要扣掉上年已有的 $2,000。"}}, "check": "python:820000+(8000−2000) = 826000;備抵 8000,與官方相符。", "verified": true, "note": ""}, {"id": "110-3-A-22", "exam": "110-3", "paper": "A", "q": 22, "unit": "十五、長期營業用資產", "topic": "年數合計法折舊", "stem": "臺北公司於 03 年 7 月 1 日購入一部機器,其提列折舊方法採年數合計法,購買時原始成本$2,300,000,且已知 03 年及 04 年的折舊費用分別為$300,000 及$550,000,則該機器於 06 年折舊為何?", "options": ["$350,000", "$450,000", "$500,000", "$550,000"], "answer": "A", "figure": null, "official": "推得耐用年限 N = 6、殘值 $200,000;06 年折舊 = $350,000。", "explain": {"concept": "年數合計法:每年折舊 = (成本 − 殘值) × 剩餘年數 ÷ 年數合計;不是整年起算時要按月分攤。", "steps": ["設耐用年限 N 年,年數合計 = N(N+1)/2,殘值 S。03 年(7/1~12/31,半年)折舊 = (2,300,000 − S) × N/年數合計 × 6/12 = $300,000 ……①", "04 年折舊 = 第一年後半年 + 第二年前半年 = $550,000,即第二年前半年的部分為 (2,300,000 − S) × (N−1)/年數合計 × 6/12 = $550,000 − $300,000 = $250,000 ……②", "①÷②:N ÷ (N−1) = 300 ÷ 250 = 6/5,得 N = 6,年數合計 = 21。", "代入①:(2,300,000 − S) × 6/21 × 1/2 = $300,000,得 2,300,000 − S = $2,100,000,S = $200,000。", "06 年 = 第三年後半年(剩 4)+ 第四年前半年(剩 3):($2,100,000) × [4×(1/2) + 3×(1/2)] ÷ 21 = $2,100,000 × 3.5 ÷ 21 = $350,000,選 A。"], "pitfalls": "年數合計法的折舊逐年遞減,且因 7/1 購入,每個會計年度折舊橫跨兩個使用年度,要用「半年+半年」計算。", "distractors": {"D": "把 04 年折舊 $550,000 當成 06 年折舊,忽略年數合計法折舊逐年遞減。"}}, "check": "python:N=6,S=200000;(4*.5+3*.5)/21*2100000 = 350000,與官方相符。", "verified": true, "note": ""}, {"id": "110-3-A-23", "exam": "110-3", "paper": "A", "q": 23, "unit": "十五、長期營業用資產", "topic": "定率遞減法與處分", "stem": "高雄公司於 05 年 7 月 1 日購入一部機器成本$160,000,殘值$10,000,即予啟用,估計可使用四年,折舊採用定率遞減法,則 07 年 10 月 1 日將該機器出售,當時承認$55,000 處分不動產廠房設備利益,請問機器出售價格多少?", "options": ["$90,000", "$92,500", "$95,000", "$97,500"], "answer": "A", "figure": null, "official": "折舊率 = 1 − (10,000/160,000)^(1/4) = 0.5;07/10/1 帳面金額 $35,000;售價 = $35,000 + $55,000 = $90,000。", "explain": {"concept": "定率遞減法:折舊率 = 1 −(殘值/成本)^(1/n),每年折舊 = 期初帳面金額 × 折舊率;處分利益 = 售價 − 帳面金額。", "steps": ["折舊率 = 1 − 四次方根(殘值 ÷ 成本) = 1 − 四次方根(10,000 ÷ 160,000) = 1 − 0.5 = 0.5。", "第一個使用年度(05/7/1~06/6/30):折舊 $160,000 × 0.5 = $80,000,帳面金額 $80,000;第二年(06/7/1~07/6/30):折舊 $80,000 × 0.5 = $40,000,07/7/1 帳面金額 $40,000。", "07/7/1 到 10/1 共 3 個月:折舊 = $40,000 × 0.5 × 3/12 = $5,000,07/10/1 帳面金額 = $40,000 − $5,000 = $35,000。", "處分利益 $55,000 = 售價 − 帳面金額,所以售價 = $35,000 + $55,000 = $90,000,選 A。"], "pitfalls": "處分前要先提列到出售日為止的折舊;利益是「售價 − 帳面金額」,所以售價要用「加」。", "distractors": {"C": "漏提 07/7/1~10/1 的 3 個月折舊 $5,000,帳面金額取 $40,000,售價算成 $95,000。"}}, "check": "python:BV(07/10/1)=35000;售價 90000,與官方相符。", "verified": true, "note": ""}, {"id": "110-3-A-24", "exam": "110-3", "paper": "A", "q": 24, "unit": "十五、長期營業用資產", "topic": "年數合計法與倍數餘額遞減法", "stem": "臺北公司 06 年 1 月 1 日購買機器設備,估計耐用年限為四年,無殘值。若採用年數合計法提列折舊,該機器 07 年 12 月 31 日之帳面金額,會比採用倍數餘額遞減法之下的帳面金額多出$25,000。試問該設備之原始帳列成本為何?", "options": ["$200,000", "$240,000", "$360,000", "$500,000"], "answer": "D", "figure": null, "official": "年數合計法 07 年底帳面金額 0.3C;倍數餘額遞減法 0.25C;0.05C = $25,000,C = $500,000。", "explain": {"concept": "比較兩種折舊法兩年後的帳面金額,用設成本為 C 的方程式求解。", "steps": ["設原始成本為 C。年數合計 = 4+3+2+1 = 10。", "年數合計法:第 1 年折舊 C × 4/10,第 2 年折舊 C × 3/10,兩年後帳面金額 = C − C×(4/10) − C×(3/10) = 0.3C。", "倍數餘額遞減法:折舊率 = 2 × 1/4 = 0.5,兩年後帳面金額 = C × (1 − 0.5) × (1 − 0.5) = 0.25C。", "帳面金額差 = 0.3C − 0.25C = 0.05C = $25,000。", "C = $25,000 ÷ 0.05 = $500,000,選 D。"], "pitfalls": "倍數餘額遞減法的折舊率是直線法的兩倍(這題 50%),且不先扣殘值(本題殘值 0)。", "distractors": {}}, "check": "python:0.3C − 0.25C = 25000 → C = 500000,與官方相符。", "verified": true, "note": ""}, {"id": "110-4-A-01", "exam": "110-4", "paper": "A", "q": 1, "unit": "一、會計基本概念", "topic": "會計資訊使用者與準則", "stem": "有關會計基本概念之敘述,下列何者錯誤?", "options": ["會計資訊之內部使用者包括管理階層、董事、監察人及企業一般員工", "公司係採公司會計並以營利為目的,依公司法組織之社團法人", "會計是一門專業的知識與技能,企業若需要外部人員執行記帳業務,可委由會計師、記帳士等專業人員協助", "行政院金融監督管理委員會為金融服務業之主管機關,認可並發布「國際財務報導準則(IFRSs)正體中文版」"], "answer": "A", "figure": null, "official": "企業一般員工為會計資訊之「外部」使用者。", "explain": {"concept": "會計資訊使用者分成內部(管理階層、董事、監察人)與外部(投資人、債權人、政府、一般員工等)。", "steps": ["先把使用者分成兩類:能直接取得公司內部資料、參與經營決策的是內部使用者;只能看公司對外公布報表的是外部使用者。", "管理階層、董事、監察人參與公司經營與監督,屬內部使用者。", "一般員工只能透過公布的財務報表了解公司,所以是外部使用者,因此(A)把一般員工放進內部使用者是錯的。", "(B)(C)(D)都是正確的常識敘述,所以本題選(A)。"], "pitfalls": "容易把「員工」想成公司裡的人就是內部使用者,其實判斷標準是能不能參與經營決策。", "distractors": {"B": "公司是社團法人、以營利為目的,敘述正確。", "C": "會計師、記帳士可受託處理帳務,敘述正確。", "D": "金管會為主管機關並認可發布 IFRSs,敘述正確。"}}, "check": "概念題,與官方詳解及會計常識一致。", "verified": true, "note": ""}, {"id": "110-4-A-02", "exam": "110-4", "paper": "A", "q": 2, "unit": "二、會計循環及會計帳簿", "topic": "統一發票與原始憑證", "stem": "漢斯視聽器材公司的傳票制度採複式傳票三分法,因賒銷而留存一張三聯式統一發票之存根聯,部份資料如圖(一)。請判斷下列敘述何者錯誤?", "options": ["三聯式統一發票為原始憑證,可證明交易的發生", "本張三聯式統一發票為對外憑證,原則上買受人應為非營業人", "會計人員可根據本張三聯式統一發票,製作一張轉帳傳票", "本張發票之營業稅應為 $2,100×5%=$105"], "answer": "B", "figure": "figs/110-4-A-q02.png", "official": "三聯式統一發票之買受人原則上應為「營業人」。", "explain": {"concept": "三聯式統一發票是開給營業人的(買受人可扣抵進項稅額),二聯式才是開給非營業人;發票是原始憑證,賒銷用轉帳傳票。", "steps": ["先看圖:發票品名為音響 1 組,金額 $2,100,營業稅欄勾選「應稅」。這是漢斯公司賣出商品所開立、留存存根聯。", "(A)發票是證明交易發生的原始憑證,正確。", "(B)三聯式統一發票的買受人原則上是營業人(對方可憑第二聯扣抵進項稅額);非營業人通常開二聯式。所以(B)敘述錯誤。", "(C)本題是賒銷(無現金收付),應作成轉帳傳票,正確。", "(D)金額 $2,100 為銷售額(未稅),營業稅 5%=$105,正確。"], "pitfalls": "三聯式與二聯式的買受人對象容易搞混:三聯式給營業人,二聯式給非營業人。", "distractors": {"A": "發票確為原始憑證,敘述正確。", "C": "賒銷無現金收付,製作轉帳傳票正確。", "D": "稅額 $2,100×5%=$105,算式正確。"}}, "check": "營業稅 2,100×5%=105,與(D)相符;其餘為概念題,與官方詳解一致。", "verified": true, "note": ""}, {"id": "110-4-A-03", "exam": "110-4", "paper": "A", "q": 3, "unit": "三、會計基本法則", "topic": "借貸法則與交易影響", "stem": "根據借貸法則,判斷下列敘述何者正確?", "options": ["企業收回先前溢付的保險費,會使資產增加,收益增加", "企業與銀行簽訂透支契約,會使資產增加,負債增加", "企業於期末時提列機器折舊,會使費損增加,負債增加", "業主簽發六十天期本票以償還商店債務,會使權益增加,負債減少"], "answer": "D", "figure": null, "official": "(A)資產增加,費損減少;(B)簽訂契約並非交易事項,不影響會計要素;(C)費損增加,資產減少。", "explain": {"concept": "判斷每個交易對資產、負債、權益、收益、費損的影響方向。", "steps": ["(A)先前溢付保險費記為費損(借),收回時借:現金,貸:保險費,所以是資產增加、費損減少,不是收益增加。", "(B)簽訂透支契約只是雙方約定,還沒有資金流動,不是會計上的交易,不影響任何要素。", "(C)提列折舊:借:折舊費用,貸:累計折舊(資產抵減),所以是費損增加、資產減少。", "(D)業主以個人簽發的本票替企業還債:借:應付帳款(負債減少),貸:業主資本(權益增加)。所以選(D)。"], "pitfalls": "契約簽訂、訂貨等不是會計交易;累計折舊是資產的減項,不是負債。", "distractors": {"A": "把退回的保險費當成收益,其實是沖減原本的費損。", "B": "誤把簽約當成交易。", "C": "把累計折舊當成負債,其實是資產的減項。"}}, "check": "概念題,以借貸分錄逐項推演,與官方詳解一致。", "verified": true, "note": ""}, {"id": "110-4-A-04", "exam": "110-4", "paper": "A", "q": 4, "unit": "一、會計基本概念", "topic": "會計基本假設", "stem": "有關會計基本假設,下列敘述何者錯誤?", "options": ["基於「企業個體假設」,若業主從企業提取資金以供自用,企業必須借記業主往來", "基於「貨幣評價假設」,企業需估計員工士氣可能為企業帶來之收入金額,並認列入帳", "基於「權責發生基礎」,期末時企業應作調整分錄,以計算當期正確之收益與費損", "基於「繼續經營假設」,不動產、廠房及設備應以其帳面金額列示於資產負債表"], "answer": "B", "figure": null, "official": "基於「貨幣評價假設」,員工士氣不入帳。", "explain": {"concept": "貨幣評價假設:只有能以貨幣衡量的事項才入帳。", "steps": ["貨幣評價假設是指會計只記錄可以用貨幣客觀衡量的交易事項。", "員工士氣、企業形象等無法以貨幣客觀衡量,不能入帳,所以(B)錯誤。", "(A)企業與業主分開,業主提款記業主往來(借),正確。", "(C)權責發生基礎要求期末調整,正確。", "(D)繼續經營下,資產以帳面金額(成本減折舊)列示,而非清算價值,正確。"], "pitfalls": "士氣、商譽(自創)等無法客觀衡量,不能硬估計入帳。", "distractors": {"A": "業主提取資金,企業借記業主往來,正確。", "C": "期末調整是權責基礎的結果,正確。", "D": "繼續經營假設下資產用帳面金額表達,正確。"}}, "check": "概念題,與官方詳解及會計基本假設一致。", "verified": true, "note": ""}, {"id": "110-4-A-05", "exam": "110-4", "paper": "A", "q": 5, "unit": "五、過帳與分類帳", "topic": "日記簿與分類帳", "stem": "有關分錄及過帳之敘述,下列何者正確?", "options": ["日記簿是過帳的依據,分類帳則是分錄的依據", "日記簿是以會計項目為記錄主體,分類帳是以交易為記錄主體", "若想瞭解企業每個客戶的應收帳款狀況,可查詢應收帳款明細分類帳", "日記簿中設置日頁欄,可避免重複或遺漏過帳"], "answer": "C", "figure": null, "official": "(A)分類帳是分錄過帳後的「結果」,「傳票」才是分錄的依據;(B)日記簿以「交易」為記錄主體,分類帳以「第四級會計項目」為記錄主體;(D)日記簿中設置「類頁欄」。", "explain": {"concept": "日記簿(依時間順序記交易)與分類帳(依科目分類彙總)的差別。", "steps": ["流程是:憑證→傳票→日記簿(分錄)→分類帳(過帳)。所以分錄的依據是傳票,過帳的依據是日記簿,(A)顛倒了。", "日記簿以「交易」為記錄主體,分類帳以「會計項目」為記錄主體,(B)顛倒了。", "明細分類帳記錄每位客戶的應收帳款,(C)正確。", "避免重複或遺漏過帳的是日記簿的「類頁欄」(記載過入分類帳的頁次),不是「日頁欄」,(D)錯誤。"], "pitfalls": "類頁欄與日頁欄的名稱容易記反。", "distractors": {"A": "把日記簿與分類帳的先後順序及依據顛倒。", "B": "把兩種帳簿的記錄主體顛倒。", "D": "過帳核對用的是類頁欄,不是日頁欄。"}}, "check": "概念題,與官方詳解一致。", "verified": true, "note": ""}, {"id": "110-4-A-06", "exam": "110-4", "paper": "A", "q": 6, "unit": "二、會計循環及會計帳簿", "topic": "會計循環與帳簿憑證", "stem": "下列敘述何者正確?\n①「會計循環」是指會計處理程序自分錄、過帳、試算、調整、結帳、編表之循環\n②「營業循環」是指營業活動中自投入現金購買商品、將商品出售,再收回現金之循環\n③依商業會計法規定,企業必須設置的會計帳簿為普通序時帳簿及特種序時帳簿\n④依商業會計法規定,各項會計憑證及會計帳簿皆需至少保存 10 年\n⑤企業現付電話費 $3,000,其中三分之一應由業主負擔,此交易為現金交易\n⑥業主支付租金 $10,000,其中半數應由企業負擔,此交易為混合交易", "options": ["①②⑤", "①②⑥", "①③⑤", "②④⑥"], "answer": "A", "figure": null, "official": "③依商業會計法規定,必須設置的帳簿為普通序時帳簿及「總分類帳簿」;④會計憑證至少保存 5 年,會計帳簿需至少保存 10 年;⑥分錄為「借:租金支出 $5,000,貸:業主往來 $5,000」,為轉帳交易。", "explain": {"concept": "會計循環、營業循環、必設帳簿、保存年限與交易種類的判斷。", "steps": ["①會計循環是分錄、過帳、試算、調整、結帳、編表,正確。", "②營業循環是現金→商品→應收→現金的循環,正確。", "③必須設置的是普通序時帳簿與總分類帳簿(特種序時帳簿是選擇設置),所以③錯。", "④憑證至少保存 5 年、帳簿至少保存 10 年,④說「皆 10 年」錯。", "⑤企業付現 $3,000,分錄為借:電話費 $2,000、借:業主往來 $1,000,貸:現金 $3,000,貸方全為現金,屬現金交易,⑤正確。", "⑥業主以個人資金替企業付租金,借:租金支出,貸:業主往來,沒有現金收付,屬轉帳交易,不是混合交易,⑥錯。因此①②⑤正確,選(A)。"], "pitfalls": "現金交易、轉帳交易、混合交易是看有沒有現金收付:全部有現金→現金交易;全部沒有→轉帳交易;部分有→混合交易。", "distractors": {"B": "誤以為⑥是混合交易,其實全程沒有現金,是轉帳交易。", "C": "誤把特種序時帳簿當成必設帳簿。", "D": "誤以為憑證與帳簿皆保存 10 年。"}}, "check": "概念題,與官方詳解及商業會計法保存年限規定(憑證 5 年、帳簿 10 年)雙重確認。", "verified": true, "note": ""}, {"id": "110-4-A-07", "exam": "110-4", "paper": "A", "q": 7, "unit": "六、試算與試算表", "topic": "試算表錯誤更正", "stem": "小樺公司餘額式試算表不平衡,更正前貸方合計為 $5,000,經查明其原因如下:\n①現購商品 $1,500,漏未入帳\n②水電瓦斯費借方金額重複過帳 $2,000\n③客戶償還帳款 $3,600,公司過帳時貸方誤記為 $6,300\n試判斷下列敘述何者正確?", "options": ["更正錯誤前,借方合計為 $5,700", "更正錯誤前,借方合計為 $4,700", "正確之貸方合計為 $7,700", "正確之借方合計為 $5,000"], "answer": "D", "figure": null, "official": "更正試算表如下,可知正確之借貸方合計皆為 $5,000;更正錯誤前,借方合計為 $4,300。", "explain": {"concept": "試算表不平衡時,逐項判斷每個錯誤對借方、貸方合計的影響,再調整到兩邊相等。", "steps": ["設更正前借方合計為 D,貸方合計為 $5,000。", "①現購商品漏未入帳:借(購貨)與貸(現金)都漏記,更正後借貸各加 $1,500。", "②水電瓦斯費借方重複過帳 $2,000:借方多了 $2,000,更正後借方減 $2,000。", "③貸方應為 $3,600 卻記 $6,300:貸方多了 $2,700,更正後貸方減 $2,700。", "官方解答認定正確借貸合計為 $5,000、更正前借方為 $4,300,所以選(D)。(本題官方的調整表與一般算法有出入,詳見備註。)"], "pitfalls": "遇到「漏記」要看是借貸兩邊都漏,還是只漏一邊,會影響不平衡金額。", "distractors": {"A": "借方更正前金額算錯,官方為 $4,300。", "B": "借方更正前金額算錯,官方為 $4,300。", "C": "正確貸方合計不是 $7,700。"}}, "check": "我獨立依題意推算:借方 D+1,500-2,000,貸方 5,000+1,500-2,700=3,800,平衡時 D=4,300、正確合計為 $3,800,與官方 $5,000 不符。", "verified": false, "note": "官方答案 D(正確借方合計 $5,000)。我獨立推算正確合計為 $3,800(更正前借方 $4,300 與官方相同),四個選項皆不成立,疑似官方調整表另有解讀或題目有瑕疵,請人工確認。answer 依官方。"}, {"id": "110-4-A-08", "exam": "110-4", "paper": "A", "q": 8, "unit": "七、調整", "topic": "預付保險費調整", "stem": "阿信公司每季編製財務報表,在民國 110 年中購買一張一年期保單,在 111 年 3 月 31 日作完調整分錄後,保險費餘額為 $600,預付保險費餘額為 $1,200,請問阿信公司在 110 年中的哪一天購買保單?", "options": ["8 月 1 日", "9 月 1 日", "10 月 1 日", "12 月 1 日"], "answer": "C", "figure": null, "official": "每個月保險費 $600÷3(111 年 1-3 月)=$200,由預付保險費 $1,200 知未耗用保險費尚餘 $1,200÷$200=6 個月,表示 111 年 9 月 30 日保單到期。因保單為一年期,故阿信公司係於 110 年 10 月 1 日購買保單。", "explain": {"concept": "預付保險費餘額代表還沒用掉的月數;保險費餘額代表今年已用掉的月數。", "steps": ["先算每月保費:111 年只有 1~3 月共 3 個月被耗用,保險費餘額 $600,所以每月 $600÷3=$200。", "再算還沒用的月數:預付保險費 $1,200÷$200=6 個月。", "3 月 31 日再過 6 個月,保單到期日為 9 月 30 日。", "保單為一年期,到期日 111 年 9 月 30 日往前推一年,起保日是 110 年 10 月 1 日,選(C)。"], "pitfalls": "只看餘額容易忘記要用「保險費餘額只含 111 年 1~3 月」來求月保費,而不是全年。", "distractors": {"A": "推算起保日時月數算錯。", "B": "推算起保日時月數算錯。", "D": "推算起保日時月數算錯。"}}, "check": "600/3=200;1,200/200=6 個月;3/31 加 6 個月=9/30,減一年後起保日 10/1,與官方一致。", "verified": true, "note": ""}, {"id": "110-4-A-09", "exam": "110-4", "paper": "A", "q": 9, "unit": "十五、長期營業用資產", "topic": "折舊會計估計變動", "stem": "阿榮公司於 X1 年初購入一機器設備,成本 $300,000,估計可用 5 年,無殘值,採年數合計法提列折舊。試問下列敘述何者錯誤?", "options": ["X2 年初重新估計,發現該機器尚可使用 5 年,殘值 $50,000,則 X2 年之折舊額=$50,000", "X3 年初重新估計,發現該機器總耐用年限應為 6 年,則 X3 年之折舊額=$48,000", "X3 年底調整前,公司決定改用定率遞減法提列折舊,殘值 $15,000,則 X4 年之折舊額=$60,000", "X4 年底調整前,公司決定改用倍數餘額遞減法,耐用年限比原估計耐用年限多了 4 年,則 X4 年之折舊額=$20,000"], "answer": "C", "figure": null, "official": "(C)X3 年底調整前帳面金額 $120,000,剩餘年限 3 年、殘值 $15,000,定率=1-(15,000/120,000)開三次方=50%,X3 年折舊 $60,000,X4 年折舊=($120,000-$60,000)×50%=$30,000。", "explain": {"concept": "折舊方法或估計變動屬會計估計變動,採「未來適用」:以當時帳面金額、剩餘年限、新殘值重算。", "steps": ["年數合計法第 1~5 年折舊率為 5/15、4/15、3/15、2/15、1/15。", "(A)X2 年初帳面金額=$300,000×(1-5/15)=$200,000,剩餘 5 年、殘值 $50,000,X2 折舊=($200,000-$50,000)×5/15=$50,000,正確。", "(B)X3 年初帳面金額=$300,000×(1-5/15-4/15)=$120,000,總年限 6 年,已用 2 年,剩餘 4 年,折舊=$120,000×4/10=$48,000,正確。", "(C)X3 年初帳面金額 $120,000,改用定率遞減法,剩餘 3 年、殘值 $15,000,折舊率=1-(15,000÷120,000)^(1/3)=1-1/2=50%。X3 年折舊=$120,000×50%=$60,000;X4 年折舊=($120,000-$60,000)×50%=$30,000,不是 $60,000,所以(C)錯誤。", "(D)X4 年初帳面金額=$300,000×(1-12/15)=$60,000,剩餘年限 2+4=6 年,倍數餘額遞減法折舊率=2/6=1/3,折舊=$60,000×1/3=$20,000,正確。"], "pitfalls": "(C)容易把 X3 年的折舊 $60,000 誤當成 X4 年的折舊;定率遞減法每年都用「當年初帳面金額」乘折舊率。", "distractors": {"A": "此選項計算正確,不是錯誤選項。", "B": "此選項計算正確,不是錯誤選項。", "D": "此選項計算正確,不是錯誤選項。"}}, "check": "python 驗算:300000*(1-5/15-4/15)=120000;120000*4/10=48000;1-(15000/120000)^(1/3)=0.5;X4=(120000-60000)*0.5=30000;60000*2/6=20000。與官方一致。", "verified": true, "note": ""}, {"id": "110-4-A-10", "exam": "110-4", "paper": "A", "q": 10, "unit": "八、結帳", "topic": "結帳與結帳後試算表", "stem": "有關結帳之敘述,下列何者錯誤?", "options": ["本期損益此一會計項目為結帳時專用,平時並無此項目記錄", "若獨資企業發生淨利,結帳時應借記本期損益、貸記業主往來", "結帳分錄須登入日記簿,並進行過帳", "結帳後試算表的內容應包含實帳戶及虛帳戶"], "answer": "D", "figure": null, "official": "結帳會結清虛帳戶,故結帳後試算表只會列示實帳戶。", "explain": {"concept": "結帳是把虛帳戶(收益、費損)結清轉入權益,所以結帳後只剩實帳戶。", "steps": ["(A)本期損益是結帳專用的暫時性科目,正確。", "(B)獨資淨利:借:本期損益,貸:業主往來(或業主資本),正確。", "(C)結帳分錄要登日記簿並過帳,正確。", "(D)結帳時虛帳戶餘額都已結清為零,所以結帳後試算表只有實帳戶(資產、負債、權益),不含虛帳戶,(D)錯誤。"], "pitfalls": "把「結帳前試算表」與「結帳後試算表」混淆。", "distractors": {"A": "本期損益確為結帳專用科目,敘述正確。", "B": "獨資淨利之結轉分錄正確。", "C": "結帳分錄需入日記簿並過帳,正確。"}}, "check": "概念題,與官方詳解一致。", "verified": true, "note": ""}, {"id": "110-4-A-11", "exam": "110-4", "paper": "A", "q": 11, "unit": "十、加值型營業稅會計實務", "topic": "零稅率與免稅", "stem": "有關加值型營業稅之「零稅率」與「免稅」之規定,下列何者正確?", "options": ["外銷貨物適用零稅率規定,且進項稅額可扣抵,故可獲得完全免稅", "外銷貨物適用免稅規定,且進項稅額可扣抵,故可獲得完全免稅", "零稅率的銷項稅額為零,但進項稅額不可扣抵", "免稅之銷項稅額為零,且進項稅額可以扣抵"], "answer": "A", "figure": null, "official": "(B)外銷貨物適用「零稅率」規定;(C)零稅率的銷項稅額為零,「且進項稅額可以扣抵」;(D)免稅係指銷售貨物或勞務在銷售階段時免徵營業稅,但進項稅額不可扣抵。", "explain": {"concept": "零稅率:銷項稅額為零且進項稅額可扣抵(可退稅),稱完全免稅;免稅:銷項為零但進項不可扣抵。", "steps": ["外銷貨物適用零稅率(不是免稅),(B)錯。", "零稅率:銷項稅額 0,而且進項稅額可以扣抵(可申請退稅),整條供應鏈的稅都不用負擔,所以是「完全免稅」,(A)正確。", "(C)說零稅率進項不可扣抵,錯。", "(D)免稅的進項稅額不可扣抵,所以不是完全免稅,(D)錯。"], "pitfalls": "零稅率與免稅名稱相似,差別在進項稅額能不能扣抵。", "distractors": {"B": "外銷是零稅率,不是免稅。", "C": "零稅率進項稅額可以扣抵。", "D": "免稅的進項稅額不可扣抵。"}}, "check": "概念題,與官方詳解及營業稅法常識一致。", "verified": true, "note": ""}, {"id": "110-4-A-12", "exam": "110-4", "paper": "A", "q": 12, "unit": "十一、現金及內部控制", "topic": "零用金與內部控制", "stem": "下列敘述何者正確?", "options": ["為達到職能分工,應付帳款及應收帳款之帳務應由不同會計人員負責", "在公司設有定額零用金制度下,若以零用金支付計程車費時,應貸記零用金", "存入客戶的支票因存款不足遭退票時,公司分錄應借記「應收票據」", "定額預付制的零用金制度,報銷費用並補充撥補零用金時,零用金之帳戶餘額不變"], "answer": "D", "figure": null, "official": "(A)管帳不管錢,管錢不管帳。帳務處理可由同一人負責;(B)以零用金支付費用時,不需作分錄;(C)存入客戶的支票因存款不足遭退票時,公司應借記「應收帳款」。", "explain": {"concept": "定額零用金制度:帳上零用金餘額固定不變,只在撥補時才有分錄。", "steps": ["內部控制的職能分工重點是「管帳的不管錢、管錢的不管帳」,應收、應付帳款帳務可由同一人處理,(A)錯。", "定額制下,動用零用金支付費用時只在零用金支出表登記,不作分錄,(B)錯。", "客戶支票退票,表示原來的應收帳款沒收到錢,應借記應收帳款、貸記銀行存款,(C)錯。", "定額制撥補時:借:各項費用,貸:現金,零用金帳戶餘額維持固定金額不變,(D)正確。"], "pitfalls": "定額制與非定額制的差別:定額制帳上零用金餘額固定、撥補時才作費用分錄。", "distractors": {"A": "職能分工是指管錢與管帳分開,不是應收與應付要分開。", "B": "定額制支付時不作分錄。", "C": "退票應借記應收帳款,不是應收票據。"}}, "check": "概念題,與官方詳解一致。", "verified": true, "note": ""}, {"id": "110-4-A-13", "exam": "110-4", "paper": "A", "q": 13, "unit": "十一、現金及內部控制", "topic": "銀行存款調節表", "stem": "阿統公司 X1 年 5 月 31 日銀行存款之帳面餘額為 $500,000,已知帳列存款餘額與對帳單差異如下:\n①5 月 23 日公司存入現金 $46,000,銀行誤記為 $64,000\n②存款利息 $2,000,銀行於 5 月 31 日入帳,公司尚未入帳\n③公司於 5 月 31 日存入即期支票一張 $70,000,銀行尚未入帳\n④公司委請銀行代收票據 $50,000,銀行已於 5 月 29 日收訖,但公司尚未入帳\n⑤公司已開立但尚未兌現支票計有 $60,000(其中包含保付支票 $15,000,及 4 月份開立至本月份尚未兌現金額 $25,000 之支票)\n根據上述資料,請問下列敘述何者正確?", "options": ["5 月 31 日正確之銀行存款餘額為 $548,000", "5 月 31 日正確之銀行存款餘額為 $552,000", "5 月 31 日銀行對帳單之存款餘額為 $509,000", "5 月 31 日銀行對帳單之存款餘額為 $520,000"], "answer": "B", "figure": null, "official": "公司帳面 $500,000 +$2,000 +$50,000=$552,000;銀行對帳單 $545,000 -$18,000 +$70,000 -$45,000=$552,000。", "explain": {"concept": "銀行存款調節表:公司帳面與銀行對帳單各自調整到「正確餘額」,兩邊應相等。", "steps": ["先調整公司帳面:利息 $2,000 公司尚未入帳→加;代收票據 $50,000 銀行已收、公司尚未入帳→加。", "公司正確餘額=$500,000+$2,000+$50,000=$552,000,所以(A)錯、(B)對。", "再調整銀行對帳單(設為 X):銀行誤多記 $64,000-$46,000=$18,000→減;在途存款 $70,000→加;未兌現支票要扣的只有一般支票,保付支票銀行已先扣款,所以 $60,000-$15,000=$45,000→減。", "X-$18,000+$70,000-$45,000=$552,000,得 X=$545,000,所以(C)(D)皆錯。"], "pitfalls": "保付支票(開票時銀行已先從存款扣款)不屬於未兌現支票,不可再扣一次。", "distractors": {"A": "可能少加某一項調整,例如漏掉代收票據或利息。", "C": "對帳單餘額推算錯誤,正確為 $545,000。", "D": "對帳單餘額推算錯誤,正確為 $545,000。"}}, "check": "python:500000+2000+50000=552000;545000-18000+70000-45000=552000,與官方一致。", "verified": true, "note": ""}, {"id": "110-4-A-14", "exam": "110-4", "paper": "A", "q": 14, "unit": "十二、應收款項", "topic": "銷貨折扣與淨額法(IFRS 15)", "stem": "大大公司賒銷商品一批,定價 $500,000,以八折優惠成交,付款條件為 4/10,1/20,n/30。若採 IFRS 15 淨有權取對價認列銷貨,請問下列敘述何者錯誤?", "options": ["若銷貨條件為起運點交貨,由賣方墊付運費,該運費大大公司應借記「應收帳款」", "若銷貨條件為目的地交貨,由賣方支付運費,該運費大大公司應借記「運費」", "若客戶在第 15 天償還全部貨款,大大公司應貸記「銷貨收入 $4,000」", "若客戶在第 25 天償還全部貨款,且一年以 360 天計,折扣之隱含利率為 100%"], "answer": "C", "figure": null, "official": "成交價=$500,000×0.8=$400,000;客戶在第 15 天還款,有未享折扣共計 $400,000×(4%-1%)=$12,000,故公司應貸記「銷貨收入 $12,000」。", "explain": {"concept": "IFRS 15 淨有權取對價法:先以「最大折扣後金額」認列銷貨,客戶未享的折扣再補認銷貨收入。", "steps": ["成交價=$500,000×80%=$400,000。淨額法先按最大折扣 4% 入帳:銷貨收入=$400,000×96%=$384,000。", "客戶第 15 天付款,屬 1/20 折扣期間,實際只享 1% 折扣,多付的部分是未享折扣=$400,000×(4%-1%)=$12,000,應貸記銷貨收入 $12,000,所以(C)的 $4,000 錯。", "(A)起運點交貨,賣方墊付運費應借記應收帳款(向買方代墊),正確。", "(B)目的地交貨,運費由賣方負擔,借記運費,正確。", "(D)第 25 天付款(超過 10 天折扣期 15 天):每 $96 的貨款多付 $4,隱含利率=$4÷$96×360÷15=100%,正確。"], "pitfalls": "$4,000 是 $400,000×1% 的折扣金額,容易誤以為是補認收入;實際補認的是未享折扣 4%-1%=3%。", "distractors": {"A": "起運點交貨運費由買方負擔,賣方代墊記應收帳款,正確。", "B": "目的地交貨運費由賣方負擔,記運費,正確。", "D": "隱含利率 4/96×360/15=100%,正確。"}}, "check": "python:400000*(4%-1%)=12000;96*r*15/360=4 得 r=100%。與官方一致。", "verified": true, "note": ""}, {"id": "110-4-A-15", "exam": "110-4", "paper": "A", "q": 15, "unit": "十二、應收款項", "topic": "不附息票據貼現", "stem": "小測公司 5 月 1 日銷售商品收到客戶六個月期面額 $200,000 的不附息票據,公司於 7 月 1 日持向銀行貼現,貼現率為年息 6%,到期時付款人如期償還。試問下列敘述何者正確?", "options": ["到期值 $206,000", "貼現息 $2,000", "貼現金額 $198,000", "貼現日應認列應收票據貼現負債折價 $4,000"], "answer": "D", "figure": null, "official": "不附息票據之到期值為面額 $200,000;貼現息=$200,000×6%×(4/12)=$4,000;貼現金額=$200,000-$4,000=$196,000;應收票據貼現負債折價=貼現息=$4,000。", "explain": {"concept": "不附息票據:到期值=面額;貼現息=到期值×貼現率×貼現期間。", "steps": ["票據 5/1 簽發、六個月期,11/1 到期。7/1 貼現,到銀行到期還有 7/1→11/1 共 4 個月。", "不附息票據到期值=面額=$200,000,(A)錯。", "貼現息=$200,000×6%×4/12=$4,000,(B)的 $2,000 錯。", "貼現金額=$200,000-$4,000=$196,000,(C)錯。", "貼現時帳列:借:銀行存款 $196,000,借:應收票據貼現負債折價 $4,000,貸:應收票據貼現 $200,000,所以(D)正確。"], "pitfalls": "貼現期間是「貼現日到到期日」,不是整張票據的期間。", "distractors": {"A": "把票據誤當附息票據算出到期值。", "B": "貼現期間誤用 2 個月。", "C": "貼現期間誤用 2 個月或扣錯貼現息。"}}, "check": "python:200000*0.06*4/12=4000;200000-4000=196000,與官方一致。", "verified": true, "note": ""}, {"id": "110-4-A-16", "exam": "110-4", "paper": "A", "q": 16, "unit": "十三、存貨", "topic": "存貨錯誤對盈餘的影響", "stem": "小小公司 2020 年與 2021 年列報之本期淨利分別為 $80,000 及 $95,000,2022 年初公司發現 2020 年及 2021 年底的存貨分別低估 $12,500 及 $20,500。請問下列敘述何者錯誤?", "options": ["小小公司 2020 年正確的本期淨利為 $92,500", "小小公司 2021 年正確的本期淨利為 $103,000", "小小公司 2020 年底之保留盈餘低估 $12,500", "小小公司 2021 年底之保留盈餘低估 $8,000"], "answer": "D", "figure": null, "official": "2020 年的存貨錯誤不影響 2021 年底之保留盈餘(錯誤至第二年底結帳後已自動抵銷)。僅 2021 年底之存貨低估 $20,500 導致 2021 年底之保留盈餘低估 $20,500。", "explain": {"concept": "期末存貨低估→銷貨成本高估→當年淨利低估;錯誤到下年度會自動抵銷。", "steps": ["2020 年底存貨低估 $12,500→2020 淨利低估 $12,500,正確淨利=$80,000+$12,500=$92,500,(A)正確。", "2021 年:期初存貨(2020 年底)低估 $12,500→成本低估→淨利高估 $12,500;期末存貨低估 $20,500→淨利低估 $20,500;淨影響=低估 $8,000,正確淨利=$95,000+$8,000=$103,000,(B)正確。", "2020 年底保留盈餘低估 $12,500,(C)正確。", "2021 年底:累積來看,2020 的錯誤已被 2021 抵銷,只剩 2021 年底存貨低估 $20,500,所以保留盈餘低估 $20,500,不是 $8,000,(D)錯誤。"], "pitfalls": "把 2021 年「當年淨利」低估 $8,000 與「年底保留盈餘」低估 $20,500 混為一談。", "distractors": {"A": "此選項正確,92,500=80,000+12,500。", "B": "此選項正確,103,000=95,000+8,000。", "C": "此選項正確。"}}, "check": "python:80000+12500=92500;95000+(20500-12500)=103000;2021 年底保留盈餘低估=20500。與官方一致。", "verified": true, "note": ""}, {"id": "110-4-A-17", "exam": "110-4", "paper": "A", "q": 17, "unit": "十三、存貨", "topic": "進貨漏記對報表影響", "stem": "公司年底漏記一筆起運點交貨之賒購進貨,年底盤點時亦未將該商品列入當年度之期末存貨中,且該公司年底權益總額大於 0,則此項錯誤可能導致的影響為何?", "options": ["不影響當年底負債比率", "不影響當年度銷貨成本", "低估當年底營運資金", "高估當年底保留盈餘"], "answer": "B", "figure": null, "official": "漏記進貨會使進貨(營業成本)少計、應付帳款(流動負債)少計;年底盤點亦未將商品列入期末存貨,會使期末存貨(流動資產)少計及營業成本多計。兩者抵銷,營業成本不受影響。", "explain": {"concept": "進貨漏記且期末存貨漏列(同金額),銷貨成本=期初+進貨-期末存貨,兩個錯誤互相抵銷。", "steps": ["起運點交貨:貨物一裝運,所有權就歸買方,所以年底前該商品已是公司的。", "漏記進貨:進貨少 X、應付帳款(負債)少 X。", "漏列期末存貨:期末存貨(資產)少 X。", "銷貨成本=期初存貨+進貨-期末存貨;進貨少 X、期末存貨少 X,相抵,所以銷貨成本不變,淨利與保留盈餘也不變,(B)正確。", "負債少計→負債比率被低估,(A)錯;流動資產與流動負債同時少 X,營運資金(流動資產-流動負債)不變,(C)錯;保留盈餘不受影響,(D)錯。"], "pitfalls": "容易忘記漏記的進貨同時少了「負債」與「存貨」,營運資金反而不變。", "distractors": {"A": "負債少計會使負債比率被低估,不是不受影響。", "C": "流動資產與流動負債同減 X,營運資金不變。", "D": "淨利不變,保留盈餘不會被高估。"}}, "check": "概念題,以會計恆等式與銷貨成本公式推演,與官方詳解一致。", "verified": true, "note": ""}, {"id": "110-4-A-18", "exam": "110-4", "paper": "A", "q": 18, "unit": "十四、證券投資", "topic": "FVTPL 金融資產評價", "stem": "小豪公司擁有之「透過損益按公允價值衡量之金融資產」資料如下:\n\n| 股票種類 | 01 年購入成本 | 01 年收到現金股利 | 01 年底公允價值 | 02 年底公允價值 |\n|---|---|---|---|---|\n| 日陽公司 | $30,000 | $1,000 | $25,000 | $36,000 |\n| 東昇公司 | (甲) | $1,000 | $40,000 | (乙) |\n\n01 年底時,期末衡量分錄借記「強制透過損益按公允價值衡量之金融資產評價調整 $8,000」;02 年底調整後,「強制透過損益按公允價值衡量之金融資產評價調整」帳戶餘額為貸餘 $2,000,試問下列敘述何者正確?", "options": ["01 年購入東昇公司股票之成本(甲)=$43,000", "01 年購入東昇公司股票之成本(甲)=$25,000", "02 年底持有東昇公司股票之公允價值(乙)=$19,000", "02 年底持有東昇公司股票之公允價值(乙)=$27,000"], "answer": "C", "figure": null, "official": "(甲)=$25,000+$40,000-$8,000-$30,000=$27,000;(乙):$36,000+(乙)=$30,000+$27,000-$2,000,故(乙)=$19,000。", "explain": {"concept": "評價調整=期末公允價值總額-成本總額;借餘表示公允價值高於成本,貸餘表示低於成本。", "steps": ["01 年底公允價值合計=$25,000+$40,000=$65,000;評價調整借餘 $8,000,表示成本合計=$65,000-$8,000=$57,000。", "成本合計=日陽 $30,000+東昇(甲),故(甲)=$57,000-$30,000=$27,000,所以(A)(B)錯。", "02 年底評價調整貸餘 $2,000,表示公允價值合計=成本合計-$2,000=$57,000-$2,000=$55,000。", "日陽 02 年底公允價值 $36,000,所以東昇(乙)=$55,000-$36,000=$19,000,(C)正確、(D)錯。"], "pitfalls": "現金股利是收入,不影響成本與評價調整;評價調整借餘/貸餘的方向不要弄反。", "distractors": {"A": "成本計算時加減方向錯誤。", "B": "把 01 年底公允價值 $25,000 誤當成成本。", "D": "誤將(甲)=$27,000 當成(乙)。"}}, "check": "python:25000+40000-8000-30000=27000;(57000-2000)-36000=19000,與官方一致。", "verified": true, "note": ""}, {"id": "110-4-A-19", "exam": "110-4", "paper": "A", "q": 19, "unit": "十五、長期營業用資產", "topic": "取得成本比較(折扣、現值)", "stem": "小惠公司欲購買機器一組,共有四家機器廠商提供不同購買方案之報價,請問小惠公司選擇哪一家廠商,可以使認列之機器成本達到最低?", "options": ["甲廠商:機器定價 $500,000,現購,可享一成之商業折扣", "乙廠商:機器定價 $470,000,賒購,付款條件為 5/10,3/20,n/30", "丙廠商:可以八個月後到期、面額 $484,000 之不附息票據來賒購設備,有效利率 15%", "丁廠商:可以分期付款方式購買機器,現付頭期款 $10,000,分三年每年底付現 $160,000,該機器現金價格 $445,000"], "answer": "C", "figure": null, "official": "(A)$500,000×0.9=$450,000;(B)$470,000×(1-5%)=$446,500;(C)應以票據現值入帳=$484,000÷(1+15%×8/12)=$440,000;(D)應以機器的現金價格入帳=$445,000。", "explain": {"concept": "取得成本=現金價格(或現值);商業折扣要先扣,現金折扣用淨額法取最大折扣,不附息票據要折現。", "steps": ["甲:商業折扣 10%,成本=$500,000×(1-10%)=$450,000。", "乙:付款條件 5/10,3/20,n/30,以淨額法按最大折扣 5% 入帳:$470,000×(1-5%)=$446,500。", "丙:不附息票據,成本是票據的現值=$484,000÷(1+15%×8/12)=$484,000÷1.1=$440,000。", "丁:分期付款,成本是現金價格 $445,000。", "四者比較:$450,000、$446,500、$440,000、$445,000,最低的是丙,選(C)。"], "pitfalls": "不附息票據不能直接以面額入帳,要用有效利率折現;現金折扣金額不要當成成本。", "distractors": {"A": "成本 $450,000,比丙高。", "B": "成本 $446,500,比丙高。", "D": "成本 $445,000,比丙高。"}}, "check": "python:500000*0.9=450000;470000*0.95=446500;484000/(1+0.15*8/12)=440000;丁=445000,最低為丙,與官方一致。", "verified": true, "note": ""}, {"id": "110-4-A-20", "exam": "110-4", "paper": "A", "q": 20, "unit": "十五、長期營業用資產", "topic": "專利權攤銷與年限", "stem": "阿海公司在 X1 年 1 月 1 日以 $36,000 購入法定年限 10 年,經濟效益年限 8 年之甲專利權。X5 年初為保護甲專利權,再以 $6,000 購入 X3 年初核准、法定年限 8 年之乙專利權,乙專利權僅為保護甲專利權,並不擬實際使用,故其經濟效益年限同甲專利權,而取得乙專利權估計能再增加甲專利權 2 年之經濟年限。試計算 X5 年底調整後,阿海公司專利權之帳面金額為多少?", "options": ["$20,000", "$18,000", "$15,000", "$13,500"], "answer": "A", "figure": null, "official": "X5 年初時,甲專利權剩餘經濟年限為 8-4=4 年,帳面金額=$18,000。為保護甲專利權而購入乙專利權後,甲專利權尚餘經濟年限延長為 4+2=6 年,專利權之帳面金額=$18,000+$6,000=$24,000;X5 年專利權之攤銷金額=$24,000÷6=$4,000,則 X5 年底調整後專利權之帳面金額=$24,000-$4,000=$20,000。", "explain": {"concept": "無形資產攤銷年限取「經濟年限」與「法定年限」較短者;為保護既有專利而購入的專利,成本併入原專利,按延長後的剩餘年限攤銷。", "steps": ["甲專利權經濟年限 8 年(短於法定 10 年),所以每年攤銷 $36,000÷8=$4,500。", "X1~X4 共攤 4 年,X5 年初帳面金額=$36,000-$4,500×4=$18,000(剩餘 4 年)。", "乙專利權只為了保護甲、不單獨使用,成本 $6,000 要併入甲專利權的帳面金額:$18,000+$6,000=$24,000。", "購入乙使甲的經濟年限再增加 2 年,剩餘年限=4+2=6 年。", "X5 年攤銷=$24,000÷6=$4,000;X5 年底帳面金額=$24,000-$4,000=$20,000,選(A)。"], "pitfalls": "容易把乙專利權單獨攤銷(用法定年限 8 年)或忘了併入甲專利權。", "distractors": {"B": "只算 X5 年初甲專利權帳面金額 $18,000,沒加乙,也沒攤銷。", "C": "可能漏加乙專利成本或重新計算年限有誤。", "D": "可能把剩餘年限或攤銷額算錯。"}}, "check": "python:36000*4/8=18000;18000+6000=24000;24000/6=4000;24000-4000=20000,與官方一致。", "verified": true, "note": ""}, {"id": "110-4-A-21", "exam": "110-4", "paper": "A", "q": 21, "unit": "十五、長期營業用資產", "topic": "生物資產原始認列", "stem": "阿吉牧場 X1 年 3 月 1 日買入 20 隻乳牛,每隻購買價格 $1,000,並支付 $3,000 將所有乳牛運送至牧場,準備飼養以供未來生產牛奶。牧場估計若立即將該批乳牛出售,需支付運費 $3,000 及市場管理費等其他成本 $2,000。請問 X1 年 3 月 1 日,該批乳牛的原始認列金額為多少?", "options": ["$20,000", "$17,000", "$15,000", "$12,000"], "answer": "C", "figure": null, "official": "(20×$1,000-$3,000)-$2,000=$15,000。", "explain": {"concept": "生物資產(如乳牛)原始認列按「公允價值減出售成本」衡量,而不是取得成本。", "steps": ["依 IAS 41,生物資產於原始認列及每期末按「公允價值減出售成本」衡量。", "出售成本包括出售時需支付的運費 $3,000 與市場管理費等 $2,000,合計 $5,000。", "公允價值以購買價 20×$1,000=$20,000 為基礎(官方算法列為 20×$1,000)。", "原始認列金額=$20,000-$3,000-$2,000=$15,000,選(C)。"], "pitfalls": "容易按「取得成本(價款加運費)」算成 $23,000,但生物資產要用公允價值減出售成本。", "distractors": {"A": "只用購買價款 $20,000,沒有扣出售成本。", "B": "只扣了運費 $3,000,漏扣市場管理費 $2,000。", "D": "多扣了不應扣的項目。"}}, "check": "python:20*1000-3000-2000=15000,與官方一致。", "verified": true, "note": ""}, {"id": "110-4-A-22", "exam": "110-4", "paper": "A", "q": 22, "unit": "十七、權益", "topic": "權益概念", "stem": "有關權益的概念,下列敘述何者正確?", "options": ["普通股是公司最基本的股票,享有優先股利分配權", "公司發行新股時,股票發行成本應列為「其他費用」", "發放股票股利不影響權益總額,亦不影響保留盈餘總額", "發放已宣告之現金股利,會使資產與負債皆減少"], "answer": "D", "figure": null, "official": "(A)優先股利分配權為「特別股」股東的權利;(B)股票發行成本應列為「股票發行價格的減項」;(C)發放股票股利不影響權益總額,但會「減少保留盈餘總額」。", "explain": {"concept": "宣告現金股利時記負債(應付股利),發放時才減少資產與負債。", "steps": ["(A)優先分配股利的是特別股股東,普通股沒有此權利,(A)錯。", "(B)股票發行成本(如印刷費、承銷費)是發行價款的減項(減少資本公積等),不是費用,(B)錯。", "(C)股票股利是由保留盈餘轉為股本,權益總額不變,但保留盈餘減少,(C)錯。", "(D)宣告時:借:保留盈餘,貸:應付股利(負債);發放時:借:應付股利,貸:現金。發放時資產(現金)與負債(應付股利)同時減少,(D)正確。"], "pitfalls": "股票股利:權益內部轉換(保留盈餘→股本),總額不變但保留盈餘會減少。", "distractors": {"A": "把特別股的優先股利權當成普通股權利。", "B": "股票發行成本不是費用,而是發行價款的減項。", "C": "股票股利會減少保留盈餘。"}}, "check": "概念題,以分錄推演並與官方詳解一致。", "verified": true, "note": ""}, {"id": "110-4-A-23", "exam": "110-4", "paper": "A", "q": 23, "unit": "十七、權益", "topic": "累積盈虧變動原因", "stem": "下列何者是導致公司累積盈虧增加之原因?", "options": ["公司營運狀況不佳,本期產生淨損", "公司以資本公積來彌補營運之虧損", "公司發現前一年度有淨利高估之情況", "公司提撥特別盈餘公積來限制股利的發放"], "answer": "B", "figure": null, "official": "(A)本期淨損導致累積盈虧減少;(B)資本公積減少,累積盈虧增加;(C)前一年度淨利高估,需借記「追溯適用及追溯重編之影響數」,故累積盈虧減少;(D)特別盈餘公積增加,累積盈虧減少。", "explain": {"concept": "「累積盈虧」是保留盈餘的另一種說法,淨利、彌補虧損會使其增加(虧損減少);淨損、提列公積會使其減少。", "steps": ["把累積盈虧理解成保留盈餘:增加的原因是賺錢或有人補進來。", "(A)淨損使累積盈虧減少。", "(B)用資本公積彌補虧損:借:資本公積,貸:累積虧損(保留盈餘),累積盈虧增加(虧損變少),(B)正確。", "(C)前期淨利高估,更正後前期盈餘要調低,累積盈虧減少。", "(D)提撥特別盈餘公積:借:保留盈餘,貸:特別盈餘公積,累積盈虧減少。"], "pitfalls": "累積盈虧(保留盈餘)提撥公積時是減少,不是增加。", "distractors": {"A": "淨損使累積盈虧減少。", "C": "前期高估更正後會讓保留盈餘減少。", "D": "提撥公積是從保留盈餘轉出,使累積盈虧減少。"}}, "check": "概念題,以保留盈餘變動分錄推演,與官方詳解一致。", "verified": true, "note": ""}, {"id": "110-4-A-24", "exam": "110-4", "paper": "A", "q": 24, "unit": "九、財務報表", "topic": "流動比率分析", "stem": "▲閱讀下文與圖表,回答第 24-25 題\n臺灣四面環海,且位處西太平洋重要交通樞紐,不論是經濟貿易、國際海洋漁業、海空的交通航線,皆是重要的必經地點。其中,臺灣在空運發展迅速且多元,與眾多國家、地區皆簽署航約,來往國際及兩岸的定期航線有三十多個國家地區,並連接一百多個城市,足可見臺灣空運產業的蓬勃發展。試根據下列三家航空公司的資料,回答第 24-25 題。\n\n圖(二) 流動比率(單位:%)\n\n| 年度 | A 航空公司 | B 航空公司 | C 航空公司 |\n|---|---|---|---|\n| X1 年 | 108.8 | 71.7 | 105.9 |\n| X2 年 | 126.2 | 67.0 | 106.4 |\n| X3 年 | 131.2 | 71.8 | 76.7 |\n| X4 年 | 119.0 | 59.9 | 167.5 |\n| X5 年 | 97.6 | 66.7 | 140.53 |\n\nX1 年至 X5 年間,A、B、C 三家航空公司之流動比率如圖(二)所示,試根據折線圖所提供之資訊,判斷下列敘述何者錯誤?", "options": ["A 航空公司之流動比率較其他兩家公司穩定,因此在五年間之短期償債能力最佳", "B 航空公司之流動比率在五年間無太大波動,但短期償債能力之表現為三家中最弱", "C 航空公司在 X3 年之流動比率大幅降低,可能是因公司動用短期資金大量購買飛機所導致", "為了提升流動比率,公司可藉由發行屬於非流動負債之公司債,以籌措現金"], "answer": "A", "figure": "figs/110-4-A-q24.png", "official": "流動比率越高,代表公司之短期償債能力佳。A 航空公司在 X1 年至 X3 年之短期償債能力為最佳,但在 X4-X5 年時流動比率下滑,反而是 C 航空公司擁有最佳的短期償債能力。", "explain": {"concept": "流動比率=流動資產÷流動負債,越高短期償債能力越佳;穩定不等於最好。", "steps": ["流動比率代表公司用流動資產償還流動負債的能力,數值越高越好,與「穩定」無關。", "看圖:X1~X3 年 A 公司最高(108.8、126.2、131.2),但 X4、X5 年 C 公司(167.5、140.53)超過 A(119.0、97.6),所以五年間並不是 A 最佳,(A)錯誤。", "(B)B 公司在 60~72% 之間小幅波動,每年都最低,短期償債能力最弱,正確。", "(C)C 公司 X3 年降到 76.7%,可能是動用短期資金(流動資產)購買飛機(非流動資產),正確。", "(D)發行公司債(非流動負債)取得現金,流動資產增加、流動負債不變,流動比率上升,正確。"], "pitfalls": "把「穩定」誤當成「最好」;判斷好壞要比較數值大小,不是波動大小。", "distractors": {"B": "B 公司流動比率每年皆最低,敘述正確。", "C": "買非流動資產使流動資產減少,可能使流動比率大幅下降,敘述正確。", "D": "借入長期資金增加流動資產,不增加流動負債,可提高流動比率,敘述正確。"}}, "check": "概念題,依圖表數值比較(X4、X5 年 C 公司高於 A 公司),與官方詳解一致。", "verified": true, "note": ""}, {"id": "110-4-A-25", "exam": "110-4", "paper": "A", "q": 25, "unit": "九、財務報表", "topic": "本益比與每股盈餘", "stem": "表(一)為 A、B、C 三家航空公司在 X4 及 X5 年時的資料,試判斷下列敘述何者正確?\n\n| 公司 | X4 年每股盈餘 EPS | X4 年底普通股每股公允價值 | X5 年每股盈餘 EPS | X5 年底普通股每股公允價值 |\n|---|---|---|---|---|\n| A 航空公司 | $0.23 | $16 | -$0.4 | $22 |\n| B 航空公司 | -$0.25 | $11 | -$0.14 | $14 |\n| C 航空公司 | $0.24 | $12 | $0.55 | $12 |", "options": ["A 航空公司 X4 年的本益比為三家中最高,表示其投資報酬率亦為最高", "B 航空公司 X5 年之每股盈餘 EPS 較 X4 年的表現來的好,可推測其財務績效有好轉", "C 航空公司 X4 及 X5 年之每股盈餘 EPS 皆為三家中最高,可預測未來仍可保持穩定收益", "本益比為每股市價對每股盈餘之比率,投資人可於資產負債表上查詢每股盈餘之值"], "answer": "B", "figure": null, "official": "(A)X4 年 A 公司本益比=$16÷$0.23=69.57;C 公司本益比=$12÷$0.24=50;X4 年本益比:A>C;又本益比與投資報酬率互為倒數,故 X4 年投資報酬率:A<C;(C)每股盈餘 EPS 無法推測未來公司的獲利狀況;(D)投資人可於「綜合損益表」上查詢每股盈餘之值。", "explain": {"concept": "本益比=每股市價÷每股盈餘;EPS 為負時本益比無意義;本益比越高表示回收年數越長(報酬率越低)。", "steps": ["先算 X4 年本益比:A=$16÷$0.23≈69.57;C=$12÷$0.24=50;B 的 EPS 為負,本益比無意義。A 的本益比最高沒錯,但本益比高表示用越多年才回收本金(投資報酬率=本益比的倒數,越低),所以 A 的投資報酬率反而低於 C,(A)錯。", "(B)B 公司 EPS 由 -$0.25 變成 -$0.14,虧損縮小,表現較好,財務績效有好轉,(B)正確。", "(C)X4 年 C 的 EPS(0.24)確實高於 A(0.23),X5 年 C 的 EPS(0.55)也最高,但 EPS 只是過去的數字,無法據此預測未來是否穩定獲利,(C)錯。", "(D)每股盈餘列示於綜合損益表,不是資產負債表,(D)錯。"], "pitfalls": "本益比高不代表報酬率高;EPS 是損益表(綜合損益表)上的資料。", "distractors": {"A": "把本益比高誤當成投資報酬率高,兩者為倒數關係。", "C": "以過去兩年 EPS 高低預測未來穩定收益,但 EPS 無法預測未來獲利。", "D": "每股盈餘在綜合損益表上,不在資產負債表。"}}, "check": "python:16/0.23=69.57;12/0.24=50;B 公司 EPS -0.25→-0.14(虧損縮小),與官方一致。", "verified": true, "note": "(C)選項錯誤主因為『EPS 無法推測未來獲利』(官方)。"}, {"id": "110-5-A-01", "exam": "110-5", "paper": "A", "q": 1, "unit": "一、會計基本概念", "topic": "商業會計法規定", "stem": "台美商店經營國內零食銷售,規模狹小、交易零星,且預估平均每月銷售額$150,000,於開始營業前申請並獲准免用統一發票,剛剛擔任該店會計工作的小芳,向四位前輩請教實務上會計事務的處理,下列哪些人的說法正確?\n甲:經獲准免用統一發票之商店,銷售時不必開列發票,也不必繳納營業稅\n乙:會計帳簿保存 5 年以上後,經負責人書面核准即可以銷毀\n丙:依現行商業會計法之規定,每筆支出超過新台幣$1,000,000 者,不得使用現金(新台幣)支付\n丁:經辦人有實際且合理支出的憑證如果遺失了,可填寫支出證明單,經主管或負責人核准後報帳", "options": ["甲丁", "乙丙", "丙丁", "甲丙丁"], "answer": "C", "figure": null, "official": "免用統一發票者仍要繳營業稅;帳簿應至少保存10年;丙、丁正確。", "explain": {"concept": "考商業會計法與營業稅的基本常識:免用統一發票不等於免稅;帳簿保存年限;大額支出限制;憑證遺失的處理。", "steps": ["逐項判斷:甲說「免用統一發票就不必繳營業稅」,但小規模營業人仍要依法按季繳納營業稅,只是稅額用查定方式計算,所以甲錯。", "乙說帳簿保存 5 年,商業會計法規定帳簿應至少保存 10 年(會計憑證至少 5 年),所以乙錯。", "丙:每筆支出超過新台幣 $1,000,000 不得以現金支付,要用支票、匯款等方式,所以丙對。", "丁:憑證遺失時,若支出確實且合理,可填「支出證明單」,經主管或負責人核准後入帳,所以丁對。", "正確的是丙、丁,選(C)。"], "pitfalls": "最常搞混「帳簿保存 10 年」與「憑證保存 5 年」;也容易以為免用發票就免稅。", "distractors": {"A": "只認為甲對,但免用統一發票仍要繳營業稅;丁雖對卻漏掉丙。", "B": "把乙「帳簿 5 年」當成對的,其實是憑證才 5 年;且漏了丁。", "D": "多選了甲,誤以為免用發票就不用納稅。"}}, "check": "概念題:官方詳解與商業會計法常識一致。", "verified": true, "note": ""}, {"id": "110-5-A-02", "exam": "110-5", "paper": "A", "q": 2, "unit": "一、會計基本概念", "topic": "交際費與稅法調整", "stem": "擔任會計工作的小明,依據相關法令及一般公認會計原則進行會計事務之處理。公司經理及業務員交來了與客戶或同業的餐敘、饋贈禮品等支出憑證,該交際費支出共計$50,000 均與業務有關並取得合法憑證,且經單位主管核准。但依所得稅法第 37 條及營利事業所得稅查核準則第 80 條規定所計算的交際費列支限額為$40,000,則會計人員小明應如何處理交際費?", "options": ["在帳冊上記載交際費$50,000、營利事業所得稅申報書上之交際費調減金額為$0", "在帳冊上記載交際費$40,000、營利事業所得稅申報書上列報之交際費金額為$40,000", "在帳冊上記載交際費$40,000、營利事業所得稅申報書上之交際費調增金額為$50,000", "在帳冊上記載交際費$50,000、營利事業所得稅申報書上之交際費調減金額為$40,000"], "answer": "D", "figure": null, "official": "帳上依實際金額$50,000記載,申報時依稅法限額,超限$10,000於申報書調整(調減)。", "explain": {"concept": "考會計與稅法的差異:帳上依實際發生記錄,報稅時才依稅法限額調整。", "steps": ["會計處理以一般公認會計原則為準:實際花了 $50,000 就要在帳上記 $50,000,不可以因為稅法有限額就少記。", "稅法只認列 $40,000,超出的 $10,000 在報稅時要調整(帳外調整)。", "官方答案的表述:申報書上依稅法列報 $40,000,也就是由帳上 $50,000 調整減少 $10,000,選(D)。"], "pitfalls": "容易把稅法限額直接寫進帳裡,忘了會計帳要反映實際交易。", "distractors": {"A": "帳上 $50,000 正確,但說申報時調減 $0,等於稅法限額沒有作用。", "B": "帳上只記 $40,000,把稅法限額當成會計記錄,不符合會計原則。", "C": "帳上少記 $10,000,且「調增 $50,000」金額完全不合理。"}}, "check": "概念題:與官方詳解及稅法與會計分離之常識一致。", "verified": true, "note": "選項(D)中「調減金額為$40,000」之語意與詳解之「調整後列報$40,000」略有出入,以官方答案D為準。"}, {"id": "110-5-A-03", "exam": "110-5", "paper": "A", "q": 3, "unit": "九、財務報表", "topic": "淨利與現金變動差異", "stem": "大發公司採權責發生基礎,總經理和員工天天衝營收,銷售狀況良好,但一般銷售平均為成交後 3 個月收現,因此常常發生營運現金不足的現象。年底公司的會計人員小美向總經理提出本年度財務報表,報表顯示本期淨利很高,但現金及約當現金的增加金額卻較本期淨利少,總經理問:「本期淨利很高,但卻沒有賺進相當的現金及約當現金,錢都到哪裡去了?你的財務報表正確嗎?」小美向總經理解釋本公司本期淨利高於現金及約當現金增加金額的原因,下列何者為合理原因?", "options": ["賒銷的銷貨已經入帳,但產生的應收帳款尚未全部收現", "本年年底有一筆銀行長期借款獲准了,並已獲得該筆款項", "本年年底認列鉅額的公司債利息,按約定應於明年年初支付", "現金被竊盜,現金內部控制不良"], "answer": "A", "figure": null, "official": "賒銷已認列收入使淨利增加,但現金尚未流入,是合理原因。", "explain": {"concept": "權責發生基礎下,收入在賺得時認列,不一定同時收到現金。", "steps": ["題目問:為什麼「淨利」比「現金增加數」高?原因要是「讓淨利增加、但現金沒增加(或增加較少)」的事項。", "(A) 賒銷:借應收帳款、貸銷貨收入。收入增加使淨利變大,但現金沒進來,所以淨利大於現金增加,符合。", "(B) 長期借款:現金增加,但不影響損益,會讓現金變多,方向相反。", "(C) 認列應付利息:費用增加使淨利減少,現金沒流出,會讓淨利變小,方向相反。", "(D) 現金被竊:並不是題目的合理說明,也不一定代表內控不良。", "選(A)。"], "pitfalls": "要先確認方向:是「淨利大、現金小」,選項的影響方向要對。", "distractors": {"B": "借款讓現金增加但不影響淨利,會使現金增加大於淨利,方向反了。", "C": "應付利息使費用增加、淨利減少,卻沒有現金流出,方向反了。", "D": "現金被竊屬於特殊事件,題目所述情況是營運週期性的收現落差,並非主要原因。"}}, "check": "概念題:與官方詳解一致。", "verified": true, "note": "單元歸類可能有爭議(現金流量與損益差異,歸九或十二)。"}, {"id": "110-5-A-04", "exam": "110-5", "paper": "A", "q": 4, "unit": "九、財務報表", "topic": "流動比率變動", "stem": "天平公司的流動比率大於 1,則下列交易何者使流動比率下降?", "options": ["客戶償還貨款,交來 6 個月期商業本票", "年底存貨價值衡量,增加「備抵存貨跌價」帳戶餘額", "發行 3 年期公司債$1,000,000,償還短期借款$1,000,000", "將代扣員工的勞保費以本公司存款匯入勞保局"], "answer": "B", "figure": null, "official": "備抵存貨跌價使存貨下降、流動資產減少,流動負債不變,比率下降。", "explain": {"concept": "流動比率 = 流動資產 ÷ 流動負債,比率大於 1 時,判斷分子分母如何變動。", "steps": ["先寫公式:流動比率 = 流動資產 ÷ 流動負債,目前大於 1。", "(A) 收到 6 個月期商業本票:應收票據增加、應收帳款減少,流動資產總額不變,比率不變。", "(B) 提列存貨跌價損失:銷貨成本(或損失)增加,備抵存貨跌價增加,存貨帳面金額減少,流動資產減少,流動負債不變,比率下降。", "(C) 發行長期公司債還短期借款:流動負債減少,流動資產不變,比率上升。", "(D) 匯出代扣勞保費:代收款(流動負債)和銀行存款(流動資產)同時減少相同金額。因為原本比率大於 1,分子分母同減同額,比率會上升。", "所以只有(B)使比率下降。"], "pitfalls": "同額加減分子與分母時,比率大於 1 會往 1 靠近:同減則上升,同加則下降。", "distractors": {"A": "以為票據替代帳款會影響比率,其實只是流動資產內部互換,比率不變。", "C": "以為借新還舊會變差,其實流動負債減少,比率上升。", "D": "以為付錢流動資產減少就下降,忽略流動負債也同額減少。"}}, "check": "以假設流動資產 $200、流動負債 $100 為例:(B)減$10 → 190/100=1.9<2;(D)減$10 → 190/90≈2.11>2;與官方相符。", "verified": true, "note": ""}, {"id": "110-5-A-05", "exam": "110-5", "paper": "A", "q": 5, "unit": "二、會計循環及會計帳簿", "topic": "會計帳簿", "stem": "有關會計帳簿之敘述,下列何者正確?", "options": ["「日記簿」及「分類帳」兩者每一頁的借貸金額合計必相等,並且應過入次頁", "分類帳中統制帳戶的餘額必等於其明細分類帳中各子項目餘額之和", "若要了解個別會計項目的增減變動及餘額應查閱日記簿", "日記帳簿完全正確時,即可省略分類帳簿"], "answer": "B", "figure": null, "official": "統制帳戶餘額等於其明細分類帳各子帳戶餘額之和。", "explain": {"concept": "考日記簿、分類帳、統制帳戶與明細分類帳的關係。", "steps": ["(A) 日記簿每頁借貸合計相等,但分類帳是依科目分頁,資產帳戶借方通常大於貸方,每頁借貸不一定相等,所以錯。", "(B) 統制帳戶(如應收帳款)記的是總數,明細分類帳(各客戶)記的是細項,兩者餘額必須相等,所以對。", "(C) 想了解某個會計項目的增減及餘額,應查「分類帳」,日記簿是依日期記錄,不是依科目,所以錯。", "(D) 分類帳與日記簿都是必要帳簿,日記簿再正確也不能省略分類帳。", "選(B)。"], "pitfalls": "日記簿是「按時間」記,分類帳是「按科目」記,找科目餘額要看分類帳。", "distractors": {"A": "把日記簿每筆分錄借貸相等,誤用到分類帳每頁。", "C": "混淆日記簿與分類帳的功能。", "D": "以為日記簿正確就夠,其實兩種帳簿都必要。"}}, "check": "概念題:與官方詳解一致。", "verified": true, "note": ""}, {"id": "110-5-A-06", "exam": "110-5", "paper": "A", "q": 6, "unit": "十七、權益", "topic": "獨資權益變動", "stem": "亮亮商店年初業主資本帳戶餘額$100,000、權益總額$240,000,本年度權益發生下列變動:辦理現金增資$60,000、業主提領現金$7,000 自用、業主代付商店的水電費$5,000,本年度收益$500,000、費損$360,000。則下列有幾項正確?\n①年底業主資本$100,000\n②年底結帳前業主往來$207,000\n③本年度淨損$140,000\n④年底權益總額$438,000", "options": ["一項", "二項", "三項", "四項"], "answer": "A", "figure": null, "official": "只有④正確,①②③皆錯。", "explain": {"concept": "獨資權益由業主資本與業主往來構成,結帳前業主往來要逐項算,淨利要看收益減費損。", "steps": ["①年底業主資本 = 年初 $100,000 + 增資 $60,000 = $160,000,不是 $100,000,①錯。", "年初業主往來 = 權益總額 $240,000 − 業主資本 $100,000 = $140,000。", "②結帳前業主往來 = $140,000 − 提領 $7,000 + 代付水電 $5,000 = $138,000(提領是減少、業主代付費用是增加),所以不是 $207,000,②錯。", "③本年度淨利 = 收益 $500,000 − 費損 $360,000 = $140,000,是淨利不是淨損,③錯。", "④年底權益總額 = 資本 $160,000 + 業主往來 $138,000 + 淨利 $140,000 = $438,000,④對。", "只有一項正確,選(A)。"], "pitfalls": "業主提領使權益減少,但業主代付費用(借費用貸業主往來)是使業主往來增加;別全當成增加或全當成減少。", "distractors": {"B": "多算了一項,可能把②或③誤算為正確。", "C": "多算了兩項。", "D": "以為四項都對。"}}, "check": "python 算 160000+138000+140000=438000,與官方相符。", "verified": true, "note": ""}, {"id": "110-5-A-07", "exam": "110-5", "paper": "A", "q": 7, "unit": "六、試算與試算表", "topic": "試算表錯誤更正", "stem": "朱紅商店年底餘額式試算表的借貸方合計不相等,更正前借方餘額合計為$800,000,經查帳冊,發現下列事實:\n(1) 某交易借記應付帳款$1,500,過帳時過入應付帳款之貸方\n(2) 現付房租$1,200,重複入帳\n(3) 加計代收款借方金額時,借方合計為$2,000,誤記為$1,000\n則該試算表上原貸方餘額合計為何?", "options": ["$800,000", "$802,000", "$802,800", "$804,000"], "answer": "D", "figure": null, "official": "原貸方餘額合計 = $800,000 + $1,500×2 + $1,000 = $804,000。", "explain": {"concept": "試算表錯誤:找出每項錯誤會使借方、貸方各差多少,再回推原貸方合計。", "steps": ["先看哪些錯誤會造成借貸不平衡:", "(2) 重複入帳:借方和貸方同時多記,借貸仍相等,不影響差額,可以忽略。", "(1) 借方金額誤過入貸方:借方少了 $1,500,貸方卻多了 $1,500,差額共 $3,000(貸方比借方多)。", "(3) 借方合計少算 $1,000,借方再少 $1,000。", "正確借貸相等,設正確金額為 X:原借方 = X − 1,500 − 1,000 = $800,000,所以 X = $802,500。", "原貸方 = X + 1,500 = $804,000。(與官方 $800,000 + $1,500×2 + $1,000 相同)"], "pitfalls": "房租重複入帳會讓借貸同時變多,不會造成不平衡,不要被它干擾。", "distractors": {"A": "沒有調整任何錯誤。", "B": "可能只考慮 (3) 的 $1,000 再加其他錯誤算錯。", "C": "把 (2) 的 $1,200 也算進去,但重複入帳借貸同額,不影響差額。"}}, "check": "python:800000+1500*2+1000=804000,相符。", "verified": true, "note": ""}, {"id": "110-5-A-08", "exam": "110-5", "paper": "A", "q": 8, "unit": "十三、存貨", "topic": "進銷貨與銷貨毛利", "stem": "美林商店於本月初成立並開始營業,採永續盤存制,本月進銷資料如下:\n(1) 1 日賒購商品定價$150,000,以八折成交,起運點交貨,付款條件為 2/10,n/30,支付運費$1,000,該批貨款於本月 8 日付清貨款。\n(2) 15 日將 1 日購入的商品以$160,000 的價格全部賒銷,付款條件為 1/10,n/30,目的地交貨,並自行支付運費$2,000。買方於本月 23 日付清全部貨款後又於本月底退回四分之一的商品,本店以現金退還其貨款。\n根據上列資料計算本月份的銷貨毛利為何?", "options": ["$200", "$29,450", "$29,850", "$30,600"], "answer": "C", "figure": null, "official": "銷貨毛利 = $118,800 − $88,950 = $29,850。", "explain": {"concept": "淨額法下的進貨成本、銷貨折讓、銷貨退回,以及運費的歸屬。", "steps": ["進貨成本:定價 $150,000 打八折 = $120,000;8 日付款在 10 天內,享 2% 折扣 → $120,000 × 98% = $117,600;起運點交貨,運費 $1,000 由買方(本店)負擔,計入存貨 → 成本 $118,600。", "銷貨:售價 $160,000;23 日付款,離 15 日 8 天,在 10 天內享 1% 折扣 $1,600,銷貨淨額 $158,400。", "月底退回四分之一:銷貨退回 $40,000,對應折扣 $400,所以淨退還現金 $39,600;存貨回來 $118,600 × 1/4 = $29,650,銷貨成本減少 $29,650。", "銷貨淨額 = $160,000 − $1,600 − ($40,000 − $400) = $118,800。", "銷貨成本 = $118,600 − $29,650 = $88,950。", "銷貨毛利 = $118,800 − $88,950 = $29,850。目的地交貨的運費 $2,000 是營業費用,不影響毛利。"], "pitfalls": "賣方目的地交貨運費是銷貨費用,不是銷貨成本;進貨運費才加進存貨成本。", "distractors": {"A": "數字與計算不合理,可能只算了某些零碎項目。", "B": "可能少算了銷貨折讓(退回部分折扣 $400 等)或誤把運費算進成本。", "D": "可能把賣方運費 $2,000 或折讓處理錯誤,使毛利變大。"}}, "check": "python:(160000-1600-39600)-(118600-29650)=29850,相符。", "verified": true, "note": ""}, {"id": "110-5-A-09", "exam": "110-5", "paper": "A", "q": 9, "unit": "七、調整", "topic": "調整與結帳概念", "stem": "下列敘述,何者錯誤?", "options": ["平時會計帳務處理正確,則可省略調整程序", "根據國際會計準則,企業應採應計基礎會計編製其財務報表", "因營業產生的應收款項所提列之「預期信用減損損失」,將導致資產總額減少、營業利益減少", "所有調整分錄皆應過入分類帳"], "answer": "A", "figure": null, "official": "調整是必要的會計程序,不可省略。", "explain": {"concept": "考調整分錄的目的與必要性。", "steps": ["期末調整是為了讓收入與費用依權責發生基礎正確入帳,即使平時帳務都對,仍有應收收益、預付費用、折舊、呆帳等項目需要調整。", "(A) 說可以省略,錯誤。", "(B) 應計基礎(權責發生基礎)是編製財務報表的基本假設,正確。", "(C) 提列預期信用減損損失:費用增加(營業利益減少)、備抵損失增加使應收款項淨額下降(資產減少),正確。", "(D) 調整分錄與一般分錄一樣要過入分類帳,正確。", "題目問「錯誤」,選(A)。"], "pitfalls": "題目問的是「錯誤」,別選成正確的敘述。", "distractors": {"B": "這是正確敘述(權責發生基礎)。", "C": "這是正確敘述,提列呆帳使費用增加、資產減少。", "D": "這是正確敘述,調整分錄須過帳。"}}, "check": "概念題:與官方詳解一致。", "verified": true, "note": ""}, {"id": "110-5-A-10", "exam": "110-5", "paper": "A", "q": 10, "unit": "六、試算與試算表", "topic": "前期錯誤對淨利影響", "stem": "公司帳務經查發現 X1 年至 X3 年有下列會計錯誤:\n\n| | X1 年 | X2 年 | X3 年 |\n|---|---|---|---|\n| (1) 少計應付租金 | $200 | | $500 |\n| (2) 少計期末存貨 | 1,000 | $400 | 1,100 |\n| (3) 少計折舊 | 300 | 300 | 300 |\n\n若 X3 年度更正錯誤前之本期淨利為$100,000,則 X3 年度正確之本期淨利為何?", "options": ["$99,300", "$99,900", "$100,900", "$102,300"], "answer": "B", "figure": null, "official": "正確淨利 = $100,000 − $500 − $400 + $1,100 − $300 = $99,900。", "explain": {"concept": "錯誤更正:只計算「對 X3 年淨利」的影響;期末存貨錯誤會有前後年度抵銷效果。", "steps": ["(1) 應付租金:X1 的錯誤在 X2 自動抵銷,X3 少計 $500 費用 → X3 淨利多計 $500,要減 $500。", "(2) 期末存貨:X2 少計期末存貨 $400,就是 X3 期初存貨少 $400 → X3 銷貨成本少算 → 淨利多計 $400,要減 $400。X3 少計期末存貨 $1,100 → X3 銷貨成本多算 → 淨利少計 $1,100,要加 $1,100。X1 的錯誤在 X2 已抵銷,不影響 X3。", "(3) 折舊:X3 少提 $300 折舊 → X3 淨利多計 $300,要減 $300。X1、X2 的錯誤不影響 X3 的當年度淨利。", "正確淨利 = $100,000 − $500 − $400 + $1,100 − $300 = $99,900。"], "pitfalls": "期末存貨的錯誤會影響兩年(本年期末、下年期初),本題要分別看 X3 的期初(X2 的錯)與期末(X3 的錯)。", "distractors": {"A": "可能少加或多減某項,例如沒算 X3 期初存貨的 $400 影響方向。", "C": "可能方向全部弄反或漏掉折舊。", "D": "可能把應付租金、折舊錯誤都當成要加回。"}}, "check": "python:100000-500-400+1100-300=99900,相符。", "verified": true, "note": ""}, {"id": "110-5-A-11", "exam": "110-5", "paper": "A", "q": 11, "unit": "八、結帳", "topic": "結帳分錄", "stem": "陽光農場為獨資企業,年底的結帳分錄,下列何者合理?", "options": ["借:本期損益,貸:銷項稅額", "借:本期損益,貸:預付保險費", "借:累積盈虧,貸:本期損益", "借:原始認列生物資產及農產品之利益,貸:本期損益"], "answer": "D", "figure": null, "official": "「原始認列生物資產及農產品之利益」為收益,結轉本期損益。", "explain": {"concept": "結帳只結轉收益、費損(虛帳戶),資產負債不結轉;獨資不用累積盈虧。", "steps": ["結帳分錄的對象是損益類(收益與費損)帳戶。", "(A) 銷項稅額是負債,不能結轉本期損益。", "(B) 預付保險費是資產,不能結轉本期損益。", "(C) 獨資企業本期損益應結轉到「業主往來」,而不是「累積盈虧」(那是公司的科目)。", "(D) 該科目是收益,結帳時借記收益、貸記本期損益,合理。", "選(D)。"], "pitfalls": "獨資沒有保留盈餘/累積盈虧;別看到「損益」就選。", "distractors": {"A": "把銷項稅額(負債)當成收益來結轉。", "B": "把預付保險費(資產)當成費用結轉。", "C": "公司組織才有累積盈虧,本題是獨資,應轉入業主往來。"}}, "check": "概念題:與官方詳解一致。", "verified": true, "note": ""}, {"id": "110-5-A-12", "exam": "110-5", "paper": "A", "q": 12, "unit": "十、加值型營業稅會計實務", "topic": "營業稅累積留抵稅額", "stem": "新新公司為一般稅率營業人,營業稅稅率 5%,本期申報資料(未含稅):內銷$400,000、內銷的銷貨退回$20,000,外銷(經海關出口)$200,000,購置機器設備$500,000,一般進貨及費用支付$780,000,上期留抵稅額為$1,000。則本期申報後累積留抵稅額為何?", "options": ["$10,000", "$11,000", "$12,000", "$13,000"], "answer": "B", "figure": null, "official": "累積留抵稅額 = $46,000 − $35,000 = $11,000。", "explain": {"concept": "營業稅:進項稅額可抵銷項稅額,外銷零稅率,退稅時有限額。", "steps": ["進項稅額 = ($780,000 + $500,000) × 5% = $64,000,再加上期留抵 $1,000 → 進項共 $65,000。", "銷項稅額 = ($400,000 − $20,000) × 5% = $19,000(外銷零稅率,稅額 $0)。", "累積留抵稅額 = $65,000 − $19,000 = $46,000 …①", "退稅限額 = (外銷 $200,000 + 購買固定資產 $500,000) × 5% = $35,000 …②", "可退還金額取①、②較小者 = $35,000。", "保留到下期的累積留抵稅額 = $46,000 − $35,000 = $11,000。"], "pitfalls": "外銷是零稅率(有進項、無銷項),退稅金額有上限;未退還部分才是留抵。", "distractors": {"A": "可能把上期留抵 $1,000 漏掉。", "C": "可能把退稅限額算錯。", "D": "可能算錯進項或限額。"}}, "check": "python:(1280000*.05+1000)-(380000*.05)=46000;(200000+500000)*.05=35000;差 11000,相符。", "verified": true, "note": ""}, {"id": "110-5-A-13", "exam": "110-5", "paper": "A", "q": 13, "unit": "十一、現金及內部控制", "topic": "現金及零用金", "stem": "天天公司實施定額零用金$20,000,並於每月底撥補零用金,下列敘述何者錯誤?", "options": ["現金及約當現金項目中,包含持有客戶交來發票日為一個月後的支票", "指定用途的存款列為非流動資產", "為了現金的內部控制,管錢者不能管帳", "已支用的零用金於年底報銷費用並且撥補時,「零用金」帳戶的餘額仍為$20,000"], "answer": "A", "figure": null, "official": "發票日為一個月後的支票屬應收票據,不屬於現金及約當現金。", "explain": {"concept": "現金包含哪些項目:遠期支票不算現金。", "steps": ["(A) 客戶交來發票日為一個月後的支票(遠期支票),在到期前不能兌現,應列為「應收票據」,不是現金,所以(A)錯誤。", "(B) 指定用途(如償債基金)存款屬非流動資產,正確。", "(C) 管錢與管帳分開是基本內部控制,正確。", "(D) 定額零用金制,「零用金」帳戶餘額平時固定不變,撥補後仍是 $20,000,正確。", "題目問錯誤,選(A)。"], "pitfalls": "已到期或可立即兌現的票據才算現金;遠期支票不算。", "distractors": {"B": "是正確敘述。", "C": "是正確敘述(職能分離)。", "D": "是正確敘述(定額零用金)。"}}, "check": "概念題:與官方詳解一致。", "verified": true, "note": ""}, {"id": "110-5-A-14", "exam": "110-5", "paper": "A", "q": 14, "unit": "十二、應收款項", "topic": "帳齡分析與備抵損失", "stem": "宏運公司年底調整前備抵損失貸餘$2,000。應收帳款帳戶餘額及帳齡分析表如下:\n\n| 賒欠期間 | 應收帳款餘額 | 估計損失率 |\n|---|---|---|\n| 31-60 天 | $ ? | 1% |\n| 61-90 天 | 500,000 | 2% |\n| 91 天以上 | 100,000 | 3% |\n\n年底調整分錄提列「預期信用減損損失」$15,000,則年底調整後的資產負債表上應收帳款淨額為何?", "options": ["$383,000", "$385,000", "$983,000", "$985,000"], "answer": "C", "figure": null, "official": "X = $400,000,淨額 = $1,000,000 − $17,000 = $983,000。", "explain": {"concept": "備抵損失 = 調整前餘額 + 提列金額;帳齡法先求出空格。", "steps": ["調整後備抵損失 = 調整前貸餘 $2,000 + 本期提列 $15,000 = $17,000。", "帳齡法下,備抵損失 = 各組應收帳款 × 損失率之和:X × 1% + $500,000 × 2% + $100,000 × 3% = $17,000。", "算出:X × 1% + $10,000 + $3,000 = $17,000,所以 X × 1% = $4,000,X = $400,000。", "應收帳款總額 = $400,000 + $500,000 + $100,000 = $1,000,000。", "應收帳款淨額 = $1,000,000 − $17,000 = $983,000。"], "pitfalls": "備抵損失是帳齡法算出的「期末應有餘額」,不是要提列的金額;提列金額 = 應有餘額 − 調整前餘額。", "distractors": {"A": "把 X 當成淨額,或漏加其他組別。", "B": "可能扣了 $15,000 而不是 $17,000 並且少算 X。", "D": "用 $1,000,000 − $15,000,忘了加上調整前備抵損失 $2,000。"}}, "check": "python:X=(17000-10000-3000)/0.01=400000;1000000-17000=983000,相符。", "verified": true, "note": ""}, {"id": "110-5-A-15", "exam": "110-5", "paper": "A", "q": 15, "unit": "十二、應收款項", "topic": "無息票據利息收入", "stem": "連光公司 X1 年 12 月 31 日出售土地,土地成本$230,000,收到兩年後到期面額$290,400,不附息票據乙紙,當時有效利率為 10%。則 X3 年因該票據所認列的利息收入為何?", "options": ["$24,000", "$25,300", "$26,400", "$31,944"], "answer": "C", "figure": null, "official": "X3 年利息收入 = ($240,000 + $24,000) × 10% = $26,400。", "explain": {"concept": "無息票據以現值入帳,利息收入以期初帳面金額 × 有效利率計算。", "steps": ["無息票據的入帳金額是未來面額的現值:$290,400 ÷ (1 + 10%)² = $240,000。", "X2 年利息收入 = $240,000 × 10% = $24,000(X1/12/31 到 X2/12/31),期末帳面金額 = $264,000。", "X3 年利息收入 = $264,000 × 10% = $26,400,恰好把帳面金額加到面額 $290,400。"], "pitfalls": "利息收入要用「期初帳面金額」計算,別直接用現值或面額。", "distractors": {"A": "那是 X2 年的利息收入($24,000)。", "B": "可能用其他利率或本金算錯。", "D": "可能以 $290,400 或 $319,440 等錯誤基礎計算。"}}, "check": "python:290400/1.1**2=240000;264000*.1=26400,相符。", "verified": true, "note": ""}, {"id": "110-5-A-16", "exam": "110-5", "paper": "A", "q": 16, "unit": "十三、存貨", "topic": "期末存貨正確餘額", "stem": "神寶公司的期末存貨餘額為$100,000,期末存貨金額中除了庫存商品另包括:(1) 起運點交貨之在途進貨,成本為$10,000、(2) 寄銷在其他公司的商品,成本為$12,000、(3) 分期付款銷售的商品:貨款尚未全部收回,該批商品之成本為$13,000、售價為$18,000。則期末存貨的正確餘額為何?", "options": ["$65,000", "$75,000", "$82,000", "$87,000"], "answer": "D", "figure": null, "official": "(3) 已銷售,不屬於公司存貨,應扣除 $13,000;正確餘額 $87,000。", "explain": {"concept": "判斷哪些商品所有權屬於本公司:起運點在途進貨、寄銷商品是我的;分期付款銷貨已賣出,不是我的。", "steps": ["(1) 起運點交貨:貨一離開賣方,所有權就是買方(本公司)的,所以在途進貨應列入本公司存貨,已包含在 $100,000 內,不必調整。", "(2) 寄銷在別人那裡的商品,所有權還是本公司,屬於本公司存貨,已包含,不調整。", "(3) 分期付款銷貨:貨已經交給客戶,在會計上視為已出售,不應再列為本公司存貨,要扣除成本 $13,000(不是售價 $18,000)。", "正確期末存貨 = $100,000 − $13,000 = $87,000。"], "pitfalls": "扣除時用「成本」,不是售價;在途與寄銷要分清楚歸誰。", "distractors": {"A": "把三項都扣掉,再多扣了其他金額。", "B": "可能扣了 (3) 的 $13,000 與 (1) 的 $10,000。", "C": "可能扣了售價 $18,000。"}}, "check": "python:100000-13000=87000,相符。", "verified": true, "note": ""}, {"id": "110-5-A-17", "exam": "110-5", "paper": "A", "q": 17, "unit": "十三、存貨", "topic": "存貨盤存制與衡量", "stem": "有關存貨之敘述,下列何者錯誤?", "options": ["採永續盤存制,發生的進貨退出、進貨折讓皆使存貨成本減少", "採永續盤存制,帳列存貨大於實際盤點金額時,導致銷貨成本增加", "可替換的大量存貨,存貨成本公式不適宜採個別認定法", "存貨的後續衡量應採成本與公允價值孰低法"], "answer": "D", "figure": null, "official": "存貨後續衡量應採「成本與淨變現價值孰低」法。", "explain": {"concept": "存貨的後續衡量基礎:成本與淨變現價值孰低。", "steps": ["(A) 永續盤存制中,進貨退出與折讓使存貨減少,正確。", "(B) 帳列存貨大於實際盤點:有盤損,借銷貨成本、貸存貨,銷貨成本增加,正確。", "(C) 大量可替換的存貨,個別認定法不實用,應採先進先出、加權平均等,正確。", "(D) 存貨後續衡量是「成本與淨變現價值孰低」,不是公允價值,錯誤。", "題目問錯誤,選(D)。"], "pitfalls": "「淨變現價值」是估計售價減完工成本與出售費用,和「公允價值」不同。", "distractors": {"A": "正確敘述。", "B": "正確敘述。", "C": "正確敘述。"}}, "check": "概念題:與官方詳解及會計準則一致。", "verified": true, "note": ""}, {"id": "110-5-A-18", "exam": "110-5", "paper": "A", "q": 18, "unit": "十四、證券投資", "topic": "透過損益按公允價值衡量之金融資產", "stem": "創意公司為 IC 設計公司,管理當局決定除了經營本業,因應臺灣上市櫃公司業績普遍成長,股市前景看好,因此將部分資金投入股票市場。X1 年 5 月 1 日創意公司購入國內甲、乙兩家公司的普通股股票,甲公司股票於證券交易所上市,乙公司股票於證券櫃檯買賣中心買賣。創意公司購買甲、乙兩家公司各流通在外股票的 0.1%股數,股票持有目的主要是短期內出售、經常買賣賺取價差。投資相關資料如下:\n\n| 股票 | 成交價格 | 手續費 | X1 年收取現金股利 | X2 年收取現金股利 | X1 年底收盤價 | X2 年底收盤價 |\n|---|---|---|---|---|---|---|\n| 甲公司 | $160,000 | $230 | $8,000 | $3,000 | $164,000 | $140,000 |\n| 乙公司 | $120,000 | $170 | $6,000 | $5,000 | $136,000 | $115,000 |\n\n創意公司除了以上的普通股股票,無其他股票投資。有關創意公司的股票投資,下列敘述何者錯誤?", "options": ["創意公司對甲、乙兩家公司之投資皆無重大影響力", "X1 年度股票投資產生營業外支出$400、營業外收入$14,000", "X1 年底「透過損益按公允價值衡量之金融資產」帳面金額$300,000", "X2 年度「透過損益按公允價值衡量之金融資產損失」$45,000"], "answer": "B", "figure": null, "official": "X1 年營業外收入應為 $34,000,不是 $14,000。", "explain": {"concept": "持有供交易的股票:手續費當期費用、期末依公允價值評價,評價損益與股利都入損益。", "steps": ["(A) 持股只有 0.1%,遠低於 20%,無重大影響力,正確。", "(B) X1 年:手續費 $230 + $170 = $400 為營業外支出(正確)。評價利益 = 期末公允價值 ($164,000 + $136,000) − 成本 ($160,000 + $120,000) = $20,000;現金股利 $8,000 + $6,000 = $14,000;營業外收入 = $14,000 + $20,000 = $34,000,所以「$14,000」錯誤。", "(C) 帳面金額 = 年底公允價值 $164,000 + $136,000 = $300,000,正確。", "(D) X2 年底公允價值 $140,000 + $115,000 = $255,000,與 X1 年底 $300,000 比,損失 $45,000,正確。", "題目問錯誤,選(B)。"], "pitfalls": "手續費不計入成本,當期直接列費用;評價利益要和股利一起加進營業外收入。", "distractors": {"A": "正確敘述,0.1% 小於 20%。", "C": "正確敘述,帳面金額即公允價值。", "D": "正確敘述,($300,000 − $255,000)。"}}, "check": "python:300000-280000=20000;14000+20000=34000;255000-300000=-45000,相符。", "verified": true, "note": ""}, {"id": "110-5-A-19", "exam": "110-5", "paper": "A", "q": 19, "unit": "十五、長期營業用資產", "topic": "改變折舊方法", "stem": "美達公司於 X1 年初購置並使用某批機器設備,取得成本$420,000,估計殘值為$7,200,預估使用年限為 5 年,按雙倍數餘額遞減法提列折舊。至 X3 年初,公司決定改採年數合計法提列折舊,則 X3 年度之折舊額為何?", "options": ["$12,000", "$28,800", "$72,000", "$75,600"], "answer": "C", "figure": null, "official": "X3 年折舊額 = ($420,000 − $268,800 − $7,200) × 3/6 = $72,000。", "explain": {"concept": "折舊方法變動屬會計估計變動,從變動當年起推延適用,以當時帳面金額與剩餘年限重新計算。", "steps": ["雙倍數餘額遞減法的折舊率 = 1/5 × 2 = 40%,不先扣殘值。", "X1 折舊 = $420,000 × 40% = $168,000;X2 折舊 = ($420,000 − $168,000) × 40% = $100,800;X3 年初累計折舊 = $268,800。", "X3 年初帳面金額 = $420,000 − $268,800 = $151,200。", "改用年數合計法:剩餘年限 3 年,年數合計 = 3 + 2 + 1 = 6;可折舊金額 = $151,200 − 殘值 $7,200 = $144,000。", "X3 年折舊 = $144,000 × 3/6 = $72,000。"], "pitfalls": "雙倍數餘額遞減不扣殘值,年數合計法才扣殘值;改採新方法時年數合計要用「剩餘年限」(3 年),不是 5 年。", "distractors": {"A": "可能算錯剩餘年限與分數。", "B": "可能用 1/5 或其他分數算錯。", "D": "可能沒扣殘值 $7,200。"}}, "check": "python:(420000-268800-7200)*3/6=72000,相符。", "verified": true, "note": ""}, {"id": "110-5-A-20", "exam": "110-5", "paper": "A", "q": 20, "unit": "十五、長期營業用資產", "topic": "無形資產", "stem": "有關無形資產之敘述,下列何者正確?", "options": ["必定無實體", "內部產生的無形資產,不得入帳", "我國非公開發行公司的商譽,絕對不得攤銷,應每年定期進行減損測試", "專利權發生的訴訟支出,應列入專利權成本"], "answer": "A", "figure": null, "official": "無形資產是不具實體形式的資產。", "explain": {"concept": "無形資產的定義、內部產生及商譽、訴訟支出的處理。", "steps": ["(A) 無形資產定義即「無實體形式」,正確。", "(B) 內部產生的無形資產,研究階段支出作費用,發展階段符合資本化條件時可入帳,不是完全不得入帳,錯誤。", "(C) 非公開發行公司商譽,依商業會計處理準則可選擇攤銷,或不攤銷但每年減損測試,不是「絕對不得攤銷」,錯誤。", "(D) 專利權訴訟支出,僅能維持專利權現有預期效益時,應在發生時認列為費用,不是增加專利權成本,錯誤。", "選(A)。"], "pitfalls": "看到「絕對」「必定」等字眼要小心,但本題(A)的定義是正確的。", "distractors": {"B": "發展階段符合條件的支出可資本化,不是絕對不得入帳。", "C": "商業會計處理準則允許非公開發行公司的商譽可攤銷。", "D": "訴訟支出多為費用,不是專利權成本。"}}, "check": "概念題:與官方詳解及會計準則一致。", "verified": true, "note": ""}, {"id": "110-5-A-21", "exam": "110-5", "paper": "A", "q": 21, "unit": "十三、存貨", "topic": "消耗性生物資產", "stem": "來旺畜牧公司主要從事養豬事業,X1 年購入一批豬隻,預計飼養約 5 個月成熟後出售。\n(1) X1 年底帳上該批豬隻相關帳戶:「消耗性生物資產」$100,000、「消耗性生物資產公允價值減出售成本累計變動數」$10,000(貸方餘額)。\n(2) X2 年初該批豬隻飼養成熟後收成並出售,支付運送至市場的運費$2,000、該批豬隻的交易價格為$88,000、交易市場管理費及稅捐$1,000。\n有關來旺畜牧公司該批豬隻的帳務處理,下列敘述何者正確?", "options": ["X1 年底生物資產列為非流動資產", "X2 年初收成時認列「生物資產當期公允價值減出售成本之變動損失」$13,000", "X2 年初收成時認列「農產品」$85,000", "X2 年初收成時分錄貸記「消耗性生物資產」$100,000、「消耗性生物資產公允價值減出售成本累計變動數」$10,000"], "answer": "C", "figure": null, "official": "農產品 = 公允價值 − 出售成本 = $88,000 − $2,000 − $1,000 = $85,000。", "explain": {"concept": "消耗性生物資產以公允價值減出售成本衡量,收成時轉為農產品。", "steps": ["(A) 豬隻約 5 個月就成熟出售,屬於流動資產,所以錯。", "(B) X1 年底帳面價值 = $100,000 − $10,000 = $90,000。收成時公允價值減出售成本 = $88,000 − $2,000 − $1,000 = $85,000。變動 = $85,000 − $90,000 = −$5,000(損失 $5,000),不是 $13,000,所以錯。", "(C) 農產品入帳 = 收成時公允價值減出售成本 = $85,000,正確。", "(D) 累計變動數是貸方餘額,收成時應借記「累計變動數」$10,000、貸記「消耗性生物資產」$100,000,方向錯,所以錯。", "選(C)。"], "pitfalls": "累計變動數是貸方餘額(備抵性質),結轉時要借記。", "distractors": {"A": "以為養豬是長期,其實約 5 個月成熟,屬流動資產。", "B": "可能把 $88,000 + $2,000 + $1,000 或其他數字亂減,正確損失為 $5,000。", "D": "累計變動數是貸方餘額,結轉時應在借方,方向弄反。"}}, "check": "python:(88000-2000-1000)-(100000-10000)=-5000;農產品85000,相符。", "verified": true, "note": "單元歸類可能有爭議(生物資產不在清單中,暫歸十三存貨)。"}, {"id": "110-5-A-22", "exam": "110-5", "paper": "A", "q": 22, "unit": "十六、負債", "topic": "負債概念", "stem": "有關負債之敘述,下列何者錯誤?", "options": ["公司發行公司債,將資金用於綠色投資計畫包括氣候、環保、節能、減碳等,此債券稱為綠色債券(Green bond)", "產品製造瑕疵的售後服務保固,應於銷貨年度的銷貨時或報導期間結束日認列費用及負債", "公司組織發生課稅所得超過$120,000 時,應於當年度估列本期所得稅負債,列入流動負債", "若發生機率小於 50%,金額能可靠估計的損失與負債,應認列入帳"], "answer": "D", "figure": null, "official": "發生機率小於 50%者不予認列(列為或有負債揭露)。", "explain": {"concept": "負債準備(或有負債)的認列條件:很有可能(機率大於 50%)且可靠估計。", "steps": ["(A) 綠色債券的定義,正確。", "(B) 保固負債依權責發生基礎,在銷貨時或期末認列費用與負債,正確。", "(C) 本期所得稅負債估列於流動負債,正確。", "(D) 負債準備須「很有可能發生(機率大於 50%)」且金額能可靠估計才認列;機率小於 50% 不入帳,錯誤。", "題目問錯誤,選(D)。"], "pitfalls": "「很有可能」指發生機率大於 50%;小於 50% 通常只揭露不入帳。", "distractors": {"A": "正確敘述。", "B": "正確敘述。", "C": "正確敘述。"}}, "check": "概念題:與官方詳解一致。", "verified": true, "note": ""}, {"id": "110-5-A-23", "exam": "110-5", "paper": "A", "q": 23, "unit": "十六、負債", "topic": "公司債折價發行期間利息", "stem": "天璣公司奉准於 X1 年 1 月 1 日發行 10 年期公司債$200,000,票面利率為 12%,每年 6 月 30 日及 12 月 31 日各付息一次。該公司債因故延至 X1 年 3 月 1 日才出售,並收現$193,000(內含過期利息),有效利率為 13%,則 X1 年 6 月 30 日認列應付公司債之利息費用為何?", "options": ["$7,720", "$8,190", "$8,363", "$12,285"], "answer": "B", "figure": null, "official": "利息費用 = $189,000 × 13% × 4/12 = $8,190。", "explain": {"concept": "延後發行的公司債:收現金額含過期利息,要先扣掉,才得到實際發行價格。", "steps": ["3 月 1 日出售,買方要補付 1/1 到 3/1(2 個月)的應計利息:$200,000 × 12% × 2/12 = $4,000(包含在 $193,000 內)。", "公司債發行價格 = $193,000 − $4,000 = $189,000。", "利息費用從實際發行日 3/1 到 6/30,共 4 個月,用有效利率計算:$189,000 × 13% × 4/12 = $8,190。"], "pitfalls": "收現金額含應計利息,別直接拿 $193,000 去算利息費用;期間只有 4 個月。", "distractors": {"A": "可能用 $193,000 × 12% × ... 算錯,或其他比率。", "C": "可能用 $193,000 × 13% × 4/12 = $8,363,忘了扣過期利息。", "D": "可能用 6 個月或其他期間計算。"}}, "check": "python:(193000-4000)*.13*4/12=8190,相符。", "verified": true, "note": ""}, {"id": "110-5-A-24", "exam": "110-5", "paper": "A", "q": 24, "unit": "十七、權益", "topic": "股份有限公司帳務", "stem": "有關股份有限公司各項帳務處理之敘述,下列哪幾項正確?\n①發行無面額股股票,所支付的股票發行成本將減少股本金額\n②庫藏股票屬於權益,列為股本的減項\n③本期折舊計算錯誤之更正,記入「追溯適用及追溯重編之影響數」\n④我國公司法允許每季、每半年或每年分派盈餘\n⑤我國不允許股票分割\n⑥宣告並發放股票股利,保留盈餘總額不變且權益總額也不變", "options": ["①④", "①②⑥", "④⑤⑥", "①②③④⑤"], "answer": "A", "figure": null, "official": "①④正確。", "explain": {"concept": "考股份有限公司的股本、庫藏股票、錯誤更正、盈餘分派、股票分割與股票股利。", "steps": ["①發行無面額股,股票發行成本減少股本金額,正確。", "②庫藏股票是權益的減項,不是股本的減項,錯誤。", "③「前期」折舊計算錯誤更正才記入追溯適用及追溯重編影響數;「本期」折舊錯誤是當期更正,錯誤。", "④公司法允許每季、每半年或每年分派盈餘,正確。", "⑤我國可以進行股票分割,錯誤。", "⑥股票股利:保留盈餘減少、股本增加,權益總額不變,但保留盈餘總額是減少的,錯誤。", "正確的是①④,選(A)。"], "pitfalls": "股票股利是「保留盈餘轉股本」:保留盈餘減少、股本增加,權益總額不變。", "distractors": {"B": "認為庫藏股是股本減項,且以為股票股利不改變保留盈餘。", "C": "誤以為不能股票分割,且股票股利不影響保留盈餘。", "D": "多選了②③⑤,均為錯誤敘述。"}}, "check": "概念題:與官方詳解及公司法常識一致。", "verified": true, "note": "③題中「本期」與詳解「前期」的措辭以題目及官方答案為準。"}, {"id": "111-1-A-01", "exam": "111-1", "paper": "A", "q": 1, "unit": "一、會計基本概念", "topic": "獨資企業的責任與稅負", "stem": "小娟工作數年,陸續籌存創業基金,X1 年初終於能夠獨資設立登記資本額為 50 萬元之咕嚕嚕飲料店,緊接著尋找創意貼圖及文創藝術家,跨界合作設計聯名商品,預估每月平均營業額為 18 萬元,經財政部核定免用統一發票。商場前輩提醒小娟:創業除了認真經營,對於債務責任、會計處理、營業稅及所得稅,更是老闆不可不知的重要課題。\n有關咕嚕嚕飲料店的情況,下列哪幾項正確?\n①小娟對於咕嚕嚕飲料店的債務不必負擔無限清償責任\n②該店獨資且資本額不高,會計處理不必依商業會計法之規定\n③該店不必繳納營利事業所得稅\n④該店不必繳納營業稅", "options": ["③", "①②", "②④", "③④"], "answer": "A", "figure": null, "official": "①獨資者對債務須負無限清償責任;②會計處理應依商業會計法;③獨資企業不必繳營利事業所得稅(併入業主綜合所得);④免用統一發票但仍須每3個月繳納營業稅(總額型營業人)。", "explain": {"concept": "本題考獨資企業的特性:業主責任、會計法規適用、稅負。", "steps": ["先看①:獨資的業主和店是同一個人,店欠錢業主要用自己的財產還,也就是「無限清償責任」,所以①「不必負擔」是錯的。", "②:只要是商業(不論資本大小)都要依商業會計法處理會計事務,②錯。", "③:獨資、合夥企業的盈餘直接算成業主(合夥人)的個人所得,由業主繳綜合所得稅,企業本身不繳營利事業所得稅,③對。", "④:免用統一發票的小規模營業人,仍要繳營業稅,只是採總額型(定額稅率)、每3個月申報一次,④錯。", "只有③正確,答案選(A)。"], "pitfalls": "容易把「免用統一發票」誤會成「免繳營業稅」;也容易忘記獨資業主要負無限責任。", "distractors": {"B": "以為獨資業主不用負無限責任,且②也誤判。", "C": "以為資本小就不必依商業會計法,又誤以為免用發票就免營業稅。", "D": "③對但③④搭配時,誤認免用統一發票就不必繳營業稅。"}}, "check": "概念題,依官方詳解與商業會計法、營業稅法常識確認:只有③正確。", "verified": true, "note": ""}, {"id": "111-1-A-02", "exam": "111-1", "paper": "A", "q": 2, "unit": "一、會計基本概念", "topic": "會計恆等式與交易影響", "stem": "咕嚕嚕飲料店 X1 年 1 月 1 日~1 月 5 日發生交易如下:\n(1) 1 月 1 日業主小娟出資現金$500,000 設立本店\n(2) 1 月 3 日本店向銀行借入現金$300,000\n(3) 1 月 4 日本店以現金購置餐飲器具$200,000\n(4) 1 月 5 日客戶預訂後天交貨的飲料 100 杯,每杯$50,交來現金$5,000\n(5) 1 月 5 日業主小娟以私人現金$10,000 支付飲料店的廣告文宣\n根據以上交易,咕嚕嚕飲料店 X1 年 1 月 5 日之財務狀況,下列何者正確?", "options": ["資產總計$795,000", "負債總計$300,000", "業主資本$510,000", "現金餘額$605,000"], "answer": "D", "figure": null, "official": "資產=現金$605,000+器具$200,000=$805,000;負債=$300,000+預收貨款$5,000=$305,000;業主資本=$500,000;資產$805,000=負債$305,000+(業主資本$500,000+業主往來$10,000-費用$10,000)。", "explain": {"concept": "用「資產=負債+業主權益」逐筆分析交易,算出各項目餘額。", "steps": ["先逐筆記錄:(1)現金+500,000、業主資本+500,000。", "(2)借款:現金+300,000、借款(負債)+300,000。", "(3)買器具:現金-200,000、器具(資產)+200,000,資產內部一增一減。", "(4)客戶預付貨款:現金+5,000,但還沒交貨,所以記「預收貨款」(負債)5,000,不是收入。", "(5)業主用私人錢替店付廣告費$10,000:店的廣告費增加$10,000(費用),同時記「業主往來」(視為業主投入)$10,000,店的現金不變。", "現金=500,000+300,000-200,000+5,000=$605,000;器具$200,000;資產總計=$805,000。", "負債=300,000+5,000=$305,000;業主資本=$500,000。可見只有(D)正確。"], "pitfalls": "(4)的預收款是負債不是收入;(5)是業主私人現金付款,店的現金不會減少。", "distractors": {"A": "資產實為$805,000,$795,000是把預收的$5,000漏算再扣$10,000之類的誤算。", "B": "漏記預收貨款$5,000這項負債,負債應為$305,000。", "C": "把業主以私人現金支付的$10,000加進業主資本,但該筆同時是廣告費,資本仍是$500,000。"}}, "check": "python:500000+300000-200000+5000=605000;資產805,000=負債305,000+權益500,000,平衡。", "verified": true, "note": ""}, {"id": "111-1-A-03", "exam": "111-1", "paper": "A", "q": 3, "unit": "十二、應收款項", "topic": "應收票據的認列時機", "stem": "呆萌玩偶店聘任阿文擔任會計,在營業過程中阿文拿到一些客戶交來的票據,阿文覺得很頭痛,這些票據在哪些情況下會計科目應借記「應收票據」?\n①3 月 1 日銷貨,收到客戶交來發票日為 3 月 11 日的支票\n②3 月 1 日銷貨,收到客戶交來到期日為 7 月 1 日的本票\n③3 月 1 日銷貨,收到客戶交來發票日為 3 月 1 日的支票,當日將支票存入銀行\n④3 月 1 日銷貨,簽發到期日為 6 月 1 日的匯票,本日並寄給客戶承兌", "options": ["③", "①②", "②③", "②③④"], "answer": "B", "figure": null, "official": "①②借記應收票據;③借記銀行存款;④借記應收帳款。", "explain": {"concept": "分辨什麼時候是「應收票據」:已收到的遠期支票、本票、已承兌的匯票;即期票據(可立即兌現)當現金處理。", "steps": ["①:支票發票日(發票日=發票日期)是 3 月 11 日,晚於交易日,是「遠期支票」,還不能立刻兌現,視為應收票據。", "②:收到到期日 7 月 1 日的本票,是客戶的付款承諾,記應收票據。", "③:當日開立的支票可立刻存入銀行,視同現金,記「銀行存款」。", "④:只是我方簽發匯票寄給客戶,客戶還沒承兌(同意付款),尚未收到票據,先記「應收帳款」。", "所以只有①②,選(B)。"], "pitfalls": "把「簽發匯票、尚未承兌」誤當成已取得票據;或忘了即期支票視同現金。", "distractors": {"A": "只看到③而忽略①②。", "C": "把當日支票③誤當應收票據,漏掉遠期支票①。", "D": "同樣誤將即期支票③與未承兌的匯票④當應收票據。"}}, "check": "概念題,依官方詳解與應收票據定義確認。", "verified": true, "note": ""}, {"id": "111-1-A-04", "exam": "111-1", "paper": "A", "q": 4, "unit": "二、會計循環及會計帳簿", "topic": "商業會計法-帳簿憑證保存", "stem": "強棒商店採用會計軟體記帳,下列處理哪幾項合乎商業法令?\n①設置普通序時帳簿、特種序時帳簿、總分類帳、明細分類帳等帳簿\n②會計憑證、會計帳簿及財務報表等,以電子方式輸出或以資料儲存媒體儲存\n③各項會計帳簿,除應永久保存或有關未結會計事項者外,至少保存五年\n④各項會計財務報表,除應永久保存或有關未結會計事項者外,至少保存十年", "options": ["①③", "③④", "①②④", "①②③④"], "answer": "C", "figure": null, "official": "各項會計帳簿,除應永久保存或有關未結會計事項者外,至少保存十年(③錯);報表至少保存十年。", "explain": {"concept": "商業會計法對帳簿種類、電子化及保存年限的規定。", "steps": ["①:商業會計法規定帳簿分序時帳簿(普通、特種)與分類帳簿(總分類、明細分類),①正確。", "②:採電子處理會計資料時,憑證、帳簿、報表得以電子方式輸出或以資料儲存媒體儲存,②正確。", "③:保存年限要記清楚:會計憑證 5 年;會計帳簿、財務報表 10 年。③寫帳簿保存五年,錯。", "④:財務報表至少保存十年,正確。", "正確的是①②④,選(C)。"], "pitfalls": "記憶口訣:憑證 5 年、帳簿與報表 10 年。", "distractors": {"A": "認為③帳簿保存五年正確,並漏掉②④。", "B": "把③誤認為正確,且漏掉①②。", "D": "把③「帳簿保存五年」也當成正確。"}}, "check": "概念題,依商業會計法第38條(憑證5年、帳簿及報表10年)確認。", "verified": true, "note": ""}, {"id": "111-1-A-05", "exam": "111-1", "paper": "A", "q": 5, "unit": "四、分錄與日記簿", "topic": "起運點交貨之設備購入", "stem": "一路發商店 2 月 1 日自國外賒購營業用機器設備$80,000,當日起運,交貨條件為起運點交貨。2 月 13 日該設備運達一路發商店,當日該店以發票日為 2 月 23 日的支票支付$80,000,並以現金支付該設備的運費$2,000。有關機器設備的帳務,會計人員所作的分錄下列哪一項正確?", "options": ["2 月 1 日該設備尚未送達,不作分錄", "2 月 13 日分錄借記機器設備成本$82,000", "2 月 13 日分錄借記機器設備成本$80,000、運費$2,000", "2 月 13 日分錄借記應付設備款$80,000、機器設備成本$2,000"], "answer": "D", "figure": null, "official": "2/1 借:機器設備成本 80,000 貸:應付設備款 80,000;2/13 借:應付設備款 80,000、機器設備成本 2,000 貸:應付票據 80,000、現金 2,000。", "explain": {"concept": "起運點交貨:貨物一起運,所有權(與記帳時點)就歸買方;運費屬取得成本,要加入資產成本。", "steps": ["先看交貨條件「起運點交貨」:貨物一離開出口地,所有權就轉給買方,所以 2/1 就要記帳,不是等到送達。", "2/1 分錄:借 機器設備成本 80,000,貸 應付設備款 80,000。→ 選項(A)錯。", "2/13 支付運費$2,000:運費是為了讓設備達到可使用狀態而花的,屬於設備成本,借 機器設備成本 2,000(不是費用)。", "另外 2/13 簽發支票(發票日為2/23,屬遠期支票,記應付票據)清償原賒購款$80,000:借 應付設備款 80,000,貸 應付票據 80,000。", "所以 2/13 借方有「應付設備款 80,000、機器設備成本 2,000」,選(D)。"], "pitfalls": "忘了起運點交貨要在起運日就入帳;也容易把運費當成費用而不是資產成本。", "distractors": {"A": "把交貨日當作入帳日,忽略起運點交貨在起運時所有權即轉移。", "B": "82,000是把80,000與運費合併,但2/1已先入帳,2/13借方要沖銷應付設備款,設備成本只增加運費2,000。", "C": "運費要資本化計入設備成本,不能記為費用;且80,000應沖銷應付設備款。"}}, "check": "分錄題,依官方分錄確認:2/1 借機器設備80,000貸應付設備款80,000;2/13 借應付設備款80,000、機器設備2,000貸應付票據80,000、現金2,000。", "verified": true, "note": ""}, {"id": "111-1-A-06", "exam": "111-1", "paper": "A", "q": 6, "unit": "二、會計循環及會計帳簿", "topic": "會計循環", "stem": "大光公司為上市公司,有關該公司的「會計循環」,下列敘述何者錯誤?", "options": ["會計循環係自分錄、過帳、試算、調整、結帳、編表止之程序且周而復始", "該公司的會計循環期間為一年", "調整程序必定在結帳程序之前", "如果分錄、過帳程序皆正確,省略試算程序不影響財務資料的正確性"], "answer": "B", "figure": null, "official": "上市公司的會計循環期間不是一年,而是每一季就要對外公布財務報表。", "explain": {"concept": "會計循環的步驟與循環期間。", "steps": ["(A) 會計循環從分錄、過帳、試算、調整、結帳到編表,周而復始,正確。", "(B) 一般企業循環期間常為一年,但上市公司依法每一季就要公布財務報表,所以不一定是一年,此敘述錯誤。", "(C) 要先調整(把收入費用歸屬正確期間)再結帳,正確。", "(D) 試算表只是檢查借貸是否平衡的工具,若分錄、過帳都正確,省略試算不影響報表正確性,正確。", "題目問「錯誤」,選(B)。"], "pitfalls": "注意題目問的是「錯誤」;上市公司按季公布報表。", "distractors": {"A": "此敘述正確。", "C": "此敘述正確,調整在結帳之前。", "D": "此敘述正確,試算只是檢查工具。"}}, "check": "概念題,依官方詳解確認。", "verified": true, "note": ""}, {"id": "111-1-A-07", "exam": "111-1", "paper": "A", "q": 7, "unit": "九、財務報表", "topic": "預付款項之內容", "stem": "下列會計項目何者不屬於預付款項?", "options": ["留抵稅額", "用品盤存", "進項稅額", "暫付款"], "answer": "D", "figure": null, "official": "預付款項包含預付費用、用品盤存、進項稅額、留抵稅額等;暫付款屬其他應收款。", "explain": {"concept": "資產負債表上「預付款項」包含哪些科目。", "steps": ["預付款項是「先付出代價、之後才享受服務或取得貨物」的資產。", "用品盤存(尚未用完的文具用品)是預付性質,屬預付款項。", "進項稅額、留抵稅額是先付給政府或供應商、之後可抵銷項稅額的稅款,也歸為預付款項。", "暫付款是暫時代付、日後要收回的款項,性質是向別人請求返還,屬「其他應收款」,不是預付款項。", "題目問「不屬於」,選(D)。"], "pitfalls": "暫付款名稱有「付」字,易誤當預付款項,其實是其他應收款。", "distractors": {"A": "留抵稅額屬預付款項。", "B": "用品盤存屬預付款項。", "C": "進項稅額屬預付款項。"}}, "check": "概念題,依官方答案與資產分類常識確認。", "verified": true, "note": "詳解頁無此題文字說明,說明內容為依會計科目分類常識補充。"}, {"id": "111-1-A-08", "exam": "111-1", "paper": "A", "q": 8, "unit": "一、會計基本概念", "topic": "會計基本假設", "stem": "有關會計基本假設之敘述,下列有幾項正確?\n①「繼續經營假設」主張不動產、廠房及設備應以目前公允價值來列示\n②「企業個體假設」主張業主私人與企業應視為同一經濟個體處理\n③「報導期間假設」主張企業應將經營過程劃分相等的報導期間,以表達企業的財務績效與財務狀況\n④「貨幣評價假設」主張應以貨幣為衡量單位,並依幣值波動調整帳冊金額", "options": ["一項", "二項", "三項", "四項"], "answer": "A", "figure": null, "official": "①應以成本減累計折舊列示;②企業個體假設主張業主私人與企業不能視為同一經濟個體;④貨幣評價假設不須依幣值波動調整。只有③正確。", "explain": {"concept": "會計四大基本假設的內容。", "steps": ["①繼續經營假設:假設企業會一直經營下去,所以設備用「成本-累計折舊」列示,不是用公允價值(清算價值),①錯。", "②企業個體假設:企業與業主是兩個不同的會計個體,業主私人財產與企業要分開,②錯。", "③報導期間假設:把企業壽命分成相等期間(如一年、一季)來編表,③對。", "④貨幣評價假設:以貨幣為衡量單位,並假設幣值穩定,不隨物價調整帳冊,④錯。", "只有③正確,選(A)。"], "pitfalls": "企業個體假設是「分開」不是「合一」;貨幣評價假設不調整幣值。", "distractors": {"B": "以為②或④之一也正確。", "C": "誤把②④中的兩項當正確。", "D": "全選,未辨別各假設的內容。"}}, "check": "概念題,依官方詳解確認。", "verified": true, "note": ""}, {"id": "111-1-A-09", "exam": "111-1", "paper": "A", "q": 9, "unit": "四、分錄與日記簿", "topic": "業主往來之分錄", "stem": "業主以其私人現金支付房租$60,000,其中三分之二應由商店負擔,則分錄為何?", "options": ["借記:租金支出$60,000,貸記:業主往來$60,000", "借記:租金支出$40,000、現金$20,000,貸記:業主往來$60,000", "借記:租金支出$40,000,貸記:業主往來$40,000", "借記:租金支出$60,000,貸記:業主往來$40,000、現金$20,000"], "answer": "C", "figure": null, "official": "商店負擔$60,000×2/3=$40,000:借 租金支出 40,000,貸 業主往來 40,000。", "explain": {"concept": "業主以私人資金代商店付費,店只就屬於店的部分入帳,另一部分是業主自己的開銷。", "steps": ["先算商店應負擔的房租:$60,000×2/3=$40,000。", "剩下1/3($20,000)是業主私人的支出,與商店無關,不入商店帳。", "業主用私人現金替店付$40,000,等於業主對店有一筆投入,記貸方「業主往來」。", "分錄:借 租金支出 40,000,貸 業主往來 40,000。選(C)。", "店並沒有動用自己的現金,所以不會出現「現金」。"], "pitfalls": "不要把業主私人那部分$20,000也入帳;也別把現金扯進來。", "distractors": {"A": "把全部$60,000都入店帳,沒有扣除業主私人負擔的1/3。", "B": "誤以為店出了現金$20,000;實際現金全是業主私人付的。", "D": "同樣全額入帳,並誤把現金$20,000記到貸方。"}}, "check": "python:60000*2/3=40000,與官方相符。", "verified": true, "note": ""}, {"id": "111-1-A-10", "exam": "111-1", "paper": "A", "q": 10, "unit": "十三、存貨", "topic": "進貨退出與折讓(2/10,1/20,n/30)", "stem": "3 月 15 日賒購商品一批,定價$100,000,九折成交,付款條件為 2/10,1/20,n/30。3 月 24 日以現金還清貨款。3 月 26 日退出商品$10,000,並收回現金。則 3 月 26 日分錄為何?", "options": ["借記:現金$10,000,貸記:進貨退出$10,000", "借記:應付帳款$10,000,貸記:進貨退出$10,000", "借記:現金$9,800、進貨折讓$200,貸記:進貨退出$10,000", "借記:應付帳款$9,900、進貨折讓$100,貸記:進貨退出$10,000"], "answer": "C", "figure": null, "official": "3/24 距 3/15 為 9 天,在 10 天內付款享 2%折扣;退貨$10,000 應收回現金$10,000×98%=$9,800,並貸記進貨退出$10,000,借記進貨折讓$200(折扣比例轉回)。", "explain": {"concept": "進貨採總額法:付款享了現金折扣,之後退貨時,退貨的那部分折扣也要沖回。", "steps": ["先看付款日:3/15 賒購,3/24 付款,相隔9天,在10天內,適用 2/10,所以享2%折扣。", "進貨(總額法)金額=$100,000×0.9=$90,000(九折,是商業折扣,已直接減掉)。", "3/26 退貨$10,000:這部分原本付款時已享2%折扣,所以賣方只退還$10,000×98%=$9,800。", "分錄:借 現金 9,800,借 進貨折讓 200(=$10,000×2%,折扣一併沖回),貸 進貨退出 10,000。", "這裡的進貨折讓是現金折扣沖回,也可用「進貨折扣」科目的減項。選(C)。"], "pitfalls": "容易忽略付款日是否在折扣期間(9天在10天內),以及退貨部分折扣要沖回。", "distractors": {"A": "忽略折扣,把退貨全額$10,000當現金收回。", "B": "貨款已付清,不能借記應付帳款。", "D": "已付清貨款,不應借記應付帳款,且折扣金額算錯。"}}, "check": "python:10000*0.98=9800,折讓200,與官方答案(C)相符。", "verified": true, "note": "詳解頁無此題文字說明,說明內容依總額法進貨折扣原理補充。"}, {"id": "111-1-A-11", "exam": "111-1", "paper": "A", "q": 11, "unit": "五、過帳與分類帳", "topic": "過帳與分類帳", "stem": "有關過帳與分類帳的敘述,下列何者錯誤?", "options": ["分類帳的格式,實務上較常採用餘額式", "分類帳每記滿一頁應將每頁的最後一列合計金額過入次頁", "餘額式分類帳每次交易的金額與餘額的金額,不一定相等", "統制帳戶的借餘與明細分類帳中各子目借餘的和,一定相等"], "answer": "D", "figure": null, "official": "統制帳戶的「餘額」與明細分類帳中各子目「餘額」的和,一定相等。", "explain": {"concept": "分類帳格式與統制帳戶、明細分類帳的關係。", "steps": ["(A)實務上分類帳多採餘額式(隨時看得到餘額),正確。", "(B)記滿一頁,把最後一列的合計(餘額)過入次頁,正確。", "(C)餘額式每筆交易金額與累計餘額通常不同,正確。", "(D)統制帳戶與其明細帳「餘額淨額」相等,但明細帳中可能有些子目是貸餘(如某客戶多付款),只比較借餘的和就不一定相等,所以錯誤。", "題目問「錯誤」,選(D)。"], "pitfalls": "關鍵是「淨餘額」相等,而不是「借餘」的和相等。", "distractors": {"A": "此敘述正確。", "B": "此敘述正確。", "C": "此敘述正確。"}}, "check": "概念題,依官方詳解確認。", "verified": true, "note": ""}, {"id": "111-1-A-12", "exam": "111-1", "paper": "A", "q": 12, "unit": "十三、存貨", "topic": "定期盤存制銷貨成本", "stem": "天機商店的商品採定期盤存制,調整前部分帳戶餘額如下:\n存貨$3,000、進貨$135,000、進貨費用$5,000、進貨退出$10,000、進貨折讓$5,000。\n期末盤點商品$4,500,並在調整程序採銷貨成本法調整「銷貨成本」相關帳戶。則調整後試算表下列帳戶餘額何者正確?", "options": ["存貨$4,500", "進貨$135,000", "進貨退出$10,000", "銷貨成本$128,000"], "answer": "A", "figure": null, "official": "銷貨成本=3,000+135,000+5,000-10,000-5,000-4,500=$123,500;調整後進貨、進貨退出等已結轉為0,存貨為期末$4,500。", "explain": {"concept": "定期盤存制「銷貨成本法」調整:把期初存貨、進貨相關帳戶結轉到銷貨成本,並設期末存貨。", "steps": ["銷貨成本法的調整:借 銷貨成本(結轉期初存貨與進貨),貸 存貨、進貨…;再借 存貨(期末盤點),貸 銷貨成本。", "所以調整後試算表的「存貨」帳戶餘額就是期末存貨$4,500。(A)對。", "進貨、進貨費用、進貨退出、進貨折讓,都已被結轉進銷貨成本,餘額為0,(B)(C)錯。", "銷貨成本=期初存貨3,000+進貨135,000+進貨費用5,000-進貨退出10,000-進貨折讓5,000-期末存貨4,500=$123,500,不是128,000,(D)錯。"], "pitfalls": "銷貨成本法調整後,進貨相關帳戶都歸零;記得減掉期末存貨。", "distractors": {"B": "沒有結轉進貨,忘了調整後進貨歸零。", "C": "同上,進貨退出已轉入銷貨成本。", "D": "漏減進貨折讓或期末存貨,算出$128,000。"}}, "check": "python:3000+135000+5000-10000-5000-4500=123500,與官方相符。", "verified": true, "note": ""}, {"id": "111-1-A-13", "exam": "111-1", "paper": "A", "q": 13, "unit": "一、會計基本概念", "topic": "現金基礎與權責基礎損益", "stem": "天方商店本期損益資料如下:\n(1) 應收而未收營業外收入有$10,000\n(2) 應付而未付營業費用有$6,000\n(3) 本期賒銷商品$500,000、現銷商品$300,000\n(4) 本期賒購商品$420,000、現購商品$200,000\n(5) 本期營業費用付現$20,000,其中$2,000 為預付下期的保險費\n(6) 不動產、廠房及設備本期折舊估計為$15,000\n試依上述資料,分別計算採現金基礎、權責基礎時本期淨利為多少?\n\n| | 現金基礎損益 | 權責基礎損益 |\n|---|---|---|\n| (A) | $65,000 | $51,000 |\n| (B) | $80,000 | $151,000 |\n| (C) | $84,000 | $151,000 |\n| (D) | $65,000 | $169,000 |", "options": ["現金基礎$65,000;權責基礎$51,000", "現金基礎$80,000;權責基礎$151,000", "現金基礎$84,000;權責基礎$151,000", "現金基礎$65,000;權責基礎$169,000"], "answer": "B", "figure": null, "official": "現金基礎:300,000-200,000-20,000=$80,000;權責基礎:10,000-6,000+800,000-620,000-18,000-15,000=$151,000。", "explain": {"concept": "現金基礎只看「有沒有收付現金」;權責基礎看「收入賺得、費用發生」。", "steps": ["現金基礎:只計實際收付現金。收入=現銷$300,000(賒銷還沒收到不算);支出=現購$200,000+費用付現$20,000。淨利=300,000-200,000-20,000=$80,000。", "權責基礎:收入=應收營外收入$10,000+銷貨$800,000(賒銷、現銷都算)。", "費用=進貨$620,000(賒購$420,000+現購$200,000,在此視為銷貨成本全數)+營業費用($20,000-預付$2,000=$18,000)+應付費用$6,000+折舊$15,000。", "淨利=(10,000+800,000)-(620,000+18,000+6,000+15,000)=810,000-659,000=$151,000。", "所以現金基礎$80,000、權責基礎$151,000,選(B)。"], "pitfalls": "預付保險費$2,000在權責基礎不是本期費用;折舊雖未付現,權責基礎要認列。", "distractors": {"A": "現金基礎$65,000是把未付現的折舊$15,000也扣掉了,現金基礎不認列折舊;權責基礎$51,000也不對。"}}, "check": "python:現金80,000;權責 10000-6000+800000-620000-18000-15000=151000,與官方相符。", "verified": true, "note": ""}, {"id": "111-1-A-14", "exam": "111-1", "paper": "A", "q": 14, "unit": "七、調整", "topic": "預付保險費調整", "stem": "天祥商店採應計基礎記帳,01 年 10 月 1 日預付兩年期保險費,02 年初帳上「預付保險費」$210,000,則 02 年 12 月 31 日的調整分錄借記應為何?", "options": ["保險費$30,000", "保險費$120,000", "預付保險費$30,000", "預付保險費$120,000"], "answer": "B", "figure": null, "official": "預付兩年(24個月)的保險,02年初剩21個月,每月$210,000÷21=$10,000;02年用掉12個月,調整:借 保險費 120,000,貸 預付保險費 120,000。", "explain": {"concept": "預付費用調整:把已過期間的部分轉為費用。", "steps": ["01/10/1 預付24個月,到 01/12/31 已過3個月,所以 02 年初剩下 21 個月,帳上餘額$210,000。", "每月保險費=$210,000÷21=$10,000。", "02 年全年(12個月)都在保險期間內,已使用的保險費=$10,000×12=$120,000。", "調整分錄:借 保險費 120,000,貸 預付保險費 120,000。", "所以借記是「保險費$120,000」,選(B)。"], "pitfalls": "算每月金額要用「剩餘月數21」,不是24;借方是費用,不是預付保險費。", "distractors": {"A": "只算了3個月(30,000),可能把未使用的3個月當作費用。", "C": "借貸方向搞反,且金額錯。", "D": "借貸方向搞反:預付保險費應該是貸方。"}}, "check": "python:210000/21*12=120000,與官方相符。", "verified": true, "note": ""}, {"id": "111-1-A-15", "exam": "111-1", "paper": "A", "q": 15, "unit": "十二、應收款項", "topic": "備抵損失調整(預期信用減損)", "stem": "天圓商店「應收帳款」年初餘額$50,000、「備抵損失-應收帳款」$750,本年度賒銷$500,000、賒銷帳款收回$360,000(不含本期收回沖銷之帳款)、確定無法收回之帳款$38,000、去年已沖銷的帳款又收回$40,000。年底按去年年底的損失率提列備抵損失。年底預期信用減損損失(利益)之調整分錄為何?", "options": ["貸記預期信用減損利益$470", "借記備抵損失-應收帳款$39,530", "借記預期信用減損損失$1,230", "貸記備抵損失-應收帳款$39,530"], "answer": "A", "figure": null, "official": "年底應收帳款$152,000,損失率=$750÷$50,000=1.5%,應有備抵損失$2,280;調整前貸餘$750-$38,000+$40,000=$2,750,故貸記預期信用減損利益$470。", "explain": {"concept": "先算期末應有的備抵損失,再與調整前餘額比較,差額就是本期調整數。", "steps": ["損失率:去年年底 750÷50,000=1.5%。", "期末應收帳款=50,000+500,000-360,000-38,000=$152,000(沖銷的壞帳要扣掉;收回舊壞帳是先借記應收帳款、再貸記收現,淨額0)。", "期末應有備抵損失=152,000×1.5%=$2,280。", "調整前備抵損失餘額:750(期初貸餘)-38,000(沖銷,借方)+40,000(收回已沖銷,貸方)=貸餘$2,750。", "調整數=2,280-2,750=-470,貸餘太多要減少,所以借 備抵損失 470,貸 預期信用減損利益 470。", "題問「預期信用減損損失(利益)」之調整,答案為貸記利益$470,選(A)。"], "pitfalls": "容易把已沖銷的壞帳收回40,000和沖銷38,000的方向搞反;還有一個重點是得先算出調整前餘額才知道要補提還是迴轉。", "distractors": {}}, "check": "python:750-38000+40000=2750;152000*.015=2280;差額-470,與官方相符。", "verified": true, "note": ""}, {"id": "111-1-A-16", "exam": "111-1", "paper": "A", "q": 16, "unit": "八、結帳", "topic": "結帳後帳戶餘額", "stem": "有關結帳後帳戶的敘述,下列何者錯誤?", "options": ["結帳後的「存貨」帳戶金額一定是期末存貨的金額", "結帳後的「銷貨成本」帳戶一定是借方餘額", "結帳後的「備抵損失」帳戶一定是貸方餘額", "結帳後的「業主往來」帳戶可能是借方餘額也可能是貸方餘額"], "answer": "B", "figure": null, "official": "結帳後的銷貨成本帳戶餘額為零。", "explain": {"concept": "結帳後只有實帳戶有餘額,虛帳戶(損益類)餘額歸零。", "steps": ["銷貨成本是損益項目(虛帳戶),結帳時會結轉到本期損益,結帳後餘額為0,所以(B)「一定是借方餘額」錯誤。", "(A)存貨是資產(實帳戶),調整/結帳後餘額就是期末存貨,正確。", "(C)備抵損失是資產的抵銷項,正常餘額在貸方,正確。", "(D)業主往來若是業主提取多於投入就是借餘,反之貸餘,兩種都可能,在結帳時有的做法會結清,但題目敘述「可能」,正確。", "題目問「錯誤」,選(B)。"], "pitfalls": "虛帳戶(損益項目)結帳後都是0。", "distractors": {"A": "此敘述正確。", "C": "此敘述正確。", "D": "此敘述正確。"}}, "check": "概念題,依官方詳解確認。", "verified": true, "note": ""}, {"id": "111-1-A-17", "exam": "111-1", "paper": "A", "q": 17, "unit": "九、財務報表", "topic": "財務報表編製", "stem": "有關編表的敘述,下列有幾項正確?\n①企業表達財務狀況的報表是資產負債表\n②要了解企業的獲利能力應審閱企業的綜合損益表\n③要了解企業的短期償債能力應審閱企業的資產負債表\n④根據國際會計準則,企業應採權責發生基礎編製財務報表", "options": ["一項", "二項", "三項", "四項"], "answer": "D", "figure": null, "official": "①②③④皆正確。", "explain": {"concept": "各財務報表的功能與編製基礎。", "steps": ["①資產負債表表達某一時點的財務狀況,正確。", "②綜合損益表表達一段期間的經營績效(獲利能力),正確。", "③短期償債能力要看流動資產與流動負債,在資產負債表,正確。", "④國際財務報導準則規定採權責發生基礎(現金流量表除外),正確。", "四項都對,選(D)。"], "pitfalls": "這題四項全對,不要因為覺得「不太可能全對」而猜。", "distractors": {"A": "低估正確項數。", "B": "低估正確項數。", "C": "可能把④誤判為錯。"}}, "check": "概念題,依官方答案與會計準則常識確認。", "verified": true, "note": ""}, {"id": "111-1-A-18", "exam": "111-1", "paper": "A", "q": 18, "unit": "九、財務報表", "topic": "綜合損益表項目計算", "stem": "天雲公司為上櫃公司,經營自行車製造及銷售,本期損益資料如下:\n銷貨毛利率為 40%,銷貨成本$720,000,租金收入$13,000,處分不動產、廠房及設備利益$40,000,推銷費用$20,000,管理費用$30,000,其他費用$3,000,其他損失$600,預期信用減損損失$1,400(應收帳款、應收票據所產生的減損),利息費用$38,000。下列項目金額何者正確?", "options": ["銷貨毛利$432,000", "營業費用$53,000", "營業利益$425,600", "營業外支出$40,000"], "answer": "C", "figure": null, "official": "毛利=$720,000÷(1-40%)×40%=$480,000;營業費用=20,000+30,000+3,000+1,400=$54,400;營業利益=480,000-54,400=$425,600。", "explain": {"concept": "由毛利率反推銷貨收入與毛利,再依分類計算營業費用、營業利益。", "steps": ["毛利率 40% → 銷貨成本率 60%。銷貨收入=720,000÷60%=$1,200,000。", "銷貨毛利=1,200,000-720,000=$480,000(也可算 720,000÷60%×40%)。(A)432,000錯。", "營業費用=推銷費用20,000+管理費用30,000+其他費用3,000+預期信用減損損失1,400=$54,400。(B)53,000錯。", "營業利益=毛利480,000-營業費用54,400=$425,600。(C)對。", "營業外支出=其他損失600+利息費用38,000=$38,600,(D)40,000錯。", "租金收入、處分資產利益屬營業外收入,不影響營業利益。"], "pitfalls": "預期信用減損損失(應收款項產生者)要放營業費用;其他損失與利息費用才是營業外支出。", "distractors": {"A": "432,000=720,000×60%,把成本乘上毛利率以外的比率,忘了先反推銷貨收入。", "B": "53,000不含預期信用減損損失$1,400以外的正確組合,營業費用應含此項而為54,400。"}}, "check": "python:1200000, 毛利480000, 營業費用54400, 營業利益425600, 營業外支出38600,與官方相符。", "verified": true, "note": ""}, {"id": "111-1-A-19", "exam": "111-1", "paper": "A", "q": 19, "unit": "九、財務報表", "topic": "財務比率反推報表項目", "stem": "帝雲公司的資產負債資料如下:\n\n| 資產 | 金額 | 負債 | 金額 |\n|---|---|---|---|\n| 現金及約當現金 | ? | 短期借款 | $100,000 |\n| 應收票據 | 150,000 | 合約負債-流動 | 100,000 |\n| 應收帳款 | 350,000 | 應付帳款 | 400,000 |\n| 其他應收款 | 10,000 | 其他應付款 | 5,000 |\n| 存貨 | ? | 長期借款 | ? |\n| 預付款項 | ? | | |\n| 不動產、廠房及設備 | 790,000 | | |\n| 資產總計 | $2,000,000 | 負債總計 | ? |\n\n已知本年底流動比率為 200%,速動比率為 100%,負債比率為 60%,預付款項是存貨的三分之一。則下列敘述何者正確?", "options": ["現金及約當現金為$100,000", "存貨為$453,750", "營運資金為$600,000", "長期借款為$1,395,000"], "answer": "B", "figure": null, "official": "流動負債$605,000;流動資產=$1,210,000;速動資產=$605,000;存貨=$605,000×3/4=$453,750。", "explain": {"concept": "用流動比率、速動比率、負債比率反推各項金額。", "steps": ["流動負債=短期借款100,000+合約負債100,000+應付帳款400,000+其他應付款5,000=$605,000。", "流動比率200% → 流動資產=605,000×2=$1,210,000;速動比率100% → 速動資產=$605,000。", "速動資產=現金+應收票據+應收帳款+其他應收款=現金+150,000+350,000+10,000=605,000 → 現金=$95,000,(A)錯。", "流動資產-速動資產=存貨+預付款項=605,000,且預付=存貨×1/3 → 存貨×4/3=605,000 → 存貨=$453,750,(B)對。", "營運資金=流動資產-流動負債=1,210,000-605,000=$605,000,(C)600,000錯。", "負債總計=2,000,000×60%=1,200,000;長期借款=1,200,000-605,000=$595,000,(D)錯。"], "pitfalls": "速動資產不含存貨與預付款項;先算流動負債是起點。", "distractors": {"D": "1,395,000=2,000,000-605,000,是把資產總額減流動負債;長期借款要用負債總計1,200,000減流動負債605,000=595,000。"}}, "check": "python:現金95000;存貨453750;營運資金605000;長期借款595000,與官方相符(B)。", "verified": true, "note": ""}, {"id": "111-1-A-20", "exam": "111-1", "paper": "A", "q": 20, "unit": "十、加值型營業稅會計實務", "topic": "預收貨款與銷項稅額", "stem": "星際公司是開立統一發票的一般應稅營業人,10 月營收之中有 2 筆交易:\n(1) 10 月 1 日客戶甲前來訂購商品$30,000,現收訂金$8,000,另加 5%營業稅,開立統一發票給客戶\n(2) 10 月 5 日交付商品如數給客戶甲,並現收剩餘貨款及營業稅\n則下列分錄之會計項目及金額何者正確?", "options": ["10 月 1 日貸記「預收貨款」$8,400", "10 月 5 日借記「現金」$22,000", "10 月 5 日貸記「銷貨收入」$31,500", "10 月 5 日貸記「銷項稅額」$1,100"], "answer": "D", "figure": null, "official": "10/1:借現金8,400,貸預收貨款8,000、銷項稅額400;10/5:借現金23,100、預收貨款8,000,貸銷貨收入30,000、銷項稅額1,100。", "explain": {"concept": "收訂金時就要開發票,營業稅在開立發票時就要認列銷項稅額。", "steps": ["10/1 收訂金$8,000,加5%營業稅=$400,共收現金$8,400。", "分錄:借 現金 8,400,貸 預收貨款 8,000、銷項稅額 400。(A)貸記預收貨款$8,400錯,應為$8,000。", "10/5 交貨:總價30,000,稅額應為30,000×5%=1,500,其中400已在10/1認列,本次再認列1,100。", "收現金=30,000+1,500-8,400=$23,100。(B)22,000錯。", "分錄:借 現金 23,100、預收貨款 8,000,貸 銷貨收入 30,000、銷項稅額 1,100。", "(C)銷貨收入是$30,000,不是31,500。(D)銷項稅額$1,100正確。"], "pitfalls": "預收款時營業稅已開票,稅額不能重複認列;銷貨收入不含稅。", "distractors": {"A": "把含稅金額$8,400都當預收貨款,稅額$400要貸記銷項稅額。", "B": "22,000是沒有考慮營業稅的差額(30,000-8,000)。", "C": "31,500是含稅總價,銷貨收入不含稅。"}}, "check": "python:8000*1.05=8400;30000*5%-400=1100;現金23100;與官方相符。", "verified": true, "note": ""}, {"id": "111-1-A-21", "exam": "111-1", "paper": "A", "q": 21, "unit": "十、加值型營業稅會計實務", "topic": "得扣抵進項稅額", "stem": "巴斯公司是開立統一發票的一般應稅營業人,本期支付進項明細如下表:\n\n| 項目 | 支付金額(未含營業稅) |\n|---|---|\n| (1) 購買商品 | $1,000,000 |\n| (2) 支付員工薪資 | 40,000 |\n| (3) 承租給外籍移工宿舍之水電、瓦斯 | 20,000 |\n| (4) 購買救援物資捐贈給外國政府 | 5,000 |\n| (5) 支付自用乘人小汽車之修理費 | 4,000 |\n| (6) 支付招待客戶之旅費、住宿費 | 6,000 |\n\n則本期得扣抵銷項稅額之進項稅額為多少?", "options": ["$50,200", "$50,450", "$51,200", "$52,250"], "answer": "A", "figure": null, "official": "得扣抵者為(1)、(5):($1,000,000+$4,000)×5%=$50,200。", "explain": {"concept": "哪些進項稅額可以扣抵銷項稅額,哪些不得扣抵。", "steps": ["(1)購買商品,供營業用,可扣抵。", "(2)薪資不是向營業人購買貨物或勞務,沒有進項稅額。", "(3)承租給外籍移工宿舍之水電瓦斯,屬員工個人使用且與營業無直接關聯,不得扣抵。", "(4)捐贈給「外國」政府的救援物資,不是營業用,不得扣抵(捐贈給本國政府才可能不同)。", "(5)自用乘人小汽車的修理費,可扣抵(購買乘人小汽車本身不得扣抵,但修理費可)。", "(6)招待客戶的旅費住宿費屬交際應酬,不得扣抵。", "可扣抵金額=(1,000,000+4,000)×5%=$50,200,選(A)。"], "pitfalls": "購買「乘人小汽車」不能扣抵,但「修理費」可以;交際應酬與員工個人使用都不能扣抵。", "distractors": {"B": "50,450=(1,000,000+4,000+5,000)×5%,多算了(4)捐贈外國政府的物資,不得扣抵。", "C": "51,200=(1,000,000+4,000+20,000)×5%,多算了(3)移工宿舍水電,不得扣抵。"}}, "check": "python:(1000000+4000)*0.05=50200,與官方相符。", "verified": true, "note": "詳解僅列(3)(4)不得扣抵原因,(2)(6)不得扣抵的說明為補充。"}, {"id": "111-1-A-22", "exam": "111-1", "paper": "A", "q": 22, "unit": "十、加值型營業稅會計實務", "topic": "營業稅申報書(401)稅額計算", "stem": "光年公司是開立統一發票的一般應稅營業人,本期銷項、進項資料如下(以下金額均未含稅):\n(1) 非經海關出口外銷$100,000,已檢附證明文件\n(2) 國內銷貨開立三聯式發票$1,420,000、國內銷貨退回及折讓$20,000\n(3) 一般進貨及費用$2,000,000,取得統一發票。另向小規模營業人購買餐點$2,000\n(4) 購買自用載貨卡車$700,000、機器設備$100,000,均取得統一發票\n(5) 上期累積留抵稅款$10,000\n則光年公司本期《營業人銷售額與稅額申報書(401)》的部分「稅額計算」:\n\n| 代號 | 項目 | 稅額 |\n|---|---|---|\n| 12 | 本期(月)申報留抵稅額 | 甲 |\n| 13 | 得退稅限額合計 | 乙 |\n| 14 | 本期(月)應退稅額 | 丙 |\n| 15 | 本期(月)累積留抵稅額 | 丁 |\n\n上列表格中甲乙丙丁的金額,何者正確?", "options": ["甲:$70,000", "乙:$40,000", "丙:$45,000", "丁:$25,000"], "answer": "C", "figure": null, "official": "甲=$80,000;乙=$45,000;丙=$45,000;丁=$35,000。", "explain": {"concept": "營業稅申報書中留抵稅額、得退稅限額與應退稅額的計算。", "steps": ["進項稅額=($2,000,000+$700,000+$100,000)×5%=$140,000(向小規模營業人購買餐點無進項稅額)。", "銷項稅額=($1,420,000-$20,000)×5%=$70,000(外銷零稅率,稅額為0)。", "甲(申報留抵稅額)=(140,000+上期累積留抵10,000)-70,000=$80,000,(A)70,000錯。", "乙(得退稅限額)=(外銷100,000+載貨卡車700,000+機器設備100,000)×5%=$45,000,(B)40,000錯。", "丙(應退稅額)=甲80,000與乙45,000取較小者=$45,000,(C)對。", "丁(累積留抵)=甲-丙=80,000-45,000=$35,000,(D)25,000錯。"], "pitfalls": "得退稅限額只看零稅率銷售額與購買固定資產(機器、載貨卡車等)的進項;應退稅額取兩者之小。", "distractors": {"A": "$70,000是銷項稅額,或漏掉上期累積留抵,甲應為80,000。"}}, "check": "python:進項140,000;銷項70,000;甲=80,000;乙=45,000;丙=45,000;丁=35,000,與官方相符。", "verified": true, "note": ""}, {"id": "111-1-A-23", "exam": "111-1", "paper": "A", "q": 23, "unit": "六、試算與試算表", "topic": "試算表與錯誤更正", "stem": "福爾商店每月底作帳務試算,會計人員摩斯在 10 月 31 日進行試算時,餘額式試算表的借貸方合計不相等,經查核發現下列四項錯誤:\n(1) 10 月 5 日現購商品$4,000,作分錄時誤記為現銷商品$4,000\n(2) 10 月 11 日帳款付現$1,000,過帳時誤入應付帳款帳戶之貸方\n(3) 10 月 28 日現收租金$15,000,作分錄時誤記為現收佣金$1,500\n(4) 10 月 30 日客戶交來現金償還貨款$9,800,作分錄時貸方金額誤記為$8,900\n有關試算與試算表的敘述,下列有幾項正確?\n①試算表不必對外公布\n②上列四項錯誤中,記入日記簿的更正分錄共有三項\n③第(1)項錯誤,將更正分錄記入日記簿時,該分錄的日期應記為 10 月 5 日\n④第(2)項錯誤,若未更正,將導致「應付帳款」帳戶餘額少計$2,000", "options": ["一項", "二項", "三項", "四項"], "answer": "A", "figure": null, "official": "①正確;②需記入日記簿的更正分錄只有(1)(3)兩項;③日期應記10月31日;④(2)未更正將使應付帳款餘額「多」計$2,000。", "explain": {"concept": "錯誤更正:分錄(記帳)錯誤要寫更正分錄;過帳錯誤只要在分類帳更正。", "steps": ["①試算表是內部檢查用的工具,不必對外公布,正確。", "②(1)(3)是分錄的科目錯誤,要用更正分錄記入日記簿;(2)是過帳錯誤、(4)是借貸金額不符的錯誤,官方詳解(見第24題表)都用「註銷更正」(直接在帳上更正),不必寫更正分錄。所以記入日記簿的更正分錄只有(1)(3)兩項,②說三項,錯。", "③更正分錄應記在發現錯誤的日期,也就是 10 月 31 日,不是原交易日10月5日,③錯。", "④(2)付現應借記應付帳款,卻誤貸記,所以應付帳款餘額被多計$2,000(借貸差1,000+1,000),④錯。", "只有①正確,選(A)。"], "pitfalls": "更正分錄記入日記簿的日期是「發現日」;過帳錯誤只在分類帳更正。", "distractors": {"B": "誤以為②或④之一也正確。", "C": "誤以為②③④中兩項正確。", "D": "全選,未逐項判斷。"}}, "check": "概念題,依官方詳解確認:②共兩項(1)(3);③10/31;④多計。", "verified": true, "note": ""}, {"id": "111-1-A-24", "exam": "111-1", "paper": "A", "q": 24, "unit": "六、試算與試算表", "topic": "餘額式試算表更正後借貸合計", "stem": "(承第23題題幹)若餘額式試算表更正前的借方餘額合計數為$800,000,則更正前貸方餘額合計數為多少?", "options": ["$787,600", "$795,100", "$801,100", "$808,600"], "answer": "C", "figure": null, "official": "更正後借貸皆為$808,600;更正前貸方=808,600-(−4,000−2,000+13,500)=$801,100。", "explain": {"concept": "用「更正後借貸相等」反推更正前的貸方合計。", "steps": ["先把四項錯誤對借方、貸方餘額的影響整理成「更正數」。", "(1)現購誤記現銷:借方 進貨+4,000、現金-8,000(合計-4,000);貸方 銷貨收入-4,000。", "(2)過帳錯:應付帳款應借記$1,000卻貸記,貸方餘額多了$2,000,註銷更正:貸方 應付帳款-2,000,借方無變動。", "(3)租金$15,000誤記佣金$1,500:借方 現金+13,500;貸方 佣金收入-1,500、租金收入+15,000(合計+13,500)。", "(4)註銷更正:應收帳款貸方應為9,800卻記8,900,少貸$900,更正後應收帳款借方餘額-900。", "借方合計更正後=800,000-4,000+13,500-900=$808,600。", "貸方更正後也是$808,600,所以更正前貸方=808,600-(-4,000-2,000+13,500)=808,600-7,500=$801,100。選(C)。"], "pitfalls": "要分清楚是借方還是貸方餘額被更正;(4)雖寫在分錄金額,但影響的是應收帳款餘額。", "distractors": {"D": "808,600是更正後的借方與貸方合計,不是更正前貸方。"}}, "check": "python:借方 800000-4000+13500-900=808600;貸方 808600-(-4000-2000+13500)=801100,與官方相符。", "verified": true, "note": ""}, {"id": "111-2-A-01", "exam": "111-2", "paper": "A", "q": 1, "unit": "一、會計基本概念", "topic": "會計制度選擇", "stem": "大大從法律系畢業並順利通過律師國考後,他想要跟小小一起成立聯合律師事務所,兩人共同出資、共同經營並共同負擔損益,請問下列針對「聯合律師事務所」採用之會計處理,何者正確?", "options": ["採用合夥會計且屬於非營利事業會計", "採用公司會計且屬於非營利事業會計", "採用合夥會計且屬於營利事業會計", "採用公司會計且屬於營利事業會計"], "answer": "C", "figure": null, "official": "兩人共同出資、經營、負擔損益為合夥組織,屬營利事業。", "explain": {"concept": "依組織型態分辨採用獨資、合夥或公司會計;依目的分辨營利或非營利。", "steps": ["看「兩人共同出資、共同經營、共同負擔損益」,這是合夥的特徵,所以用合夥會計(不是公司,公司是股東出資、由董事會經營)。", "律師事務所提供服務、目的是賺取利潤,所以屬於營利事業會計,不是政府或慈善機構那類非營利。", "合夥會計 + 營利事業會計,選 C。"], "pitfalls": "不要因為「律師」是專門職業就以為是非營利;只要以營利為目的就是營利事業。", "distractors": {"A": "合夥沒錯,但律師事務所是賺錢的,不是非營利。", "B": "兩人共同經營不是公司組織,而且也不是非營利。", "D": "營利沒錯,但不是公司組織(股份有限公司有股東與董事會)。"}}, "check": "概念題:依組織型態與營業目的雙重判斷,與官方答案 C 一致。", "verified": true, "note": ""}, {"id": "111-2-A-02", "exam": "111-2", "paper": "A", "q": 2, "unit": "二、會計循環及會計帳簿", "topic": "會計憑證種類", "stem": "會計憑證是指證明會計事項發生的經過及處理人員的責任,可作為入帳參考依據之各項單據憑證。有關會計憑證的敘述,下列何者錯誤?", "options": ["現銷商品而開立之發票,屬於對外憑證並應編製現金收入傳票", "以現金支付租金而收取之收據,屬於外來憑證並應編製現金支出傳票", "銷貨退回之退貨單,屬於外來憑證,可作為記帳憑證之依據", "公司開立之個人員工薪資單,屬於內部憑證,可作為記帳憑證之依據"], "answer": "D", "figure": null, "official": "(D) 公司開立之個人員工薪資單屬於「對外憑證」。", "explain": {"concept": "原始憑證依來源分為外來憑證、對外憑證、內部憑證。", "steps": ["外來憑證:別人開給我們的(例如收到的收據、進貨發票)。", "對外憑證:我們開給別人的(例如銷貨發票、薪資單給員工)。", "內部憑證:公司內部自己使用、不對外的單據(例如內部請購單、領料單)。", "公司開立薪資單給員工,是交給「員工」(公司以外的人)的,屬於對外憑證,所以 D 說它是內部憑證是錯的。"], "pitfalls": "薪資單雖是公司自己製作,但交給員工,所以是對外憑證,別被「公司開立」誤導成內部憑證。", "distractors": {"A": "開發票給客人是對外憑證,現金收入要做現金收入傳票,敘述正確。", "B": "收到的租金收據是別人開給我們的,屬外來憑證,支出要做現金支出傳票,敘述正確。", "C": "官方判定此敘述正確(退貨單可作記帳依據)。"}}, "check": "概念題:官方詳解指出 D 為對外憑證,與常識一致。", "verified": true, "note": ""}, {"id": "111-2-A-03", "exam": "111-2", "paper": "A", "q": 3, "unit": "一、會計基本概念", "topic": "會計基本假設", "stem": "下列敘述依序應適用於哪一項會計基本假設?\n①企業替業主代墊電話費,借記「業主往來」\n②企業將不動產、廠房及設備之成本依預期使用年限進行分攤\n③報導期間終了須進行調整,結算損益\n④企業財務報表中明確區分流動資產及非流動資產之理論依據", "options": ["企業個體假設、報導期間假設、報導期間假設、權責發生基礎", "企業個體假設、繼續經營假設、權責發生基礎、繼續經營假設", "權責發生基礎、繼續經營假設、報導期間假設、權責發生基礎", "權責發生基礎、報導期間假設、權責發生基礎、繼續經營假設"], "answer": "B", "figure": null, "official": "①企業個體 ②繼續經營 ③權責發生基礎 ④繼續經營。", "explain": {"concept": "會計基本假設:企業個體、繼續經營、報導期間(會計期間)、權責發生基礎等,要把情境對到正確的假設。", "steps": ["①業主與企業的帳要分開,替業主代墊要記「業主往來」,是企業個體假設。", "②設備成本分多年攤提(折舊),是假設企業會持續經營、用到耐用年限,屬繼續經營假設。", "③期末要調整後結算損益,是為了讓收入與費用歸屬正確期間,屬權責發生基礎。", "④有「流動/非流動」之分,是假設企業會繼續營業、資產會在未來正常營業循環中使用或變現,屬繼續經營假設。", "依序是:企業個體、繼續經營、權責發生、繼續經營,選 B。"], "pitfalls": "②折舊容易誤選權責發生(配合原則);③「報導期間終了」字眼容易誤選報導期間假設,但「調整」的理論基礎是權責發生。", "distractors": {"A": "②不是報導期間,③也不是報導期間(重複),④也不對。", "C": "①不是權責發生,是企業個體。", "D": "①不是權責發生,②也不是報導期間。"}}, "check": "概念題:對照官方答案 B,逐項判斷一致。", "verified": true, "note": ""}, {"id": "111-2-A-04", "exam": "111-2", "paper": "A", "q": 4, "unit": "九、財務報表", "topic": "資產負債分類計算", "stem": "星星公司年底調整後試算表列示資產及負債類帳戶餘額如下:\n\n| 帳戶 | 金額 | 帳戶 | 金額 | 帳戶 | 金額 |\n|---|---|---|---|---|---|\n| 現金 | $10,000 | 進項稅額 | $4,800 | 土地成本 | $2,000,000 |\n| 應收帳款 | 7,600 | 銷項稅額 | 6,200 | 房屋及建築成本 | 800,000 |\n| 備抵損失-應收帳款 | 2,600 | 存入保證金 | 3,800 | 累計折舊 | 250,000 |\n| 存貨 | 3,500 | 預付貨款 | 2,500 | 銀行借款 | 40,000 |\n| 代收款 | 2,200 | 預收貨款 | 3,000 | 應付公司債 | 650,000 |\n\n下列敘述何者錯誤?", "options": ["流動資產為$25,800", "非流動資產為$2,550,000", "流動負債為$55,200", "負債總額為$705,200"], "answer": "C", "figure": null, "official": "流動負債=銷項稅額6,200+銀行借款40,000+代收款2,200+預收貨款3,000=$51,400,故(C)錯誤。", "explain": {"concept": "把各帳戶分成流動資產、非流動資產、流動負債、非流動負債,再分別加總;備抵損失與累計折舊是資產的減項。", "steps": ["流動資產:現金10,000 + 應收帳款7,600 - 備抵損失2,600 + 存貨3,500 + 進項稅額4,800 + 預付貨款2,500 = $25,800(A 正確)。", "非流動資產:土地2,000,000 + 房屋及建築800,000 - 累計折舊250,000 = $2,550,000(B 正確)。", "流動負債:銷項稅額6,200 + 銀行借款40,000 + 代收款2,200 + 預收貨款3,000 = $51,400,不是55,200,所以 C 錯。", "非流動負債:存入保證金3,800 + 應付公司債650,000 = 653,800。負債總額 = 51,400 + 653,800 = $705,200(D 正確)。"], "pitfalls": "進項稅額屬資產、銷項稅額屬負債;備抵損失、累計折舊要扣除而不是加。存入保證金、應付公司債為非流動負債。", "distractors": {"A": "此選項計算正確,不是答案。", "B": "此選項計算正確,不是答案。", "D": "此選項計算正確,不是答案。"}}, "check": "python 計算:流動資產25,800;非流動2,550,000;流動負債51,400;負債705,200,與官方一致。", "verified": true, "note": ""}, {"id": "111-2-A-05", "exam": "111-2", "paper": "A", "q": 5, "unit": "二、會計循環及會計帳簿", "topic": "日記簿與分類帳", "stem": "有關下列日記簿及分類帳之敘述,有哪幾項正確?\n①日記簿以「交易」為主體,依交易先後發生順序記載\n②分類帳以「會計項目」為主體,為編製財務報表之依據\n③會計事項應按發生次序逐日登載於日記簿中,最遲不得超過三個月\n④日記簿設有日頁欄,分類帳設有類頁欄,兩者於過帳時相互勾稽\n⑤日記簿及分類帳簿應於年度決算程序辦理終了之後至少保存十年", "options": ["①②③", "①②④", "①②⑤", "②③⑤"], "answer": "C", "figure": null, "official": "③最遲不得超過「兩個月」;④日記簿設有「類頁欄」,分類帳設有「日頁欄」。", "explain": {"concept": "日記簿(序時帳簿)與分類帳(分類帳簿)的特性及商業會計法相關規定。", "steps": ["①日記簿按交易發生先後順序記錄,正確。", "②分類帳按會計項目分類彙總,是編製報表的依據,正確。", "③商業會計法規定登帳最遲不得超過「兩個月」,不是三個月,錯誤。", "④日記簿的欄位是「類頁」(記載過入分類帳第幾頁),分類帳的欄位是「日頁」(記載來自日記簿第幾頁),題目說反了,錯誤。", "⑤帳簿保存十年(自年度決算程序辦理終了後),正確。", "正確的是①②⑤,選 C。"], "pitfalls": "記憶口訣:日記簿寫「類頁」、分類帳寫「日頁」,是互相指向對方。三個月 vs 兩個月容易記錯。", "distractors": {"A": "把③(三個月)當成正確。", "B": "把④(日頁/類頁說反)當成正確,同時漏掉⑤。", "D": "漏掉①,又誤把③當成正確。"}}, "check": "概念題:對照官方詳解(③兩個月、④說反)逐項確認。", "verified": true, "note": ""}, {"id": "111-2-A-06", "exam": "111-2", "paper": "A", "q": 6, "unit": "四、分錄與日記簿", "topic": "交易分錄判斷", "stem": "下列記載於 A 商店日記簿中的交易事項,何者錯誤?", "options": ["銷售商品$2,000,半數暫欠、半數收現\n借:現金  1,000\n借:應收帳款  1,000\n  貸:銷貨收入  2,000", "年底前,A 商店應收取 B 商店之佣金 1,500,B 商店應收取 A 商店租金 2,000,雙方同意互抵,差額補足現金\n借:租金支出  2,000\n  貸:佣金收入  1,500\n  貸:現金  500", "業主提取商品自用,以成本$500 入帳,採定期盤存制\n借:業主往來  500\n  貸:進貨  500", "結帳後,以現金收回溢付保險費$1,000\n借:現金  1,000\n  貸:保險費  1,000"], "answer": "D", "figure": null, "official": "(D) 結帳後保險費帳戶已結清,應貸記「本期損益」$1,000。", "explain": {"concept": "結帳後,收益費損類(暫時性)帳戶已結清為零;結帳後若再發生與其有關之收回,不能再記入已結清的帳戶。", "steps": ["(A)賒銷一半、現收一半:借現金1,000、應收帳款1,000,貸銷貨收入2,000,借貸相等,正確。", "(B)互抵:應付租金2,000以應收佣金1,500抵銷,不足500付現,借租金支出2,000,貸佣金收入1,500、現金500,正確。", "(C)定期盤存制下業主提用商品,借業主往來、貸進貨,正確。", "(D)「結帳後」保險費帳戶已經結清歸零,收回溢付保險費時不能再貸記保險費,官方答案為借:現金1,000、貸:本期損益1,000,所以 D 錯誤。"], "pitfalls": "關鍵是題目寫的「結帳後」。若是結帳前才收回,貸記保險費是對的。", "distractors": {"A": "此分錄正確。", "B": "此分錄正確,借貸各2,000。", "C": "此分錄正確。"}}, "check": "概念題:對照官方詳解(貸:本期損益)一致。", "verified": true, "note": ""}, {"id": "111-2-A-07", "exam": "111-2", "paper": "A", "q": 7, "unit": "六、試算與試算表", "topic": "試算表概念", "stem": "有關試算表的敘述,下列何者正確?", "options": ["試算是指運用「借貸法則」協助檢驗分錄與過帳是否正確無誤的會計程序", "過帳時誤將「進貨費用」借方$3,000 過入「運費」借方$3,000,此錯誤無法從試算表發現", "合計式試算表係依「等量加等量,其和相等」的原理,列示帳戶借方或貸方餘額", "若試算時發現「已過帳且影響借貸平衡之錯誤」,應以分錄更正法進行更正"], "answer": "B", "figure": null, "official": "(A)應為借貸平衡原理;(C)合計式列示借貸方總額;(D)應以註銷更正法更正。", "explain": {"concept": "試算表的原理、種類與錯誤更正方式。", "steps": ["(A)試算的依據是「借貸平衡原理」(借方合計=貸方合計),不是借貸法則,錯誤。", "(B)借方記錯帳戶(兩個都是借方、金額同),借貸總額仍相等,試算表無法發現,正確。", "(C)合計式(總額式)試算表列示各帳戶借方、貸方的「總額」;列示餘額的是餘額式,錯誤。", "(D)已過帳且影響借貸平衡的錯誤,應用「註銷更正法」;分錄更正法用於不影響借貸平衡的錯誤,錯誤。"], "pitfalls": "試算表只能檢查借貸是否相等;記錯帳戶、漏記整筆、同額重複等錯誤都查不出來。", "distractors": {"A": "把「借貸平衡原理」誤說成「借貸法則」。", "C": "把合計式(總額)和餘額式搞混。", "D": "把兩種更正方式用法對調:影響平衡用註銷更正法。"}}, "check": "概念題:對照官方詳解一致。", "verified": true, "note": ""}, {"id": "111-2-A-08", "exam": "111-2", "paper": "A", "q": 8, "unit": "六、試算與試算表", "topic": "錯誤對試算表影響", "stem": "西方公司編製試算表時,發現兩項錯誤:①日記簿中賒銷商品$2,000,誤以現銷$20,000 入帳,②應收帳款借方重複過帳$9,000。請問此兩項錯誤對試算表之影響,下列何者正確?", "options": ["若為餘額式試算表,則借方合計數比正確合計數多計$27,000", "若為餘額式試算表,則貸方合計數比正確合計數少計$18,000", "若為總額式試算表,則借貸雙方合計數依然平衡且皆多計$27,000", "若為總額式試算表,則借方合計數比貸方合計數多計$18,000"], "answer": "A", "figure": null, "official": "①借貸均多$18,000;②只有借方多$9,000。", "explain": {"concept": "先找出每個錯誤對借方、貸方各多或少多少,再分別看餘額式與總額式。", "steps": ["正確分錄:借應收帳款2,000、貸銷貨收入2,000。錯誤①記成借現金20,000、貸銷貨收入20,000,所以借方多記 20,000-2,000 = 18,000,貸方也多記 20,000-2,000 = 18,000(借貸同時多,仍平衡)。", "錯誤②:應收帳款借方重複過帳9,000,只有借方多9,000。", "合併:借方多 18,000 + 9,000 = 27,000;貸方多 18,000。借貸不平衡,借方比貸方多9,000。", "餘額式(每個帳戶只列餘額):借方合計多27,000、貸方合計多18,000,借方比貸方多9,000,所以 A「借方多計27,000」正確。", "總額式:同樣借方多27,000、貸方多18,000,不平衡,借方比貸方多9,000(C、D 都不對)。", "注意:B 說貸方「少計」18,000,但實際是「多計」,錯誤。"], "pitfalls": "算影響時要「借方、貸方各算一次」;別把兩個錯誤混成一個數字。C 說「依然平衡」忽略了第②項只影響借方。", "distractors": {"B": "方向說反,貸方是多計不是少計。", "C": "忽略第②項只影響借方,所以不平衡。", "D": "借貸差額應是9,000(27,000-18,000),不是18,000。"}}, "check": "python:借方多=18,000+9,000=27,000;貸方多=18,000;差=9,000,與官方一致。", "verified": true, "note": ""}, {"id": "111-2-A-09", "exam": "111-2", "paper": "A", "q": 9, "unit": "十六、負債", "topic": "應付票據利息", "stem": "公司於 X2 年 8 月 1 日因賒購簽發一年期附息票據$40,000,月息三厘,本息於到期時一次支付,下列敘述何者錯誤?", "options": ["X2 年底之調整分錄,應借:利息費用$600、貸:應付利息$600", "X2 年底調整所產生之利息費用,於結帳時,會使權益減少", "X3 年票據到期時之分錄,應借記「應付票據$40,000、應付利息$600、利息費用$600」", "票據到期時,貸方「現金」之金額為本金加票據期間之利息費用"], "answer": "C", "figure": null, "official": "X3 年利息費用應為$840(1/1~8/1共7個月),不是$600。", "explain": {"concept": "月息三厘=月利率0.3%;利息=本金×月利率×月數。票據期間為 X2/8/1~X3/8/1,X2 年佔5個月、X3 年佔7個月。", "steps": ["X2 年(8~12月共5個月)利息 = $40,000 × 0.3% × 5 = $600,所以調整分錄:借利息費用600、貸應付利息600(A 正確)。", "結帳時利息費用(費用)轉入本期損益,使本期損益減少、最終使權益減少(B 正確)。", "X3 年(1~7月共7個月)利息費用 = $40,000 × 0.3% × 7 = $840,不是600,所以到期分錄應是:借應付票據40,000、應付利息600、利息費用840;貸現金41,440。C 錯誤。", "到期現金 = 本金40,000 + 全年利息(600+840)= $41,440,也就是「本金加票據期間之利息費用」(D 正確)。"], "pitfalls": "X3 年的利息不要跟 X2 年的 600 搞混:到期當年只有 1/1~8/1 共7個月。", "distractors": {"A": "此敘述正確。", "B": "此敘述正確(費用結入本期損益,減少權益)。", "D": "此敘述正確。"}}, "check": "python:40,000×0.003×5=600;×7=840;現金=41,440,與官方一致。", "verified": true, "note": ""}, {"id": "111-2-A-10", "exam": "111-2", "paper": "A", "q": 10, "unit": "八、結帳", "topic": "結帳程序", "stem": "有關結帳程序,下列敘述何者錯誤?", "options": ["結帳時若「本期損益」帳戶產生貸方餘額,係代表本期有淨利產生", "獨資企業若發生淨利,結帳分錄應借:本期損益、貸:業主往來", "完成結帳工作後,所有費損類與收益類的帳戶餘額都會歸零", "「預期信用減損損失」與「備抵損失」二帳戶會同時出現在結帳後試算表中"], "answer": "D", "figure": null, "official": "預期信用減損損失為費用,結帳後歸零,不會出現在結帳後試算表。", "explain": {"concept": "結帳是把暫時性帳戶(收益、費損)結清,結帳後試算表只剩永久性帳戶(資產、負債、權益)。", "steps": ["(A)收益結入本期損益(貸方)、費用結入(借方),貸方餘額表示收益>費用,即淨利,正確。", "(B)獨資企業淨利結入業主權益,分錄借本期損益、貸業主往來(或業主資本),正確。", "(C)收益及費損帳戶結帳後餘額皆為零,正確。", "(D)預期信用減損損失是費用類,結帳後已結清為零,不會出現在結帳後試算表;只有「備抵損失」(資產減項,永久性帳戶)會出現,所以 D 錯誤。"], "pitfalls": "記住:費用/收益=暫時性帳戶,結帳後歸零;資產、負債、權益=永久性帳戶,會留在結帳後試算表。", "distractors": {"A": "敘述正確。", "B": "敘述正確。", "C": "敘述正確。"}}, "check": "概念題:對照官方詳解一致。", "verified": true, "note": ""}, {"id": "111-2-A-11", "exam": "111-2", "paper": "A", "q": 11, "unit": "九、財務報表", "topic": "財務報表內容", "stem": "有關綜合損益表、權益變動表、資產負債表及現金流量表之敘述,下列何者錯誤?", "options": ["除資產負債表為特定日期之靜態報表外,其餘報表之報導時間皆為特定期間", "財務報表僅包含附註揭露,如存貨明細表、銷貨成本表等附表非屬財務報表之內容", "綜合損益表與資產負債表中的「本期損益」數額相同", "現金流量表應列明來自營業活動、投資活動及籌資活動所產生之現金流量變動"], "answer": "B", "figure": null, "official": "四大報表及其附表、附註揭露皆屬於財務報表之內容。", "explain": {"concept": "財務報表的組成:四大報表、附表(明細表)及附註。", "steps": ["(A)資產負債表是某一時點(靜態),其餘三表是一段期間(動態),正確。", "(B)財務報表不只有附註,還包含四大報表與其附表,存貨明細表、銷貨成本表等附表也屬財務報表內容,所以說「僅包含附註」「附表非屬財務報表」是錯的。", "(C)本期損益同時出現在綜合損益表與資產負債表(結入權益),數額相同,正確。", "(D)現金流量表分營業、投資、籌資三大活動,正確。"], "pitfalls": "「僅」「非屬」這類絕對字眼要小心;題目常用來設陷阱。", "distractors": {"A": "敘述正確。", "C": "敘述正確。", "D": "敘述正確。"}}, "check": "概念題:對照官方詳解一致。", "verified": true, "note": ""}, {"id": "111-2-A-12", "exam": "111-2", "paper": "A", "q": 12, "unit": "九、財務報表", "topic": "損益計算", "stem": "公司本年度損益資料包括:\n①銷貨毛利率為 30%\n②營業費用為$400,000\n③無營業外支出,營業外收入$120,000\n④所得稅率 20%\n⑤稅後淨利為銷貨淨額的 16%\n則下列敘述何者正確?", "options": ["銷貨淨額為$2,000,000", "銷貨毛利為$840,000", "營業利益為$560,000", "稅後淨利為$576,000"], "answer": "B", "figure": null, "official": "設銷貨淨額x,(0.3x-400,000+120,000)×(1-20%)=0.16x,x=2,800,000。", "explain": {"concept": "稅前淨利 = 毛利 - 營業費用 + 營業外收入;稅後 = 稅前 ×(1-稅率)。用代數解出銷貨淨額。", "steps": ["設銷貨淨額為 x,毛利 = 0.3x。", "稅前淨利 = 0.3x - 400,000 + 120,000 = 0.3x - 280,000。", "稅後淨利 = (0.3x - 280,000)×(1-0.2) = 0.24x - 224,000,又等於 0.16x。", "0.24x - 224,000 = 0.16x → 0.08x = 224,000 → x = $2,800,000。", "毛利 = 2,800,000×30% = $840,000(B 正確)。", "營業利益 = 840,000 - 400,000 = $440,000(C 的560,000錯);稅後淨利 = 2,800,000×16% = $448,000(D 的576,000錯)。"], "pitfalls": "營業外收入要加在營業利益之後、稅前;所得稅是對稅前淨利課徵,不是對毛利。", "distractors": {"A": "2,000,000 不是解出來的銷貨淨額。", "C": "營業利益是毛利扣營業費用,不含營業外收入,應為440,000。", "D": "稅後淨利應為銷貨淨額×16%=448,000。"}}, "check": "python 解 x=2,800,000;毛利840,000;營業利益440,000;稅後淨利448,000,與官方一致。", "verified": true, "note": ""}, {"id": "111-2-A-13", "exam": "111-2", "paper": "A", "q": 13, "unit": "九、財務報表", "topic": "流動比率變動", "stem": "若流動比率為 3,下列哪項交易的發生會提高公司的流動比率?", "options": ["簽發即期支票償還欠款", "收到客戶以遠期票據償還貨款", "賒購辦公用印表機", "向銀行短期借款取得現金"], "answer": "A", "figure": null, "official": "流動資產、流動負債同額減少,在流動比率大於1時,使流動比率上升。", "explain": {"concept": "流動比率 = 流動資產 ÷ 流動負債。比率 >1 時,兩者同減,比率上升;兩者同增,比率下降。", "steps": ["(A)還欠款:現金(流動資產)減少、應付帳款(流動負債)減少,同額減少。例如 300/100=3,各減 50 變成 250/50=5,比率上升。", "(B)收到遠期票據償還貨款:應收票據增加、應收帳款減少,流動資產總額不變,比率不變。", "(C)賒購印表機:設備(非流動資產)增加、應付設備款(流動負債)增加,流動負債增加,比率下降。", "(D)短期借款取得現金:流動資產、流動負債同額增加,比率 >1 時下降(例如 300/100 各加 50 → 350/150≈2.33)。"], "pitfalls": "比率為3(大於1)時「同額增」會讓比率下降、「同額減」會讓比率上升;若比率小於1則相反。", "distractors": {"B": "流動資產總額不變,比率不變。", "C": "流動負債增加但流動資產不變,比率下降。", "D": "同額增加使比率從3往1靠近,下降。"}}, "check": "python:300/100=3;各減50→5(升);各加50→2.33(降),與官方一致。", "verified": true, "note": ""}, {"id": "111-2-A-14", "exam": "111-2", "paper": "A", "q": 14, "unit": "十、加值型營業稅會計實務", "topic": "加值型營業稅", "stem": "有關加值型營業稅之敘述,下列何者錯誤?", "options": ["支付交際費所繳納之進項稅額,不能用以扣抵銷項稅額", "買受人為非營業人時,應開立二聯式統一發票", "採行加值型營業稅優點之一,是可消弭重複課稅", "買受人為營業人時,營業稅採稅款內含的方式徵收"], "answer": "D", "figure": null, "official": "買受人為營業人時,營業稅採稅款「外加」方式徵收。", "explain": {"concept": "營業稅開立發票:買受人為營業人用三聯式、稅額外加;買受人為非營業人用二聯式、稅款內含。", "steps": ["(A)交際應酬支出的進項稅額依規定不得扣抵銷項稅額,正確。", "(B)買受人是非營業人(一般消費者)時,開二聯式發票(含稅),正確。", "(C)加值型營業稅只對「加值部分」課稅,可避免重複課稅,正確。", "(D)買受人為營業人時,稅額要「外加」(單獨列示稅額)才能扣抵;稅款內含是賣給非營業人(零售)的做法,所以 D 錯誤。"], "pitfalls": "外加 vs 內含:賣給營業人 = 外加(三聯式),賣給消費者 = 內含(二聯式)。", "distractors": {"A": "敘述正確。", "B": "敘述正確。", "C": "敘述正確。"}}, "check": "概念題:對照官方詳解與營業稅法常識一致。", "verified": true, "note": ""}, {"id": "111-2-A-15", "exam": "111-2", "paper": "A", "q": 15, "unit": "十、加值型營業稅會計實務", "topic": "營業稅申報計算", "stem": "關西商店為一般稅率加值型營業人,9、10月份進貨總額$600,000,外銷$150,000,內銷$1,800,000,購置機器設備$300,000,支付交際費$9,000,支付辦公室的租金$100,000,支付外籍經理房屋租金$20,000,支付自用乘人小汽車之維修費$50,000,營業稅5%皆為外加。另悉,上期留抵稅額$64,000,則關西商店於11月15日報繳營業稅,將產生下列何者?", "options": ["累積留抵稅額$4,000", "累積留抵稅額$4,500", "應付營業稅$3,500", "應收退稅款$24,000"], "answer": "A", "figure": null, "official": "溢付稅額26,500 > 退稅上限22,500,應退22,500,累積留抵稅額4,000。", "explain": {"concept": "進項稅額(可扣抵者)- 銷項稅額 + 上期留抵,若為溢付,可退稅限額為(外銷+購買固定資產)×5%,超過的部分留抵。", "steps": ["可扣抵進項:進貨600,000 + 機器300,000 + 辦公室租金100,000 + 乘人小汽車維修50,000 = 1,050,000;交際費、外籍經理房屋租金(非營業用)不得扣抵。進項稅額 = 1,050,000×5% = $52,500。", "銷項稅額:只有內銷課稅,外銷零稅率。1,800,000×5% = $90,000。", "本期應納(溢付)= 銷項90,000 - 進項52,500 - 上期留抵64,000 = -26,500,即溢付稅額$26,500。", "退稅上限 =(外銷150,000 + 購買固定資產300,000)×5% = $22,500。", "溢付26,500 > 22,500,所以退稅22,500(應收退稅款22,500,D 的24,000錯),剩下 26,500 - 22,500 = $4,000 留抵下期。答案 A。"], "pitfalls": "哪些進項不能扣抵(交際費、非營業用的租金、小汽車購置/租賃/油料等)要先剔除;退稅有上限,超過部分只能留抵。", "distractors": {"B": "累積留抵稅額不是4,500。", "C": "本期為溢付稅額,沒有應納稅額,不會產生應付營業稅。", "D": "退稅有上限22,500,不能全額26,500,24,000也無依據。"}}, "check": "python:進項52,500;銷項90,000;溢付26,500;上限22,500;留抵4,000,與官方一致。", "verified": true, "note": ""}, {"id": "111-2-A-16", "exam": "111-2", "paper": "A", "q": 16, "unit": "十一、現金及內部控制", "topic": "現金內部控制", "stem": "一名任職於補習班、深受老闆信任的會計侵占補習班款項高達數千萬元。該補習班的老闆表示:「這名會計心思細膩、做事細心謹慎,平時由他收取學生的學費並登錄到帳簿中,再由他負責到往來銀行進行存款,實在想不到他會這樣對我!」請問,根據老闆的說法「平時由他收取學生的學費並登錄到帳簿中」,該補習班違反了下列哪一項現金內部控制的要點?", "options": ["管錢不管帳、管帳不管錢", "每日將現金存入銀行,避免現金失竊", "應定期或非預警性檢查現金餘額", "應讓員工定期輪調工作或強迫休假"], "answer": "A", "figure": null, "official": "同一人既收錢又記帳,違反「管錢不管帳、管帳不管錢」(職能分工)。", "explain": {"concept": "現金內部控制的核心之一是職責分離:出納(管錢)與會計(管帳)不可由同一人擔任。", "steps": ["題目說「他收取學費」(管錢)並且「登錄到帳簿」(管帳),兩件事同一人做。", "這就是沒有做到職務分工,違反「管錢不管帳、管帳不管錢」,選 A。", "B、C、D 雖然也是內控要點,但題目針對的是「收錢又記帳」這一句話。"], "pitfalls": "題目問的是「根據老闆的說法」的那句話,不要被「存款、侵占」等字眼帶去選其他內控要點。", "distractors": {"B": "題目那句話談的不是存入銀行的時間。", "C": "題目那句話談的不是檢查餘額。", "D": "輪調或強迫休假是另一項內控,但題目引述的句子與此無關。"}}, "check": "概念題:對照官方詳解一致。", "verified": true, "note": ""}, {"id": "111-2-A-17", "exam": "111-2", "paper": "A", "q": 17, "unit": "十一、現金及內部控制", "topic": "零用金撥補", "stem": "香山公司在期初設立定額零用金$5,500,每月底撥補零用金,12 月底時零用金保管箱中現金為$300,另12月中付訖之請款憑單中有:郵電費$800、辦公室文具$2,500、雜誌費用$1,000、員工生日蛋糕$950,今欲撥補並同時將定額零用金增加至$6,000,則公司在報銷並撥補之分錄中,「現金短溢」之金額應如何?", "options": ["借記$50", "貸記$50", "借記$450", "貸記$450"], "answer": "B", "figure": null, "official": "已支用零用金=$5,250;應剩250,實際剩300,現金溢出$50,貸記現金短溢。", "explain": {"concept": "定額零用金:期初零用金5,500 = 現金 + 已付憑單。若兩者合計不等於定額,差額記「現金短溢」(短少記借方,溢出記貸方)。", "steps": ["先算憑單總額(已支出):800 + 2,500 + 1,000 + 950 = $5,250。", "照理說保管箱應剩 5,500 - 5,250 = $250。", "實際剩 $300,比應有的 250 多 50,是現金「溢出」。", "報銷分錄:借 郵電費800、文具用品2,500、雜費(雜誌、蛋糕)1,950;貸 零用金5,250 加上現金短溢 50(貸方)。可見現金短溢在貸方 $50。", "(增加定額500是另一筆:借零用金500、貸現金500,與短溢無關。)"], "pitfalls": "短少(實際比應有少)記借方「現金短溢」;溢出(實際比應有多)記貸方。方向容易記反。", "distractors": {"A": "方向反了:現金多出來是貸記。", "C": "450 無依據(未計算正確的已支出總額)。", "D": "金額與方向皆不對。"}}, "check": "python:800+2,500+1,000+950=5,250;5,500-5,250=250;300-250=50 溢出 → 貸記$50,與官方一致。", "verified": true, "note": ""}, {"id": "111-2-A-18", "exam": "111-2", "paper": "A", "q": 18, "unit": "十一、現金及內部控制", "topic": "銀行調節表", "stem": "豐原公司 X2 年 9 月 30 日銀行存款帳面餘額為$32,450,但銀行對帳單餘額為$31,540,經雙方核對後,發現差異之原因如下:\n①9 月底未兌現支票兩張:第 78 號$2,500 及第 168 號$1,000,其中第 168 號支票為保付支票\n②豐原公司委託銀行代收一張本票,金額為$2,800,銀行已收現,豐原公司尚未入帳\n③收自顧客的支票,金額為$3,500,存入銀行後,因存款不足遭銀行退票\n④9 月底在途存款$3,000\n⑤銀行扣除 9 月份的手續費$300,但豐原公司尚未入帳\n⑥銀行對帳單有一筆利息費用,公司帳記錄的金額為$950,與銀行對帳單記錄的金額不符,經查明後,雙方確定是公司誤記了利息費用的金額,銀行記錄的金額則正確無誤\n請問在⑥中,這筆利息費用的正確金額是多少?", "options": ["$360", "$410", "$590", "$1,590"], "answer": "A", "figure": null, "official": "銀行方調節後餘額=$32,040,推出公司誤記差額x=$590(多記),正確利息費用=950-590=$360。", "explain": {"concept": "銀行存款調節表:雙方調整後餘額必須相等。先算銀行方的正確餘額,再反推公司方的未知差額。", "steps": ["銀行方:對帳單餘額31,540 + 在途存款3,000 - 未兌現支票2,500 = $32,040(保付支票168號銀行已先保留款項,不算未兌現)。", "公司方:帳面32,450 + 託收票據2,800 - 存款不足退票3,500 - 手續費300 + 公司誤記差額x = 32,040。", "32,450 + 2,800 - 3,500 - 300 = 31,450,所以 31,450 + x = 32,040,x = +590(公司利息費用多記了590,要加回)。", "公司記950,多記590,正確利息費用 = 950 - 590 = $360。"], "pitfalls": "保付支票不列為未兌現支票;別把利息誤記的差額方向弄反(多記費用要加回銀行存款)。", "distractors": {"B": "410 無對應計算。", "C": "590 是誤記的差額,不是正確金額。", "D": "1,590 是把差額加在950上,方向錯。"}}, "check": "python:銀行方32,040;公司方31,450 + x = 32,040 → x=590;950-590=360,與官方一致。", "verified": true, "note": ""}, {"id": "111-2-A-19", "exam": "111-2", "paper": "A", "q": 19, "unit": "十二、應收款項", "topic": "總額法銷貨折扣", "stem": "斗六公司2月1日曾賒銷商品一批,付款條件為 3/10,1/20,n/30,並於2月11日收取三分之二貨款、2月21日收取剩餘貨款。因顧客未享折扣而貸記:「銷貨收入$360」,若公司改採總額法處理記錄此交易,則下列敘述何者正確?", "options": ["產生「銷貨折讓」金額共$1,260", "產生「銷貨折讓」金額共$1,080", "收取「現金」金額共$54,000", "收取「現金」金額共$52,380"], "answer": "A", "figure": null, "official": "設銷貨總額X,1/3X×(3%-1%)=360,X=54,000;總額法折扣=2/3×54,000×3%+1/3×54,000×1%=$1,260。", "explain": {"concept": "淨額法下,顧客未享折扣時,貸記「銷貨收入」代表多收的折扣。由此倒推原銷貨總額,再用總額法算折扣。", "steps": ["付款條件3/10,1/20,n/30:10天內付款折3%,20天內折1%。", "2月11日(第10天)收2/3 → 享3%折扣;2月21日(第20天)收1/3 → 享1%折扣。", "淨額法下原按3%記淨額,第二批只享1%,多收2%,貸記銷貨收入360:1/3 × X × (3% - 1%) = 360 → X = $54,000。", "總額法折扣 = 2/3×54,000×3% + 1/3×54,000×1% = 1,080 + 180 = $1,260(A 正確,B 的1,080只是第一批)。", "現金 = 54,000 - 1,260 = $52,740(不是54,000或52,380)。"], "pitfalls": "折扣要依每次付款日分別計算;現金收取總額是扣掉折扣後的淨額。", "distractors": {"B": "只算了前三分之二的折扣(1,080),漏掉後三分之一的 180。", "C": "54,000 是未扣折扣的總額。", "D": "52,380 無對應算法。"}}, "check": "python:X=360/(1/3×0.02)=54,000;折扣=1,260;現金=52,740,與官方一致。", "verified": true, "note": ""}, {"id": "111-2-A-20", "exam": "111-2", "paper": "A", "q": 20, "unit": "十二、應收款項", "topic": "統制帳戶與明細帳", "stem": "月亮公司應收帳款統制帳戶餘額為$60,000,同時設置三個明細帳分別為甲客戶借餘$40,000、乙客戶借餘$35,000、丙客戶金額未知。下列敘述何者正確?", "options": ["丙客戶之明細帳餘額為借餘$15,000", "丙客戶之明細帳餘額為貸餘$15,000", "流動資產項下應收帳款金額為$60,000", "流動負債項下合約負債金額為$75,000"], "answer": "B", "figure": null, "official": "丙客戶為貸餘$15,000;資產項下應收帳款為借餘合計$75,000,負債項下合約負債為貸餘$15,000。", "explain": {"concept": "統制帳戶餘額 = 各明細帳餘額合計(借餘為正、貸餘為負)。貸餘的客戶代表預收款,報表上要列負債。", "steps": ["統制帳戶60,000 = 甲40,000 + 乙35,000 + 丙X → X = 60,000 - 75,000 = -15,000,即丙為貸餘$15,000(B 正確,A 錯)。", "報表表達:借餘的客戶合計(40,000+35,000=75,000)列流動資產「應收帳款」,不是60,000(C 錯)。", "貸餘的客戶15,000列流動負債「合約負債」,不是75,000(D 錯)。"], "pitfalls": "明細帳不能互抵:借餘列資產、貸餘列負債,要分開表達。", "distractors": {"A": "符號弄反:算出來是負的(貸餘)。", "C": "60,000 是互抵後的淨額,資產項下應是借餘合計75,000。", "D": "75,000 是借餘合計(資產),合約負債應為貸餘15,000。"}}, "check": "python:60,000-40,000-35,000=-15,000(貸餘),與官方一致。", "verified": true, "note": ""}, {"id": "111-2-A-21", "exam": "111-2", "paper": "A", "q": 21, "unit": "十二、應收款項", "topic": "預期信用減損損失", "stem": "恆春公司採帳款餘額百分比法估計預期信用減損損失,每期採相同之損失率。X2 年底應收帳款餘額$300,000,備抵損失貸餘$6,000。於 X3 年間共賒銷$1,500,000,收取帳款$1,350,000(不包含收回之沖銷數),並沖銷無法收回的帳款$25,000,惟已沖銷之帳款$8,000 經證實可收回,並已回收$3,000。請問 X3 年預期信用減損損失為何?", "options": ["$5,400", "$8,600", "$19,600", "$105,000"], "answer": "C", "figure": null, "official": "損失率=6,000÷300,000=2%;期末應收帳款430,000,備抵應為8,600;補提X=19,600。", "explain": {"concept": "帳款餘額百分比法:期末備抵損失 = 期末應收帳款 × 損失率;提列費用 = 期末應有餘額 - 調整前餘額。", "steps": ["損失率 = 6,000 ÷ 300,000 = 2%。", "期末應收帳款 = 300,000 + 賒銷1,500,000 - 收款1,350,000 - 沖銷25,000 + 恢復8,000 - 回收3,000 = $430,000。", "期末備抵損失應有餘額 = 430,000 × 2% = $8,600(貸餘)。", "調整前備抵損失:期初貸6,000 - 沖銷25,000 + 收回已沖銷之帳款恢復8,000 = 借餘11,000。", "要補提的預期信用減損損失 X:-11,000 + X = 8,600 → X = $19,600。"], "pitfalls": "已沖銷又收回:要先把應收帳款與備抵損失「恢復」(借應收、貸備抵),再記收現;調整前備抵可能變成借餘,補提要把借餘補平再加上期末應有餘額。", "distractors": {"A": "5,400 無對應算法。", "B": "8,600 是期末應有餘額,沒有考慮調整前的借餘11,000。", "D": "105,000 無依據。"}}, "check": "python:AR=430,000;期末備抵8,600;調整前=6,000-25,000+8,000=-11,000;X=19,600,與官方一致。", "verified": true, "note": ""}, {"id": "111-2-A-22", "exam": "111-2", "paper": "A", "q": 22, "unit": "十二、應收款項", "topic": "應收票據貼現", "stem": "馬祖公司於 X1 年 10 月 1 日持原定 X 天到期票據至銀行貼現,其面額$60,000,票面利率 6%,貼現期間 Y 天,現已知 X:Y = 3:1,X + Y = 120,且馬祖公司於貼現日認列$106 之應收票據貼現負債折價。下列敘述何者錯誤?(一年以 360 天計算)", "options": ["貼現率為 8%", "貼現期間為 30 天", "貼現日收到現金$60,494", "貼現日認列利息收入$406"], "answer": "D", "figure": null, "official": "(D)貼現日認列利息收入應為$600(持有60天),不是$406。", "explain": {"concept": "票據貼現:持有期間(出售前)的利息收入=面額×票面利率×持有天數/360;貼現息=到期值×貼現率×貼現期間/360。", "steps": ["X:Y=3:1、X+Y=120 → X=90、Y=30:票據總期間90天,貼現期間(貼現日到到期日)30天,持有期間 = 90 - 30 = 60天。(B 正確)", "到期值 = 60,000 +60,000×6%×90/360 = 60,000 + 900 = $60,900。", "貼現日票據帳面(含持有60天利息)= 60,000 × (1 + 6% × 60/360) = $60,600;負債折價106 = 60,600 - 貼現金額,所以貼現金額 = $60,494(C 正確),貼現息 = 到期值60,900 - 60,494 = $406。", "貼現率:406 = 60,900 × r × 30/360 → r = 406 ÷ 5,075 = 8%(A 正確)。", "貼現日認列的利息收入是持有60天的利息 = 60,000 × 6% × 60/360 = $600,不是406(406是貼現息),所以 D 錯誤。"], "pitfalls": "貼現息(利息費用側)與持有期間利息收入是兩個不同的金額,別混在一起。", "distractors": {"A": "貼現率=406÷(60,900×30/360)=8%,正確。", "B": "貼現期間Y=30天,正確。", "C": "貼現金額=60,900-406=60,494,正確。"}}, "check": "python:X=90,Y=30;到期值60,900;貼現息406;貼現金額60,494;r=8%;利息收入600,與官方一致。", "verified": true, "note": ""}, {"id": "111-2-A-23", "exam": "111-2", "paper": "A", "q": 23, "unit": "七、調整", "topic": "預付租金調整", "stem": "▲閱讀下文,回答第 23-24 題\n斯拜公司依規定於期末時進行會計帳戶之調整,以正確計算收益與費損之歸屬期間分類。其中會計人員阿妮亞在進行調整時,遇到下列兩種情況:\n情況一:年底調整前「預付租金」帳戶餘額為$6,000,其中屬於本期已實現者占三分之二\n情況二:年底調整後淨利為$126,000\n\n根據「情況一」,若該公司當年度無其他交易影響,下列敘述何者正確?", "options": ["年底調整後,「租金支出」帳戶餘額應為$2,000", "年底調整後,「預付租金」帳戶餘額應為$4,000", "年底調整分錄為借:租金支出$2,000、貸:預付租金$2,000", "年底調整分錄為借:租金支出$4,000、貸:預付租金$4,000"], "answer": "D", "figure": null, "official": "已實現 6,000×2/3=4,000,調整借:租金支出4,000、貸:預付租金4,000。", "explain": {"concept": "預付費用調整:已用掉(已實現)的部分轉為費用,尚未用掉的留在資產。", "steps": ["預付租金 6,000 中,已實現(已使用)的部分占 2/3:6,000 × 2/3 = $4,000。", "已實現的要轉成費用:借 租金支出 4,000、貸 預付租金 4,000(D 正確)。", "調整後:租金支出餘額 4,000(A 的2,000錯)、預付租金餘額 6,000 - 4,000 = 2,000(B 的4,000錯)。", "C 金額 2,000 是未實現部分,搞錯了。"], "pitfalls": "「已實現」的金額才轉費用;留下來的才是預付租金餘額,別把兩個數字對調。", "distractors": {"A": "租金支出應是 4,000,2,000 是剩下的預付租金。", "B": "預付租金餘額應為 2,000,4,000 是轉成費用的部分。", "C": "把未實現的 2,000 拿來調整,金額錯。"}}, "check": "python:6,000×2/3=4,000;6,000-4,000=2,000,與官方一致。", "verified": true, "note": ""}, {"id": "111-2-A-24", "exam": "111-2", "paper": "A", "q": 24, "unit": "七、調整", "topic": "調整錯誤對淨利影響", "stem": "▲閱讀下文,回答第 23-24 題\n斯拜公司依規定於期末時進行會計帳戶之調整,以正確計算收益與費損之歸屬期間分類。其中會計人員阿妮亞在進行調整時,遇到下列兩種情況:\n情況一:年底調整前「預付租金」帳戶餘額為$6,000,其中屬於本期已實現者占三分之二\n情況二:年底調整後淨利為$126,000\n\n根據「情況二」,由於阿妮亞是新進的會計人員,對於會計程序尚有些疏漏之處,其主管檢查全部之調整程序後發現下列錯誤:\n①估列預期信用減損損失時少計$3,000\n②應收租金,漏未調整$28,000\n③預收租金$2,400 中,有四分之三屬於本期已實現部分,漏作調整\n④文具用品$5,000 中,未耗用部份佔 2/5 ,漏未調整\n請幫助阿妮亞計算出公司之正確淨利為何?", "options": ["$150,800", "$151,200", "$154,800", "$160,800"], "answer": "C", "figure": null, "official": "正確淨利=126,000-3,000+28,000+1,800+2,000=$154,800。", "explain": {"concept": "逐項判斷錯誤使淨利「多計」或「少計」,再由原淨利反向修正:少計的加回、多計的減掉。", "steps": ["①預期信用減損損失少計3,000 → 費用少計 → 淨利多計3,000 → 要減3,000。", "②應收租金漏調整28,000 → 收入少計 → 淨利少計28,000 → 要加28,000。", "③預收租金2,400,四分之三已實現 = 2,400×3/4 = 1,800;漏作調整 → 收入少計 → 要加1,800。", "④文具用品5,000,未耗用占2/5 → 未耗用 = 5,000×2/5 = 2,000,這部分應留作資產;原本(假設全部列費用)費用多計2,000 → 淨利少計 → 要加2,000。", "正確淨利 = 126,000 - 3,000 + 28,000 + 1,800 + 2,000 = $154,800。"], "pitfalls": "每一項要先判斷是收入/費用、多計/少計;預收收入的已實現部分是「加」,不是減。", "distractors": {}}, "check": "python:126,000-3,000+28,000+1,800+2,000=154,800,與官方一致。", "verified": true, "note": ""}, {"id": "111-3-A-01", "exam": "111-3", "paper": "A", "q": 1, "unit": "一、會計基本概念", "topic": "會計資訊使用者與組織", "stem": "臻臻為澎湖股份有限公司的一般會計人員,該公司為公開發行公司,則下列敘述何者錯誤?", "options": ["臻臻為會計資訊內部使用者", "臻臻依照金管會所認可發布的國際財務報導準則(IFRS)做公司的帳務處理", "澎湖股份有限公司為社團法人組織", "澎湖股份有限公司財務報表須由會計師簽證"], "answer": "A", "figure": null, "official": "一般企業員工為會計資訊之外部使用者。", "explain": {"concept": "這題考會計資訊的「內部使用者」與「外部使用者」,以及公開發行公司的會計規範。", "steps": ["先分清楚:內部使用者是能直接取得公司內部資訊、做經營決策的人(如董事、經理人);外部使用者是靠公司公布的財務報表來了解公司的人(如股東、債權人、政府)。", "臻臻只是一般會計人員,不是管理決策階層,公司對他而言屬於外部資訊的使用立場,所以說他是內部使用者並不恰當,(A)為錯誤敘述。", "(B)公開發行公司須依金管會認可的 IFRS 處理帳務,正確。(C)股份有限公司屬營利社團法人,正確。(D)公開發行公司財務報表須經會計師查核簽證,正確。", "題目問「錯誤」,所以答案是(A)。"], "pitfalls": "看到「公司的會計人員」就直覺當成內部人員;其實本題依官方觀點,一般企業員工屬外部使用者。也要小心題目問的是「錯誤」。", "distractors": {"B": "這是正確敘述(公開發行公司採 IFRS),選的人可能漏看題目問「錯誤」。", "C": "股份有限公司確實是社團法人,若以為公司不是法人才會誤選。", "D": "公開發行公司依法財報須會計師簽證,選的人可能不知道此規定。"}}, "check": "概念題:依官方詳解及公司法、證交法常識確認(A)為錯誤敘述。", "verified": true, "note": ""}, {"id": "111-3-A-02", "exam": "111-3", "paper": "A", "q": 2, "unit": "八、結帳", "topic": "結帳前後等式與淨利", "stem": "臺北公司 X2 年底結帳前資產 $400,000、權益 $180,000,結帳後負債與權益比為 2:3,X2 年度收益與費損之比為 4:3,則 X2 年度淨利為何?", "options": ["$60,000", "$160,000", "$180,000", "$240,000"], "answer": "A", "figure": null, "official": "結帳前資產=結帳後資產;結帳前權益+損益=結帳後權益。$400,000=2X+3X,X=$80,000,結帳後負債$160,000、權益$240,000;$180,000+損益=$240,000,損益=$60,000。", "explain": {"concept": "結帳只會把損益轉入權益,資產與負債不會因結帳而改變,用會計恆等式「資產=負債+權益」倒推。", "steps": ["結帳不改變資產和負債,所以結帳後資產還是 $400,000。", "結帳後負債:權益=2:3,把 $400,000 分成 2+3=5 份,每份 $400,000÷5=$80,000。", "結帳後負債=$80,000×2=$160,000;結帳後權益=$80,000×3=$240,000。", "結帳前權益是 $180,000,結帳時淨利會加到權益,所以 $180,000+淨利=$240,000。", "淨利=$240,000−$180,000=$60,000。", "(補充驗證)收益:費損=4:3,設收益4k、費損3k,淨利=k=$60,000,收益$240,000、費損$180,000,完全吻合。"], "pitfalls": "把「結帳後權益 $240,000」或「結帳後負債 $160,000」直接當成淨利;題目要的是權益的「增加數」。", "distractors": {"B": "$160,000 是結帳後的負債,不是淨利。", "C": "$180,000 是結帳前權益,也剛好是費損總額,容易被誤選。", "D": "$240,000 是結帳後權益(也是收益總額),不是淨利。"}}, "check": "python:X=400000/5=80000;權益=3X=240000;淨利=240000-180000=60000,與官方相符;收益240,000-費損180,000=60,000 亦吻合。", "verified": true, "note": ""}, {"id": "111-3-A-03", "exam": "111-3", "paper": "A", "q": 3, "unit": "四、分錄與日記簿", "topic": "傳票與分錄判斷", "stem": "欣欣是新任的會計人員,請協助欣欣判斷下列帳務處理何者正確?", "options": ["業主投資現金、商品開設商店,在複式傳票三分法下,應編製現金轉帳傳票", "賒購商品一批,採定期盤存制,以淨額法入帳,付款條件 1/10,n/30,在折扣期間內付款,分錄為:\n借:應付帳款,貸:進貨折讓、現金", "現付水電費、電費,其中 1/3 為業主私人費用,在複式傳票三分法下應編製現金支出傳票", "賒銷商品給甲公司,起運點交貨,商品已運出,因尚未收到貨款,所以尚未入帳"], "answer": "C", "figure": null, "official": "(A)借:現金、存貨;貸:業主資本,編製轉帳傳票;(B)借:應付帳款,貸:現金;(C)借:水電瓦斯費、業主往來;貸:現金;(D)權責基礎,權利責任發生,起運點交貨,商品所有權已轉移,即應入帳。", "explain": {"concept": "這題綜合考傳票種類、淨額法進貨、業主私人費用與權責基礎。", "steps": ["(C)現付水電費,有付出現金,所以屬於「現金支出傳票」;其中 1/3 是業主私人費用,不是公司的費用,要記「業主往來」:借:水電瓦斯費(2/3)、業主往來(1/3);貸:現金。正確。", "(B)淨額法在進貨時就已經把折扣扣掉入帳,折扣期間內付款,直接「借:應付帳款 貸:現金」,不會再出現進貨折讓。(進貨折讓是總額法才用的帳戶。)", "(A)投資的現金部分要開現金收入傳票,商品部分要開轉帳傳票;三分法裡沒有「現金轉帳傳票」這種傳票,所以不對。", "(D)會計採權責基礎,賒銷、起運點交貨,商品運出時所有權已轉移,銷貨就要入帳,不能等收到貨款。"], "pitfalls": "以為「還沒收錢就還不用記帳」,其實權責基礎看的是權利義務是否發生,不是看現金。淨額法與總額法的折扣處理也容易混淆。", "distractors": {"A": "傳票名稱不正確,現金與非現金部分需分開處理,沒有「現金轉帳傳票」。", "B": "把淨額法誤當總額法,在淨額法下付款時沒有進貨折讓。", "D": "誤用現金基礎,忽略起運點交貨時所有權即已轉移。"}}, "check": "概念題:對照官方詳解與權責基礎、淨額法觀念確認(C)正確。", "verified": true, "note": ""}, {"id": "111-3-A-04", "exam": "111-3", "paper": "A", "q": 4, "unit": "六、試算與試算表", "topic": "試算表錯誤更正", "stem": "竹北商店年底餘額式試算表的借貸方總額不相等,原借方總額為 $160,000,經查帳冊發現下列錯誤:\n(1) 利息收入 $2,000 此項目遺漏過帳\n(2) 銷貨退回 $9,000 誤過入進貨退出借方\n(3) 現銷商品 $5,600 誤記為賒購商品\n(4) 交易借記應收佣金 $1,600,過帳時誤過入應收佣金之貸方\n則該試算表正確的總額為何?", "options": ["$147,000", "$152,600", "$161,200", "$172,200"], "answer": "D", "figure": null, "official": "(1)貸方少記+$2,000;(2)借貸皆少記+$9,000;(3)無影響;(4)借方少記+$3,200(方向錯誤)。$160,000+(2)$9,000+(4)$3,200=$172,200。", "explain": {"concept": "餘額式試算表是把各帳戶的「餘額」列在借方或貸方。逐項判斷每個錯誤讓借方、貸方各少列(或多列)多少,再把借方補到正確。", "steps": ["先搞清楚:餘額式試算表列的是各帳戶「餘額」,所以要判斷每個錯誤讓借方或貸方的合計少列(多列)多少。", "(1)利息收入是貸餘帳戶,漏過帳 → 貸方少列 $2,000,借方不受影響。", "(2)銷貨退回(借餘)沒有入帳,借方少列 $9,000;而進貨退出(貸餘)被多借 $9,000,貸方餘額少列 $9,000。所以借貸皆少列 $9,000。", "(3)現銷誤記為賒購:兩種記法借貸金額相同,餘額式試算表仍平衡 → 無影響。", "(4)應收佣金本應借記 $1,600,卻過入貸方,帳戶餘額差了 $1,600+$1,600=$3,200,借方少列 $3,200,貸方不受影響。", "借方正確總額=原借方 $160,000+(2)$9,000+(4)$3,200=$172,200。", "(驗算)貸方:原貸方+(1)$2,000+(2)$9,000=正確貸方 $172,200,所以原貸方=$161,200,原本借 $160,000、貸 $161,200 確實不平衡,補正後兩邊都是 $172,200。"], "pitfalls": "(2)、(4)的方向錯誤要用「餘額」去想,不是單純用借貸金額相加;(3)沒有影響,不要加進去。", "distractors": {"C": "$161,200 是原本(未更正)的貸方總額,不是正確的總額。"}}, "check": "python:160000+9000+3200=172200,與官方相符。", "verified": true, "note": ""}, {"id": "111-3-A-05", "exam": "111-3", "paper": "A", "q": 5, "unit": "七、調整", "topic": "調整錯誤對淨利的影響", "stem": "中壢商店 06 年調整後淨利為 $154,000,會計人員發現下列錯誤:\n(1) 預收租金 $32,000 中有 3/4 已實現,漏作調整\n(2) 多提折舊 $1,800\n(3) 漏調整應收佣金 $36,000\n(4) 文具用品 $50,000 中,未實現部分占 2/5 未調整\n經更正後 06 年度之正確淨利為何?", "options": ["$72,000", "$81,000", "$195,000", "$235,800"], "answer": "D", "figure": null, "official": "(1)租金收入少計$24,000→淨利少計$24,000;(2)折舊多計$1,800→淨利少計$1,800;(3)應收佣金漏計$36,000→佣金收入少計$36,000→淨利少計$36,000;(4)文具用品$20,000未調整→淨利少計$20,000。$154,000+$24,000+$1,800+$36,000+$20,000=$235,800。", "explain": {"concept": "逐項判斷每個錯誤讓淨利「少算」還是「多算」,少算就加回去,多算就減掉。", "steps": ["先寫下調整後淨利 $154,000,這是「含錯誤」的淨利。", "(1)預收租金 $32,000 的 3/4 已賺得,應轉為租金收入:$32,000×3/4=$24,000。漏做→收入少計→淨利少計 $24,000,要加回。", "(2)折舊多提 $1,800:費用多算→淨利少算,加回 $1,800。", "(3)應收佣金 $36,000 漏調整:佣金收入少計→淨利少計,加回 $36,000。", "(4)文具用品 $50,000 當初全數記為費用,期末有 2/5 未使用($50,000×2/5=$20,000)卻沒轉成資產:費用多算,淨利少算 $20,000,加回。", "正確淨利=$154,000+$24,000+$1,800+$36,000+$20,000=$235,800。"], "pitfalls": "最容易搞反「加」與「減」:費用多算或收入少算,淨利都是被低估,要加回去。第(4)項要看出文具用品原先是記為費用、期末未用部分要轉列資產。", "distractors": {}}, "check": "python:154000+24000+1800+36000+20000=235800,與官方相符。第(4)項題幹「未實現部分」措辭較含糊,依官方解法(淨利少計$20,000)計算。", "verified": true, "note": "第(4)項題幹措辭「未實現部分占2/5未調整」較含糊,依官方詳解解讀為文具用品原記費用、期末未用部分未轉列資產,淨利少計$20,000。"}, {"id": "111-3-A-06", "exam": "111-3", "paper": "A", "q": 6, "unit": "七、調整", "topic": "預付費用調整(保險費)", "stem": "屏東公司於 X2 年 5 月 1 日預付 2 年保險費 $57,600,採權責基礎記帳,則 X3 年底調整後,相關帳戶餘額為何?", "options": ["保險費 $19,200,預付保險費 $38,400", "保險費 $28,800,預付保險費 $9,600", "保險費 $48,000,預付保險費 $9,600", "保險費 $19,200,預付保險費 $28,800"], "answer": "B", "figure": null, "official": "$57,600÷24=$2,400/月;X3年度保險費=$2,400×12=$28,800;預付保險費(X4年1/1~5/1)=$2,400×4=$9,600。", "explain": {"concept": "預付保險費要依月份攤銷:已過的期間轉為費用,未到的期間留在資產。", "steps": ["先算每月保險費:$57,600÷24 個月=$2,400。", "保險期間是 X2/5/1 到 X4/4/30。X3 全年(1~12 月)都在保險期間內,所以 X3 年度保險費=$2,400×12=$28,800。", "X3 年底之後,還剩 X4 年 1~4 月共 4 個月未到期,預付保險費=$2,400×4=$9,600。", "所以調整後:保險費 $28,800、預付保險費 $9,600,選(B)。", "(驗算)X2 年 8 個月 $19,200+X3 年 12 個月 $28,800+剩餘 4 個月 $9,600=$57,600。"], "pitfalls": "把「X3 年底累計已用掉的費用」當成 X3 年度的保險費(那會是 20 個月=$48,000);題目問的是 X3 年度的費用。", "distractors": {"A": "$19,200 是 X2 年(8 個月)的保險費,$38,400 是 16 個月,等於用 X2 年的數字。", "C": "$48,000 是從 X2/5 到 X3 年底累計 20 個月的保險費,不是 X3 年度的保險費。", "D": "$19,200 是 X2 年保險費,$28,800 是 X3 年保險費,把兩者放反了位置。"}}, "check": "python:57600/24=2400;×12=28800;×4=9600,與官方相符。", "verified": true, "note": ""}, {"id": "111-3-A-07", "exam": "111-3", "paper": "A", "q": 7, "unit": "八、結帳", "topic": "結帳觀念", "stem": "結帳是指企業於報導期間終了時,彙集計算所有帳戶資料,以利財務報表編製。有關結帳的敘述,下列何者正確?", "options": ["在定期盤存制下,商品帳戶結帳採銷貨成本法及本期損益法,結帳分錄均貸記存貨(期末)", "結帳後的試算表只有虛帳戶", "結清收益類帳戶會使本期損益帳戶借餘增加", "若商店發生淨利,則結帳時應借記本期損益、貸記業主往來"], "answer": "D", "figure": null, "official": "(A)均借記存貨(期末);(B)只有實帳戶;(C)貸餘增加。", "explain": {"concept": "結帳的目的:把虛帳戶(收入、費用)結清到本期損益,再把損益轉入業主權益,最後只剩實帳戶。", "steps": ["(A)期末存貨是資產,要「借記」存貨(期末),不是貸記,錯誤。", "(B)結帳後虛帳戶都已結清歸零,試算表只剩實帳戶(資產、負債、權益),(B)說反了。", "(C)收益類帳戶是貸餘,結清時「借:收入 貸:本期損益」,會使本期損益貸方增加,不是借餘增加。", "(D)若有淨利,本期損益會有貸餘,結清時「借:本期損益 貸:業主往來(或業主資本)」,把淨利轉入權益,正確。"], "pitfalls": "(A)的借貸方向、(C)的借餘或貸餘容易記反;可用「收入→貸餘、結清要借記」來確認。", "distractors": {"A": "把期末存貨誤當成要貸記,其實期末存貨是借記資產。", "B": "誤以為結帳後留下虛帳戶,實際上虛帳戶已結清歸零。", "C": "收益結清是貸記本期損益,誤以為借餘。"}}, "check": "概念題:對照官方詳解及結帳程序確認(D)正確。", "verified": true, "note": ""}, {"id": "111-3-A-08", "exam": "111-3", "paper": "A", "q": 8, "unit": "十、加值型營業稅會計實務", "topic": "進項稅額不得扣抵", "stem": "南投公司為一般稅率營業人,06 年 9-10 月進項支出資料如下,試問下列不可扣抵銷項稅額的進項有哪幾項?\n①購置董事長座車 ②支付主管座車修繕費 ③支付外籍主管房屋租金\n④購買尾牙禮品 ⑤購買文具捐贈給私立育幼院", "options": ["①②③④", "①②④⑤", "①③④⑤", "②③④⑤"], "answer": "C", "figure": null, "official": "官方詳解頁未列第 8 題說明,答案表為(C)①③④⑤。", "explain": {"concept": "營業稅的進項稅額,有些支出依法不得扣抵(如自用乘人小汽車、交際應酬、非供本業使用的支出等)。", "steps": ["①董事長座車屬自用乘人小汽車的購置,進項稅額不得扣抵。", "④尾牙禮品屬交際應酬性質,進項稅額不得扣抵。", "⑤購買文具捐贈給育幼院是無償贈與、非供本業使用,依官方答案不得扣抵。", "③外籍主管房屋租金屬員工個人性質的支出,依官方答案不得扣抵。", "②主管座車修繕費,依官方答案不在「不可扣抵」之列。", "所以不可扣抵的是①③④⑤,選(C)。"], "pitfalls": "乘人小汽車相關支出(購置、修繕、油料)的扣抵範圍細節較多,容易混淆;本題以官方答案為準。", "distractors": {"A": "把②也算成不可扣抵,又漏掉⑤。", "B": "漏掉③、多選②。", "D": "漏掉①(座車購置不可扣抵)、多選②。"}}, "check": "官方詳解漏列第8題,無法逐項對照官方理由;僅依答案表(C)。", "verified": false, "note": "官方詳解頁缺第8題說明;②修繕費為何可扣抵、③外籍主管房租與⑤捐贈文具為何不可扣抵之法條依據無法由詳解確認,解析為依答案表推論。"}, {"id": "111-3-A-09", "exam": "111-3", "paper": "A", "q": 9, "unit": "九、財務報表", "topic": "資產負債表推算與比率", "stem": "翰翰在編製新竹公司的資產負債表時,漏了以下項目的金額,已知營運資金 $700,000,速動比率為 3.85,又現金及約當現金:應收帳款為 5:6。試問下列何者正確?\n\n新竹公司 資產負債表 中華民國 01 年 12 月 31 日\n\n| 資產 | 01/12/31 | 負債及權益 | 01/12/31 |\n|---|---|---|---|\n| 流動資產 | | 流動負債 | |\n| 現金及約當現金 | ($      ) | 應付帳款 | ($      ) |\n| 應收帳款 | (      ) | 非流動負債 | |\n| 存貨 | 130,000 | 長期借款 | 400,000 |\n| 流動資產合計 | ($      ) | 負債總計 | ($      ) |\n| 非流動資產 | | 權益 | |\n| 不動產、廠房及設備 | $600,000 | 股本 | $1,200,000 |\n| 無形資產 | 500,000 | 資本公積 | 320,000 |\n| 生物資產—非流動 | 300,000 | 保留盈餘 | 180,000 |\n| 非流動資產合計 | $1,400,000 | 權益總計 | $1,700,000 |\n| 資產總計 | ($      ) | 負債及權益總計 | ($      ) |\n", "options": ["應收帳款 $420,000", "流動負債 $250,000", "流動比率為 4.18", "資產負債表為特定期間的靜態報表,應於年度決算程序辦理終了後,至少保存 10 年"], "answer": "A", "figure": null, "official": "流動資產=流動負債+$700,000;速動比率=(流動資產−存貨$130,000)÷流動負債=3.85,得流動負債$200,000、流動資產$900,000,流動比率4.5;5X+6X+$130,000=$900,000,X=$70,000,應收帳款=$70,000×6=$420,000;(D)資產負債表為特定日期的靜態報表。", "explain": {"concept": "用「營運資金=流動資產−流動負債」和「速動比率」兩條式子,解出流動負債與流動資產。", "steps": ["設流動負債為 L。營運資金=流動資產−流動負債=$700,000,所以流動資產=L+$700,000。", "速動資產=流動資產−存貨=L+$700,000−$130,000=L+$570,000。", "速動比率=速動資產÷流動負債:(L+$570,000)÷L=3.85,即 $570,000=2.85L,L=$200,000。", "流動資產=$200,000+$700,000=$900,000;流動比率=$900,000÷$200,000=4.5。", "現金與應收帳款合計=$900,000−存貨$130,000=$770,000,比例 5:6,共 11 份,每份$70,000:現金=$350,000,應收帳款=$420,000。", "逐項檢查:(A)應收帳款 $420,000 正確;(B)流動負債是 $200,000;(C)流動比率是 4.5;(D)資產負債表是「特定日期」的靜態報表,不是「特定期間」。"], "pitfalls": "速動資產要把存貨扣掉(本題沒有預付費用);另外資產負債表是「某一天」的報表,損益表才是「一段期間」。", "distractors": {"B": "流動負債正確為 $200,000,不是 $250,000。", "C": "流動比率正確為 4.5,不是 4.18;可能把速動比率與流動比率混淆。", "D": "把「特定日期」誤寫成「特定期間」,屬於報表性質的觀念錯誤。"}}, "check": "python:L=570000/2.85=200000;流動資產900000;比率4.5;應收=770000/11×6=420000,與官方相符。", "verified": true, "note": ""}, {"id": "111-3-A-10", "exam": "111-3", "paper": "A", "q": 10, "unit": "十一、現金及內部控制", "topic": "零用金保管箱正確餘額", "stem": "宜蘭公司設置 $50,000 之零用金,每月底撥補零用金,並由東東經管。由於東東八月份已曠職多日,人也不知去向。公司指派您展開調查,當打開零用金保管箱時發現:\n(1) 八月份購買公司之文具用品發票兩張,金額共為 $5,250,確定由部門使用中\n(2) 宜蘭公司之銷貨發票存根聯數張,總金額為 $290,000,皆由東東擔任銷貨員,且皆為現金銷貨,但東東並未向公司報帳\n(3) 有一張由臺中公司開立之發票,金額為 $27,000,由東東自行簽字收貨,查證宜蘭公司並無驗收記錄,對該公司亦無貨欠\n(4) 八月份購買郵票之收據一張,金額為 $8,000,所有郵票仍放在保管箱內\n(5) 保管箱內尚存之紙鈔及硬幣共 $3,750\n試問八月份零用金保管箱之正確餘額應為多少?", "options": ["$33,000", "$36,750", "$40,500", "$50,000"], "answer": "B", "figure": null, "official": "$50,000−$5,250−$8,000=$36,750。", "explain": {"concept": "零用金採定額制,「正確餘額」=定額−已經合法支用的金額(有憑證的支出)。", "steps": ["零用金定額是 $50,000,正確情況下:現金+已支用的單據=$50,000。", "(1)文具用品發票 $5,250 是真實的零用金支出,要扣除。", "(4)購買郵票的收據 $8,000,錢已經付出去換成郵票,也要扣除。", "(2)的銷貨款與(3)臺中公司發票,與零用金基金無關(銷貨款屬公司收入、公司並無該筆貨欠),不能扣減零用金。", "正確餘額=$50,000−$5,250−$8,000=$36,750。", "(補充)箱內實際現金只有 $3,750,所以短少 $36,750−$3,750=$33,000,須進一步追查。"], "pitfalls": "把短少金額 $33,000 誤當成正確餘額;也容易被(2)(3)的大金額干擾,把它們扣掉。", "distractors": {"A": "$33,000 是「短少」金額($36,750−$3,750),不是正確餘額。", "C": "$40,500 是 $36,750+$3,750,把實際現金再加回去,觀念錯誤。", "D": "$50,000 是零用金定額,沒有扣除已支用的單據。"}}, "check": "python:50000-5250-8000=36750,與官方相符。", "verified": true, "note": ""}, {"id": "111-3-A-11", "exam": "111-3", "paper": "A", "q": 11, "unit": "十一、現金及內部控制", "topic": "銀行存款調節表", "stem": "軒軒編製平鎮公司銀行存款調節表時,發生下列情形,請問軒軒的哪個操作是正確的?", "options": ["公司送存銀行的存款,因過了營業時間,銀行未入帳,在編製由公司帳面餘額調整至銀行對帳單餘額時,應列為銀行存款調節表的加項", "軒軒將公司水電費 $500 列為 $550,在編製正確的銀行存款調節表時,做為公司帳面餘額的加項", "銀行寄來的對帳單顯示利息收入、托收票據、銀行手續費,在編製正確的銀行存款調節表時,做為公司帳面餘額的加項", "軒軒針對所有調節項目作調整分錄"], "answer": "B", "figure": null, "official": "(A)在途存款,由公司帳面餘額調整至銀行對帳單餘額時,應列為銀行存款調節表的減項;(C)銀行手續費為公司帳面餘額的減項;(D)僅針對公司帳面調節項目作調整分錄。", "explain": {"concept": "調節表要把公司帳上餘額與銀行對帳單餘額調成相同;要判斷每一項是「加」或「減」、以及要不要作分錄。", "steps": ["(B)公司把水電費 $500 誤記成 $550,多扣了 $50 現金,帳面餘額被低估,所以要「加回」$50,正確。", "(A)在途存款是公司已記、銀行未記,若從公司帳面餘額往銀行對帳單餘額調整,要「減」掉,不是加。", "(C)利息收入、托收票據收現是公司帳面餘額的加項,但銀行手續費是減項,不能全部都當加項。", "(D)只有「公司帳面」需要調整的項目(如利息收入、手續費、記錯金額)才需調整分錄;銀行方面的項目(在途存款、未兌現支票)不用作分錄。"], "pitfalls": "弄混「公司帳面餘額」與「銀行對帳單餘額」的調整方向;以及誤以為所有調節項都要分錄。", "distractors": {"A": "以為在途存款要加,其實從公司帳面往銀行餘額調整應減。", "C": "把手續費也當加項,手續費是減項。", "D": "銀行方面的調節項目不需要作分錄。"}}, "check": "概念題:依官方詳解及銀行調節表原則確認(B)正確。", "verified": true, "note": ""}, {"id": "111-3-A-12", "exam": "111-3", "paper": "A", "q": 12, "unit": "十二、應收款項", "topic": "附退貨權銷貨與退款負債", "stem": "新北公司將其商品 900 個公仔,每個售價 $160,放置各賣場銷售,約定半年內沒有賣完的可全數退回,估計退貨比例為 10%。下列敘述何者正確?", "options": ["銷貨時,認列退款負債 $14,400", "實際售出 825 個公仔,實際售出時的分錄為借:銷貨收入 $2,400", "實際售出 825 個公仔,實際售出時的分錄為貸:銷貨收入 $132,000", "新北公司的退款負債應列為非流動負債"], "answer": "A", "figure": null, "official": "(A)900×$160×10%=$14,400;(B)(C)借:現金$132,000、退款負債$14,400;貸:應收帳款$144,000、銷貨收入$2,400;(D)半年內列為流動負債。", "explain": {"concept": "附退貨權的銷貨,預估會退回的部分不能認列收入,要先記「退款負債」。", "steps": ["銷貨總額=900×$160=$144,000;預估退貨 10%,退款負債=$144,000×10%=$14,400。(A)正確。", "實際售出 825 個,收現=825×$160=$132,000,未售出而退回的有 75 個($12,000)。", "結算分錄:\n借:現金  132,000\n借:退款負債  14,400\n  貸:應收帳款  144,000\n  貸:銷貨收入  2,400\n(多估的退款負債 $14,400−$12,000=$2,400 轉為收入)。", "(B)、(C)與上述分錄不符。(D)退貨期間只有半年,屬一年內到期,應列流動負債。"], "pitfalls": "以為多估的退款負債要借記銷貨收入,實際是估多了,差額 $2,400 要「貸記」銷貨收入。", "distractors": {"B": "方向相反,多估的退款負債差額 $2,400 應貸記銷貨收入。", "C": "$132,000 是收現金額,不是銷貨收入的貸記數。", "D": "半年內到期應列流動負債。"}}, "check": "python:900*160*10%=14400;825*160=132000;14400−(900−825)*160=2400,與官方相符。", "verified": true, "note": ""}, {"id": "111-3-A-13", "exam": "111-3", "paper": "A", "q": 13, "unit": "十二、應收款項", "topic": "備抵損失(預期信用損失)", "stem": "臺南公司 02 年初應收帳款淨額 $646,800(假設每年損失率均為 2%),02 年度賒銷 $160,000,賒銷的銷貨退回 $40,000,帳款收現 $80,000(不含實際發生沖銷後又收回 $10,000),實際發生沖銷帳款 $25,000,試問臺南公司 02 年底應提列「備抵損失-應收帳款」金額為何?", "options": ["$13,500", "$15,300", "$15,500", "$25,300"], "answer": "B", "figure": null, "official": "期初應收帳款$660,000(=646,800÷0.98);期末應收帳款$675,000;備抵損失期初$13,200、收回$10,000、沖銷$25,000,調整$15,300,期末餘額$13,500(675,000×2%)。", "explain": {"concept": "用 T 字帳推出期末應收帳款,再算期末備抵損失應有餘額 2%,與調整前餘額的差就是本年應提列金額。", "steps": ["期初淨額=總額×(1−2%),所以期初應收帳款總額=$646,800÷0.98=$660,000;期初備抵損失=$660,000×2%=$13,200。", "期末應收帳款:$660,000+賒銷 $160,000−銷貨退回 $40,000−收現 $80,000−沖銷 $25,000+沖銷後收回(先轉回應收)$10,000−該筆再收現 $10,000=$675,000。", "期末備抵損失應有餘額=$675,000×2%=$13,500。", "調整前備抵損失餘額=期初 $13,200+收回 $10,000−沖銷 $25,000=−$1,800(借餘)。", "本年應提列(調整)金額=$13,500−(−$1,800)=$15,300。題目問「應提列」金額,所以選 $15,300,不是期末餘額 $13,500。"], "pitfalls": "題目問的是本期「應提列」(調整分錄)金額,不是期末備抵損失餘額;還要記得沖銷後收回的兩筆分錄。", "distractors": {"A": "$13,500 是期末備抵損失餘額,不是應提列金額。"}}, "check": "python:期初總額=660000;期末應收=675000;調整前備抵=13200+10000−25000=−1800;調整=13500+1800=15300,與官方相符。", "verified": true, "note": ""}, {"id": "111-3-A-14", "exam": "111-3", "paper": "A", "q": 14, "unit": "十二、應收款項", "topic": "應收票據貼現(貼現率)", "stem": "高雄公司 8 月 1 日銷貨一批,收到附年息 6%、四個月期面額 $360,000 之票據一張。公司因有資金需求,故於同年 9 月 1 日持該票據向銀行貼現,已知公司於貼現日曾認列應收票據貼現負債折價 $3,780,請問貼現率為何?", "options": ["8%", "9%", "10%", "11%"], "answer": "C", "figure": null, "official": "票據利息=$360,000×6%×4/12=$7,200;到期值=$367,200;貼現息=$367,200×貼現率×3/12;持有期間利息收入=$360,000×6%×1/12=$1,800;貼現日票據帳面金額=$361,800;貼現金額=$361,800−$3,780=$358,020;貼現息=$9,180,貼現率=10%。", "explain": {"concept": "貼現的步驟:算到期值→算已持有利息→由折價反推貼現金額→求貼現息→求貼現率。", "steps": ["票據利息=$360,000×6%×4/12=$7,200;到期值=$360,000+$7,200=$367,200。", "8/1~9/1 持有 1 個月,應計利息收入=$360,000×6%×1/12=$1,800;貼現日票據帳面金額=$360,000+$1,800=$361,800。", "貼現日「應收票據貼現負債折價」$3,780=票據帳面金額−貼現金額(銀行給的現金),所以貼現金額=$361,800−$3,780=$358,020。", "貼現息=到期值−貼現金額=$367,200−$358,020=$9,180。", "貼現期間為 9/1 到 12/1,共 3 個月:$9,180=$367,200×貼現率×3/12,貼現率=$9,180÷($367,200×3/12)=10%。"], "pitfalls": "貼現息要用「到期值」計算,不是面額;貼現期間是 3 個月(貼現日到到期日),不是持有期間 1 個月。", "distractors": {}}, "check": "python:(367200-358020)/(367200×3/12)=0.10,與官方相符。", "verified": true, "note": ""}, {"id": "111-3-A-15", "exam": "111-3", "paper": "A", "q": 15, "unit": "十三、存貨", "topic": "存貨錯誤對淨利的影響", "stem": "花蓮公司對存貨盤點採定期盤存制,已知各年帳列淨利及期末存貨之錯誤情形如下:\n\n| 年度 | 帳上淨利 | 期末存貨 |\n|---|---|---|\n| 107 | $950,000 | 高估 $40,000 |\n| 108 | 800,000 | 低估 30,000 |\n| 109 | 650,000 | 無誤 |\n| 110 | 780,000 | 高估 80,000 |\n\n有關花蓮公司各年度正確的淨利,下列敘述何者正確?", "options": ["107 年度為 $990,000", "108 年度為 $870,000", "109 年度為 $650,000", "110 年度為 $860,000"], "answer": "B", "figure": null, "official": "(A)107年度淨利=$950,000−$40,000=$910,000;(B)108年度淨利=$800,000+$40,000+$30,000=$870,000;(C)109年度淨利=$650,000−$30,000=$620,000;(D)110年度淨利=$780,000−$80,000=$700,000。", "explain": {"concept": "期末存貨錯誤會影響當年淨利(同向),也會影響下一年度淨利(反向)。", "steps": ["先記規則:期末存貨高估→當年銷貨成本低估→淨利高估;下年度期初存貨就多了,淨利反而低估。", "107:期末高估 $40,000,淨利高估,正確=$950,000−$40,000=$910,000。", "108:受 107 期末高估影響(期初存貨多了),淨利低估 $40,000;自己期末又低估 $30,000,淨利再低估 $30,000。正確=$800,000+$40,000+$30,000=$870,000。", "109:受 108 期末低估影響(期初少了),淨利高估 $30,000;本期無誤。正確=$650,000−$30,000=$620,000。", "110:期末高估 $80,000,淨利高估,正確=$780,000−$80,000=$700,000。", "所以只有(B)正確。"], "pitfalls": "忘了上一年度的錯誤會「反向」影響本年度;或把高估、低估的加減做反。", "distractors": {"A": "把高估 $40,000 加上去($950,000+$40,000=$990,000),方向做反。", "C": "沒有考慮 108 年末低估對 109 年的影響,直接用帳上數字。", "D": "把高估 $80,000 加上去($780,000+$80,000=$860,000),方向做反。"}}, "check": "python:910000、870000、620000、700000,僅(B)為870,000,與官方相符。", "verified": true, "note": ""}, {"id": "111-3-A-16", "exam": "111-3", "paper": "A", "q": 16, "unit": "十三、存貨", "topic": "成本流動假設", "stem": "有關存貨的成本流動假設,下列何者錯誤?", "options": ["可替換之大量存貨若採個別認定法,易發生損益操縱,故不宜採用", "物價上漲時,採先進先出法,從綜合損益表觀點,易造成虛盈實虧", "物價上漲時,先進先出法的銷貨成本小於平均法", "採移動平均法,須於每次進貨時重新計算單位成本,僅適用於定期盤存制"], "answer": "D", "figure": null, "official": "(D)僅適用於永續(帳面)盤存制。", "explain": {"concept": "各種存貨計價方法的特性與適用的盤存制度。", "steps": ["(A)可替換的大量存貨若用個別認定法,可以挑選出售哪一批來操縱損益,所以不適合,敘述正確。", "(B)物價上漲時,先進先出法銷貨成本用舊(便宜)成本,利潤偏高,但重置成本變貴,形成「虛盈實虧」,正確。", "(C)同樣物價上漲,先進先出法的銷貨成本比平均法小,正確。", "(D)移動平均法是「每次進貨後」重新計算平均單位成本,必須隨時有帳面存貨紀錄,只適用於永續盤存制,所以(D)說「僅適用定期盤存制」是錯的。"], "pitfalls": "移動平均法 vs 加權平均法:移動平均用於永續盤存制,加權平均用於定期盤存制,別弄反。", "distractors": {"A": "此為正確敘述。", "B": "此為正確敘述。", "C": "此為正確敘述,物價上漲時先進先出銷貨成本較小。"}}, "check": "概念題:依官方詳解與存貨計價常識確認(D)為錯誤。", "verified": true, "note": ""}, {"id": "111-3-A-17", "exam": "111-3", "paper": "A", "q": 17, "unit": "十三、存貨", "topic": "存貨帳面金額與備抵存貨跌價", "stem": "存貨的帳面金額為存貨減備抵存貨跌價,期初存貨的帳面金額為 $7,300,備抵存貨跌價帳戶調整後增加 $110 至年底餘額為 $1,060,期末帳面金額比期初多 $200,試問期末「存貨」帳戶金額為何?", "options": ["$7,500", "$8,160", "$8,250", "$8,560"], "answer": "D", "figure": null, "official": "期初備抵存貨跌價=$1,060−$110=$950;期初存貨=$7,300+$950=$8,250;期末帳面金額=$7,300+$200=$7,500;期末存貨=$7,500+$1,060=$8,560。", "explain": {"concept": "帳面金額(淨額)=存貨(成本)−備抵存貨跌價,先算出帳面金額,再把備抵加回去才是「存貨」帳戶。", "steps": ["期初帳面金額 $7,300;期末帳面金額比期初多 $200,所以期末帳面金額=$7,300+$200=$7,500。", "期末備抵存貨跌價 $1,060。", "期末「存貨」帳戶金額=帳面金額+備抵=$7,500+$1,060=$8,560。", "(補充)期初備抵=$1,060−$110=$950,期初存貨=$7,300+$950=$8,250。"], "pitfalls": "題目問的是「存貨」帳戶(未扣備抵),不是帳面金額($7,500);也別拿期初存貨 $8,250 當答案。", "distractors": {"A": "$7,500 是期末的帳面金額(已扣備抵),不是存貨帳戶。", "C": "$8,250 是期初的存貨帳戶金額。"}}, "check": "python:(7300+200)+1060=8560,與官方相符。", "verified": true, "note": ""}, {"id": "111-3-A-18", "exam": "111-3", "paper": "A", "q": 18, "unit": "十五、長期營業用資產", "topic": "不動產廠房及設備取得成本", "stem": "臺東公司以不同方式取得各種不同的不動產、廠房及設備,下列敘述何者錯誤?", "options": ["政府無條件贈與公司房屋一棟,貸記:遞延政府補助之利益", "以分期付款方式購入運輸設備,應以現金價格加直接可歸屬之必要成本作為運輸設備的入帳成本", "購入機器一部,支付的營業稅、安裝費、運費為機器設備的成本", "自行建造廠房,支付給建築師的設計費、挖掘地基、建造期間的融資利息皆為廠房的成本"], "answer": "C", "figure": null, "official": "(C)購入機器支付的營業稅屬進項稅額,非機器設備成本。", "explain": {"concept": "不動產廠房及設備的成本=購價+使可供使用所需的一切必要支出,但可扣抵的營業稅不計入。", "steps": ["(C)營業人購買機器支付的營業稅是進項稅額,可以抵銷銷項稅額,不屬於機器成本;只有安裝費、運費等才計入成本。所以(C)錯誤。", "(A)政府無條件贈與的資產,借:房屋,貸:遞延政府補助之利益,正確。", "(B)分期付款購入,以現金價格(不含利息)加必要成本入帳,正確。", "(D)自建廠房的設計費、整地、建造期間符合資本化的借款利息,都屬於成本,正確。"], "pitfalls": "把營業稅一律當成成本;其實可扣抵的進項稅額另記「進項稅額」帳戶。", "distractors": {"A": "此為正確敘述。", "B": "此為正確敘述,分期付款以現金價格入帳。", "D": "此為正確敘述,符合資本化條件的利息可計入成本。"}}, "check": "概念題:依官方詳解與取得成本常識確認(C)為錯誤。", "verified": true, "note": ""}, {"id": "111-3-A-19", "exam": "111-3", "paper": "A", "q": 19, "unit": "十五、長期營業用資產", "topic": "會計估計變動(年數合計法改直線法)", "stem": "雲林公司於 02 年初購買一部機器,成本 $916,000,耐用年限 8 年,殘值 $16,000,採年數合計法提折舊,至 05 年底調整前發現機器共可用 9 年,改採直線法提折舊,試問 06 年折舊額為何?", "options": ["$37,500", "$39,100", "$62,500", "$65,167"], "answer": "C", "figure": null, "official": "至05年底調整前累計折舊=($916,000−$16,000)×(8+7+6)/36=$525,000;06年折舊=($916,000−$525,000−$16,000)÷(9−3)=$62,500。", "explain": {"concept": "耐用年限改變屬「會計估計變動」,從變動當期起「推延適用」:用帳面金額扣殘值,除以剩餘年限。", "steps": ["年數合計法:8 年的年數總和=8+7+6+5+4+3+2+1=36。", "至 05 年底調整前,已提折舊 02、03、04 三年:($916,000−$16,000)×(8+7+6)/36=$900,000×21/36=$525,000。", "新估計共 9 年,已用 3 年,剩 9−3=6 年;帳面金額=$916,000−$525,000=$391,000。", "改直線法,每年折舊=($391,000−殘值 $16,000)÷6=$62,500。05 年、06 年各提 $62,500,所以 06 年折舊為 $62,500。"], "pitfalls": "剩餘年限是 9−3=6 年(因為 05 年折舊尚未提列);別把已提 4 年當成已用年數。", "distractors": {}}, "check": "python:900000×21/36=525000;(916000−525000−16000)/6=62500,與官方相符。", "verified": true, "note": ""}, {"id": "111-3-A-20", "exam": "111-3", "paper": "A", "q": 20, "unit": "十五、長期營業用資產", "topic": "資本支出誤列與追溯更正", "stem": "金門公司 01 年初購買機器一部 $1,050,000(內含運送中不慎損壞的修理費 $50,000),估計使用年限 5 年,無殘值,按直線法提折舊,02 年底調整後結帳前發現,下列調整分錄何者正確?", "options": ["借:累計折舊-機器設備  20,000\n借:追溯適用及追溯重編之影響數  40,000\n  貸:機器設備成本  50,000\n  貸:折舊  10,000", "借:累計折舊-機器設備  20,000\n借:追溯適用及追溯重編之影響數  30,000\n  貸:機器設備成本  50,000", "借:累計折舊-機器設備  20,000\n借:追溯適用及追溯重編之影響數  40,000\n  貸:機器設備成本  50,000\n  貸:本期損益  10,000", "借:累計折舊-機器設備  10,000\n借:追溯適用及追溯重編之影響數  40,000\n  貸:機器設備成本  50,000"], "answer": "A", "figure": null, "official": "累計折舊=$50,000÷5×2=$20,000;02年結帳前發現,所以02年折舊未轉本期損益。", "explain": {"concept": "把本該列費用的 $50,000 誤記為機器成本,屬前期錯誤:要把多提的折舊沖回,並區分「前期」與「本期」的影響。", "steps": ["修理費 $50,000 本該當費用(01 年),卻被記進機器成本,並跟著每年提折舊:$50,000÷5=$10,000/年。", "02 年底已經提了 2 年折舊在這 $50,000 上:$10,000×2=$20,000,要「借:累計折舊 $20,000」沖回。", "機器設備成本要減少 $50,000:「貸:機器設備成本 $50,000」。", "01 年的影響(已結帳,屬前期):01 年少列費用 $50,000,又多提折舊 $10,000,淨影響=$50,000−$10,000=$40,000,借:追溯適用及追溯重編之影響數 $40,000。", "02 年的折舊 $10,000 是本期帳,還沒結帳,直接貸記「折舊」$10,000 沖回即可。", "借貸合計:借 $20,000+$40,000=$60,000;貸 $50,000+$10,000=$60,000,平衡。選(A)。"], "pitfalls": "要分清「前期」(動用追溯適用影響數)與「本期」(直接調整當期帳戶);因為 02 年還沒結帳,不必用「本期損益」。", "distractors": {"B": "前期影響數算成 $30,000,借貸雖然平衡,但忽略了 02 年折舊 $10,000 的調整。", "C": "02 年折舊要直接沖「折舊」帳戶;因為尚未結帳,不會用「本期損益」。", "D": "累計折舊只借 $10,000,只算一年折舊,忽略了第二年。"}}, "check": "python:50000/5×2=20000;前期影響50000−10000=40000;借貸皆60000,與官方相符。", "verified": true, "note": ""}, {"id": "111-3-A-21", "exam": "111-3", "paper": "A", "q": 21, "unit": "十五、長期營業用資產", "topic": "不動產廠房設備相關處理", "stem": "下列敘述何者正確?", "options": ["當不動產、廠房及設備不堪使用,即可予以報廢,以報廢資產入帳", "因疫情關係暫停營業,相關設備暫時閒置,此設備仍列為不動產、廠房及設備", "待出售非流動資產,列為非流動資產,繼續提折舊", "出售營業用設備,產生處分損益,列為營業外收入"], "answer": "B", "figure": null, "official": "(A)帳面金額轉為處分資產損失,非以報廢資產入帳;(C)列為流動資產,不提列折舊;(D)處分損益,列為營業外收入(支出)。", "explain": {"concept": "不動產廠房及設備的報廢、閒置、待出售與處分損益的處理。", "steps": ["(B)暫時閒置的設備仍符合不動產、廠房及設備的定義,仍然列在 PP&E,並繼續提列折舊,所以正確。", "(A)不堪使用要報廢時,是把帳面金額轉成「處分資產損失」,不是另外用「報廢資產」帳戶入帳。", "(C)待出售的非流動資產,要重分類為「流動資產」,並且停止提列折舊。", "(D)出售營業用設備的處分損益,應列為「營業外」收益或損失(其他利益及損失),(D)的文字說「營業外收入」,依官方說明此選項不正確。"], "pitfalls": "「待出售」與「閒置」不同:待出售要轉流動資產、不再折舊;閒置仍是 PP&E,折舊照提。", "distractors": {"A": "報廢時應轉為處分資產損失,不是以報廢資產入帳。", "C": "待出售非流動資產應列流動資產且不提折舊。", "D": "依官方詳解,(D)的說法被判定為錯誤。"}}, "check": "概念題:依官方詳解確認(B)正確。(D)選項依官方詳解判定錯誤,但詳解理由簡略。", "verified": true, "note": ""}, {"id": "111-3-A-22", "exam": "111-3", "paper": "A", "q": 22, "unit": "十四、證券投資", "topic": "股票投資相關常識", "stem": "以我國目前上市公司之情形,針對投資宏碁公司股票(上市公司),下列敘述何者錯誤?", "options": ["公開發行股票公司的主管機關是財政部", "宏碁公司股票發行時得免印製股票", "宏碁公司股票的公開交易平台為證券交易所", "股票屬於權益證券"], "answer": "A", "figure": null, "official": "(A)公開發行股票公司的主管機關是金管會。", "explain": {"concept": "證券市場基本常識:主管機關、無實體發行、交易所與權益證券。", "steps": ["(A)公開發行股票公司的主管機關是「金融監督管理委員會(金管會)」,不是財政部,所以此敘述錯誤。", "(B)公開發行公司股票可採無實體發行(免印製股票),正確。", "(C)上市股票在證券交易所公開買賣,正確。", "(D)股票代表對公司的所有權,屬於權益證券,正確。"], "pitfalls": "舊的證券主管機關說法(財政部)已不適用,現在是金管會。", "distractors": {"B": "此為正確敘述,上市公司可不印製股票。", "C": "此為正確敘述,上市股票在證券交易所交易。", "D": "此為正確敘述,股票屬權益證券。"}}, "check": "概念題:依官方詳解與證券交易常識確認(A)為錯誤。", "verified": true, "note": ""}, {"id": "111-3-A-23", "exam": "111-3", "paper": "A", "q": 23, "unit": "十四、證券投資", "topic": "FVTPL 金融資產期末評價", "stem": "桃園公司為調節資金、獲取收益,在 01 年初以 $180,000 購入草潔公司普通股 5,000 股,每股面額 10 元,另支付手續費 $1,000,作為透過損益按公允價值衡量之金融資產,於 01/7/31 收到現金股利 $9,000、股票股利每股 1 元,01 年底該股票的公允價值為每股 $32,02 年底「強制透過損益按公允價值衡量之金融資產評價調整」餘額 $10,000(借餘),則 01 年期末衡量分錄何者正確?", "options": ["借:透過損益按公允價值衡量之金融資產損失 $5,000", "貸:透過損益按公允價值衡量之金融資產利益 $5,000", "借:透過損益按公允價值衡量之金融資產損失 $4,000", "貸:透過損益按公允價值衡量之金融資產利益 $4,000"], "answer": "C", "figure": null, "official": "01年初成本$180,000;股票股利率=$1÷$10=10%;股數=5,000×(1+10%)=5,500股;01年底公允價值=$32×5,500股=$176,000;借:損失$4,000,貸:評價調整$4,000。", "explain": {"concept": "FVTPL 資產取得時手續費記費用;期末按公允價值衡量,差額列入損益。股票股利只增加股數、不增加成本。", "steps": ["取得成本=$180,000(手續費 $1,000 要當費用,不計入成本)。", "股票股利每股 1 元、面額 10 元,等於 10% 的股票股利,股數增加:5,000×10%=500 股,共 5,500 股。成本不變,仍為 $180,000。", "01 年底公允價值=每股 $32×5,500 股=$176,000。", "評價差額=$176,000−$180,000=−$4,000,公允價值比成本低,是損失。", "分錄:\n借:透過損益按公允價值衡量之金融資產損失  4,000\n  貸:強制透過損益按公允價值衡量之金融資產評價調整  4,000"], "pitfalls": "忘記股票股利使股數增加(用 5,000 股算成 $160,000);或把手續費算進成本。", "distractors": {"A": "把手續費 $1,000 算進成本($181,000−$176,000=$5,000),不正確。", "B": "方向與金額都不對。", "D": "金額正確但方向錯,公允價值低於成本應是損失而非利益。"}}, "check": "python:180000−32×5500=4000(損失),與官方相符。", "verified": true, "note": ""}, {"id": "111-3-A-24", "exam": "111-3", "paper": "A", "q": 24, "unit": "十四、證券投資", "topic": "FVTPL 金融資產帳面金額", "stem": "承上題,02 年底資產負債表上金融資產帳面金額為多少?", "options": ["$176,000", "$178,000", "$186,000", "$190,000"], "answer": "D", "figure": null, "official": "$180,000+$10,000=$190,000。", "explain": {"concept": "金融資產帳面金額=成本+評價調整(借餘加、貸餘減)。", "steps": ["成本仍是 $180,000(股票股利只增加股數,不改變總成本)。", "02 年底「強制透過損益按公允價值衡量之金融資產評價調整」為借餘 $10,000,表示公允價值比成本高 $10,000。", "帳面金額(=02 年底公允價值)=$180,000+$10,000=$190,000。"], "pitfalls": "別拿 01 年底的 $176,000 當答案,題目問的是 02 年底。", "distractors": {"A": "$176,000 是 01 年底的公允價值。", "C": "$186,000 是 $176,000+$10,000,把 01 年底公允價值加上評價調整,重複計算。"}}, "check": "python:180000+10000=190000,與官方相符。", "verified": true, "note": ""}, {"id": "111-4-A-01", "exam": "111-4", "paper": "A", "q": 1, "unit": "五、過帳與分類帳", "topic": "過帳意義", "stem": "公司於執行相關會計作業時,將分錄的會計項目及金額予以分類並轉記的會計程序稱為下列何者?", "options": ["分錄", "過帳", "調整", "試算"], "answer": "B", "figure": null, "official": "將分錄的科目與金額分類轉記到分類帳,稱為過帳。", "explain": {"concept": "會計循環中,把日記簿的分錄「轉記」到分類帳各帳戶的動作叫過帳。", "steps": ["先看關鍵字:「分類並轉記」,表示是把分錄搬到各科目帳戶裡。", "日記簿記的是分錄,分類帳是依科目分開的帳戶;從日記簿搬到分類帳的動作就叫「過帳」。", "所以答案是(B)過帳。"], "pitfalls": "把「分錄」(記錄在日記簿)和「過帳」(轉記到分類帳)搞混。", "distractors": {"A": "分錄是依交易寫出借貸科目與金額,這是過帳的前一步,還沒有轉記。", "C": "調整是期末為了符合應計基礎而作的更正性分錄,不是分類轉記。", "D": "試算是把各帳戶餘額列出來檢查借貸是否相等。"}}, "check": "概念題,依會計循環定義(分錄→過帳→試算)確認。", "verified": true, "note": ""}, {"id": "111-4-A-02", "exam": "111-4", "paper": "A", "q": 2, "unit": "三、會計基本法則", "topic": "借貸法則", "stem": "依據借貸法則,下列何者之交易分錄不會成立?", "options": ["費用增加與負債增加", "資產增加與負債減少", "資產增加與權益增加", "資產減少與費用增加"], "answer": "B", "figure": null, "official": "資產增加與負債減少皆在借方,分錄不會成立。", "explain": {"concept": "借貸法則:資產、費用增加記借方;負債、權益、收益增加記貸方,減少則相反。分錄必須有借有貸。", "steps": ["先列出各項目的借貸方向:資產增加=借、資產減少=貸;負債增加=貸、負債減少=借;權益增加=貸;費用增加=借。", "(A)費用增加(借)+負債增加(貸):有借有貸,成立。", "(B)資產增加(借)+負債減少(借):兩個都在借方,沒有貸方,不成立。", "(C)資產增加(借)+權益增加(貸):成立。", "(D)資產減少(貸)+費用增加(借):成立。"], "pitfalls": "只記得「增加減少」,卻沒有逐項判斷借貸方向。", "distractors": {"A": "費用增加借、負債增加貸,有借有貸,是會成立的分錄。", "C": "資產增加借、權益增加貸(如股東投資),成立。", "D": "資產減少貸、費用增加借(如付現支付費用),成立。"}}, "check": "逐項判斷借貸方向,只有(B)同在借方。", "verified": true, "note": ""}, {"id": "111-4-A-03", "exam": "111-4", "paper": "A", "q": 3, "unit": "六、試算與試算表", "topic": "錯誤對試算表的影響", "stem": "小叮噹公司現購商品$3,000,會計人員卻誤記錄為借:應付帳款$3,000、貸:現金$3,000,則此錯誤對小叮噹公司編製之餘額式試算表的影響為何?", "options": ["餘額式試算表仍平衡且借貸合計數正確", "餘額式試算表仍平衡,但借貸方合計數皆高估$3,000", "餘額式試算表仍平衡,但借貸方合計數皆低估$3,000", "餘額式試算表不平衡且借貸方合計數相差$6,000"], "answer": "C", "figure": null, "official": "正確分錄應為借:進貨 3,000、貸:現金 3,000;誤記後借貸仍相等,餘額式試算表仍平衡,但借貸方合計數皆低估$3,000。", "explain": {"concept": "錯誤分錄若借貸金額相等,試算表仍會平衡;要判斷的是各帳戶餘額改變後,借貸方餘額合計數是高估還是低估。", "steps": ["先寫出正確分錄:借:進貨 3,000、貸:現金 3,000。", "再看誤記分錄:借:應付帳款 3,000、貸:現金 3,000。貸方現金一樣,所以兩者只差在借方科目。", "正確做法借方是「進貨」(借方餘額 +3,000);誤記後變成「應付帳款」減少 3,000(應付帳款本來是貸方餘額,借記使貸方餘額減少 3,000)。", "結果:借方餘額少了進貨 3,000,貸方餘額少了應付帳款 3,000,所以借貸方合計數「皆低估 $3,000」。", "借貸兩邊同時少 3,000,仍然相等,試算表平衡。答案(C)。"], "pitfalls": "以為錯誤分錄一定會讓試算表不平衡;其實借貸相等的錯誤(用錯科目)試算表看不出來。", "distractors": {"A": "合計數會因誤記而改變,不是正確的。", "B": "方向相反,誤記使借貸合計減少而非增加。", "D": "借貸兩邊同時少記,仍然平衡,不會差 6,000。"}}, "check": "以正確分錄與誤記分錄逐帳戶比較:借方餘額-3,000,貸方餘額-3,000,仍平衡,與官方一致。", "verified": true, "note": ""}, {"id": "111-4-A-04", "exam": "111-4", "paper": "A", "q": 4, "unit": "十三、存貨", "topic": "期末存貨錯誤的影響", "stem": "阿弟公司存貨數量盤點採定期盤存制,X8年的帳務記錄發生錯誤,造成該年度的期末存貨漏計$80,000,請問此錯誤對於公司X8年度及X9年度的銷貨成本及淨利的影響(不考慮所得稅),下列敘述何者正確?", "options": ["導致X8年度銷貨成本高估$80,000、淨利低估$80,000", "導致X8年度銷貨成本低估$80,000、淨利高估$80,000", "導致X9年度銷貨成本高估$80,000、淨利高估$80,000", "導致X9年度銷貨成本低估$80,000、淨利低估$80,000"], "answer": "A", "figure": null, "official": "X8期末存貨低估$80,000,銷貨成本高估、淨利低估;X9期初存貨亦低估,銷貨成本低估、淨利高估。", "explain": {"concept": "銷貨成本=期初存貨+進貨-期末存貨。期末存貨錯誤會影響當年度,又因為是下一年的期初存貨,會在下一年度反向影響。", "steps": ["公式:銷貨成本=期初存貨+本期進貨-期末存貨。", "X8年期末存貨少記(漏計)$80,000,減項變小,所以X8銷貨成本高估$80,000。", "銷貨成本高估,表示費用多了,所以X8淨利低估$80,000。", "X8期末存貨就是X9期初存貨,所以X9期初存貨也低估$80,000,加項變小,X9銷貨成本低估$80,000,X9淨利高估$80,000。", "對照選項,X8的敘述只有(A)正確。(C)、(D)的方向都錯。"], "pitfalls": "忘記錯誤在第二年會「反向」影響;或把高估、低估方向記反。", "distractors": {"B": "把X8的方向弄反了:期末存貨低估會使銷貨成本高估,不是低估。", "C": "X9銷貨成本是低估而非高估,淨利才是高估。", "D": "X9銷貨成本低估正確,但淨利應為高估而非低估。"}}, "check": "以數字驗證:設正確期末存貨為S,正確銷貨成本C。誤差後期末存貨=S-80,000,銷貨成本=C+80,000(高估),淨利低估;X9反向,與官方一致。", "verified": true, "note": ""}, {"id": "111-4-A-05", "exam": "111-4", "paper": "A", "q": 5, "unit": "七、調整", "topic": "預付保險費推算購買日", "stem": "小微公司每月底皆會進行會計事項之調整,公司在X8年的某月初曾經購買一張為期一年的保單,在X9/1/31作完調整分錄後,保險費餘額為$300,預付保險費餘額為$1,200,請問小微公司在X8年的哪一天購買此張保單?", "options": ["5月1日", "6月1日", "7月1日", "8月1日"], "answer": "B", "figure": null, "official": "每月保險費$300,預付$1,200代表尚有4個月,故一年保單在X8/6/1購入。", "explain": {"concept": "預付費用調整:保險費每月攤銷相同金額,先求每月攤銷額,再推已用月數與剩餘月數。", "steps": ["保單期間一年,每月調整,X9/1/31調整後的「保險費」餘額只有$300,表示這個月(1月)認列的保險費就是$300(每月保險費)。", "每月保險費$300,所以全年保費=$300×12=$3,600。", "X9/1/31調整後預付保險費餘額$1,200,表示尚未攤銷的月數=$1,200÷$300=4個月(2、3、4、5月)。", "保單期間共12個月,剩4個月,所以到X9/1/31已經過了12-4=8個月。", "這8個月是從購買月到X9年1月:X9年1月是第8個月,往前數X8年12月、11月、10月、9月、8月、7月、6月共7個月,所以保單從X8/6/1開始(6月至隔年5月),選(B)。"], "pitfalls": "忘記「保險費餘額$300」只是一個月的數字(每月調整後科目餘額),而把它當成累計數。", "distractors": {"A": "5月1日購買,到X9/1/31已用9個月,預付只剩3個月($900)。", "C": "7月1日購買,到X9/1/31已用7個月,預付應剩5個月($1,500)。", "D": "8月1日購買,已用6個月,預付應剩6個月($1,800)。"}}, "check": "6/1購買:保險到X9/5/31,X9/1/31後剩2~5月共4個月×$300=$1,200,吻合。", "verified": true, "note": ""}, {"id": "111-4-A-06", "exam": "111-4", "paper": "A", "q": 6, "unit": "八、結帳", "topic": "結帳後帳戶餘額", "stem": "請問公司於期末辦理「結帳」後,下列敘述何者正確?", "options": ["所有帳戶餘額均為零", "資產、負債及權益帳戶餘額為零", "收益、費損及保留盈餘帳戶餘額必為零", "收益、費損及本期損益帳戶餘額為零"], "answer": "D", "figure": null, "official": "結帳後虛帳戶(收益、費損)及本期損益餘額為零。", "explain": {"concept": "結帳的目的是把虛帳戶(損益類帳戶)歸零,並將本期損益轉入權益(保留盈餘)。實帳戶餘額則結轉到下期。", "steps": ["虛帳戶(收益、費損)只記錄單一期間,期末要結清;結帳時先轉入「本期損益」(或損益彙總),再把本期損益結轉到保留盈餘。", "所以結帳後,收益、費損及本期損益(過渡帳戶)餘額都是零。", "實帳戶(資產、負債、權益,含保留盈餘)餘額要帶到下期,不會歸零。", "因此(D)正確。"], "pitfalls": "以為結帳後所有帳戶都歸零,或把保留盈餘也當成歸零帳戶。", "distractors": {"A": "資產、負債、權益是實帳戶,餘額帶到下期。", "B": "資產、負債、權益都不歸零。", "C": "保留盈餘是權益,結帳後會有餘額(包含本期損益轉入的金額)。"}}, "check": "概念題,依結帳程序(虛帳戶歸零、實帳戶結轉)確認,與官方一致。", "verified": true, "note": ""}, {"id": "111-4-A-07", "exam": "111-4", "paper": "A", "q": 7, "unit": "九、財務報表", "topic": "流動比率推算", "stem": "臺南公司在X8年底營運資金有$540,000,X9/1/1賒購一批商品成本$600,000,當天並將該商品按成本加計30%之利潤全部賒銷。臺南公司存貨數量衡量採永續盤存制,X9/1/1計入此兩筆交易後其流動比率為2,則臺南公司X8年底的流動比率為何?", "options": ["1.75", "2.2", "3.5", "5.5"], "answer": "D", "figure": null, "official": "設X8年底流動負債CL,依X9/1/1流動比率為2解得CL=$120,000,X8年底流動比率=($540,000+$120,000)/$120,000=5.5。", "explain": {"concept": "營運資金=流動資產-流動負債;流動比率=流動資產÷流動負債。先用交易後的比率2建立方程式求流動負債。", "steps": ["設X8年底流動負債為CL,則流動資產=CL+$540,000。", "賒購存貨$600,000:存貨增加(流動資產+$600,000),應付帳款增加(流動負債+$600,000)。", "賒銷,售價=$600,000×(1+30%)=$780,000:應收帳款增加$780,000,存貨減少$600,000。", "交易後流動資產=($540,000+CL)+$600,000+$780,000-$600,000=$540,000+CL+$780,000;流動負債=CL+$600,000。", "流動比率為2:($540,000+CL+$780,000)/(CL+$600,000)=2,即$1,320,000+CL=2CL+$1,200,000,解得CL=$120,000。", "X8年底流動資產=$540,000+$120,000=$660,000,流動比率=$660,000÷$120,000=5.5,選(D)。"], "pitfalls": "忘記賒購同時增加流動負債,或把賣出後的存貨減少漏掉。", "distractors": {}}, "check": "python驗算:CL=120000時,(540000+120000+600000+780000-600000)/(120000+600000)=2.0,X8比率=660000/120000=5.5,相符。", "verified": true, "note": ""}, {"id": "111-4-A-08", "exam": "111-4", "paper": "A", "q": 8, "unit": "九、財務報表", "topic": "銷貨毛利率", "stem": "臺北公司在X8年底調整後有部份會計項目餘額如下:\n\n| 項目 | 金額 | 項目 | 金額 |\n|---|---|---|---|\n| 銷貨收入 | $600,000 | 銷貨折讓 | $15,000 |\n| 銷貨退回 | $105,000 | 銷貨成本 | $360,000 |\n\n請問臺北公司X8年度之銷貨毛利率為何?", "options": ["75%", "60%", "40%", "25%"], "answer": "D", "figure": null, "official": "銷貨淨額=$600,000-$15,000-$105,000=$480,000;毛利=$480,000-$360,000=$120,000;毛利率=25%。", "explain": {"concept": "銷貨毛利率=銷貨毛利÷銷貨淨額。銷貨淨額要先扣掉銷貨退回與銷貨折讓。", "steps": ["先求銷貨淨額=銷貨收入-銷貨退回-銷貨折讓=$600,000-$105,000-$15,000=$480,000。", "銷貨毛利=銷貨淨額-銷貨成本=$480,000-$360,000=$120,000。", "銷貨毛利率=$120,000÷$480,000=25%。"], "pitfalls": "用銷貨收入$600,000當分母,或忘記扣銷貨退回與折讓。", "distractors": {"A": "$360,000÷$480,000=75%,這是銷貨成本率,不是毛利率。", "B": "$360,000÷$600,000=60%,用總銷貨及成本計算,方式錯誤。", "C": "($600,000-$360,000)÷$600,000=40%,分母用了總額、也沒扣退回折讓。"}}, "check": "python:(600000-15000-105000-360000)/(600000-15000-105000)=0.25。", "verified": true, "note": ""}, {"id": "111-4-A-09", "exam": "111-4", "paper": "A", "q": 9, "unit": "十、加值型營業稅會計實務", "topic": "營業稅申報", "stem": "志明公司於X8年1月開始營業,為採用一般稅率(稅率皆為5%)之加值型營業稅營業人,該公司1月至2月份之相關交易資料如下:\n①銷貨收入計$5,000,000(包括:內銷$2,500,000、外銷$2,500,000)\n②進貨及相關費用計$7,000,000,其中$6,500,000(包括:進貨$5,500,000、修繕費$100,000、春節員工禮品$600,000、交際費$300,000)取得加值型營業人所開立之發票\n③購買機器設備$2,000,000及自用乘人小汽車$1,500,000,均取得加值型營業人所開立之發票\n依據上述資料公司申報1至2月份之營業稅,則下列敘述何者正確?", "options": ["進項稅額$480,000", "應收退稅款$225,000", "留抵稅額$100,000", "留抵稅額$130,000"], "answer": "B", "figure": null, "official": "銷項稅額$125,000;可扣抵進項稅額$380,000;溢付$255,000;退稅限額$225,000,應退$225,000,留抵$30,000。", "explain": {"concept": "營業稅:銷項稅額-進項稅額,若為負數即為溢付稅額。溢付稅額中,可退稅的部分以零稅率銷售額及固定資產購入之稅額為限,其餘留抵。進項稅額中,交際費、自用乘人小汽車、員工福利禮品等不得扣抵。", "steps": ["銷項稅額:內銷$2,500,000×5%=$125,000;外銷為零稅率,稅額0。", "可扣抵進項:進貨$5,500,000、修繕費$100,000、機器設備$2,000,000,共$7,600,000,×5%=$380,000。", "不可扣抵:交際費$300,000、春節員工禮品$600,000、自用乘人小汽車$1,500,000。", "溢付稅額=進項$380,000-銷項$125,000=$255,000。", "退稅限額=(零稅率銷售額$2,500,000+購買固定資產$2,000,000)×5%=$225,000,所以應收退稅款$225,000。", "留抵稅額=$255,000-$225,000=$30,000。選(B)。"], "pitfalls": "把不得扣抵的交際費、禮品、小汽車也算入進項;或不知道退稅有「限額」,把溢付全數當退稅。", "distractors": {"D": "$255,000-$125,000=$130,000:誤把銷項稅額再扣一次,留抵應為$30,000。"}}, "check": "python:進項=(5.5e6+0.1e6+2e6)*5%=380,000;溢付=255,000;退稅限額=225,000;留抵=30,000,相符。", "verified": true, "note": ""}, {"id": "111-4-A-10", "exam": "111-4", "paper": "A", "q": 10, "unit": "十一、現金及內部控制", "topic": "銀行存款調節表", "stem": "魯夫公司X8年6月底臺灣銀行之存款帳戶有關資料如下:\n①6月底銀行對帳單餘額$29,000、未兌現支票$12,000(內含銀行保付支票$7,000)\n②銀行代收票據$2,400,公司尚未入帳\n③公司6月底存入的即期支票$3,100,銀行尚未入帳\n④客戶大雄公司所開支票$1,800,存款不足退票\n⑤銀行手續費$300,公司尚未入帳\n則下列有關魯夫公司X8年6月底臺灣銀行存款調節表中的餘額何者正確?", "options": ["調節後銀行存款正確餘額$27,100", "調節後銀行存款正確餘額$25,100", "調節前公司帳面餘額$25,800", "調節前公司帳面餘額$24,800"], "answer": "A", "figure": null, "official": "銀行方調節後=$29,000+$3,100-$5,000=$27,100;公司方調節前帳面餘額=$26,800。", "explain": {"concept": "銀行存款調節表:銀行方調整「在途存款」「未兌現支票」;公司方調整「銀行代收」「退票」「手續費」等公司尚未入帳的項目。銀行保付支票銀行已先扣款,不是未兌現。", "steps": ["銀行方:餘額$29,000;加在途存款$3,100;減未兌現支票(不含保付支票)=$12,000-$7,000=$5,000。", "調節後銀行存款正確餘額=$29,000+$3,100-$5,000=$27,100。", "公司方:調節前帳面餘額+代收票據$2,400-退票$1,800-手續費$300=調節後$27,100。", "倒推調節前公司帳面餘額=$27,100-$2,400+$1,800+$300=$26,800。", "故(A)正確;(B)$25,100(C)(D)都不對。"], "pitfalls": "把保付支票也算成未兌現支票,或把公司帳要加減的項目弄反。", "distractors": {"C": "調節前公司帳面餘額應為$26,800(已倒推驗算),$25,800不符。"}}, "check": "python:29000+3100-5000=27100;27100-2400+1800+300=26800,雙方一致。", "verified": true, "note": ""}, {"id": "111-4-A-11", "exam": "111-4", "paper": "A", "q": 11, "unit": "十二、應收款項", "topic": "預期信用減損損失", "stem": "已知桃園公司X8年12月31日應收帳款的帳面金額為$550,000,X8年1月1日備抵損失餘額為$50,000,X8年實際發生帳款無法收回$25,000,X8年中收回過去已沖銷帳款$10,000,X8年12月31日應收帳款總額$600,000,請問該公司X8年底應提列之預期信用減損損失金額為何?", "options": ["$15,000", "$25,000", "$35,000", "$45,000"], "answer": "A", "figure": null, "official": "期末備抵損失=$600,000-$550,000=$50,000;提列金額=$50,000-($50,000-$25,000+$10,000)=$15,000。", "explain": {"concept": "應收帳款帳面金額=應收帳款總額-備抵損失,所以可由此求出期末備抵損失;再用T字帳倒推本期應提列金額。", "steps": ["期末備抵損失=應收帳款總額-帳面金額=$600,000-$550,000=$50,000。", "備抵損失T字帳:期初$50,000(貸);實際發生無法收回沖銷$25,000(借);收回已沖銷帳款$10,000(貸,先恢復應收再收現,使備抵增加);本期提列為X(貸)。", "$50,000-$25,000+$10,000+X=$50,000。", "解得X=$15,000,即X8年底應提列的預期信用減損損失,選(A)。"], "pitfalls": "忘記收回已沖銷帳款會使備抵損失增加,或誤用帳面金額$550,000當期末備抵。", "distractors": {"C": "$35,000是提列前的備抵損失餘額($50,000-$25,000+$10,000),不是本期應提列的金額。", "B": "可能只看到實際發生無法收回的$25,000就當成提列金額,忽略期末備抵目標$50,000。"}}, "check": "python:50000-25000+10000+X=50000 → X=15000,相符。", "verified": true, "note": ""}, {"id": "111-4-A-12", "exam": "111-4", "paper": "A", "q": 12, "unit": "十二、應收款項", "topic": "應收帳款概念", "stem": "有關公司應收帳款的敘述,下列何者錯誤?", "options": ["屬於流動資產項下之會計項目", "期末應認列可能無法收回的損失", "其流動性大小比存貨低", "由公司賒銷商品或勞務而產生"], "answer": "C", "figure": null, "official": "應收帳款流動性比存貨高,(C)錯誤。", "explain": {"concept": "流動資產按流動性高低排列:現金、短期投資、應收款項、存貨、預付費用。應收帳款一旦收現就變現金,流動性比存貨高。", "steps": ["(A)應收帳款一年內可收回,屬流動資產,正確。", "(B)期末依預期信用損失模型認列備抵損失,正確。", "(C)存貨還要先賣掉才變成應收或現金,流動性比應收帳款低;說應收帳款流動性比存貨低是錯的。", "(D)賒銷商品或勞務產生應收帳款,正確。題目問「錯誤」,答案選(C)。"], "pitfalls": "審題時看漏「錯誤」二字;或不熟流動性排序。", "distractors": {"A": "敘述正確,題目問錯誤者,不選。", "B": "敘述正確,期末要評估預期信用減損並提列備抵損失。", "D": "敘述正確。"}}, "check": "概念題,依流動資產排列順序與官方詳解確認。", "verified": true, "note": ""}, {"id": "111-4-A-13", "exam": "111-4", "paper": "A", "q": 13, "unit": "四、分錄與日記簿", "topic": "交易分錄判斷", "stem": "有關娜美公司的會計交易紀錄,下列何者正確?", "options": ["收到股東現金投資,借記:現金、貸記:投資收入", "收客戶貨款之訂金,借記:現金、貸記:預收貨款", "償付先前已認列之員工薪資,借記:薪資支出、貸記:現金", "簽發票據償還對供應商之貨欠,借記:應收票據、貸記:應收帳款"], "answer": "B", "figure": null, "official": "(A)應貸記股本;(C)應借記應付薪資;(D)應借記應付帳款、貸記應付票據。", "explain": {"concept": "判斷分錄是否正確,先想交易性質,再決定借貸科目。", "steps": ["(A)股東投資是公司增資,應貸記「股本」,不是收益。", "(B)收到客戶訂金,公司尚未交貨,現金增加(借),形成預收貨款(負債,貸),正確。", "(C)薪資「先前已認列」代表已記應付薪資,現在付款應借記應付薪資,不是再認列費用。", "(D)簽發票據還給供應商,是公司欠供應商錢,應借應付帳款、貸應付票據(不是應收)。選(B)。"], "pitfalls": "沒注意「先前已認列」「簽發」等關鍵字,以致借貸科目選錯。", "distractors": {"A": "股東投資不是收益,不能貸記投資收入。", "C": "已認列的薪資只要借記應付薪資,若再借記薪資支出就重複認列費用。", "D": "簽發票據是公司開出票據(應付票據),不是收到票據,也不是應收帳款。"}}, "check": "概念題,逐項還原正確分錄,與官方詳解一致。", "verified": true, "note": ""}, {"id": "111-4-A-14", "exam": "111-4", "paper": "A", "q": 14, "unit": "十三、存貨", "topic": "出售商品運費的處理", "stem": "春嬌公司為一家具經銷商,常年與國內上市公司「新家具台霸」峰源集團合作,故漸漸從小規模的家具經銷商成長為國內眾所熟知的大型家具經銷商;X年公司擴大營運後,因會計人力短缺,故新聘小美為公司的會計人員,X8年間,公司曾出售兩組辦公桌椅給小夫公司,成交價為$105,000,春嬌公司依據銷售契約應負擔貨運公司運費$5,000,則有關此運費$5,000的交易,身為新進會計人員的小美,應該如何紀錄?", "options": ["應將此運費$5,000列入春嬌公司的存貨成本", "應將此運費$5,000列入春嬌公司的銷貨成本", "應將此運費$5,000列入春嬌公司的營業費用", "此運費$5,000不需作紀錄"], "answer": "C", "figure": null, "official": "春嬌公司應將此$5,000列入營業費用(運費)。", "explain": {"concept": "賣方負擔的出貨運費是銷貨費用(營業費用),不是存貨成本;只有買方購貨時的運入運費才計入進貨成本。", "steps": ["題目是春嬌「出售」商品給小夫,春嬌依合約要負擔運費,這是賣方的運費,即「運費(運出)」。", "進貨運費(運入)才加入存貨成本;出貨運費是為了把貨送到客戶手上的銷售活動支出,應列為營業費用(運費)。", "分錄:借:運費 5,000、貸:現金(或應付帳款)5,000。", "所以選(C)。"], "pitfalls": "把所有運費都算存貨成本,忽略買賣方與運入運出的差別。", "distractors": {"A": "存貨成本只含購入時的運入運費;此為出售後運出,不能加到存貨。", "B": "運出運費不屬銷貨成本,銷貨成本是商品本身的成本。", "D": "契約約定賣方付運費,是實際發生的費用,必須認列。"}}, "check": "概念題,依運費處理原則(運入計存貨成本、運出為營業費用)確認,與官方一致。", "verified": true, "note": ""}, {"id": "111-4-A-15", "exam": "111-4", "paper": "A", "q": 15, "unit": "十三、存貨", "topic": "永續盤存制FIFO", "stem": "臺中公司係一家「皮帶」專賣店,門市就位於臺中市區的臺灣大道上,其在X8年1月份的皮帶進銷存資料如下:\n期初存貨100條,每條單價$440\n1月3日購買40條,每條單價$500\n1月8日銷售50條,\n1月13日購買70條,每條單價$600\n1月20日銷售100條,\n1月28日購買40條,每條單價$700\n根據上述進銷存資料,請問在永續盤存制FIFO法下,1月份銷售皮帶應認列的銷貨成本為何?", "options": ["$90,000", "$80,400", "$70,000", "$64,000"], "answer": "C", "figure": null, "official": "1/8銷50條成本$22,000;1/20銷100條成本$48,000;合計$70,000。", "explain": {"concept": "永續盤存制每次銷貨當下就結轉銷貨成本;先進先出法(FIFO)表示先賣出最早買進的存貨。", "steps": ["1/8銷售50條:先用期初存貨(100條@$440)。成本=50×$440=$22,000。剩餘:期初50條@$440。", "1/3購買的40條@$500在1/8前已買入,排在期初之後;1/13再買70條@$600。", "1/20銷售100條:先用剩下的期初50條@$440=$22,000;再用1/3的40條@$500=$20,000;還差10條,用1/13的@$600=10×$600=$6,000。小計=$22,000+$20,000+$6,000=$48,000。", "1/28購買不影響本月已售的成本。", "1月份銷貨成本=$22,000+$48,000=$70,000,選(C)。"], "pitfalls": "1/8時只算了期初存貨卻把1/3買進的存貨先用;或把1/28的購貨也算進去。", "distractors": {}}, "check": "python:50*440+(50*440+40*500+10*600)=70000,相符。", "verified": true, "note": ""}, {"id": "111-4-A-16", "exam": "111-4", "paper": "A", "q": 16, "unit": "十四、證券投資", "topic": "股利收入的認列", "stem": "柯南公司投資小蘭公司所發行之普通股,小蘭公司在X8年宣告並支付X8年的普通股股利。請問柯南公司應如何認列所收到的X8年股利?", "options": ["貸記應收股利", "貸記追溯適用及追溯重編之影響數", "作為保留盈餘的減少", "認列於綜合損益表,作為當期損益"], "answer": "D", "figure": null, "official": "收到股利應記:借:現金,貸:股利收入,故應認列於綜合損益表,作為當期損益。", "explain": {"concept": "投資股票收到股利,對投資公司而言是股利收入,認列為當期損益。", "steps": ["柯南是股票投資人,小蘭宣告並支付股利。", "對投資人而言,股利屬於投資收益:借:現金 ○○○、貸:股利收入 ○○○。", "股利收入是綜合損益表中的收益,所以選(D)。", "(A)題目是「宣告並支付」,不需要經過應收股利;且若有應收股利也是借記。"], "pitfalls": "把投資人收到股利與發行公司發放股利(保留盈餘減少)搞混。", "distractors": {"A": "貸記應收股利是宣告後、實際收款時才會用的科目;此處是借現金、貸股利收入。", "B": "追溯適用等是會計政策變動的處理,與股利無關。", "C": "保留盈餘減少是「發放股利的公司」的處理,不是收股利的投資人。"}}, "check": "概念題,依一般股利收入認列原則與官方一致。", "verified": true, "note": ""}, {"id": "111-4-A-17", "exam": "111-4", "paper": "A", "q": 17, "unit": "十五、長期營業用資產", "topic": "無形資產", "stem": "有關公開發行公司無形資產會計處理之敘述,下列何者錯誤?", "options": ["有限耐用年限無形資產在攤銷時,若未來經濟效益型態無法可靠決定時,應採用餘額遞減法", "內部產生無形資產者,於研究階段所發生之支出,應認列為費用", "企業內部產生的品牌、客戶名單不得認列為無形資產", "非確定耐用年限之無形資產,應每年作減損測試"], "answer": "A", "figure": null, "official": "有限耐用年限無形資產攤銷方法若無法可靠決定,應採用直線法,(A)錯誤。", "explain": {"concept": "無形資產攤銷方法應反映未來經濟效益的耗用型態;若無法可靠決定該型態,則採直線法。", "steps": ["(A)題目問的是「錯誤」。依準則,攤銷方法若無法可靠決定,應採直線法,不是餘額遞減法,所以(A)錯誤。", "(B)研究階段支出於發生時認列為費用,正確。", "(C)企業內部產生的品牌、報頭、客戶名單等不得認列為無形資產,正確。", "(D)非確定耐用年限的無形資產不攤銷,但每年及有跡象時要作減損測試,正確。", "所以答案是(A)。"], "pitfalls": "記不清攤銷方法,把「無法可靠決定」時的預設當成餘額遞減法。", "distractors": {"B": "敘述正確(研究階段支出費用化,發展階段符合條件才資本化)。", "C": "敘述正確。", "D": "敘述正確。"}}, "check": "概念題,對照無形資產準則(直線法為無法可靠決定時之預設)與官方詳解確認。", "verified": true, "note": ""}, {"id": "111-4-A-18", "exam": "111-4", "paper": "A", "q": 18, "unit": "十五、長期營業用資產", "topic": "處分資產,直線法折舊", "stem": "高雄公司在X5年10月1日以$50,000購入一輛運輸用卡車,估計耐用年限為4年,殘值為$2,000,採直線法提列折舊。X8年5月1日出售後產生利益$6,000,試問運輸卡車的出售價格為何?", "options": ["$8,000", "$13,000", "$19,000", "$25,000"], "answer": "D", "figure": null, "official": "出售日帳面金額=$50,000-累計折舊$31,000=$19,000;出售價格=$19,000+$6,000=$25,000。", "explain": {"concept": "處分利益=出售價格-帳面金額;帳面金額=成本-累計折舊。折舊要按月計算到出售日。", "steps": ["每年折舊=($50,000-$2,000)÷4=$12,000,每月$1,000。", "X5年10月1日~X8年5月1日:X5年10~12月3個月、X6年12個月、X7年12個月、X8年1~4月4個月,共31個月。", "累計折舊=$1,000×31=$31,000。", "帳面金額=$50,000-$31,000=$19,000。", "利益$6,000=出售價格-帳面金額,所以出售價格=$19,000+$6,000=$25,000,選(D)。"], "pitfalls": "忘記折舊要算到出售日,或把利益當損失(應減而非加)。", "distractors": {"C": "$19,000是出售時的帳面金額,還沒有加上處分利益$6,000。"}}, "check": "python:48000/48*31=31000,50000-31000+6000=25000,相符。", "verified": true, "note": ""}, {"id": "111-4-A-19", "exam": "111-4", "paper": "A", "q": 19, "unit": "十五、長期營業用資產", "topic": "資本支出與收益支出", "stem": "當公司誤將修繕費列為機器設備成本時,對當年度財務報表的影響,下列敘述何者正確?", "options": ["高估資產,高估淨利", "高估資產,低估淨利", "低估資產,高估淨利", "低估資產,低估淨利"], "answer": "A", "figure": null, "official": "修繕費誤列為資產,使資產(機器設備成本)高估、費用(修繕費)低估,故淨利高估。", "explain": {"concept": "收益支出(修繕費)應列為當期費用;資本支出才列為資產。誤把費用資本化,會使當期費用變少、資產變多。", "steps": ["正確做法:借:修繕費(費用)、貸:現金。", "錯誤做法:借:機器設備(資產)、貸:現金。", "結果:資產變多(高估);費用少記→淨利多算(高估)。", "(機器設備被多算,之後多提的折舊金額小,當年度主要影響仍是資產高估、淨利高估。)"], "pitfalls": "以為費用少了是低估淨利;或把資產增加和淨利增加方向搞混。", "distractors": {"B": "資產高估正確,但費用少記會使淨利高估而非低估。", "C": "資產是高估,不是低估。", "D": "資產與淨利方向都錯。"}}, "check": "概念題:費用少記→淨利高估,資產多記→高估,與官方一致。", "verified": true, "note": ""}, {"id": "111-4-A-20", "exam": "111-4", "paper": "A", "q": 20, "unit": "十三、存貨", "topic": "農產品會計處理", "stem": "有關公司自生物資產收成之「農產品」之會計處理,下列敘述何者正確?", "options": ["列於資產負債表「生物資產」項下", "原始衡量採用成本原則", "後續衡量採用成本與淨變現價值孰低法衡量", "後續衡量採用淨公允價值衡量"], "answer": "C", "figure": null, "official": "農產品列於存貨;原始衡量採公允價值減出售成本;後續依存貨處理,採成本與淨變現價值孰低法衡量。", "explain": {"concept": "生物資產(如牛、果樹)收成後所得到的農產品(如牛奶、水果)轉為存貨。收成時以公允價值減出售成本作為成本,之後依存貨準則處理。", "steps": ["生物資產(活的動植物)收成後變成農產品,不再是生物資產,所以(A)錯。", "農產品收成時的原始衡量採「公允價值減出售成本」,不是成本原則,(B)錯。", "收成後即適用存貨準則,後續衡量採「成本與淨變現價值孰低」,(C)正確。", "(D)淨公允價值衡量是生物資產收成前的衡量方式,不是農產品。"], "pitfalls": "混淆生物資產與農產品的衡量方式。", "distractors": {"A": "農產品屬存貨,不是生物資產。", "B": "收成時採公允價值減出售成本,不是原始成本。", "D": "公允價值減出售成本是生物資產後續衡量及農產品收成時的原始衡量,不是農產品後續衡量。"}}, "check": "概念題,依IAS 41/IAS 2對農產品之規定與官方詳解確認。", "verified": true, "note": ""}, {"id": "111-4-A-21", "exam": "111-4", "paper": "A", "q": 21, "unit": "十七、權益", "topic": "股票股利對財務報表影響", "stem": "當公司宣告並發放股票股利時,對公司「資產負債表」的影響為何?", "options": ["資產減少", "權益減少", "股本減少", "保留盈餘減少"], "answer": "D", "figure": null, "official": "宣告並發放股票股利:借:保留盈餘(累積虧絀)、貸:普通股股本,故資產不變、權益總額不變、股本增加、保留盈餘減少。", "explain": {"concept": "股票股利是把保留盈餘轉成股本,權益內部項目改變,總額不變。", "steps": ["股票股利分錄:借:保留盈餘(或累積虧絀)、貸:普通股股本(及資本公積)。", "公司沒有付出資產,所以資產不變,(A)錯。", "權益項下:保留盈餘減少、股本增加,權益總額不變,(B)錯。", "股本是增加不是減少,(C)錯。", "保留盈餘減少,(D)正確。"], "pitfalls": "以為發放股利就會讓資產減少(那是現金股利)。", "distractors": {"A": "股票股利不動用資產,資產不變。", "B": "權益有增有減,總額不變。", "C": "股本增加,不是減少。"}}, "check": "概念題,依分錄:借保留盈餘、貸股本,與官方詳解一致。", "verified": true, "note": ""}, {"id": "111-4-A-22", "exam": "111-4", "paper": "A", "q": 22, "unit": "十七、權益", "topic": "股票股利與股票分割", "stem": "有關公司「股票股利」與「股票分割」對股本、每股面額、保留盈餘及股東權益總額等依序的影響,下列何者正確?", "options": ["股票股利:增加、不變、減少、不變;股票分割:不變、減少、不變、不變", "股票股利:不變、減少、不變、不變;股票分割:增加、不變、減少、不變", "股票股利:增加、不變、減少、不變;股票分割:不變、不變、減少、不變", "股票股利:增加、減少、不變、不變;股票分割:不變、減少、不變、不變"], "answer": "A", "figure": null, "official": "股票股利:股本增加、面額不變、保留盈餘減少、權益總額不變;股票分割:股本不變、面額減少、保留盈餘不變、權益總額不變。", "explain": {"concept": "股票股利是把保留盈餘轉成股本;股票分割只是把一股拆成多股,面額變小,股數增加,權益內容不變。", "steps": ["股票股利:借保留盈餘、貸股本。股本增加、保留盈餘減少、面額不變、權益總額不變。", "股票分割:股數增加、每股面額按比例縮小(如1股拆2股面額減半)。股本總額不變、保留盈餘不變、權益總額不變。", "對照選項,第一組(股票股利)「增加、不變、減少、不變」與第二組(股票分割)「不變、減少、不變、不變」完全符合,選(A)。"], "pitfalls": "把兩者的面額與保留盈餘影響弄反。", "distractors": {"B": "股票股利與分割的敘述互相顛倒。", "C": "股票分割時每股面額會減少,保留盈餘不會減少。", "D": "股票股利不會讓每股面額減少。"}}, "check": "概念題,依兩者分錄及面額變化確認。", "verified": true, "note": ""}, {"id": "111-4-A-23", "exam": "111-4", "paper": "A", "q": 23, "unit": "十七、權益", "topic": "累積特別股股利", "stem": "花蓮公司於X8年成立,發行有普通股:面額$10,流通在外股數500,000股及5%累積非參加特別股:面額$10,流通在外股數120,000股;花蓮公司X8年的盈餘不佳,並未宣告及發放股利,X9年的盈餘分配中宣告分派股利$250,000,請問:X9年的盈餘應分配多少股利給普通股股東?", "options": ["$250,000", "$190,000", "$130,000", "$120,000"], "answer": "C", "figure": null, "official": "X9年特別股股利=積欠$60,000+當年$60,000=$120,000;普通股股利=$250,000-$120,000=$130,000。", "explain": {"concept": "累積特別股:以前年度未發的股利要累積補發,而且要先發完特別股股利,剩餘才給普通股。非參加特別股只領固定股利,不分享剩餘。", "steps": ["特別股每年股利=120,000股×$10×5%=$60,000。", "X8年未發,積欠$60,000;X9年當年度股利$60,000。", "特別股X9可領=$60,000+$60,000=$120,000。", "可分配普通股=總股利$250,000-$120,000=$130,000。非參加特別股不再參與剩餘分配,所以答案是$130,000(C)。"], "pitfalls": "漏掉積欠的特別股股利,只扣掉當年$60,000得到$190,000。", "distractors": {"A": "$250,000是全部股利,忘了先給特別股。", "B": "$250,000-$60,000=$190,000,只扣當年特別股股利,漏掉積欠的一年。", "D": "$120,000是特別股應得的股利,不是普通股的金額。"}}, "check": "python:120000*10*.05*2=120000;250000-120000=130000,相符。", "verified": true, "note": ""}, {"id": "111-4-A-24", "exam": "111-4", "paper": "A", "q": 24, "unit": "十七、權益", "topic": "每股盈餘與本益比", "stem": "屏東公司X8年期初有流通在外普通股股數為35,000股,10月1日現金增資發行20,000股普通股。屏東公司X8年度稅後淨利為$64,000,並於X8年12月31日宣告發放普通股股利$20,000,特別股股利$12,000。若屏東公司X8年年底股票之每股市價為$26,則請問X8年年底之本益比為何?", "options": ["16.25", "20", "23.64", "32.5"], "answer": "B", "figure": null, "official": "加權平均流通在外股數=40,000股;EPS=($64,000-$12,000)/40,000=$1.3;本益比=$26/$1.3=20。", "explain": {"concept": "本益比=每股市價÷每股盈餘。每股盈餘=(稅後淨利-特別股股利)÷加權平均流通在外普通股股數。", "steps": ["先求加權平均股數:1/1~9/30有35,000股×9/12=26,250;10/1~12/31有35,000+20,000=55,000股×3/12=13,750。合計=26,250+13,750=40,000股。", "EPS分子=稅後淨利-特別股股利=$64,000-$12,000=$52,000(普通股股利$20,000不能扣)。", "EPS=$52,000÷40,000股=$1.3。", "本益比=市價$26÷EPS $1.3=20倍,選(B)。"], "pitfalls": "把普通股股利也扣掉,或用期末股數55,000股計算。", "distractors": {}}, "check": "python:(35000*9/12+55000*3/12)=40000;(64000-12000)/40000=1.3;26/1.3=20,相符。", "verified": true, "note": ""}, {"id": "111-5-A-01", "exam": "111-5", "paper": "A", "q": 1, "unit": "十五、長期營業用資產", "topic": "生物資產與政府補助", "stem": "小光所經營的花神農場種植各種花卉,致力於提昇花卉品質與產業競爭力,得到臺灣農業界奧斯卡之稱的「神農獎」。小光為國爭光,運用科技調整花卉產季,拿下日本、歐洲、杜拜等國際市場。本月該農場除了購買花苗(公允價值能可靠衡量),也購置綠能包材設備,栽種技術獲得專利權,並受到政府補助一批設備。該農場下列各項資產的入帳金額哪幾項正確?\n①購買的花苗,以公允價值減出售成本入帳\n②購置綠能包材設備,以成本入帳\n③栽種技術獲得的專利權,以符合無形資產認列條件之日起至登記完成之成本入帳\n④政府補助的設備,以公允價值入帳\n⑤收成時的花卉,以成本與淨變現價值孰低法入帳", "options": ["①④", "②③⑤", "①②③④", "①②③④⑤"], "answer": "C", "figure": null, "official": "⑤收成時的花卉(農產品)以公允價值減出售成本入帳;期末衡量時才以成本與淨變現價值孰低法衡量,故⑤錯,①②③④正確。", "explain": {"concept": "考生物資產、不動產廠房設備、無形資產與政府補助的「入帳基礎」,要分清各項資產用成本還是公允價值。", "steps": ["先逐項判斷。①花苗是生物資產且公允價值可靠衡量,入帳用「公允價值減出售成本」,正確。", "②購入的設備(不動產、廠房及設備)一律以取得成本入帳,正確。", "③專利權是無形資產,從符合認列條件之日起,到登記完成所發生的成本入帳,正確。", "④政府補助的設備(非貨幣性補助)可以公允價值入帳,題目採此作法,正確。", "⑤農產品「收成時」是用「公允價值減出售成本」入帳(轉成存貨的成本),之後期末才用成本與淨變現價值孰低衡量,所以⑤錯誤。", "①②③④正確、⑤錯誤,答案選 (C)。"], "pitfalls": "最容易把⑤「期末的孰低法」誤當成「收成時的入帳基礎」,兩個時點用的方法不同。", "distractors": {"A": "只選①④,漏掉②③也正確。", "B": "把⑤當成正確,又漏掉①④。", "D": "全選,忽略⑤收成時應以公允價值減出售成本入帳。"}}, "check": "概念題,依官方詳解與 IAS 41、IAS 20 常識確認:①②③④正確、⑤錯誤。", "verified": true, "note": ""}, {"id": "111-5-A-02", "exam": "111-5", "paper": "A", "q": 2, "unit": "十七、權益", "topic": "本益比與每股盈餘", "stem": "投資人小明買了A、B兩家公開發行公司的股票,兩家股票每股面額都是$10,X3年底兩家公司股票的每股收盤價:A公司$90、B公司$48,兩家公司X3年度股數都沒有變動,A公司X3年度賺了一個股本,B公司X3年度每股盈餘$8。下列敘述何者正確?", "options": ["A公司股票X3年底本益比為9", "B公司股票X3年底本益比為8", "A公司的X3年度稅後淨利一定大於B公司X3年度稅後淨利", "目前我國所有公開發行公司的股票每股面額都是新臺幣10元"], "answer": "A", "figure": null, "official": "A公司賺一個股本→每股盈餘=面額$10,本益比=$90÷$10=9;B公司本益比=$48÷$8=6。", "explain": {"concept": "本益比=每股市價÷每股盈餘;「賺一個股本」=每股盈餘等於每股面額。", "steps": ["本益比公式:本益比=每股收盤價÷每股盈餘。", "A公司賺了一個股本,表示淨利=股本,所以每股盈餘=每股面額=$10。", "A公司本益比=$90÷$10=9,所以(A)正確。", "B公司本益比=$48÷$8=6,不是8,所以(B)錯。", "兩家公司股數不知道,無法比較稅後淨利大小,(C)錯。", "我國有些公開發行公司股票面額不是$10(例如面額$1的股票),(D)錯。"], "pitfalls": "容易把本益比算成「每股盈餘÷股價」或誤把每股盈餘當成8或9以外的數字;也容易忽略股數不同無法比較淨利。", "distractors": {"B": "用$48÷$6之類算錯,或把每股盈餘$8直接當本益比;正確為$48÷$8=6。", "C": "以為每股盈餘高或股價高淨利就大,但股數未知,無法判斷。", "D": "以為所有公司面額都是$10,但並非全部。"}}, "check": "A:90/10=9;B:48/8=6。與官方相符。", "verified": true, "note": ""}, {"id": "111-5-A-03", "exam": "111-5", "paper": "A", "q": 3, "unit": "一、會計基本概念", "topic": "商業會計法與會計處理", "stem": "小美為某一公開發行公司的會計人員,多年的會計工作經驗,深知會計事務的處理,在從事會計事項的辨認、衡量、記載、分類、彙總及據以編製財務報表。下列小美的會計處理,何者錯誤?", "options": ["會計基礎採用權責發生制,會計事項之記錄應採用雙式簿記", "採複式傳票三分法,除了現金收入、現金支出交易,其他交易都編製轉帳傳票", "財務報表應每季公告,年度財務報表之格式採二年度對照方式編製", "支出達100萬元以上時,須經主管核准後才能整筆支出以新臺幣(現金)支付"], "answer": "D", "figure": null, "official": "支出達100萬元以上時,應使用匯票、本票、支票、匯款、劃撥、電匯、轉帳等支付工具或方法,並載明受款人;不是核准後以現金整筆支付。", "explain": {"concept": "考商業會計法的基本規定,特別是大額支付的方式。", "steps": ["(A) 商業會計採權責發生制,記錄用雙式簿記(有借必有貸),正確。", "(B) 三單式傳票(現金收入、現金支出、轉帳傳票),非現金交易編製轉帳傳票,正確。", "(C) 公開發行公司財務報表每季公告,年度報表採兩年度對照,正確。", "(D) 依規定,支出達100萬元以上,必須用匯票、本票、支票、匯款、劃撥、電匯、轉帳等方式並載明受款人,不可整筆用現金,因此(D)錯誤。", "本題問「錯誤」,答案選 (D)。"], "pitfalls": "題目問錯誤選項,容易看到(D)有「主管核准」就以為合理。重點是大額支付不能用現金。", "distractors": {"A": "此為正確敘述,別當成錯誤。", "B": "此為正確敘述。", "C": "此為正確敘述。"}}, "check": "概念/法規題,與官方詳解及商業會計法常識相符。", "verified": true, "note": ""}, {"id": "111-5-A-04", "exam": "111-5", "paper": "A", "q": 4, "unit": "一、會計基本概念", "topic": "會計事務處理", "stem": "有關會計事務處理之敘述,下列何者錯誤?", "options": ["帳冊記載應遵照商業會計法及一般公認會計原則的規範", "獨資及合夥組織應將「本期所得稅費用」的餘額轉入「本期損益」帳戶的借方", "我國非公開發行公司的會計事務,適用會計研究發展基金會所發布的企業會計準則公報", "企業得委託外部人員代為記帳,合法業者有以下3類:會計師、記帳士、記帳及報稅代理業務人"], "answer": "B", "figure": null, "official": "獨資及合夥組織無須計算及繳納營利事業所得稅,故會計事務處理中無「本期所得稅費用」項目。", "explain": {"concept": "考不同組織型態是否負擔營利事業所得稅。", "steps": ["(A) 帳冊記載依商業會計法及一般公認會計原則,正確。", "(B) 獨資、合夥本身不繳營利事業所得稅(由業主或合夥人併入綜合所得稅),所以根本沒有「本期所得稅費用」帳戶可轉入,(B)錯誤。", "(C) 非公開發行公司適用企業會計準則公報,正確。", "(D) 委託外部人員記帳,合法業者有會計師、記帳士、記帳及報稅代理業務人三類,正確。"], "pitfalls": "以為所有企業都有所得稅費用;其實只有公司組織才繳營利事業所得稅。", "distractors": {"A": "正確敘述。", "C": "正確敘述。", "D": "正確敘述。"}}, "check": "概念題,與官方詳解相符。", "verified": true, "note": ""}, {"id": "111-5-A-05", "exam": "111-5", "paper": "A", "q": 5, "unit": "二、會計循環及會計帳簿", "topic": "會計事項與憑證", "stem": "有關會計事項及會計憑證之敘述,下列何者正確?", "options": ["災害損失、業主提取商品自用,兩者都屬於內部交易", "資產、負債、權益、收益及費損發生增減變化之事項,稱為借貸法則", "證明會計事項之經過,作為造具記帳憑證所根據之憑證,稱為記帳憑證", "會計憑證應按日或按月裝訂成冊,有原始憑證者,應附於記帳憑證之後"], "answer": "D", "figure": null, "official": "(A)災害損失屬內部交易,業主提取商品自用屬對外交易;(B)應稱會計事項;(C)應稱原始憑證。", "explain": {"concept": "分辨內外部交易、會計事項、原始憑證與記帳憑證。", "steps": ["(A) 災害損失是內部交易沒錯,但業主提取商品自用(企業與業主間往來)屬對外交易,所以錯。", "(B) 使資產、負債、權益、收益、費損增減的事項叫「會計事項」,不是借貸法則。", "(C) 證明會計事項經過、作為造具記帳憑證依據的叫「原始憑證」;記帳憑證是會計人員據以記帳的傳票。", "(D) 會計憑證按日或按月裝訂成冊,有原始憑證者附於記帳憑證之後,正確。"], "pitfalls": "原始憑證與記帳憑證名稱容易互換;「業主提取」是對外交易也常被忽略。", "distractors": {"A": "以為業主提取自用商品屬內部交易。", "B": "把「會計事項」誤稱為「借貸法則」。", "C": "把原始憑證說成記帳憑證。"}}, "check": "概念題,與官方詳解相符。", "verified": true, "note": ""}, {"id": "111-5-A-06", "exam": "111-5", "paper": "A", "q": 6, "unit": "八、結帳", "topic": "結帳處理", "stem": "有關結帳之敘述,下列何者正確?", "options": ["銷貨成本帳戶採本期損益法的結帳分錄,借記銷貨成本、貸記本期損益", "若本期收益金額大於費損金額,則稅前的本期損益帳戶為借方餘額", "虛帳戶的結帳,須編製傳票記入日記簿,或是直接在分類帳作差額結轉", "「現金短溢」、「職工福利」、「處分無形資產利益」等帳戶結帳後餘額為零"], "answer": "D", "figure": null, "official": "(A)應借記本期損益、貸記銷貨成本;(B)應為貸方餘額;(C)虛帳戶結帳必須在日記簿作結帳分錄。", "explain": {"concept": "結帳時虛帳戶(損益類)餘額都要結清為零。", "steps": ["(A) 銷貨成本是費損,結帳要「貸」銷貨成本、「借」本期損益,選項寫反了。", "(B) 收益大於費損=賺錢,本期損益為貸方餘額,不是借方。", "(C) 虛帳戶結帳必須在日記簿編製結帳分錄,不能直接在分類帳結轉。", "(D) 現金短溢、職工福利、處分無形資產利益都是損益類(虛帳戶),結帳後餘額為零,正確。"], "pitfalls": "借貸方向容易寫反;結帳分錄也一定要先入日記簿。", "distractors": {"A": "把費用結帳分錄借貸寫反。", "B": "賺錢時本期損益是貸方餘額,不是借方。", "C": "以為虛帳戶可不記日記簿直接在分類帳結轉。"}}, "check": "概念題,與官方詳解相符。", "verified": true, "note": ""}, {"id": "111-5-A-07", "exam": "111-5", "paper": "A", "q": 7, "unit": "九、財務報表", "topic": "綜合損益表營業利益", "stem": "綜合損益表上,下列項目何者不影響營業利益(損失)?", "options": ["銷貨成本", "預期信用減損損失(利益)", "透過損益按公允價值衡量之金融資產損失", "研究發展費用"], "answer": "C", "figure": null, "official": "透過損益按公允價值衡量之金融資產損失為營業外支出,不影響營業利益(損失)。", "explain": {"concept": "分辨營業項目與營業外項目。", "steps": ["營業利益=營業收入-營業成本-營業費用。", "(A) 銷貨成本屬營業成本,影響營業利益。", "(B) 預期信用減損損失(利益)列為營業費用,影響營業利益。", "(C) 透過損益按公允價值衡量之金融資產損失屬營業外支出,不影響營業利益,選 (C)。", "(D) 研究發展費用是營業費用,影響營業利益。"], "pitfalls": "容易把金融資產評價損益誤認為營業項目。", "distractors": {"A": "銷貨成本一定影響營業利益。", "B": "預期信用減損損失列在營業費用內。", "D": "研發費用是營業費用。"}}, "check": "概念題,與官方詳解相符。", "verified": true, "note": ""}, {"id": "111-5-A-08", "exam": "111-5", "paper": "A", "q": 8, "unit": "五、過帳與分類帳", "topic": "統制帳戶與明細分類帳", "stem": "有關分類帳,下列敘述何者錯誤?", "options": ["若「應付票據」帳戶餘額$100,000、「應付票據折價」帳戶餘額$2,000,則應付票據帳面金額為$102,000", "若「應付帳款」統制帳戶餘額為$100,000、其明細分類帳中有一供應商為借方餘額$2,000,則在資產負債表的流動負債項下應付帳款列示金額為$102,000", "總分類帳能表達第四級會計項目個別帳戶的變動情形與結果", "分類帳可以做為編製報表的依據"], "answer": "A", "figure": null, "official": "應付票據帳面金額=$100,000-$2,000=$98,000,不是$102,000。", "explain": {"concept": "應付票據折價是應付票據的減項(抵銷帳戶)。", "steps": ["應付票據帳面金額=應付票據-應付票據折價=$100,000-$2,000=$98,000,所以(A)寫$102,000錯誤。", "(B) 統制帳戶$100,000含一個借方餘額$2,000的供應商,代表其他供應商貸方合計$102,000,借方餘額$2,000要列為資產(預付款),流動負債列$102,000,正確。", "(C) 總分類帳有統制帳戶角色,表達第四級會計項目;(D) 分類帳是編製報表的依據,皆正確。"], "pitfalls": "把折價誤當成加項(加$2,000),忘記折價是減項。", "distractors": {"B": "屬正確敘述,借方餘額應另列資產,負債要還原成$102,000。", "C": "屬正確敘述(依官方)。", "D": "屬正確敘述。"}}, "check": "算式:$100,000-$2,000=$98,000,與官方答案(A)為錯誤敘述相符。", "verified": true, "note": ""}, {"id": "111-5-A-09", "exam": "111-5", "paper": "A", "q": 9, "unit": "七、調整", "topic": "勞務收入預收調整", "stem": "精良公司X3年10月1日與客戶簽約,合約金額共計$400,000,約定提供一年期的維修服務,簽約時收取全部款項,採權責發生基礎記帳。公司於X3年12月31日已完成維修服務之40%,下列有關X3年12月31日之敘述何者正確?", "options": ["未收現金,不必作調整分錄", "應作調整分錄,增加收益$160,000", "應作調整分錄,增加收益$240,000", "應作調整分錄,增加負債$160,000"], "answer": "B", "figure": null, "official": "預收維修收入$160,000,已完成40%轉為收益:借:預收維修收入160,000,貸:維修收入160,000。", "explain": {"concept": "預收收益調整:賺得的部分從負債轉成收益。", "steps": ["簽約時已收現金$400,000,應記預收維修收入(負債)$400,000。", "年底已完成服務的40%,已賺得收益=$400,000×40%=$160,000。", "調整分錄:借:預收維修收入 160,000,貸:維修收入 160,000。", "結果:收益增加$160,000、負債減少$160,000,選 (B)。", "注意題目給的是完成程度40%,不是用月數(3/12)算。"], "pitfalls": "用時間(3/12=25%)算成$100,000,或把增加收益金額算成未完成的60%($240,000)。", "distractors": {"A": "已收現金仍需依完工程度認列收益。", "C": "算成未完成的60%=$240,000。", "D": "負債是減少而不是增加。"}}, "check": "400,000×40%=160,000,與官方相符。", "verified": true, "note": ""}, {"id": "111-5-A-10", "exam": "111-5", "paper": "A", "q": 10, "unit": "十二、應收款項", "topic": "備抵損失與沖銷帳款收回", "stem": "應收帳款期末衡量採備抵法提列備抵損失,去年已沖銷之帳款今日又收回,此交易分錄對下列項目之影響,何者錯誤?", "options": ["不影響本期損益金額", "流動資產總額不變", "應收帳款帳面金額不變", "營運資金總額不變"], "answer": "C", "figure": null, "official": "收回已沖銷帳款分錄:①借:應收帳款,貸:備抵損失;②借:現金,貸:應收帳款。應收帳款帳面金額(應收帳款-備抵損失)減少、現金增加。", "explain": {"concept": "已沖銷帳款收回要先「回復」再「收款」。", "steps": ["先回復:借:應收帳款 ×××,貸:備抵損失-應收帳款 ×××(兩者同時增加,帳面金額不變)。", "再收現:借:現金 ×××,貸:應收帳款 ×××。", "(A) 全程無損益項目,不影響本期損益。", "(B)(D) 現金增加、應收帳款帳面金額減少,流動資產總額不變,營運資金也不變。", "(C) 應收帳款帳面金額(=應收帳款-備抵損失)因為現金收回而減少,所以說「不變」是錯誤的,選 (C)。"], "pitfalls": "以為回復分錄與收款分錄沒有影響應收帳款帳面金額。", "distractors": {"A": "整個交易沒有損益項目,敘述正確。", "B": "現金增加、應收減少,流動資產合計不變,正確。", "D": "流動資產不變、流動負債不變,營運資金不變,正確。"}}, "check": "概念題,與官方詳解相符。", "verified": true, "note": ""}, {"id": "111-5-A-11", "exam": "111-5", "paper": "A", "q": 11, "unit": "十三、存貨", "topic": "存貨會計處理", "stem": "有關存貨之會計處理,下列敘述何者正確?", "options": ["存貨採永續盤存制,調整前帳列存貨為期初存貨", "分期付款銷貨後,因客戶違約所收回的商品預計再出售,列為賣方的存貨", "可替換的大量存貨,依照國際會計準則,可採用個別認定法、先進先出法或平均法", "期末衡量前,「存貨」成本$100,000、「備抵存貨跌價」貸餘$2,000,若期末衡量分錄導致「銷貨成本」增加$1,000,則衡量後存貨帳面金額為$99,000"], "answer": "B", "figure": null, "official": "(A)永續盤存制調整前帳列存貨為期末存貨;(C)可替換大量存貨不得採個別認定法;(D)衡量後為$97,000。", "explain": {"concept": "存貨制度、成本流動假設與備抵存貨跌價。", "steps": ["(A) 永續盤存制隨時記錄,調整前帳上存貨即期末存貨(定期盤存制才是期初存貨),錯。", "(B) 分期付款客戶違約收回商品,預計再出售,賣方列為存貨,正確。", "(C) 可替換的大量存貨不可用個別認定法,只能用先進先出或平均法,錯。", "(D) 衡量分錄使銷貨成本增加$1,000→借:銷貨成本1,000,貸:備抵存貨跌價1,000;備抵變為$3,000,存貨帳面金額=$100,000-$3,000=$97,000,不是$99,000,錯。", "答案選 (B)。"], "pitfalls": "(D)容易只看一個備抵而忘記要再加上新增的跌價$1,000。", "distractors": {"A": "把永續盤存制的帳列存貨誤認為期初存貨。", "C": "沒有注意大量可替換存貨不可用個別認定法。", "D": "算成$100,000-$2,000+$1,000=$99,000,把增加的跌價誤當成備抵減少;其實備抵增加,存貨帳面金額要再減$1,000,成為$97,000。"}}, "check": "(D) 算:100,000-(2,000+1,000)=97,000,與官方相符(D不正確)。", "verified": true, "note": ""}, {"id": "111-5-A-12", "exam": "111-5", "paper": "A", "q": 12, "unit": "十五、長期營業用資產", "topic": "折舊與攤提", "stem": "綠野茶園為公開發行公司,該公司下列哪幾項期末應提列折舊或各項攤提?\n①因企業合併所取得的商譽\n②內部產生的客戶名單\n③由非確定耐用年限變更為有限耐用年限時的商標權\n④政府無條件補助的房屋\n⑤生產性茶樹", "options": ["①③", "③⑤", "②④⑤", "③④⑤"], "answer": "D", "figure": null, "official": "①商譽不得攤提;②內部產生的客戶名單不得列為無形資產,也就不得攤提;③應列計各項攤提;④⑤應列計折舊。", "explain": {"concept": "哪些資產要折舊或攤提。", "steps": ["①商譽:耐用年限非確定,不攤銷(每年減損測試),不選。", "②內部產生的客戶名單:不可認列為無形資產,沒有攤提問題,不選。", "③商標權由非確定改為有限耐用年限→開始攤提,選。", "④政府無條件補助的房屋:是不動產,廠房及設備要折舊,選。", "⑤生產性茶樹(生產性植物)依不動產廠房設備處理,要折舊,選。", "所以③④⑤,答案 (D)。"], "pitfalls": "以為商譽也要攤提(我國準則已不攤銷);或把內部產生的客戶名單當作資產。", "distractors": {"A": "①商譽不攤提,且漏掉④⑤。", "B": "漏了④房屋也要折舊。", "C": "②內部產生客戶名單不是資產。"}}, "check": "概念題,與官方詳解相符。", "verified": true, "note": ""}, {"id": "111-5-A-13", "exam": "111-5", "paper": "A", "q": 13, "unit": "十六、負債", "topic": "票據與債券入帳", "stem": "有關債券及票據之敘述,下列何者錯誤?", "options": ["發行5年期公司債,附有票面利率,公司債的發行價格=公司債面額×有效利率的複利現值", "購買商品簽發3個月期本票,不附息,應付票據的入帳金額=票據面額", "購入營業用機器簽發半年期本票,票面利率3%,有效利率3%,應付票據的入帳金額=票據面額", "向銀行借款得到現金,簽發2年期本票,不附息,應付票據的入帳金額=票據面額×有效利率的複利現值"], "answer": "A", "figure": null, "official": "有票面利率時,公司債發行價格=面額×有效利率的複利現值+每期票面利息×有效利率的年金現值。", "explain": {"concept": "公司債發行價格=本金現值+利息年金現值。", "steps": ["公司債價格是把「未來所有現金流量」折現:到期本金(一次給付,用複利現值)加每期利息(每期固定,用年金現值)。", "(A) 只算了本金的複利現值,漏了利息的年金現值,錯誤。", "(B) 3個月期短期不附息票據,折現影響不大,入帳金額為面額,正確。", "(C) 票面利率=有效利率→折溢價為零,入帳金額=票據面額,正確。", "(D) 2年期不附息票據,利息隱含在面額中,入帳金額=面額×複利現值,正確。"], "pitfalls": "忘記有票面利率時還要加利息的年金現值。", "distractors": {"B": "短期不附息,折現不重要,以面額入帳(正確敘述)。", "C": "票面利率等於有效利率,現值=面額(正確敘述)。", "D": "長期不附息票據應折現(正確敘述)。"}}, "check": "概念題,與官方詳解相符。", "verified": true, "note": ""}, {"id": "111-5-A-14", "exam": "111-5", "paper": "A", "q": 14, "unit": "十五、長期營業用資產", "topic": "支付項目是否資本化", "stem": "下列支付項目,哪幾項入帳時借記資產?\n①購入營業用機器所支付的安裝費\n②購入消耗性生物資產所支付的運費,交貨條件為起運點交貨,該生物資產公允價值能可靠衡量\n③購入無重大影響力且持有供交易的上櫃公司股票,所支付的交易成本\n④銷售商品支付的運費,交貨條件為目的地交貨\n⑤永續盤存制下,購買商品的運費,交貨條件為起運點交貨", "options": ["①②", "①④", "①⑤", "②③⑤"], "answer": "C", "figure": null, "official": "①安裝費列為資產成本;⑤運費列為存貨成本;②運費不是生物資產入帳成本;③交易成本列為營業外支出;④運費列為營業費用。", "explain": {"concept": "哪些支出要「資本化」(借記資產),哪些是費用。", "steps": ["①機器安裝費是使機器達可使用狀態的必要支出,計入機器成本,借記資產。", "②消耗性生物資產以「公允價值減出售成本」入帳,運費是出售成本的一部分,不是入帳成本,不借資產(列費用/不計入)。", "③持有供交易的股票(透過損益按公允價值衡量),交易成本直接列為營業外支出。", "④目的地交貨,運費由賣方負擔,列為營業費用(運費)。", "⑤起運點交貨,買方負擔運費,存貨成本增加,借記存貨(資產)。", "所以①⑤,選 (C)。"], "pitfalls": "②③容易以為都是取得成本要加進資產,其實依據衡量方式不同(公允價值減出售成本/透過損益)。", "distractors": {"A": "把②運費當成資產入帳成本。", "B": "④賣方運費是營業費用,不是資產。", "D": "②③不借資產。"}}, "check": "概念題,與官方詳解相符。", "verified": true, "note": ""}, {"id": "111-5-A-15", "exam": "111-5", "paper": "A", "q": 15, "unit": "九、財務報表", "topic": "流動資產、流動負債與速動資產", "stem": "必達公司年底資產負債資料如下:\n銀行存款$100,000、應收票據$200,000、備抵損失-應收票據$2,000、應收票據折價$1,000、應付股利$10,000、本期所得稅負債$10,000、用品盤存$2,000、存貨$50,000、預付保險費$2,600、其他應收款$400、償債基金$30,000、機器設備成本$200,000、累計折舊$100,000、銀行借款$40,000、應付帳款$100,000、存入保證金$40,000。根據上述資料,下列各項金額或比率,何者正確?", "options": ["流動資產$382,000", "流動負債$150,000", "流動比率176%", "速動資產$297,400"], "answer": "D", "figure": null, "official": "流動資產=$352,000;流動負債=$160,000;流動比率=220%;速動資產=$352,000-$50,000-$2,600-$2,000=$297,400。", "explain": {"concept": "分辨流動資產、速動資產與流動負債。", "steps": ["流動資產=銀行存款+應收票據淨額+用品盤存+存貨+預付費用+其他應收款=100,000+(200,000-2,000-1,000)+2,000+50,000+2,600+400=$352,000(償債基金、機器設備不是流動資產)。", "流動負債=應付股利10,000+本期所得稅負債10,000+銀行借款40,000+應付帳款100,000=$160,000(存入保證金視為非流動負債)。", "流動比率=352,000÷160,000=220%。", "速動資產=流動資產-存貨-預付費用-用品盤存=352,000-50,000-2,600-2,000=$297,400。", "所以(D)正確。"], "pitfalls": "忘記備抵損失與折價是應收票據的減項;速動資產要扣除存貨、預付費用與用品盤存。", "distractors": {"A": "把償債基金$30,000加進流動資產(352,000+30,000=382,000)。"}}, "check": "python 驗算:流動資產352,000、流動負債160,000、比率220%、速動資產297,400,與官方相符。", "verified": true, "note": ""}, {"id": "111-5-A-16", "exam": "111-5", "paper": "A", "q": 16, "unit": "六、試算與試算表", "topic": "錯誤更正與試算表", "stem": "欣欣商店X1年初向外承租店面,租期5年,每月租金$10,000,X1年初支付保證金$20,000、租金$10,000,分錄誤記為借:租金支出$30,000,貸:現金$30,000,並已經完成過帳,X1年1月底編製餘額式試算表。則下列敘述何者正確?", "options": ["此錯誤發現時應作註銷更正", "期末流動資產低估$20,000", "餘額式試算表不平衡,借貸方合計金額相差$20,000", "餘額式試算表仍平衡,且借貸方合計金額均正確"], "answer": "D", "figure": null, "official": "正確分錄:借:存出保證金$20,000、租金支出$10,000,貸:現金$30,000。存出保證金與租金支出都是借方餘額帳戶,試算表仍平衡,借貸方合計金額均正確。", "explain": {"concept": "錯誤只在借方科目選錯,不影響試算表平衡。", "steps": ["正確應為:借:存出保證金20,000、租金支出10,000,貸:現金30,000。", "錯誤分錄把保證金$20,000也記入租金支出,借方總額仍是$30,000,貸方也是$30,000。", "因為「存出保證金」與「租金支出」都是借方餘額,試算表借貸合計仍相等且金額正確,選 (D)。", "(A) 此錯誤應作「更正分錄」(借存出保證金20,000、貸租金支出20,000),不是註銷更正。", "(B) 存出保證金屬非流動資產,低估的是非流動資產$20,000,不是流動資產。", "(C) 試算表平衡,沒有差額。"], "pitfalls": "以為所有錯誤都會造成試算表不平衡;其實借借(或貸貸)互相錯置不會影響平衡。", "distractors": {"B": "保證金為非流動資產,不是流動資產。", "C": "錯在同方向科目,試算表仍平衡。", "A": "此錯誤是科目選錯,應以更正分錄(借存出保證金、貸租金支出)處理,不是註銷更正。"}}, "check": "概念題,與官方詳解相符(答案表為D)。", "verified": true, "note": ""}, {"id": "111-5-A-17", "exam": "111-5", "paper": "A", "q": 17, "unit": "六、試算與試算表", "topic": "前期錯誤對保留盈餘之更正", "stem": "美美公司於X1年初成立,存貨採實地盤存制,X3年底發現X1年至X3年有下列錯誤:\n\n| 項目 | X1年度 | X2年度 | X3年度 |\n|---|---|---|---|\n| 預收租金 | - | 高估$3,000 | 低估$2,000 |\n| 期末存貨 | 低估$12,000 | 高估$8,000 | 高估$3,000 |\n| 折舊 | 高估$1,200 | 高估$1,200 | 高估$1,200 |\n\n若X3年底更正前保留盈餘為$400,000,在不考慮所得稅因素下,則正確的保留盈餘為何?", "options": ["$398,600", "$401,400", "$403,600", "$406,200"], "answer": "A", "figure": null, "official": "預收租金X3低估→保留盈餘高估$2,000;期末存貨X3高估→保留盈餘高估$3,000;折舊每年高估$1,200,三年共$3,600→保留盈餘低估$3,600。正確=$400,000-$2,000-$3,000+$3,600=$398,600。", "explain": {"concept": "累積效果:有「兩年自動抵銷」的錯誤只剩最後一年(X3)的影響,折舊錯誤則逐年累積。", "steps": ["期末存貨錯誤、預收租金錯誤會在次年自動抵銷,所以X1、X2年的錯誤對X3年底保留盈餘已無影響,只看X3年。", "預收租金X3低估$2,000:負債低估=收益多認列,保留盈餘高估$2,000,要減$2,000。", "期末存貨X3高估$3,000:銷貨成本低估,淨利高估,保留盈餘高估$3,000,要減$3,000。", "折舊不會自動抵銷,每年高估$1,200費用,3年共$3,600→保留盈餘低估$3,600,要加$3,600。", "正確保留盈餘=$400,000-$2,000-$3,000+$3,600=$398,600,選 (A)。"], "pitfalls": "誤把X1、X2的錯誤也算進去;或忘記折舊錯誤是會累積的。", "distractors": {}}, "check": "python 驗算:400,000-2,000-3,000+1,200×3=398,600,與官方相符。", "verified": true, "note": ""}, {"id": "111-5-A-18", "exam": "111-5", "paper": "A", "q": 18, "unit": "十、加值型營業稅會計實務", "topic": "應退稅額計算", "stem": "王牌公司X3年3~4月份之銷項、進項資料如下(金額皆未含營業稅5%):\n(1) 銷項:經海關出口外銷$200,000,國內銷貨$550,000、預收訂金$50,000\n(2) 進項:進貨$600,000,購入機器設備$200,000,向小規模營業人購入文具$400,支付交際費$1,600,支付承租給集中管理的國際移工宿舍租金$20,000\n(3) 上期累積留抵稅額$1,000\n則王牌公司本期應收退稅款為何?", "options": ["$0", "$11,000", "$12,000", "$20,000"], "answer": "C", "figure": null, "official": "銷項稅額=($550,000+$50,000)×5%=$30,000;進項稅額=($600,000+$200,000+$20,000)×5%=$41,000;申報留抵稅額=($1,000+$41,000)-$30,000=$12,000;得退稅限額=($200,000+$200,000)×5%=$20,000;取較小者$12,000。", "explain": {"concept": "營業稅退稅:留抵稅額與「得退稅限額」取小。", "steps": ["銷項稅額:外銷零稅率,國內銷貨$550,000與預收訂金$50,000要課稅,(550,000+50,000)×5%=$30,000。", "進項稅額:進貨、機器設備、國際移工宿舍租金可扣抵;小規模營業人文具、交際費不得扣抵。(600,000+200,000+20,000)×5%=$41,000。", "申報留抵稅額=上期留抵1,000+進項41,000-銷項30,000=$12,000。", "得退稅限額=(零稅率銷售額200,000+購買固定資產200,000)×5%=$20,000。", "實際退稅額取兩者較小者:min(12,000,20,000)=$12,000,選 (C)。"], "pitfalls": "漏加上期累積留抵、或把交際費、小規模營業人文具誤列為進項;忘記退稅限額要和留抵稅額取小。", "distractors": {"B": "例如沒把宿舍租金進項$1,000扣抵(用$40,000算成11,000)。", "D": "直接用得退稅限額$20,000,忘記要和留抵稅額比較。"}}, "check": "python 驗算:銷項30,000、進項41,000、留抵12,000、退稅限額20,000→退12,000,與官方相符。", "verified": true, "note": ""}, {"id": "111-5-A-19", "exam": "111-5", "paper": "A", "q": 19, "unit": "十二、應收款項", "topic": "應收票據貼現", "stem": "麗麗公司於X1年6月1日銷貨收到客戶簽發的3個月期,年利率10%的附息票據,X1年7月1日公司將該票據持往銀行貼現,貼現率12%,取得貼現金額$241,080。試計算X1年7月1日應收票據貼現交易導致下列項目的變動為何?", "options": ["流動資產增加$1,080", "流動負債增加$239,080", "應收票據帳戶減少$241,080", "收益增加$2,009"], "answer": "B", "figure": null, "official": "票據面額$240,000,到期值$246,000,貼現息$4,920,現金$241,080;應收票據貼現負債$240,000減折價$920,流動負債增加$239,080。", "explain": {"concept": "附息票據貼現:先算到期值,再算貼現息,附追索權時列「應收票據貼現負債」。", "steps": ["設面額為X:到期值=X×(1+10%×3/12)。貼現息=到期值×12%×2/12(持有1個月後貼現,剩2個月)。", "現金=到期值-貼現息→$241,080=到期值×(1-0.02)=到期值×0.98,所以到期值=$246,000。", "面額=$246,000÷1.025=$240,000。", "分錄:借:現金241,080、應收票據貼現負債折價920,貸:應收票據貼現負債240,000、利息收入2,000(1個月利息=240,000×10%×1/12)。", "流動資產(現金)增加$241,080;流動負債=240,000-920=增加$239,080;應收票據帳戶沒有變動;收益增加$2,000。選 (B)。"], "pitfalls": "貼現後應收票據帳戶仍在(只是列為負債減項),不是減少;收益是$2,000而不是$2,009。", "distractors": {"A": "流動資產增加應為$241,080,$1,080只是差額。", "C": "貼現(附追索權)時應收票據帳戶不減少,改記貼現負債。", "D": "利息收入是$240,000×10%×1/12=$2,000,不是$2,009。"}}, "check": "python 驗算:到期值=241,080/0.98=246,000;面額=240,000;流動負債增加=240,000-920=239,080;與官方相符。", "verified": true, "note": ""}, {"id": "111-5-A-20", "exam": "111-5", "paper": "A", "q": 20, "unit": "十三、存貨", "topic": "存貨錯誤對淨利影響", "stem": "棒棒公司存貨採實地盤存制,X1年底實地盤點存貨為$100,000。X2年底調整後發現下列錯誤:\n(1) X1年年底盤點存貨中未計入寄銷品,售價$1,800(按成本加價20%)\n(2) X1年年底盤點存貨中包括一批過時商品,成本$5,000,但估計只能以成本的四折出售(該批商品已於X2年中出售)\n(3) X1年年底有一批運送中目的地交貨的銷貨(於X2年1月10日運抵目的地),成本$3,000、售價$5,000,X1年年底已認列銷貨收入、該批商品盤點時未列入存貨\n上述錯誤更正前X2年度本期淨利為$800,000,在不考慮所得稅因素下,正確的X2年度本期淨利為何?", "options": ["$797,840", "$798,500", "$801,500", "$803,500"], "answer": "D", "figure": null, "official": "(1)期末存貨少計$1,500→X2淨利多計$1,500;(2)期末存貨多計$3,000→X2淨利少計$3,000;(3)X1銷貨收入多計$5,000、存貨少計$3,000→X2淨利少計$5,000、多計$3,000。合計X2淨利少計$3,500,正確為$803,500。", "explain": {"concept": "期末存貨錯誤會影響當期淨利,並以相反方向影響次期淨利。", "steps": ["(1) 寄銷品成本=$1,800÷1.2=$1,500,X1年底存貨少計$1,500,X1淨利少計、X2淨利多計$1,500(要減)。", "(2) 過時商品成本$5,000,淨變現價值=$5,000×40%=$2,000,存貨應減損$3,000;X1存貨多計$3,000,X2淨利少計$3,000(要加)。", "(3) X1多認列銷貨收入$5,000,存貨少計$3,000,X1淨利淨多計$2,000;X2年相反:收入少計$5,000(要加)、銷貨成本少計$3,000(要減)。", "對X2淨利的調整:-1,500+3,000+5,000-3,000=+$3,500。", "正確X2淨利=$800,000+$3,500=$803,500,選 (D)。"], "pitfalls": "方向容易弄反;以及忘記(2)的減損是用淨變現價值(四折)計算,(3)要同時調整收入與成本。", "distractors": {"B": "若只調整(1)而漏掉(2)(3),會得到$798,500,但這樣忽略了其他兩項錯誤。"}}, "check": "python 驗算:800,000-1,500+3,000+5,000-3,000=803,500,與官方相符。", "verified": true, "note": ""}, {"id": "111-5-A-21", "exam": "111-5", "paper": "A", "q": 21, "unit": "十五、長期營業用資產", "topic": "雙倍餘額遞減法與年數合計法", "stem": "X2年年初購買機器設備,估計耐用年限5年,無殘值,該設備X3年年底調整後,採用雙倍倍數餘額遞減法與採用變率遞減法,前者的累計折舊餘額比後者的累計折舊餘額多出$12,000,試計算該機器設備的成本為何?", "options": ["$300,000", "$480,000", "$600,000", "$720,000"], "answer": "A", "figure": null, "official": "設成本為X。雙倍餘額遞減法累計折舊=X×(2/5)+X×(3/5)×(2/5)=0.64X;變率遞減法(年數合計法)累計折舊=X×(5+4)/15=0.6X。差額0.04X=$12,000,X=$300,000。", "explain": {"concept": "兩種遞減折舊法前兩年累計折舊的比較。", "steps": ["X2、X3共兩年。雙倍餘額遞減法年折舊率=2÷5=40%。", "第一年折舊=X×40%=0.4X;第二年折舊=(X-0.4X)×40%=0.24X;累計0.64X。", "年數合計法(變率遞減法):分母=5+4+3+2+1=15。第一年5/15、第二年4/15,累計=9/15=0.6X。", "差額=0.64X-0.6X=0.04X=$12,000。", "X=$12,000÷0.04=$300,000,選 (A)。"], "pitfalls": "年數合計法分母是1+2+…+5=15,容易誤用或忘記雙倍餘額遞減法第二年要用帳面金額計算。", "distractors": {}}, "check": "python 驗算:12,000÷(0.64-0.6)=300,000,與官方相符。", "verified": true, "note": ""}, {"id": "111-5-A-22", "exam": "111-5", "paper": "A", "q": 22, "unit": "十六、負債", "topic": "售後服務保證負債準備", "stem": "大興公司銷售產品附有1年製造瑕疵的售後服務保固,X1年度共銷售10,000組產品,根據經驗估計瑕疵的發生機率與維修費用如下:\n\n| 項目 | 發生機率 | 維修費用 |\n|---|---|---|\n| 無瑕疵 | 90% | 每組$0 |\n| 小瑕疵 | 8% | 每組$200 |\n| 大瑕疵 | 2% | 每組$500 |\n\nX1年度實際發生的產品售後服務維修為$200,000。有關該公司售後服務保固的帳務處理,下列敘述何者正確?", "options": ["X1年底資產負債表有關產品售後服務保固之負債準備列示$60,000", "實際發生產品售後服務維修時,導致負債準備增加$200,000", "估列售後服務保固時,導致營業費用增加$260,000", "大興公司的產品售後服務保固,屬於或有負債"], "answer": "A", "figure": null, "official": "估列保固負債準備=[(8%×$200)+(2%×$500)]×10,000=$260,000;負債準備餘額=$260,000-$200,000=$60,000。", "explain": {"concept": "期望值估列保固負債準備,實際發生時沖減準備。", "steps": ["每組期望維修費=8%×200+2%×500=16+10=$26。", "10,000組應估列保固=$26×10,000=$260,000;分錄:借:銷貨成本260,000,貸:保固之短期負債準備260,000。", "實際維修$200,000時:借:保固之短期負債準備200,000,貸:現金等200,000(負債準備減少,不是增加)。", "年底準備餘額=260,000-200,000=$60,000,故(A)正確。", "(C)估列時增加的是「銷貨成本」,不是營業費用;(D)製造瑕疵保固屬負債準備,不是或有負債。"], "pitfalls": "實際維修時負債準備是「減少」;估列保固費用要用機率加權(期望值)。", "distractors": {"B": "實際發生維修應使負債準備減少而非增加。", "C": "估列時借記「銷貨成本」,不是營業費用。", "D": "此類保固可合理估計,屬負債準備。"}}, "check": "python 驗算:(0.08×200+0.02×500)×10,000=260,000;260,000-200,000=60,000,與官方答案表(A)相符。", "verified": true, "note": ""}, {"id": "111-5-A-23", "exam": "111-5", "paper": "A", "q": 23, "unit": "十七、權益", "topic": "法定盈餘公積提撥", "stem": "小麗公司每年分配一次盈餘,X3年初累積虧損$100,000,X3年度認列員工酬勞$380,000、董監事酬勞$120,000,X3年度未扣除員工酬勞與董監事酬勞之稅前淨利為$2,000,000(營利事業所得稅稅率按目前所得稅法計算),X4年中經股東會決議X3年度的盈餘分配如下:\n(1) 彌補累積虧損\n(2) 提撥法定盈餘公積10%\n(3) 配發員工酬勞$380,000、董監事酬勞$120,000\n(4) 配發給股東現金股利$600,000\n依據上述決議,X3年度提列法定盈餘公積為何?", "options": ["$50,000", "$100,000", "$110,000", "$150,000"], "answer": "C", "figure": null, "official": "所得稅=($2,000,000-$380,000-$120,000)×20%=$300,000;法定盈餘公積=(稅前淨利-所得稅-累積虧損)×10%=($1,500,000-$300,000-$100,000)×10%=$110,000。", "explain": {"concept": "法定盈餘公積=(稅後淨利-彌補虧損)×10%。", "steps": ["先算稅前淨利(已扣員工、董監事酬勞)=2,000,000-380,000-120,000=$1,500,000。", "所得稅費用=1,500,000×20%=$300,000。", "稅後淨利=1,500,000-300,000=$1,200,000。", "先彌補累積虧損$100,000,剩$1,100,000。", "法定盈餘公積=1,100,000×10%=$110,000,選 (C)。"], "pitfalls": "忘記先扣員工與董監事酬勞才算所得稅;或忘記要先彌補虧損才提列公積。", "distractors": {"D": "沒扣所得稅,用1,500,000×10%。"}}, "check": "python 驗算:稅=300,000;(1,500,000-300,000-100,000)×10%=110,000,與官方相符。", "verified": true, "note": ""}, {"id": "111-5-A-24", "exam": "111-5", "paper": "A", "q": 24, "unit": "十一、現金及內部控制", "topic": "銀行存款調節表", "stem": "大雅公司3月31日台灣銀行存款調節表中項目如下:在途存款$40,000、銀行代收票據$30,000、未兌現支票$60,000、客戶支票存款不足被退票$9,000,3月31日銀行存款正確餘額為$150,000,4月份銀行往來資料如下:\n\n| 項目 | 存款紀錄 | 支票紀錄 | 銀行代收票據 | 客戶支票被退票 |\n|---|---|---|---|---|\n| 銀行帳 | $84,000 | $80,000 | $60,000 | $18,000 |\n| 公司帳 | $94,000 | $97,000 | $30,000 | $9,000 |\n\n試計算4月底銀行存款正確餘額為何?", "options": ["$123,000", "$143,000", "$189,000", "$203,000"], "answer": "C", "figure": null, "official": "由銀行方面:調節前銀行餘額=150,000-40,000+60,000=$170,000;4月底調節前銀行餘額=170,000+84,000-80,000+60,000-18,000=$216,000;在途存款=40,000+94,000-84,000=$50,000;未兌現支票=60,000+97,000-80,000=$77,000;正確餘額=216,000+50,000-77,000=$189,000。", "explain": {"concept": "用銀行對帳單方面,逐步往下推4月底餘額。", "steps": ["先求3月底調節前銀行餘額:正確餘額150,000=銀行餘額+在途存款40,000-未兌現支票60,000→銀行餘額=150,000-40,000+60,000=$170,000。", "4月底調節前銀行餘額=170,000+存款84,000-支票80,000+代收票據60,000-退票18,000=$216,000。", "4月底在途存款=3月在途40,000+公司存款94,000-銀行存款84,000=$50,000。", "4月底未兌現支票=3月未兌現60,000+公司開支票97,000-銀行已付80,000=$77,000。", "正確餘額=216,000+50,000-77,000=$189,000,選 (C)。", "也可由公司方面算:調節前公司餘額147,000+代收60,000-退票18,000=$189,000,兩種算法一致。"], "pitfalls": "在途存款、未兌現支票要「累計」,不是只用4月份金額;同時別漏掉退票與銀行代收。", "distractors": {}}, "check": "python 驗算:銀行方面與公司方面皆得189,000,與官方相符。", "verified": true, "note": ""}, {"id": "112-1-A-01", "exam": "112-1", "paper": "A", "q": 1, "unit": "一、會計基本概念", "topic": "會計法令適用對象", "stem": "我國企業適用之法令、行政命令及一般公認會計原則,下列敘述何者正確?\n①台基鋼股份有限公司為「公開發行公司」　　②明洋股份有限公司為「非公開發行公司」\n③旭日聯合會計師事務所為「合夥組織」　　④日順商店為「獨資組織」", "options": ["適用「證券交易法」者僅有①、②", "適用「商業會計法」者僅有③、④", "適用「企業會計準則公報」者有②、③、④", "適用「國際財務報導準則」者僅有①,其餘企業組織均不得選用"], "answer": "C", "figure": null, "official": "證券交易法僅適用公開發行公司①;商業會計法適用所有商業(①②③④);企業會計準則公報適用非公開發行公司及合夥、獨資(②③④);IFRS 以①為原則,其他企業亦得因實際業務需要選用。", "explain": {"concept": "分辨不同型態企業適用哪一套法令與會計準則:商業會計法管所有企業,證交法管公開發行,IFRS 給公開發行,企業會計準則公報給中小型企業。", "steps": ["先判斷四個組織的型態:①是公開發行公司,②是非公開發行公司,③合夥,④獨資。", "證券交易法只管「公開發行」公司,所以只適用①,選項 A 說「①、②」就錯了。", "商業會計法是所有「商業」都要遵守的基本大法,①②③④全部適用,所以 B 說「僅有③、④」錯誤。", "非公開發行公司、合夥與獨資適用「企業會計準則公報」,也就是②③④,所以 C 正確。", "IFRS 原則上由公開發行公司適用,但其他企業有需要也可選用,所以 D 的「均不得選用」太絕對,錯誤。"], "pitfalls": "「僅」「均不得」這類絕對字眼常是陷阱;另外別把「公開發行」與「非公開發行」的法令搞混。", "distractors": {"A": "以為非公開發行公司也要受證券交易法管,其實證交法只管公開發行公司。", "B": "以為商業會計法只管合夥、獨資,忘了它適用所有商業(含公司)。", "D": "以為 IFRS 只有公開發行公司可用,忽略其他企業可自願選用。"}}, "check": "逐一對照四個組織與法令適用範圍,僅 C 完全相符,與官方答案 C 一致。", "verified": true, "note": ""}, {"id": "112-1-A-02", "exam": "112-1", "paper": "A", "q": 2, "unit": "一、會計基本概念", "topic": "會計職業道德與法律責任", "stem": "李先生為一家實收資本額達五千萬元之欣欣股份有限公司負責人,從事貿易生意,並委託會計師事務所協助其處理會計事務,往年業務狀況良好。顧先生為會計師事務所的合夥人。李先生的公司為顧先生會計師事務所的主要客戶。2022 年,欣欣股份有限公司的業務陷入困境,顧先生的會計師事務所在年終核算後,發現欣欣股份有限公司存在嚴重虧損。本日,李先生邀請顧先生共進午餐,希望顧先生能盡一切能力幫助欣欣股份有限公司「改善」財政狀況,協助公司成功申請銀行信貸去支持近期生意,以扭轉公司的劣勢。屆時,公司將會給顧先生的會計師事務所更多生意。但如果顧先生拒絕他的要求,將終止與他的合作關係。試問下列敘述,何者錯誤?", "options": ["若顧先生答應李先生的要求,協助欣欣股份有限公司編製不實的財務報表,依據我國商業會計法第 71 條,將處五年以下有期徒刑、拘役或科或併科新臺幣六十萬元以下罰金", "李先生利用不正當方法,致使會計事項或財務報表發生不實之結果,依據我國商業會計法,最高可處五年以下有期徒刑", "顧先生應遵守「會計師職業道德規範」,按照相關法令及會計準則提供會計資訊", "欣欣股份有限公司若為非公開發行公司,則其財務報表不需另外經會計師簽證"], "answer": "D", "figure": null, "official": "實收資本額達三千萬元以上之非公開發行公司,其財務報表仍須經會計師簽證,故 D 錯誤。", "explain": {"concept": "非公開發行公司只要實收資本額達新臺幣三千萬元以上,財務報表就必須經會計師查核簽證;另外考商業會計法罰則與職業道德。", "steps": ["題目問「錯誤」的敘述,所以要找出說錯的那一項。", "A、B 都是商業會計法的罰則:製作不實報表、利用不正當方法使會計事項不實,最高皆可處五年以下有期徒刑,故 A、B 正確。", "C:會計師應遵守職業道德規範、依法令與準則提供資訊,正確。", "D:欣欣公司實收資本額是五千萬元,已超過三千萬元,即使是非公開發行公司,財務報表仍需經會計師簽證,所以 D 說「不需」是錯的。"], "pitfalls": "容易以為「非公開發行」就不用會計師簽證;其實要看資本額是否達三千萬元。", "distractors": {"A": "以為罰則數字記錯而誤判;其實五年以下有期徒刑、六十萬元以下罰金是正確的。", "B": "同樣是罰則,官方認為正確,沒有錯。", "C": "職業道德本來就要守法與依準則,屬正確敘述。"}}, "check": "資本額 $50,000,000 ≥ $30,000,000 ⇒ 須會計師簽證,D 錯誤,與官方答案 D 一致。", "verified": true, "note": ""}, {"id": "112-1-A-03", "exam": "112-1", "paper": "A", "q": 3, "unit": "二、會計循環及會計帳簿", "topic": "商業會計法帳簿憑證規定", "stem": "王老師任教於某國立技術型高中,於同學參加會計技術士丙級檢定前之會計課堂,提出以下四個依據我國「商業會計法」規定之會計帳簿處理問題,分別請四位同學回答,請問有哪幾位同學回答正確?\nQ1、會計憑證及帳簿至少應保存幾年?王同學:會計憑證及帳簿均至少保存十年\nQ2、會計事項應按發生次序逐日登帳,至遲不得超過多久?陳同學:會計事項應按發生次序逐日登帳,至遲不得超過二個月\nQ3、企業之主要帳簿為何?李同學:企業必須設置之會計帳簿為普通序時帳簿及總分類帳簿\nQ4、應採用之會計基礎為何?林同學:應採用之會計基礎為權責發生制;在平時採用現金收付制者,俟決算時,應依權責發生制予以更正", "options": ["僅陳同學、李同學", "僅王同學、林同學", "僅陳同學、李同學、林同學", "僅王同學、李同學、林同學"], "answer": "C", "figure": null, "official": "憑證除應永久保存或有關未結會計事項者外,於年度決算程序終了後至少保存 5 年;帳簿至少保存 10 年。故王同學錯,其餘三位正確。", "explain": {"concept": "商業會計法對憑證與帳簿保存年限(憑證 5 年、帳簿 10 年)、登帳時限、主要帳簿與會計基礎的規定。", "steps": ["Q1:會計憑證至少保存 5 年,會計帳簿至少保存 10 年,不是都 10 年,所以王同學錯。", "Q2:應按發生次序逐日登帳,至遲不得超過二個月,陳同學正確。", "Q3:企業必須設置的主要帳簿為「普通序時帳簿」與「總分類帳簿」,李同學正確。", "Q4:會計基礎採權責發生制,平時用現金收付制者,決算時要依權責發生制調整,林同學正確。", "正確的是陳、李、林三位,答案選 C。"], "pitfalls": "最常被混淆的是保存年限:憑證 5 年、帳簿 10 年(都是從決算程序終了後算起)。", "distractors": {"A": "漏掉林同學,可能以為平時用現金收付制,決算時就不必再調整。", "B": "相信王同學「均 10 年」的說法,忽略憑證只要保存 5 年。", "D": "同樣誤信王同學的 10 年說法。"}}, "check": "對照官方詳解,四人中僅王同學錯,選 C,與官方一致。", "verified": true, "note": ""}, {"id": "112-1-A-04", "exam": "112-1", "paper": "A", "q": 4, "unit": "一、會計基本概念", "topic": "會計基本假設", "stem": "有關會計基本假設之敘述,下列何者正確?", "options": ["業主代替企業支付電話費,必須記帳,是根據「繼續經營假設」", "員工士氣或經理人員之能力,無法入帳,是根據「企業個體假設」", "機器設備以帳面金額表示,而不考慮其清算價值,是根據「貨幣評價假設」", "定期編製財務報表,提供及時資訊,協助使用者擬定決策,是根據「報導期間假設」"], "answer": "D", "figure": null, "official": "A 是企業個體假設;B 是貨幣評價假設;C 是繼續經營假設;D 報導期間假設正確。", "explain": {"concept": "辨認四個基本假設:企業個體、繼續經營、貨幣評價、報導期間。", "steps": ["企業個體假設:企業與業主分開,所以業主代付電話費要入帳(A 說成繼續經營,錯)。", "貨幣評價假設:只記能用貨幣衡量的事項,所以員工士氣、經理能力無法入帳(B 說成企業個體,錯)。", "繼續經營假設:假設企業持續營運,所以機器用帳面金額(成本減折舊),不看清算價值(C 說成貨幣評價,錯)。", "報導期間假設:把繼續的經營切成一段段期間定期編表,及時提供資訊,所以 D 正確。"], "pitfalls": "四個假設名稱很像,記得關鍵字:個體=公私分開、繼續=不考慮清算、貨幣=可量化、期間=定期報表。", "distractors": {"A": "把「業主與企業分開」誤認成繼續經營。", "B": "把「無法用貨幣衡量」誤認成企業個體。", "C": "把「不看清算價值」誤認成貨幣評價,其實是繼續經營。"}}, "check": "逐項對應四個假設定義,僅 D 對,與官方一致。", "verified": true, "note": ""}, {"id": "112-1-A-05", "exam": "112-1", "paper": "A", "q": 5, "unit": "一、會計基本概念", "topic": "會計恆等式", "stem": "光明商店於 X1 年初的業主權益為$300,000,而在 X1 年底結帳前資產總額為$800,000,費損總額為$200,000,另外業主於 X1 年中增投現金$50,000,且已知 X1 年底負債與當年度收益比為 3:2,則 X1 年底負債總額及本期淨利之金額,下列何者正確?", "options": ["負債總額=$360,000,本期淨利=$40,000", "負債總額=$390,000,本期淨利=$60,000", "負債總額=$420,000,本期淨利=$80,000", "負債總額=$480,000,本期淨利=$120,000"], "answer": "B", "figure": null, "official": "設負債=3x、收益=2x,資產 $800,000=3x+($300,000+$50,000+2x-$200,000),得 x=$130,000,負債$390,000,淨利$60,000。", "explain": {"concept": "用會計恆等式:資產=負債+期末權益,期末權益=期初權益+增資+淨利。", "steps": ["設負債為 3x、收益為 2x。", "期末權益=期初權益+增資+(收益-費損)=$300,000+$50,000+(2x-$200,000)。", "資產=負債+權益:$800,000=3x+$300,000+$50,000+2x-$200,000。", "整理:$800,000=5x+$150,000,5x=$650,000,x=$130,000。", "負債=3×$130,000=$390,000;收益=2×$130,000=$260,000;淨利=$260,000-$200,000=$60,000,選 B。"], "pitfalls": "容易漏掉「增資 $50,000」,或把費損也乘進比例裡。", "distractors": {}}, "check": "python 解 5x+150,000=800,000 得 x=130,000,負債 390,000、淨利 60,000,與官方 B 相符。", "verified": true, "note": ""}, {"id": "112-1-A-06", "exam": "112-1", "paper": "A", "q": 6, "unit": "一、會計基本概念", "topic": "資產負債歸類與會計等式", "stem": "小明將會計項目進行下列初步歸類,並依據上課所學之會計恆等式進行驗算,結果等式兩邊並不相等,請教四位同學協助幫忙檢查錯誤,請問哪一位同學的說明正確?\n資產:現金$50,000、應收帳款$60,000、備抵損失-應收帳款$6,000(貸餘)、應收票據$80,000、預收佣金$30,000,存入保證金$50,000、機器設備成本$600,000、累計折舊-機器設備$120,000,資產總額共計$744,000\n負債:預付貨款$20,000、應付帳款$35,000、暫收款$39,600、代付款$3,000、銀行長期借款$150,000,負債總額共計$247,600\n權益:業主資本$300,000,業主往來$82,400(貸餘)", "options": ["趙同學說:正確的資產應為$686,600、負債應為$305,000", "錢同學說:正確的資產應為$687,000、負債應為$304,600", "孫同學說:正確的資產應為$694,000、負債應為$297,600", "李同學說:正確的資產應為$696,600、負債應為$295,000"], "answer": "B", "figure": null, "official": "資產=現金$50,000+應收帳款$60,000-備抵損失$6,000+應收票據$80,000+預付貨款$20,000+代付款$3,000+機器設備$600,000-累計折舊$120,000=$687,000;負債=應付帳款$35,000+暫收款$39,600+預收佣金$30,000+存入保證金$50,000+銀行長期借款$150,000=$304,600。", "explain": {"concept": "先把會計項目歸到對的類別(預收、暫收、存入保證金是負債;預付、代付是資產),再驗證資產=負債+權益。", "steps": ["權益=$300,000+$82,400=$382,400。", "找出歸錯類的項目:預收佣金(先收錢、有義務提供服務)是負債;存入保證金(別人存放在我們這的押金)是負債。這兩項原本放在資產,要搬到負債。", "預付貨款(先付錢、可收貨)是資產;代付款(替人代墊)是資產。這兩項原本放在負債,要搬到資產。", "重算資產:$50,000+$60,000-$6,000+$80,000+$20,000+$3,000+$600,000-$120,000=$687,000。", "重算負債:$35,000+$39,600+$30,000+$50,000+$150,000=$304,600。", "驗算:$687,000=$304,600+$382,400,等式成立,選 B。"], "pitfalls": "最容易判斷錯的是「存入保證金」(對方給我們的押金=負債)與「存出保證金」(我們付出去的押金=資產)。", "distractors": {}}, "check": "python 計算資產 687,000、負債 304,600,權益 382,400,等式成立,與官方 B 相符。", "verified": true, "note": ""}, {"id": "112-1-A-07", "exam": "112-1", "paper": "A", "q": 7, "unit": "十三、存貨", "topic": "進銷貨運費", "stem": "欣欣商店商品採用定期盤存制,有關運費之敘述,下列何者正確?", "options": ["目的地銷貨所支付之運費,屬於「銷貨成本」", "目的地進貨所代付之運費,貸記「應付帳款」", "起運點銷貨所代付之運費,借記「應收帳款」", "起運點進貨所支付之運費,屬於「營業費用」"], "answer": "C", "figure": null, "official": "目的地銷貨運費屬「運費(營業費用)」;目的地進貨代付運費借記「應付帳款」;起運點進貨運費屬「進貨運費(進貨成本)」。", "explain": {"concept": "運費要看「誰負擔」:賣方負擔屬營業費用(運費),買方負擔屬進貨成本;若對方該負擔但我方代付,則先借記應收(或應付)帳款。", "steps": ["起運點交貨:貨物一出賣方倉庫,所有權就轉給買方,運費由買方負擔。", "起運點銷貨、賣方先代付運費:賣方是替買方墊錢,借記「應收帳款」,所以 C 正確。", "目的地交貨:運費由賣方負擔。賣方付運費屬「運費」(營業費用),不是銷貨成本,A 錯。", "目的地進貨、賣方負擔運費,若買方代付,是替賣方墊錢,應借記「應付帳款」(減少欠款),不是貸記,B 錯。", "起運點進貨運費由買方負擔,屬「進貨運費」,是進貨成本的一部分(定期盤存制下最終歸入銷貨成本),不是營業費用,D 錯。"], "pitfalls": "先判斷是買方還是賣方負擔,再決定記成費用、成本或應收應付。", "distractors": {"A": "把賣方負擔的運費誤當成銷貨成本;應記營業費用(運費)。", "B": "方向記反,代付應借記應付帳款以抵減欠款。", "D": "忘記進貨運費要計入進貨成本,而非營業費用。"}}, "check": "概念題,依運費負擔原則與官方詳解雙重確認,選 C。", "verified": true, "note": ""}, {"id": "112-1-A-08", "exam": "112-1", "paper": "A", "q": 8, "unit": "二、會計循環及會計帳簿", "topic": "會計憑證種類", "stem": "有關會計憑證之敘述,下列何者錯誤?", "options": ["請購單、領料單,屬於「對外憑證」", "員工向企業借款所開立之借據,屬於「外來憑證」", "賒銷商品,在複式傳票四分法下,應編製「分錄轉帳傳票」", "原始憑證已具備傳票格式,以原始憑證代替記帳憑證,稱為「代傳票」"], "answer": "A", "figure": null, "official": "請購單、領料單屬於「內部憑證」,不是對外憑證,故 A 錯誤。", "explain": {"concept": "原始憑證分外來、對外、內部三類;傳票與代傳票的觀念。", "steps": ["題目問「錯誤」,找說錯的項目。", "請購單、領料單是企業內部作業使用,不對外交付,屬內部憑證,所以 A 錯。", "員工借款的借據由員工開給企業,是外來憑證,B 正確。", "複式傳票四分法下,賒銷(沒有現金收付)屬於轉帳交易,編製分錄轉帳傳票,C 正確。", "原始憑證已有傳票格式而直接代替記帳憑證,稱為代傳票,D 正確。"], "pitfalls": "憑證的分類看「從哪來、到哪去」:外來=別人給我、對外=我給別人、內部=公司內部使用。", "distractors": {"B": "借據由員工(外部)開立交給企業,為外來憑證,敘述正確。", "C": "賒銷無現金收付,屬轉帳傳票,敘述正確。", "D": "代傳票定義正確。"}}, "check": "概念題,官方詳解指 A 為錯誤,與會計憑證分類相符。", "verified": true, "note": ""}, {"id": "112-1-A-09", "exam": "112-1", "paper": "A", "q": 9, "unit": "十三、存貨", "topic": "進貨銷貨折扣與退回", "stem": "欣欣商店 10/15 賒購定價$50,000 之商品,九折成交,付款條件 2/10,n/30,EOM。10/30 因商品瑕疵,退還 1/5 之商品,剩餘貨款於 11/9 還清,則欣欣商店共支付多少現金還清貨款?", "options": ["$35,280", "$36,000", "$39,200", "$40,000"], "answer": "A", "figure": null, "official": "成交價$50,000×0.9=$45,000;退回 1/5=$9,000;剩$36,000;11/9 在次月 10 日內付款,享 2% 折扣,付$36,000×0.98=$35,280。", "explain": {"concept": "商業折扣先扣(定價×折數)得成交價;退貨後以剩餘金額計算現金折扣;EOM 表示從月底起算折扣期。", "steps": ["商業折扣:定價$50,000 九折,成交價=$50,000×0.9=$45,000(商業折扣不入帳)。", "退回 1/5:$45,000×1/5=$9,000,剩餘貨款=$45,000-$9,000=$36,000。", "付款條件 2/10,n/30,EOM:折扣期間是「月底後 10 天」,即 10/31 之後 10 天內,到 11/10。", "11/9 還款在 11/10 前,可享 2% 現金折扣:$36,000×2%=$720。", "實付現金=$36,000-$720=$35,280,選 A。"], "pitfalls": "注意商業折扣與現金折扣不同;EOM 的 10 天要從月底(10/31)起算。", "distractors": {"B": "算到剩餘貨款$36,000,忘記現金折扣。", "C": "用$40,000 乘 0.98,或誤用其他退回金額。", "D": "可能用定價$50,000 退 1/5 得$40,000,忽略九折與現金折扣。"}}, "check": "python:(50,000×0.9−50,000×0.9/5)×0.98=35,280,與官方 A 相符。", "verified": true, "note": ""}, {"id": "112-1-A-10", "exam": "112-1", "paper": "A", "q": 10, "unit": "四、分錄與日記簿", "topic": "分錄種類", "stem": "有關分錄種類之敘述,下列何者正確?", "options": ["企業現付水電費$5,000,其中半數應由業主負擔,屬於「簡單分錄」", "出租閒置倉庫,收取半年租金及一個月押金,屬於「現金分錄」", "在現金折扣期間內,收到客戶還來賒欠貨款,屬於「轉帳分錄」", "購買商品,半數簽發三十天期票據,半數暫欠,屬於「混合分錄」"], "answer": "B", "figure": null, "official": "A 為複合分錄;C 為混合分錄(現金+轉帳);D 為轉帳分錄。B 全部涉及現金,屬現金分錄,正確。", "explain": {"concept": "分錄依有無現金分三類:現金分錄(全部是現金)、轉帳分錄(完全無現金)、混合分錄(部分現金部分轉帳)。", "steps": ["出租倉庫收半年租金+一個月押金:借現金,貸租金收入(預收租金)及存入保證金,所有借貸都涉及現金,所以是現金分錄,B 正確。", "A:水電費半數歸業主,分錄「借:水電瓦斯費、業主往來;貸:現金」,有多個借方科目,是複式(複合)分錄,不是簡單分錄,A 錯。", "C:折扣期內收到賒欠貨款,借:現金、銷貨折讓;貸:應收帳款,既有現金又有轉帳項目,是混合分錄,C 錯。", "D:購買商品半數簽發票據、半數暫欠(應付帳款),完全沒有現金,是轉帳分錄,D 錯。"], "pitfalls": "「現金分錄/轉帳分錄/混合分錄」是看有沒有現金;「簡單分錄/複合分錄」是看借貸科目數量,兩種分類方式別混淆。", "distractors": {"A": "把一借二方當成簡單分錄,其實是複合分錄。", "C": "沒發現有銷貨折讓,以為是現金分錄的錯誤延伸;其實是混合分錄。", "D": "以為半數票據半數暫欠是混合分錄,但根本沒有現金,屬轉帳分錄。"}}, "check": "概念題,依官方詳解逐項核對,B 正確。", "verified": true, "note": ""}, {"id": "112-1-A-11", "exam": "112-1", "paper": "A", "q": 11, "unit": "五、過帳與分類帳", "topic": "分類帳", "stem": "有關分類帳之敘述,下列哪幾項正確?\n①分類帳之日期欄應填寫交易發生之日期\n②分類帳為表達第四級會計項目的變動情況\n③設有明細分類帳之總分類帳,又稱為統制帳戶\n④標準式分類帳有三個金額欄,隨時可得知帳戶之餘額", "options": ["僅②、③正確", "僅③、④正確", "僅①、②、③正確", "①、②、③、④均正確"], "answer": "C", "figure": null, "official": "④標準式分類帳僅有二個金額欄(借方金額及貸方金額),無法隨時得知帳戶之餘額;餘額式有三個金額欄,方可隨時得知。", "explain": {"concept": "分類帳格式:標準式(借方、貸方兩欄)與餘額式(借、貸、餘額三欄);總分類帳又稱統制帳戶。", "steps": ["①分類帳日期欄填交易發生日期,正確。", "②分類帳用來表達第四級(帳戶/會計項目)的增減變動,正確。", "③有明細分類帳控制的總分類帳,稱為統制帳戶,正確。", "④標準式只有借方金額欄與貸方金額欄,沒有餘額欄,所以不能隨時知道餘額;有三個金額欄的是餘額式,④錯。", "正確的是①②③,選 C。"], "pitfalls": "「標準式」跟「餘額式」要分清楚:有餘額欄的是餘額式。", "distractors": {"A": "漏掉①,以為日期是記帳日期而不是交易日期。", "B": "相信④是對的,把標準式與餘額式搞混。", "D": "④也當成正確,忽略標準式沒有餘額欄。"}}, "check": "概念題,官方指出④為錯誤,選 C。", "verified": true, "note": ""}, {"id": "112-1-A-12", "exam": "112-1", "paper": "A", "q": 12, "unit": "六、試算與試算表", "topic": "試算表與錯誤更正", "stem": "有關試算表的敘述,下列何者正確?", "options": ["試算表非企業正式報表,編製期間可視企業需要而定", "影響借貸平衡之錯誤並已過帳,則此類錯誤應採「分錄更正法」予以更正", "不影響借貸平衡之錯誤並已過帳,則此類錯誤應採「註銷更正法」予以更正", "係依據借貸平衡原理,驗證分錄或過帳是否有誤。故只要借貸平衡即可確認並無錯誤發生"], "answer": "A", "figure": null, "official": "影響借貸平衡之錯誤應採「註銷更正法」;不影響借貸平衡之錯誤應採「分錄更正法」,故 B、C 錯;試算表平衡仍可能有不影響平衡的錯誤,D 錯。", "explain": {"concept": "試算表是內部查核工具,不是正式報表;已過帳錯誤的更正方法依「是否影響借貸平衡」選擇。", "steps": ["A:試算表是自我檢查用,不屬正式財務報表,編製週期(每日、每月、每年)可依企業需要決定,正確。", "B:已過帳且「影響」借貸平衡的錯誤(例如金額抄錯、借貸方金額不等),要用註銷更正法;選項寫成分錄更正法,錯。", "C:已過帳但「不影響」借貸平衡的錯誤(例如用錯科目、借貸同額寫錯),要用分錄更正法;選項寫成註銷更正法,錯。", "D:試算表只檢查借貸總額是否相等,漏記整筆分錄、科目用錯、借貸同額重複等錯誤仍然會平衡,所以平衡不代表沒有錯誤,D 錯。"], "pitfalls": "兩種更正法很容易記反,記法:影響平衡→註銷更正;不影響平衡→分錄更正。", "distractors": {"B": "把兩種更正法的適用情形記反。", "C": "同樣把更正方法記反。", "D": "以為借貸平衡就代表帳務完全正確,忽略漏記、記錯科目等不影響平衡的錯誤。"}}, "check": "概念題,依官方詳解與更正法原則雙重確認,A 正確。", "verified": true, "note": ""}, {"id": "112-1-A-13", "exam": "112-1", "paper": "A", "q": 13, "unit": "六、試算與試算表", "topic": "餘額式試算表不平衡", "stem": "下列錯誤事項,何者會使餘額式試算表發生不平衡?", "options": ["賒銷商品$5,000,誤記為$50,000", "應收帳款收現$50,000,貸方誤記為「應付帳款$50,000」", "現購文具紙張$1,000,過帳時過入「現金」借方$1,000、「文具用品」貸方$1,000", "開立即期支票償還應付帳款$40,000,過帳時過入「應付帳款」借方$40,000、「銀行存款」借方$40,000"], "answer": "D", "figure": null, "official": "D 將銀行存款貸方誤過入借方,導致餘額式試算表借方餘額多記$80,000,貸方餘額正確,故借貸不平衡。", "explain": {"concept": "判斷錯誤是否使借貸不平:只有「借貸方金額不等」或「借貸方向記錯其一」會不平衡;金額同錯、科目用錯則仍平衡。", "steps": ["A:借貸兩邊同時記成$50,000,借貸仍相等,平衡。", "B:貸方應是「應收帳款」,誤記成「應付帳款」,只是科目用錯,借貸金額仍相等,平衡。", "C:現購文具:正確應借文具用品、貸現金。過帳時借現金、貸文具用品,兩個科目都反向,借貸金額仍相等,平衡。", "D:正確應借應付帳款$40,000、貸銀行存款$40,000。過帳時兩個都在借方,貸方少了$40,000,借方多了$40,000,借方餘額多記$80,000,所以不平衡。"], "pitfalls": "判斷時看「借方總額有沒有等於貸方總額」,而不是看科目有沒有用對。", "distractors": {"A": "以為金額錯誤就會不平衡,但借貸同時錯同額,仍平衡。", "B": "科目用錯並不影響借貸總額相等。", "C": "借貸方向都反過來,借貸總額仍相等。"}}, "check": "概念題:D 借方比正確多 $40,000、貸方比正確少 $40,000,試算表差額 $80,000,與官方 D 相符。", "verified": true, "note": ""}, {"id": "112-1-A-14", "exam": "112-1", "paper": "A", "q": 14, "unit": "七、調整", "topic": "漏作調整對淨利影響", "stem": "下列應調整項目於期末漏作,對淨利之影響為何?\n①應收未收利息$2,000\n②預期信用減損損失估計$5,000\n③記虛轉實下之預付半年保險費$12,000,尚有 2 個月\n④記虛轉實下之預收一年租金收入$24,000,已過期 10 個月", "options": ["淨利多計$1,000", "淨利多計$3,000", "淨利少計$5,000", "淨利少計$7,000"], "answer": "B", "figure": null, "official": "①收益少記$2,000→淨利少$2,000;②費損少記$5,000→淨利多$5,000;③費損多記$4,000→淨利少$4,000;④收益多記$4,000→淨利多$4,000;合計 -2,000+5,000-4,000+4,000=多計$3,000。", "explain": {"concept": "漏作調整分錄,會使收益或費損記錯。收益少記或費損多記→淨利少計;收益多記或費損少記→淨利多計。", "steps": ["①應收利息:漏作 借:應收利息 貸:利息收入 $2,000,收益少記,淨利少計$2,000。", "②預期信用減損損失:漏作 借:預期信用減損損失 貸:備抵損失 $5,000,費損少記,淨利多計$5,000。", "③「記虛轉實」是指購買時先把保險費記成費用(虛),期末要把未到期的部分轉回資產(預付保險費)。半年$12,000,每月$2,000,剩 2 個月=$4,000,漏作,費損多記$4,000,淨利少計$4,000。", "④預收租金一年$24,000,每月$2,000;已過期 10 個月,剩 2 個月=$4,000 應轉為負債。先記成收益而漏調整,收益多記$4,000,淨利多計$4,000。", "加總:-$2,000+$5,000-$4,000+$4,000=+$3,000,淨利多計$3,000,選 B。"], "pitfalls": "「記虛轉實」的調整要看清楚:是把已記成費用/收益中尚未屬於本期的部分轉出,不是把已到期的認列。", "distractors": {}}, "check": "python:-2000+5000-4000+4000=3000,淨利多計,與官方 B 相符。", "verified": true, "note": ""}, {"id": "112-1-A-15", "exam": "112-1", "paper": "A", "q": 15, "unit": "七、調整", "topic": "收付基礎與調整", "stem": "小閱獨資經營之「悅閱書坊」,因受消費者閱讀習慣的改變,銷售狀況不佳,故擬縮小營業規模,將部分空間出租。X2 年 9 月 1 日將此部分空間出租給蕭新業主經營飲料店,談妥每月租金$30,000,並簽訂 2 年合約,當日預收一年租金及押金$45,000,下列敘述何者正確?", "options": ["若該書坊採用現金收付基礎,X2 年度應認列租金收入$405,000", "若該書坊採用應計基礎,X2 年底調整分錄應借記「租金收入$120,000」", "若該書坊採用聯合基礎,X2 年底調整分錄應貸記「預收租金$240,000」", "該書坊無論採用何種基礎記帳,X2 年度應認列之租金收入均相同"], "answer": "C", "figure": null, "official": "現金基礎 X2 認列租金收入$360,000;應計基礎與聯合基礎 X2 應認列租金收入$120,000。", "explain": {"concept": "比較現金基礎與應計基礎:現金基礎收到錢就認列收入;應計基礎只認列本期已賺得的部分。", "steps": ["先算收取金額:每月$30,000×12 個月=$360,000(押金$45,000 是負債,不是收入)。", "現金基礎:收現即認列,X2 租金收入=$360,000,所以 A 說$405,000(把押金也算進去)錯。", "應計基礎:X2 年只賺 9/1~12/31 共 4 個月,租金收入=$30,000×4=$120,000。若收款時記預收租金,調整分錄是借:預收租金 120,000 貸:租金收入 120,000;B 說借記租金收入,錯。", "聯合基礎(收益依官方採應計認列):若收款時已全部記為租金收入$360,000,年底要把未賺得的$360,000-$120,000=$240,000 轉為預收租金,調整分錄:借:租金收入 240,000 貸:預收租金 240,000,所以 C 正確。", "現金基礎認列$360,000、其餘基礎$120,000,金額不同,D 錯。"], "pitfalls": "押金不是收入;還要記得現金基礎與應計基礎認列的收入金額不同。", "distractors": {"A": "把押金$45,000 也算成租金收入($360,000+$45,000)。", "B": "借貸方向記反,應是貸記租金收入(或借記預收租金)。", "D": "忽略現金基礎與應計基礎的差異。"}}, "check": "python:360,000-120,000=240,000;現金基礎 360,000、應計 120,000,與官方 C 相符。", "verified": true, "note": "官方詳解中聯合基礎之認列金額為$120,000(與應計基礎同),本題依官方答案。"}, {"id": "112-1-A-16", "exam": "112-1", "paper": "A", "q": 16, "unit": "十二、應收款項", "topic": "備抵損失餘額百分比法", "stem": "洋洋公司採帳款餘額百分比法提列預期信用減損損失,損失率 1%。該公司在 X1 年初備抵損失餘額為貸餘$100,當年度實際無法收回帳款金額為$150,損益表上預期信用減損損失為$900。請問該公司 X1 年底應收帳款餘額為何?", "options": ["$85,000", "$90,000", "$95,000", "$100,000"], "answer": "A", "figure": null, "official": "期末備抵損失=$100-$150+$900=$850;應收帳款=$850÷1%=$85,000。", "explain": {"concept": "備抵損失帳戶:期初餘額+本期提列的損失-實際沖銷=期末餘額;帳款餘額百分比法下,期末備抵損失=應收帳款餘額×損失率。", "steps": ["備抵損失 T 字帳:期初貸餘$100(貸方);實際無法收回$150 時借記備抵損失(減少);提列預期信用減損損失$900 時貸記備抵損失(增加)。", "期末餘額=$100-$150+$900=$850(貸餘)。", "帳款餘額百分比法:期末備抵損失=應收帳款餘額×1%。", "所以應收帳款餘額=$850÷1%=$85,000,選 A。"], "pitfalls": "$900 是「費用」也是「本期提列」金額,不是期末餘額;要先算出期末餘額再反推應收帳款。", "distractors": {"B": "把本期提列金額$900 當成期末備抵損失,$900÷1%=$90,000。", "D": "期末備抵損失誤算為$1,000($100+$900),忘記扣除實際沖銷的$150。"}}, "check": "python:(100-150+900)/0.01=85,000,與官方 A 相符。", "verified": true, "note": ""}, {"id": "112-1-A-17", "exam": "112-1", "paper": "A", "q": 17, "unit": "七、調整", "topic": "現金基礎與應計基礎轉換", "stem": "洋洋公司本年度應付帳款淨減少$100,000,預付貨款淨增加$250,000,存貨淨減少$50,000,則應計基礎下之銷貨成本比現金基礎下之銷貨成本多或少若干?", "options": ["多$100,000", "少$100,000", "多$300,000", "少$300,000"], "answer": "D", "figure": null, "official": "應計基礎銷貨成本+$100,000+$250,000-$50,000=現金基礎銷貨成本,所以應計基礎比現金基礎少$300,000。", "explain": {"concept": "現金基礎的進貨成本是「實際付現」,應計基礎是「權責發生」。把付現金額與應計金額之間的差,透過應付帳款、預付貨款、存貨的變動來還原。", "steps": ["應付帳款淨減少$100,000:表示付出去的現金比進貨多$100,000(還了以前的欠款),現金基礎成本較大 +$100,000。", "預付貨款淨增加$250,000:先付了錢但貨還沒到,現金基礎多付$250,000,現金基礎成本較大 +$250,000。", "存貨淨減少$50,000:賣掉的比買進的多,應計基礎銷貨成本比進貨多$50,000,所以現金基礎要 -$50,000。", "列式:現金基礎銷貨成本=應計基礎銷貨成本+$100,000+$250,000-$50,000=應計基礎+$300,000。", "所以應計基礎比現金基礎少$300,000,選 D。"], "pitfalls": "應付帳款「減少」代表現金付出較多;存貨「減少」則是成本較大的一方,方向容易弄反。", "distractors": {"C": "把差額方向弄反,誤以為應計基礎成本較多。"}}, "check": "python:-50,000+100,000+250,000=300,000,現金基礎多$300,000,即應計少$300,000,與官方 D 相符。", "verified": true, "note": ""}, {"id": "112-1-A-18", "exam": "112-1", "paper": "A", "q": 18, "unit": "八、結帳", "topic": "結帳", "stem": "有關結帳之敘述,下列何者正確?", "options": ["「備抵損失」需結清,轉入「本期損益」的借方", "「銷貨退回」需結清,轉入「本期損益」的借方", "無論採用銷貨成本法或本期損益法,期末存貨應記入貸方", "借記「本期損益」、貸記「業主往來」,表示本期有淨損產生"], "answer": "B", "figure": null, "official": "A 備抵損失應結轉下期;C 無論採用銷貨成本法或本期損益法,期末存貨均應借記;D 借記「本期損益」、貸記「業主往來」表示有淨利,選項寫淨損故錯;B 銷貨退回屬損益科目,結清轉入本期損益借方,正確。", "explain": {"concept": "結帳時,虛帳戶(收益、費損)要結清轉入本期損益;實帳戶(資產、負債、權益)餘額轉入下期。", "steps": ["「銷貨退回」是銷貨收入的減項,屬於損益類虛帳戶,餘額在借方,結帳時貸記銷貨退回、借記本期損益,所以 B 正確。", "「備抵損失」是應收帳款的抵銷科目,屬於資產負債表科目(實帳戶),餘額直接結轉下期,不必結清,A 錯。", "期末存貨是資產,餘額在借方,不論用銷貨成本法或本期損益法,都是借記「存貨」,C 錯。", "本期損益有貸方餘額代表淨利。結清本期損益時,要「借記本期損益、貸記業主往來(或業主資本)」。所以這個分錄代表淨利,而不是淨損,D 錯。"], "pitfalls": "辨別實帳戶與虛帳戶:備抵損失、累計折舊雖然名稱像「抵銷科目」,但屬實帳戶;銷貨退回與折讓才是損益科目。", "distractors": {"A": "誤把備抵損失當成損益類科目一併結清。", "C": "忘記存貨是資產,餘額在借方,不是貸方。", "D": "分不清淨利與淨損對本期損益結清分錄的方向:借記本期損益、貸記業主權益是淨利。"}}, "check": "概念題,依官方詳解與結帳原則雙重確認,B 正確。", "verified": true, "note": ""}, {"id": "112-1-A-19", "exam": "112-1", "paper": "A", "q": 19, "unit": "八、結帳", "topic": "結帳分錄(本期損益法)", "stem": "洋洋商店 X1 年底調整後未結帳前部分帳載資料有銷貨收入$50,000、租金收入$2,000、應收收入$6,000、銷貨成本$30,000、薪資支出$6,000、廣告費$2,000、文具用品$1,000、應付費用$5,000,結帳分錄採用本期損益法,下列何者正確?", "options": ["本期損益為淨利$13,000", "本期損益為淨利$14,000", "全部收益結清時,應貸記「本期損益」$58,000", "全部費損結清時,應借記「本期損益」$44,000"], "answer": "A", "figure": null, "official": "收益=$50,000+$2,000=$52,000;費損=$30,000+$6,000+$2,000+$1,000=$39,000;淨利=$52,000-$39,000=$13,000。", "explain": {"concept": "結帳時只把損益類科目(收益、費損)結入本期損益,資產、負債科目(如應收收入、應付費用)不是損益科目,不能算進去。", "steps": ["挑出收益科目:銷貨收入$50,000、租金收入$2,000,合計$52,000。「應收收入」$6,000 是資產,不能算。", "挑出費損科目:銷貨成本$30,000、薪資支出$6,000、廣告費$2,000、文具用品$1,000(依題意視為費用),合計$39,000。「應付費用」$5,000 是負債,不能算。", "淨利=收益-費損=$52,000-$39,000=$13,000,所以 A 正確。", "C:全部收益結清,應「借記」各收益科目、「貸記」本期損益$52,000;不是$58,000(誤把應收收入$6,000 算進去)。", "D:全部費損結清應借記本期損益$39,000,不是$44,000(誤把應付費用$5,000 算進去)。"], "pitfalls": "資產負債科目(應收收入、應付費用)不是損益科目,不要當成收益或費損。", "distractors": {"C": "把應收收入$6,000 當成收益,算出$58,000。", "D": "把應付費用$5,000 當成費損,算出$44,000。"}}, "check": "python:52,000-39,000=13,000,與官方 A 相符。", "verified": true, "note": ""}, {"id": "112-1-A-20", "exam": "112-1", "paper": "A", "q": 20, "unit": "十、加值型營業稅會計實務", "topic": "含稅進貨與折扣分錄", "stem": "X1 年 5 月 1 日向洋洋公司賒購商品$50,000,另加 5% 營業稅,付款條件為 2/10,1/20,n/30。同年 5 月 9 日以現金清償全部貨款,5 月 9 日當天之分錄,下列會計項目及金額何者錯誤?", "options": ["借記應付帳款$52,500", "貸記進貨折讓$1,050", "貸記進項稅額$50", "貸記現金$51,450"], "answer": "B", "figure": null, "official": "5/9 在 10 天內付款,折扣 2%:貨款折扣$50,000×2%=$1,000,營業稅同步減少$1,000×5%=$50,現金=$52,500-$1,000-$50=$51,450。", "explain": {"concept": "付款折扣要連同營業稅一起沖回:折扣金額記進貨折讓,對應的營業稅記進項稅額(貸方減少)。", "steps": ["5/1 進貨:借進貨$50,000、進項稅額$2,500,貸應付帳款$52,500。", "5/9 在 10 天內付款,適用 2% 折扣(題目 1/20 不適用,因為是第 8 天)。", "折扣金額=未稅貨款$50,000×2%=$1,000(貸記進貨折讓)。", "折扣同時使營業稅減少:$1,000×5%=$50(貸記進項稅額)。", "現金=$52,500-$1,000-$50=$51,450。分錄:借:應付帳款 52,500 貸:進貨折讓 1,000 進項稅額 50 現金 51,450。", "題目問「錯誤」,進貨折讓應是$1,000 而不是$1,050,選 B。"], "pitfalls": "折扣要只對「未稅貨款」計算,並同時調整稅額;很多人會把折扣直接算在含稅金額上。", "distractors": {"A": "應付帳款$52,500 是原始金額,借記正確。", "C": "進項稅額$50 為折扣對應的營業稅,正確。", "D": "現金$51,450 正確。"}}, "check": "python:52,500-1,000-50=51,450,進貨折讓應為 1,000,與官方 B 相符。", "verified": true, "note": ""}, {"id": "112-1-A-21", "exam": "112-1", "paper": "A", "q": 21, "unit": "十、加值型營業稅會計實務", "topic": "加值型營業稅", "stem": "有關加值型營業稅之敘述,下列何者正確?", "options": ["政府為鼓勵出口,特別規定出口貨物或勞務免徵營業稅", "購入運輸設備,其進項稅額均不得扣抵銷項稅額", "企業購入所有的不動產、廠房及設備,皆應繳納營業稅", "同樣商品本身的定價不會因為統一發票上的營業稅稅額的外加或內含而影響到銷項稅額的數字"], "answer": "D", "figure": null, "official": "A 出口貨物或勞務適用零稅率;B 購入貨車的進項稅額可扣抵;C 土地不用繳納營業稅。", "explain": {"concept": "營業稅的基本規定:零稅率、不得扣抵的進項稅額、免稅項目,以及稅額外加或內含的表示方式。", "steps": ["A:出口貨物或勞務是「零稅率」(可退還進項稅額),不是免稅,A 錯。", "B:購入九人座以下小客車的進項稅額不得扣抵;但若是貨車,進項稅額可以扣抵,B 說「均不得」錯。", "C:土地不屬營業稅課徵範圍(土地增值稅另計),所以購入土地不必繳營業稅,C 說「所有」錯。", "D:官方判定為正確敘述:同一商品的售價相同時,稅額外加或內含只是標示方式,銷項稅額為銷售額乘 5%,故 D 正確。"], "pitfalls": "「免稅」與「零稅率」差別在於進項稅額能不能退;記得小客車不能扣抵,貨車可以。", "distractors": {"A": "零稅率才是出口貨物的稅率;免稅表示不能扣抵進項稅額。", "B": "以偏概全,貨車的進項稅額可以扣抵。", "C": "忽略土地不屬營業稅課徵範圍。"}}, "check": "概念題,官方詳解已指出 A、B、C 錯誤,僅 D 正確。", "verified": true, "note": "D 選項文字為「銷項稅額」,依官方詳解為正確。"}, {"id": "112-1-A-22", "exam": "112-1", "paper": "A", "q": 22, "unit": "十、加值型營業稅會計實務", "topic": "加值型營業稅結算", "stem": "陽明公司為適用一般稅率之加值型營業稅營業人,適用營業稅率 5%。本年度五、六月總計內銷含稅的銷貨總額為$630,000、外銷銷貨總額為$300,000;與一般營業人交易之進項(未含營業稅)如下:進貨$500,000,進貨訂金$30,000,購買房地產$900,000 其中房屋價款為土地之 2 倍,購入中秋節員工獎品$20,000,購入辦公設備$40,000,向小規模營業人購入文具$5,000 收到收據乙紙,上期留抵稅額$40,000。則該公司六月底結算,下列何者錯誤?", "options": ["銷項稅額為$30,000", "應收退稅款為$28,500", "留抵稅額餘額為$21,500", "本期得扣抵銷項稅額之進項稅額為$58,500"], "answer": "B", "figure": null, "official": "銷項稅額$30,000;可扣抵進項稅額$58,500;溢付稅額$68,500;退稅限額$47,000;應退稅款$47,000;留抵稅額$21,500。", "explain": {"concept": "營業稅計算:銷項稅額、可扣抵進項稅額、溢付稅額、退稅限額(零稅率銷售額與資本設備進項)與留抵稅額。", "steps": ["銷項稅額:內銷含稅$630,000÷1.05×5%=$30,000(外銷零稅率,稅額為 0)。", "可扣抵進項:進貨$500,000、進貨訂金$30,000、房屋$600,000(房屋價款是土地的 2 倍,房地合計$900,000,所以房屋$600,000、土地$300,000)、辦公設備$40,000,合計$1,170,000,稅額$1,170,000×5%=$58,500。員工獎品與小規模收據、土地不能扣抵。", "溢付稅額=進項稅額$58,500+上期留抵$40,000-銷項$30,000=$68,500。", "退稅限額=(零稅率銷售額$300,000+購買固定資產(房屋$600,000+辦公設備$40,000))×5%=$47,000。", "應退稅款=溢付$68,500 與退稅限額$47,000 取小者=$47,000。", "留抵稅額=$68,500-$47,000=$21,500。", "所以 B 說應收退稅款$28,500 是錯的,選 B。"], "pitfalls": "容易漏掉:土地、員工獎品、小規模收據不能扣抵;還有退稅限額要與溢付稅額比小。", "distractors": {"A": "銷項稅額$30,000 正確。", "C": "留抵稅額$21,500 正確。", "D": "可扣抵進項稅額$58,500 正確。"}}, "check": "python:銷項 30,000;進項 58,500;溢付 68,500;退稅限額 47,000;留抵 21,500;B 的$28,500 錯誤,與官方 B 相符。", "verified": true, "note": ""}, {"id": "112-1-A-23", "exam": "112-1", "paper": "A", "q": 23, "unit": "七、調整", "topic": "交易事項對財務報表要素影響", "stem": "下列交易事項對當期財務報表要素影響的敘述,有哪幾項正確?\n①本期折舊多計,結帳後,本期資產少計、權益少計\n②本店代業主支付水電費,將導致費損增加、資產減少\n③權責發生基礎下,調整預收收益,導致資產減少、收益增加\n④貸記租金收入誤記為貸記租金支出之更正分錄,將導致收益增加、費損減少", "options": ["僅①正確", "僅②、③正確", "僅①、②、④正確", "①、②、③、④均正確"], "answer": "A", "figure": null, "official": "②代業主付水電費,借記業主往來(權益減少)、貸記現金(資產減少);③預收收益調整應使負債減少、收益增加;④更正分錄:借記租金支出、貸記租金收入,導致費損增加、收益增加。僅①正確。", "explain": {"concept": "判斷每筆事項對資產、負債、權益、收益與費損的影響方向。", "steps": ["①本期折舊多計:費用多記,淨利少,結帳後權益少;累計折舊多,資產淨額少。所以資產少計、權益少計,正確。", "②店代業主付水電費:分錄 借:業主往來(權益減少) 貸:現金(資產減少)。這是業主個人的支出,不是店的費用,所以不是費損增加,②錯。", "③預收收益調整:借:預收收益(負債減少) 貸:收益(收益增加)。影響是「負債減少」不是資產減少,③錯。", "④原本錯誤:貸記了租金支出(費損減少)。更正:借:租金支出(費損增加) 貸:租金收入(收益增加),所以是費損增加、收益增加,而不是費損減少,④錯。", "只有①正確,選 A。"], "pitfalls": "代業主付款、預收款項這類常見題,要分清楚是動到權益、負債還是損益。", "distractors": {"B": "以為代付水電費是店的費用,且把預收收益調整當成資產減少。", "C": "④的更正分錄方向弄錯。", "D": "全部都當成正確,沒逐項分析。"}}, "check": "概念題,依官方詳解僅①正確。", "verified": true, "note": ""}, {"id": "112-1-A-24", "exam": "112-1", "paper": "A", "q": 24, "unit": "九、財務報表", "topic": "速動比率", "stem": "▲閱讀下文,回答第 24-25 題\n王大明 X1 年初獨自出資經營順發商店,X1 年底流動資產包含現金$120,000、應收帳款$320,000、用品盤存$40,000、應收票據$200,000、存貨$80,000 及預付租金$40,000,流動比率為 2.5,非流動資產僅有辦公設備淨額$100,000;負債除流動負債,並無非流動負債項目,X1 年中王大明曾提取現金$50,000,並代商店支付租金$30,000,X1 年度銷貨收入$1,000,000,成本毛利率為 25%,純益率為 15%,X1 年度無營業外收入及支出項目。\n24. 請根據上列敘述,計算順發商店 X1 年底之速動比率為何?", "options": ["1.2", "1.5", "1.8", "2"], "answer": "D", "figure": null, "official": "流動資產=$800,000;流動負債=$800,000÷2.5=$320,000;速動資產=$120,000+$320,000+$200,000=$640,000;速動比率=$640,000÷$320,000=2。", "explain": {"concept": "流動比率=流動資產÷流動負債;速動比率=速動資產÷流動負債,速動資產只含現金、應收帳款、應收票據、短期投資等容易變現的資產,不含存貨、預付費用、用品盤存。", "steps": ["流動資產=$120,000+$320,000+$40,000+$200,000+$80,000+$40,000=$800,000。", "流動比率 2.5,所以流動負債=$800,000÷2.5=$320,000。", "速動資產只算現金、應收帳款、應收票據:$120,000+$320,000+$200,000=$640,000(排除用品盤存、存貨、預付租金)。", "速動比率=$640,000÷$320,000=2,選 D。"], "pitfalls": "速動資產要排除存貨、預付費用、用品盤存;別把整個流動資產拿來除。", "distractors": {}}, "check": "python:CL=800,000/2.5=320,000;速動資產 640,000;比率 2,與官方 D 相符。", "verified": true, "note": ""}, {"id": "112-1-A-25", "exam": "112-1", "paper": "A", "q": 25, "unit": "九、財務報表", "topic": "財務報表金額計算", "stem": "(承第 24 題)下列順發商店之項目金額,何者正確?", "options": ["銷貨成本金額為$750,000", "營業費用金額為$100,000", "X1 年初權益金額為$450,000", "X1 年底權益金額為$600,000"], "answer": "C", "figure": null, "official": "銷貨成本=$800,000;營業費用=$50,000;年底權益=$580,000;年初權益=$580,000+$50,000-$30,000-$150,000=$450,000。", "explain": {"concept": "成本毛利率是毛利÷成本,不是毛利÷銷貨;權益增減=淨利+增資-提取。", "steps": ["成本毛利率 25%:銷貨成本:毛利=100:25,銷貨=125,所以銷貨成本=$1,000,000×100/125=$800,000。選項 A 的$750,000 錯。", "純益率 15%:淨利=$1,000,000×15%=$150,000。毛利=$1,000,000-$800,000=$200,000,營業費用=$200,000-$150,000=$50,000,B 的$100,000 錯。", "年底總資產=流動資產$800,000+辦公設備$100,000=$900,000;只有流動負債$320,000;年底權益=$900,000-$320,000=$580,000,D 的$600,000 錯。", "權益變動:年底=年初+淨利+業主增資-提取。代商店支付租金$30,000 視為業主增資。", "年初權益=$580,000-$150,000-$30,000+$50,000=$450,000,C 正確。"], "pitfalls": "成本毛利率與銷貨毛利率不同;業主代店付款是增資,業主提取是減資。", "distractors": {"A": "誤把成本毛利率 25% 當成毛利÷銷貨,算出成本$750,000;正確應為毛利÷成本。"}}, "check": "python:銷貨成本 800,000;營業費用 50,000;年底權益 580,000;年初權益 450,000,與官方 C 相符。", "verified": true, "note": ""}, {"id": "112-2-A-01", "exam": "112-2", "paper": "A", "q": 1, "unit": "一、會計基本概念", "topic": "會計處理優先順序", "stem": "我國企業會計處理須遵守商業相關之法律及行政命令。而法律及行政命令沒有規範之細部事項則依循一般公認會計原則,不同企業組織適用法律及會計準則優先順序也不同。現今會計事務處理相關法令及一般公認會計原則:①商業會計處理準則、②企業會計準則(EAS)、③商業會計法、④國際財務報導準則(IFRSs)。企業組織之會計事務處理優先順序,下列何者正確?", "options": ["小稚獨資設立美甲工作室,則其會計處理優先順序為:①→②→③", "小桑與小嘉合夥設立律師事務所,則其會計處理優先順序為:③→②→①", "小許受雇於公開發行公司擔任企業會計人員,則其會計處理優先順序為:③→①→④", "小延受雇於非公開發行公司擔任企業會計人員,則其會計處理優先順序為:③→④→①"], "answer": "C", "figure": null, "official": "獨資、合夥:商業會計法→商業會計處理準則→企業會計準則(EAS);公開發行公司:商業會計法→商業會計處理準則→IFRSs;非公開發行公司:商業會計法→商業會計處理準則→(EAS 或 IFRSs)。", "explain": {"concept": "先分清楚「法律」和「準則」兩個層級,再判斷企業屬於哪一類。", "steps": ["最高位階是法律,所以「③商業會計法」一定排第一。", "第二順位是「①商業會計處理準則」(它是依商業會計法訂的行政命令),所以選項 A、B(把①放在②或③之後)、D(③後面接④)都有順序問題。", "獨資、合夥等小型企業,準則部分適用企業會計準則(EAS),順序為 ③→①→②。", "公開發行公司要採用 IFRSs,順序為 ③→①→④,所以 C 正確。", "非公開發行公司可選 EAS 或 IFRSs,順序是 ③→①→②(或 ③→①→④),不是 ③→④→①。"], "pitfalls": "記口訣:先「法」(商業會計法)、再「處理準則」、最後才是「會計準則」(EAS 或 IFRSs)。商業會計處理準則不會排在最後。", "distractors": {"A": "把①放第一、③放最後,把法律位階弄反了。", "B": "③放第一對,但把②排在①前面,忘了商業會計處理準則要先於會計準則。", "D": "③後面直接接④,漏掉①;且非公開發行公司應是 ③→①→②(或④)。"}}, "check": "概念題,依官方詳解與商業會計法位階確認。", "verified": true, "note": ""}, {"id": "112-2-A-02", "exam": "112-2", "paper": "A", "q": 2, "unit": "八、結帳", "topic": "期末會計程序", "stem": "會計循環中,平時的會計處理程序為:分錄→過帳→試算,就期末會計處理程序,下列何者錯誤?", "options": ["結帳→結帳後試算表→調整→編表", "調整→調整後試算表→編表→結帳", "調整→結帳→編表", "調整→結帳→結帳後試算表→編表"], "answer": "A", "figure": null, "official": "期末程序一定是「調整」在先、「結帳」在後;結帳後才做結帳後試算表。", "explain": {"concept": "記住調整一定要在結帳之前,因為結帳是把已調整好的損益科目結清。", "steps": ["先回想期末正確順序:調整→(調整後試算表)→編表(或結帳)→結帳→結帳後試算表。", "題目要找「錯誤」的。選項 A 先結帳、再調整,順序顛倒,錯誤。", "調整還沒做,損益金額就不正確,結帳等於把錯的數字結掉,所以調整必須在結帳之前。", "B、C、D 都是調整在結帳之前,屬於可接受的期末流程(編表可在結帳前或結帳後)。"], "pitfalls": "看到「錯誤」兩字要找不對的選項;調整與結帳順序不能顛倒。", "distractors": {"B": "調整→調整後試算表→編表→結帳,順序合理,是正確敘述。", "C": "調整→結帳→編表,調整仍在結帳前,屬可接受順序。", "D": "調整→結帳→結帳後試算表→編表,也是合理流程。"}}, "check": "概念題,依官方詳解確認。", "verified": true, "note": ""}, {"id": "112-2-A-03", "exam": "112-2", "paper": "A", "q": 3, "unit": "三、會計基本法則", "topic": "交易對會計方程式的影響", "stem": "根據借貸法則,下列哪一項交易事項,不會使會計基本方程式之資產、負債、權益三要素各項總額發生變動?", "options": ["支付因營運產生的電話費", "收到客戶之前交易所欠貨款", "賒購運輸設備", "賒銷商品給小威商店,並簽發匯票請其承兌"], "answer": "B", "figure": null, "official": "會計方程式:資產=負債+權益。只有「資產內部一增一減」的交易,三要素總額都不變。", "explain": {"concept": "逐題判斷每筆交易使哪些科目增減,看三大要素總額有沒有變。", "steps": ["A 支付電話費:借 電話費(費用,權益減少)、貸 現金(資產減少)→資產與權益都減少,有變動。", "B 收到客戶之前所欠貨款:借 現金(資產增加)、貸 應收帳款(資產減少)→資產一增一減,總額不變,三要素都沒變動,答案選 B。", "C 賒購運輸設備:借 運輸設備(資產增加)、貸 應付帳款(負債增加)→資產、負債都增加。", "D 賒銷商品並簽發匯票請其承兌:借 應收帳款(資產增加)、貸 銷貨收入(收益增加,權益增加)→資產、權益都增加。"], "pitfalls": "「資產內部互換」(如收現、買現金資產)不影響方程式總額。賒購、賒銷都會讓總額增加。", "distractors": {"A": "費用發生使權益減少、現金減少,總額會變。", "C": "賒購使資產與負債同時增加,總額變大。", "D": "賒銷使資產與收益(權益)同時增加,總額變大。"}}, "check": "概念題,逐項分錄推演確認。", "verified": true, "note": ""}, {"id": "112-2-A-04", "exam": "112-2", "paper": "A", "q": 4, "unit": "一、會計基本概念", "topic": "會計恆等式與損益", "stem": "安心商店 08 年初權益總額為$375,000,08 年底結帳後,負債總額為$487,500,權益總額為資產的二分之一,且無增減資、存入或提取情形,08 年度收益為費損之 3 倍,則該店 08 年度收益為何?", "options": ["$112,000", "$168,750", "$225,000", "$273,500"], "answer": "B", "figure": null, "official": "資產=負債+權益;期末權益=期初權益+收益−費損(無增資、提取時)。", "explain": {"concept": "先用「權益是資產的一半」求出期末權益,再算本期淨利,最後用收益是費損 3 倍拆開。", "steps": ["設期末權益為 X,因為權益是資產的 1/2,所以期末資產=2X。", "代入資產=負債+權益:2X = $487,500 + X,所以 X = $487,500(期末權益)。", "期末權益=期初權益+本期淨利:$487,500 = $375,000 + 淨利,淨利 = $112,500。", "設費損為 Y,收益=3Y,淨利=3Y − Y = 2Y = $112,500,所以 Y = $56,250。", "收益=3Y = 3 × $56,250 = $168,750,答案選 B。"], "pitfalls": "容易把淨利 $112,500 當成收益,但題目問的是「收益」,要再用 3 倍關係分出收益與費損。", "distractors": {}}, "check": "python:淨利=487,500−375,000=112,500;費損=112,500/2=56,250;收益=168,750,與官方 B 相符。", "verified": true, "note": ""}, {"id": "112-2-A-05", "exam": "112-2", "paper": "A", "q": 5, "unit": "二、會計循環及會計帳簿", "topic": "傳票與憑證分類", "stem": "宜蘭商店傳票制度採複式傳票四分法,下列會計事項之相關會計憑證及交易分類說明,何者正確?", "options": ["業主投資現金$700,000 及商品$300,000 開設宜蘭商店,收取外來憑證及記入現金收入傳票及帳簿,此交易屬於多項、混合分錄", "現金支付員工個人薪資$30,000,並代扣所得稅 5%,開立對外憑證及記入分錄轉帳傳票及帳簿,此交易屬於多項、轉帳分錄", "現銷商品$10,000 給臺北商店,取得外來憑證及記入現金轉帳傳票及帳簿,此交易屬單項、現金分錄", "賒購載貨用卡車一部$600,000,收取外來憑證及記入分錄轉帳傳票及帳簿,此交易屬於單項、轉帳分錄"], "answer": "D", "figure": null, "official": "四分法:現金收入傳票(全部收現)、現金支出傳票、現金轉帳傳票(部分收付現)、分錄轉帳傳票(全部不涉及現金)。交易分類看「借貸科目數」(單項/多項)與「是否涉及現金」(現金/轉帳/混合)。", "explain": {"concept": "逐一判斷:涉及現金?(全部、部分、完全沒有)、科目幾項、憑證是收到(外來)或開出(對外)。", "steps": ["D:賒購卡車,借 運輸設備、貸 應付帳款,完全沒有現金,所以是轉帳分錄、記分錄轉帳傳票;借貸各一個科目,是單項;賒購向對方取得發票,是外來憑證。全部符合,D 正確。", "A:業主投資現金$700,000及商品$300,000,有部分現金,應記「現金轉帳傳票」,不是現金收入傳票;所以 A 錯。", "B:支付薪資並代扣所得稅,部分付現(其餘為代收款),屬混合分錄、記現金轉帳傳票,不是轉帳分錄;所以 B 錯。", "C:現銷商品是全部收現,屬現金分錄,應記「現金收入傳票」,而且銷貨給對方要開立「對外憑證」;所以 C 錯。"], "pitfalls": "「現金轉帳傳票」用於一筆交易中一部分涉及現金、一部分不涉及現金;全部沒有現金才是分錄轉帳傳票。外來憑證是別人開給我(進貨),對外憑證是我開給別人(銷貨)。", "distractors": {"A": "部分現金部分商品投資,應記現金轉帳傳票,誤記成現金收入傳票。", "B": "代扣稅使交易有部分現金(混合分錄),誤判成轉帳分錄。", "C": "現銷全部收現,應用現金收入傳票;且銷貨是開立對外憑證,不是收取外來憑證。"}}, "check": "概念題,依官方詳解確認。", "verified": true, "note": ""}, {"id": "112-2-A-06", "exam": "112-2", "paper": "A", "q": 6, "unit": "四、分錄與日記簿", "topic": "銷貨折扣與銷貨退回", "stem": "艾咪商店 11/1 銷售商品一批,定價$60,000,商業折扣 10%,收款條件:2/10,n/30,EOM,當日收到客戶簽發即期支票償還貨款$20,000,其餘貨款給予賒欠,收到的支票當日存入銀行,11/4 收到顧客退貨$5,000,12/8 收到客戶剩餘款項,請問艾咪商店 12/8 收現金額為何?", "options": ["$28,420", "$33,320", "$34,300", "$35,000"], "answer": "A", "figure": null, "official": "先扣商業折扣得「發票淨價」,再扣已收款、退貨,剩餘應收款項在折扣期間內付款可享現金折扣 2%。EOM 表示月底後起算 10 天,即 12/10 前付款有折扣,12/8 符合。", "explain": {"concept": "商業折扣直接降低售價(不入帳);現金折扣只就「剩餘應付款」計算。", "steps": ["商業折扣:$60,000 × (1 − 10%) = $54,000(這才是銷貨收入)。", "11/1 收到支票$20,000 → 應收帳款 = $54,000 − $20,000 = $34,000。", "11/4 顧客退貨$5,000 → 應收帳款 = $34,000 − $5,000 = $29,000。", "EOM 條件:月底(11/30)後 10 天內(到 12/10)付款可享 2% 折扣;12/8 付款,符合。", "現金折扣 = $29,000 × 2% = $580。", "12/8 實收現金 = $29,000 − $580 = $28,420,答案選 A。"], "pitfalls": "常見錯誤:忘記退貨要先扣、或忘了商業折扣,或把折扣算在 $34,000 上。", "distractors": {"B": "$34,000 × 98% = $33,320,忘了扣 11/4 的退貨$5,000。", "C": "$35,000 × 98% = $34,300,其中 $35,000 = $60,000 − $20,000 − $5,000,忘了先扣商業折扣。", "D": "$60,000 − $20,000 − $5,000 = $35,000,沒有商業折扣也沒有現金折扣。"}}, "check": "python:54,000−20,000−5,000=29,000;×0.98=28,420,與官方 A 相符。", "verified": true, "note": ""}, {"id": "112-2-A-07", "exam": "112-2", "paper": "A", "q": 7, "unit": "五、過帳與分類帳", "topic": "明細分類帳與總分類帳", "stem": "下列敘述何者正確?", "options": ["應收帳款明細分類帳是最能讓企業了解每個客戶收款狀況的帳簿資料", "分類帳可以完全避免會計項目漏記、重複紀錄的錯誤發生", "查詢標準式分類帳可得知帳戶餘額", "明細分類帳根據日記簿過帳"], "answer": "A", "figure": null, "official": "明細分類帳依客戶(或品項)分戶記錄,可看出每個客戶的欠款與收款情形。", "explain": {"concept": "分清總分類帳與明細分類帳的用途與過帳依據。", "steps": ["A:應收帳款明細分類帳為每個客戶各設一帳戶,可知每位客戶應收、已收與餘額,正確。", "B:分類帳只是把日記簿分戶彙總,不能完全避免漏記或重複記錄(日記簿漏記,分類帳也會漏),錯誤。", "C:標準式分類帳(借方、貸方分左右)不直接顯示餘額;能直接顯示餘額的是「餘額式」分類帳,錯誤。", "D:明細分類帳是根據「傳票」或原始憑證過帳,而不是日記簿(日記簿過帳到總分類帳),錯誤。"], "pitfalls": "標準式要自己算餘額;餘額式才每筆後面有餘額欄。", "distractors": {"B": "以為分類帳可以防止漏記、重複,實際上做不到。", "C": "誤把標準式當餘額式。", "D": "明細分類帳依傳票過帳,不是日記簿。"}}, "check": "概念題,依官方詳解確認。", "verified": true, "note": ""}, {"id": "112-2-A-08", "exam": "112-2", "paper": "A", "q": 8, "unit": "六、試算與試算表", "topic": "過帳錯誤與試算表差額", "stem": "會計人員筱靜在編製餘額式試算表時發現貸方餘額比借方餘額少$45,如果筱靜過帳時僅發生一項錯誤,下列敘述何者最有可能為筱靜發生之錯誤?", "options": ["過帳時將一筆交易$20,450 的金額,貸方誤記為$2,045", "過帳時將一筆交易$2,972 的金額,貸方誤記為$2,927", "將一筆現銷$450 的交易,誤記為賒購$495", "過帳時將一筆借方$45 金額誤過入貸方"], "answer": "B", "figure": null, "official": "試算表差額 $45 為 9 的倍數(換位錯誤)特徵;貸方少 $45 表示貸方少記了 $45。", "explain": {"concept": "先看差額 $45 是誰少、少多少,再逐項算每個錯誤造成的差額與方向。", "steps": ["貸方餘額比借方少 $45:表示貸方少記 $45(或借方多記 $45)。", "A:貸方 $20,450 誤記為 $2,045,貸方少 $18,405,差額不是 $45。", "B:貸方 $2,972 誤記為 $2,927,貸方少 $2,972 − $2,927 = $45,與差額吻合,且方向正確。", "C:現銷$450 誤記為賒購$495:正確是借 現金 $450、貸 銷貨收入 $450;錯誤是借 進貨 $495、貸 應付帳款 $495。兩個分錄都借貸相等,試算表仍平衡,不會出現 $45 的差額。", "D:把借方 $45 誤過入貸方,借方少 $45、貸方多 $45,差額會是 $90,不是 $45。"], "pitfalls": "差額是 9 的倍數時常是數字顛倒;但仍要用方向驗證。D 的差額是兩倍($90)。", "distractors": {"A": "貸方少記 $18,405,差額太大。", "C": "借貸同時多計 $45,試算表仍平衡。", "D": "借方少、貸方多各 $45,差額 $90,不是 $45。"}}, "check": "python:20,450−2,045=18,405;2,972−2,927=45 ✓;D 差額 90。與官方 B 相符。", "verified": true, "note": ""}, {"id": "112-2-A-09", "exam": "112-2", "paper": "A", "q": 9, "unit": "六、試算與試算表", "topic": "錯誤更正與影響", "stem": "新竹商店 12 月底支付租金$30,000,其中三分之一應由業主負擔,會計人員誤記為借:薪資支出$30,000,貸:現金$20,000、保險費$10,000,過帳過程無誤,請問上述帳務錯誤所影響結果為何?", "options": ["餘額式試算表不平衡,借貸方總和相差$20,000", "12 月底流動資產低估$10,000", "餘額式試算表仍然平衡,但借貸方總額均高估$20,000", "12 月底權益高估$10,000"], "answer": "D", "figure": null, "official": "先寫出正確分錄,再與錯誤分錄比對現金、費用、業主往來各差多少。", "explain": {"concept": "把正確分錄與錯誤分錄並排,逐個科目比較差額,再判斷對資產、權益、試算表的影響。", "steps": ["正確分錄:借 租金支出 $20,000(2/3 為商店費用)、借 業主往來 $10,000(1/3 業主負擔,相當於業主提取)、貸 現金 $30,000。", "錯誤分錄:借 薪資支出 $30,000、貸 現金 $20,000、貸 保險費 $10,000。借貸相等,所以試算表仍平衡。", "現金:正確貸 $30,000,錯誤只貸 $20,000,現金少減 $10,000,所以資產(現金)高估 $10,000。", "費用:正確費用 $20,000;錯誤費用 = 薪資 $30,000 − 保險費 $10,000 = $20,000,淨額相同,損益沒有影響。", "業主往來:正確應借 $10,000(權益減少),錯誤沒有記,權益少減 $10,000,所以權益高估 $10,000,答案選 D。"], "pitfalls": "借貸仍平衡,所以不會造成試算表不平衡;要用「正確 vs 錯誤」逐科目比較。", "distractors": {"A": "錯誤分錄借貸皆為 $30,000,試算表仍平衡。", "B": "現金少減,所以是流動資產「高估」$10,000,不是低估。", "C": "試算表平衡沒錯,但借貸兩邊高估的金額是 $10,000,不是 $20,000。"}}, "check": "手算:資產高估 10,000 且權益高估 10,000,符合 資產=負債+權益;與官方 D 相符。", "verified": true, "note": ""}, {"id": "112-2-A-10", "exam": "112-2", "paper": "A", "q": 10, "unit": "七、調整", "topic": "調整分錄概念", "stem": "期末有關應計項目及預計項目之調整分錄,下列敘述何者正確?", "options": ["若會計帳務於處理交易時沒有發生任何錯誤,則期末不用進行調整", "調整分錄會涉及現金項目", "調整分錄是因採用現金基礎衡量損益所致", "調整分錄必定同時影響資產負債表及綜合損益表項目"], "answer": "D", "figure": null, "official": "每一筆調整分錄都有一個「實帳戶」(資產或負債)和一個「虛帳戶」(收益或費損),所以一定同時影響資產負債表與綜合損益表。", "explain": {"concept": "記住調整的目的是讓收益與費損歸屬正確期間(應計基礎)。", "steps": ["調整是依「權責發生制(應計基礎)」,把收益、費損歸屬到正確期間。", "每筆調整分錄的借貸方,一邊是資產負債表科目(如應收收益、預付費用、累計折舊),另一邊是損益科目(如利息收入、折舊費用)。", "因此調整分錄必定同時影響資產負債表與綜合損益表,D 正確。", "A 錯:即使沒有記錯,仍需因時間經過而調整(如折舊、預付費用到期)。B 錯:調整分錄不涉及現金。C 錯:是採用應計基礎才需要調整,現金基礎不需調整。"], "pitfalls": "調整分錄「不涉及現金」是重點;現金基礎不用調整。", "distractors": {"A": "沒記錯也要調整,因為期間經過的費用/收益尚未入帳。", "B": "調整不動用現金(現金交易已在平時記錄)。", "C": "調整是因為採用應計(權責發生)基礎,不是現金基礎。"}}, "check": "概念題,依官方詳解與會計原理確認。", "verified": true, "note": ""}, {"id": "112-2-A-11", "exam": "112-2", "paper": "A", "q": 11, "unit": "十五、長期營業用資產", "topic": "直線法折舊與剩餘年限", "stem": "大成公司運輸設備成本$720,000,殘值$20,000,採直線法提列折舊,每年應提列折舊$70,000,至本年底結帳後,該運輸設備帳面金額為$370,000,試問該運輸設備尚可使用幾年?", "options": ["3 年", "4 年", "5 年", "6 年"], "answer": "C", "figure": null, "official": "尚可折舊的金額 = 帳面金額 − 殘值;除以每年折舊額得剩餘年限。", "explain": {"concept": "帳面金額減殘值,才是「以後還可以提列的折舊總額」。", "steps": ["帳面金額 = $370,000,殘值 = $20,000。", "尚未提列的折舊總額 = $370,000 − $20,000 = $350,000。", "每年折舊 $70,000,剩餘年限 = $350,000 ÷ $70,000 = 5 年,答案選 C。"], "pitfalls": "不要用成本去除,也不要忘了扣殘值。", "distractors": {}}, "check": "python:(370,000−20,000)/70,000=5,與官方 C 相符。", "verified": true, "note": ""}, {"id": "112-2-A-12", "exam": "112-2", "paper": "A", "q": 12, "unit": "十三、存貨", "topic": "存貨錯誤對損益的影響", "stem": "和興公司存貨採定期盤存制,該公司在 08 年 12 月 31 日有存貨一批$9,000,期末遺漏盤點且未入帳;09 年另一批進貨$12,000,於購入時並未入帳,但 09 年期末存貨盤點無誤。試問以上兩項錯誤對 09 年度之淨利及期末保留盈餘會造成何種影響?", "options": ["淨利多計$21,000;保留盈餘多計$12,000", "淨利少計$12,000;保留盈餘多計$9,000", "淨利多計$12,000;保留盈餘多計$30,000", "淨利少計$21,000;保留盈餘少計$30,000"], "answer": "A", "figure": null, "official": "定期盤存制:銷貨成本 = 期初存貨 + 進貨 − 期末存貨。期末存貨錯誤會影響當期與下期。", "explain": {"concept": "分年度判斷:08 年末存貨少計 → 09 年初存貨少計,再加 09 年進貨少計。", "steps": ["08 年底存貨少計 $9,000 → 08 年銷貨成本多計、淨利少計 $9,000。", "同一筆錯誤變成 09 年期初存貨少計 $9,000 → 09 年銷貨成本少計 $9,000 → 09 年淨利多計 $9,000。", "09 年進貨少記 $12,000 → 銷貨成本少計 $12,000 → 09 年淨利多計 $12,000。", "09 年淨利共多計 $9,000 + $12,000 = $21,000。", "保留盈餘是累積數:08 年少計 $9,000 + 09 年多計 $21,000 = 多計 $12,000(08 年的錯誤到 09 年底已自動抵銷,只剩進貨漏記的 $12,000),答案選 A。"], "pitfalls": "期末存貨錯誤會「自動抵銷」,兩年合計對保留盈餘沒有影響;題目的進貨漏記才是 09 年底留下的錯誤。", "distractors": {"B": "方向錯誤,把淨利多計寫成少計。", "C": "保留盈餘多計 $30,000 是把 $9,000 與 $21,000 加總,忘了 08 年錯誤已抵銷。", "D": "淨利多計誤為少計,方向相反。"}}, "check": "python:09 淨利影響=9,000+12,000=21,000;保留盈餘=−9,000+21,000=12,000,與官方 A 相符。", "verified": true, "note": ""}, {"id": "112-2-A-13", "exam": "112-2", "paper": "A", "q": 13, "unit": "八、結帳", "topic": "結帳概念", "stem": "有關結帳之敘述,下列何者正確?", "options": ["結帳時必須將實帳戶與虛帳戶餘額轉入下期", "結帳分錄主要是將所有非損益項目餘額結清歸零", "獨資企業於期末結帳時,應將本期損益帳戶的餘額轉入業主資本帳戶", "結帳時本期損益產生借方餘額表示本期發生淨損"], "answer": "D", "figure": null, "official": "結帳是把虛帳戶(收益、費損)結清歸零,結到本期損益,再轉入權益;實帳戶餘額才轉入下期。", "explain": {"concept": "回想:收益、費損 → 本期損益 → 業主資本(或業主往來);借方餘額代表費損大於收益。", "steps": ["A:只有「實帳戶」餘額轉入下期;虛帳戶結帳後歸零,不會轉入下期,錯誤。", "B:結帳分錄主要是把「損益項目」(收益、費損)結清,不是非損益項目,錯誤。", "D:本期損益是收益與費損的彙總帳戶,收益在貸方、費損在借方;若借方餘額,表示費損大於收益,即淨損,正確。", "C:官方詳解將此選項視為錯誤(詳解引用的是「業主往來帳戶」版本),見備註。"], "pitfalls": "結帳對象是虛帳戶,不是實帳戶;借方餘額=淨損、貸方餘額=淨利。", "distractors": {"A": "虛帳戶結帳後歸零,不會轉入下期。", "B": "結帳是結清損益項目,不是非損益項目。"}}, "check": "概念題。選項 C 依一般教材(本期損益轉入業主資本)似乎也正確,但官方詳解把 C 列為錯誤。", "verified": false, "note": "官方詳解對 C 的引文寫「轉入業主往來帳戶」,與試題印的「業主資本帳戶」不同;依試題原文 C 似乎亦可成立,答案仍照官方 D。"}, {"id": "112-2-A-14", "exam": "112-2", "paper": "A", "q": 14, "unit": "八、結帳", "topic": "調整後與結帳後試算表差異", "stem": "下列會計項目中,何者調整後試算表及結帳後試算表中所列示金額有可能不同?", "options": ["業主往來", "備抵損失", "代收款", "應收租金"], "answer": "A", "figure": null, "official": "結帳後試算表只有實帳戶;業主往來屬權益項目,結帳時會結轉到業主資本,餘額可能不同;其他資產、負債科目餘額不變。", "explain": {"concept": "實帳戶(資產、負債)結帳時餘額不變;權益中的「業主往來」是暫時性科目,結帳時結清。", "steps": ["結帳時,損益項目結到本期損益,再轉入業主資本;業主往來也要結清轉入業主資本。", "所以調整後試算表的業主往來餘額,在結帳後試算表中會變為 0(若本期損益為零則相同),金額有可能不同。", "備抵損失(資產抵銷科目)、代收款(負債)、應收租金(資產),都是實帳戶,結帳後餘額不變。", "因此答案選 A。"], "pitfalls": "「有可能不同」是找結帳時會被結清的帳戶;資產、負債項目都不會變。", "distractors": {"B": "備抵損失是資產備抵科目,結帳不影響其餘額。", "C": "代收款是負債,結帳後餘額不變。", "D": "應收租金是資產,結帳後餘額不變。"}}, "check": "概念題,依官方詳解確認。", "verified": true, "note": ""}, {"id": "112-2-A-15", "exam": "112-2", "paper": "A", "q": 15, "unit": "九、財務報表", "topic": "利潤與銷貨淨額推算", "stem": "艾麗公司 111 年度銷貨淨額$3,000,000,銷貨成本$1,800,000,營業費用$500,000,利息費用$200,000,所得稅率為 20%。該公司執行長對 111 年營運成果不滿意,故提出淨利提升計畫,期望 112 年度稅後淨利增加為$840,000,且在營業費用、利息費用及所得稅率皆維持不變情況下,營業毛利率亦須維持 40%,試問艾麗公司在 112 年度須產生多少銷貨淨額才能達到執行長的目標?", "options": ["$4,320,000", "$4,375,000", "$5,000,000", "$5,625,000"], "answer": "B", "figure": null, "official": "由稅後淨利倒推:稅前淨利→營業利益→營業毛利→銷貨淨額(毛利率 40%)。", "explain": {"concept": "從底下一路往上加回去(稅前=稅後÷(1−稅率);再加利息、營業費用得毛利;最後除以毛利率)。", "steps": ["「增加為 $840,000」就是 112 年稅後淨利目標 = $840,000。", "稅前淨利 = $840,000 ÷ (1 − 20%) = $1,050,000。", "營業利益 = 稅前淨利 + 利息費用 = $1,050,000 + $200,000 = $1,250,000。", "營業毛利 = 營業利益 + 營業費用 = $1,250,000 + $500,000 = $1,750,000。", "毛利率 40%:銷貨淨額 = $1,750,000 ÷ 40% = $4,375,000,答案選 B。"], "pitfalls": "不要把 $840,000 當成「再增加」的金額;題目是「增加為」。", "distractors": {"D": "把 $840,000 當成比 111 年的淨利 $400,000「再增加 $840,000」(目標淨利 $1,240,000),算出 $5,625,000。"}}, "check": "python:840,000/0.8+200,000+500,000=1,750,000;/0.4=4,375,000,與官方 B 相符。", "verified": true, "note": ""}, {"id": "112-2-A-16", "exam": "112-2", "paper": "A", "q": 16, "unit": "九、財務報表", "topic": "流動比率與速動比率", "stem": "庭昇公司之流動比率為 3,流動資產中之非速動資產僅有存貨及預付費用兩項,而存貨占流動資產之 20%,預付費用占存貨之二分之一,流動負債為$100,000,則速動比率為何?", "options": ["0.8", "0.9", "2.1", "2.5"], "answer": "C", "figure": null, "official": "速動資產 = 流動資產 − 存貨 − 預付費用;速動比率 = 速動資產 ÷ 流動負債。", "explain": {"concept": "先由流動比率求流動資產,再分出存貨與預付費用,剩下的就是速動資產。", "steps": ["流動資產 = 流動比率 × 流動負債 = 3 × $100,000 = $300,000。", "存貨 = $300,000 × 20% = $60,000。", "預付費用 = $60,000 × 1/2 = $30,000。", "速動資產 = $300,000 − $60,000 − $30,000 = $210,000。", "速動比率 = $210,000 ÷ $100,000 = 2.1,答案選 C。"], "pitfalls": "速動資產要同時扣掉存貨與預付費用。", "distractors": {"B": "$90,000 ÷ $100,000 = 0.9,把非速動資產($90,000)當速動資產。", "D": "只扣預付費用或沒扣完整,導致速動資產偏高。"}}, "check": "python:3*100,000=300,000;速動=300,000−60,000−30,000=210,000;比率 2.1,與官方 C 相符。", "verified": true, "note": ""}, {"id": "112-2-A-17", "exam": "112-2", "paper": "A", "q": 17, "unit": "十、加值型營業稅會計實務", "topic": "加值型營業稅概念", "stem": "有關加值型營業稅之敘述,下列何者正確?", "options": ["加值型營業稅稅率分為一般營業人、外銷營業人及小規模營業人等三大類", "加值型營業稅是依據銷售總額計算營業稅", "經營免稅事業者,於購進貨物及勞務時免課營業稅", "加值型營業稅實際上稅額負擔者為消費者"], "answer": "D", "figure": null, "official": "加值型營業稅是對每一銷售階段的「加值額」課稅,稅負最終由消費者負擔。", "explain": {"concept": "區分:營業人分類、課稅基礎、免稅業者進項稅額處理。", "steps": ["A:稅率分為一般稅率(5%)、零稅率、免稅;營業人分為一般、外銷、免稅營業人等,說法不正確。", "B:是依每一銷售階段的「加值額」計算(銷項稅額 − 進項稅額),不是依銷售總額。", "C:免稅業者購進貨物及勞務時仍須負擔進項稅額,只是把進項稅額列入資產或費用,不能扣抵或退稅。", "D:營業人轉嫁稅額給下游,最後由消費者負擔,正確。"], "pitfalls": "免稅事業買東西仍然要付營業稅,只是不能扣抵。", "distractors": {"A": "營業人分類與稅率不是這三類(分類應含免稅營業人)。", "B": "課稅基礎是加值額,不是銷售總額。", "C": "免稅業者購進時仍要負擔進項稅額,只是不能扣抵或退稅。"}}, "check": "概念題,依官方詳解確認。", "verified": true, "note": ""}, {"id": "112-2-A-18", "exam": "112-2", "paper": "A", "q": 18, "unit": "十、加值型營業稅會計實務", "topic": "營業稅結算分錄", "stem": "高雄公司為加值型營業稅一般營業人,7、8 月發生交易事項如下(以下金額均未含營業稅):①進貨$900,000、②支付外籍經理房屋租金$18,000、③購入載貨用卡車$400,000、④支付主管座車修理費$80,000、⑤購買文具$7,200、⑥支付交際費$5,000、⑦內銷$700,000、⑧外銷$100,000,上期留抵稅額尚有$16,000,請問 8 月底結算分錄中之留抵稅額項目應為何?", "options": ["借記$25,360", "借記$25,000", "借記$10,260", "借記$9,360"], "answer": "D", "figure": null, "official": "結算分錄:借 銷項稅額、應收退稅款、留抵稅額;貸 進項稅額。留抵稅額 = 累計留抵稅額 − 上期留抵稅額(調整數)。", "explain": {"concept": "先算本期進項、銷項,再算溢付稅額,退稅限額(零稅率銷售 × 5%),剩下的是留抵。", "steps": ["上期留抵稅額 $16,000。", "本期進項稅額 = ($900,000 + $400,000 + $80,000 + $7,200) × 5% = $45,000 + $20,000 + $4,000 + $360 = $69,360(官方計算方式)。", "本期銷項稅額 = 內銷 $700,000 × 5% = $35,000(外銷零稅率,銷項為 0)。", "本期溢付稅額 = ($16,000 + $69,360) − $35,000 = $50,360。", "應退稅限額:官方以 ($400,000〔購入固定資產〕+ $100,000〔外銷零稅率銷售額〕)× 5% = $25,000 計算;應退稅額取「溢付稅額」與「退稅限額」兩者較小者,即 $25,000。", "累計留抵稅額 = $50,360 − $25,000 = $25,360。", "本期留抵稅額項目 = $25,360 − 上期留抵 $16,000 = $9,360(借記),答案選 D。", "結算分錄:借 銷項稅額 $35,000、應收退稅款 $25,000、留抵稅額 $9,360;貸 進項稅額 $69,360。"], "pitfalls": "結算分錄的「留抵稅額」是新增的數字(累計留抵 − 上期留抵),不是累計留抵本身。", "distractors": {"A": "$25,360 是累計留抵稅額,忘了減上期留抵 $16,000。", "B": "$25,000 是應退稅額,不是留抵稅額。"}}, "check": "python:進項 1,387,200×5%=69,360;溢付 85,360−35,000=50,360;退稅限額 25,000;留抵 25,360;調整 9,360,與官方 D 相符。", "verified": true, "note": "官方把「主管座車修理費」進項稅額也列入扣抵(依官方計算才得到選項),實務上乘人小汽車進項不得扣抵;答案照官方。"}, {"id": "112-2-A-19", "exam": "112-2", "paper": "A", "q": 19, "unit": "十一、現金及內部控制", "topic": "現金及約當現金", "stem": "奕承公司 111 年底部分財務資料如下:庫存現金$50,000、員工借條$15,000、保付支票$32,000、郵票$850、擴充廠房基金$300,000、找零金$2,000、銀行本票$60,000、90 天期定期存款$40,000、銀行支票存款$80,000、取得一個月後到期國庫券$9,000、活期存款$35,000、客戶支票存款不足退票$27,000、三個月到期之遠期支票$48,000。則該公司 111 年底現金及約當現金金額為何?", "options": ["$356,000", "$324,000", "$308,000", "$276,000"], "answer": "C", "figure": null, "official": "現金包括:庫存現金、銀行存款(活期、支票存款)、銀行本票、保付支票、找零金等可隨時支用者;約當現金為三個月內到期的短期投資。員工借條、郵票、基金、存款不足退票、遠期支票都不是。", "explain": {"concept": "逐項判斷是否「可立即使用」或「三個月內到期、風險極低」。", "steps": ["列入:庫存現金 $50,000、保付支票 $32,000、找零金 $2,000、銀行本票 $60,000、90 天定期存款 $40,000(約當現金)、銀行支票存款 $80,000、一個月後到期國庫券 $9,000(約當現金)、活期存款 $35,000。", "不列入:員工借條 $15,000(應收款)、郵票 $850(用品或費用)、擴充廠房基金 $300,000(基金)、存款不足退票 $27,000(應收款)、三個月到期之遠期支票 $48,000(應收票據)。", "加總:$50,000 + $32,000 + $2,000 + $60,000 + $40,000 + $80,000 + $9,000 + $35,000 = $308,000,答案選 C。"], "pitfalls": "遠期支票、存款不足退票、員工借條都不算現金。", "distractors": {"A": "$308,000 + $48,000 = $356,000,把三個月到期遠期支票也算進來。", "D": "$308,000 − $32,000 = $276,000,漏掉保付支票。"}}, "check": "python:50+32+2+60+40+80+9+35=308(千元),與官方 C 相符。", "verified": true, "note": ""}, {"id": "112-2-A-20", "exam": "112-2", "paper": "A", "q": 20, "unit": "十一、現金及內部控制", "topic": "零用金撥補與調整額度", "stem": "南投公司設置定額零用金$2,500,今日報銷憑證費用共計$1,800 並補充零用金,盤點手存零用金尚有$520,並同時將定額零用金減設至$2,000,則撥補零用金分錄應貸記為何?", "options": ["貸:現金$1,480、零用金$500", "貸:現金$700、現金短溢$180", "貸:現金$1,820、現金短溢$180", "貸:現金$200、零用金$500"], "answer": "A", "figure": null, "official": "撥補時:借 費用(依憑證)、借 現金短溢(短少);貸 現金(實際撥補)、貸 零用金(減設額度)。", "explain": {"concept": "先求短少數,再求實際要撥補的現金。", "steps": ["原定額 $2,500,憑證費用 $1,800,應剩 $2,500 − $1,800 = $700,實際只剩 $520,所以短少 $180(借:現金短溢)。", "減設額度 $2,500 − $2,000 = $500,貸:零用金 $500。", "需付現金 = $2,500 − $520 − $500 = $1,480(補到新額度 $2,000:$2,000 − $520 = $1,480)。", "分錄:借 各項費用 $1,800、借 現金短溢 $180;貸 現金 $1,480、貸 零用金 $500。答案選 A。"], "pitfalls": "減設額度時,要同時貸記零用金,現金撥補數則是「新額度 − 手存現金」。", "distractors": {}}, "check": "python:2,500−520−500=1,480;現金短溢=2,500−520−1,800=180(短少);借 1,800+180=1,980=貸 1,480+500 ✓,與官方 A 相符。", "verified": true, "note": ""}, {"id": "112-2-A-21", "exam": "112-2", "paper": "A", "q": 21, "unit": "十一、現金及內部控制", "topic": "銀行存款調節表", "stem": "花蓮公司欲編製 111 年 5 月 31 日銀行往來調節表,發現 5 月 31 日銀行對帳單餘額為公司帳面餘額之三分之二、在途存款$40,000、銀行代扣手續費$800、未兌現支票$5,000、銀行代付水費$1,200,銀行已完成收款之託收票據$30,000,請問該公司 5 月 31 日調節前銀行存款帳面餘額及銀行對帳單餘額分別為何?", "options": ["$21,600 及$14,400", "$21,000 及$14,000", "$75,000 及$50,000", "$24,000 及$16,000"], "answer": "B", "figure": null, "official": "雙欄式調節表:調節後兩邊餘額相等。銀行方:+在途存款 −未兌現支票;公司方:+託收票據 −手續費 −代付水費。", "explain": {"concept": "設變數、列出兩邊調整項,令調節後餘額相等。", "steps": ["設公司帳面餘額為 3X,銀行對帳單餘額為 2X。", "公司帳面調整:3X + $30,000(銀行已託收)− $800(手續費)− $1,200(水費)= 3X + $28,000。", "銀行對帳單調整:2X + $40,000(在途存款)− $5,000(未兌現支票)= 2X + $35,000。", "調節後相等:3X + $28,000 = 2X + $35,000,X = $7,000。", "公司帳面 = 3 × $7,000 = $21,000;銀行對帳單 = 2 × $7,000 = $14,000,答案選 B。"], "pitfalls": "在途存款、未兌現支票調「銀行方」;託收、手續費、代付費用調「公司帳面」。", "distractors": {"A": "以 X = $7,200 計算,可能是調整項目加減錯一項。", "D": "X = $8,000,可能是調整項目方向弄錯。"}}, "check": "python:3X+30,000−800−1,200=2X+40,000−5,000 → X=7,000;21,000/14,000,與官方 B 相符。", "verified": true, "note": ""}, {"id": "112-2-A-22", "exam": "112-2", "paper": "A", "q": 22, "unit": "四、分錄與日記簿", "topic": "銷貨運費處理", "stem": "下列銷貨條件之敘述哪些正確?\n①銷售條件為起運點交貨,若賣方以現金支付運費,賣方應借記:運費\n②銷售條件為目的地交貨,若賣方以現金支付運費,買方應借記:應付帳款\n③銷售條件為起運點交貨,若賣方以現金支付運費,賣方應借記:應收帳款\n④銷售條件為目的地交貨,若買方以現金支付運費,買方應借記:進貨費用", "options": ["僅①④", "僅②③", "僅①②③", "僅①②③④"], "answer": "B", "figure": null, "official": "起運點交貨:運費由買方負擔;目的地交貨:運費由賣方負擔。代墊運費要記為應收帳款(或應付帳款)。", "explain": {"concept": "先判斷運費歸誰負擔,再看誰代墊。", "steps": ["先判斷運費歸誰負擔:起運點交貨,運費由買方負擔;目的地交貨,運費由賣方負擔。", "③ 起運點交貨,賣方先代墊現金運費,是替買方墊款,賣方借 應收帳款,③ 正確;① 說借運費,錯誤。", "官方詳解把 ① 的正確版本寫成「賣方應借記:應收帳款」、把 ④ 的正確版本寫成「買方應借記:應付帳款」,表示 ①④ 為錯誤敘述;④ 說借進貨費用,錯誤。", "② 依官方視為正確敘述(目的地交貨,運費原屬賣方負擔,與運費相關的帳款處理記為應付帳款),因此正確的是 ②③,答案選 B。"], "pitfalls": "代墊對方負擔的運費,不是自己的費用,要記成應收或應付(賣方代墊=應收帳款,買方代墊=應付帳款減少)。", "distractors": {"A": "以為①④正確,把運費都借記成費用。", "C": "把①也算進來,忘了起運點交貨賣方代墊運費是借應收帳款。", "D": "全選,①④錯。"}}, "check": "①③④我自行推演:①錯、③對、④錯,與官方一致;②的對錯無法獨立確認,故 verified 設 false。", "verified": false, "note": "② 的敘述在會計處理上有疑義(目的地交貨,賣方付運費是賣方自己的運費,買方不需分錄);另官方詳解文字寫「①④正確」,與答案表 B(②③)矛盾,疑似詳解文字誤植;答案表 B 與我依會計處理推演的結果一致,答案照答案表。"}, {"id": "112-2-A-23", "exam": "112-2", "paper": "A", "q": 23, "unit": "十二、應收款項", "topic": "帳齡分析法與備抵損失", "stem": "好食雞排食品公司在 2020 年受全球新冠疫情影響,經常參與「先享食月付款」活動之部分公司團體,竟發生呆帳之現象,該公司採準備矩陣法提列備抵損失,2020 年底調整前備抵損失貸餘$1,300,會計人員並於該年度分析應收帳款帳齡如下,試問 2020 年底提列預期信用減損損失為何?\n\n| 帳款期限 | 未逾期 | 逾期1~30天 | 逾期31~60天 | 逾期61~90天 | 逾期90天以上 |\n|---|---|---|---|---|---|\n| 應收帳款餘額 | $70,000 | $30,000 | $10,000 | $5,000 | $2,000 |\n| 損失率 | 0.5% | 1% | 3% | 10% | 20% |", "options": ["$1,850", "$1,720", "$550", "$250"], "answer": "C", "figure": null, "official": "準備矩陣法:各帳齡餘額 × 損失率 = 期末應有備抵損失;再與調整前餘額比較,差額為本期應提列(或迴轉)數。", "explain": {"concept": "先算「期末應有」備抵損失,再減掉現有的貸餘。", "steps": ["期末應有備抵損失 = $70,000 × 0.5% + $30,000 × 1% + $10,000 × 3% + $5,000 × 10% + $2,000 × 20%。", "= $350 + $300 + $300 + $500 + $400 = $1,850。", "調整前備抵損失已有貸餘 $1,300,所以本期應再提列 = $1,850 − $1,300 = $550。", "分錄:借 預期信用減損損失 $550、貸 備抵損失 $550,答案選 C。"], "pitfalls": "直接把 $1,850 當費用,忘了先扣原有餘額。", "distractors": {"A": "$1,850 是期末應有的備抵損失,沒有扣掉調整前貸餘 $1,300。"}}, "check": "python:350+300+300+500+400=1,850;−1,300=550,與官方 C 相符。", "verified": true, "note": ""}, {"id": "112-2-A-24", "exam": "112-2", "paper": "A", "q": 24, "unit": "十二、應收款項", "topic": "應收票據貼現", "stem": "好食雞排食品公司因資金需求,2021 年 4 月 1 日將顧客交來之一年到期,票面利率 9%,面額$150,000 之票據,於 11/1 持票據至銀行貼現,當天認列應收票據貼現負債折價$2,550,請問銀行貼現率為何?", "options": ["15%", "14%", "12%", "10%"], "answer": "C", "figure": null, "official": "貼現息 = 到期值 × 貼現率 × 貼現期間;貼現期間=到期日−貼現日(5 個月)。", "explain": {"concept": "求到期值、貼現息(由折價算出),再反推貼現率。", "steps": ["到期值 = 面額 + 票據利息 = $150,000 + $150,000 × 9% × 12/12 = $163,500。", "持有期間(4/1 到 11/1,共 7 個月)利息收入 = $150,000 × 9% × 7/12 = $7,875,所以貼現日票據帳面金額 = $150,000 + $7,875 = $157,875。", "貼現值 = 帳面金額 − 折價 = $157,875 − $2,550 = $155,325。", "貼現息 = 到期值 − 貼現值 = $163,500 − $155,325 = $8,175。", "貼現期間 = 12 − 7 = 5 個月。$8,175 = $163,500 × 貼現率 × 5/12,貼現率 = 12%,答案選 C。"], "pitfalls": "貼現息是用「到期值」乘貼現率,不是面額;期間是「貼現日到到期日」。", "distractors": {"A": "貼現期間誤用 4 個月:$8,175 ÷ ($163,500 × 4/12) = 15%。", "D": "貼現期間誤用 6 個月:$8,175 ÷ ($163,500 × 6/12) = 10%。"}}, "check": "python:到期值 163,500;貼現值=157,875−2,550=155,325;貼現息 8,175;÷(163,500×5/12)=12%,與官方 C 相符。", "verified": true, "note": ""}, {"id": "112-3-A-01", "exam": "112-3", "paper": "A", "q": 1, "unit": "一、會計基本概念", "topic": "會計準則與財報", "stem": "下列敘述何者正確?", "options": ["我國所有公司之帳務處理須採行金管會認可並發布之國際財務報導準則", "財務會計的主要功能是提供財務報導給外部使用者作為決策之參考", "獨資商店平時記載的會計帳冊,應優先適用一般公認會計原則", "臺灣自來水公司為公營事業,故應採用非營利會計"], "answer": "B", "figure": null, "official": "(A)公開發行公司才適用金管會認可並發布之IFRS,非公開發行公司採企業會計準則公報。(C)獨資應優先適用「商業會計法」。(D)臺灣自來水公司為公用事業,應採營利會計。", "explain": {"concept": "考會計的功能與各種組織適用的會計準則/法規。", "steps": ["財務會計的對象是外部使用者(投資人、債權人、政府等),所以主要功能就是提供財務報導讓他們做決策,B 正確。", "A:只有「公開發行公司」才一定要採用金管會認可的國際財務報導準則(IFRSs),非公開發行公司採「企業會計準則公報」,所以『所有公司』是錯的。", "C:獨資、合夥這類小型商號,記帳要優先遵守「商業會計法」,不是一般公認會計原則。", "D:自來水公司雖是公營事業,但是會收費營利,屬公用事業,採營利會計。"], "pitfalls": "「所有」「一律」這類絕對字眼常是陷阱;另外要分清楚商業會計法(獨資/合夥優先)與準則(公司)。", "distractors": {"A": "忽略『公開發行』的限制。", "C": "把商業會計法與一般公認會計原則的適用順序搞混。", "D": "以為公營事業就一定是非營利。"}}, "check": "概念題,依官方詳解與商業會計法常識確認。", "verified": true, "note": ""}, {"id": "112-3-A-02", "exam": "112-3", "paper": "A", "q": 2, "unit": "十七、權益", "topic": "獨資業主往來與資本", "stem": "甲商店 X2 年年初「業主往來」與「業主資本」分別貸餘$3,000、$50,000,X2 年中業主曾經提取現金$15,000 自用,且業主曾代商店支付水電費$3,000 及租金$25,000,另 X2 年度業主辦理資本額增資變更登記$28,000、X2 年度收益$55,000、本期淨損$17,000。請問下列敘述何者正確?", "options": ["X2 年底結帳後「業主往來」貸餘$10,000", "X3 年初「業主資本」貸餘$78,000", "X2 年度「費損」為$38,000", "X2 年底「權益總額」貸餘$56,000"], "answer": "B", "figure": null, "official": "業主往來貸3,000+代付28,000−提取15,000−淨損17,000=借餘$1,000;X3年初業主資本=50,000+28,000=$78,000;費損=55,000+17,000=$72,000;權益總額=78,000−1,000=$77,000。", "explain": {"concept": "獨資的「業主往來」用來處理業主與商店之間的往來(提取、代付、結轉損益),期末要和「業主資本」一起看權益。", "steps": ["先算業主往來:期初貸餘 $3,000;業主代商店付水電 $3,000、租金 $25,000,共 $28,000,商店欠業主,記貸方。→ 貸方合計 3,000+28,000=$31,000。", "借方:業主提取 $15,000(減少權益);本期淨損 $17,000 結轉到業主往來(虧損讓權益減少),借方合計 15,000+17,000=$32,000。", "結帳後業主往來 = 31,000 − 32,000 = 借餘 $1,000。A 說貸餘 $10,000 不對。", "業主資本:年初 $50,000 + 增資 $28,000 = $78,000(貸餘),這就是 X3 年初的業主資本,B 正確。", "費損:淨損 = 收益 − 費損 → 費損 = 55,000 + 17,000 = $72,000,C 的 $38,000 不對。", "權益總額 = 業主資本 78,000 − 業主往來借餘 1,000 = $77,000,D 的 $56,000 不對。"], "pitfalls": "增資只動「業主資本」;提取與淨損動「業主往來」。別把業主往來的借餘直接當成權益增加。", "distractors": {"A": "可能把代付金額或淨損方向弄錯,算成貸餘。", "C": "把費損誤算成 55,000−17,000=38,000(淨損應是費損大於收益)。", "D": "算成 50,000+28,000−17,000−... 之類,漏掉年初業主往來或代付金額。"}}, "check": "python 驗算:業主往來貸31,000、借32,000,借餘1,000;資本78,000;費損72,000;權益77,000,與官方一致。", "verified": true, "note": ""}, {"id": "112-3-A-03", "exam": "112-3", "paper": "A", "q": 3, "unit": "二、會計循環及會計帳簿", "topic": "傳票與交易類型", "stem": "下列敘述何者正確?", "options": ["購入商品,採定期盤存制,立即簽發即期支票支付,是為現金交易", "購入機器設備,半數簽發本票支付,半數暫欠,是為混合交易", "賒購商品一批,採定期盤存制,以淨額法入帳,在複式傳票三分法下,應編製現金支出傳票", "賒銷商品一批,目的地交貨,商品已運出但尚未交貨,仍為賣方存貨"], "answer": "D", "figure": null, "official": "(A)借:進貨/貸:銀行存款,是為轉帳交易。(B)借:機器設備/貸:應付票據、應付設備款,是為轉帳交易。(C)借:進貨/貸:應付帳款,應編製轉帳傳票。", "explain": {"concept": "分辨現金交易、轉帳交易、混合交易,以及目的地交貨時存貨所有權。", "steps": ["三分法傳票:分錄中有「現金」收入→收入傳票;有「現金」支出→支出傳票;完全不涉及現金→轉帳傳票。", "A:簽發的是『即期支票』,記帳時貸記銀行存款(支票存款),不是庫存現金,所以題目的記帳型態屬轉帳交易,A 錯。", "B:本票是應付票據、暫欠是應付設備款,整筆都沒有現金流入流出,是全部轉帳交易,不是混合交易,B 錯。", "C:賒購貸記應付帳款,沒有現金,應編「轉帳傳票」,不是現金支出傳票,C 錯。", "D:目的地交貨,貨物到達買方目的地才轉移所有權,運送途中仍屬賣方存貨,D 正確。"], "pitfalls": "傳票的『現金』是指實際的現金收付(含視同現金的項目另有規定),題目這種支票、本票、賒帳都要先檢查有沒有現金科目。", "distractors": {"A": "以為支票=現金,忽略記帳科目是銀行存款。", "B": "以為一半一半就是混合交易,其實混合交易必須同時有現金與非現金項目。", "C": "以為購貨就一定付現金。"}}, "check": "概念題,依官方詳解與會計常識確認。", "verified": true, "note": "單元歸類可能有爭議(二 或 十三)。"}, {"id": "112-3-A-04", "exam": "112-3", "paper": "A", "q": 4, "unit": "六、試算與試算表", "topic": "試算表錯誤更正", "stem": "乙商店查核餘額式試算表時發現下列錯誤:\n①賒購運輸設備$80,000,分錄誤記為現購辦公設備$8,000\n②以現金支付利息$5,000,分錄誤記為現收利息$5,000\n③過帳時誤將「借記銷貨退回$2,000」過入相反方向(過帳前,銷貨退回餘額$4,000)\n試算表更正前貸方餘額為$660,000。請問下列敘述何者正確?", "options": ["試算表更正後正確的借方餘額合計為$739,000", "試算表更正後正確的貸方餘額合計為$745,000", "試算表更正前的借方餘額合計為$656,000", "更正前的「收益總額」多計$1,000"], "answer": "C", "figure": null, "official": "①②③更正後借貸各為$735,000,更正前借方$656,000;收益多計=利息收入多計5,000+銷貨退回少計4,000=$9,000。", "explain": {"concept": "用「更正分錄」逐項調整借貸餘額,更正後借貸必定相等,可反推更正前的借方餘額。", "steps": ["①正確分錄:借 運輸設備80,000、貸 應付設備款80,000;誤記的是借 辦公設備8,000、貸 現金8,000。更正:借 運輸設備80,000、現金8,000;貸 應付設備款80,000、辦公設備8,000。借方餘額淨增 80,000,貸方餘額增 80,000。", "②誤記:借 現金5,000、貸 利息收入5,000。正確:借 利息費用5,000、貸 現金5,000。更正:借 利息收入5,000、利息費用5,000;貸 現金10,000。借方餘額 +5,000−10,000=−5,000;貸方餘額 −5,000(利息收入減少)。", "③銷貨退回應借記2,000卻貸記2,000:過帳後餘額 4,000−2,000=2,000,正確應為 4,000+2,000=6,000,借方餘額需 +4,000。", "貸方:660,000+80,000−5,000=$735,000;借方更正後也要是 $735,000。", "更正前借方 = 735,000 −80,000 +5,000 −4,000 = $656,000,C 正確。", "D:收益多計=利息收入多計5,000+銷貨退回少計造成銷貨淨額多計4,000=$9,000,不是1,000。"], "pitfalls": "餘額式試算表要看「餘額」的增減,不是看分錄金額;③過帳方向錯誤要調整 2 倍金額(2,000×2=4,000)。", "distractors": {"A": "更正後借方不是 739,000;可能把借方多加了 4,000 或漏算②。", "B": "更正後貸方應為 735,000,745,000 不合理(可能漏減②的5,000並多加)。", "D": "只算了某一項的影響,沒有把②的 5,000 與③的 4,000 合計。"}}, "check": "python 逐項調整:更正前借656,000/貸660,000 → 更正後借貸皆735,000,與官方一致。", "verified": true, "note": ""}, {"id": "112-3-A-05", "exam": "112-3", "paper": "A", "q": 5, "unit": "七、調整", "topic": "調整錯誤對淨利影響", "stem": "丙公司 01 年底稅前淨利為$480,000,會計人員在查帳時發現帳務處理有兩項錯誤:①期末存貨盤點時多計$3,000、②漏作應收利息$15,000 之調整,則更正後之正確稅前淨利金額應為多少?", "options": ["$462,000", "$465,000", "$492,000", "$498,000"], "answer": "C", "figure": null, "official": "①期末存貨多計3,000→銷貨成本少計→淨利多計3,000;②漏列應收利息→利息收入少計→淨利少計15,000。正確淨利=480,000−3,000+15,000=$492,000。", "explain": {"concept": "判斷錯誤會讓淨利多計或少計,再用「正確淨利=原淨利±錯誤影響」。", "steps": ["①期末存貨多計$3,000:銷貨成本 = 期初存貨 + 進貨 − 期末存貨,期末存貨多算,銷貨成本就少算,淨利多算 $3,000。更正要減 3,000。", "②漏作應收利息調整:應借 應收利息、貸 利息收入 $15,000 沒做,收益少記,淨利少算 $15,000。更正要加 15,000。", "正確稅前淨利 = 480,000 − 3,000 + 15,000 = $492,000。"], "pitfalls": "要分別判斷每個錯誤是「多計」還是「少計」,方向相反的要抵銷。", "distractors": {"A": "兩項都當成多計,算成 480,000−3,000−15,000。", "B": "只處理②方向錯誤或漏了①,算成 480,000−15,000。", "D": "兩項都當成少計,算成 480,000+3,000+15,000。"}}, "check": "python:480,000−3,000+15,000=492,000,與官方一致。", "verified": true, "note": ""}, {"id": "112-3-A-06", "exam": "112-3", "paper": "A", "q": 6, "unit": "七、調整", "topic": "預付租金推算支付日", "stem": "丁公司每月底皆會進行會計事項之調整,公司在 X1 年的某月初一次支付兩年的廠房租金,在 X2 年 3 月 31 日作調整分錄後,預付租金餘額為$255,000,租金支出餘額為$45,000。請問丁公司在 X1 年的哪一天支付此筆廠房租金?", "options": ["3 月 1 日", "6 月 1 日", "9 月 1 日", "12 月 1 日"], "answer": "C", "figure": null, "official": "每月租金=45,000÷3個月=15,000;尚餘月數=255,000÷15,000=17個月;X1/12/31時尚餘3+17=20個月,已實現4個月,故X1/9/1支付。", "explain": {"concept": "預付費用按月攤銷:先求每月金額,再由剩餘月數倒推已過期間。", "steps": ["X2 年 3 月 31 日租金支出餘額 $45,000,代表 X2 年 1~3 月共 3 個月已認列,每月租金 = 45,000 ÷ 3 = $15,000。", "預付租金 $255,000 是還沒到期的部分,剩餘月數 = 255,000 ÷ 15,000 = 17 個月。", "整筆租金是兩年,共 24 個月(總額 360,000)。扣掉 X2 年已用的 3 個月和尚餘 17 個月,X1 年已用月數 = 24 − 3 − 17 = 4 個月。", "X1 年已用 4 個月,到 12 月底,表示是從 9 月初開始(9、10、11、12 月)→ 9 月 1 日支付。"], "pitfalls": "別忘了 X1 年底也要算進去;X1 底餘 20 個月、已過 4 個月。", "distractors": {"A": "若 3/1 付款,到 X1 年底已過 10 個月,不符。", "B": "6/1 付款,X1 已過 7 個月,不符。", "D": "12/1 付款,X1 只過 1 個月,不符。"}}, "check": "python:(255,000+45,000)÷15,000=20個月,24−20=4個月,與官方一致。", "verified": true, "note": ""}, {"id": "112-3-A-07", "exam": "112-3", "paper": "A", "q": 7, "unit": "八、結帳", "topic": "結帳程序與結帳後試算表", "stem": "有關結帳程序之敘述,下列何者錯誤?", "options": ["結帳後,「累計折舊」餘額為零", "預期信用減損損失不會出現在結帳後試算表", "結帳後權益=結帳前權益+(收益−費損)", "結帳時需將虛帳戶結清,且可得出本期損益之金額"], "answer": "A", "figure": null, "official": "累計折舊屬資產項目(資產減項),為實帳戶,期末不需結清。", "explain": {"concept": "分辨虛帳戶(損益類,結帳要結清)與實帳戶(資產、負債、權益,餘額結轉下期)。", "steps": ["結帳的對象只有「虛帳戶」:收益、費損、股利(或業主提取)等,把它們結到本期損益再結到權益。", "A:累計折舊是資產的減項,屬實帳戶,餘額要帶到下期,所以結帳後不會是零。這就是錯誤的敘述。", "B:預期信用減損損失是費損(虛帳戶),結帳時已結清,結帳後試算表看不到,正確。", "C:收益−費損=本期損益,加到權益,正確。", "D:虛帳戶結清的同時就算出本期損益,正確。"], "pitfalls": "看到「累計」字眼別以為是虛帳戶;累計折舊、備抵損失都是實帳戶。", "distractors": {"B": "(此為正確敘述)有人誤以為與損失備抵有關而選它。", "C": "(此為正確敘述)", "D": "(此為正確敘述)"}}, "check": "概念題,依官方詳解與會計常識確認。", "verified": true, "note": ""}, {"id": "112-3-A-08", "exam": "112-3", "paper": "A", "q": 8, "unit": "九、財務報表", "topic": "財務報表編製與流動比率", "stem": "有關財務報表之敘述,下列何者錯誤?", "options": ["企業可以根據總分類帳餘額編製財報報表", "財務報表除了主要報表外,應包含其附表及附註揭露", "投資人可從資產負債表瞭解企業之財務狀況", "以即期支票償還應付帳款,會使流動比率下降"], "answer": "D", "figure": null, "official": "償還應付帳款會使流動資產與流動負債同額減少,流動比率可能下降、不變或上升,視原比率而定。", "explain": {"concept": "流動比率=流動資產÷流動負債;分子分母同減同一金額,結果要看原比率大小。", "steps": ["以即期支票償還應付帳款:借 應付帳款(流動負債減少)、貸 銀行存款(流動資產減少),兩者減少金額相同。", "若原流動比率 <1,分子與分母同減,比率會變得更小 → 下降。", "若原流動比率 =1,同減後仍然相等 → 不變。", "若原流動比率 >1,同減後比率會變大 → 上升。", "所以題目說『會使流動比率下降』不一定,是錯誤敘述,答案 D。A、B、C 都是財務報表的基本常識。"], "pitfalls": "同額增減流動資產與流動負債,不能直接說比率升或降,要先看原本比率。", "distractors": {"A": "(此為正確敘述)", "B": "(此為正確敘述)", "C": "(此為正確敘述)"}}, "check": "概念題,舉例驗算:流動資產300、負債200(1.5)同減50→250/150=1.67 上升;若 100/200=0.5→50/150=0.33 下降,故不一定下降。", "verified": true, "note": ""}, {"id": "112-3-A-09", "exam": "112-3", "paper": "A", "q": 9, "unit": "十一、現金及內部控制", "topic": "定額零用金", "stem": "戊公司設置$4,000 之定額零用金,由專人保管並於每月底進行撥補。本月底專人撥補零用金時,發現手存現金尚餘$900,本月份與零用金有關之事項如下:\n①3 日 A 部門購買文具用品$2,300 及郵票$1,200,並取得收據兩張為證\n②11 日 公司將零用金之額度提高至$6,000,簽發支票將提高之款項交給零用金保管員\n③15 日 B 部門購買書報雜誌$1,000、支付銀行轉帳手續費$200,並取得收據\n④25 日 C 部門由零用金支應外租場地需負擔的水電費$200,並取得收據\n根據以上資料,下列敘述何者錯誤?", "options": ["本月所有交易只需記入零用金備忘錄,月底專人撥補零用金時再將分錄記入日記簿即可", "月底零用金撥補分錄中,會有借:現金短溢$200", "本月份與零用金相關之零星支出中,營業費用總金額共$4,700", "本月份與零用金相關之零星支出中,營業外支出總金額共$400"], "answer": "A", "figure": null, "official": "11日提高零用金額度需記分錄:借 零用金$2,000、貸 銀行存款$2,000,不能只記備忘錄。", "explain": {"concept": "定額零用金:設立、增減額度要有分錄,平常支出只記備忘錄,撥補時才入帳。", "steps": ["先分辨哪些事要入帳:設立零用金、調整額度(增或減)會影響「零用金」科目餘額,必須做分錄;平常的支出才只記備忘錄。", "A:11日額度由 $4,000 提高至 $6,000,要記 借:零用金 2,000、貸:銀行存款 2,000,所以不是『只記備忘錄』→ 錯誤。", "總支出:2,300+1,200+1,000+200+200=$4,900。撥補後額度6,000,手存現金應為 6,000−4,900=1,100,但實際只剩 900,短少 $200,所以撥補分錄借:現金短溢 $200,B 正確。", "營業費用 = 文具2,300 + 郵票1,200 + 書報雜誌1,000 + 水電200 = $4,700,C 正確(銀行轉帳手續費屬營業外)。", "營業外支出 = 轉帳手續費200 + 現金短溢200 = $400,D 正確。"], "pitfalls": "別忘了提高額度不是『支出』,而是補充基金,要用分錄處理;手續費與現金短溢屬營業外。", "distractors": {"B": "(此為正確敘述)", "C": "(此為正確敘述)", "D": "(此為正確敘述)"}}, "check": "python:營業費用4,700;短少6,000−900−4,900=200;營業外200+200=400,與官方一致。", "verified": true, "note": ""}, {"id": "112-3-A-10", "exam": "112-3", "paper": "A", "q": 10, "unit": "十一、現金及內部控制", "topic": "銀行存款調節表", "stem": "己公司 7 月底收到銀行對帳單顯示存款餘額為$15,000,與帳上銀行存款餘額$38,000 不符,經查發現差異原因如下:\n①公司 7 月底存入的即期支票$22,000,銀行尚未入帳\n②7 月底未兌現支票有三張:#703 支票$2,000、#706 保付支票$3,800、#707 支票$1,500\n③已存入客戶所開的支票$4,400,因存款不足遭銀行退票\n④銀行對帳單有一筆銀行轉帳的利息收入$350,公司帳上記錄與銀行結單紀錄金額不符,經查明後,雙方確定是公司的利息收入誤記\n⑤銀行手續費$400,公司尚未入帳\n根據上述資料,下列敘述何者正確?", "options": ["公司帳上誤記④之存款利息記錄為$300", "銀行存款調節表中公司項之調節總金額為−$4,500", "銀行存款調節表中銀行項之調節總金額為$14,700", "7 月底調節後正確的銀行存款餘額為$29,700"], "answer": "B", "figure": null, "official": "公司項:+300(利息少記)−4,400(退票)−400(手續費)=−4,500;銀行項:+22,000−3,500(#703、#707)=+18,500;正確餘額$33,500。", "explain": {"concept": "雙邊式調節表:公司帳餘額與銀行對帳單餘額各自調整到相同的正確餘額。", "steps": ["公司帳面餘額 $38,000 要調整的項目:③退票(客戶支票退回,公司存款減少)−4,400;⑤手續費(公司尚未入帳)−400;④利息:銀行收到 $350,公司少記,應補記。公司帳上實際記了 350−300=$50,所以要加 $300。", "公司項調節總額 = +300 − 4,400 − 400 = −$4,500,B 正確。正確餘額 = 38,000 − 4,500 = $33,500。", "銀行對帳單餘額 $15,000:①在途存款 +22,000;②未兌現支票 −(2,000+1,500)= −3,500(#706 是保付支票,銀行已先扣款,不列調節)。", "銀行項調節總額 = +22,000 − 3,500 = +$18,500,正確餘額 = 15,000+18,500 = $33,500,與公司側相同,驗證無誤。", "所以 A(公司記$300)、C(14,700)、D(29,700)都不對。"], "pitfalls": "保付支票已由銀行保證付款並先扣款,不算未兌現支票;別漏掉誤記的利息。", "distractors": {"A": "誤把『應調整金額 $300』當成公司帳上記錄的金額(實際記錄為 $50)。", "C": "可能把保付支票 #706 也當成未兌現(22,000−2,000−3,800−1,500=14,700)。", "D": "可能把利息、手續費方向弄反或漏項。"}}, "check": "python:公司側38,000+300−400−4,400=33,500;銀行側15,000+22,000−3,500=33,500,兩邊相等。", "verified": true, "note": ""}, {"id": "112-3-A-11", "exam": "112-3", "paper": "A", "q": 11, "unit": "十二、應收款項", "topic": "現金折扣與銷貨折讓/寄銷", "stem": "有關應收帳款的敘述,下列何者正確?", "options": ["某公司的付款條件為 4/10、1/30、n/50,若一年以 360 天計算,則此一條件所隱含的利率為 37.5%", "賒銷商品$5,000,退回$1,000,客戶結清貨款時給予折扣$100,則此一交易的銷貨折扣率為 2%", "委託他公司代為出售的商品,應於寄銷商品轉交他公司時認列應收帳款", "企業為了鼓勵顧客提早還款,會訂定商業折扣,在會計上稱為銷貨折扣"], "answer": "A", "figure": null, "official": "(A)$96×隱含利率×(50−10)/360=$4,隱含利率37.5%;(B)銷貨折扣率=$100÷($5,000−$1,000)=2.5%;(C)寄銷商品於「出售」時才認列應收帳款;(D)提早還款的折扣為「現金折扣」。", "explain": {"concept": "現金折扣隱含利率:(折扣率÷(1−折扣率))×(360÷(原付款期限−折扣期限))。", "steps": ["A:4/10,n/50 的意思:10 天內付款折 4%,否則 50 天內付全額。以 $100 為例,10 天內付 $96,晚 40 天(50−10)多付 $4。", "隱含利率 = (4÷96) × (360÷40) = 0.041667 × 9 = 0.375 = 37.5%,A 正確。", "B:折扣率 = 折扣 ÷ 銷貨淨額 = 100 ÷ (5,000−1,000) = 2.5%,不是 2%。", "C:寄銷品只是把商品放在代銷商處,所有權還是自己的,要等代銷商賣出時才認列銷貨與應收帳款。", "D:鼓勵提早付款的折扣叫「現金折扣」,會計上稱「銷貨折扣」是記在賣方帳上的科目名稱…注意題目說的是『商業折扣』才錯。商業折扣是依數量或牌價打折,不入帳。"], "pitfalls": "隱含利率的分母是「折扣後金額」(96),而不是 100;天數要用 50−10=40。", "distractors": {"B": "分母誤用 5,000 (100÷5,000=2%),忘了扣除退回。", "C": "把『轉交他人』當成已經賣出。", "D": "混淆商業折扣與現金折扣。"}}, "check": "python:4/96×360/40=0.375;100/4,000=2.5%,與官方一致。", "verified": true, "note": ""}, {"id": "112-3-A-12", "exam": "112-3", "paper": "A", "q": 12, "unit": "十二、應收款項", "topic": "備抵損失與預期信用減損損失", "stem": "已知魯夫公司 X1 年 1 月 1 日應收帳款餘額為$200,000、備抵損失餘額為$4,000,X1 年賒銷$560,000、帳款收現$240,000、實際發生帳款無法收回$20,000、收回已沖銷帳款$10,000,該公司每年估計之損失率相同。請問下列敘述何者錯誤?", "options": ["損失率為 2%", "X1 年底應收帳款帳面金額為$490,000", "X1 年底應提列預期信用減損損失$16,000", "X1 年底調整分錄中應「借記」備抵損失$16,000"], "answer": "D", "figure": null, "official": "調整分錄應借:預期信用減損損失$16,000、貸:備抵損失$16,000。", "explain": {"concept": "備抵損失法(應收帳款餘額百分比法):期末備抵損失目標餘額=應收帳款餘額×損失率。", "steps": ["損失率:期初 200,000 × 損失率 = 備抵損失 4,000 → 損失率 = 2%。A 正確。", "X1 年底應收帳款餘額 = 200,000 + 賒銷 560,000 − 收現 240,000 − 沖銷 20,000 + 收回沖銷 10,000 − (收回沖銷時再沖回)10,000 = $500,000。", "備抵損失期末應有餘額 = 500,000 × 2% = $10,000。", "調整前備抵損失餘額 = 4,000 − 沖銷 20,000 + 收回已沖銷 10,000 = 借餘 $6,000(因為壞帳超過備抵)。", "需補提 = 10,000 + 6,000 = $16,000,分錄:借 預期信用減損損失 16,000、貸 備抵損失 16,000。C 正確、D 錯誤。", "帳面金額 = 500,000 − 10,000 = $490,000,B 正確。"], "pitfalls": "注意收回已沖銷帳款要先轉回(借應收帳款、貸備抵損失)再入帳收現,最終應收帳款不變、備抵增加。", "distractors": {"A": "(此為正確敘述)", "B": "(此為正確敘述)", "C": "(此為正確敘述)"}}, "check": "python:應收500,000;調整前備抵借餘6,000;應補16,000;帳面490,000,與官方一致。", "verified": true, "note": ""}, {"id": "112-3-A-13", "exam": "112-3", "paper": "A", "q": 13, "unit": "十二、應收款項", "topic": "附息票據貼現", "stem": "娜美公司 3 月 1 日因銷貨取得一張附息 6%之票據一紙,面額$20,000,8 個月後到期。5 月 1 日因公司需要資金周轉,持此一票據向銀行貼現,貼現率為 10%。有關貼現日之敘述,下列何者錯誤?", "options": ["貼現日票據之帳面金額為$20,200", "貼現息共$1,040", "娜美公司取得貼現金額共$19,760", "應收票據貼現負債折價為$600"], "answer": "D", "figure": null, "official": "應收票據貼現負債折價=貼現日票據帳面金額−貼現金額=20,200−19,760=$440。", "explain": {"concept": "票據貼現:到期值→貼現息→貼現金額;折價=帳面價值−貼現金額。", "steps": ["到期值 = 20,000 ×(1 + 6% × 8/12)= $20,800。", "貼現日(5/1):持有 3/1~5/1 共 2 個月,距到期還剩 6 個月。貼現息 = 20,800 × 10% × 6/12 = $1,040,B 正確。", "貼現金額 = 20,800 − 1,040 = $19,760,C 正確。", "貼現日票據帳面金額 = 20,000 + 利息 20,000×6%×2/12(200) = $20,200,A 正確。", "應收票據貼現負債折價 = 20,200 − 19,760 = $440(借方科目),不是 $600,所以 D 錯誤。"], "pitfalls": "貼現息用『到期值』乘貼現率,不是用面額;貼現期間是『貼現日到到期日』。", "distractors": {"A": "(此為正確敘述)", "B": "(此為正確敘述)", "C": "(此為正確敘述)"}}, "check": "python:到期值20,800;貼現息1,040;貼現金額19,760;帳面20,200;折價440,與官方一致。", "verified": true, "note": ""}, {"id": "112-3-A-14", "exam": "112-3", "paper": "A", "q": 14, "unit": "十三、存貨", "topic": "存貨錯誤對財報之影響", "stem": "巴布公司對存貨採定期盤存制,該公司於期末對帳時發現兩項會計帳務處理的錯誤:\n①12 月 31 日賒購的商品$4,000 尚未送達,因交貨條件為起運點交貨,因此會計人員沒有做進貨紀錄,同時也沒有計入期末存貨\n②期末存貨盤點時,會計人員誤將公司為騙人布公司代為銷售的承銷品$5,000 計入本公司之存貨中\n請問上述兩項錯誤會使巴布公司當年度的財務報表產生下列哪種情況?", "options": ["淨利多計$5,000,流動資產多計$1,000,流動負債少計$4,000", "淨利多計$5,000,流動資產少計$1,000,流動負債少計$4,000", "淨利多計$3,000,流動資產多計$1,000,流動負債正確", "淨利多計$3,000,流動資產少計$1,000,流動負債正確"], "answer": "A", "figure": null, "official": "①進貨少計4,000、期末存貨少計4,000(淨利不影響);②期末存貨多計5,000。合計期末存貨多計1,000、進貨少計4,000,銷貨成本少計5,000,淨利多計5,000,流動負債(應付帳款)少計4,000。", "explain": {"concept": "定期盤存制:銷貨成本=期初存貨+進貨−期末存貨,存貨與進貨的錯誤要分別影響銷貨成本與資產、負債。", "steps": ["①起運點交貨:貨物一離開賣方,所有權就屬買方,商品在途中也算買方的存貨。公司漏記進貨 4,000(進貨少計 → 銷貨成本少計)、漏記應付帳款 4,000(流動負債少計)、期末存貨也漏了 4,000(存貨少計 → 銷貨成本多計)。", "①對淨利的影響:進貨少計 4,000 與期末存貨少計 4,000 互相抵銷,淨利不受影響。", "②承銷品(寄銷品)所有權仍屬委託人,不應計入自己存貨。多計期末存貨 5,000 → 銷貨成本少計 5,000 → 淨利多計 5,000。", "合計:期末存貨(流動資產)= −4,000 + 5,000 = 多計 $1,000;淨利多計 $5,000;流動負債少計 $4,000。選 A。"], "pitfalls": "進貨與期末存貨同時漏記同額時,淨利不變,但資產與負債都會錯。", "distractors": {"B": "以為資產少計,其實 −4,000+5,000 是淨多計。", "C": "只算 ① 對淨利的影響(多算成3,000)且誤判負債。", "D": "同時算錯淨利與資產。"}}, "check": "python:−4,000+5,000=+1,000(存貨多計);銷貨成本少計5,000;淨利多計5,000;應付少計4,000。", "verified": true, "note": ""}, {"id": "112-3-A-15", "exam": "112-3", "paper": "A", "q": 15, "unit": "十三、存貨", "topic": "先進先出法期末存貨", "stem": "索羅公司在存貨控管上採用定期盤存制及先進先出法,112 年度進貨紀錄資料如下,且經實地盤點期末存貨為 2,500 單位,請問索羅公司期末存貨之成本為多少?\n\n| 項目 | 日期 | 數量 | 單位成本 |\n|---|---|---|---|\n| 存貨 | 01/01 | 2,000 | $15 |\n| 進貨 | 01/20 | 3,000 | $18 |\n| 進貨 | 06/06 | 2,500 | $17 |\n| 進貨 | 07/04 | 700 | $10 |\n| 進貨 | 11/15 | 1,200 | $15 |", "options": ["$35,000", "$35,200", "$37,500", "$42,500"], "answer": "B", "figure": null, "official": "先進先出:期末存貨由最後進貨往前算=1,200×$15+700×$10+600×$17=$35,200。", "explain": {"concept": "先進先出法(FIFO):先買的先賣,期末剩下的是「最近購買」的貨。", "steps": ["FIFO 的期末存貨是最近進的貨,所以從最後一次進貨往前湊滿 2,500 單位。", "11/15 進貨 1,200 單位 × $15 = $18,000。", "07/04 進貨 700 單位 × $10 = $7,000(累計 1,900 單位)。", "還差 2,500 − 1,900 = 600 單位,取自 06/06 進貨,每單位 $17:600 × 17 = $10,200。", "期末存貨成本 = 18,000 + 7,000 + 10,200 = $35,200。"], "pitfalls": "要從『最近的進貨』往前算,不是從期初存貨開始。", "distractors": {"C": "2,500 單位全部以 $15 計算(2,500×15=37,500)。", "D": "2,500 單位全部以 $17 計算(2,500×17=42,500)。"}}, "check": "python:1,200×15+700×10+600×17=35,200,與官方一致。", "verified": true, "note": ""}, {"id": "112-3-A-16", "exam": "112-3", "paper": "A", "q": 16, "unit": "十三、存貨", "topic": "成本與淨變現價值孰低法", "stem": "香吉士公司成立於 01 年初,期末存貨以成本與淨變現價值孰低法衡量,請依各年底存貨資料判斷下列敘述何者錯誤?\n\n| 日期 | 成本 | 淨變現價值 |\n|---|---|---|\n| 01 年 12 月 31 日 | $20,000 | $18,000 |\n| 02 年 12 月 31 日 | $25,000 | $24,000 |\n| 03 年 12 月 31 日 | $30,000 | $29,200 |\n| 04 年 12 月 31 日 | $28,000 | $29,000 |", "options": ["01 年底備抵存貨跌價帳戶餘額為$2,000", "02 年底備抵存貨跌價帳戶餘額為$1,000", "03 年底存貨調整分錄中應貸記:備抵存貨跌價$800", "04 年底存貨調整分錄中應貸記:銷貨成本$800"], "answer": "C", "figure": null, "official": "03 年初備抵存貨跌價餘額為$1,000,03 年底應有餘額$800,故應借:備抵存貨跌價$200、貸:銷貨成本$200。", "explain": {"concept": "成本與淨變現價值孰低:備抵存貨跌價期末餘額=成本−淨變現價值(若淨變現價值較低)。", "steps": ["各年底備抵存貨跌價目標餘額 = 成本 − 淨變現價值(成本較高才有):01 年 20,000−18,000=2,000;02 年 25,000−24,000=1,000;03 年 30,000−29,200=800;04 年 NRV 比成本高,目標餘額 0。", "A、B 就是各年底的目標餘額,正確。", "03 年:年初餘額 1,000 → 目標 800,要減少 200,做 借:備抵存貨跌價 200、貸:銷貨成本 200(迴轉利益)。所以C『貸記備抵存貨跌價 $800』錯誤。", "04 年:餘額 800 → 目標 0,借:備抵存貨跌價 800、貸:銷貨成本 800,D 正確(貸記銷貨成本 $800)。"], "pitfalls": "迴轉時,借記備抵存貨跌價、貸記銷貨成本;提列時方向相反。迴轉金額以原已提列金額為上限。", "distractors": {"A": "(此為正確敘述)", "B": "(此為正確敘述)", "D": "(此為正確敘述)"}}, "check": "python:2,000/1,000/800;03年調整200;04年迴轉800,與官方一致。", "verified": true, "note": ""}, {"id": "112-3-A-17", "exam": "112-3", "paper": "A", "q": 17, "unit": "十四、證券投資", "topic": "證券投資損益分類", "stem": "有關證券投資的會計項目中,下列項目哪些屬於營業外支出?\n①手續費支出\n②股利收入\n③強制透過損益按公允價值衡量之金融資產\n④強制透過損益按公允價值衡量之金融資產評價調整\n⑤透過損益按公允價值衡量之金融資產損失\n⑥透過損益按公允價值衡量之金融資產利益", "options": ["①⑤", "②⑥", "①③⑥", "①④⑤"], "answer": "A", "figure": null, "official": "營業外支出有①手續費支出、⑤透過損益按公允價值衡量之金融資產損失,共二項。", "explain": {"concept": "辨別資產負債項目、營業外收入、營業外支出。", "steps": ["②股利收入、⑥金融資產利益是營業外收入。", "①手續費支出、⑤金融資產損失是營業外支出。", "③金融資產、④評價調整是資產負債表科目(資產),不是損益科目。", "所以營業外支出是 ①⑤,選 A。"], "pitfalls": "科目名稱有『損失』『費用』『支出』才是損益的借方;『金融資產』『評價調整』是資產負債表科目。", "distractors": {"B": "②⑥ 是營業外收入。", "C": "③ 是資產科目、⑥ 是利益,不是支出。", "D": "④ 是資產調整科目,不是損益科目。"}}, "check": "概念題,依官方詳解與會計準則確認。", "verified": true, "note": ""}, {"id": "112-3-A-18", "exam": "112-3", "paper": "A", "q": 18, "unit": "十四、證券投資", "topic": "FVPL 金融資產會計處理", "stem": "有關「透過損益按公允價值衡量之金融資產(FVPL)」的敘述,下列何者錯誤?", "options": ["此筆投資收到現金股利時,應認列為「股利收入」,不影響金融資產的帳面金額", "此筆投資收到股票股利時,要做分錄並重新計算投資的每股帳面金額", "分類為此投資為對被投資公司無重大影響力,且持有供交易的金融資產", "被投資公司的本期淨利,不影響該投資的帳面金額"], "answer": "B", "figure": null, "official": "收到股票股利時「不作分錄」,僅需作備忘記錄,並重新計算每股帳面金額。", "explain": {"concept": "股票股利只增加股數,不是收益,不入帳;現金股利才認列股利收入。", "steps": ["股票股利:被投資公司把盈餘轉增資,持有股數增加但總成本、總價值不變,投資人不做分錄,只在備忘簿記錄股數,並重算每股帳面金額(總成本÷新股數)。B 說『要做分錄』所以錯誤。", "A:FVPL 收到現金股利,借 現金、貸 股利收入,正確,且不影響資產帳面金額。", "C:FVPL 用於短期交易目的、無重大影響,正確。", "D:FVPL 按公允價值衡量,與被投資公司淨利無關(不像權益法),正確。"], "pitfalls": "FVPL 是用公允價值,不用權益法;股票股利只改股數。", "distractors": {"A": "(此為正確敘述)", "C": "(此為正確敘述)", "D": "(此為正確敘述)"}}, "check": "概念題,依官方詳解與會計準則確認。", "verified": true, "note": ""}, {"id": "112-3-A-19", "exam": "112-3", "paper": "A", "q": 19, "unit": "十四、證券投資", "topic": "FVPL 取得、股利、評價與出售", "stem": "庚公司 01 年 6 月 1 日購入上市的辛公司股票,列入「透過損益按公允價值衡量之金融資產」項目中,預計持有一年後出售,相關交易事項如下:\n01 年  6 月 1 日 購入辛公司股票 2,000 股,每股面額$10,每股市價$42,另付手續費$4,000\n     8 月 1 日 收到現金股利每股$2、股票股利每股$2\n     12 月 31 日 辛公司股票收盤價每股$40\n02 年  3 月 1 日 收到現金股利每股$1\n     4 月 1 日 出售持有辛公司的全部股票,每股售價$36,另付手續費及交易稅共計$5,000\n有關此一投資,下列敘述何者正確?", "options": ["01 年度有營業外支出總計$8,000", "01 年度有營業外收入總計$4,000", "01 年底「強制透過損益按公允價值衡量之金融資產評價調整」貸餘$4,000", "02 年出售分錄中的除列分錄應貸記「強制透過損益按公允價值衡量之金融資產評價調整」$2,400"], "answer": "D", "figure": null, "official": "01 年底持有2,400股,公允價值$96,000,評價利益$12,000(借餘);02 年出售前先評價至$36:損失2,400×(40−36)=$9,600,評價調整餘額剩$2,400,出售時貸記$2,400。", "explain": {"concept": "FVPL:取得成本不含手續費(手續費記費用);期末按公允價值評價;出售前先評價到售價,再除列。", "steps": ["取得:2,000 股 × $42 = $84,000(成本),手續費 $4,000 記營業外支出。", "01/8/1 股票股利每股 $2、面額 $10,等於 2/10=20%,增加 2,000×0.2=400 股,共 2,400 股,不入帳;現金股利 2,000×$2=$4,000 記股利收入。", "01/12/31 公允價值 = 2,400 × $40 = $96,000,與成本 84,000 比,評價利益 = $12,000(評價調整借餘 12,000)。", "A:01 年營業外支出只有手續費 $4,000(不是8,000);B:營業外收入 = 股利 4,000 + 評價利益 12,000 = $16,000(不是4,000);C:評價調整是借餘 $12,000,不是貸餘 $4,000。", "02 年出售:先把股票評價到售價 $36:2,400×(36−40)=−$9,600 損失,評價調整由借餘 12,000 降為 2,400。", "出售除列:借 現金 81,400(2,400×36−5,000)、手續費 5,000;貸 金融資產 84,000、評價調整 2,400。D 正確。"], "pitfalls": "手續費不算成本(FVPL);股票股利不入帳但要增加股數;要記得算 2,400 股,不是 2,000 股。", "distractors": {"A": "把手續費加上其他項目,算成 $8,000(應只有 $4,000)。", "B": "只算了現金股利 $4,000,漏掉評價利益 $12,000。", "C": "把評價利益誤當損失、並用錯股數與餘額方向。"}}, "check": "python:2,400股;評價利益12,000;營業外收入16,000;出售前損失9,600;除列貸評價調整2,400,與官方一致。", "verified": true, "note": ""}, {"id": "112-3-A-20", "exam": "112-3", "paper": "A", "q": 20, "unit": "十五、長期營業用資產", "topic": "不動產、廠房及設備會計處理", "stem": "有關「不動產、廠房及設備」之會計處理,下列何者正確?", "options": ["購入載貨用卡車一台,支付的營業稅、安裝費、運費為運輸設備的成本", "不動產、廠房及設備若出售時淨售價高於帳面金額,會發生出售損失", "採用年數合計法計提折舊,折舊費用每年呈等差級數遞減", "受贈之不動產、廠房及設備應按捐贈者原取得時的成本入帳"], "answer": "C", "figure": null, "official": "(A)購入運輸設備支付的營業稅為進項稅額,非運輸設備成本;(B)淨售價高於帳面金額,會發生出售利益;(D)受贈資產應按「受贈當日資產之公允價值」入帳。", "explain": {"concept": "資產成本=使用前一切必要支出(不含可扣抵進項稅額);各折舊法特性。", "steps": ["A:營業稅屬『進項稅額』,可扣抵銷項稅額,不計入資產成本;安裝費、運費才算成本。", "B:賣得比帳面金額多,是『出售利益』,不是損失。", "C:年數合計法每年折舊率分母固定、分子逐年少 1,所以折舊費用每年減少相同金額,是等差級數遞減,正確。", "D:受贈資產按受贈日的公允價值入帳,不是捐贈者的成本。"], "pitfalls": "年數合計法(逐年遞減等差)與倍數餘額遞減法(逐年遞減等比)要分清楚。", "distractors": {"A": "以為營業稅都要算進成本;可扣抵的進項稅額不算。", "B": "把利益與損失搞反。", "D": "誤用原始成本入帳。"}}, "check": "概念題,依官方詳解與會計準則確認。", "verified": true, "note": ""}, {"id": "112-3-A-21", "exam": "112-3", "paper": "A", "q": 21, "unit": "十五、長期營業用資產", "topic": "直線法折舊與會計估計變動", "stem": "辛公司於 01 年初購入一辦公設備,成本$30,000,耐用 6 年,估計殘值為成本的一成,以直線法提列折舊。03 年初因辦公設備保養得宜,公司重新評估後認定設備之總耐用年限應為 8 年,且殘值金額不變,則下列敘述何者正確?", "options": ["03 年底辦公設備之帳面金額為$18,000", "03 年底辦公設備之累計折舊金額為$12,600", "04 年度應提列折舊$3,600", "04 年底調整分錄中應貸記:累計折舊$15,000"], "answer": "A", "figure": null, "official": "01、02 年每年折舊4,500,03 年初帳面金額21,000,剩餘耐用6年,新折舊=(21,000−3,000)÷6=3,000;03 年底帳面金額=21,000−3,000=$18,000。", "explain": {"concept": "會計估計變動:不追溯,以『帳面金額−殘值』除以『剩餘耐用年限』,從變動當期起(推延適用)。", "steps": ["殘值 = 30,000 × 10% = $3,000。原每年折舊 = (30,000 − 3,000) ÷ 6 = $4,500。", "01、02 兩年累計折舊 = 4,500 × 2 = $9,000,03 年初帳面金額 = 30,000 − 9,000 = $21,000。", "總耐用年限改為 8 年,已用 2 年,剩餘 8−2 = 6 年。", "新的每年折舊 = (21,000 − 殘值 3,000) ÷ 6 = $3,000(03、04 年每年都是 3,000)。", "03 年底帳面金額 = 21,000 − 3,000 = $18,000,A 正確。", "03 年底累計折舊 = 9,000+3,000 = 12,000(B 的 12,600 不對);04 年折舊 3,000(C 的 3,600 不對);04 年底調整分錄貸記累計折舊 $3,000(D 的 15,000 是累計總額,不是當年分錄)。"], "pitfalls": "耐用年限改為「總耐用年限 8 年」,剩餘年限要減去已使用的 2 年,不是直接用 8 年。", "distractors": {"B": "12,600 可能是 9,000 + 3,600 的混算。", "C": "3,600 可能是用 18,000 ÷ 5 之類錯誤年限。", "D": "15,000 是 04 年底累計折舊總額 (9,000+3,000+3,000),但分錄只貸記當年折舊 3,000。"}}, "check": "python:殘值3,000;原折舊4,500;03初帳面21,000;新折舊3,000;03底帳面18,000;累計12,000,與官方一致。", "verified": true, "note": ""}, {"id": "112-3-A-22", "exam": "112-3", "paper": "A", "q": 22, "unit": "十五、長期營業用資產", "topic": "資本化支出錯誤更正", "stem": "壬公司 110 年 9 月 1 日以$600,000 購置辦公室一棟,另支付仲介佣金$60,000,估計辦公室使用年限為 20 年,採直線法計提折舊,無殘值。該公司之會計人員於購入時誤將佣金$60,000 以佣金支出入帳,若公司事後發現此錯誤的當下立即更正,且不考慮所得稅的影響,下列不同時點所做之更正分錄,何者錯誤?", "options": ["110 年底期末調整前發現錯誤,應借:房屋及建築成本$60,000、貸:佣金支出$60,000", "110 年底期末結帳後發現錯誤,應借:房屋及建築成本$60,000、折舊$1,000;貸:佣金支出$60,000、累計折舊$3,000", "111 年初發現此錯誤,應借:房屋及建築成本$60,000、貸:追溯適用及追溯重編之影響數$59,000、累計折舊$1,000", "111 年底期末調整後結帳前發現錯誤,應借:房屋及建築成本$60,000、折舊$3,000;貸:追溯適用及追溯重編之影響數$59,000、累計折舊$4,000"], "answer": "B", "figure": null, "official": "110 年底結帳後發現,虛帳戶已結轉至本期損益,更正時應借:房屋及建築成本$60,000;貸:本期損益$59,000、累計折舊$1,000。", "explain": {"concept": "會計錯誤更正:依發現時點(結帳前/結帳後)決定使用虛帳戶或追溯重編科目。", "steps": ["漏計折舊:佣金 $60,000 應資本化,折舊期間 110/9/1~12/31 共 4 個月,折舊 = 60,000 ÷ 20 × 4/12 = $1,000(此題的 4/12);之後每年 $3,000。", "A:110 年底調整前發現:虛帳戶佣金支出還在,直接借 房屋 60,000、貸 佣金支出 60,000,正確。", "B:110 年底結帳後(佣金支出已結清到本期損益),不能再貸佣金支出,應貸 本期損益 59,000(60,000 − 折舊 1,000)、累計折舊 1,000,所以題目分錄錯誤。", "C:111 年初,110 年帳已結清,用追溯適用及追溯重編之影響數:借 房屋 60,000;貸 影響數 59,000、累計折舊 1,000,正確。", "D:111 年底調整後結帳前:111 年折舊 60,000÷20=3,000(借折舊,貸累計折舊),累計折舊共 1,000+3,000=4,000,正確。"], "pitfalls": "發現時點決定科目:本期虛帳戶還在→直接用虛帳戶;上期已結帳→用追溯重編影響數;結帳後但仍是同一期→用本期損益。", "distractors": {"A": "(此為正確敘述)", "C": "(此為正確敘述)", "D": "(此為正確敘述)"}}, "check": "python:60,000/20×4/12=1,000;60,000/20=3,000;1,000+3,000=4,000,與官方一致。", "verified": true, "note": "單元歸類可能有爭議(十五 或 六)。"}, {"id": "112-3-A-23", "exam": "112-3", "paper": "A", "q": 23, "unit": "十五、長期營業用資產", "topic": "年數合計法折舊推算", "stem": "金門公司於 X1 年 12 月 31 日購入成本為$600,000 的設備,耐用年限為 N 年,估計殘值若干,並採用年數合計法提列折舊,X4 年度該設備提列$100,000 之折舊費用、X5 年度該設備提列$50,000 之折舊費用。有關該設備的敘述,下列何者錯誤?", "options": ["可折舊成本為$550,000", "估計殘值為$100,000", "估計耐用年限為 4 年", "X2 年度折舊費用為$200,000"], "answer": "A", "figure": null, "official": "X5為最後一年,耐用年限4年(X2~X5);年數合計=1+2+3+4=10;X4−X5折舊差=可折舊成本×1/10=50,000,可折舊成本=$500,000,殘值=600,000−500,000=$100,000。", "explain": {"concept": "年數合計法:各年折舊=可折舊成本×(剩餘年數÷年數總和),每年折舊遞減相同金額=可折舊成本÷年數總和。", "steps": ["年數合計法每年折舊減少的金額固定 = 可折舊成本 ÷ 年數總和。", "題目 X4 折舊 $100,000、X5 折舊 $50,000,減少 $50,000;又 X5 是『最後一年』(因為之後沒有再給資料,且 X5 的折舊是最小一筆),可推耐用年限 N = X2~X5 共 4 年(C 正確)。", "N=4,年數總和 = 1+2+3+4 = 10;每年減少金額 = 可折舊成本 × 1/10 = 50,000 → 可折舊成本 = $500,000。A 說 550,000 錯誤。", "殘值 = 成本 − 可折舊成本 = 600,000 − 500,000 = $100,000,B 正確。", "X2 年折舊 = 500,000 × 4/10 = $200,000,D 正確。(驗算 X4 = 500,000×2/10=100,000;X5 = 500,000×1/10=50,000 ✓)"], "pitfalls": "N 要先由『最後一年折舊=可折舊成本×1/年數總和』判斷;本題 X5 折舊是最小的一年。", "distractors": {"B": "(此為正確敘述)", "C": "(此為正確敘述)", "D": "(此為正確敘述)"}}, "check": "python:D=500,000;X2=200,000;X4=100,000;X5=50,000;殘值100,000,與官方一致。", "verified": true, "note": ""}, {"id": "112-3-A-24", "exam": "112-3", "paper": "A", "q": 24, "unit": "十、加值型營業稅會計實務", "topic": "營業人銷售額與稅額申報書(401)", "stem": "▲閱讀下文,回答第 24-25 題\n小彭於 X1 年 11 月 1 日以$1,000,000 現金投資設立馬祖公司,馬祖公司為開立統一發票的一般應稅營業人。12 月 31 日,會計人員小湖整理 11-12 月相關進銷項明細如下(以下金額未含營業稅):\n①國內銷貨開立三聯式發票$200,000、國內銷貨退回及折讓$20,000\n②非經海關出口外銷$20,000,已檢附證明文件\n③一般進貨及費用$250,000(其中包含支付員工薪資$30,000、支付自用乘用小汽車之修理費$4,000、支付贈送同業開幕花籃$10,000)\n④購置機器設備$120,000、購買總經理五人座座車$60,000、購置土地$600,000\n請協助小湖編製本期《營業人銷售額與稅額申報書 401》的稅額計算,並選出數字計算正確的選項:\n\n| 代號 | 項目 | 稅額 |\n|---|---|---|\n| 12 | 本期(月)申報留抵稅額 | (A) $9,500 |\n| 13 | 得退稅限額合計 | (B) $10,000 |\n| 14 | 本期(月)應退稅額 | (C) $7,500 |\n| 15 | 本期(月)累積留抵稅額 | (D) $500 |", "options": ["代號12 本期(月)申報留抵稅額 $9,500", "代號13 得退稅限額合計 $10,000", "代號14 本期(月)應退稅額 $7,500", "代號15 本期(月)累積留抵稅額 $500"], "answer": "D", "figure": null, "official": "得扣抵進項=[(250,000−30,000−10,000)+120,000]×5%=$16,500;銷項=(200,000−20,000)×5%=$9,000;申報留抵=7,500;得退稅限額=(20,000+120,000)×5%=7,000;應退7,000;累積留抵=500。", "explain": {"concept": "401 申報書:留抵稅額=進項稅額−銷項稅額;得退稅限額=(零稅率銷售額+固定資產進項)×5%;應退取兩者較小;其餘為累積留抵。", "steps": ["先看銷項稅額:國內銷貨 $200,000 扣掉退回折讓 $20,000 = $180,000,稅額 = 180,000 × 5% = $9,000。外銷零稅率,銷項稅額為 0。", "再看可扣抵進項:薪資不是進貨、贈送同業的花籃屬『交際費性質』不得扣抵;自用乘人小汽車的『修理費』可扣抵(只有購買乘人小汽車不得扣抵)。可扣抵的一般進項 = 250,000 − 30,000 − 10,000 = 210,000,另加機器設備 120,000(座車、土地不能扣抵),合計 330,000 × 5% = $16,500。", "本期(月)申報留抵稅額(12)= 16,500 − 9,000 = $7,500。A 說 9,500 不對。", "得退稅限額(13)= (零稅率銷售額 20,000 + 購買固定資產 120,000) × 5% = 140,000 × 5% = $7,000。B 說 10,000 不對。", "本期(月)應退稅額(14)= 留抵 7,500 與 限額 7,000 取小 = $7,000。C 說 7,500 不對。", "本期(月)累積留抵稅額(15)= 7,500 − 7,000 = $500,D 正確。"], "pitfalls": "不得扣抵的是:自用乘人小汽車的『購買』、交際應酬(如花籃)、非營業用、員工薪資(非進項);零稅率與機器設備可作為退稅限額基礎。", "distractors": {"A": "可能把可扣抵進項算少了(未扣到正確金額)。", "B": "可能把座車也算進退稅限額,(20,000+120,000+60,000)×5%=10,000。", "C": "直接把申報留抵7,500當作應退稅額,忘了要與得退稅限額比較取小。"}}, "check": "python:進項16,500;銷項9,000;留抵7,500;限額7,000;應退7,000;累積留抵500,與官方一致。", "verified": true, "note": "官方詳解(24)選項字母對應方式與表格一致,依答案表 D。"}, {"id": "112-3-A-25", "exam": "112-3", "paper": "A", "q": 25, "unit": "十、加值型營業稅會計實務", "topic": "營業稅結算與財務報表比率", "stem": "小湖每年 12 月 31 日皆需編製財務報表,下列敘述何者正確?", "options": ["營業稅結算後,若有應付營業稅,應列於非流動負債項下", "營業稅結算後,若有應收退稅款,應列於非流動資產項下", "投資人可透過速動比率瞭解公司極短期的償債能力,其數值必小於或等於流動比率", "投資人可由稅後純益率瞭解公司真實的獲利能力,其計算公式為稅前淨利除以銷貨淨額"], "answer": "C", "figure": null, "official": "(A)應付營業稅應列流動負債;(B)應收退稅款應列流動資產;(D)稅後純益率=稅後淨利÷銷貨淨額。", "explain": {"concept": "營業稅結算後的科目分類,及流動比率、速動比率、純益率的定義。", "steps": ["A:應付營業稅(銷項>進項)要在短期內繳納,屬流動負債,不是非流動。", "B:應收退稅款預期在一年內收到,屬流動資產,不是非流動。", "C:速動資產 = 流動資產 − 存貨、預付費用等,分母同為流動負債,所以速動比率 ≤ 流動比率,正確。", "D:稅後純益率 = 稅後淨利 ÷ 銷貨淨額,題目寫『稅前淨利』所以錯誤。"], "pitfalls": "分辨稅前/稅後;速動資產是流動資產的子集,因此速動比率不可能比流動比率大。", "distractors": {"A": "誤以為營業稅是長期負債。", "B": "誤以為退稅要等很久才收到。", "D": "把『稅後純益率』與稅前淨利率混淆。"}}, "check": "概念題,依官方詳解與會計常識確認。", "verified": true, "note": "單元歸類可能有爭議(十 或 九)。"}, {"id": "112-4-A-01", "exam": "112-4", "paper": "A", "q": 1, "unit": "一、會計基本概念", "topic": "商業會計法令與會計假設", "stem": "阿美原是一個朝九晚五的上班族,今自行創業,投資現金$300,000,租下一個小店面,以獨資方式開設紅豆餅專賣店,每月營業額$150,000,業務單純交易量小。該店的下列會計事務處理,哪幾項違反我國商業法令及一般公認會計原則?\n①將會計事務委由記帳士處理\n②銷貨時免用統一發票,也不必繳交營業稅\n③平時採現金基礎記帳,期末決算時不作調整分錄\n④由於自負盈虧,所以將企業資金與業主個人資金一起混為專用", "options": ["①②", "②④", "①③④", "②③④"], "answer": "D", "figure": null, "official": "②免用統一發票仍須繳交營業稅;③決算時應照權責發生制予以調整;④基於企業個體假設,不得將企業資金與業主個人資金一起混為專用。", "explain": {"concept": "考商業會計法令(營業稅、權責基礎)與企業個體假設,要逐項判斷『哪些違規』。", "steps": ["先看①:會計事務委託記帳士(或會計師)辦理是法律允許的,所以①沒有違規,不能選。", "看②:月營業額$150,000的小規模營業人可以免用統一發票,但『免用發票』不等於『免繳營業稅』,仍要依規定繳稅,所以②違規。", "看③:一般公認會計原則要求用權責發生制,期末要作調整分錄(如預付、應計項目),只用現金基礎又不調整是違規。", "看④:企業個體假設規定企業與業主是不同個體,資金不能混在一起使用,④違規。", "違規的是②③④,答案(D)。"], "pitfalls": "以為『免用統一發票』就等於『免稅』;或以為委託記帳士是違法。", "distractors": {"A": "把①(委託記帳士,合法)當成違規,又漏掉③④。", "B": "只看到②④,漏掉③權責發生制必須調整。", "C": "把①當成違規,卻漏掉②免發票仍須繳稅。"}}, "check": "概念題,依商業會計法與會計基本假設逐項確認,與官方詳解一致。", "verified": true, "note": ""}, {"id": "112-4-A-02", "exam": "112-4", "paper": "A", "q": 2, "unit": "四、分錄與日記簿", "topic": "交易對財務報表的影響", "stem": "下列哪一項交易,對財務報表要素或會計項目的影響敘述正確?", "options": ["商品採永續盤存制,將承銷品運到承銷人的處所,導致「應收帳款」增加、「存貨」減少", "將短期營業活動所收到不附息應收票據,持向銀行貼現,貼現日導致流動資產增加、流動負債增加", "賒購商品,採定期盤存制,銷貨條件為起運點交貨,商品起運時由賣方代墊運費,則買方商品起運日的交易,導致營業費用增加、負債增加", "銷售商品,銷貨條件為起運點交貨,商品起運當日收到客戶簽發的支票(發票日期為一個月後),導致「銀行存款」及「銷貨收入」增加"], "answer": "B", "figure": null, "official": "(A)承銷品運到承銷人處所不作分錄,僅作備忘記錄;(B)貼現借「現金」「應收票據貼現負債」,貸「應收票據貼現負債」;(C)借「進貨」「進貨費用」,貸「應付帳款」,營業成本及負債增加;(D)借「應收票據」,貸「銷貨收入」。", "explain": {"concept": "逐項還原分錄,看借貸科目屬於哪一類,再判斷對資產、負債、費用的影響。", "steps": ["(A)承銷品只是放在承銷人那裡,所有權還是我們的,不算銷售,不作分錄(只作備忘),所以不會有應收帳款。", "(B)不附息應收票據去銀行貼現:借記『現金』(資產增加),同時要借記『應收票據貼現負債』還是貸記?此處依詳解,貼現後現金流入使流動資產增加,並產生應收票據貼現負債使流動負債增加。這是對的。", "(C)起運點交貨,買方一出貨就取得所有權,賣方代墊運費,買方分錄是借『進貨』『進貨費用』、貸『應付帳款』,影響的是營業成本(進貨費用屬進貨成本)而不是營業費用,所以敘述錯。", "(D)收到的是遠期支票(發票日一個月後),不能當現金,要借『應收票據』不是『銀行存款』,所以錯。", "結論選(B)。"], "pitfalls": "遠期支票要當成應收票據;進貨運費屬於進貨成本,不是營業費用。", "distractors": {"A": "以為運到承銷人處所就是銷售,忽略所有權沒有轉移。", "C": "把進貨費用誤當成營業費用。", "D": "把遠期支票誤當成現金(銀行存款)。"}}, "check": "概念題,依官方詳解逐項還原分錄確認。", "verified": true, "note": ""}, {"id": "112-4-A-03", "exam": "112-4", "paper": "A", "q": 3, "unit": "二、會計循環及會計帳簿", "topic": "帳簿種類與統制帳戶", "stem": "下列敘述哪幾項正確?\n①只要日記簿記載正確完備,得不必設置分類帳\n②普通序時帳簿、特種序時帳簿、總分類帳、明細分類帳,皆應至少保存10年\n③統制帳戶是指設有明細分類帳的實帳戶\n④欲得知各顧客的賒帳餘額,應查詢應收帳款明細分類帳", "options": ["①②", "①④", "②④", "②③④"], "answer": "C", "figure": null, "official": "①企業必須設置普通序時帳簿及總分類帳;③統制帳戶是指設有明細分類帳的總分類帳戶,實帳戶與虛帳戶均可視需求設置。", "explain": {"concept": "考帳簿的設置、保存年限與統制帳戶的定義。", "steps": ["①:商業會計法規定企業必須設置『普通序時帳簿』(日記簿)和『總分類帳』,不能只有日記簿,所以①錯。", "②:各種會計帳簿(序時帳簿、分類帳)依法至少保存10年,②對。", "③:統制帳戶是『設有明細分類帳的總分類帳戶』,實帳戶、虛帳戶只要需要都可以設,不是只有實帳戶,③錯。", "④:每位客戶欠多少錢,要看『應收帳款明細分類帳』,④對。", "正確的是②④,答案(C)。"], "pitfalls": "統制帳戶不限於實帳戶;分類帳是必須設置的,不能只靠日記簿。", "distractors": {"A": "相信①,但①的說法違反法規。", "B": "相信①,又漏掉②保存年限。", "D": "把③『只限實帳戶』當成對的。"}}, "check": "概念題,依官方詳解與商業會計法確認。", "verified": true, "note": ""}, {"id": "112-4-A-04", "exam": "112-4", "paper": "A", "q": 4, "unit": "六、試算與試算表", "topic": "試算表功能與錯誤", "stem": "有關試算及試算表之敘述,下列何者錯誤?", "options": ["結帳後試算表,可用來編製資產負債表", "調整後試算表,可公允表達企業的財務狀況及財務績效", "分錄與過帳程序都正確時,省略試算程序不會影響帳務的正確性", "試算時發現某一分錄借項為「銷貨退回$1,000」誤記為「進貨退出$1,000」,則餘額式試算表上借方餘額合計與貸方餘額合計皆少計$2,000"], "answer": "D", "figure": null, "official": "(D)銷貨退回為借餘項目,少計$1,000;進貨退出為貸餘項目,誤記借$1,000,使進貨退出貸餘少計$1,000,因此借方與貸方餘額合計皆少計$1,000。", "explain": {"concept": "考試算表的用途,以及『借貸誤記』對試算表兩邊的影響。", "steps": ["(A)結帳後試算表只剩資產、負債、業主權益等實帳戶,可以拿來編資產負債表,對。", "(B)調整後試算表已含所有調整,能表達財務狀況與績效,對。", "(C)試算只是檢查工具,分錄、過帳都對,不試算帳也是對的,對。", "(D)原本該借『銷貨退回$1,000』(借方餘額項目),卻誤記成借『進貨退出$1,000』。結果:銷貨退回少了借方$1,000;進貨退出是貸方餘額項目,被借了$1,000,貸方餘額少$1,000。所以借方、貸方各少$1,000,不是少$2,000,(D)錯。", "題目問『錯誤』,選(D)。"], "pitfalls": "以為借貸兩邊各錯一次就是各少$2,000,其實各只差$1,000。", "distractors": {"A": "本題問錯誤,(A)是正確敘述,誤選的人可能不確定結帳後試算表能否編資產負債表。", "B": "不確定調整後試算表的用途。", "C": "以為不試算就會影響帳的正確性,其實試算只是驗證。"}}, "check": "概念題,已依官方詳解逐項確認;借方少$1,000、貸方少$1,000。", "verified": true, "note": ""}, {"id": "112-4-A-05", "exam": "112-4", "paper": "A", "q": 5, "unit": "一、會計基本概念", "topic": "會計政策、估計變動與錯誤", "stem": "下列事項何者敘述正確?", "options": ["附退貨權之銷貨,實際退貨小於銷貨時合理估計的數量,應增加銷貨收入金額", "存貨採成本與淨變現價值孰低法衡量時,由逐項比較改變為分類比較,屬於會計估計變動", "無形資產耐用年限由非確定改為有限時,應追溯修正累計攤銷餘額,並重編財務報表", "本期實際無法收回的帳款與帳上提列的備抵損失,兩者金額不同時,屬於會計錯誤"], "answer": "A", "figure": null, "official": "(B)不屬於會計估計變動,屬於會計政策變動;(C)屬於會計估計變動,不必追溯修正累計攤銷餘額,也不必重編財務報表;(D)屬於會計估計變動。", "explain": {"concept": "分辨『會計政策變動』『會計估計變動』『會計錯誤』,估計變動採推延(未來)適用。", "steps": ["先記:估計變動是因新資訊對估計數作修正,只影響當期及未來,不追溯。", "(A)實際退貨比當初估計少,是估計的修正,屬估計變動,應增加銷貨收入,對。", "(B)逐項比較改成分類比較是『衡量方法』改變,屬會計政策變動,不是估計變動,錯。", "(C)耐用年限變動屬估計變動,只往後調整攤銷,不追溯、不重編,錯。", "(D)備抵損失是估計值,與實際有差額是估計變動,不是錯誤,錯。", "答案(A)。"], "pitfalls": "把方法改變當成估計變動;以為估計變動要追溯重編。", "distractors": {"B": "誤把逐項改分類比較(政策變動)當估計變動。", "C": "以為耐用年限變動要追溯,其實是推延適用。", "D": "把估計與實際不同當成錯誤。"}}, "check": "概念題,依官方詳解與會計準則(IAS 8)確認。", "verified": true, "note": ""}, {"id": "112-4-A-06", "exam": "112-4", "paper": "A", "q": 6, "unit": "七、調整", "topic": "漏作調整對營運資金影響", "stem": "台元商店採曆年制,採記虛轉實法記帳,X2年底遺漏下列事項之調整:\n①X2年初用品盤存$1,000,X2年購入文具$5,000,X2年底有文具$1,200尚未用完\n②X2年預收一年期租金$15,000,屬於X2年度者為三分之一\n③X2年底應收帳款應提列預期信用減損損失$3,000\n④購入的機器設備X2年應提列折舊$40,000\n以上漏作事項對X2年底之營運資金的影響為何?", "options": ["多計$7,800", "多計$11,800", "多計$12,800", "多計$52,800"], "answer": "C", "figure": null, "official": "營運資金=流動資產-流動負債。①流動資產少計$200;②流動負債少計$10,000,營運資金多計$10,000;③營運資金多計$3,000;④不動產廠房及設備不影響營運資金。合計多計$12,800。", "explain": {"concept": "營運資金=流動資產-流動負債;逐項看漏調整影響的是流動項目還是非流動項目。", "steps": ["公式:營運資金=流動資產-流動負債。我們把每一個遺漏的調整分錄補出來,看它動到哪個流動項目。", "①虛轉實法:購入文具記費用,期初用品盤存$1,000、期末$1,200,應調整:借『用品盤存』$200,貸『文具用品』$200。流動資產增加$200,漏作→營運資金少計$200。", "②預收租金$15,000全記租金收入,其中2/3($10,000)屬X3年,應調整:借『租金收入』$10,000,貸『預收租金』$10,000(流動負債增加)。漏作→流動負債少計→營運資金多計$10,000。", "③預期信用減損:借『預期信用減損損失』$3,000,貸『備抵損失』$3,000,流動資產減少。漏作→營運資金多計$3,000。", "④折舊:借折舊,貸累計折舊,動的是非流動資產,不影響營運資金。", "合計:-200+10,000+3,000=多計$12,800,答案(C)。"], "pitfalls": "①是用品盤存增加,要抵銷(少計),不要加進去;④折舊不影響營運資金。", "distractors": {"A": "可能只把②、③及①的符號算錯($10,000-$3,000+$800之類),沒依分錄推演。", "B": "把①當成多計(+$1,000後),忽略期末用品多出$200才是少計。", "D": "把折舊$40,000也算進營運資金。"}}, "check": "python獨立計算:-200+10000+3000=12800(多計),與官方一致。", "verified": true, "note": ""}, {"id": "112-4-A-07", "exam": "112-4", "paper": "A", "q": 7, "unit": "八、結帳", "topic": "獨資結帳程序", "stem": "有關獨資企業的結帳程序,下列敘述何者錯誤?", "options": ["結帳後試算表,「備抵損失」項目為貸方餘額、「銷貨成本」項目為借方餘額", "調整後試算表與結帳後試算表的「業主資本」帳戶金額相同", "實帳戶的結帳可採分錄結帳,或是在分類帳直接結轉下期", "商品採永續盤存制時,調整後試算表與結帳後試算表的「存貨」帳戶金額相同"], "answer": "A", "figure": null, "official": "(A)結帳後試算表,「備抵損失」帳戶為貸方餘額,但「銷貨成本」帳戶已經結清為零。", "explain": {"concept": "結帳:虛帳戶(收入、費用)結清歸零,實帳戶餘額結轉下期。", "steps": ["結帳要把收入、費用等虛帳戶全部結清,銷貨成本是費用性質帳戶,所以結帳後試算表中它的餘額是零,不會是借方餘額。", "『備抵損失』是實帳戶(資產的抵銷帳戶),結帳後仍有貸方餘額,這部分對。", "因此(A)後半句『銷貨成本為借方餘額』錯誤。", "題目問錯誤,選(A)。"], "pitfalls": "記住:結帳後試算表只剩實帳戶,虛帳戶全為零。", "distractors": {"B": "依官方答案(B)視為正確敘述;但實務上結帳後業主資本會加入本期損益,見備註。", "C": "實帳戶結轉下期有兩種方式,本項正確。", "D": "永續盤存制存貨隨時更新,結帳不再調整,兩試算表相同,本項正確。"}}, "check": "官方詳解:(A)錯。", "verified": false, "note": "官方答案為(A);但(B)『調整後試算表與結帳後試算表的業主資本金額相同』在一般獨資結帳(本期損益、業主往來轉入業主資本)後似也不相同,疑似命題瑕疵,請人工複核。answer照官方。"}, {"id": "112-4-A-08", "exam": "112-4", "paper": "A", "q": 8, "unit": "九、財務報表", "topic": "綜合損益表計算", "stem": "台興公司商品採永續盤存制,預期信用減損損失係來自應收票據及應收帳款預估可能收不回的帳款金額,公司損益資料如下:\n\n| 項目 | 金額 | 項目 | 金額 | 項目 | 金額 |\n|---|---|---|---|---|---|\n| 銷貨成本 | $500,000 | 銷貨收入 | $840,000 | 銷貨折讓 | $40,000 |\n| 推銷費用 | 40,000 | 管理費用 | 60,000 | 研究發展費用 | 16,000 |\n| 利息收入 | 20,000 | 現金短溢(借餘) | 2,000 | 預期信用減損損失 | 4,000 |\n\n根據上述資料,下列項目何者錯誤?", "options": ["營業毛利率37.5%", "營業費用$116,000", "稅前純益$198,000", "若按目前我國所得稅法,則稅後純益$159,000"], "answer": "B", "figure": null, "official": "營業毛利率=1-500,000÷800,000=37.5%;營業費用=40,000+60,000+16,000+4,000=$120,000;稅前純益=$198,000;所得稅=(198,000-120,000)÷2=39,000,稅後純益$159,000。", "explain": {"concept": "綜合損益表結構:銷貨淨額-銷貨成本=毛利;毛利-營業費用+營業外收益-營業外費損=稅前淨利。", "steps": ["銷貨淨額=銷貨收入-銷貨折讓=$840,000-$40,000=$800,000。", "(A)毛利=$800,000-$500,000=$300,000;毛利率=300,000÷800,000=37.5%,對。", "(B)營業費用包含推銷、管理、研發、預期信用減損損失:40,000+60,000+16,000+4,000=$120,000,不是$116,000(少加了預期信用減損損失$4,000),錯。", "(C)稅前純益=毛利300,000-營業費用120,000+利息收入20,000-現金短溢2,000=$198,000,對。", "(D)所得稅:盈餘超過$120,000的部分,稅額為超過部分的一半,且不超過20%。(198,000-120,000)÷2=$39,000(小於198,000×20%=$39,600),所以取$39,000;稅後純益=198,000-39,000=$159,000,對。", "題目問錯誤,答案(B)。"], "pitfalls": "預期信用減損損失屬營業費用,容易漏掉;現金短溢借餘是營業外費損。", "distractors": {"A": "本項正確(37.5%),誤選者可能把毛利率分母用$840,000。", "C": "本項正確;誤選者可能漏掉利息收入或現金短溢。", "D": "本項正確;誤選者可能直接用20%計算稅額($39,600)。"}}, "check": "python獨立計算:毛利率0.375、營業費用120000、稅前198000、稅39000、稅後159000,與官方一致。", "verified": true, "note": ""}, {"id": "112-4-A-09", "exam": "112-4", "paper": "A", "q": 9, "unit": "十、加值型營業稅會計實務", "topic": "營業稅留抵稅額與得退稅限額", "stem": "台雅公司本期銷項、進項資料如下(未含稅):\n①國內銷貨$800,000、國內銷貨退回$10,000、預收商品訂金$10,000\n②經海關出口外銷$80,000、非經海關出口已附證明文件之外銷$20,000\n③一般應稅進貨及費用$1,020,000,進貨取得現金折扣$20,000,另購買酬勞員工禮品$5,000\n④購置機器設備$400,000、購買九人座員工交通車$500,000\n⑤上期累積留抵稅額$5,000\n則台雅公司在《營業人銷售額與稅額申報書(401)》上填報的本期(月)累積留抵稅額為何?", "options": ["$5,000", "$10,000", "$11,000", "$25,000"], "answer": "B", "figure": null, "official": "本期申報留抵稅額=[($1,020,000-$20,000+$400,000)×5%+$5,000]-($800,000+$10,000-$10,000)×5%=$35,000;得退稅限額=($80,000+$20,000+$400,000)×5%=$25,000;本期申報留抵稅額$35,000-應退稅款$25,000=$10,000。", "explain": {"concept": "營業稅:進項稅額-銷項稅額=留抵;但可申請退稅的金額有『限額』(零稅率銷售額及購買固定資產的稅額),其餘繼續留抵。", "steps": ["先算進項稅額:可扣抵的進貨及費用=1,020,000-20,000(現金折扣要扣除)=1,000,000;機器設備400,000也可扣抵。員工禮品、九人座交通車依規定不得扣抵,不計。進項稅額=(1,000,000+400,000)×5%=70,000,再加上期留抵5,000,合計75,000。", "再算銷項稅額:國內銷貨800,000-銷退10,000+預收訂金10,000=800,000;外銷是零稅率,稅額0。銷項稅額=800,000×5%=40,000。", "累計留抵=75,000-40,000=35,000。", "得退稅限額=(零稅率銷售額80,000+20,000+固定資產購入400,000)×5%=25,000。", "因為留抵35,000大於限額25,000,最多退25,000,剩下35,000-25,000=10,000繼續留抵,答案(B)。"], "pitfalls": "員工禮品、九人座小客車的進項稅額不得扣抵;零稅率外銷與固定資產的稅額才算入退稅限額。", "distractors": {"A": "只看到上期留抵$5,000,沒有重新計算。", "C": "可能把員工禮品或其他不得扣抵的稅額誤算進去。", "D": "把得退稅限額$25,000當成留抵稅額。"}}, "check": "python獨立計算:進項75000-銷項40000=35000,限額25000,留抵10000,與官方一致。", "verified": true, "note": ""}, {"id": "112-4-A-10", "exam": "112-4", "paper": "A", "q": 10, "unit": "十一、現金及內部控制", "topic": "銀行調節表", "stem": "8月底台美公司銀行存款帳面餘額$51,000、銀行對帳單餘額$54,000,差異原因如下:\n①台美公司支付一筆保險費,公司帳上誤記為$4,000,與銀行對帳單的金額不符\n②顧客簽發的支票$7,200,台美公司存入銀行後因存款不足遭銀行退票\n③台美公司所開的支票8月底尚未兌現共$13,000,包含保付支票$3,000、5月份開出的未兌現支票$2,000、8月份開出的未兌現支票$8,000\n試計算在①中保險費的實際金額為何?", "options": ["$3,800", "$4,200", "$5,800", "$6,800"], "answer": "A", "figure": null, "official": "銀行方:$54,000-③未兌現支票$10,000=正確餘額$44,000。公司帳面餘額$51,000+①差異金額-②$7,200=$44,000,①差異金額=$200。①之調整分錄:借:銀行存款200,貸:保險費200。保險費實際金額=$4,000-$200=$3,800。", "explain": {"concept": "銀行調節表:雙方調整後的正確餘額必須相等。保付支票銀行已保留款項,不算未兌現。", "steps": ["先算銀行方正確餘額:對帳單$54,000減去『未兌現支票』。保付支票$3,000銀行已先扣款,不算未兌現;所以未兌現=2,000+8,000=10,000。正確餘額=54,000-10,000=$44,000。", "再算公司方:帳面51,000,②退票要扣7,200,再加上①的調整金額X。51,000-7,200+X=44,000,解得X=200(公司少記了存款,要加回)。", "X=200代表公司帳上保險費多記了$200(帳上$4,000多於實際),所以實際保險費=4,000-200=$3,800。", "答案(A)。"], "pitfalls": "保付支票不是未兌現支票;調整金額是要『補回』存款的差額,不是保險費本身。", "distractors": {"B": "把差異$200加到$4,000(方向弄反)。", "C": "可能把未兌現支票只扣$8,000,或算錯差額。", "D": "可能用未兌現支票全額$13,000來算,差額大幅偏離。"}}, "check": "python獨立計算:54000-10000=44000;51000-7200+X=44000→X=200;4000-200=3800,與官方一致。", "verified": true, "note": ""}, {"id": "112-4-A-11", "exam": "112-4", "paper": "A", "q": 11, "unit": "十二、應收款項", "topic": "現金折扣處理(總額法與淨額法)", "stem": "台新公司10月26日賒銷商品一批,收款條件:3/10,1/20,n/30,EOM。客戶於11月10日償還三分之二貨款,並於11月20日交來剩餘款項。對於現金折扣的處理如下:\n①若公司採方式一處理現金折扣,於11月20日認列「銷貨折讓」$3,000\n②若公司採方式二處理現金折扣,於11月20日認列「銷貨收入」$6,000\n下列敘述何者正確?", "options": ["採方式一,台新公司對於現金折扣的處理為淨有權收取的對價", "採方式一,台新公司10月26日~11月20日,該批商品產生的銷貨淨額為$897,000", "採方式二,台新公司10月26日認列銷貨收入$900,000", "採方式二,台新公司銷貨帳務符合IFRS規定,可避免虛增應收帳款及銷貨收入"], "answer": "D", "figure": null, "official": "(A)11月20日曾認列「銷貨折讓」,故採「總額法」;(B)銷貨總額=$3,000÷(1-2/3)÷1%=$900,000,銷貨淨額=900,000-900,000×2/3×3%-3,000=$879,000;(C)因顧客未享之折扣而認列「銷貨收入」,故採「淨有權收取的對價」,10月26日貸記銷貨收入=900,000-900,000×3%=$873,000。", "explain": {"concept": "現金折扣兩種記法:總額法(先按總價認列,折扣時才記銷貨折讓)、淨額法(先扣最大折扣認列,未享折扣時補認銷貨收入)。", "steps": ["先判斷方式:方式一在客戶付款時才認列『銷貨折讓』→總額法。方式二在客戶沒享受折扣時才補認『銷貨收入』→淨額法。", "算出原價:11月20日付剩餘1/3,享1%折扣=$3,000,所以剩餘1/3貨款=3,000÷1%=300,000,總價=300,000÷(1/3)=$900,000。", "(A)總額法是先按總價入帳,不是『淨有權收取的對價』,錯。", "(B)總額法銷貨淨額:2/3($600,000)享3%折扣=18,000;1/3享1%折扣=3,000;淨額=900,000-18,000-3,000=$879,000,不是$897,000,錯。", "(C)淨額法10月26日先按最大折扣3%認列收入:900,000×97%=$873,000,不是$900,000,錯。", "(D)淨額法依IFRS 15只認列預期有權收取的對價,避免虛增應收帳款及銷貨收入,對。答案(D)。"], "pitfalls": "EOM期間要看清:11/10付款享3%,11/20付款只享1%;別把總價與淨價搞混。", "distractors": {"A": "把總額法當成淨額法的說法。", "B": "算成900,000-3,000=897,000,忽略前2/3的3%折扣。", "C": "把淨額法起始認列金額誤當成總價。"}}, "check": "python獨立計算:總價900000;總額法淨額879000;淨額法起始873000,補認6000,與官方一致。", "verified": true, "note": ""}, {"id": "112-4-A-12", "exam": "112-4", "paper": "A", "q": 12, "unit": "十二、應收款項", "topic": "不附息票據與折價攤銷", "stem": "台翔公司X2年初因出售營業用機器收到二年期、面值$508,200的不附息票據,當時有效利率為10%,則下列敘述何者正確?", "options": ["X2年初應收票據之現值為$508,200", "X2年底應收票據之帳面金額為$420,000", "X2年底「應收票據折價」之帳戶餘額為$46,200", "X3年度應收票據之利息收入為$42,000"], "answer": "C", "figure": null, "official": "(A)現值=$508,200÷(1+10%)²=$420,000;(B)X2年底帳面金額=$420,000+$420,000×10%=$462,000;(C)折價餘額=($508,200-$420,000)-$420,000×10%=$46,200;(D)X3年利息收入=X2年底折價餘額=$46,200。", "explain": {"concept": "不附息票據=面值折現成現值,折價用有效利率法攤銷成利息收入。", "steps": ["先求現值:二年後收$508,200,折現率10%,現值=508,200÷1.1²=508,200÷1.21=$420,000。折價=508,200-420,000=$88,200。", "X2年利息收入=420,000×10%=$42,000,折價攤銷42,000;所以X2年底折價餘額=88,200-42,000=$46,200,選項(C)正確。", "X2年底帳面金額=面值508,200-折價46,200=$462,000(或420,000+42,000),不是420,000,(B)錯。", "X3年利息收入=X3年初帳面462,000×10%=$46,200(剛好等於剩餘折價),不是42,000,(D)錯。", "(A)508,200是未來值不是現值,錯。答案(C)。"], "pitfalls": "把面值當現值;把X2年利息誤當X3年利息。", "distractors": {"A": "把面值直接當現值,沒有折現。", "B": "只算到初始現值$420,000,沒加X2年利息收入。", "D": "把X2年的利息$42,000當成X3年。"}}, "check": "python獨立計算:現值420000;X2底帳面462000;折價餘額46200;X3利息46200,與官方一致。", "verified": true, "note": ""}, {"id": "112-4-A-13", "exam": "112-4", "paper": "A", "q": 13, "unit": "十三、存貨", "topic": "存貨的成本與盤存制度", "stem": "有關存貨的敘述,下列何者正確?", "options": ["異常耗損的原料、人工或其他製造成本,不得計入存貨成本", "分期付款銷貨的商品,帳款尚未收齊時,該商品列入賣方的存貨", "商品採定期盤存制,若X1年期末存貨多計,將導致X2年當期淨利少計、X2年期末保留盈餘少計", "物價持續上漲時,存貨的成本公式採平均法比先進先出法,較有可能造成當年度淨利虛盈實虧"], "answer": "A", "figure": null, "official": "(B)該商品列入買方的存貨;(C)若X1年期末存貨多計,將導致X2年當期淨利少計、X2年期末保留盈餘無影響;(D)物價持續上漲時,先進先出法比平均法,較有可能造成當年度淨利虛盈實虧。", "explain": {"concept": "存貨成本範圍、所有權歸屬、期末存貨錯誤的連鎖影響、物價上漲時的成本流程假設。", "steps": ["(A)異常耗損不是為了使存貨達到可銷售狀態的必要成本,應列為當期費用,不計入存貨成本,對。", "(B)分期付款銷貨,商品已交付,所有權風險報酬已移轉,應列入買方存貨,錯。", "(C)X1期末存貨多計→X1銷貨成本少計、X1淨利多計;X2期初存貨多計→X2銷貨成本多計、X2淨利少計。兩年互相抵銷,所以X2年底保留盈餘正確(無影響),選項說『少計』錯。", "(D)物價上漲時,先進先出法銷貨成本較低、利潤較高,較容易有虛盈實虧;不是平均法,錯。", "答案(A)。"], "pitfalls": "期末存貨錯誤的影響是『兩年抵銷』,累計到第二年底保留盈餘不受影響。", "distractors": {"B": "把分期付款商品誤認為仍屬賣方存貨。", "C": "忘記錯誤兩年互相抵銷,保留盈餘無影響。", "D": "把先進先出與平均法在物價上漲時的方向弄反。"}}, "check": "概念題,依官方詳解與存貨會計常識確認。", "verified": true, "note": ""}, {"id": "112-4-A-14", "exam": "112-4", "paper": "A", "q": 14, "unit": "十三、存貨", "topic": "成本與淨變現價值孰低", "stem": "本公司存貨相關資料如下:\n\n| 年底 | 成本 | 估計售價 | 推銷費用 |\n|---|---|---|---|\n| X1年底 | $100,000 | $85,000 | $2,000 |\n| X2年底 | 110,000 | 102,000 | 2,000 |\n| X3年底 | 125,000 | 124,000 | 2,000 |\n\n則下列敘述何者正確?", "options": ["X3年底資產負債表上存貨列示金額為$125,000", "X3年底備抵存貨跌價帳戶餘額為$0", "X3年底存貨衡量分錄導致銷貨成本減少$7,000", "X3年底存貨衡量分錄導致營業外支出減少$3,000"], "answer": "C", "figure": null, "official": "(A)X3年底列示金額為較低的淨變現價值$122,000;(B)X3年底備抵存貨跌價餘額=$125,000-($124,000-$2,000)=$3,000;(C)(D)X3年底分錄:借:備抵存貨跌價7,000,貸:銷貨成本7,000,導致銷貨成本減少$7,000。", "explain": {"concept": "存貨採成本與淨變現價值(NRV=估計售價-推銷費用)孰低衡量,跌價損失/回升利益都列在銷貨成本。", "steps": ["NRV=估計售價-估計推銷費用。X2年底:NRV=102,000-2,000=100,000,成本110,000,所以備抵存貨跌價=110,000-100,000=$10,000(調整前已有)。", "X3年底:NRV=124,000-2,000=122,000,成本125,000,成本較高,應有備抵=125,000-122,000=$3,000;資產負債表存貨列示淨額$122,000((A)錯)。", "備抵存貨跌價由10,000降為3,000,要迴轉7,000:借『備抵存貨跌價』7,000,貸『銷貨成本』7,000。", "迴轉利益沖減『銷貨成本』,所以銷貨成本減少$7,000,(C)對;不是營業外項目,(D)錯;備抵餘額是$3,000不是0,(B)錯。"], "pitfalls": "跌價損失與迴升利益都在銷貨成本,不是營業外;列示金額要取較低者。", "distractors": {"A": "忘記要用較低的淨變現價值$122,000。", "B": "沒算出X3年底仍有備抵$3,000。", "D": "誤以為存貨迴升屬營業外項目。"}}, "check": "python獨立計算:X2備抵10000;X3備抵3000;迴轉7000,與官方一致。", "verified": true, "note": ""}, {"id": "112-4-A-15", "exam": "112-4", "paper": "A", "q": 15, "unit": "九、財務報表", "topic": "營業外收入的認列", "stem": "我國目前公開發行公司的會計處理,下列何者將導致營業外收入增加?", "options": ["存貨採永續盤存制,期末盤點時發現商品實際數量高於帳上記載數量", "應收帳款提列備抵損失時,「備抵損失」帳戶調整前餘額高於調整後餘額", "強制透過損益按公允價值衡量之金融資產,期末衡量時股票之帳面金額高於公允價值", "出售營業用機器設備時,收到不附息應收票據,該機器設備之帳面金額低於票據現值"], "answer": "D", "figure": null, "official": "(A)借「存貨」、貸「銷貨成本」,營業成本減少;(B)借「備抵損失」、貸「預期信用減損利益」,營業費用減少;(C)借「透過損益按公允價值衡量之金融資產損失」、貸「評價調整」,營業外支出增加;(D)貸「處分不動產、廠房及設備利益」,營業外收入增加。", "explain": {"concept": "分辨各分錄貸方(或借方)科目屬於營業成本、營業費用還是營業外收支。", "steps": ["(A)盤盈要借『存貨』、貸『銷貨成本』,影響的是營業成本(減少),不是營業外收入,錯。", "(B)備抵損失調整前餘額高於調整後,要迴轉:貸『預期信用減損利益』沖減營業費用,不是營業外收入,錯。", "(C)金融資產帳面高於公允價值→產生評價損失,是營業外『支出』增加,錯。", "(D)機器帳面金額低於收到票據的現值→賣得比帳面多,產生處分利益,屬營業外收入增加,對。", "答案(D)。"], "pitfalls": "存貨盤盈、備抵損失迴轉看似『利益』,但屬營業成本/營業費用的減少。", "distractors": {"A": "以為盤盈是收入。", "B": "以為備抵迴轉是營業外利益。", "C": "沒判斷方向,損失當成利益。"}}, "check": "概念題,依官方詳解與IFRS分類確認。", "verified": true, "note": ""}, {"id": "112-4-A-16", "exam": "112-4", "paper": "A", "q": 16, "unit": "十四、證券投資", "topic": "持有供交易金融資產", "stem": "台王公司X1年3月初購入台慶公司發行普通股股數的0.1%,持有供交易,相關資料如下:\n\n| 公司 | 購入成本 | 交易成本 | 收到現金股利X1年 | 收到現金股利X2年 | 公允價值X1年底 | 公允價值X2年底 |\n|---|---|---|---|---|---|---|\n| 台慶公司股票 | $100,000 | $140 | $5,000 | $3,000 | $103,000 | $98,000 |\n\n根據上表資料,台王公司下列項目之金額何者正確?", "options": ["該投資導致X1年度本期淨利增加$8,000", "X1年底資產負債表「透過損益按公允價值衡量之金融資產」列示金額為$103,000", "X1年底「強制透過損益按公允價值衡量之金融資產評價調整」帳戶餘額為(貸)$3,000", "X2年底「強制透過損益按公允價值衡量之金融資產評價調整」帳戶餘額為(貸)$5,000"], "answer": "B", "figure": null, "official": "(A)-$140+$5,000+$3,000=$7,860;(B)資產負債表列示金額為公允價值=$103,000;(C)$103,000-$100,000=$3,000(借);(D)$98,000-$100,000=-$2,000(貸)。", "explain": {"concept": "持有供交易(強制透過損益按公允價值衡量):成本與交易成本分開(交易成本當期費用),期末評價利益損失入本期損益。", "steps": ["交易成本$140要直接當費用,不算入投資成本;投資成本入帳$100,000。", "(A)X1年淨利影響=-交易成本140+股利收入5,000+評價利益(103,000-100,000=3,000)=$7,860,不是$8,000,錯。", "(B)資產負債表以公允價值列示,X1年底$103,000,對。", "(C)評價調整=公允價值-成本=103,000-100,000=+3,000,是借餘(加項),不是貸,錯。", "(D)X2年底:98,000-100,000=-2,000,貸餘$2,000,不是$5,000,錯。", "答案(B)。"], "pitfalls": "忘記交易成本當期費用;評價調整的借貸方向。", "distractors": {"A": "忘記扣除交易成本$140。", "C": "公允價值高於成本時,評價調整是借餘,不是貸餘。", "D": "可能把X2年收到股利或跌價數字亂湊;正確是貸餘$2,000。"}}, "check": "python獨立計算:7860;評價調整+3000(借);X2為-2000(貸),與官方一致。", "verified": true, "note": ""}, {"id": "112-4-A-17", "exam": "112-4", "paper": "A", "q": 17, "unit": "十五、長期營業用資產", "topic": "資產入帳成本", "stem": "哪幾項會增加下列資產的入帳成本?\n①購入營業用辦公設備所支付的營業稅\n②購入營業用廠房的除役成本之現值\n③賒購營業用機器設備的現金折扣\n④購入專利權所支付的註冊登記費\n⑤購入公允價值能可靠衡量的生物資產所支付的運費", "options": ["①②", "②④", "③④⑤", "②③④⑤"], "answer": "B", "figure": null, "official": "①為進項稅額,流動資產;③機器設備成本的減項;⑤生物資產成本為公允價值減出售成本,購買生物資產時所支付之運費屬於支付現金的一部分,但不是生物資產的成本。", "explain": {"concept": "資產入帳成本=使資產達可使用狀態的必要支出;反之折扣是成本的減項。", "steps": ["①營業稅屬進項稅額,可扣抵銷項稅額,算流動資產,不增加設備成本,不選。", "②廠房的除役成本(拆除、復原)現值,依準則要計入廠房成本,選。", "③賒購的現金折扣是成本的減項(讓成本變少),不是增加,不選。", "④專利權的註冊登記費是取得專利權的必要支出,計入成本,選。", "⑤生物資產以『公允價值減出售成本』入帳,運費已包含在出售成本之計算,不另加成本,不選。", "所以②④,答案(B)。"], "pitfalls": "折扣是減項;生物資產成本用公允價值減出售成本,不另計運費。", "distractors": {"A": "把進項稅額①當成成本。", "C": "把折扣③當成增加。", "D": "把③⑤也算入。"}}, "check": "概念題,依官方詳解與準則確認。", "verified": true, "note": ""}, {"id": "112-4-A-18", "exam": "112-4", "paper": "A", "q": 18, "unit": "十五、長期營業用資產", "topic": "資本支出誤列費用之影響", "stem": "台利公司X1年7月12日購入機器,買價$100,000,另付安裝費$10,000,估計耐用年限四年,殘值$1,000,採年數合計法提列折舊。公司的折舊計算政策,每月15日以前買入者當月折舊全部計算,每月16日以後買入者當月折舊不計入。公司X3年初發現X1年購入機器時誤將安裝費當作當期費用,若不考慮所得稅因素下,該錯誤對X1、X2年淨利、資產、權益的影響,下列敘述何者正確?", "options": ["X1年底本期淨利少計$10,000", "X2年度本期淨利多計$2,500", "X2年底資產少計$6,250", "X2年底權益少計$4,500"], "answer": "D", "figure": null, "official": "(A)X1年少計半年折舊:費損多計$10,000-$10,000×0.4÷2=$8,000,淨利少計$8,000;(B)X2年度少計折舊=(X2年前半年折舊+X2年後半年折舊)=($2,000+$10,000×0.3÷2)=$3,500,淨利多計$3,500;(C)(D)少計資產成本-少計累計折舊=$10,000-($10,000×0.4÷2+$3,500)=$4,500,X2年底資產少計$4,500、權益少計$4,500。", "explain": {"concept": "資本支出誤列費用:當年淨利少計(費用多記),之後少提折舊使淨利多計;年數合計法折舊要依『第幾年』分段計算。", "steps": ["7月12日買入(15日以前),7月折舊全算,所以X1年使用6個月(7~12月)。年數合計法:耐用4年,年數總和=1+2+3+4=10,第1年折舊率4/10,第2年3/10。", "安裝費$10,000應資本化卻誤記費用,折舊基礎少$10,000(殘值不變,折舊基礎差額就是$10,000)。", "X1年:誤列費用$10,000,少提折舊=10,000×4/10×6/12=2,000。淨利少計=10,000-2,000=$8,000,(A)說$10,000錯。", "X2年:前6個月屬第1年折舊=10,000×4/10×6/12=2,000;後6個月屬第2年折舊=10,000×3/10×6/12=1,500;合計少提3,500,淨利多計$3,500,(B)說2,500錯。", "X2年底資產少計=少列成本10,000-少提累計折舊(2,000+3,500=5,500)=$4,500,(C)說6,250錯。", "X2年底權益少計=X1淨利少計8,000-X2淨利多計3,500=$4,500,與資產少計相同,(D)對。"], "pitfalls": "年數合計法的年度分界與使用月份;漏看X2年要分兩段(第1年後半、第2年前半)。", "distractors": {"A": "忘記扣除少提的折舊,直接用$10,000。", "B": "X2年折舊只算一段或算錯,得$2,500。", "C": "資產少計金額算成$6,250,可能把折舊算錯。"}}, "check": "python獨立計算:X1少計8000;X2多計3500;資產與權益少計4500,與官方一致。", "verified": true, "note": ""}, {"id": "112-4-A-19", "exam": "112-4", "paper": "A", "q": 19, "unit": "十五、長期營業用資產", "topic": "無形資產", "stem": "有關無形資產的敘述,下列何者正確?", "options": ["企業內部不得自行產生無形資產", "專利權的訴訟支出應列入專利權的成本", "非公開發行公司的「商譽」項目,期末可選擇攤銷或不攤銷", "獲得政府免費授予的無形資產,因不需付錢故不必入帳"], "answer": "C", "figure": null, "official": "(A)企業內部得自行產生無形資產;(B)專利權的訴訟支出應列入訴訟費用;(D)獲得政府免費授予的無形資產,仍應入帳。", "explain": {"concept": "無形資產的認列、成本範圍;商譽(非公開發行公司)可選擇攤銷或不攤銷。", "steps": ["(A)內部研發階段支出(開發階段符合條件時)可認列為無形資產,所以『不得』錯。", "(B)專利權的訴訟支出屬於當期費用(訴訟費用),不計入專利權成本,錯。", "(C)依我國規定,非公開發行公司的商譽可選擇攤銷(估計耐用年限)或不攤銷(只作減損測試),對。", "(D)政府免費授予的無形資產,依公允價值或名目金額仍應入帳,錯。", "答案(C)。"], "pitfalls": "以為內部產生的一定不能認列;以為免費取得就不入帳。", "distractors": {"A": "忽略開發階段支出可資本化。", "B": "以為訴訟支出可增加專利權成本。", "D": "認為沒付錢就不必入帳。"}}, "check": "概念題,依官方詳解與我國會計準則確認。", "verified": true, "note": ""}, {"id": "112-4-A-20", "exam": "112-4", "paper": "A", "q": 20, "unit": "十五、長期營業用資產", "topic": "生物資產(未成熟乳牛)", "stem": "大旺畜牧公司於X1年中購買一批未成熟乳牛,準備飼養成熟後生產牛奶,乳牛價格為$675,000,另付運費$5,000。估計若將該批乳牛立即出售,應支付運送牛隻至市場的運費$4,000、經銷商佣金$6,400、交易市場徵收的稅捐$600。乳牛X1年共產出牛奶30,000公升,預估每公升的公允價值$80、出售成本$10。根據上述資料,則下列各項金額何者正確?", "options": ["購買日認列生產性生物資產$680,000", "購買日認列「原始認列生物資產及農產品之損失」$11,000", "收成日生物資產項下金額增加$2,100,000", "收成日認列「原始認列生物資產及農產品之利益」$2,100,000"], "answer": "D", "figure": null, "official": "購買日分錄:借:生產性生物資產664,000、原始認列生物資產及農產品之損失16,000,貸:現金680,000。664,000=($675,000-$4,000)-$6,400-$600;680,000=$675,000+$5,000。收成日分錄:借:農業產品2,100,000,貸:原始認列生物資產及農產品之利益2,100,000(=($80-$10)×30,000)。", "explain": {"concept": "生物資產以『公允價值減出售成本』入帳;收成時農業產品也以公允價值減出售成本衡量,差額列損益。", "steps": ["購買日:公允價值=乳牛價格675,000;出售成本=運費4,000+佣金6,400+稅捐600=11,000。公允價值減出售成本=675,000-11,000=$664,000(生物資產入帳金額),注意題目運費$4,000等是出售成本,這裡算式為(675,000-4,000)-6,400-600=664,000。", "實際付出現金=675,000+5,000=$680,000,所以差額680,000-664,000=$16,000為『原始認列生物資產及農產品之損失』。", "因此(A)680,000錯、(B)11,000錯(應為16,000)。", "收成日:30,000公升×(80-10)=$2,100,000,借『農業產品』2,100,000,貸『原始認列生物資產及農產品之利益』2,100,000。", "(C)收成日增加的是『農業產品』(存貨類),不是生物資產,錯;(D)利益$2,100,000,對。"], "pitfalls": "收成產出的是農業產品,不屬生物資產;運費5,000是付現金一部分,不是生物資產成本。", "distractors": {"A": "把付出現金$680,000當作生物資產入帳。", "B": "把出售成本$11,000當損失,其實損失為$16,000。", "C": "把農產品增加誤當生物資產增加。"}}, "check": "python獨立計算:664000;損失16000;收成2100000,與官方一致。", "verified": true, "note": ""}, {"id": "112-4-A-21", "exam": "112-4", "paper": "A", "q": 21, "unit": "十七、權益", "topic": "權益與負債的分類", "stem": "下列敘述何者正確?", "options": ["「強制贖回特別股」屬於負債", "「已認股本」、「庫藏股票」均列為權益的加項", "「待分配股票股利」在股票股利宣告日即應列為流動負債", "目前我國公開發行公司的股票,每股面額均為新臺幣10元"], "answer": "A", "figure": null, "official": "(B)「庫藏股票」列為權益的減項;(C)「待分配股票股利」列為權益的加項;(D)目前我國公開發行公司的股票,採行彈性面額,僅規定每股面額應歸一律,並未規定每股面額均為新臺幣10元。", "explain": {"concept": "權益、負債的分類:強制贖回的特別股本質是債務;庫藏股票是權益減項;股票股利不是負債。", "steps": ["(A)特別股若有強制贖回的義務,公司必須還錢,本質是負債,對。", "(B)庫藏股票是公司買回自己的股票,在權益中是減項,錯。", "(C)股票股利是發放股票,不需支付現金,宣告日借『保留盈餘』、貸『待分配股票股利』(權益加項),不是負債,錯。", "(D)我國已採彈性面額,每股面額只要全公司一律即可,不一定是$10,錯。", "答案(A)。"], "pitfalls": "以為所有股利宣告都是負債(只有現金股利才是);仍以為面額一定是$10。", "distractors": {"B": "不知庫藏股票為權益減項。", "C": "把股票股利與現金股利混淆。", "D": "沿用舊制每股面額$10的印象。"}}, "check": "概念題,依官方詳解與公司法/會計準則確認。", "verified": true, "note": ""}, {"id": "112-4-A-22", "exam": "112-4", "paper": "A", "q": 22, "unit": "十七、權益", "topic": "權益相關計算公式", "stem": "下列計算公式何者正確?", "options": ["面額股之「股本」項目金額=已發行的股數×每股面額", "法定盈餘公積=(稅後淨利+累積盈餘)×10%", "非累積非參加特別股股利=特別股股本×基本股利率+特別股以前年度累積的積欠股利", "每股盈餘=(本期稅後淨利或淨損-累積特別股本期股利或非累積特別股本期宣告股利)÷普通股流通在外股數"], "answer": "A", "figure": null, "official": "(B)法定盈餘公積=(稅後淨利-累積虧損)×10%;(C)非累積非參加特別股股利=特別股股本×基本股利率;(D)每股盈餘=(本期稅後淨利或淨損-累積特別股本期股利或非累積特別股本期宣告股利)÷普通股流通在外加權平均股數。", "explain": {"concept": "股本、法定盈餘公積、特別股股利、每股盈餘的基本公式。", "steps": ["(A)面額股的股本=已發行股數×每股面額,對。", "(B)法定盈餘公積是從『稅後淨利彌補累積虧損後』提列10%,應是(稅後淨利-累積虧損)×10%,不是加累積盈餘,錯。", "(C)非累積非參加特別股只有當年的基本股利,沒有積欠股利,所以不應加『以前年度累積的積欠股利』,錯(累積特別股才有積欠股利)。", "(D)每股盈餘的分母是『普通股流通在外加權平均股數』,不是期末股數,錯。", "答案(A)。"], "pitfalls": "非累積特別股沒有積欠股利;EPS分母是加權平均股數。", "distractors": {"B": "公式符號記錯,法定盈餘公積要扣累積虧損。", "C": "把累積特別股的積欠股利加到非累積特別股。", "D": "忽略分母是加權平均股數。"}}, "check": "概念題,依官方詳解與會計準則確認;公式與公司法一致。", "verified": true, "note": ""}, {"id": "112-4-A-23", "exam": "112-4", "paper": "A", "q": 23, "unit": "十七、權益", "topic": "盈餘分配表計算", "stem": "▲閱讀下文,回答第23-24題\n小明是大展股份有限公司(以下簡稱大展公司)的股東,大展公司屬於公開發行公司,每年分配盈餘一次。小明收到112年股東常會開會通知,會中討論及承認111年度營業概況、決算表冊、員工與董監事酬勞以及盈餘分配表。大展公司股東常會中各項決議如下:\n(一)111年初累積虧損$50,000、111年度未扣除員工與董監事酬勞之稅前淨利為$550,000,營利事業所得稅稅率為20%\n(二)111年度員工酬勞及董監事酬勞分派情形如下:依公司法235條之1及承認本公司章程規定:本公司當年度如有獲利,扣除累積虧損後應提撥百分之二十為員工酬勞及提撥百分之二為董監事酬勞,兩者均以現金方式發放\n(三)提撥法定盈餘公積百分之十\n(四)配發股東現金股利$150,000、股票股利$50,000\n大展公司之盈餘分配表如下:\n\n| 項目 | 金額 |\n|---|---|\n| 期初未分配盈餘 | (50,000) |\n| 加:本年度稅後淨利 | (A) |\n| 減:提列10%法定盈餘公積 | (B) |\n| 可供分配盈餘 | (C) |\n| 分配項目: | |\n| 股東現金股利 | 150,000 |\n| 股東股票股利 | 50,000 |\n| 期末未分配盈餘 | (D) |\n\n(單位:新臺幣元)\n\n試根據大展公司股東常會各項決議,計算大展公司111年度盈餘分配表中(A)、(B)、(C)、(D)各項金額,何者正確?", "options": ["本年度稅後淨利$343,200", "法定盈餘公積$35,200", "可供分配盈餘$271,800", "期末未分配盈餘$58,000"], "answer": "C", "figure": null, "official": "員工酬勞=($550,000-$50,000)×20%=$100,000;董監事酬勞=($550,000-$50,000)×2%=$10,000。(A)稅後淨利=($550,000-員工酬勞$100,000-董監事酬勞$10,000)×(1-20%)=$352,000;(B)法定盈餘公積=($352,000-$50,000)×10%=$30,200;(C)可供分配盈餘=-$50,000+$352,000-$30,200=$271,800;(D)期末未分配盈餘=$271,800-$150,000-$50,000=$71,800。", "explain": {"concept": "盈餘分配:員工酬勞按(稅前淨利-累積虧損)提列,是費用;稅後淨利再提法定盈餘公積(扣累積虧損後的10%)。", "steps": ["先算員工酬勞與董監事酬勞,基礎是『稅前淨利(未扣酬勞)扣除累積虧損』:550,000-50,000=500,000。員工酬勞=500,000×20%=100,000;董監酬勞=500,000×2%=10,000。", "酬勞是費用,扣除後稅前淨利=550,000-100,000-10,000=440,000;所得稅20%=88,000;稅後淨利(A)=440,000-88,000=$352,000(選項(A)的343,200錯)。", "法定盈餘公積(B)要先彌補累積虧損後再提10%:(352,000-50,000)×10%=$30,200(選項35,200錯)。", "可供分配盈餘(C)=期初未分配盈餘(-50,000)+稅後淨利352,000-法定盈餘公積30,200=$271,800,選項(C)正確。", "期末未分配盈餘(D)=271,800-現金股利150,000-股票股利50,000=$71,800(選項58,000錯)。"], "pitfalls": "員工酬勞基礎要先扣累積虧損;法定盈餘公積也要先扣累積虧損;別忘記酬勞是費用(減稅前淨利)。", "distractors": {"A": "可能先扣累積虧損再算稅或漏扣董監酬勞。", "B": "提列基礎用錯(例如不扣累積虧損,352,000×10%=35,200)。", "D": "可能把股票股利與現金股利扣除錯誤或用錯可供分配盈餘。"}}, "check": "python獨立計算:員工100000、董監10000、稅後352000、公積30200、可供分配271800、期末71800,與官方一致。", "verified": true, "note": ""}, {"id": "112-4-A-24", "exam": "112-4", "paper": "A", "q": 24, "unit": "十七、權益", "topic": "股利與盈餘分配的帳務處理", "stem": "有關大展公司的帳務處理,下列敘述何者正確?", "options": ["目前我國公司的盈餘分配,公司法允許一年、半年、一季或每月分配一次", "員工酬勞及董監事酬勞屬於盈餘分配,應在提供勞務當期自保留盈餘項目扣除", "公司宣告股票股利時,不作分錄,但應備註股數,重新計算每股帳面金額", "公司宣告現金股利時,導致權益減少、流動負債增加"], "answer": "D", "figure": null, "official": "(A)目前公司法允許一年、半年或一季分配一次,不能每月分配;(B)員工酬勞及董監事酬勞屬於薪資支出,不是盈餘分配;(C)宣告股票股利時要作分錄,借:累積虧損,貸:待分配股票股利,(資本公積-股票溢價);(D)公司宣告現金股利時,借:累積虧損,貸:應付股利,導致權益減少、流動負債增加。", "explain": {"concept": "股利宣告日的分錄與影響;員工酬勞是費用。", "steps": ["(A)公司法允許年度、半年度、季度分派盈餘,但沒有每月分配,錯。", "(B)員工酬勞、董監事酬勞視為薪資費用,在提供勞務的當期列為費用,不是盈餘分配,錯。", "(C)宣告股票股利時要作分錄:借『保留盈餘(累積虧損)』,貸『待分配股票股利』(及股本溢價),不是只備註,錯。", "(D)宣告現金股利:借『保留盈餘』(權益減少),貸『應付股利』(流動負債增加),對。", "答案(D)。"], "pitfalls": "以為股票股利宣告日不作分錄(那是發放日才發行股票);以為員工酬勞是盈餘分配。", "distractors": {"A": "以為我國可以每月分配。", "B": "沿用舊制,把員工紅利當盈餘分配。", "C": "以為股票股利不影響帳,只作備註。"}}, "check": "概念題,依官方詳解與公司法確認。", "verified": true, "note": ""}, {"id": "112-5-A-01", "exam": "112-5", "paper": "A", "q": 1, "unit": "一、會計基本概念", "topic": "會計報導與使用者", "stem": "暖暖為品品股份有限公司的員工,該公司為公開發行公司,下列敘述何者正確?", "options": ["公司分為營利與非營利", "品品股份有限公司為社團法人組織且所編製的財務報表須由會計師簽證", "品品股份有限公司適用的一般公認會計原則為國際財務報導準則正體中文版,由金管會翻譯、認可並發布", "暖暖目前擔任公司的總經理,其為會計資訊的外部使用者"], "answer": "B", "figure": null, "official": "公司以營利為目的;IFRS 正體中文版由會計研究發展基金會翻譯,金管會認可並發布;總經理屬內部使用者。", "explain": {"concept": "考公司的性質、公開發行公司的財報規定,以及會計資訊使用者的分類。", "steps": ["先看(A):公司的定義就是「以營利為目的」的社團法人,不會再分營利與非營利,所以(A)錯。", "看(B):股份有限公司是社團法人;公開發行公司的財務報表依法必須經會計師查核簽證,所以(B)正確。", "看(C):IFRS 正體中文版是由「會計研究發展基金會」翻譯,再由金管會「認可並發布」,不是金管會自己翻譯,所以(C)錯。", "看(D):總經理在公司內部做管理決策,是會計資訊的「內部使用者」,不是外部使用者,所以(D)錯。"], "pitfalls": "最容易被(C)的『翻譯者』混淆:翻譯的是會計研究發展基金會,金管會負責認可發布。", "distractors": {"A": "以為公司可以分營利與非營利,其實公司一定以營利為目的。", "C": "誤以為翻譯者是金管會,實際是會計研究發展基金會。", "D": "把總經理誤當外部使用者;內部管理人員屬內部使用者。"}}, "check": "概念題,對照官方詳解與公司法、會計準則常識,結論一致。", "verified": true, "note": ""}, {"id": "112-5-A-02", "exam": "112-5", "paper": "A", "q": 2, "unit": "二、會計循環及會計帳簿", "topic": "會計循環與會計年度", "stem": "有關會計循環(程序)之敘述,下列何者錯誤?", "options": ["分錄為平時會計程序,交易發生時,按交易發生之順序逐日登帳,最遲不可超過二個月", "調整為期末的會計程序,是將各帳戶予以修正,使其帳面金額與實際情況相符,必在結帳程序之前", "以營業淡季之月份作為財務年度結束月份者,稱為自然營業年度", "自分錄、過帳、試算、調整、結帳、編表等六大程序週而復始地於每個報導期間循環一次稱為會計循環,此報導期間為一年一個循環"], "answer": "D", "figure": null, "official": "報導期間長短不限,以一年為期者稱為財務年度(會計年度),並非一定一年一循環。", "explain": {"concept": "考會計循環的六大程序,以及會計年度與報導期間的差別。", "steps": ["本題問「錯誤」的敘述,要逐項檢查。", "(A)分錄是平時程序,商業會計法規定最遲不得超過二個月入帳,正確。", "(B)調整在期末進行,且必在結帳之前,正確。", "(C)選淡季月份當年度結束月,叫自然營業年度,正確。", "(D)報導期間的長短「不限」(可以是月、季、半年、年),只有以一年為期時才叫財務年度或會計年度,所以說「此報導期間為一年一個循環」是錯的,答案選(D)。"], "pitfalls": "看到「循環」就直覺想成一年一次;實際上報導期間可以是月、季、年。", "distractors": {"A": "此項正確(商業會計法:最遲二個月內登帳),不是錯誤敘述。", "B": "此項正確,調整一定在結帳之前。", "C": "此項正確,自然營業年度即以淡季月份為年度結束。"}}, "check": "概念題,與官方詳解及商業會計法常識一致。", "verified": true, "note": ""}, {"id": "112-5-A-03", "exam": "112-5", "paper": "A", "q": 3, "unit": "一、會計基本概念", "topic": "會計基本假設", "stem": "有關會計基本假設之敘述,下列何者錯誤?", "options": ["負債可依據到期時間的長短,區分為流動負債與非流動負債,係基於「應計基礎」假設", "母子公司應編製合併報表,係基於「企業個體」假設", "「貨幣評價」假設在物價波動嚴重時易受指責", "平時以應計基礎記錄交易,期末仍須調整,係基於「報導期間」假設"], "answer": "A", "figure": null, "official": "流動與非流動的區分,是基於「繼續經營」假設。", "explain": {"concept": "考各項會計基本假設(企業個體、繼續經營、貨幣評價、報導期間、應計基礎)分別對應什麼會計處理。", "steps": ["本題問「錯誤」。逐項配對假設與處理方式。", "(A)區分流動、非流動負債,是因為假設企業會繼續經營、負債依到期時間陸續償還,對應「繼續經營」假設,不是應計基礎,所以(A)錯。", "(B)母子公司法律上各自獨立但經濟上視為一體,編合併報表是「企業個體」假設,正確。", "(C)貨幣評價假設以貨幣幣值穩定為前提,物價大漲時歷史成本失真,易受批評,正確。", "(D)因為要分期報導,期末才需調整,屬「報導期間」假設,正確。"], "pitfalls": "「應計基礎」重點是收入費用何時認列,不是資產負債的流動性分類。", "distractors": {"B": "此項正確(企業個體假設)。", "C": "此項正確(貨幣評價的缺點)。", "D": "此項正確(報導期間假設要求期末調整)。"}}, "check": "概念題,與官方詳解及會計基本假設常識一致。", "verified": true, "note": ""}, {"id": "112-5-A-04", "exam": "112-5", "paper": "A", "q": 4, "unit": "二、會計循環及會計帳簿", "topic": "會計憑證種類", "stem": "公司將舉辦聯誼餐會活動,職員小穎至市場攤販採買水果,然而攤販並未給小穎發票或收據,小穎回到公司後隨即填寫水果支出的證明單並經主管或負責人核准,請問此支出證明單屬於何種會計憑證?", "options": ["外來憑證", "內部憑證", "對外憑證", "記帳憑證"], "answer": "A", "figure": null, "official": "支出證明單:因實務限制無法取得憑證(如向小販購物)時,由經辦人填寫,經主管或商業負責人簽章核准後,即可作為外來憑證。", "explain": {"concept": "考原始憑證的分類:外來憑證、對外憑證、內部憑證,以及支出證明單的歸類。", "steps": ["先分類:外來憑證=從外界取得的憑證(如進貨發票);對外憑證=公司開給外界的(如銷貨發票);內部憑證=公司內部自製自用的(如領料單)。", "本題向攤販買水果,對方沒給憑證,依規定可用「支出證明單」代替。", "官方規定這種支出證明單經主管或商業負責人簽章核准後,作為「外來憑證」使用,所以選(A)。", "(D)記帳憑證是分錄用的憑證(如傳票),不是原始憑證,和本題無關。"], "pitfalls": "因為支出證明單是公司自己填寫的,容易誤選「內部憑證」;但它的功能是替代外界憑證,所以歸為外來憑證。", "distractors": {"B": "因為是公司內部人員填寫,誤以為是內部憑證。", "C": "對外憑證是公司開給外界的,方向相反。", "D": "記帳憑證是記帳用的傳票,不是證明交易發生的原始憑證。"}}, "check": "概念題,與官方詳解一致。", "verified": true, "note": ""}, {"id": "112-5-A-05", "exam": "112-5", "paper": "A", "q": 5, "unit": "五、過帳與分類帳", "topic": "分類帳", "stem": "下列敘述何者正確?", "options": ["總分類帳又稱為統制帳", "T 字帳是餘額式分類帳的簡化,實務常用", "分類帳是以會計項目為主體而記錄的帳簿,又稱為終結記錄簿", "分類帳設有類頁欄與日記簿日頁欄互註頁次,兩者相互勾稽,可避免遺漏或重複"], "answer": "C", "figure": null, "official": "(A)設有明細帳的總分類帳才稱為統制帳;(B)T 字帳是標準式分類帳的簡化;(D)分類帳設有日頁欄與日記簿類頁欄互註頁次。", "explain": {"concept": "考分類帳的格式、用途與欄位名稱。", "steps": ["逐項找出錯誤用語。", "(A)並非所有總分類帳都叫統制帳,要「設有明細帳」的總分類帳才稱為統制帳,所以錯。", "(B)T 字帳是「標準式」分類帳的簡化,而且是教學、分析用,不是實務常用,所以錯。", "(C)分類帳以會計項目(科目)為主體記錄,是帳簿的最終記錄,故稱終結記錄簿,正確。", "(D)互註頁次的欄位是「分類帳的日頁欄」對應「日記簿的類頁欄」,題目講反了,所以錯。"], "pitfalls": "(D)的「日頁欄、類頁欄」很容易記反:分類帳有日頁(記日記簿頁次),日記簿有類頁(記分類帳頁次)。", "distractors": {"A": "忽略「設有明細帳」這個前提。", "B": "T 字帳是標準式的簡化,不是餘額式。", "D": "日頁欄與類頁欄放錯帳簿,說反了。"}}, "check": "概念題,與官方詳解一致。", "verified": true, "note": ""}, {"id": "112-5-A-06", "exam": "112-5", "paper": "A", "q": 6, "unit": "六、試算與試算表", "topic": "試算表與錯誤更正", "stem": "晴晴商店的會計人員將貸記應付帳款$80,000,誤過入應付帳款帳戶借方,已知該帳戶過帳前貸方餘額大於$80,000,則有關試算表敘述,下列何者正確?", "options": ["試算表的表首日期必為每年年底", "此錯誤借貸合計數的差額可被「9」除盡", "此錯誤對餘額式試算表的影響為借方多計$80,000", "此錯誤會計人員應該採用註銷更正法予以更正"], "answer": "D", "figure": null, "official": "(A)試算表表首日期為截止日期;(B)借貸方向錯誤,差額可被「2」除盡;(C)對餘額式試算表影響為貸方少計$160,000。", "explain": {"concept": "考過帳錯誤對試算表的影響,以及該用哪種方式更正。", "steps": ["先看錯誤:本來要貸記$80,000,卻記成借記$80,000,是「借貸方向記反」。", "方向記反時,借貸差額 = 2 × $80,000 = $160,000,所以差額可被「2」除盡,不是 9(9 是數字位置顛倒才有的特性),(B)錯。", "影響餘額式試算表:應付帳款原是貸餘,少貸$80,000再多借$80,000,貸餘減少$160,000,所以是「貸方少計$160,000」,(C)錯。", "(A)試算表表首日期是試算的截止日期,可以是月底、季底等,不一定年底,(A)錯。", "(D)這是過帳時發生的錯誤,分錄本身沒錯,依規定用註銷更正法更正,正確。"], "pitfalls": "差額能被 9 除盡是「數字位置顛倒」的特徵;「借貸方向錯誤」差額是金額的 2 倍,能被 2 除盡。", "distractors": {"A": "試算表表首日期是試算截止日,不限年底。", "B": "被 9 整除是位數顛倒的錯誤;本題為方向錯誤,差額$160,000 能被 2 除盡。", "C": "貸餘減少$160,000,是貸方少計,不是借方多計$80,000。"}}, "check": "差額 = 2 × 80,000 = 160,000(方向錯誤);餘額式試算表貸方少計 160,000,與官方詳解一致。", "verified": true, "note": ""}, {"id": "112-5-A-07", "exam": "112-5", "paper": "A", "q": 7, "unit": "七、調整", "topic": "期末調整後淨利", "stem": "忠忠公司 X1 年底調整前淨利為$85,000,期末有下列調整分錄待處理:\n①提列折舊費用$1,000\n②佣金支出中有未實現部分$3,000\n③租金收入中有未實現部分$5,000\n④應收未收之利息$7,000\n試計算 X1 年底調整後淨利應為多少?", "options": ["$93,000", "$89,000", "$83,000", "$81,000"], "answer": "B", "figure": null, "official": "$85,000-$1,000+$3,000-$5,000+$7,000=$89,000", "explain": {"concept": "考調整分錄對淨利的影響:費用增加→淨利減少;費用減少→淨利增加;收入增加→淨利增加;收入減少→淨利減少。", "steps": ["先決定每一項調整是讓收入或費用變多還是變少。", "①提列折舊:費用增加$1,000,淨利減少$1,000。", "②佣金支出有未實現部分(預付費用):這部分屬於以後期間,本期費用要減少$3,000,淨利增加$3,000。", "③租金收入有未實現部分(預收收入):這部分屬於以後期間,本期收入要減少$5,000,淨利減少$5,000。", "④應收利息(應計收益):本期收入增加$7,000,淨利增加$7,000。", "合計:$85,000 - $1,000 + $3,000 - $5,000 + $7,000 = $89,000。"], "pitfalls": "預付費用(費用減少)與預收收入(收入減少)的加減方向最容易弄反。", "distractors": {"A": "②佣金未實現部分與③預收租金的方向都弄反:$85,000-$1,000-$3,000+$5,000+$7,000=$93,000。", "C": "只有②佣金未實現部分的方向弄反(當成費用增加):$85,000-$1,000-$3,000-$5,000+$7,000=$83,000。", "D": "四項調整的方向全部弄反:$85,000+$1,000-$3,000+$5,000-$7,000=$81,000。"}}, "check": "python 算:85000-1000+3000-5000+7000 = 89000,與官方相符。", "verified": true, "note": ""}, {"id": "112-5-A-08", "exam": "112-5", "paper": "A", "q": 8, "unit": "七、調整", "topic": "用品盤存調整", "stem": "程程商店記帳採應計基礎,期初「用品盤存」帳戶餘額$2,000,當年購入文具$4,000,期末盤點尚存$1,000,則下列何者正確?", "options": ["期末調整分錄為,借:文具用品$1,000,貸:用品盤存$1,000", "期末調整分錄為,借:用品盤存$1,000,貸:文具用品$1,000", "期末調整分錄為,借:文具用品$5,000,貸:用品盤存$5,000", "漏作期末調整分錄,將使資產低估"], "answer": "C", "figure": null, "official": "用品盤存帳戶期初$2,000+購入$4,000-期末$1,000=調整數$5,000,故借:文具用品$5,000,貸:用品盤存$5,000;漏作調整將使資產高估。", "explain": {"concept": "考用品的期末調整:購入時先記入資產(用品盤存),期末依實際耗用數轉列費用。", "steps": ["本題購買文具是記入「用品盤存」(資產)的做法,所以期末帳上用品盤存 = 期初$2,000 + 購入$4,000 = $6,000。", "期末盤點只剩$1,000,表示耗用了 $6,000 - $1,000 = $5,000。", "耗用部分要轉成費用:借:文具用品(費用)$5,000,貸:用品盤存$5,000,調整後用品盤存剩$1,000。", "若漏作這筆調整,資產(用品盤存)會高估$5,000、費用低估,所以(D)說「低估」是錯的。"], "pitfalls": "容易只拿「期末剩$1,000」或「期初$2,000」去記分錄;要先把期初與當期購入加總,再扣掉期末餘額。", "distractors": {"A": "把期末剩餘$1,000 當成耗用數,方向與金額都錯。", "B": "分錄借貸方向顛倒,且金額為期末數。", "D": "漏調整會使資產高估,不是低估。"}}, "check": "T 字帳:2,000+4,000-1,000=5,000,與官方相符。", "verified": true, "note": ""}, {"id": "112-5-A-09", "exam": "112-5", "paper": "A", "q": 9, "unit": "八、結帳", "topic": "本期損益法結帳", "stem": "璇璇商店有關商品帳戶及虛帳戶均採本期損益法結帳,則下列璇璇商店期末的結帳分錄,何者正確?", "options": ["借:存貨(12/31)\n  貸:本期損益", "借:本期損益\n  貸:佣金收入", "借:薪資支出\n  貸:本期損益", "借:本期損益\n  貸:累計折舊"], "answer": "A", "figure": null, "official": "(B)收入應借記收入、貸記本期損益;(C)費用應借記本期損益、貸記費用;(D)累計折舊是實帳戶,不必結轉。", "explain": {"concept": "考本期損益法的結帳分錄:收入結入貸方、費用結入借方,期末存貨作為銷貨成本的減項轉入本期損益。", "steps": ["本期損益法:商品帳戶與虛帳戶(收入、費用)都要結轉到「本期損益」。", "期末存貨(12/31)是銷貨成本的減項,結帳時借:存貨(12/31),貸:本期損益,所以(A)正確。", "收入類(如佣金收入)是貸餘,結帳要把它「借」記,對方貸:本期損益,(B)借貸方向反了。", "費用類(如薪資支出)是借餘,結帳要把它「貸」記,對方借:本期損益,(C)反了。", "累計折舊是資產的抵銷帳戶(實帳戶),結帳時餘額留到下期,不會結入本期損益,(D)錯。"], "pitfalls": "收入、費用的結帳方向:收入借記、費用貸記;記成「借:費用」就反了。", "distractors": {"B": "收入應借記收入科目、貸記本期損益,此選項方向顛倒。", "C": "費用應貸記費用科目、借記本期損益,此選項顛倒。", "D": "累計折舊是實帳戶,餘額帶到下期,不結轉。"}}, "check": "概念題,依結帳規則逐項確認,與官方詳解一致。", "verified": true, "note": ""}, {"id": "112-5-A-10", "exam": "112-5", "paper": "A", "q": 10, "unit": "九、財務報表", "topic": "速動比率", "stem": "以下為新竹商店各實帳戶及損益帳戶調整後金額,試問新竹商店的速動比率為何?(算至小數點後第 2 位四捨五入)\n\n| 帳戶 | 金額 | 帳戶 | 金額 | 帳戶 | 金額 |\n|---|---|---|---|---|---|\n| 現金 | $550,000 | 累計折舊-機器設備 | $105,000 | 銷貨成本 | $460,000 |\n| 應收帳款 | $450,000 | 應付帳款 | $590,000 | 薪資支出 | $22,500 |\n| 備抵損失-應收帳款 | $30,000 | 應付利息 | $50,000 | 折舊 | $65,000 |\n| 存貨(期末) | $260,000 | 業主資本 | $3,000,000 | 文具用品 | $10,000 |\n| 用品盤存 | $20,000 | 業主往來(借) | $50,000 | 預期信用減損損失 | $6,000 |\n| 辦公設備成本 | $2,385,000 | 銷貨收入 | $800,000 | 利息費用 | $6,500 |\n| 累計折舊-辦公設備 | $120,000 | 銷貨退回 | $30,000 | | |\n| 機器設備成本 | $370,000 | 銷貨折讓 | $10,000 | | |", "options": ["1.95", "1.64", "1.61", "1.52"], "answer": "D", "figure": null, "official": "速動比率=($550,000+$450,000-$30,000)÷($590,000+$50,000)≒1.52", "explain": {"concept": "速動比率 = 速動資產 ÷ 流動負債,用來衡量短期償債能力,比流動比率更嚴格。", "steps": ["速動資產 = 現金、應收款項(扣除備抵損失)、短期投資等能很快變現的資產;存貨與用品盤存不算。", "本題速動資產 = 現金$550,000 + 應收帳款$450,000 - 備抵損失$30,000 = $970,000。", "流動負債 = 應付帳款$590,000 + 應付利息$50,000 = $640,000。", "速動比率 = $970,000 ÷ $640,000 = 1.515625,四捨五入到小數第 2 位 ≒ 1.52。"], "pitfalls": "把存貨、用品盤存也算進速動資產就變成流動比率;備抵損失是應收帳款的減項,要扣除。", "distractors": {"C": "把備抵損失當加項:($550,000+$450,000+$30,000)÷$640,000≒1.61。"}}, "check": "python:(550000+450000-30000)/(590000+50000)=1.515625≒1.52,與官方相符。", "verified": true, "note": ""}, {"id": "112-5-A-11", "exam": "112-5", "paper": "A", "q": 11, "unit": "八、結帳", "topic": "結轉本期損益至業主往來", "stem": "承上題,新竹商店的本期損益結轉業主往來後,業主往來的金額為何?", "options": ["貸餘$90,000", "貸餘$140,000", "貸餘$190,000", "貸餘$240,000"], "answer": "B", "figure": null, "official": "淨利$190,000結轉業主往來,原借餘$50,000,結轉後貸餘$140,000(權益總額=業主資本$3,000,000+業主往來$140,000)。", "explain": {"concept": "獨資商店結帳時,本期損益(淨利)結轉到業主往來(或業主資本),要先算出淨利,再與原有借餘相抵。", "steps": ["先算本期淨利:銷貨淨額 = $800,000 - $30,000 - $10,000 = $760,000。", "費用合計 = 銷貨成本$460,000 + 薪資$22,500 + 折舊$65,000 + 文具用品$10,000 + 預期信用減損損失$6,000 + 利息費用$6,500 = $570,000。", "淨利 = $760,000 - $570,000 = $190,000(貸餘,增加權益)。", "結帳分錄:借:本期損益$190,000,貸:業主往來$190,000。", "業主往來原為借餘$50,000(業主提取),加上貸記$190,000 後 = 貸餘 $190,000 - $50,000 = $140,000。"], "pitfalls": "忘記業主往來原本是借餘$50,000(要先抵銷),直接寫成淨利$190,000。", "distractors": {"C": "漏扣原有借餘$50,000,直接用淨利當餘額。", "D": "把借餘$50,000 當成加項:$190,000+$50,000=$240,000。"}}, "check": "python:淨利=800000-30000-10000-460000-22500-65000-10000-6000-6500=190000;190000-50000=140000,與官方相符。", "verified": true, "note": ""}, {"id": "112-5-A-12", "exam": "112-5", "paper": "A", "q": 12, "unit": "十、加值型營業稅會計實務", "topic": "加值型營業稅", "stem": "有關我國加值型營業稅之敘述,下列何者正確?", "options": ["我國加值型營業稅稅率一律為 5%", "經營免稅項目之營業,其購進貨物無須支付營業稅", "特種統一發票非我國統一發票使用辦法規定之發票種類", "電子發票是指營業人銷售貨物或勞務時,以網際網路或其他電子方式開立、傳輸或接收的統一發票"], "answer": "D", "figure": null, "official": "(A)一般稅率5%,外銷零稅率;(B)經營免稅項目之營業,其購進貨物仍須支付營業稅;(C)統一發票分5種:三聯式、二聯式、特種、收銀機、電子發票。", "explain": {"concept": "考加值型營業稅的稅率、免稅與統一發票的種類。", "steps": ["(A)一般稅率是 5%,但外銷等適用零稅率(0%),不是一律 5%,錯。", "(B)免稅營業人銷售時不收營業稅,但他「購進」貨物仍要付進項稅額,且無法扣抵,錯。", "(C)統一發票使用辦法規定共 5 種:三聯式、二聯式、特種統一發票、收銀機統一發票、電子發票,特種統一發票是其中之一,錯。", "(D)電子發票的定義正確,選(D)。"], "pitfalls": "零稅率與免稅常被混淆:零稅率可退還進項稅額,免稅則不能扣抵也不能退。", "distractors": {"A": "忽略零稅率(外銷)。", "B": "免稅營業人購進仍須付營業稅。", "C": "特種統一發票正是 5 種發票之一。"}}, "check": "概念題,與官方詳解及營業稅法常識一致。", "verified": true, "note": ""}, {"id": "112-5-A-13", "exam": "112-5", "paper": "A", "q": 13, "unit": "十一、現金及內部控制", "topic": "定額零用金制度", "stem": "會計老師提出下列幾點有關採定額預付制零用金制度的會計處理,何者正確?", "options": ["設置零用金將使流動比率提高", "動支零用金購買文具,分錄為借:文具用品,貸:零用金", "撥補零用金時,將使零用金帳戶餘額不變", "現金短溢為現金的加減項"], "answer": "C", "figure": null, "official": "(A)設置零用金使資產+、資產-,流動比率不變;(B)動支零用金不作分錄,僅在零用金登記簿中作備忘記錄;(D)現金短溢帳戶屬於營業外收入支出共同項目。", "explain": {"concept": "定額預付制零用金:設置時才有分錄,平時動支不作分錄,撥補時才把已花用的費用入帳並補回定額。", "steps": ["(A)設置零用金是借:零用金、貸:現金,流動資產一增一減,總額不變,流動比率不變,錯。", "(B)定額預付制下,動支零用金時「不作分錄」,只在零用金登記簿記錄備忘,錯。", "(C)撥補時分錄是借:各項費用、貸:現金,零用金帳戶餘額維持定額不動,所以餘額不變,正確。", "(D)現金短溢是營業外收入或支出的共同項目,不是現金的加減項,錯。"], "pitfalls": "(B)是「零用金週轉制(非定額)」或其他記法才會有的想法;定額預付制動支時不分錄。", "distractors": {"A": "流動資產一增一減,流動比率不變。", "B": "定額預付制動支不作分錄,撥補時才記費用。", "D": "現金短溢屬營業外收益或費損,不是現金的加減項。"}}, "check": "概念題,與官方詳解一致。", "verified": true, "note": ""}, {"id": "112-5-A-14", "exam": "112-5", "paper": "A", "q": 14, "unit": "十二、應收款項", "topic": "應收帳款淨額列示", "stem": "怡怡公司 111 年期末應收帳款統制帳戶餘額$28,000,其中甲客戶的明細帳為貸餘$2,000,以應收帳款餘額提列 2%的備抵損失,期末調整前備抵損失為借餘$600,則怡怡公司 111 年底資產負債表應收帳款的列示金額為何?", "options": ["$27,440", "$28,000", "$29,400", "$30,000"], "answer": "C", "figure": null, "official": "明細帳借方餘額=$28,000+$2,000=$30,000;備抵損失=$30,000×2%=$600;列示金額=$30,000-$600=$29,400。", "explain": {"concept": "貸餘的應收帳款明細帳要在資產負債表改列為負債(預收款項),應收帳款的提列基礎只能是各客戶的借餘合計。", "steps": ["統制帳戶餘額$28,000 是「借餘客戶合計」減「貸餘客戶」後的淨額。", "甲客戶貸餘$2,000,要從應收帳款中分離出來列為負債,所以借餘客戶合計 = $28,000 + $2,000 = $30,000。", "備抵損失提列基礎 = $30,000,期末餘額 = $30,000 × 2% = $600(貸餘)。", "資產負債表列示:$30,000 - $600 = $29,400。", "(期初借餘$600 只影響調整分錄金額,不影響調整後餘額$600。)"], "pitfalls": "忘記把甲客戶的貸餘加回,直接用統制帳戶$28,000 去計算。", "distractors": {"A": "用$28,000 去乘(1-2%)=$27,440,沒有把貸餘客戶還原為借餘$30,000。", "B": "用統制帳戶餘額,沒扣備抵損失也沒調整貸餘明細。", "D": "只還原借餘$30,000,沒扣備抵損失。"}}, "check": "python:(28000+2000)*(1-0.02)=29400,與官方相符。", "verified": true, "note": ""}, {"id": "112-5-A-15", "exam": "112-5", "paper": "A", "q": 15, "unit": "十二、應收款項", "topic": "應收票據貼現", "stem": "玲玲公司 3 月 1 日收到面額$200,000,票面利率 8%,6 個月期票據一紙,於同年某月 1 日持向銀行貼現,貼現率 12%,已知貼現日認列之「應收票據貼現負債折價」為$2,240,則貼現日為:", "options": ["5 月 1 日", "6 月 1 日", "7 月 1 日", "8 月 1 日"], "answer": "B", "figure": null, "official": "到期值=$208,000;設貼現期間 n 個月,$208,000×12%×n/12-$200,000×8%×n/12=$2,240,n=3,貼現日為 9 月 1 日往前 3 個月=6 月 1 日。", "explain": {"concept": "附息票據貼現:貼現息 = 到期值 × 貼現率 × 貼現期間;「貼現負債折價」= 貼現息 - 剩餘期間應收的票面利息。", "steps": ["先算到期日:3 月 1 日起 6 個月,到期日為 9 月 1 日。", "到期值 = $200,000 + $200,000×8%×6/12 = $208,000。", "設貼現期間為 n 個月:貼現息 = $208,000×12%×n/12 = $2,080n;未來才賺得的票面利息 = $200,000×8%×n/12 ≒ $1,333.33n。", "折價 = 貼現息 - 票面利息 = $2,080n - $1,333.33n = $746.67n = $2,240,所以 n = 3。", "貼現日 = 9 月 1 日往前推 3 個月 = 6 月 1 日。"], "pitfalls": "貼現期間是「貼現日到到期日」,不是從出票日起算。", "distractors": {"A": "貼現期間會是 4 個月,折價約$2,987,不符。", "C": "貼現期間 2 個月,折價約$1,493,不符。", "D": "貼現期間 1 個月,折價約$747,不符。"}}, "check": "python:n=1,2,3,4 折價分別為 746.67、1493.33、2240、2986.67,n=3 相符,與官方一致。", "verified": true, "note": ""}, {"id": "112-5-A-16", "exam": "112-5", "paper": "A", "q": 16, "unit": "十三、存貨", "topic": "商品買賣與銷貨毛利", "stem": "欣欣商店本月 1 日賒購智慧型手機十台,每台定價$60,000,以九折成交,付款條件為 2/10,n/30,該批手機於本月 9 日付清全部貨款,並於本月 16 日以每台$62,000 的價格全部售出,目的地交貨,付款條件為 2/10,n/30,支付運費$1,000,買方於本月 25 日付清全部貨款,接著月底退回 3 台,貨款尚未退還,本批商品銷貨毛利為何?", "options": ["$54,880", "$49,000", "$48,020", "$40,880"], "answer": "A", "figure": null, "official": "銷貨淨額=$62,000×(1-2%)=$60,760/台;銷貨成本=$60,000×90%×(1-2%)=$52,920/台;銷貨毛利=($60,760-$52,920)×(10-3)=$54,880。", "explain": {"concept": "進貨與銷貨都有商業折扣與現金折扣;毛利 = 銷貨淨額 - 銷貨成本,要用最終實際售出的數量計算。", "steps": ["進貨每台成本:定價$60,000 打九折(商業折扣)= $54,000;本月 9 日付款在 10 天內,享 2% 現金折扣,淨成本 = $54,000×98% = $52,920。", "銷貨每台:定價$62,000,買方 9 天內(16 日→25 日)付款,享 2% 折扣,實收 = $62,000×98% = $60,760。", "每台毛利 = $60,760 - $52,920 = $7,840。", "目的地交貨運費$1,000 由賣方負擔,屬於營業費用(運費),不影響銷貨毛利。", "月底退回 3 台,實際售出 10 - 3 = 7 台,毛利 = $7,840 × 7 = $54,880。"], "pitfalls": "目的地交貨的運費是賣方的營業費用,不要拿來扣毛利;退回的 3 台要把銷貨與成本一起扣除。", "distractors": {}}, "check": "python:(62000*0.98-60000*0.9*0.98)*7=54880,與官方相符。", "verified": true, "note": "distractors B~D 無法確切還原其算法,已省略。"}, {"id": "112-5-A-17", "exam": "112-5", "paper": "A", "q": 17, "unit": "十三、存貨", "topic": "移動平均法與成本與淨變現價值孰低", "stem": "書書公司存貨成本採移動平均法計算,期末按成本與淨變現價值孰低法評價。X1 年初存貨數量為 10,000 件,每件成本$8,X1 年前兩季商品資料如下:\n\n| 日期 | 交易 | 單價 |\n|---|---|---|\n| 1 月 10 日 | 銷貨 8,000 件 | @$18(售價) |\n| 2 月 15 日 | 進貨 6,000 件 | @$9 |\n| 3 月 31 日 | 進貨 2,000 件 | @$10 |\n| 4 月 16 日 | 銷貨 5,000 件 | @$20(售價) |\n| 5 月 20 日 | 進貨 5,000 件 | @$12 |\n| 6 月 30 日 | 銷貨 6,000 件 | @$22(售價) |\n\nX1 年第 1 季及第 2 季季底每件存貨淨變現價值分別為$7 及$12。若書書公司按季編製財務報表,則 X1 年第 2 季銷貨成本為何?", "options": ["$88,000", "$94,000", "$108,000", "$114,000"], "answer": "A", "figure": null, "official": "第2季銷貨成本=$45,000+$63,000-$20,000=$88,000(第1季季底跌價損失$20,000於第2季回升而迴轉,沖減銷貨成本)。", "explain": {"concept": "移動平均法:每次進貨後重算平均單價;成本與淨變現價值孰低:存貨成本高於 NRV 時認列跌價,NRV 回升時在原跌價額內迴轉。", "steps": ["第1季:1/10 賣 8,000 件,成本 $8 → 剩 2,000 件 $16,000。2/15 進 6,000 件 @$9 → 共 8,000 件,成本 $16,000+$54,000=$70,000,平均 $8.75。3/31 進 2,000 件 @$10 → 共 10,000 件,成本 $70,000+$20,000=$90,000,平均 $9。", "第1季底:成本 $90,000,NRV = 10,000×$7 = $70,000,成本較高,要認列跌價 $20,000(借:銷貨成本 $20,000,貸:備抵存貨跌價 $20,000)。", "第2季:4/16 賣 5,000 件 @$9 = $45,000,剩 5,000 件 $45,000。5/20 進 5,000 件 @$12 = $60,000,共 10,000 件、成本 $105,000,平均 $10.5。6/30 賣 6,000 件 @$10.5 = $63,000,剩 4,000 件、成本 $42,000。", "第2季底:NRV = 4,000×$12 = $48,000 > 成本 $42,000,不需跌價;原有備抵跌價 $20,000 要全數迴轉(借:備抵存貨跌價 $20,000,貸:銷貨成本 $20,000)。", "第2季銷貨成本 = $45,000 + $63,000 - $20,000 = $88,000。"], "pitfalls": "忘記第1季的跌價損失在第2季回升時要迴轉並沖減銷貨成本,會誤算成$108,000。", "distractors": {"C": "$45,000+$63,000=$108,000,忘記把第1季的跌價$20,000 迴轉沖減銷貨成本。"}}, "check": "python:45000+63000-20000=88000,與官方相符。", "verified": true, "note": "distractors B、D 無法確切還原其算法,已省略。"}, {"id": "112-5-A-18", "exam": "112-5", "paper": "A", "q": 18, "unit": "十四、證券投資", "topic": "透過損益按公允價值衡量之金融資產損益", "stem": "臻臻公司於 01 年 2 月 1 日購入小小公司股票 10,000 股,持股比例 10%,每股面額$20,每股市價$30,另付手續費$450,分類為透過損益按公允價值衡量之金融資產,01 年 7 月 1 日收到現金股利每股$2、股票股利 10%。01 年底每股公允價值$32,01 年 12 月 31 日出售小小公司全部股票,另付手續費及交易稅各計$1,500。01 年度臻臻公司股票投資的淨損益為何?", "options": ["$38,550", "$40,050", "$68,550", "$70,050"], "answer": "C", "figure": null, "official": "-$450(購入手續費)+$52,000(評價調整:$32×11,000-$300,000)+$20,000(股利收入)-$3,000(出售手續費及交易稅)=$68,550", "explain": {"concept": "透過損益按公允價值衡量的金融資產:手續費當期費用;持有期間公允價值變動與股利都列入損益;股票股利不記錄金額,只增加股數。", "steps": ["購入成本 = 10,000 股 × $30 = $300,000;手續費$450 不計入成本,直接列費用,損失$450。", "現金股利 = 10,000 股 × $2 = $20,000,列股利收入(利益)。", "股票股利 10% = 10,000 × 10% = 1,000 股,只增加股數不入帳,總股數變成 11,000 股,但總成本仍是$300,000。", "年底公允價值 = 11,000 股 × $32 = $352,000,評價利益 = $352,000 - $300,000 = $52,000。", "出售時以公允價值$352,000 出售,出售的手續費及交易稅「各」$1,500,共 $3,000,列為損失。", "淨損益 = -$450 + $20,000 + $52,000 - $3,000 = $68,550。"], "pitfalls": "題目「手續費及交易稅各計$1,500」是兩項各$1,500,共$3,000,容易只算一次$1,500 而選到(D)$70,050。", "distractors": {"D": "只扣一次$1,500 的出售費用:-$450+$20,000+$52,000-$1,500=$70,050。"}}, "check": "python:-450+20000+(32*11000-300000)-3000=68550,與官方相符。", "verified": true, "note": "distractors A、B 無法還原其算法,已省略。"}, {"id": "112-5-A-19", "exam": "112-5", "paper": "A", "q": 19, "unit": "十五、長期營業用資產", "topic": "不動產、廠房及設備", "stem": "有關不動產、廠房及設備,下列敘述何者正確?", "options": ["持有供未來開發後營業使用的資產,應列為投資性不動產", "受贈取得的資產,入帳成本=資產的公允價值+直接可歸屬成本", "依所得稅法規定,不動產、廠房及設備折舊方法,以採用平均法(直線法)、生產數量法、工作時間法、年數合計法、定率遞減法、倍數餘額遞減法或其他主管機關核定之折舊方法", "待出售非流動資產,屬於流動資產,不需提列折舊"], "answer": "D", "figure": null, "official": "(A)持有供未來開發後營業使用的資產,應列為不動產、廠房及設備;(B)受贈資產入帳成本=取得時資產的公允價值;(C)所得稅法規定的折舊方法不包含倍數餘額遞減法。", "explain": {"concept": "考不動產、廠房及設備的分類、入帳成本與折舊的規定。", "steps": ["(A)持有是為了「未來開發後自己營業使用」,屬於不動產、廠房及設備,不是投資性不動產(投資性是為了賺租金或增值),錯。", "(B)受贈資產以取得時的公允價值入帳,題目多加了「直接可歸屬成本」,依官方說法為錯。", "(C)所得稅法規定的折舊方法不包含倍數餘額遞減法,題目多列了,錯。", "(D)待出售非流動資產要分類為流動資產(持有待出售),且依規定不再提列折舊,正確。"], "pitfalls": "(B)、(C)的「多加一項」容易忽略;要逐項核對法規列舉的方法。", "distractors": {"A": "投資性不動產是為賺租金或資本利得而持有,不是自用。", "B": "官方答案認定受贈資產入帳成本為公允價值,題目多加直接可歸屬成本。", "C": "所得稅法列舉的折舊方法沒有倍數餘額遞減法。"}}, "check": "概念題,以官方詳解為準。", "verified": true, "note": ""}, {"id": "112-5-A-20", "exam": "112-5", "paper": "A", "q": 20, "unit": "十五、長期營業用資產", "topic": "商標權攤銷", "stem": "洋洋公司為公開發行公司,於 X1 年 7 月 12 日以$20,000 取得某商標權,其剩餘法定年限 5 年,依現行法令,商標權得以申請延展,若公司於法定年限屆滿後,無意繼續使用該商標權,則 X1 年度應提列各項攤提的金額為何?", "options": ["$4,000", "$2,000", "$1,000", "$0"], "answer": "B", "figure": null, "official": "$20,000÷5×1/2=$2,000(X1 年 7 月 12 日取得,當年使用半年)", "explain": {"concept": "無形資產若有有限耐用年限就要攤銷;商標權雖可延展,但公司無意延展,耐用年限就是剩餘法定年限 5 年。", "steps": ["因為公司「無意繼續使用」商標權,所以耐用年限以剩餘法定年限 5 年為準,屬有限耐用年限,要攤銷(不是 $0)。", "每年攤銷 = $20,000 ÷ 5 = $4,000。", "X1 年 7 月 12 日取得,到年底約半年(官方詳解以 1/2 年計算),所以 X1 年攤銷 = $4,000 × 1/2 = $2,000。"], "pitfalls": "不要因為「可延展」就當成耐用年限不確定而不攤銷;也不要忘記只用了半年。", "distractors": {"A": "忘記按使用期間(半年)比例攤銷,全年攤銷$4,000。", "D": "誤認商標權可延展就是無限耐用年限,不攤銷。"}}, "check": "python:20000/5*0.5=2000,與官方相符。", "verified": true, "note": "官方詳解以半年計算(7 月 12 日至年底約 5.6 個月,以 6 個月計)。"}, {"id": "112-5-A-21", "exam": "112-5", "paper": "A", "q": 21, "unit": "十五、長期營業用資產", "topic": "生物資產", "stem": "哲哲公司於 X1 年初購入乳牛及肉牛各一批,分別各支付$225,000、$220,000。X1 年間飼養該乳牛及肉牛之成本飼料分別為$120,000 及$130,000,而飼養人員薪資分別為$180,000 及$200,000。若要將牛隻於 X1 年底出售,全數乳牛可賣得$355,000,全數肉牛可賣得$320,000,且各自需要支付運送至市場運費$5,000。則哲哲公司 X1 年底資產負債表中期末之生物資產總金額為何?", "options": ["$1,075,000", "$670,000", "$665,000", "$445,000"], "answer": "C", "figure": null, "official": "$355,000+$320,000-$10,000=$665,000", "explain": {"concept": "生物資產(如牛隻)於每個報導期間結束日,按「公允價值減出售成本」衡量,不是用取得成本。", "steps": ["生物資產期末衡量基礎:公允價值 - 出售成本(運費等),不是成本。", "乳牛:$355,000 - $5,000(運費) = $350,000。", "肉牛:$320,000 - $5,000(運費) = $315,000。", "合計 = $350,000 + $315,000 = $665,000(即 $355,000 + $320,000 - $10,000)。", "購買價、飼料、薪資是成本資訊,本題用不到。"], "pitfalls": "被一堆成本數字干擾,以為要用成本累加。", "distractors": {"A": "把所有成本加總:$225,000+$220,000+$120,000+$130,000+$180,000+$200,000=$1,075,000。", "B": "只扣一次運費:$355,000+$320,000-$5,000=$670,000。", "D": "只看購入成本$225,000+$220,000=$445,000。"}}, "check": "python:355000+320000-2*5000=665000,與官方相符。", "verified": true, "note": ""}, {"id": "112-5-A-22", "exam": "112-5", "paper": "A", "q": 22, "unit": "十六、負債", "topic": "產品保固負債準備", "stem": "次次公司成立於 X1 年初,專門銷售品牌包包,產品出售時皆提供顧客 2 年的產品保固服務,估計保固期間於銷售後第 1 年及第 2 年產生的產品維修費用分別為銷貨收入的 1%及 2%,次次公司 X1 年度及 X2 年度銷貨收入分別為$780,000 及$960,000,X1 年度及 X2 年度實際發生維修費用分別為$6,000 及$16,000,若次次公司於 X1 年及 X2 年年底均未調整及認列保固負債準備,但實際發生費用時帳務處理無誤,則下列敘述何者正確?(不考慮所得稅影響)", "options": ["X1 年底負債低估$17,400;X2 年底權益高估$12,800", "X1 年底權益高估$17,400;X2 年底負債低估$30,200", "X1 年底負債低估$1,800;X2 年底權益高估$5,000", "X1 年底權益高估$1,800;X2 年底負債低估$3,200"], "answer": "B", "figure": null, "official": "X1 年底保固負債準備=$780,000×(1%+2%)=$23,400,減已發生$6,000=$17,400(負債低估、權益高估);X2 年底準備帳戶餘額=$17,400+($28,800-$16,000)=$30,200(負債低估、權益高估)。", "explain": {"concept": "銷貨時就要依估計保固成本認列費用及負債準備(配合原則);沒認列會讓負債低估、費用低估、權益高估。", "steps": ["保固費用應在銷貨當年估計,所以 X1 年應估計:$780,000 × (1% + 2%) = $23,400。", "X1 年實際發生$6,000,已當費用處理,所以應有但未認列的負債準備餘額 = $23,400 - $6,000 = $17,400。", "沒認列負債準備 → 負債低估$17,400,同時費用少認列 → 淨利高估 → 權益高估$17,400。", "X2 年估計:$960,000 × 3% = $28,800;實際發生$16,000。X2 年底應有餘額 = $17,400 + ($28,800 - $16,000) = $17,400 + $12,800 = $30,200。", "所以 X2 年底負債低估$30,200、權益高估$30,200。選項(B)的「X1 權益高估$17,400、X2 負債低估$30,200」皆符合。"], "pitfalls": "X2 年要累計前一年的未認列金額,不能只看 X2 當年的差額$12,800。", "distractors": {"A": "X2 權益高估$12,800 只算 X2 當年差額,忘記累計 X1 的$17,400。", "C": "只用第 1 年保固率 1%:$7,800-$6,000=$1,800,漏了第 2 年 2%。"}}, "check": "python:780000*0.03-6000=17400;960000*0.03=28800;17400+28800-16000=30200,與官方相符。", "verified": true, "note": "官方答案 B 的兩部分皆成立。distractor D 無法還原其算法,已省略。"}, {"id": "112-5-A-23", "exam": "112-5", "paper": "A", "q": 23, "unit": "十七、權益", "topic": "每股盈餘與本益比", "stem": "證券投資是指購買股票、債券等有價證券,藉以達成投資目的的行為。夢夢有一筆閒置資金,想購買股票作為投資,請就下列敘述分別計算本益比,在不考慮其他情形之下,單就 X6 年各公司本益比高低,幫夢夢選擇最佳投資公司為何?", "options": ["甲公司 X6 年度稅前淨利為$960,000,若所得稅率為 25%,年初流通在外普通股有 200,000 股,當年 9 月 1 日增發普通股 120,000 股,普通股每股公允價值$12", "已知乙公司普通股每股面值$10、每股帳面金額$12、X6 年度每股盈餘為$2、X6 年底普通股每股公允價值$13", "丙公司 X6 年部分項目之期末餘額如下:權益$1,200,000、非累積特別股股本$300,000。X6 年度綜合損益表中稅後淨利$150,000。已知特別股每年基本股利$10,000,且 X6 年預計不發放,X6 年 12 月 31 日普通股每股公允價值為$14,X6 年普通股加權平均流通在外股數為 50,000 股", "丁公司 X6 年度稅後淨利$540,000,資本結構有:八厘累積特別股 50,000 股,每股面額$10 及普通股 100,000 股,每股面額$20,兩種股票均全年流通在外,年底普通股每股公允價值為$30"], "answer": "A", "figure": null, "official": "本益比愈大,投資報酬率愈小,所以應選擇本益比最小者(甲公司,本益比 4)。", "explain": {"concept": "本益比 = 每股市價 ÷ 每股盈餘(EPS)。本益比越低,表示用同樣的錢買到越多盈餘,投資報酬率越高。", "steps": ["先算每家公司的 EPS(每股盈餘)= (稅後淨利 - 特別股股利)÷ 普通股加權平均流通在外股數,再算本益比 = 每股公允價值 ÷ EPS。", "甲:稅後淨利 = $960,000 × (1-25%) = $720,000;加權平均股數 = 200,000 + 120,000 × 4/12(9 月 1 日增發,流通 4 個月)= 240,000;EPS = $3;本益比 = $12 ÷ $3 = 4。", "乙:EPS 已知 $2,本益比 = $13 ÷ $2 = 6.5(帳面金額與面值是干擾資料)。", "丙:非累積特別股且該年預計不發放,不必扣特別股股利;EPS = $150,000 ÷ 50,000 = $3;本益比 = $14 ÷ $3 ≒ 4.67。", "丁:累積特別股股利 = 50,000 × $10 × 8% = $40,000(累積特別股不論發放與否都要扣);EPS = ($540,000 - $40,000) ÷ 100,000 = $5;本益比 = $30 ÷ $5 = 6。", "比較:甲 4 < 丙 4.67 < 丁 6 < 乙 6.5。本益比最小者為甲,選(A)。"], "pitfalls": "加權平均股數要乘以流通月份(4/12);累積特別股股利要扣,非累積且未宣告的不扣。", "distractors": {"B": "本益比 6.5 為四家中最高,代表買貴了,不是最佳。", "C": "本益比約 4.67,略高於甲;若誤把非累積且未發放的特別股股利$10,000 扣掉,EPS 會變成$2.8,算錯。", "D": "本益比 6,較甲高。"}}, "check": "python:甲 EPS=720000/(200000+120000*4/12)=3,PE=4;乙 6.5;丙 EPS=3,PE≒4.67;丁 EPS=5,PE=6,與官方相符。", "verified": true, "note": "選項的『選本益比最小者』為官方詳解採用的判斷標準。"}, {"id": "112-5-A-24", "exam": "112-5", "paper": "A", "q": 24, "unit": "十六、負債", "topic": "公司債基本概念", "stem": "「公司債」,顧名思義即是指由公司發行的債務契約,為一種債券類型。由於公司需要資金,故先向投資人預先借款,約定於特定日期償還本金,並定期支付利息予投資人。國國公司董事會決議,因充實營運資金及償還借款需求,於 112 年 3 月 1 日奉准發行公司債,發行期間 5 年,面額$300,000,票面利率 6%,每年 3 月 1 日及 9 月 1 日付息,有效利率 8%,但公司因故於 112 年 5 月 1 日出售,公司債出售日收到現金$275,000。\n\n有關公司債的敘述,下列何者錯誤?", "options": ["股份有限公司籌措長期資金的方式", "通貨膨脹舉債有利", "不可發行無記名債券", "非公開發行公司,發行公司債的總額無限制"], "answer": "C", "figure": null, "official": "公司債得發行無記名債券,(C)敘述錯誤。", "explain": {"concept": "考公司債的基本性質:籌措長期資金、通貨膨脹時舉債有利、記名與無記名債券、發行總額限制。", "steps": ["本題問「錯誤」。", "(A)公司債是股份有限公司向大眾籌措長期資金的方式之一,正確。", "(B)通貨膨脹時幣值下降,將來還的本金價值變低,舉債對公司有利,正確。", "(C)公司債可以發行記名債券,也可以發行無記名債券,所以「不可發行無記名債券」是錯的,答案選(C)。", "(D)依現行公司法,非公開發行公司發行公司債的總額已無限制,正確。"], "pitfalls": "(D)是新舊法差異,舊法有發行限額,現行公司法已放寬。", "distractors": {"A": "此項正確。", "B": "此項正確。", "D": "此項正確(現行公司法對非公開發行公司已無限額)。"}}, "check": "概念題,與官方答案(C)及公司法常識一致。", "verified": true, "note": "與第 25 題共用同一段閱讀文章。"}, {"id": "112-5-A-25", "exam": "112-5", "paper": "A", "q": 25, "unit": "十六、負債", "topic": "公司債折溢價攤銷", "stem": "「公司債」,顧名思義即是指由公司發行的債務契約,為一種債券類型。由於公司需要資金,故先向投資人預先借款,約定於特定日期償還本金,並定期支付利息予投資人。國國公司董事會決議,因充實營運資金及償還借款需求,於 112 年 3 月 1 日奉准發行公司債,發行期間 5 年,面額$300,000,票面利率 6%,每年 3 月 1 日及 9 月 1 日付息,有效利率 8%,但公司因故於 112 年 5 月 1 日出售,公司債出售日收到現金$275,000。\n\n有關國國公司 112 年發行公司債的相關金額計算,下列何者正確?", "options": ["112 年 5 月 1 日帳面金額$275,000", "112 年度利息費用$14,507", "112 年度攤銷溢價$2,540", "112 年 12 月 31 日調整後帳面金額$274,540"], "answer": "D", "figure": null, "official": "5/1 帳面金額=$275,000-$300,000×6%×2/12=$272,000;5/1~9/1 利息費用$7,253、折價攤銷$1,253;9/1~12/31 利息費用$7,287;全年利息費用$14,540,攤銷折價$2,540,12/31 帳面金額=$272,000+$2,540=$274,540。", "explain": {"concept": "公司債在兩個付息日之間出售,收到的現金包含「已過的應計利息」,要先扣除;再用有效利率法算利息費用與折價攤銷。", "steps": ["發行日是 3/1,5/1 才出售,已過 2 個月,買方多付 2 個月利息 = $300,000 × 6% × 2/12 = $3,000。", "所以 5/1 的公司債帳面金額 = $275,000 - $3,000 = $272,000(不是$275,000),(A)錯。", "面額$300,000 > 帳面金額$272,000,所以是「折價」發行,攤銷是增加帳面金額,不是攤銷溢價,(C)用詞也錯。", "5/1~9/1(4 個月):利息費用 = $272,000 × 8% × 4/12 ≒ $7,253;付息 = $300,000 × 6% × 4/12 = $6,000;折價攤銷 = $7,253 - $6,000 = $1,253;9/1 帳面金額 = $272,000 + $1,253 = $273,253。", "9/1~12/31(4 個月):利息費用 = $273,253 × 8% × 4/12 ≒ $7,287;應付利息 = $6,000;折價攤銷 ≒ $1,287。", "全年利息費用 = $7,253 + $7,287 = $14,540(B 的$14,507 錯);全年折價攤銷 = $1,253 + $1,287 = $2,540。", "12/31 調整後帳面金額 = $272,000 + $2,540 = $274,540,選(D)。"], "pitfalls": "忘記扣除出售日的應計利息,以及折價、溢價名稱混淆。", "distractors": {"A": "忘記扣除已過 2 個月的應計利息$3,000。", "B": "整年都用$272,000 計算:$272,000×8%×8/12≒$14,507,沒有把 9/1 的帳面金額增加納入。", "C": "此債券為折價發行(帳面金額低於面額),應稱攤銷折價;且 112 年攤銷$2,540 是折價攤銷,不是溢價。"}}, "check": "python:7253.33+7286.75=14540;攤銷 1253+1287=2540;272000+2540=274540,與官方相符。", "verified": true, "note": "選項(C)的『攤銷溢價』字面上與折價攤銷數字相同,官方詳解以(D)為答案。"}, {"id": "113-1-A-01", "exam": "113-1", "paper": "A", "q": 1, "unit": "一、會計基本概念", "topic": "會計法規適用順序", "stem": "股市名嘴所稱之護國神山「台積電公司」,該公司係公開發行公司,針對下列所列示之法律、行政命令及一般公認會計原則,其會計事務處理的優先順序,下列何者正確?\n①商業會計法　②證券發行人財務報告編製準則　③IFRSs　④企業會計準則公報　⑤證券交易法", "options": ["①②③④", "①⑤②③", "⑤①②③", "⑤②①④"], "answer": "C", "figure": null, "official": "公開發行公司適用位階:法律>行政命令>一般公認會計原則,法律中證券交易法>商業會計法,GAAP為IFRSs。", "explain": {"concept": "公開發行公司的會計處理,先看法律,再看行政命令,最後才是一般公認會計原則。", "steps": ["先分三層:法律 > 行政命令 > 一般公認會計原則(GAAP)。", "①商業會計法、⑤證券交易法都是「法律」;公開發行公司受證券交易法管得更嚴,所以⑤要排在①前面。", "②證券發行人財務報告編製準則是主管機關訂的「行政命令」,排在法律之後。", "③IFRSs(國際財務報導準則)是公開發行公司採用的一般公認會計原則;④企業會計準則公報是給非公開發行公司用的,所以不列入。", "所以順序是 ⑤→①→②→③,選(C)。"], "pitfalls": "容易把商業會計法放最前面,忘了公開發行公司還要先遵守證券交易法。", "distractors": {"A": "把商業會計法排最前,又把④企業會計準則公報放進來,但公開發行公司採IFRSs。", "B": "①與⑤順序顛倒,證券交易法應優先於商業會計法。", "D": "把行政命令②排在法律①前面,且多放了④。"}}, "check": "概念題,依官方詳解與法規位階常識確認。", "verified": true, "note": ""}, {"id": "113-1-A-02", "exam": "113-1", "paper": "A", "q": 2, "unit": "三、會計基本法則", "topic": "會計科目分類", "stem": "高一會計課,老師進行分組競賽,比賽一般行業會計項目分類的正確性,則哪一隊完全正確?\n紅隊:營業費用包含薪資支出、其他損失、文具用品、手續費支出、預期信用減損損失\n白隊:流動資產包含進項稅額、留抵稅額、備抵損失—應收票據、應收退稅款、其他應收款、暫付款、代付款、償債基金\n藍隊:營業外收入包含利息收入、租金收入、捐贈收入、處分投資利益、預期信用減損利益\n黑隊:流動負債包含銀行透支、應付土地房屋款、代收款、銷項稅額、本期所得稅負債", "options": ["紅隊", "白隊", "藍隊", "黑隊"], "answer": "D", "figure": null, "official": "紅隊:營業費用不含其他損失、手續費支出。白隊:流動資產不含償債基金。藍隊:營業外收入不含預期信用減損利益。", "explain": {"concept": "分辨各科目屬於哪一大類(營業費用/營業外收支/流動資產/流動負債)。", "steps": ["逐隊檢查,只要有一個科目放錯,那隊就不完全正確。", "紅隊:「其他損失」是營業外支出,「手續費支出」是營業外支出(官方詳解亦不列入營業費用),所以錯。", "白隊:償債基金是長期投資/基金,屬非流動資產,不是流動資產,所以錯。", "藍隊:預期信用減損利益是「營業費用」的減項(沖回減損),不是營業外收入,所以錯。", "黑隊:銀行透支、應付土地房屋款、代收款、銷項稅額、本期所得稅負債都是一年內要償付的流動負債,全對,選(D)。"], "pitfalls": "最容易把償債基金當流動資產,或把預期信用減損利益當成營業外收入。", "distractors": {"A": "誤把其他損失、手續費支出當成營業費用。", "B": "誤把償債基金當流動資產。", "C": "誤把預期信用減損利益當成營業外收入。"}}, "check": "概念題,依官方詳解確認。", "verified": true, "note": ""}, {"id": "113-1-A-03", "exam": "113-1", "paper": "A", "q": 3, "unit": "一、會計基本概念", "topic": "由權益推算損益", "stem": "臺北公司 112 年 12 月 31 日資產總額及負債總額分別為 $370,000 及 $110,000,111 年 12 月 31 日資產總額及負債總額分別為 $420,000 及 $250,000。若 112 年 10 月業主代公司支付通訊費用 $18,000,且已知臺北公司 112 年底結帳前權益金額為 $150,000,則臺北公司 112 年度損益為何?", "options": ["淨損 $10,000", "淨利 $90,000", "淨利 $110,000", "淨利 $132,000"], "answer": "C", "figure": null, "official": "112年底權益$370,000-$110,000=$260,000;結帳前權益已含增資、減資及存入、提取,結帳後權益差額為當期損益:$260,000-$150,000=$110,000(淨利)。", "explain": {"concept": "會計恆等式:資產-負債=權益。結帳前的權益還沒加入本期損益,結帳後才加入,兩者的差就是本期損益。", "steps": ["先用恆等式算 112 年底(結帳後)權益:$370,000-$110,000=$260,000。", "題目給的結帳前權益 $150,000,已經包含了期間內的增資、減資、業主提取、業主存入(含業主代付的 $18,000)。", "結帳就是把損益轉入權益,所以:結帳後權益-結帳前權益=本期損益。", "$260,000-$150,000=$110,000,為正數,所以是淨利 $110,000。", "111 年底數字與業主代付通訊費 $18,000 都是干擾資訊,已經反映在結帳前權益裡,不用再加減。"], "pitfalls": "看到 111 年資料就想用「期末權益-期初權益」,但那會混入增資、提取等非損益因素。", "distractors": {"B": "用 112 年底權益 $260,000 減 111 年底權益 $170,000 得 $90,000,忽略了期間內業主增減資與提取。"}}, "check": "260,000-150,000=110,000(python asserts)。", "verified": true, "note": ""}, {"id": "113-1-A-04", "exam": "113-1", "paper": "A", "q": 4, "unit": "六、試算與試算表", "topic": "試算表概念", "stem": "有關試算之敘述,下列何者正確?", "options": ["試算表表首日期為記載試算的總分類帳記錄之截止日期", "試算表借貸平衡代表分錄與過帳工作均無錯誤", "試算表是企業之正式報表,須定期對外公布", "若某一會計項目帳戶餘額為零,仍應列入餘額式試算表中"], "answer": "A", "figure": null, "official": "B:借貸平衡仍可能有不影響平衡的錯誤;C:試算表非正式報表;D:餘額為零者不列入餘額式試算表。", "explain": {"concept": "試算表的功能與限制。", "steps": ["試算表的表首日期,是指總分類帳記錄到哪一天為止(例如「X1年12月31日試算表」),所以(A)正確。", "(B)借貸平衡只能說借貸金額相等,但漏記、重複記、借貸同時記錯科目等錯誤,借貸仍然平衡,所以不能保證完全沒錯。", "(C)試算表是內部查核用的工作底稿,不是正式報表,不必對外公布。", "(D)餘額式試算表只列有餘額的帳戶,餘額為零的不用列入。"], "pitfalls": "「平衡就代表沒錯」是最常見的迷思。", "distractors": {"B": "以為借貸平衡就一定沒有錯誤。", "C": "把試算表誤當成財務報表。", "D": "餘額式試算表是不列餘額為零的帳戶。"}}, "check": "概念題,依官方詳解確認。", "verified": true, "note": ""}, {"id": "113-1-A-05", "exam": "113-1", "paper": "A", "q": 5, "unit": "二、會計循環及會計帳簿", "topic": "會計憑證", "stem": "有關會計憑證敘述,下列何者錯誤?", "options": ["記帳憑證可以證明會計處理人員的責任", "銷售商品半數收現,半數暫欠於複式傳票四分法下,應該開立現金轉帳傳票", "傳票當中分號的編號,不考慮傳票的種類,只依交易發生的先後次序連續編號", "傳票與其他單據、表格、證明等各表件以一次套寫的方式完成,可避免錯誤發生,此為套寫傳票"], "answer": "C", "figure": null, "official": "傳票當中分號的編號,須考慮傳票的種類;總號的編號不考慮傳票種類,只依交易發生先後次序連續編號。", "explain": {"concept": "傳票的總號與分號編法不同。", "steps": ["題目問「錯誤」的選項。", "(C)把總號與分號的規則講反了:分號要「依傳票種類」(收入、支出、轉帳)分別編號;總號才是不分種類、依發生先後連續編號。", "(B)半收現半賒欠,一部分現金、一部分轉帳,在四分法下開現金轉帳傳票,正確。", "(A)記帳憑證上有經手人簽章,可證明處理人員責任,正確。", "(D)套寫傳票是一次寫好多份,正確。"], "pitfalls": "總號、分號容易記反。", "distractors": {"A": "此敘述正確,不是答案。", "B": "此敘述正確,不是答案。", "D": "此敘述正確,不是答案。"}}, "check": "概念題,依官方詳解確認。", "verified": true, "note": ""}, {"id": "113-1-A-06", "exam": "113-1", "paper": "A", "q": 6, "unit": "二、會計循環及會計帳簿", "topic": "帳簿概念", "stem": "下列敘述何者錯誤?", "options": ["混合交易一定是複雜交易,但複雜交易不一定是混合交易", "總分類帳中之所有帳戶都可稱為「統制帳戶」", "分類帳中每頁的合計金額須過入次頁", "「T」字帳係由標準式分類帳簡化而來"], "answer": "B", "figure": null, "official": "總分類帳帳戶中設有明細分類帳者才可稱為「統制帳戶」。", "explain": {"concept": "統制帳戶的定義。", "steps": ["題目問「錯誤」。", "統制帳戶是指「底下設有明細分類帳」的總分類帳戶(如應收帳款、應付帳款),不是所有總帳戶都算。所以(B)錯。", "(A)混合交易(同時含兩類以上性質)必然涉及多個科目,是複雜交易的一種,反之則不一定,正確。", "(C)每頁合計要過入次頁,正確。", "(D)T字帳是標準式帳戶簡化而成,正確。"], "pitfalls": "把「總分類帳戶」都當成統制帳戶。", "distractors": {"A": "敘述正確。", "C": "敘述正確。", "D": "敘述正確。"}}, "check": "概念題,依官方詳解確認。", "verified": true, "note": ""}, {"id": "113-1-A-07", "exam": "113-1", "paper": "A", "q": 7, "unit": "七、調整", "topic": "調整錯誤的影響", "stem": "下列何種調整錯誤,將造成資產多計、淨利多計?", "options": ["漏記應收利息之調整", "漏未調整預付租金中已經實現之部份", "定期盤存制期末盤點存貨,盤點錯誤導致存貨少計", "漏未調整文具用品中尚未耗用的部份"], "answer": "B", "figure": null, "official": "漏調整預付租金已實現部分,應借租金支出貸預付租金,漏調整使費用少計、淨利多計,預付租金(資產)多計。", "explain": {"concept": "判斷漏調整對資產與損益的影響。", "steps": ["先想正確分錄:預付租金已用掉的部份要「借:租金支出,貸:預付租金」。", "若漏掉:費用少記→淨利多計;預付租金沒減少→資產多計。符合題意,(B)正確。", "(A)漏記應收利息:借應收利息、貸利息收入都漏了→資產少計、收益少計、淨利少計。", "(C)期末存貨少計→資產少計、銷貨成本多計、淨利少計。", "(D)文具用品買入時記費用,期末未耗用部分要調整為資產(借用品盤存、貸文具用品)。漏調整→費用多計、淨利少計、資產少計。"], "pitfalls": "分不清漏調整是「少了借方」還是「少了貸方」。", "distractors": {"A": "漏記應收利息會使資產與淨利都少計。", "C": "存貨少計會使資產與淨利都少計。", "D": "漏調整會使費用多計、資產少計、淨利少計。"}}, "check": "概念題,依官方詳解確認。", "verified": true, "note": ""}, {"id": "113-1-A-08", "exam": "113-1", "paper": "A", "q": 8, "unit": "十、加值型營業稅會計實務", "topic": "營業稅概念", "stem": "有關加值型營業稅之敘述,下列何者錯誤?", "options": ["加值型營業稅稅率分為一般營業、外銷營業及金融保險業,三大類", "小規模營業人是指每月平均銷售額20萬元以下,銷售時開立普通收據,免用統一發票", "醫院提供的醫療服務及藥品適用營業稅免稅", "申報期間原則為每兩個月為一期,並於次期單月15日內向主管機關申報;適用零稅率者,得申請以每月為一期,於次月15日前申報"], "answer": "A", "figure": null, "official": "加值型營業稅稅率分為一般營業、外銷營業及免稅營業,三大類。", "explain": {"concept": "營業稅的稅率分類。", "steps": ["題目問「錯誤」。", "營業稅的三大類是:一般營業人(稅率5%)、外銷營業(零稅率)、免稅營業(免稅),不是「金融保險業」。所以(A)錯。", "(B)小規模營業人每月平均銷售額20萬元以下,可開普通收據,正確。", "(C)醫療服務及藥品免稅,正確。", "(D)申報每兩個月一期、單月15日前申報;零稅率可申請每月申報,正確。"], "pitfalls": "把「免稅營業」記成「金融保險業」(金融保險業是特種稅額計算)。", "distractors": {"B": "敘述正確。", "C": "敘述正確。", "D": "敘述正確。"}}, "check": "概念題,依官方詳解確認。", "verified": true, "note": ""}, {"id": "113-1-A-09", "exam": "113-1", "paper": "A", "q": 9, "unit": "一、會計基本概念", "topic": "財務報導觀念", "stem": "有關「財務報導觀念」之敘述,下列哪一項正確?", "options": ["企業應將負債區分為流動、非流動負債,是基於「企業個體假設」", "企業員工的團隊精神是公司重要人力資源,因此必須入帳,是基於「貨幣評價假設」", "「報導期間假設」主要目的為提供即時性資訊,企業報導期間之長度不可超過一年", "根據「財務報導之觀念架構」,財務報表的基本假設是基於「繼續經營假設」"], "answer": "D", "figure": null, "official": "(A)流動/非流動區分是基於繼續經營假設;(B)團隊精神無法以貨幣量化不得入帳;(C)報導期間長短可自訂,惟每段長短需一致。", "explain": {"concept": "財務報導的基本假設:繼續經營假設。", "steps": ["財務報表是假設企業會繼續經營下去來編製的,所以(D)正確。", "(A)企業會區分流動與非流動,是因為企業持續經營、會一直有流動資金循環,屬繼續經營假設,而企業個體假設是指企業與業主分開。", "(B)團隊精神無法用貨幣衡量,不能入帳。貨幣評價假設是指交易以貨幣衡量。", "(C)報導期間可依需求自訂長短(例如會計年度1年也可更短),只要每段一致即可,不是不能超過一年。"], "pitfalls": "混淆各項會計假設與其用途。", "distractors": {"A": "誤用企業個體假設。", "B": "忽略不能貨幣量化者不得入帳。", "C": "誤以為報導期間不可超過一年。"}}, "check": "概念題,依官方詳解確認。", "verified": true, "note": ""}, {"id": "113-1-A-10", "exam": "113-1", "paper": "A", "q": 10, "unit": "二、會計循環及會計帳簿", "topic": "傳票判讀", "stem": "根據花蓮商店所編製之複式傳票,下列敘述何者錯誤?\n\n花蓮商店　現金轉帳傳票　中華民國 112 年 12 月 31 日　總號 20　分號 4\n\n| 付方(借) | 摘要 | 金額 | 收方(貸) | 摘要 | 金額 |\n|---|---|---|---|---|---|\n| 進貨 | 部分付現 | 12,000 | 應付票據 | 瑞穗商店 | 6,000 |\n| 現金收入(轉帳部分) |  |  | 現金支出 |  | 6,000 |\n| 合計 |  | 12,000 | 合計 |  | 12,000 |", "options": ["此一交易為混合交易", "該商店複式傳票種類採用三分法", "該交易分錄應為借:進貨$12,000,貸:應付票據$6,000、現金$6,000", "此會計憑證應至少保存5年"], "answer": "B", "figure": null, "official": "此傳票為現金轉帳傳票,代表複式傳票採四分法(現金收入、現金支出、轉帳、現金轉帳)。", "explain": {"concept": "傳票三分法與四分法的差別。", "steps": ["三分法只有:收入傳票、支出傳票、轉帳傳票。四分法再多一種「現金轉帳傳票」。", "圖上標題是「現金轉帳傳票」,三分法沒有這種傳票,所以該商店採四分法,(B)敘述錯誤。", "(A)進貨一次含現金與應付票據兩種貸方,屬混合交易,正確。", "(C)借進貨 12,000;貸應付票據 6,000、現金 6,000,正確。", "(D)會計憑證依商業會計法至少保存5年,正確。"], "pitfalls": "不知道現金轉帳傳票只出現在四分法。", "distractors": {"A": "敘述正確。", "C": "敘述正確。", "D": "敘述正確。"}}, "check": "概念題,依官方詳解確認。", "verified": true, "note": "傳票原為表格圖,已轉成文字表格,金額依原圖(12,000/6,000)。"}, {"id": "113-1-A-11", "exam": "113-1", "paper": "A", "q": 11, "unit": "二、會計循環及會計帳簿", "topic": "帳簿種類", "stem": "根據下列敘述,依序選出相對應的帳簿代號選項:\n甲、普通序時帳簿　乙、總分類帳簿　丙、明細分類帳簿\n①____記錄所有會計事項\n②____又稱終結記錄簿\n③____特定第四級會計項目之子項目設置帳戶,以記載其變動", "options": ["甲乙丙", "甲丙乙", "乙甲丙", "乙丙甲"], "answer": "A", "figure": null, "official": "①普通序時帳簿(日記簿)記錄所有交易;②總分類帳又稱終結記錄簿;③明細分類帳對第四級會計項目之子項目設置帳戶。", "explain": {"concept": "序時帳簿、總分類帳、明細分類帳的特性。", "steps": ["①「記錄所有會計事項」:依日期順序記載全部交易,是普通序時帳簿(甲)。", "②「終結記錄簿」:交易最後要歸類記在總分類帳,所以是總分類帳簿(乙)。", "③「第四級會計項目之子項目」:更細分的帳,是明細分類帳簿(丙)。", "所以依序是甲、乙、丙,選(A)。"], "pitfalls": "把總分類帳與序時帳簿搞混。", "distractors": {"B": "把②誤認為明細分類帳。", "C": "把①誤認為總分類帳。", "D": "①②③全部對應錯誤。"}}, "check": "概念題,依官方詳解確認。", "verified": true, "note": ""}, {"id": "113-1-A-12", "exam": "113-1", "paper": "A", "q": 12, "unit": "十、加值型營業稅會計實務", "topic": "營業稅申報(401)", "stem": "嘉義公司為適用加值型營業稅率之營業人,7~8月份相關資料如下,試完成營業人銷售額與稅額申報(401)之稅額計算。則有關申報書中所列示之金額何者正確?\n甲、國內銷售收入:(1) 三聯式收銀機發票應稅銷售額 $550,000 (2) 二聯式統一發票應稅總金額 $105,000 (3) 銷貨退回及折讓證明單,應稅銷售額 $32,000\n乙、經海關出口外銷 $200,000\n丙、進貨、購置不動產及支付修繕費金額(皆未含稅):(1) 進貨 $820,000 (2) 購置載貨用卡車 $50,000 (3) 支付公務車修繕費 $5,000\n丁、前期申報累積留抵稅額 $10,000\n\n以下表格為嘉義公司7~8月份《營業人銷售額與稅額申報書(401)》的「稅額計算」:\n\n| 項目 | 代號 | 稅額 |\n|---|---|---|\n| 本期(月)銷項稅額合計 | 101 |  |\n| 得扣抵進項稅額合計 | 107 |  |\n| 上期(月)累積留抵稅額 | 108 |  |\n| 小計 | 110 | (A) |\n| 本期(月)應實繳稅額 | 111 |  |\n| 本期(月)申報留抵稅額 | 112 | (B) |\n| 得退稅限額合計 | 113 | (C) |\n| 本期(月)應退稅額 | 114 |  |\n| 本期(月)累積留抵稅額 | 115 | (D) |", "options": ["(A) $53,750", "(B) $22,900", "(C) $12,750", "(D) $12,500"], "answer": "A", "figure": null, "official": "銷項=$550,000×5%+$105,000÷1.05×5%-$32,000×5%=$30,900;進項=$820,000×5%+$50,000×5%+$5,000×5%=$43,750;(A)小計=$43,750+$10,000=$53,750;(B)=$53,750-$30,900=$22,850;(C)=($200,000+$50,000)×5%=$12,500;(D)=$22,850-$12,500=$10,350。", "explain": {"concept": "401 申報書稅額計算流程:進項+上期留抵-銷項=留抵稅額;退稅限額=(零稅率銷售額+固定資產進項)×5%。", "steps": ["先算銷項稅額:三聯式銷售額 $550,000×5%=$27,500;二聯式含稅 $105,000,稅額=$105,000÷1.05×5%=$5,000;銷貨退回折讓要減:$32,000×5%=$1,600。合計 $27,500+$5,000-$1,600=$30,900。", "再算得扣抵進項稅額:進貨 $820,000×5%=$41,000;卡車 $50,000×5%=$2,500;公務車修繕 $5,000×5%=$250。合計 $43,750。", "(A)小計(代號110)=進項稅額+上期累積留抵稅額=$43,750+$10,000=$53,750。選項(A)正確。", "(B)申報留抵稅額=小計-銷項=$53,750-$30,900=$22,850(選項寫 $22,900,不對)。", "(C)得退稅限額=(零稅率銷售額 $200,000+購買固定資產 $50,000)×5%=$12,500(選項寫 $12,750,不對)。", "(D)累積留抵稅額=$22,850-$12,500(應退稅額)=$10,350(選項寫 $12,500,不對)。"], "pitfalls": "容易漏掉銷貨退回要減、二聯式發票要先除以1.05。", "distractors": {"B": "正確為 $22,850,此選項差 $50。", "C": "正確為 $12,500,誤把退稅限額算成 $12,750。", "D": "$12,500 其實是 (C) 的正確金額,而非本期累積留抵稅額。"}}, "check": "python 獨立計算:銷項 30,900、進項 43,750、(A)=53,750、(B)=22,850、(C)=12,500、(D)=10,350。與官方相符。", "verified": true, "note": "試題選項 (B)22,900 與官方詳解算得 22,850 略有出入,但不影響答案為(A)。"}, {"id": "113-1-A-13", "exam": "113-1", "paper": "A", "q": 13, "unit": "六、試算與試算表", "topic": "錯誤更正", "stem": "下列敘述何者錯誤?", "options": ["試算表不平衡如為數字移位或換位錯誤,其差額可被9除盡", "當試算表發現不平衡的錯誤,實務上常用「逆查法」按會計程序的相反順序「試算、過帳、分錄」檢查", "賒購商品誤記為賒銷商品,於過帳後才發現者,應採註銷更正法", "應付票據貸方 $3,000 誤過入借方,應採註銷更正法"], "answer": "C", "figure": null, "official": "(C)賒購商品誤記為賒銷商品為不影響借貸平衡的錯誤,於過帳後才發現,應採分錄更正法。", "explain": {"concept": "錯誤更正:註銷更正法 vs. 分錄更正法。", "steps": ["註銷更正法只用在「影響借貸平衡」的錯誤且「過帳前」或「過帳時」記錯方向者(如把貸方金額過入借方)。", "分錄更正法用在「不影響借貸平衡」的錯誤(如科目記錯)且在過帳後才發現者。", "(C)賒購誤記賒銷是科目記錯,借貸仍平衡,過帳後發現,要用分錄更正法,所以(C)錯。", "(D)貸方過成借方,借貸不平衡,用註銷更正法,正確。", "(A)(B)為試算表查錯的常識,正確。"], "pitfalls": "錯誤是否影響借貸平衡,是選方法的關鍵。", "distractors": {"A": "敘述正確。", "B": "敘述正確。", "D": "敘述正確。"}}, "check": "概念題,依官方詳解確認。", "verified": true, "note": ""}, {"id": "113-1-A-14", "exam": "113-1", "paper": "A", "q": 14, "unit": "九、財務報表", "topic": "財務比率分析", "stem": "有關財務報表分析,下列敘述何者正確?", "options": ["流動比率大於1時,用現金償還應付帳款會使流動比率下降", "流動比率小於1時,採權責發生基礎入帳,賒購文具用品會使流動比率上升", "速動比率小於1時,期末將已實現之預付費用轉為費用,會使速動比率下降", "現金償還短期借款,營運資金會減少"], "answer": "B", "figure": null, "official": "(A)現金償還應付帳款使流動資產與流動負債同減,流動比率>1時會增加;(B)採權責發生基礎賒購文具用品,借用品盤存、貸應付帳款,流動資產與流動負債同額增加,流動比率小於1時會上升;(C)預付費用不屬速動資產,速動比率不變;(D)營運資金不變。", "explain": {"concept": "流動比率、速動比率、營運資金受各交易影響的方向。", "steps": ["流動比率=流動資產÷流動負債。若比率大於1,同額減少分子分母→比率上升;若小於1,同額增加分子分母→比率上升。", "(B)官方詳解:採權責發生制賒購文具用品,借「用品盤存」(資產)、貸「應付帳款」(流動負債),流動資產與流動負債同額增加。比率<1 時,分子分母同加同一數會使比率上升,所以(B)正確。", "(A)現金還應付帳款,流動資產、流動負債同減,比率>1時會增加,不是下降。", "(C)預付費用不屬於速動資產,轉為費用時速動資產不變,速動比率不變。", "(D)現金還短期借款,流動資產與流動負債同減,營運資金(流動資產-流動負債)不變。"], "pitfalls": "同額增減分子分母對比率的影響,要先看比率大於或小於1。", "distractors": {"A": "忘了比率>1時,分子分母同減會使比率變大。", "C": "誤以為預付費用是速動資產。", "D": "還款使資產負債同減,營運資金不變。"}}, "check": "概念題,官方詳解確認,並以數字代入(如流動資產 40、流動負債 80)檢驗方向。", "verified": true, "note": "官方詳解對(B)的文字描述略簡,已於解析中補充。"}, {"id": "113-1-A-15", "exam": "113-1", "paper": "A", "q": 15, "unit": "七、調整", "topic": "調整後淨利", "stem": "高雄公司 112 年底調整前試算表上之收益為 $100,000,費用為 $51,000,有下列須調整之事項:預收收入已實現部分為 $7,500,本期折舊 $3,600,已賺得但尚未入帳之收益為 $6,000,12 月份薪資 $7,000 預計於次年 1 月發放,則高雄公司 112 年度正確之淨利為何?(不考慮所得稅影響)", "options": ["$36,900", "$44,400", "$48,000", "$51,900"], "answer": "D", "figure": null, "official": "調整後收益=$100,000+$7,500+$6,000=$113,500;調整後費用=$51,000+$3,600+$7,000=$61,600;淨利=$113,500-$61,600=$51,900。", "explain": {"concept": "調整後淨利=調整後收益-調整後費用。", "steps": ["先分辨每項調整是影響收益還是費用。", "預收收入已實現 $7,500:收益增加 → $100,000+$7,500。", "已賺得尚未入帳的收益 $6,000(應收收益):收益增加。調整後收益=$100,000+$7,500+$6,000=$113,500。", "本期折舊 $3,600:費用增加;12月薪資 $7,000 尚未發放(應付薪資):費用增加。調整後費用=$51,000+$3,600+$7,000=$61,600。", "淨利=$113,500-$61,600=$51,900,選(D)。"], "pitfalls": "把預收收入實現或應收收益當成費用,或漏調整某一項。", "distractors": {"B": "差額剛好是預收收入實現 $7,500,漏加收益。"}}, "check": "python:100000+7500+6000-(51000+3600+7000)=51,900,與官方相符。", "verified": true, "note": ""}, {"id": "113-1-A-16", "exam": "113-1", "paper": "A", "q": 16, "unit": "七、調整", "topic": "應收租金", "stem": "臺南公司 112 年初於國華街之透天大樓決定出租空置多時位於國華街之透天大樓,租賃契約簽訂時,註明每月月初承租廠商應支付當月份之固定租金 $100,000,另按承租廠商全年營業額超過 $3,000,000 部分之 5% 額外收取變動租金,並於次年 1 月 5 日前支付。承租廠商 112 年度結算後全年營業額為 $5,000,000,則有關臺南公司該租約於 112 年底之應收租金為何?", "options": ["$0", "$15,000", "$100,000", "$200,000"], "answer": "C", "figure": null, "official": "變動租金($5,000,000-$3,000,000)×5%=$100,000。固定租金每月月初已收,故年底應收租金僅變動租金 $100,000。", "explain": {"concept": "應收收益:已賺得但尚未收到的租金。", "steps": ["固定租金是每月月初預先收取,年底不會有未收的固定租金。", "變動租金按營業額超過 $3,000,000 的部分收 5%:($5,000,000-$3,000,000)×5%=$2,000,000×5%=$100,000。", "變動租金要到次年1月5日才收,112年底已賺得但尚未收到,所以記「應收租金 $100,000」。", "答案選(C)。"], "pitfalls": "誤以為固定租金也有未收,或忘了要扣掉免計變動租金的基數 $3,000,000。", "distractors": {"D": "把固定租金 $100,000 加上變動租金 $100,000,但固定租金已收。"}}, "check": "python:(5,000,000-3,000,000)×5%=100,000,與官方相符。", "verified": true, "note": ""}, {"id": "113-1-A-17", "exam": "113-1", "paper": "A", "q": 17, "unit": "十、加值型營業稅會計實務", "topic": "進項稅額分錄", "stem": "池上公司賒購貨用卡車一部 $250,000,加計 5% 營業稅,另現付本年度牌照稅 $2,000,該公司慣例將每年皆須繳納之費用以費損入帳,則下列何者為正確分錄?", "options": ["借:運輸設備成本 $250,000、進項稅額 $12,500、稅捐 $2,000,貸:應付設備款 $262,500、現金 $2,000", "借:運輸設備成本 $252,000、進項稅額 $12,600,貸:應付設備款 $262,600、現金 $2,000", "借:運輸設備成本 $252,000、進項稅額 $12,500、稅捐 $2,000,貸:應付設備款 $266,500", "借:運輸設備成本 $264,600,貸:應付設備款 $262,600、現金 $2,000"], "answer": "A", "figure": null, "official": "牌照稅為每年皆須支付費用,不能列入資產加項。", "explain": {"concept": "購買資產的進項稅額與牌照稅處理。", "steps": ["卡車價款 $250,000,營業稅=$250,000×5%=$12,500,稅額記「進項稅額」(可扣抵),不計入資產成本。", "應付設備款=$250,000+$12,500=$262,500。", "牌照稅每年都要繳,屬於期間性費用,應記「稅捐」$2,000,不能加到卡車成本。", "分錄:借運輸設備成本 250,000、進項稅額 12,500、稅捐 2,000;貸應付設備款 262,500、現金 2,000。借貸各 264,500,平衡。選(A)。"], "pitfalls": "把牌照稅資本化,或把進項稅額算錯。", "distractors": {"B": "把牌照稅 $2,000 加進設備成本,並用 $252,000×5% 算稅額。", "C": "貸方漏列現金,應付設備款也多算。", "D": "把進項稅額併入設備成本。"}}, "check": "python:250,000×5%=12,500;借 264,500=貸 262,500+2,000,平衡。", "verified": true, "note": ""}, {"id": "113-1-A-18", "exam": "113-1", "paper": "A", "q": 18, "unit": "八、結帳", "topic": "結帳概念", "stem": "有關結帳之敘述,下列何者正確?", "options": ["獨資企業若發生淨損時,借記「本期損益」、貸記「業主往來」", "結帳分錄若漏記,將導致結帳後試算表不平衡", "根據結帳後試算表可以編製綜合損益表", "結帳後所有虛帳戶將結清歸零"], "answer": "D", "figure": null, "official": "(A)獨資企業淨損時應借記「業主往來」、貸記「本期損益」;(B)整筆分錄漏記不會導致結帳後試算表不平衡;(C)結帳後試算表可編製資產負債表。", "explain": {"concept": "結帳的目的與結果。", "steps": ["結帳就是把收入、費用等虛帳戶結清,轉入權益。", "(D)結帳後所有虛帳戶(收入、費用)餘額都歸零,正確。", "(A)淨損時,損失要減少業主權益:借「業主往來」,貸「本期損益」。選項寫反。", "(B)整筆結帳分錄漏記,借貸仍然平衡(只是虛帳戶沒結清)。", "(C)結帳後試算表只剩實帳戶,可編資產負債表;綜合損益表要用結帳前資料。"], "pitfalls": "忘了淨損時分錄方向是反過來的。", "distractors": {"A": "淨損與淨利的分錄方向搞混。", "B": "整筆漏記時借貸仍平衡。", "C": "結帳後只剩實帳戶,只能編資產負債表。"}}, "check": "概念題,依官方詳解確認。", "verified": true, "note": ""}, {"id": "113-1-A-19", "exam": "113-1", "paper": "A", "q": 19, "unit": "十二、應收款項", "topic": "日記簿判讀", "stem": "高雄公司部分日記簿記錄如下,根據所作分錄判斷,下列何者正確?\n\n日記簿(112年)\n\n| 月/日 | 會計項目 | 摘要 | 借方金額 | 貸方金額 |\n|---|---|---|---|---|\n| 4/3 | 用品盤存 | 購買文具 | 5,000 |  |\n|  | 　現金 |  |  | 5,000 |\n| 4/5 | 應收帳款 |  | 100,000 |  |\n|  | 　銷貨收入 |  |  | 100,000 |\n| 4/5 | 銷貨成本 | 4/5銷貨 | 75,000 |  |\n|  | 　存貨 |  |  | 75,000 |\n| 4/14 | 現金 | 收回4/5帳款 | 97,000 |  |\n|  | 銷貨折讓 |  | 3,000 |  |\n|  | 　應收帳款 |  |  | 100,000 |\n| …… | …… |  |  |  |\n| 12/31 | 存貨 |  | 2,000 |  |\n|  | 　銷貨成本 |  |  | 2,000 |\n| 12/31 | 薪資支出 |  | 100,000 |  |\n|  | 　應付薪資 |  |  | 100,000 |", "options": ["該公司會計基礎採用現金基礎", "該公司遞延項目採用先虛後實法記帳", "該公司收款現金折扣條件為 2/10,n/30", "該公司年底期末盤存貨時,帳上存貨小於實際存貨"], "answer": "D", "figure": null, "official": "官方更正:12/31調整分錄為借:存貨2,000、貸:銷貨成本2,000,本題開放送分。", "explain": {"concept": "由日記簿分錄判斷會計基礎、遞延項目記帳法、折扣條件與存貨調整。", "steps": ["(A)有賒銷記應收帳款、有應付薪資,是權責發生基礎,不是現金基礎,錯。", "(B)4/3購買文具借「用品盤存」(資產),是先實後虛法,不是先虛後實,錯。", "(C)4/14收款 $100,000,折讓 $3,000 即 3%,10天內還款(4/5→4/14共9天),所以條件應是 3/10,n/30,不是 2/10,錯。", "(D)依更正後的12/31調整分錄:借存貨 2,000、貸銷貨成本 2,000,表示帳上存貨比實際盤點少,要補記,故正確。", "官方因題目圖表更正,本題送分。"], "pitfalls": "看分錄方向時要先弄清借貸代表帳上多或少。", "distractors": {"A": "有賒銷與應付薪資,是權責發生基礎。", "B": "購入文具記資產(用品盤存)是先實後虛。", "C": "折讓 3,000÷100,000=3%,應為 3/10,n/30。"}}, "check": "概念題,依官方更正(送分)。", "verified": true, "note": "官方更正:12/31調整分錄更正為借:存貨2,000、貸:銷貨成本2,000(原卷印成借銷貨成本、貸存貨),本題送分。本卷已依更正後分錄抄錄。答案表原為D。", "accept_all": true}, {"id": "113-1-A-20", "exam": "113-1", "paper": "A", "q": 20, "unit": "一、會計基本概念", "topic": "會計資訊使用者", "stem": "光光初入職場,預計將第一份薪水的全額用來購買白日光海運公司的股票,下列敘述何者正確?", "options": ["光光可以利用白日光海運公司的會計資訊瞭解營運及財務狀況,幫助決定是否增減投資金額,因此判定會計的財務資訊僅供投資人使用", "會計資訊只對企業外部使用者有用,對企業內部使用者的決策沒有幫助", "該公司的總經理為會計資訊的內部使用者,光光可稱是會計資訊的外部使用者", "白日光海運公司係依公司法組織設立登記,以營利為目的之財團法人"], "answer": "C", "figure": null, "official": "(A)會計資訊供內、外部使用者使用;(B)會計資訊對企業內部、外部使用者的決策都有幫助;(D)公司是以營利為目的之社團法人。", "explain": {"concept": "會計資訊的使用者區分為內部與外部。", "steps": ["總經理在公司內部,是內部使用者;光光是投資人,在公司外部,是外部使用者。所以(C)正確。", "(A)會計資訊不只投資人用,還有債權人、政府、管理階層等。", "(B)內部使用者(管理階層)也需要會計資訊決策。", "(D)公司是由「人」(股東)組成的團體,為社團法人,不是財團法人(財團法人是捐助財產成立)。"], "pitfalls": "把公司誤認為財團法人。", "distractors": {"A": "誤以為財務資訊只供投資人使用。", "B": "誤以為只對外部有用。", "D": "社團法人與財團法人搞混。"}}, "check": "概念題,依官方詳解確認。", "verified": true, "note": ""}, {"id": "113-1-A-21", "exam": "113-1", "paper": "A", "q": 21, "unit": "七、調整", "topic": "權責與現金基礎轉換", "stem": "新竹公司 112 年度綜合損益表列示之租金收入為 $56,000,其他相關資料如下,則 112 年度實際收現之租金收入金額為何?\n\n| 項目 | 112 年期初餘額 | 112 年期末餘額 |\n|---|---|---|\n| 預收租金 | $13,000 | $16,000 |\n| 應收租金 | $8,000 | $4,500 |", "options": ["$49,500", "$62,500", "$64,500", "$69,500"], "answer": "B", "figure": null, "official": "權責基礎轉現金基礎:$56,000+$8,000-$4,500-$13,000+$16,000=$62,500。", "explain": {"concept": "權責基礎收入轉現金基礎收入:應收減少加、預收增加加。", "steps": ["損益表的 $56,000 是權責基礎(賺到就算)。要換成「實際收到的現金」。", "應收租金:期初 $8,000 本年收現了(加);期末 $4,500 還沒收到(減)。", "預收租金:期初 $13,000 是以前收的,今年才認列收入,今年沒有收現(減);期末 $16,000 是今年先收下一年的錢(加)。", "現金基礎=$56,000+$8,000-$4,500-$13,000+$16,000=$62,500,選(B)。"], "pitfalls": "應收、預收的加減方向最容易搞反。", "distractors": {}}, "check": "python:56,000+8,000-4,500-13,000+16,000=62,500,與官方相符。", "verified": true, "note": ""}, {"id": "113-1-A-22", "exam": "113-1", "paper": "A", "q": 22, "unit": "十三、存貨", "topic": "銷貨成本計算", "stem": "公司今年度部分帳戶資料如下:進貨$55,000、進貨費用$2,000、運費$7,500、進貨退出與折讓$13,000、期初存貨$37,000、期末盤點商品剩餘$14,000,若商品帳戶之結帳採銷貨成本法,則銷貨成本金額為何?", "options": ["$43,000", "$44,000", "$67,000", "$76,500"], "answer": "C", "figure": null, "official": "銷貨成本=$37,000+$55,000+$2,000-$13,000-$14,000=$67,000。", "explain": {"concept": "定期盤存制銷貨成本=期初存貨+淨進貨-期末存貨。", "steps": ["銷貨成本=期初存貨+本期進貨成本-期末存貨。", "進貨成本=進貨 $55,000+進貨費用 $2,000-進貨退出與折讓 $13,000=$44,000。", "運費 $7,500 是出貨給客戶的運費(銷貨運費),屬營業費用,不列入進貨成本。", "銷貨成本=$37,000+$44,000-$14,000=$67,000,選(C)。"], "pitfalls": "不要把銷貨運費加進進貨成本。", "distractors": {"B": "只算出淨進貨 $44,000,忘了加減期初與期末存貨。"}}, "check": "python:37,000+55,000+2,000-13,000-14,000=67,000,與官方相符。", "verified": true, "note": ""}, {"id": "113-1-A-23", "exam": "113-1", "paper": "A", "q": 23, "unit": "一、會計基本概念", "topic": "營業費用判斷", "stem": "下列交易何者會導致營業費用增加?", "options": ["商品採定期盤存制時,購買商品所應負擔的運費", "認列預期信用減損利益", "購買營業用機器設備所需支付之安裝費", "支付招待客戶的餐費"], "answer": "D", "figure": null, "official": "(A)進貨費用,銷貨成本加項;(B)預期信用減損利益為營業費用減項;(C)機器設備成本加項;(D)交際費為營業費用加項。", "explain": {"concept": "分辨哪些支出算費用、哪些算成本。", "steps": ["(D)招待客戶餐費記「交際費」,屬營業費用,使營業費用增加。", "(A)定期盤存制下,購貨運費記進貨費用,最後計入銷貨成本,不是營業費用。", "(B)預期信用減損利益是沖回,會使營業費用減少。", "(C)機器安裝費要加入機器設備成本,資本化,不是費用。"], "pitfalls": "把進貨運費、安裝費當成營業費用。", "distractors": {"A": "進貨運費屬銷貨成本。", "B": "利益會減少營業費用。", "C": "安裝費屬資產成本。"}}, "check": "概念題,依官方詳解確認。", "verified": true, "note": ""}, {"id": "113-1-A-24", "exam": "113-1", "paper": "A", "q": 24, "unit": "一、會計基本概念", "topic": "會計恆等式推算", "stem": "閱讀下文,回答第24-25題\n小洋畢業之後決定暫不升學,希望可以將高中三年所學專業課程學以致用,故向主管機關進行公司設立及營業登記,聘任同學小明為主辦會計人員,採電腦化處理會計事務,並擇期於112年8月正式開始營業:\n(一)該公司112年12月31日資產負債表中流動資產、非流動資產、負債與權益等皆為200萬元;負債項目中包含流動負債(應付帳款與短期借款各50萬元)與非流動負債100萬元。112年度銷貨收入為100萬元,純益率20%。目前產能已充分利用,113年度銷貨收入成長25%,純益率仍維持20%,另外小洋因公司前景看好,113年初再增資10萬元,除上述外,113年度結帳前權益項目無其他變動。113年12月31日流動資產、非流動資產隨銷貨收入而成長了30%,非流動負債不變、應付帳款增加至70萬元。\n(二)營運資金管理與公司的營業利益與短期償債能力有著非常顯著的關係,營運初期公司現金流量不足,負責人小洋為了少繳納營業稅,因此指示會計人員小明漏報營業額。\n\n24. 在公司流動負債仍維持僅有應付帳款及短期借款兩項之下,113年底公司短期借款比起去年底增加金額應為多少?", "options": ["30萬元", "65萬元", "70萬元", "135萬元"], "answer": "B", "figure": null, "official": "113年底:資產總額=260+260=520萬;權益=200+10+25=235萬;短期借款=520-235-70-100=115萬;113年底短期借款比112年底50萬增加65萬。", "explain": {"concept": "資產=負債+權益,倒推未知的短期借款。", "steps": ["先算 113 年底資產:流動資產 200 萬×(1+30%)=260 萬;非流動資產 200 萬×(1+30%)=260 萬;合計 520 萬。", "再算 113 年底權益:112 年底權益 200 萬+增資 10 萬+本期損益。", "113 年銷貨收入=100 萬×(1+25%)=125 萬,純益=125 萬×20%=25 萬。權益=200+10+25=235 萬。", "負債=資產-權益=520-235=285 萬。", "負債=應付帳款 70 萬+短期借款+非流動負債 100 萬 → 短期借款=285-70-100=115 萬。", "112 年底短期借款 50 萬,所以增加 115-50=65 萬,選(B)。"], "pitfalls": "容易漏掉增資10萬,或把純益算成 100 萬×20%。", "distractors": {}}, "check": "python asserts:520-235-70-100=115,115-50=65,與官方相符。", "verified": true, "note": "第24~25題為題組,題幹共用。"}, {"id": "113-1-A-25", "exam": "113-1", "paper": "A", "q": 25, "unit": "一、會計基本概念", "topic": "商業會計法罰則", "stem": "(題組:同第24題小洋公司情境)有關漏報營業稅,下列敘述何者正確?", "options": ["負責人小洋與會計人員小明都將處五年以下有期徒刑、拘役或科或併科新臺幣六十萬元以下罰金", "使用電腦化記帳,故不必保存會計憑證及財務報表", "小明身為會計人員登錄不實的會計資料,是因聽從負責人的指示,就可免除刑責與罰金", "該公司與外國公司貿易為大宗,基於簡化作帳程序原則,財務報表可使用外國貨幣記帳"], "answer": "A", "figure": null, "official": "(B)使用電腦化記帳,仍須保存會計憑證及財務報表;(C)會計人員登錄不實,不論是否聽從負責人指示,都須負刑責與罰金;(D)財務報表需使用本國貨幣記帳。", "explain": {"concept": "商業會計法對登載不實的刑責規定。", "steps": ["商業會計法規定:商業負責人、主辦會計人員等,以明知不實事項登載於會計憑證、帳簿、報表,處五年以下有期徒刑、拘役或科或併科新臺幣六十萬元以下罰金。所以(A)正確。", "(B)電腦化記帳仍必須保存憑證、報表,只是保存方式不同。", "(C)聽命負責人不能免責,會計人員同樣有責任。", "(D)財務報表應以本國貨幣為記帳單位。"], "pitfalls": "以為聽命行事就可免責。", "distractors": {"B": "電腦記帳仍須保存憑證與報表。", "C": "聽從指示不免責。", "D": "應以本國貨幣為單位。"}}, "check": "概念題,依官方詳解與商業會計法確認。", "verified": true, "note": "題幹為「漏報營業稅」,依官方答案(A)。單元歸一(商業會計法)。"}, {"id": "113-2-A-01", "exam": "113-2", "paper": "A", "q": 1, "unit": "一、會計基本概念", "topic": "組織型態與會計資訊使用者", "stem": "小蝸為食品加工業之員工,本身具備多項才能,為追求生活的多樣性並創造個人工作成就感,便開始斜槓經營副業,辦理商業廣告有限公司之工商登記,運用下班或假日之餘接案,有關小蝸所設立的組織型態,下列敘述何者錯誤?", "options": ["有限公司出資者所負責任有限,並具有法人資格", "小蝸委託記帳及報稅代理人代為處理會計事務,定期交付公司營收與費用之相關憑證辦理稅務申報,記帳及報稅代理人定期提供會計資訊給予小蝸,小蝸為內部資訊使用者", "該組織僅為小蝸斜槓經營之副業,屬於非以營利為目的之社團法人", "平時帳務之記載適用中華民國會計研究發展基金會所制定之企業會計準則公報及其解釋"], "answer": "C", "figure": null, "official": "有限公司是以營利為目的之社團法人。", "explain": {"concept": "本題考公司組織型態:有限公司是營利社團法人,以及會計資訊使用者的分類。", "steps": ["題目問「錯誤」的選項,所以要逐項找出說錯的那一個。", "看 (A):有限公司股東以出資額為限負責任,且為法人,正確。", "看 (B):小蝸是公司的經營者,屬於公司內部的資訊使用者,正確。", "看 (C):公司登記設立的商業廣告有限公司,目的是接案賺錢,是「以營利為目的」的社團法人,不是非營利法人。即使只是副業,只要設立目的是營利,就屬營利法人,所以 (C) 敘述錯誤。", "看 (D):一般企業記帳依企業會計準則公報及其解釋,正確。所以答案選 (C)。"], "pitfalls": "「副業」「斜槓」只是經營的投入程度,不會改變公司是營利法人的本質;不要被題幹情境誤導。", "distractors": {"A": "這是正確敘述,不是題目要找的錯誤。", "B": "這是正確敘述:公司的經營者屬內部資訊使用者。", "D": "這是正確敘述:適用企業會計準則。"}}, "check": "概念題:對照公司法與商業會計法常識,有限公司為營利社團法人,與官方詳解一致。", "verified": true, "note": ""}, {"id": "113-2-A-02", "exam": "113-2", "paper": "A", "q": 2, "unit": "二、會計循環及會計帳簿", "topic": "帳簿種類與會計循環", "stem": "下列敘述哪幾項正確?\n①應付帳款明細帳係以供應商作為設立依據,並可據以查詢本公司待清償之貨款餘額\n②帳務處理程序中,「分錄、過帳、試算」為平時之營業循環\n③年度決算之財務報表須依法至少保存十年\n④日記簿及特種序時帳簿之現金簿,記載企業一般及常見的現金交易,故為商業會計法規定必須設置之帳簿", "options": ["①③", "②④", "②③④", "①②③④"], "answer": "A", "figure": null, "official": "「分錄、過帳、試算」為平時之「會計」循環;特種序時帳簿之現金簿為視企業個別需要設置,並非必須設置。", "explain": {"concept": "考會計帳簿的設置依據、會計循環名稱與帳簿保存年限。", "steps": ["看 ①:應付帳款明細帳是依「供應商」(債權人)設帳戶,可查還欠誰多少錢,正確。", "看 ②:分錄、過帳、試算是「平時」的會計工作,稱為「會計循環」;「營業循環」指現金→存貨→應收帳款→現金這類營運流程,兩者不同,所以 ② 錯誤。", "看 ③:依商業會計法,會計憑證、帳簿、報表等有保存年限,年度決算財務報表須至少保存十年,正確。", "看 ④:商業會計法規定必須設置的序時帳簿是「日記簿」;特種序時帳簿(如現金簿)是企業視交易需要才設,不是法定必設,所以 ④ 錯誤。", "正確的是 ①③,選 (A)。"], "pitfalls": "「會計循環」和「營業循環」名稱很像,別混淆;另外「日記簿」是必設,「特種日記簿」是選設。", "distractors": {"B": "選②④的人誤把兩個錯誤敘述當成正確。", "C": "把 ②④ 當正確,又漏了 ① 的正確敘述。", "D": "以為四項都對,沒有分辨出 ②④ 的細節錯誤。"}}, "check": "概念題:官方詳解指出 ② 應為「會計」循環、④ 現金簿為視需要設置;對照商業會計法常識一致。", "verified": true, "note": ""}, {"id": "113-2-A-03", "exam": "113-2", "paper": "A", "q": 3, "unit": "一、會計基本概念", "topic": "會計基本假設", "stem": "有關會計基本假設之敘述,下列何者正確?", "options": ["根據財務報導之觀念架構,財務報表的基本假設為企業個體假設", "企業購入載貨用卡車以成本入帳,依預估使用年限逐期分攤為費用,係繼續經營假設之應用", "企業因店住合一,租金支出全數認列為企業之費用,係違反貨幣評價假設", "企業就到期日之長短將負債劃分為流動負債與非流動負債,係根據報導期間假設"], "answer": "B", "figure": null, "official": "(A) 根據財務報導之觀念架構,財務報表的基本假設為繼續經營假設;(C) 係違反企業個體假設;(D) 係根據繼續經營假設。", "explain": {"concept": "考會計基本假設(企業個體、繼續經營、會計期間、貨幣評價)各自對應的應用。", "steps": ["(A):現行財務報導觀念架構中,財務報表的基本假設是「繼續經營假設」,不是企業個體假設,所以錯。", "(B):卡車預期會長期使用,才會把成本依年限分攤成折舊費用,這是「企業會繼續經營下去」的假設,正確。", "(C):店面和住家合一,卻把全部租金當企業費用,是把個人與企業的支出混在一起,違反「企業個體假設」,不是貨幣評價假設。", "(D):流動與非流動負債是看「企業會繼續營運」下的到期時間,屬繼續經營假設的應用。", "所以選 (B)。"], "pitfalls": "看到「分攤、折舊、流動/非流動分類」就想到繼續經營;看到「公私混在一起」就想到企業個體。", "distractors": {"A": "把企業個體假設誤當成財務報表的基本假設。", "C": "公私混用的問題對應企業個體假設,不是貨幣評價。", "D": "流動/非流動的劃分是繼續經營假設的應用,不是報導期間假設。"}}, "check": "概念題:與官方詳解一致,並對照會計基本假設常識。", "verified": true, "note": ""}, {"id": "113-2-A-04", "exam": "113-2", "paper": "A", "q": 4, "unit": "一、會計基本概念", "topic": "交易與會計要素變動", "stem": "欣欣電器行採永續盤存制,有關交易與影響財務報表要素變動的敘述,下列何者正確?", "options": ["業主自企業提取店內商品餽贈友人,屬於內部交易,使得企業的權益及資產均減少", "受颱風影響電器行之商品泡水受損,屬於外部交易,使得企業的費損及資產均減少", "與銀行簽訂透支契約,屬於外部交易,使得企業的資產及負債均增加", "員工出差返程報支旅費給予現金,屬於外部交易,使得企業的資產及權益均減少"], "answer": "D", "figure": null, "official": "(A) 業主自企業提取店內商品餽贈友人,屬於外部交易,使企業權益及資產均減少;(B) 受颱風影響商品泡水受損,屬於內部交易,使企業費損增加及資產減少;(C) 簽訂透支契約非屬交易,企業的要素變化無影響。", "explain": {"concept": "考交易的內外部分類,以及交易對資產、負債、權益的影響。", "steps": ["(A):業主提取商品,資產(存貨)減少、業主權益(提取)減少,屬外部交易(涉及業主),題目說「內部交易」所以錯。", "(B):颱風造成商品損失是企業內部財產損失,屬內部交易,不是外部交易,而且是「費損增加、資產減少」,題目說外部所以錯。", "(C):只是簽訂透支「契約」,尚未實際透支,不是會計上的交易,資產負債都不變,所以錯。", "(D):報支旅費付現金,現金(資產)減少,旅費(費用)增加使權益減少,為外部交易,資產與權益均減少,正確。", "所以選 (D)。"], "pitfalls": "分辨內部交易(只在企業內部產生,如損失、折舊)與外部交易(與外界往來);「契約」不等於「交易」,要有實際資源流動才入帳。", "distractors": {"A": "業主提取商品涉及業主,官方歸為外部交易。", "B": "颱風損失是內部交易,不是外部交易。", "C": "簽訂透支契約非屬交易,要素不會變動。"}}, "check": "概念題:與官方詳解一致;(D) 為現金支付旅費,資產減、費用增使權益減,分錄驗證成立。", "verified": true, "note": "單元歸類可能有爭議(一或三)"}, {"id": "113-2-A-05", "exam": "113-2", "paper": "A", "q": 5, "unit": "一、會計基本概念", "topic": "會計恆等式與當期損益", "stem": "福興公司年底結帳前資產總額$222,000,結帳前權益總額$100,000;結帳後權益總額與負債總額之比為4:2;已知當年度收益與費損之比為5:3,則當期收益之金額為何?", "options": ["$72,000", "$120,000", "$148,000", "$185,000"], "answer": "B", "figure": null, "official": "期末資產$222,000,權益:負債=4:2,得期末權益$148,000;結帳前權益$100,000+5Y-3Y=$148,000,Y=$24,000,收益=5Y=$120,000。", "explain": {"concept": "用會計恆等式「資產=負債+權益」求結帳後權益,再用「期末權益=期初權益+收益-費損」反推收益。", "steps": ["結帳前後資產總額不變(結帳只動權益內部的科目),所以期末資產=$222,000。", "期末權益:負債=4:2,所以權益占 4/(4+2)=2/3,期末權益=$222,000×4/6=$148,000(負債=$74,000)。", "當年度收益:費損=5:3,設收益=5Y、費損=3Y。", "結帳後權益=結帳前權益+收益-費損:$100,000+5Y-3Y=$148,000。", "2Y=$48,000,Y=$24,000。", "收益=5Y=5×$24,000=$120,000,選 (B)。(費損=3×$24,000=$72,000)"], "pitfalls": "別把 (A) $72,000 的「費損」當成答案;題目問的是「收益」。", "distractors": {"A": "$72,000 是費損(3Y),題目問的是收益。", "C": "$148,000 是結帳後的期末權益,不是收益。"}}, "check": "python:期末權益=222000×4/6=148000;2Y=48000→Y=24000;收益=120000,與官方相符。", "verified": true, "note": ""}, {"id": "113-2-A-06", "exam": "113-2", "paper": "A", "q": 6, "unit": "二、會計循環及會計帳簿", "topic": "傳票與交易類型", "stem": "在不考慮營業稅的情況下,有關複式傳票之敘述何者正確?", "options": ["企業伙食部門的員工於市場現購的食材因故未能取得原始憑證,由經手人出具之支出證明單經主管核章申請核銷,依三分法此交易應編製現金支出傳票,此支出證明單視為內部憑證", "企業銷售部門接獲客戶訂購商品一批,收取一成貨款作為訂金,依三分法應編製現金收入傳票,此交易屬於複雜交易", "企業購買生產產品之機械手臂一部,以現金支付三分之一款項,餘開立四個月期支票,依四分法應編製現金轉帳傳票,此交易屬於混合交易", "前向供應商賒購商品一批$40,000,支付貨款時取得1%現金折扣,依四分法應編製分錄轉帳傳票,此交易屬於轉帳交易"], "answer": "C", "figure": null, "official": "(A) 支出證明單視為外來憑證;(B) 借:現金,貸:預收貨款,屬簡單交易;(D) 借:應付帳款$40,000,貸:進貨折讓$400,現金$39,600,四分法應編製現金轉帳傳票,屬於混合交易。", "explain": {"concept": "考憑證種類、簡單/複雜交易,以及傳票(三分法、四分法)的對應。", "steps": ["先記住分類:交易只涉及現金「一收」或「一付」且借貸各一個科目→簡單交易;借方或貸方有多個科目→複雜交易;部分現金、部分轉帳→混合交易。", "(A):支出證明單是用來代替取不到的原始憑證,官方詳解認定它視為「外來憑證」,選項說「內部憑證」所以錯。", "(B):收一成貨款作訂金:借現金、貸預收貨款,借貸各一個科目,是簡單交易,不是複雜交易。", "(C):機械手臂以現金付三分之一、其餘開支票(票據,屬轉帳性質):借 機械設備、貸 現金 與 應付票據,同時有現金與轉帳,是混合交易,四分法編現金轉帳傳票,正確。", "(D):付款取得1%現金折扣:借 應付帳款 $40,000;貸 進貨折讓 $400、現金 $39,600,有現金收付又有轉帳成分,應是混合交易,編現金轉帳傳票,不是分錄轉帳傳票。", "所以選 (C)。"], "pitfalls": "四分法的傳票:現金收入、現金支出、現金轉帳(混合交易)、分錄轉帳(完全不涉及現金)。只要有現金一部分,就不是純轉帳交易。", "distractors": {"A": "把支出證明單當成內部憑證;官方認定視為外來憑證。", "B": "收訂金只有「借現金、貸預收貨款」,是簡單交易,誤以為是複雜交易。", "D": "付款有現金流出,不是純轉帳,應為現金轉帳傳票(混合交易)。"}}, "check": "概念題:對照官方詳解,(B)(D) 說明明確。", "verified": true, "note": "(A) 選項的憑證種類官方寫為「外來憑證」,題幹選項寫「內部憑證」,以官方答案 C 為準;解析中對 (A) 的說明已盡量保守。"}, {"id": "113-2-A-07", "exam": "113-2", "paper": "A", "q": 7, "unit": "二、會計循環及會計帳簿", "topic": "日記簿的特性", "stem": "有關日記簿之敘述,下列何者正確?", "options": ["日記簿按交易時序登帳,可瞭解交易的全貌", "日記簿之分錄可作為編表之依據,又稱終結記錄簿", "日記簿之交易不得跨頁記帳,借貸金額合計數需轉載至次頁", "日記簿係以交易為記錄主體,屬於橫的記錄"], "answer": "A", "figure": null, "official": "(B) 日記簿之分錄可作為過帳之依據,又稱原始記錄簿;(C) 日記簿合計數不需轉記至次頁;(D) 日記簿屬於縱的記錄。", "explain": {"concept": "考日記簿(序時帳簿)的性質:按時間順序、以交易為單位記錄。", "steps": ["日記簿依交易發生的「先後順序」登載,所以叫「序時帳簿」,而且一筆交易的借貸科目都在一起,可看見交易全貌,(A) 正確。", "(B):日記簿分錄是「過帳」的依據,它是「原始記錄簿」(最先記下的帳簿);「終結記錄簿」指的是分類帳。", "(C):日記簿的交易可以跨頁,合計數不需轉載至次頁(是否轉頁看帳頁格式與規定),官方認定此說法錯誤。", "(D):日記簿以「交易」為記錄主體,依時間往下一筆接一筆記,屬於「縱的記錄」,不是橫的。"], "pitfalls": "日記簿=原始記錄簿、序時帳簿;分類帳=終結記錄簿、分類帳簿,別顛倒。", "distractors": {"B": "把日記簿和分類帳的角色(原始/終結)弄反。", "C": "以為日記簿像分類帳要每頁小計後轉頁。", "D": "把「縱的記錄」誤記成「橫的記錄」。"}}, "check": "概念題:與官方詳解一致。", "verified": true, "note": "單元歸類可能有爭議(二或四)"}, {"id": "113-2-A-08", "exam": "113-2", "paper": "A", "q": 8, "unit": "五、過帳與分類帳", "topic": "過帳與分類帳", "stem": "有關過帳之相關敘述,下列何者正確?", "options": ["過帳是根據分錄轉記至分類帳之程序,故分類帳屬於依交易先後順序登載之序時帳簿", "標準式總分類帳可隨時查詢第四級會計項目之帳戶餘額", "總分類帳係以第四級會計項目設置之帳戶,又稱為統制帳戶", "過帳是為了將交易所涉及的會計項目進行帳戶分類,以利得知個別帳戶的變動情形及餘額"], "answer": "D", "figure": null, "official": "(A) 實帳戶之分類帳係依會計項目為帳戶記載之終結記錄簿;(B) 餘額式總分類帳可隨時查詢第四級會計項目之帳戶餘額;(C) 設有明細分類帳之總分類帳始得稱為「統制帳戶」。", "explain": {"concept": "考過帳的目的與分類帳(總帳、明細帳、統制帳戶)的特性。", "steps": ["過帳的目的:把日記簿裡按時間排列的分錄,依「會計項目」分類到各帳戶,這樣才能看出每個帳戶的增減與餘額,(D) 正確。", "(A):分類帳是依「會計項目」分帳戶記載的終結記錄簿,不是依時間先後的序時帳簿。", "(B):能隨時查餘額的是「餘額式」帳戶;標準式要自己算,不能隨時看餘額。", "(C):總分類帳是依「第一級會計項目(總括科目)」設置;只有設有明細分類帳的總帳才叫統制帳戶。", "所以選 (D)。"], "pitfalls": "序時帳簿=日記簿;分類帳簿=分類帳。看到「依先後順序」就想到日記簿。", "distractors": {"A": "把日記簿的特徵套到分類帳。", "B": "標準式不會隨時顯示餘額,餘額式才會。", "C": "統制帳戶需有明細帳支援,且總帳設在第一級科目。"}}, "check": "概念題:與官方詳解一致。", "verified": true, "note": ""}, {"id": "113-2-A-09", "exam": "113-2", "paper": "A", "q": 9, "unit": "六、試算與試算表", "topic": "試算表的性質", "stem": "有關試算程序之敘述,下列何者正確?", "options": ["總額餘額式試算表兼具顯示各帳戶之總額及餘額資料,為實務上普遍應用之試算表格式", "試算期間依企業業務需要進行編製試算表,屬於無須對外公布之非正式報表", "試算表係根據借貸法則編製而成,藉以驗證分錄及過帳程序有無明顯借貸不平衡之情形", "試算表需依交易之順序排列,並於前方設置類頁欄以利查閱"], "answer": "B", "figure": null, "official": "(A) 實務上普遍應用之試算表格式為餘額式試算表;(C) 試算表係根據借貸平衡原理編製而成;(D) 試算表需依資產、負債、權益、收益、費損之要素順序排列。", "explain": {"concept": "考試算表的編製依據、格式與性質。", "steps": ["試算表是企業內部用的檢查表,依需要定期編製,不必對外公布,屬於非正式報表,(B) 正確。", "(A):實務上最常用的是「餘額式」試算表,不是總額餘額式。", "(C):官方認定此項錯誤,理由是試算表依「借貸平衡原理」編製;「借貸法則」與「借貸平衡原理」用字不同。", "(D):試算表依資產、負債、權益、收益、費損的要素順序排列,不是依交易時間順序。", "所以選 (B)。"], "pitfalls": "試算表平衡只代表「借方合計=貸方合計」,不保證沒有錯誤(例如漏記、記錯科目都不會不平衡)。", "distractors": {"A": "把最常用的格式說成總額餘額式,實際是餘額式。", "D": "把試算表當成日記簿依時間排列,實際依要素順序排列。"}}, "check": "概念題:與官方詳解一致。", "verified": true, "note": "官方詳解對 (C) 的錯誤理由為「應為借貸平衡原理」,此處僅轉述,未再深究。"}, {"id": "113-2-A-10", "exam": "113-2", "paper": "A", "q": 10, "unit": "六、試算與試算表", "topic": "試算表錯誤更正", "stem": "涵霏公司帳列餘額式試算表借方餘額合計數$187,000,公司採憑證數位化,於匯憑證進行帳務檢核時,發現下列錯誤:\n①賒購商品$32,000,貸方誤記為應收帳款\n②現付租金$20,000,漏未入帳\n③現付自海外購進之商品投保之保險費$3,000,貸方誤以應付帳款入帳\n則餘額式試算表之正確餘額合計數應為何?", "options": ["$216,000", "$219,000", "$222,000", "$239,000"], "answer": "A", "figure": null, "official": "更正:①借 應收帳款32,000/貸 應付帳款32,000;②借 租金支出(預付租金)20,000/貸 現金20,000;③借 應付帳款3,000/貸 現金3,000。正確餘額合計=$216,000。", "explain": {"concept": "餘額式試算表看的是各帳戶「餘額」(借餘或貸餘)的合計,要逐一把錯誤更正分錄,對借方餘額合計的影響算進去。", "steps": ["先寫出每個錯誤的「更正分錄」。", "① 賒購商品:應借 進貨、貸 應付帳款;原本把貸方誤記成「應收帳款」(貸應收帳款)。更正分錄:借 應收帳款 $32,000、貸 應付帳款 $32,000。借方餘額帳戶 應收帳款 +$32,000,借方餘額合計 +$32,000。", "② 現付租金漏記:補記 借 租金支出 $20,000、貸 現金 $20,000。租金支出(借餘)+$20,000,現金(借餘)-$20,000,借方餘額合計淨變動 0。", "③ 保險費貸方誤記應付帳款:正確應貸 現金。更正:借 應付帳款 $3,000、貸 現金 $3,000。現金(借餘)-$3,000,應付帳款是貸餘,借方餘額合計 -$3,000。", "借方餘額合計=$187,000+$32,000+($20,000-$20,000)-$3,000=$216,000,選 (A)。"], "pitfalls": "注意題目問的是「餘額」合計,現金是借方餘額帳戶,貸記現金會讓借方餘額減少,要同時考慮。", "distractors": {"B": "$219,000=$187,000+$32,000,只考慮了 ① 的調增,忽略 ② 中現金減少及 ③ 的調減。"}}, "check": "python:187000+32000+20000-20000-3000=216000,與官方相符。", "verified": true, "note": ""}, {"id": "113-2-A-11", "exam": "113-2", "paper": "A", "q": 11, "unit": "七、調整", "topic": "權責基礎下調整本期損益", "stem": "星光公司帳務處理採用權責基礎,112年度帳列本期淨利$731,500,但發現未計入112年度專利權之攤銷$1,200及113年1月12日收到計費期間自112年12月10日至113年1月10日之電信費帳單$3,100,該電信費採「計尾不計首」依天數進行分攤;另帳列損益資料包括預收113年1月份租金$2,000,若不考慮所得稅情況下,112年度之「本期損益」正確金額為何?", "options": ["$726,200", "$726,400", "$727,163", "$732,500"], "answer": "A", "figure": null, "official": "正確淨利=$731,500-專利權攤銷$1,200-電信費分攤$3,100×21/31-預收租金$2,000=$726,200。", "explain": {"concept": "期末調整:未入帳的費用要補列(淨利減少);誤列為本期收益的預收收入要扣除(淨利減少)。", "steps": ["先抓三項調整:專利權攤銷$1,200(費用漏記)、電信費應付未付(費用漏記)、預收租金$2,000(收入多列)。", "專利權攤銷漏記:費用增加$1,200,淨利減少$1,200。", "電信費:計費期間12/10至1/10共31天(計尾不計首:12/10 不算、1/10 算,共31天);屬於112年度的是12/11~12/31共21天。費用=$3,100×21/31=$2,100,淨利再減$2,100。", "預收113年1月租金$2,000不屬於112年度收益,帳列損益中包含了,需扣除$2,000。", "正確本期損益=$731,500-$1,200-$2,100-$2,000=$726,200,選 (A)。"], "pitfalls": "「計尾不計首」要數清楚天數;預收租金多列的收入是要「扣掉」,不是加。", "distractors": {}}, "check": "python:731500-1200-3100*21/31-2000=726200.0,與官方相符。", "verified": true, "note": "單元歸類可能有爭議(七或九)"}, {"id": "113-2-A-12", "exam": "113-2", "paper": "A", "q": 12, "unit": "七、調整", "topic": "預付保險費調整", "stem": "企業為載貨用卡車所投保之第三人責任險因去年發生保險事故且有肇事責任,致使今年投保之保險費較去年增加百分之十,已知企業定期於11月1日支付一年期保險費,採記實轉虛法記帳,去年投保於今年實現之保險費金額為$40,000,已於實現時調整認列,則今年底調整分錄應為何?", "options": ["借:保險費$8,000\n  貸:預付保險費$8,000", "借:預付保險費$18,182\n  貸:保險費$18,182", "借:保險費$8,800\n  貸:預付保險費$8,800", "借:預付保險費$72,727\n  貸:保險費$72,727"], "answer": "C", "figure": null, "official": "去年投保今年實現保險費$40,000為1/1~10/31計10個月,每月$4,000;今年保險費較去年增加10%,每月$4,400,記實轉虛期末調整已實現11-12月2個月,借:保險費$8,800,貸:預付保險費$8,800。", "explain": {"concept": "記實轉虛法(付款時借預付費用),期末要把「已用掉」的部分轉為費用。", "steps": ["「記實轉虛」:11/1付款時借「預付保險費」(資產),年底再把已過期的部分轉成「保險費」(費用)。", "去年11/1付的一年保險費,今年1/1~10/31共10個月實現,金額$40,000,所以每月=$40,000÷10=$4,000。", "今年保險費較去年增加10%:每月$4,000×(1+10%)=$4,400;整年保費=$4,400×12=$52,800,11/1已付並借記預付保險費。", "今年底已實現期間為11/1~12/31共2個月:$4,400×2=$8,800。", "調整分錄:借 保險費 $8,800;貸 預付保險費 $8,800。選 (C)。"], "pitfalls": "今年的保費是「去年的月保費×1.1」,不是用$40,000直接乘1.1;還要確認去年$40,000是10個月不是12個月。", "distractors": {"A": "用去年的月保費$4,000×2=$8,000,忘了今年保費漲10%。", "B": "借貸方向顛倒(11/1 已借記預付保險費,年底應貸記預付)。", "D": "借貸方向顛倒。"}}, "check": "python:40000/10*1.1*2=8800,與官方相符。", "verified": true, "note": ""}, {"id": "113-2-A-13", "exam": "113-2", "paper": "A", "q": 13, "unit": "十二、應收款項", "topic": "備抵損失(備抵矩陣法)", "stem": "昱甄公司應收帳款年底採準備矩陣法依帳款除欠期間評估損失率,112年底帳款未收現相關資料如下:\n\n| 客戶別 | 甲客戶 | | 乙客戶 | 丙客戶 |\n|---|---|---|---|---|\n| 銷貨日期 | 112/9/10 | 112/11/18 | 112/12/15 | 112/12/30 |\n| 帳款金額 | $200,000 | $100,000 | $50,000 | $80,000 |\n\n| 應收帳款除欠期間 | 1~30日 | 31~100日 | 101日以上 |\n|---|---|---|---|\n| 估計損失率 | 1% | 3% | 8% |\n\n調整前「備抵損失—應收帳款」借餘$1,700,下列敘述何者正確?", "options": ["112年底應收帳款帳面金額為$428,300", "112年度應認列預期信用減損損失$22,000", "調整後「備抵損失—應收帳款」期末應有之餘額為$22,000", "期末漏作此一調整分錄將造成淨利少計,應收帳款帳面金額多計"], "answer": "B", "figure": null, "official": "備抵損失期末餘額=($50,000+$80,000)×1%+$100,000×3%+$200,000×8%=$20,300;(A) 帳面金額=$430,000-$20,300=$409,700;(B) 損失=$20,300+$1,700=$22,000;(D) 漏作將造成費用少計、淨利多計。", "explain": {"concept": "備抵矩陣法:依帳齡分組乘損失率求期末備抵損失餘額,再扣除調整前餘額求本期損失。", "steps": ["算帳齡到12/31:甲 9/10→12/31 共112天(101日以上)$200,000;甲 11/18→12/31 共43天(31~100日)$100,000;乙 12/15 共16天(1~30日)$50,000;丙 12/30 共1天(1~30日)$80,000。", "備抵損失期末應有餘額=($50,000+$80,000)×1%+$100,000×3%+$200,000×8%=$1,300+$3,000+$16,000=$20,300。", "調整前備抵損失是「借餘」$1,700(表示以前多沖銷),要補足到貸餘$20,300,本期應認列損失=$20,300+$1,700=$22,000。", "調整分錄:借 預期信用減損損失 $22,000;貸 備抵損失—應收帳款 $22,000。", "對照選項:(B) 正確。(A) 應收帳款帳面金額=總額$430,000-$20,300=$409,700;(C) 期末餘額是$20,300不是$22,000;(D) 漏作調整會少記費用,淨利多計。"], "pitfalls": "調整前是「借餘」$1,700,要加(不是減)才得到損失金額;期末應有餘額($20,300)與本期損失($22,000)是兩個不同的數字。", "distractors": {"A": "$428,300=$430,000-$1,700,用了調整前備抵借餘,沒有用期末應有餘額。", "C": "把本期損失$22,000誤當成期末應有餘額。", "D": "漏作調整,費用少列、淨利多計,應收帳款帳面金額也多計,但淨利方向是「多計」,不是少計。"}}, "check": "python:帳齡天數112/43/16/1,期末備抵=20,300;損失=20,300+1,700=22,000;帳面=430,000-20,300=409,700,與官方相符。", "verified": true, "note": ""}, {"id": "113-2-A-14", "exam": "113-2", "paper": "A", "q": 14, "unit": "八、結帳", "topic": "結帳方法與結帳後項目", "stem": "有關結帳之敘述,下列何者正確?", "options": ["虛帳戶之結帳方法可分為「差額結轉法」及「分錄結轉法」", "獨資企業無論淨利或淨損,皆須將年度營業結果結轉至「累積盈虧」之帳戶", "結帳前試算表實帳戶「業主往來」帳戶金額與結帳後試算表中之金額必定相同", "採定期盤存制之存貨,調整前存貨為期初存貨,結帳後之存貨為期末存貨"], "answer": "D", "figure": null, "official": "(A) 實帳戶之結帳方法可分為差額結轉法及分錄結轉法;(B) 獨資須將年度營業結果結轉至「業主資本」(原題以業主往來說明);(C)「業主往來」帳戶結帳前未包括本期損益之金額,結帳後包括本期損益金額。", "explain": {"concept": "考結帳方法與結帳前後的帳戶變化。", "steps": ["定期盤存制平時不記存貨增減,所以調整前「存貨」帳戶餘額是期初存貨;期末盤點後,結帳時把期初存貨轉出、記入期末存貨,結帳後留下的是期末存貨,(D) 正確。", "(A):差額結轉法與分錄結轉法是「實帳戶」的結帳方法(有兩種記法),虛帳戶是直接結清轉入損益,所以說成虛帳戶是錯的。", "(B):獨資企業的損益結轉到「業主資本」(或業主往來),「累積盈虧」是公司組織才有的科目。", "(C):業主往來結帳前不含本期損益,結帳後把損益轉入,所以結帳後金額會不同。"], "pitfalls": "「累積盈虧」是公司用語;獨資是「業主資本/業主往來」。", "distractors": {"A": "把實帳戶的結帳方法套到虛帳戶。", "B": "把公司組織的「累積盈虧」誤用在獨資。", "C": "忽略結帳後損益會轉入該帳戶。"}}, "check": "概念題:與官方詳解及結帳程序常識一致。", "verified": true, "note": "官方詳解對 (B) 的說明用字與題幹略有出入(業主資本/業主往來),答案 D 無疑義。"}, {"id": "113-2-A-15", "exam": "113-2", "paper": "A", "q": 15, "unit": "八、結帳", "topic": "結帳分錄與本期損益", "stem": "芸昕公司今年度之營業收入(淨額)$1,980,000,進貨$750,000,支付員工薪資$336,000,租金費用$120,000,期初存貨$50,000,期末存貨$30,000,運費$70,000,進貨費用$40,000,進貨退出$25,000,佣金收入$37,000,利息費用$18,000,營利事業所得稅按目前所得稅法計算,下列敘述何者錯誤?", "options": ["本期應結轉營業毛利$1,195,000至「本期損益」", "本期所得稅費用應結轉至「本期損益」之金額為$137,600", "營業費用應結轉予「本期損益」之金額為$566,000", "本期應結轉本期損益至「累積盈虧」之金額為$550,400"], "answer": "C", "figure": null, "official": "(A) 銷貨成本=$50,000+$750,000+$40,000-$25,000-$30,000=$785,000,營業毛利=$1,980,000-$785,000=$1,195,000;(B) 稅前淨利$688,000,所得稅費用=$688,000×20%=$137,600;(C) 營業費用=薪資$336,000+租金$120,000+運費$70,000=$526,000;(D) 本期損益=$688,000×(1-20%)=$550,400。", "explain": {"concept": "結帳要先算各項金額:進貨費用屬於進貨成本,不是營業費用;所得稅按20%計算。", "steps": ["先算銷貨成本=期初存貨+進貨+進貨費用-進貨退出-期末存貨=$50,000+$750,000+$40,000-$25,000-$30,000=$785,000。", "營業毛利=營業收入淨額-銷貨成本=$1,980,000-$785,000=$1,195,000,(A) 正確。", "營業費用=薪資$336,000+租金$120,000+運費$70,000=$526,000(進貨費用$40,000已在銷貨成本中,不能重複算),所以 (C) 說$566,000是錯的。", "稅前淨利=毛利$1,195,000-營業費用$526,000+佣金收入$37,000-利息費用$18,000=$688,000;所得稅費用=$688,000×20%=$137,600,(B) 正確。", "本期淨利=$688,000-$137,600=$550,400,(D) 正確。所以錯誤的是 (C)。"], "pitfalls": "進貨費用要併入進貨成本(銷貨成本),不要再重複放入營業費用。", "distractors": {"A": "此項正確,不是錯誤選項。", "B": "此項正確,不是錯誤選項。", "D": "此項正確,不是錯誤選項。"}}, "check": "python:銷貨成本785,000;毛利1,195,000;營業費用526,000;稅前688,000;稅137,600;淨利550,400,與官方相符。", "verified": true, "note": "單元歸類可能有爭議(八或九)"}, {"id": "113-2-A-16", "exam": "113-2", "paper": "A", "q": 16, "unit": "九、財務報表", "topic": "財務報表比率分析", "stem": "佳佳是資產管理股份有限公司之負責人,公司之營業項目除了出租不動產、廠房及設備之外,平時亦透過投資其他公司之方式作為收入來源,若佳佳以企業毛利率至少需達三成及純益率等獲利能力作為主要評估重點,比較表(一)同年度相同產業之兩家企業財務報表,下列敘述何者正確?\n\n表(一)\n\n| 項目 | 丙公司 | 丁公司 |\n|---|---|---|\n| 營業收入 | $6,400,000 | $22,100,000 |\n| 營業成本 | 4,400,000 | 16,000,000 |\n| 營業毛利(毛損) | 2,000,000 | 6,100,000 |\n| 營業費用 | 953,000 | 2,100,000 |\n| 營業利益(損失) | 1,047,000 | 4,000,000 |\n| 營業外收入及支出 | 72,000 | (2,000,000) |\n| 稅前淨利(淨損) | 1,119,000 | 2,000,000 |\n| 所得稅費用 | 223,800 | 400,000 |\n| 本期淨利(淨損) | $895,200 | $1,600,000 |", "options": ["丁公司之營收金額較丙公司高,獲利能力較佳,應選擇投資丁公司", "丙公司之毛利率及純益率皆符合評估重點,應選擇投資丙公司", "丙公司及丁公司之毛利率皆符合評估重點,但丙公司之純益率較佳,應選擇投資丙公司", "丙公司及丁公司之毛利率皆符合評估重點,但丁公司之純益率較佳,應選擇投資丁公司"], "answer": "B", "figure": null, "official": "丙公司毛利率=$2,000,000/$6,400,000=31.25%,純益率=$895,200/$6,400,000=13.99%;丁公司毛利率=$6,100,000/$22,100,000=27.6%(未達評估重點三成),純益率=$1,600,000/$22,100,000=7.24%;丙公司毛利率>30%且純益率較丁公司佳,選擇投資丙公司。", "explain": {"concept": "毛利率=營業毛利÷營業收入;純益率=本期淨利÷營業收入。比較比率而不是金額大小。", "steps": ["公式:毛利率=營業毛利÷營業收入;純益率=本期淨利÷營業收入。", "丙公司:毛利率=$2,000,000÷$6,400,000=31.25%(≥30% 符合);純益率=$895,200÷$6,400,000≈13.99%。", "丁公司:毛利率=$6,100,000÷$22,100,000≈27.6%(<30%,不符合);純益率=$1,600,000÷$22,100,000≈7.24%。", "佳佳要求毛利率至少三成,且重視純益率:只有丙公司達標,純益率也較高,所以應選丙公司,選 (B)。"], "pitfalls": "營收金額大不代表獲利能力好;要看「率」。同時要注意毛利率有門檻(三成)。", "distractors": {"A": "只比營收金額大小,沒算比率,而且丁公司毛利率也不達標。", "C": "誤以為丁公司毛利率也符合三成,實際只有27.6%。", "D": "同樣誤判丁公司毛利率,且丁公司純益率(7.24%)其實低於丙公司。"}}, "check": "python:丙毛利率0.3125、純益率0.139875;丁毛利率0.2760、純益率0.0724,與官方相符。", "verified": true, "note": ""}, {"id": "113-2-A-17", "exam": "113-2", "paper": "A", "q": 17, "unit": "九、財務報表", "topic": "償債能力比率", "stem": "大林公司欲辦理企業貸款進行規模擴張,往來銀行完成通過審查其綜合損益表及近一年之營業稅申報資料評估企業成長與獲利能力後,目前正以企業之資產負債表進行評估公司的經營風險穩健度,若公司還款期限設定為一年內還款,銀行係以負債比率小於40%及速動比率大於1.5做為放款基準,有關大林公司相關資料如表(二),下列敘述何者正確?\n\n表(二)\n\n| 資產 | 金額 | 負債與權益 | 金額 |\n|---|---|---|---|\n| 現金及約當現金 | $162,000 | 流動負債小計 | $217,000 |\n| 存貨 | 178,000 | 非流動負債小計 | 112,000 |\n| 預付款項 | 2,000 | 負債總計 | 329,000 |\n| 流動資產小計 | 342,000 | 權益 | |\n| 非流動資產小計 | 603,000 | 權益總計 | 616,000 |\n| 資產總計 | $945,000 | 負債及權益總計 | $945,000 |", "options": ["負債比率為22.96%,速動比率為1.58,符合往來銀行之放款基準", "負債比率為34.81%,速動比率為1.58,符合往來銀行之放款基準", "負債比率為22.96%,速動比率為0.75,不符合往來銀行之放款基準", "負債比率為34.81%,速動比率為0.75,不符合往來銀行之放款基準"], "answer": "D", "figure": null, "official": "負債比率=$329,000/$945,000=34.81%<40%;速動比率=$162,000/$217,000=0.75<1.5,不符合放款基準。", "explain": {"concept": "負債比率=負債總額÷資產總額;速動比率=速動資產÷流動負債(速動資產不含存貨與預付款項)。", "steps": ["負債比率=負債總額÷資產總額=$329,000÷$945,000≈34.81%,小於40%,符合。", "速動資產=現金及約當現金(題中沒有其他應收款項或短期投資);存貨與預付款項不算速動資產。速動資產=$162,000。", "速動比率=$162,000÷$217,000≈0.75,小於 1.5,不符合。", "兩項基準必須「都」符合,速動比率不合格,所以不符合放款基準,選 (D)。"], "pitfalls": "負債比率分母是「資產總額」不是權益;速動資產要扣掉存貨與預付款項,不要直接用流動資產。", "distractors": {"A": "負債比率誤用$217,000/$945,000=22.96%(只用流動負債),速動比率1.58 則是用$342,000/$217,000 的流動比率。", "B": "負債比率對,但速動比率誤用流動比率$342,000/$217,000≈1.58。", "C": "速動比率對,但負債比率誤用流動負債$217,000/$945,000=22.96%。"}}, "check": "python:329000/945000=0.3481;162000/217000=0.7465;(A)(C) 之22.96%=217000/945000,(A)(B) 之1.58=342000/217000,與官方相符。", "verified": true, "note": ""}, {"id": "113-2-A-18", "exam": "113-2", "paper": "A", "q": 18, "unit": "十、加值型營業稅會計實務", "topic": "營業稅申報計算", "stem": "中南股份有限公司為自行車零件生產廠商,適用一般稅率之營業人,主要目標客群除國內廠商之外,亦從事外銷活動,111年9-10月401申報書中進、銷項資料如下(金額均未含稅):內銷$4,200,000,銷貨退回及折讓$200,000,外銷$2,700,000,進項取得統一發票扣抵聯(包括一般稅額計算之電子計算機發票扣抵聯)$3,100,000,三聯式收銀機發票扣抵聯及一般稅額計算之電子發票$400,000,另有進貨退出及折讓$50,000,上期無法抵累積留抵稅額。有關營業稅之敘述,下列何者正確?", "options": ["本期銷項稅額$200,000;進項稅額$172,500;本期應有應納稅額$27,500", "本期銷項稅額$210,000;進項稅額$175,000;本期應有應納稅額$35,000", "本期銷項稅額$335,000;進項稅額$150,000;本期應有應納稅額$185,000", "只要有外銷即符合退稅資格,故本期可申請退稅"], "answer": "A", "figure": null, "official": "銷項稅額=($4,200,000-$200,000)×5%=$200,000;進項稅額=($3,100,000+$400,000-$50,000)×5%=$172,500;銷項稅額>進項稅額,且上期無留抵稅額,本期應納稅額$27,500。", "explain": {"concept": "營業稅稅率5%;銷項稅額看內銷淨額(外銷為零稅率);進項稅額=可扣抵進項金額×5%,銷退折讓與進退折讓要扣除。", "steps": ["銷項:內銷$4,200,000扣掉銷貨退回及折讓$200,000,淨額$4,000,000;外銷$2,700,000適用零稅率,稅額為0。銷項稅額=$4,000,000×5%=$200,000。", "進項:取得統一發票扣抵聯$3,100,000+收銀機發票及電子發票$400,000-進貨退出及折讓$50,000=$3,450,000;進項稅額=$3,450,000×5%=$172,500。", "應納稅額=銷項稅額-進項稅額-上期留抵=$200,000-$172,500-0=$27,500,選 (A)。", "(D) 外銷只有零稅率,要退稅需進項稅額大於銷項稅額(留抵)才可能申請退稅,不是「只要有外銷就能退」。"], "pitfalls": "外銷零稅率不計銷項稅額,但仍可扣進項;銷退折讓、進退折讓都要從金額中扣除後再乘稅率。", "distractors": {"B": "銷項$210,000=$4,200,000×5%、進項$175,000=$3,500,000×5%,都沒有扣除銷貨退回折讓與進貨退出折讓。", "C": "銷項$335,000=($4,200,000-$200,000+$2,700,000)×5%,把零稅率的外銷也算入。", "D": "外銷只是零稅率,仍須比較進銷項稅額,本期是應納稅額不是留抵,不能退稅。"}}, "check": "python:4,000,000*5%=200,000;(3,100,000+400,000-50,000)*5%=172,500;差額27,500,與官方相符。", "verified": true, "note": ""}, {"id": "113-2-A-19", "exam": "113-2", "paper": "A", "q": 19, "unit": "十、加值型營業稅會計實務", "topic": "進項稅額扣抵規定", "stem": "好好吃有限公司經營登記項目為中式餐館,店舖經營型態為複合式火鍋餐飲,有關營業稅之敘述,下列何者正確?", "options": ["公司為凝聚員工向心力,每季為員工辦理慶生活動,訂購之餐點皆依法取具發票,故可申報為費用,並申報扣抵營業稅", "公司定期向在地小農購買新鮮蔬菜,取具免用統一發票收據,該蔬菜為公司之進貨品項,故可申報為進貨成本並扣抵營業稅", "公司另開發鍋底湯包於網路進行販售,企業需依銷售訂單金額開立銷貨發票申報營業稅", "公司委託美食外送平台之運費每月結算開立發票,屬於不可扣抵之進項"], "answer": "C", "figure": null, "official": "(A) 屬職工福利,為不可扣抵之進項稅額;(B) 收據為不可扣抵之項目;(D) 銷貨運費之營業稅為可扣抵之進項稅額。", "explain": {"concept": "考營業稅的銷項開立發票,以及進項稅額可否扣抵的規定。", "steps": ["(A):員工的慶生活動屬職工福利,雖然取得發票,其進項稅額依規定不可扣抵;費用可認列,但營業稅不能扣。", "(B):向小農購買蔬菜取得的是「免用統一發票收據」,收據沒有營業稅額,也不能作為進項稅額扣抵憑證(購買農產品有另外規定,但本題官方判定為不可扣抵)。", "(C):網路販售鍋底湯包屬銷貨,營業人銷售貨物應依規定開立統一發票並申報銷項稅額,正確。", "(D):營業用的運費(銷貨運費)取得發票者,其進項稅額可以扣抵。", "所以選 (C)。"], "pitfalls": "職工福利、交際應酬、自用乘人小汽車等進項稅額不可扣抵;收據、免用發票不能申報進項稅額。", "distractors": {"A": "以為取得發票就可扣抵,忽略職工福利進項不得扣抵。", "B": "收據不是可扣抵進項稅額的憑證。", "D": "運費若取得合法發票,進項稅額可以扣抵。"}}, "check": "概念題:與官方詳解一致。", "verified": true, "note": ""}, {"id": "113-2-A-20", "exam": "113-2", "paper": "A", "q": 20, "unit": "十一、現金及內部控制", "topic": "零用金與內部控制", "stem": "(閱讀下文,回答第20-21題)\n小花公司平時設置定額零用金制度$10,000,每月底由保管員提出單據向會計人員報撥補款項,目前收存之單據有購買清潔用品$550、文具紙張$1,800、電話費$1,500、郵資$1,680,保管員因個人因素致7月底無法如期辦理相關事項,便自行預估至7月底之花費填具公司小規模營業人所提供之空白收據,向會計人員申請撥付款項,已知盤點手存現金數為$1,470。\n\n有關小花公司現金及內部控制之相關敘述,下列何者錯誤?", "options": ["該公司會計人員與出納人員由不同人員負責,符合現金管理及內部控制原則", "若明知為不實事項,利用不正當之方法致使會計事項發生不實之結果,可處以五年以下有期徒刑、拘役或科或併科新台幣六十萬元以下罰金", "未發生之交易事項不應入帳,避免虛增公司費用", "保管員將企業至月底可能之花費直接填寫空白收據預估入帳,符合配合原則"], "answer": "D", "figure": null, "official": "此題為錯誤敘述選擇題,(D) 預估花費填空白收據入帳,屬於虛構交易,不符合配合原則。", "explain": {"concept": "考內部控制原則、商業會計法罰則,與帳務處理必須以真實發生的交易為依據。", "steps": ["題目問「錯誤」的敘述。", "(A):會計與出納(管錢)由不同人負責,是內部牽制的基本原則,正確。", "(B):商業會計法規定,明知為不實事項而以不正當方法使會計事項發生不實結果,處五年以下有期徒刑、拘役或科或併科新臺幣六十萬元以下罰金,正確。", "(C):未發生的交易不能入帳,避免虛增費用,正確。", "(D):保管員還沒花費就先自己「預估」填空白收據請款,這是沒有真實交易的虛偽憑證,不能入帳;而且「配合原則」是指收入與相關費用要在同期間配合,不是可以用預估虛構費用,所以 (D) 錯誤。"], "pitfalls": "配合原則的前提是「費用真的發生」;沒有發生的交易不可以入帳,更不能自填收據。", "distractors": {"A": "這是正確敘述。", "B": "這是商業會計法罰則的正確內容。", "C": "這是正確敘述。"}}, "check": "概念題:與官方詳解及商業會計法常識(明知不實事項罰則)一致。", "verified": true, "note": ""}, {"id": "113-2-A-21", "exam": "113-2", "paper": "A", "q": 21, "unit": "十一、現金及內部控制", "topic": "零用金短少計算", "stem": "(承第20題之題幹)\n小花公司平時設置定額零用金制度$10,000,每月底由保管員提出單據向會計人員報撥補款項,目前收存之單據有購買清潔用品$550、文具紙張$1,800、電話費$1,500、郵資$1,680,保管員因個人因素致7月底無法如期辦理相關事項,便自行預估至7月底之花費填具公司小規模營業人所提供之空白收據,向會計人員申請撥付款項,已知盤點手存現金數為$1,470。\n\n小花公司可能遭零用金保管員挪用之金額為何?", "options": ["$3,000", "$4,470", "$5,530", "$8,530"], "answer": "A", "figure": null, "official": "定額$10,000-$550-$1,800-$1,500-$1,680=$4,470(手存現金應有之金額);實際手存現金僅$1,470,短少$3,000可能遭挪用。", "explain": {"concept": "定額零用金:現金+單據=定額;若現金不足,代表可能有短少。", "steps": ["定額零用金制度下,「手邊現金+已花費的單據」應該剛好等於定額$10,000。", "目前有的單據:$550+$1,800+$1,500+$1,680=$5,530。", "手邊現金「應有」金額=$10,000-$5,530=$4,470。", "實際盤點只有$1,470,短少=$4,470-$1,470=$3,000,可能遭挪用,選 (A)。", "(保管員 7 月底預估填空白收據的部分不是已發生的真實花費,所以不計入單據。)"], "pitfalls": "別直接拿定額減單據當成挪用金額;要再和實際盤點的現金比較。", "distractors": {"B": "$4,470 是現金「應有」金額,不是短少金額。", "C": "$5,530 是目前單據合計,不是短少金額。", "D": "$8,530=$10,000-$1,470,把預估單據也當成短少,但單據$5,530是真實花費。"}}, "check": "python:10000-550-1800-1500-1680=4470;4470-1470=3000,與官方相符。", "verified": true, "note": ""}, {"id": "113-2-A-22", "exam": "113-2", "paper": "A", "q": 22, "unit": "十一、現金及內部控制", "topic": "銀行存款調節表", "stem": "新北公司6月底帳上銀行存款餘額為$30,588,與銀行所寄來之對帳單顯示餘額$26,781不相符,下列何者為造成此差異的可能原因?", "options": ["銀行代收票據$1,000及利息收入$412及在途存款$3,807", "銀行代收票據$1,000及手續費支出$4,500及在途存款$693", "銷貨收到客戶開立之支票$6,000因客戶存款不足遭銀行退票及手續費$412,6月底有未兌現支票$1,781", "銷貨收到客戶開立之支票$6,000因客戶存款不足遭銀行退票及利息收入$412,6月底有未兌現支票$1,781"], "answer": "D", "figure": null, "official": "公司帳上餘額$30,588+利息收入$412-存款不足退票$6,000=銀行對帳單餘額$26,781-未兌現支票$1,781=正確餘額$25,000。", "explain": {"concept": "銀行存款調節表:公司帳與銀行帳各自調整後應該相等。", "steps": ["先算兩邊調整後的正確餘額,用 (D) 檢驗:", "公司帳上餘額$30,588,調整:+銀行已收利息收入$412(帳上未記),-客戶支票存款不足遭退票$6,000(帳上先前已加)。調整後=$30,588+$412-$6,000=$25,000。", "銀行對帳單$26,781,調整:-未兌現支票$1,781(帳上已扣,銀行尚未扣)。調整後=$26,781-$1,781=$25,000。", "兩邊相等,所以 (D) 是造成差異的可能原因。", "(C) 若把$412 當手續費要減,公司帳調整成$30,588-$6,000-$412=$24,176,與銀行調整後$25,000 不相等。"], "pitfalls": "利息收入是「加」、手續費和退票是「減」;未兌現支票是減銀行對帳單餘額。", "distractors": {"A": "公司帳$30,588+$1,000+$412=$32,000;銀行$26,781+$3,807=$30,588,兩邊不相等。", "B": "公司帳$30,588+$1,000-$4,500=$27,088;銀行$26,781+$693=$27,474,兩邊不相等。", "C": "手續費$412 應減,公司帳調整後=$24,176,與銀行調整後$25,000 不相等。"}}, "check": "python:30588+412-6000=25000;26781-1781=25000,兩邊相等;(C) 的 30588-6000-412=24176≠25000,與官方相符。", "verified": true, "note": ""}, {"id": "113-2-A-23", "exam": "113-2", "paper": "A", "q": 23, "unit": "十二、應收款項", "topic": "應收款項相關敘述", "stem": "有關應收款項之敘述,下列何者正確?", "options": ["交貨條件為目的地交貨,買方代墊運費,買方應認列進貨費用", "附退貨權之銷貨預期可能退回之部分應列為退款負債,俟退款期限屆滿時調整應認列之銷貨收入", "分期付款銷貨因買方款項未付清,商品所有權屬於賣方,尚不能認列應收帳款之債權", "出售貨車收到18個月期不附息票據,年底毋須調整認列利息收入"], "answer": "B", "figure": null, "official": "(A) 交貨條件為目的地交貨,買方代墊運費,賣方應認列運費;(C) 分期付款銷貨於交付商品時認列應收帳款之債權;(D) 18個月期票據以現值入帳,應將票據面額與現值間差額列為「應收票據折價」,逐期轉列為「利息收入」。", "explain": {"concept": "考交貨條件、附退貨權銷貨、分期付款銷貨、不附息票據等應收款項處理。", "steps": ["(A):目的地交貨,運費由賣方負擔;買方代墊運費,賣方應認列運費(銷貨運費)。", "(B):附退貨權的銷貨,預期會退回的部分不認列收入,而認列「退款負債」;退貨期限屆滿後,再把退款負債轉列(調整)銷貨收入,正確。", "(C):分期付款銷貨,交付商品時就應認列「應收帳款」債權,不管所有權是否保留。", "(D):超過一年的不附息票據,要以現值入帳,面額與現值的差額是「應收票據折價」,年底要逐期轉列利息收入。", "所以選 (B)。"], "pitfalls": "目的地交貨=賣方負擔運費;長期不附息票據要用現值,並調整利息收入。", "distractors": {"A": "忘記目的地交貨的運費由賣方負擔。", "C": "以為所有權未移轉就不能認列債權,實際上交付商品時就認列應收帳款。", "D": "18個月超過一年,需以現值入帳並分期轉列利息收入。"}}, "check": "概念題:與官方詳解一致。", "verified": true, "note": ""}, {"id": "113-2-A-24", "exam": "113-2", "paper": "A", "q": 24, "unit": "十二、應收款項", "topic": "應收票據貼現", "stem": "柯南剛出社會自行創業,因未完全符合青年創業貸款之條件,目前接獲客戶訂單,柯南需投入資金購置設備生產產品,但主要客戶的應收帳款大多是開立六個月至九個月之期票,無法支應短期資金需求,因此7/1柯南持6/1客戶開來面額$500,000六個月期不附息票據向銀行辦理票據貼現,銀行貼現率1.5%,下列敘述何者正確?", "options": ["應收票據貼現負債折價$3,125", "該票據到期銀行通知客戶拒付,連同拒絕證書費$250,公司應轉列催收款項$504,000", "柯南持票據向銀行辦理貼現,貼現金額為$496,250", "公司持應收票據向銀行辦理貼現與公司開立本票向銀行貼現之會計處理分錄相同"], "answer": "A", "figure": null, "official": "不附息票據面額=到期值=$500,000;貼現息=$500,000×1.5%×5/12=$3,125;貼現金額=$500,000-$3,125=$496,875;應收票據貼現負債折價=$500,000-$496,875=$3,125;(B) 應轉列應收款項$500,250;(C) 貼現金額$496,875。", "explain": {"concept": "票據貼現:貼現息=到期值×貼現率×貼現期間;貼現金額=到期值-貼現息;貼現視為擔保借款,出現「應收票據貼現負債折價」。", "steps": ["票據是6/1收到、六個月期,到期日12/1,不附息,到期值=面額$500,000。", "7/1貼現,貼現期間=7/1至12/1共5個月。", "貼現息=$500,000×1.5%×5/12=$3,125;貼現金額=$500,000-$3,125=$496,875。", "此貼現視為以票據為擔保的借款,分錄:借 現金 $496,875、應收票據貼現負債折價 $3,125;貸 應收票據貼現負債 $500,000。折價$3,125,(A) 正確。", "(B):到期遭拒付,連同拒絕證書費$250,應轉列的是應收款項$500,250(或催收款項),不是$504,000。(C) 貼現金額是$496,875,不是$496,250。(D) 公司持應收票據貼現是以他人開的票據貼現,與公司自己開立本票貼現,分錄不同。"], "pitfalls": "貼現期間是「貼現日到到期日」,不是整張票據的六個月;別把貼現金額與貼現息混淆。", "distractors": {"B": "拒付時應轉列的金額是面額$500,000加拒絕證書費$250=$500,250,不是$504,000。", "C": "貼現金額應為$500,000-$3,125=$496,875,不是$496,250。", "D": "以為兩種貼現處理相同,但本票是自己開立的,屬於應付票據,分錄不同。"}}, "check": "python:500000*0.015*5/12=3125;500000-3125=496875,與官方相符。", "verified": true, "note": ""}, {"id": "113-2-A-25", "exam": "113-2", "paper": "A", "q": 25, "unit": "十二、應收款項", "topic": "銷貨折扣(淨價法)", "stem": "戊廠商為生產風力發電葉扇之廠商,對於應收帳款採淨額有權收取之對價處理,於112年10月6日賒銷商品$400,000給庚客戶,九五折成交,收款條件為2/10,1/20,n/30。若庚客戶於112年10月15日交來半數貨款;112年10月22日償還剩餘貨款之半數;112年11月3日付清所有款項,此出售交易共產生多少的銷貨收入?", "options": ["$372,400", "$373,350", "$375,250", "$380,000"], "answer": "C", "figure": null, "official": "銷貨收入按淨額法認列:$400,000×0.95×0.98=$372,400;10/22 償還剩餘貨款之半數=$186,200÷2=$93,100,銷貨收入增加數=$93,100÷0.98×(2%-1%)=$950;11/3 還清剩餘貨款$93,100,銷貨收入增加數=$93,100÷0.98×(2%-0%)=$1,900;共產生銷貨收入=$372,400+$950+$1,900=$375,250。", "explain": {"concept": "淨額法:先假設客戶會享有最大折扣(2%),若客戶沒有在最大折扣期內付款,放棄的折扣再補認銷貨收入。", "steps": ["商業折扣:定價$400,000打九五折=$380,000(商業折扣不在帳上顯示)。", "淨額法:先以享有最大現金折扣2%入帳,銷貨收入=$380,000×(1-2%)=$372,400,應收帳款$372,400。", "10/6~10/15 付款共9天(2/10 期內),半數付款享2%折扣,沒有額外收入。", "10/22 付半數:此時為16天(1/20 期內),折扣只有1%,少拿1%折扣,多認銷貨收入。剩餘應收$186,200,半數=$93,100,對應的總額=$93,100÷0.98=$95,000,多認收入=$95,000×(2%-1%)=$950。", "11/3 付清最後一半$93,100:已 28 天(超過 20 天,無折扣),多認銷貨收入=$95,000×(2%-0%)=$1,900。", "合計銷貨收入=$372,400+$950+$1,900=$375,250,選 (C)。"], "pitfalls": "九五折是商業折扣,直接降低售價;2/10,1/20 是現金折扣,淨額法下要用「放棄折扣再補認收入」處理,不要混為一談。", "distractors": {"A": "只算最初的$372,400,沒補認未享折扣的收入。", "D": "$380,000=$400,000×0.95,只扣商業折扣,把現金折扣完全忽略(總額法)。"}}, "check": "python:400000*.95*.98=372400;+950+1900=375250,與官方相符。", "verified": true, "note": "單元歸類可能有爭議(十二或一)"}, {"id": "113-3-A-01", "exam": "113-3", "paper": "A", "q": 1, "unit": "一、會計基本概念", "topic": "會計分類與準則", "stem": "曾正玫服飾店是由曾玫老板獨自出資開設,並聘請兩位工讀生、一位會計人員,老板曾玫因兒時家境貧苦曾受社會善心人士幫忙,故每月都會固定捐贈營業利益5%給慈善團體。下列敘述何者正確?", "options": ["曾正玫服飾店會計的種類若依「企業組織」區分,應分類為「合夥會計」,因為有老板曾玫、兩位工讀生及會計人員共四人", "曾正玫服飾店會計處理應遵循之一般公認會計原則,為由「中華民國會計研究發展基金會」制定的「企業會計準則公報」", "曾正玫服飾店會計的種類若依「營利與否」區分,應分類為「收支會計」,因為會計人員只要負責計算「收入」及「支出」就好", "曾正玫服飾店會計的種類若依「營利與否」區分,應分類為「非營利會計」,因為老板曾玫每月都會捐款給慈善團體做公益"], "answer": "B", "figure": null, "official": "(A)應為獨資會計;(C)(D)依營利與否應為營利會計。", "explain": {"concept": "考會計種類的分類標準(企業組織、營利與否)以及我國一般公認會計原則的制定機構。", "steps": ["先看題目:店是老板「一個人」出資開設 → 依企業組織分是「獨資會計」,不是合夥(合夥是兩人以上共同出資,工讀生、會計人員只是員工,不是出資人),所以(A)錯。", "再看營利與否:服飾店的目的是賺錢 → 屬「營利會計」。捐款只是把利潤的一部分拿去做公益,不會改變它營利的本質,所以(C)(D)錯。「收支會計」是非營利組織(如學校、社團)用的,重點在收入與支出,與一般營利事業不同。", "(B)我國商業會計處理的一般公認會計原則,是由「中華民國會計研究發展基金會」所制定的「企業會計準則公報」,敘述正確 → 選(B)。"], "pitfalls": "分類看的是「出資人數」與「經營目的」,不是員工人數,也不是有沒有捐款。", "distractors": {"A": "把員工人數當成合夥人數,忽略合夥是指出資人。", "C": "誤以為收支會計是只記收入與支出的簡單記帳,其實它是非營利機構的會計。", "D": "以為有做公益就是非營利,忽略營利與否看的是事業的設立目的。"}}, "check": "概念題,依商業會計法與會計準則常識確認:獨資、營利會計、ARDF 制定企業會計準則公報,皆與官方答案(B)相符。", "verified": true, "note": ""}, {"id": "113-3-A-02", "exam": "113-3", "paper": "A", "q": 2, "unit": "四、分錄與日記簿", "topic": "交易對財報要素影響", "stem": "老師為了提升班上學習風氣,由老師出題後,每四人為一組討論會計題目,若其中一人答對則會幫小組加分,可提高所有組員的平時成績。老師:「甲公司存貨處理採用定期盤存制,3/1 簽發一個月期票據購買商品$10,000,3/8 出售全部商品收到$30,000 即期支票乙張,並立即存入銀行。假設 3 月份只有這兩筆交易,試問 3 月份交易對財務報表要素之影響為何?」下列四位同學為同一組成員,根據下列四位同學討論中各自的答案,應派哪一位同學回答老師的問題,才能為小組爭取加分的機會?", "options": ["小葵:資產增加$30,000、負債增加$10,000、費損增加$10,000、收益增加$30,000、權益無影響", "阿呆:資產增加$30,000、負債減少$10,000、費損減少$10,000、收益增加$30,000、權益無影響", "小新:資產無影響、負債增加$10,000、費損增加$10,000、收益增加$30,000、權益增加$30,000", "正男:資產增加$30,000、負債增加$10,000、費損增加$10,000、收益增加$30,000、權益增加$20,000"], "answer": "D", "figure": null, "official": "3/1 借:進貨(費損) 10,000 貸:應付票據 10,000;3/8 借:銀行存款 30,000 貸:銷貨收入 30,000;淨利 $20,000 使權益增加。", "explain": {"concept": "考交易對資產、負債、權益、收益、費損的影響,以及收益與費損最後都會轉入權益(淨利增加權益)。", "steps": ["定期盤存制下買商品記「進貨」,進貨屬費損。3/1 分錄:借:進貨 10,000、貸:應付票據 10,000 → 費損增加 $10,000、負債增加 $10,000(簽發票據是欠錢)。", "3/8 賣出商品收到即期支票並存入銀行,分錄:借:銀行存款 30,000、貸:銷貨收入 30,000 → 資產增加 $30,000、收益增加 $30,000。(定期盤存制賣出時不記銷貨成本。)", "收益與費損最後會結入權益:淨利 = 收益 $30,000 − 費損 $10,000 = $20,000,所以權益增加 $20,000。", "對照選項:資產 +30,000、負債 +10,000、費損 +10,000、收益 +30,000、權益 +20,000 → 只有正男(D)全對。"], "pitfalls": "權益要看的是淨利($20,000),不是單看收益($30,000)。", "distractors": {"A": "收益 30,000 與費損 10,000 都有變動,卻說權益無影響,忘了淨利會增加權益。", "B": "簽發票據是負債增加,不是減少;進貨是費損增加,不是減少。", "C": "銀行存款增加 30,000,資產不是「無影響」;且權益增加數應是淨利 20,000,不是收益 30,000。"}}, "check": "python 驗算:淨利=30,000-10,000=20,000,與(D)相符。", "verified": true, "note": ""}, {"id": "113-3-A-03", "exam": "113-3", "paper": "A", "q": 3, "unit": "二、會計循環及會計帳簿", "topic": "會計憑證", "stem": "小丸子和小玉是會計部門的同事,他們正在討論下列交易事項相關之處理,「企業以現金支付辦公大樓全部租金$80,000,因 1~3 樓供企業營業用,4 樓是業主住家」,租金依樓層使用比例認列企業與業主應負擔之費用」,以下小丸子與小玉的對話,對話中有哪一項會計觀念錯誤?", "options": ["小丸子:「房東給我們收據是『原始憑證』嗎?」小玉:「是原始憑證的『對外憑證』」", "小丸子:「分錄該如何做?」小玉:「借:租金支出$60,000、業主往來$20,000  貸:現金$80,000,而且這筆交易是『現金交易』」", "小丸子:「我們公司記帳憑證是採用複式傳票三分法,那要編製哪一種傳票?」小玉:「複式傳票中的『現金支出傳票』」", "小丸子:「會計憑證要保存幾年?」小玉:「會計憑證除應永久保存或未結事項外,至少保存 5 年,它包含『原始憑證』和『記帳憑證』」"], "answer": "A", "figure": null, "official": "(A)房東給的收據是原始憑證中的「外來憑證」,不是對外憑證。", "explain": {"concept": "考會計憑證的種類(外來/對外/內部憑證)、分錄、傳票與保存年限。", "steps": ["(A)房東開給我們的收據,是「從外面來到本公司」的憑證 → 叫「外來憑證」;「對外憑證」則是本公司開給別人的(如我們開出的發票、收據)。所以小玉說錯了。", "(B)租金 $80,000 的 4 樓由業主住,不是企業費用:3/4 的企業負擔 = $80,000 × 3/4 = $60,000 記租金支出,其餘 $20,000 記業主往來;分錄借:租金支出 60,000、業主往來 20,000,貸:現金 80,000。全部以現金收付,屬現金交易,正確。", "(C)複式傳票三分法有現金收入、現金支出、轉帳三種傳票;有現金支出就編「現金支出傳票」,正確。", "(D)會計憑證(原始憑證+記帳憑證)除應永久保存或未結事項外,至少保存 5 年,正確。所以錯誤的是(A)。"], "pitfalls": "「外來」與「對外」名稱很像,記法:外來=別人給我的;對外=我給別人的。", "distractors": {"B": "此選項分錄與交易分類皆正確,不是答案。", "C": "現金支出用現金支出傳票,是正確敘述。", "D": "保存 5 年、含原始與記帳憑證,是正確敘述。"}}, "check": "概念題,依商業會計法與官方詳解確認;分錄 60,000+20,000=80,000 借貸平衡。", "verified": true, "note": ""}, {"id": "113-3-A-04", "exam": "113-3", "paper": "A", "q": 4, "unit": "六、試算與試算表", "topic": "試算表錯誤影響", "stem": "有一筆交易事項,以現金償還貨款$90,000,並獲得折讓$1,000,誤以借:應付帳款$90,000 貸:應付票據$90,000 入帳,下列有關對試算表影響之敘述何者正確?", "options": ["若為總額式試算表借貸仍不平衡,但借貸方合計數均高估$1,000", "若為總額式試算表借貸仍不平衡,但借貸方合計數均低估$1,000", "若為餘額式試算表借貸仍平衡,借貸方合計數均高估$89,000", "若為餘額式試算表借貸不平衡,借貸方合計數相差$1,000"], "answer": "C", "figure": null, "official": "正確分錄:借 應付帳款 90,000,貸 進貨折讓 1,000、現金 89,000;誤記借貸各 90,000,總額式借貸方合計都少算 $90,000,餘額式借貸方餘額都高估 $89,000。", "explain": {"concept": "考錯誤對試算表的影響:先寫出「正確分錄」和「錯誤分錄」,比較借方、貸方各差多少。", "steps": ["正確分錄:借:應付帳款 90,000;貸:進貨折讓 1,000、現金 89,000。借貸都是 90,000,平衡。", "錯誤分錄:借:應付帳款 90,000;貸:應付票據 90,000。借貸也都是 90,000,所以試算表仍然平衡(錯誤是借貸等額的錯,試算表看不出來)。", "總額式試算表(看借、貸方「累計總額」):正確與錯誤的借、貸方都各增加 $90,000,兩者相同 → 總額式合計數正確,(A)(B)說高估/低估 1,000 都不對。", "餘額式試算表(看各帳戶「餘額」):應付帳款餘額(貸)兩種都減少 90,000;但錯誤分錄多了「應付票據」貸方餘額 +90,000,卻少了正確分錄中的「現金餘額減少 89,000(借方少)」與「進貨折讓 +1,000(貸方多)」。把差異算出來:正確情況借方 −89,000、貸方 −90,000 + 1,000 = −89,000;錯誤情況借、貸方都是 0(−90,000 + 90,000)。", "所以餘額式試算表仍平衡,但借方、貸方合計數都比正確數高估 $89,000 → 選(C)。"], "pitfalls": "別因為金額有 $1,000 折讓就以為會不平衡;借貸等額的錯誤不會使試算表失衡。", "distractors": {"A": "以為折讓 1,000 會造成總額高估;其實總額式兩種分錄借貸合計都是 90,000。", "B": "同上,誤把折讓 1,000 當成差額。", "D": "以為借貸會差 1,000;實際兩邊差異同為 89,000,依然平衡。"}}, "check": "手算餘額式:正確 借−89,000、貸−89,000;錯誤 0、0;兩邊都高估 89,000,與(C)相符。", "verified": true, "note": ""}, {"id": "113-3-A-05", "exam": "113-3", "paper": "A", "q": 5, "unit": "七、調整", "topic": "期末調整後淨利", "stem": "會計人員在期末發現有以下項目未作調整:①房屋當年度的折舊$5,300、②採權責基礎下盤點文具後得知當年已耗用文具用品共$1,700、③期初「應收帳款」借餘$200,000、「備抵損失-應收帳款」貸餘$2,000。調整前「應收帳款」借餘$275,000、「備抵損失-應收帳款」借餘$200,已知每年估計帳款損失率皆相同。④期末有應收未收租金$16,800。若調整前淨利為$71,000,則調整後淨利為多少?", "options": ["$77,850", "$78,250", "$81,450", "$82,000"], "answer": "A", "figure": null, "official": "折舊 −5,300、文具 −1,700、損失率 2,000÷200,000=1%,應提損失 275,000×1%+200=2,950 → −2,950、租金 +16,800;71,000−5,300−1,700−2,950+16,800=77,850。", "explain": {"concept": "考期末調整對淨利的影響:費用增加→淨利減少;收益增加→淨利增加。備抵損失要用「提列後餘額 − 調整前餘額」。", "steps": ["①折舊 $5,300 未記 → 補記後費用增加,淨利 −$5,300。", "②文具已耗用 $1,700 未記 → 補記用品費用,淨利 −$1,700。", "③先求損失率:期初備抵損失 $2,000 ÷ 應收帳款 $200,000 = 1%。期末應收帳款 $275,000 × 1% = $2,750 是備抵損失「應有的貸方餘額」。", "調整前備抵損失是「借餘 $200」(代表多沖銷了),要補到貸餘 $2,750,所以要提列 $2,750 + $200 = $2,950(預期信用減損損失,淨利 −$2,950)。", "④應收未收租金 $16,800 → 補記租金收入,淨利 +$16,800。", "合計:$71,000 − $5,300 − $1,700 − $2,950 + $16,800 = $77,850 → 選(A)。"], "pitfalls": "備抵損失原為借餘時,要「加上」借餘,不是減掉;應收租金是收益增加,不要減。", "distractors": {"B": "把調整前借餘 $200 當成貸餘,算成提列 $2,550,淨利多算 $400。", "C": "把文具耗用 $1,700 當成加項,且備抵損失只算 $2,750(忘記加借餘 $200)。"}}, "check": "python:71000-5300-1700-(275000*0.01+200)+16800=77850,與官方(A)相符。", "verified": true, "note": ""}, {"id": "113-3-A-06", "exam": "113-3", "paper": "A", "q": 6, "unit": "七、調整", "topic": "錯誤對保留盈餘影響", "stem": "已知公司對存貨盤存採實地盤存制,去年期末存貨低估$100 且今年預收租金高估$200,在不考慮所得稅情況下,這兩項錯誤對今年底的「保留盈餘」之影響為何?", "options": ["高估$200", "高估$300", "低估$100", "低估$200"], "answer": "D", "figure": null, "official": "去年期末存貨低估會在今年期初存貨自動抵銷,不影響今年底保留盈餘;預收租金高估 $200 → 租金收入低估 $200 → 年底保留盈餘低估 $200。", "explain": {"concept": "考存貨錯誤的「自動抵銷」特性,以及調整錯誤對保留盈餘的累積影響。", "steps": ["去年期末存貨低估 $100 → 去年銷貨成本高估 → 去年淨利低估 $100(去年底保留盈餘低估 $100)。", "實地盤存制下,去年期末存貨就是今年期初存貨,今年期初存貨也低估 $100 → 今年銷貨成本低估 $100 → 今年淨利高估 $100。", "去年低估 $100、今年高估 $100,兩年相抵,到今年底保留盈餘已經「恢復正確」,存貨錯誤影響為 $0。", "預收租金高估 $200:本期應轉為收益的部分沒轉 → 租金收入低估 $200 → 淨利低估 $200,這是今年的錯誤,不會自動抵銷,今年底保留盈餘低估 $200。", "合計:$0 + (−$200) = 低估 $200 → 選(D)。"], "pitfalls": "期末存貨錯誤兩年內自動抵銷,但預收收益調整錯誤要看當年有沒有被後續年度沖回。", "distractors": {"A": "把預收租金高估誤認為收益高估,方向弄反。", "B": "把去年存貨低估 100 與租金方向搞錯後相加。", "C": "只算了存貨低估 100,忽略它已被今年自動抵銷,且漏了租金錯誤。"}}, "check": "推演:RE 影響 = 去年(−100)+今年存貨(+100)+租金(−200)=−200,與(D)相符。", "verified": true, "note": ""}, {"id": "113-3-A-07", "exam": "113-3", "paper": "A", "q": 7, "unit": "八、結帳", "topic": "結帳敘述", "stem": "有關結帳之敘述,下列何者正確?", "options": ["獨資企業若發生淨損時,結帳分錄,借:業主往來、貸:本期損益", "結帳後試算表中會出現「各項攤提」的會計項目", "實帳戶的結帳方法有「英美式結轉法」與「大陸式結轉法」,其中採「英美式結轉法」期末需作結帳分錄", "根據結帳後試算表可以編綜合損益表"], "answer": "A", "figure": null, "official": "(B)結帳後試算表只有實帳戶;(C)英美式不需作結帳分錄,僅需在分類帳上將餘額結轉下期;(D)結帳後試算表無虛帳戶故無法編製綜合損益表。", "explain": {"concept": "考結帳的觀念:虛帳戶結清、實帳戶結轉,淨損淨利的結轉分錄。", "steps": ["(A)淨損代表虧錢,「本期損益」會是借餘,要把它結清:借:業主往來(或業主資本)、貸:本期損益,正確。(若是淨利則相反:借:本期損益、貸:業主往來。)", "(B)「各項攤提」是虛帳戶(費用),已在結帳時結清,所以結帳後試算表看不到,錯。", "(C)實帳戶結轉:英美式只是在分類帳結出餘額、結轉下期,不需作結帳分錄;大陸式才需作結清與開帳分錄。選項說反了,錯。", "(D)結帳後試算表只剩實帳戶(資產、負債、權益),沒有收益與費損,所以不能編綜合損益表,錯。"], "pitfalls": "英美式、大陸式的結轉常被搞反;結帳後試算表只含實帳戶。", "distractors": {"B": "忘了攤提(費用)是虛帳戶,結帳已清空。", "C": "把英美式與大陸式的作法顛倒。", "D": "結帳後試算表沒有收益、費損,無法編綜合損益表。"}}, "check": "概念題,與官方詳解及會計常識一致。", "verified": true, "note": ""}, {"id": "113-3-A-08", "exam": "113-3", "paper": "A", "q": 8, "unit": "九、財務報表", "topic": "銷貨成本率計算", "stem": "凱米公司 09 年度銷貨收入$97,000、進貨$70,000、銷貨運費$3,200、進貨退出$1,200,已知可售商品總成本$90,000,期末存貨為期初存貨 1.5 倍,則銷貨成本率為何?(四捨五入取到百分位小數位第二位)", "options": ["64.95%", "60.00%", "36.74%", "32.62%"], "answer": "B", "figure": null, "official": "設期初存貨 x:x+70,000−1,200=90,000,x=21,200;期末存貨 31,800;銷貨成本 58,200;58,200÷97,000=60.00%。", "explain": {"concept": "考「可售商品總成本 = 期初存貨 + 進貨淨額」及銷貨成本 = 可售商品總成本 − 期末存貨。", "steps": ["進貨淨額 = 進貨 $70,000 − 進貨退出 $1,200 = $68,800。注意「銷貨運費」$3,200 是銷售費用(運出商品給客人),不是進貨成本,不能加進進貨。", "可售商品總成本 = 期初存貨 + 進貨淨額 → $90,000 = x + $68,800,期初存貨 x = $21,200。", "期末存貨 = 1.5 × $21,200 = $31,800。", "銷貨成本 = $90,000 − $31,800 = $58,200。", "銷貨淨額 = $97,000(題目只給銷貨收入,沒有退回折讓)。銷貨成本率 = $58,200 ÷ $97,000 = 0.6 = 60.00% → 選(B)。"], "pitfalls": "銷貨運費(賣方負擔)是營業費用,進貨運費才加進進貨成本。", "distractors": {"A": "把銷貨運費 $3,200 加進進貨,算出期初存貨 $18,000、期末 $27,000、銷貨成本 $63,000,63,000÷97,000=64.95%。"}}, "check": "python:x=90000-(70000-1200)=21200;COGS=90000-31800=58200;58200/97000=60.00%。選項 A 為忽略運費性質的陷阱值,確認非答案。", "verified": true, "note": ""}, {"id": "113-3-A-09", "exam": "113-3", "paper": "A", "q": 9, "unit": "九、財務報表", "topic": "財務比率分析", "stem": "全民瘋 AI 產業,阿達打算從甲、乙兩間從事 AI 產業同規模的公司進行投資,阿達先從今年度財務報表了解這兩間公司財務狀況及績效來分析財務比率,下列敘述何者錯誤?(假設不考慮所得稅)\n\n| 項目 | 甲公司 | 乙公司 |\n|---|---|---|\n| 流動資產 | $1,650 | $2,160 |\n| 流動負債 | 1,100 | 1,200 |\n| 總資產 | 90,000 | 52,500 |\n| 總負債 | 45,000 | 21,000 |\n| 銷貨淨額 | 40,000 | 25,000 |\n| 銷貨成本 | 10,000 | 15,000 |\n| 營業費用 | 15,000 | 6,000 |\n| 營業外收入 | 400 | 8,120 |\n| 營業外支出 | 300 | 120 |\n", "options": ["甲公司短期償債能力劣於乙公司", "甲公司銷貨毛利率優於乙公司,代表甲公司主要營業活動獲利績效佳", "乙公司營業利益劣於甲公司,都是因銷貨成本過高,與營業費用無關", "乙公司純益率優於甲公司,主要原因是乙公司營業外收入所帶來的成果"], "answer": "C", "figure": null, "official": "營業利益甲 $15,000、乙 $4,000;營業利益=毛利−營業費用,除銷貨成本外也與營業費用有關,故(C)錯。", "explain": {"concept": "考流動比率、毛利率、營業利益、純益率等財務比率的計算與解讀。", "steps": ["(A)流動比率 = 流動資產 ÷ 流動負債:甲 1,650÷1,100 = 1.5,乙 2,160÷1,200 = 1.8,乙較大 → 甲短期償債能力較差,敘述正確。", "(B)毛利率 = 銷貨毛利 ÷ 銷貨淨額:甲 (40,000−10,000)÷40,000 = 0.75,乙 (25,000−15,000)÷25,000 = 0.4,甲較高,敘述正確。", "(C)營業利益 = 毛利 − 營業費用:甲 30,000 − 15,000 = 15,000;乙 10,000 − 6,000 = 4,000。乙較低,原因除了毛利較低(銷貨成本佔比高),營業費用也有影響(乙的營業費用佔銷貨淨額 24%,甲 37.5%,但乙毛利更小),不能說「與營業費用無關」,所以(C)錯誤 → 選(C)。", "(D)純益 = 營業利益 + 營業外收入 − 營業外支出:甲 15,000+400−300 = 15,100,純益率 15,100÷40,000 = 37.75%;乙 4,000+8,120−120 = 12,000,純益率 12,000÷25,000 = 48%。乙較高,主要因營業外收入 8,120 很大,敘述正確。"], "pitfalls": "題目問「錯誤」;(C)用「都是…與…無關」的絕對說法就要特別小心。", "distractors": {"A": "此為正確敘述(乙流動比率較高),不是答案。", "B": "此為正確敘述(甲毛利率 75% 較高)。", "D": "此為正確敘述(乙純益率 48% 較高)。"}}, "check": "python:流動比 1.5/1.8;毛利率 .75/.4;營業利益 15,000/4,000;純益率 .3775/.48,與官方相符。", "verified": true, "note": ""}, {"id": "113-3-A-10", "exam": "113-3", "paper": "A", "q": 10, "unit": "十、加值型營業稅會計實務", "topic": "營業稅", "stem": "有關營業稅之敘述,下列何者正確?", "options": ["所謂小規模營業人,係因規模狹小,平均每月銷貨毛利未達20萬元,按查定課徵營業稅之營業人,非加值型營業稅體系營業人", "使用特種統一發票的店家,銷售對象限定為營業人", "外銷商品適用零稅率的店家,向加值稅體系營業人購買商品時仍須支付 5%營業稅,其進項稅額可以申請退稅", "加值型營業稅之稅率一律為 5%"], "answer": "C", "figure": null, "official": "(A)每月銷售額未達 20 萬元;(B)使用特種統一發票的店家銷售對象營業人或非營業人皆可;(D)加值型營業稅的稅率有 5%、0%、免稅。", "explain": {"concept": "考營業稅的基本規定:小規模營業人標準、特種統一發票、零稅率、稅率。", "steps": ["(A)小規模營業人的標準是「每月銷售額」未達 $20 萬元(不是銷貨毛利),錯。", "(B)特種統一發票(如銀行、保險業用)的銷售對象不限於營業人,營業人或非營業人皆可,錯。", "(C)外銷適用零稅率:銷項稅額 0%,但向上游購買商品時仍付 5% 進項稅額,這筆進項稅額可以申請退稅,正確。", "(D)加值型營業稅稅率有 5%、零稅率 0%,還有免稅,不是一律 5%,錯。"], "pitfalls": "選項(A)把「銷售額」偷換成「銷貨毛利」,是常見的陷阱。", "distractors": {"A": "把小規模標準誤成「銷貨毛利」未達 20 萬。", "B": "以為特種統一發票只能開給營業人。", "D": "忽略零稅率與免稅。"}}, "check": "概念題,與官方詳解及營業稅法規一致。", "verified": true, "note": ""}, {"id": "113-3-A-11", "exam": "113-3", "paper": "A", "q": 11, "unit": "十一、現金及內部控制", "topic": "零用金制度", "stem": "小芸上高中後,媽媽就以小芸現在所學會計學的「零用金制度」運用在給小芸的零用錢上。今年 9 月初媽媽給小芸$5,000 設置零用金,平時支用時不用跟媽媽報備,但要將發票、收據留存好並作備忘記錄,等到月底再跟媽媽報銷費用並撥補零用金。9 月底小芸手存現金$124,餐飲發票共計$3,289、髮妝用品$1,423、文具用品$148。以企業會計處理之「零用金制度」觀點,下列敘述何者錯誤?", "options": ["撥補後的「零用金」帳戶餘額為$5,000", "若未撥補應貸記零用金$4,860", "9 月底撥補時應借記:現金短溢$16", "若撥補,並同時將零用金額度提高至$6,000,則應貸記:現金$5,876"], "answer": "B", "figure": null, "official": "零用金應支用 $5,000−$124=$4,876,發票合計 $4,860,短少 $16。未撥補應貸記零用金 $4,876,不是 $4,860。", "explain": {"concept": "考零用金定額制:支用數 = 設置額 − 手存現金;發票不足者列現金短溢。", "steps": ["已支用金額 = 設置額 $5,000 − 手存現金 $124 = $4,876。", "發票合計 = $3,289 + $1,423 + $148 = $4,860。差額 $4,876 − $4,860 = $16 → 現金短少 $16(借:現金短溢 16)。", "撥補分錄:借:餐飲費等費用 4,860、現金短溢 16,貸:現金 4,876。撥補後零用金餘額回到 $5,000,(A)(C)正確。", "(B)若未撥補、直接把費用入帳,是貸記「零用金」$4,876(因為零用金實際少了 4,876),不是 $4,860,所以(B)錯誤。", "(D)提高額度到 $6,000:貸記現金 = 撥補 $4,876 + 增加額度 $1,000 = $5,876,正確。"], "pitfalls": "別忘了現金短溢也要算進零用金的減少數。", "distractors": {"A": "撥補後零用金回到定額 $5,000,敘述正確。", "C": "短少 $16 要借記現金短溢,敘述正確。", "D": "4,876+1,000=5,876,敘述正確。"}}, "check": "python:5000-124=4876;發票合計 4860;差 16;4876+1000=5876,與官方(B)為錯誤敘述相符。", "verified": true, "note": ""}, {"id": "113-3-A-12", "exam": "113-3", "paper": "A", "q": 12, "unit": "十一、現金及內部控制", "topic": "銀行存款調節表", "stem": "仁愛公司 4 月底支票存款帳面餘額$94,000,並有以下未達帳:銀行託收票據$6,200、銀行手續費$120、在途存款$8,300、未兌現支票$6,100(含保付支票$1,600 及 2 月份開出迄今尚未兌現之支票$500),則 4 月底銀行存款調節表中之金額,下列敘述何者錯誤?", "options": ["銀行對帳單餘額為$95,780", "銀行對帳單餘額為$96,280", "調節表正確銀行存款餘額為$100,080", "4 月底撥補時,調整分錄應借記:銀行存款$6,080"], "answer": "A", "figure": null, "official": "公司帳面 94,000+6,200−120=100,080;銀行對帳單 x+8,300−(6,100−1,600)=100,080,x=96,280。", "explain": {"concept": "考銀行存款調節表:雙方餘額調整到「正確餘額」,保付支票不是未兌現支票。", "steps": ["公司帳面餘額調整:$94,000 + 託收票據 $6,200 − 手續費 $120 = $100,080(正確餘額)。", "銀行方:未兌現支票要扣除,但「保付支票」銀行在簽證時已扣款,不算未兌現,所以未兌現支票 = $6,100 − $1,600 = $4,500(其中 2 月份的 $500 仍然是未兌現,照扣)。", "銀行對帳單餘額 + 在途存款 $8,300 − 未兌現支票 $4,500 = $100,080 → 對帳單餘額 = $100,080 − $8,300 + $4,500 = $96,280。所以(B)(C)正確,(A) $95,780 錯誤 → 選(A)。", "(D)調整分錄:借:銀行存款 6,080、手續費 120,貸:應收票據 6,200,借記銀行存款 $6,080 正確。"], "pitfalls": "保付支票要從未兌現支票中剔除;題目問「錯誤」。", "distractors": {"B": "96,280 正確。", "C": "100,080 正確。", "D": "6,200−120=6,080,正確。"}}, "check": "python:94000+6200-120=100080;100080-8300+4500=96280,與官方(A)為錯誤敘述相符。", "verified": true, "note": ""}, {"id": "113-3-A-13", "exam": "113-3", "paper": "A", "q": 13, "unit": "十二、應收款項", "topic": "附退貨權銷貨", "stem": "有關附退貨權銷貨會計處理之敘述,下列何者錯誤?", "options": ["若商品無法合理估計被退貨的比例,則全數認列為「退款負債」", "若商品估計不會被退貨的部分,認列為「銷貨收入」", "若商品估計將會被退貨的部分,認列為「退款負債」", "若實際退貨與原估計金額不同視為會計錯誤,要追溯調整"], "answer": "D", "figure": null, "official": "實際退貨與估計不同視為估計變動,調整銷貨收入,不是會計錯誤。", "explain": {"concept": "考附退貨權銷貨:預期不退才認列收入,預期退的部分認列退款負債;實際與估計不同為估計變動。", "steps": ["預期不會被退貨的部分才可以認列「銷貨收入」,(B)正確。", "預期會被退貨的部分,先認列為「退款負債」,(C)正確。", "若沒辦法合理估計退貨比例,就保守地全部先放在「退款負債」,(A)正確。", "實際退貨與原估計不同,是估計變動(用新資訊修正估計),只調整當期的銷貨收入,不必追溯調整,不是會計錯誤,所以(D)錯誤 → 選(D)。"], "pitfalls": "估計變動採「推延適用」(往後調整);會計錯誤才追溯。", "distractors": {"A": "此為正確處理(無法估計則全額先列負債)。", "B": "此為正確處理。", "C": "此為正確處理。"}}, "check": "概念題,與官方詳解及準則一致。", "verified": true, "note": ""}, {"id": "113-3-A-14", "exam": "113-3", "paper": "A", "q": 14, "unit": "十二、應收款項", "topic": "不附息票據入帳", "stem": "下列不附息票據中,何者得以「面值」入帳?", "options": ["汽車公司出售汽車收到一張 6 個月期票據", "因借款給同業收到一張 18 個月期票據", "家具店出售土地收到一張 4 個月期票據", "文具店出售文具一批收到 14 個月期票據"], "answer": "A", "figure": null, "official": "(B)非主要營業活動,票據期間超過一年,按現值入帳;(C)非主要營業活動,按現值入帳;(D)主要營業活動,但票據期間超過一年,按現值入帳。", "explain": {"concept": "考不附息票據的入帳基礎:一年內且屬主要營業活動才可用面值,其餘用現值。", "steps": ["先判斷是不是「主要營業活動」:汽車公司賣汽車、文具店賣文具,是本業;借款給同業、家具店賣土地,不是本業。", "再判斷票據期間是否超過一年:6 個月、4 個月沒超過;18 個月、14 個月超過。", "(A)本業 + 6 個月(一年內)→ 利息影響不大,得以面值入帳。", "(B)非本業且超過一年 → 現值;(C)出售土地為非主要營業活動 → 現值;(D)本業但 14 個月超過一年 → 現值。只有(A)可用面值 → 選(A)。"], "pitfalls": "兩個條件要同時成立:主要營業活動 + 一年以內。", "distractors": {"B": "非本業且超過一年,要現值。", "C": "土地買賣不是家具店的本業,即使短期也要現值。", "D": "本業,但超過一年,仍要現值。"}}, "check": "概念題,與官方詳解一致。", "verified": true, "note": ""}, {"id": "113-3-A-15", "exam": "113-3", "paper": "A", "q": 15, "unit": "十二、應收款項", "topic": "應收票據貼現", "stem": "丙公司將一年期、年息 4%,面值$10,000 之應收票據,於到期前三個月持向銀行貼現,已知貼現日認列之「應收票據貼現負債折價」金額為$56,試計算貼現率為何?", "options": ["9%", "8%", "7%", "6%"], "answer": "D", "figure": null, "official": "到期值 10,400;持有 9 個月利息 300;貼現金額 10,300−56=10,244;貼現息 10,400−10,244=156;156=10,400×貼現率×3/12,貼現率=6%。", "explain": {"concept": "考附息票據貼現:到期值、貼現息、貼現金額的關係。", "steps": ["先算到期值:$10,000 × (1 + 4%) = $10,400(一年期,年息 4%)。", "票據持有到貼現日有 12 − 3 = 9 個月,已賺利息 = $10,000 × 4% × 9/12 = $300,所以貼現日票據帳面金額 = $10,300。", "「應收票據貼現負債折價」$56 是貼現日帳面金額與負債之間的差:貼現收到現金 = $10,300 − $56 = $10,244。", "貼現息 = 到期值 − 貼現所得 = $10,400 − $10,244 = $156。", "貼現息 = 到期值 × 貼現率 × 貼現期間 → $156 = $10,400 × r × 3/12,r = 156 ÷ 2,600 = 6% → 選(D)。"], "pitfalls": "貼現息是用「到期值」乘貼現率,不是用面值。", "distractors": {}}, "check": "python:10,400−10,244=156;156=10,400×0.06×3/12,成立,與官方(D)相符。", "verified": true, "note": ""}, {"id": "113-3-A-16", "exam": "113-3", "paper": "A", "q": 16, "unit": "十三、存貨", "topic": "期末存貨範圍", "stem": "下列敘述有幾項應列入公司期末存貨?\n①已購入之在途進貨,言明目的地交貨 ②已運出之在途銷貨,言明起運點交貨\n③飛天公司已向本公司訂購但尚未運出之商品 ④分期付款銷售的商品\n⑤寄放在他人公司的存貨", "options": ["僅③、⑤", "僅④、⑤", "僅①、②、③", "僅①、②、⑤"], "answer": "A", "figure": null, "official": "①目的地交貨為賣方存貨;②起運點交貨為買方存貨;③仍在倉庫,列入;④分期付款銷售為買方存貨;⑤寄放他人者列入。", "explain": {"concept": "考存貨所有權歸屬:誰擁有商品的風險與報酬,存貨就算誰的。", "steps": ["①買入的在途進貨,目的地交貨 → 貨到目的地前所有權還在賣方 → 不列入。", "②運出的在途銷貨,起運點交貨 → 貨一離開我們,所有權就轉給買方 → 不列入。", "③客人訂購但還沒運出 → 商品還在我們倉庫、所有權在我們 → 列入。", "④分期付款銷售 → 商品已交給買方,屬於買方存貨 → 不列入。", "⑤寄放在別人那裡的商品(寄銷),所有權仍在我們 → 列入。只有③⑤ → 選(A)。"], "pitfalls": "在途存貨看「交貨條件」:起運點交貨→買方負責;目的地交貨→賣方負責。", "distractors": {"B": "誤把分期付款銷售商品當成賣方存貨。", "C": "把①②在途商品當成列入。", "D": "同樣誤判在途與漏掉③。"}}, "check": "概念題,與官方詳解一致。", "verified": true, "note": ""}, {"id": "113-3-A-17", "exam": "113-3", "paper": "A", "q": 17, "unit": "十三、存貨", "topic": "存貨評價與成本", "stem": "下列敘述何者錯誤?", "options": ["本期發生存貨的淨變現價值回升,應貸記「銷貨成本」", "在永續盤存制下,向國外進貨時所產生之關稅,應借記「存貨」", "存貨後續衡量採逐項比較法所得帳面金額必定大於或等於分類比較法", "存貨成本流動假設採用「個別認定」法,僅適用於不可替換之存貨項目及依專案計畫生產(或購買)且能區隔的產品"], "answer": "C", "figure": null, "official": "逐項比較法所得帳面金額必定小於或等於分類比較法。", "explain": {"concept": "考存貨後續衡量(成本與淨變現價值孰低)及存貨成本內容。", "steps": ["(A)淨變現價值回升,要把以前提列的跌價損失沖回,貸記「銷貨成本」,正確。", "(B)進貨時的關稅是取得成本的一部分,永續盤存制借記「存貨」,正確。", "(C)逐項比較法每一項目都取「成本與淨變現價值孰低」,最後金額最小;分類比較法把同類放一起比,高低互相抵銷,金額較大。所以逐項比較法 ≤ 分類比較法,不是「≥」,(C)錯 → 選(C)。", "(D)個別認定法只用在不可替換、可區隔的存貨,正確。"], "pitfalls": "逐項最保守→金額最低;分類最寬鬆→金額較高。", "distractors": {"A": "此為正確敘述。", "B": "此為正確敘述。", "D": "此為正確敘述。"}}, "check": "概念題,與官方詳解一致。", "verified": true, "note": ""}, {"id": "113-3-A-18", "exam": "113-3", "paper": "A", "q": 18, "unit": "十三、存貨", "topic": "現金折扣(總額法/淨額法)", "stem": "公司賒購一批成交價總額為$60,000 之商品,現金折扣條件僅交易後 10 日內還款可享受,交易當日認列之「應付帳款」若以總額法入帳較淨額法多$1,200,今於折扣期間內支付現金$22,540,則獲得折扣金額為何?", "options": ["$600", "$540", "$460", "$320"], "answer": "C", "figure": null, "official": "折扣率 1,200÷60,000=2%;總額法應付帳款 22,540÷(1−2%)=23,000;折扣 23,000−22,540=460。", "explain": {"concept": "考現金折扣:總額法與淨額法的差額就是折扣總額,付款金額 = 應付金額 ×(1 − 折扣率)。", "steps": ["總額法應付帳款 = $60,000;淨額法 = $60,000 ×(1 − 折扣率)。差額 $1,200 就是折扣總額。", "折扣率 = $1,200 ÷ $60,000 = 2%。", "現在只還了一部分,付現金 $22,540,是「扣掉 2% 折扣之後」的金額,所以還清的帳款面額 = $22,540 ÷ (1 − 2%) = $23,000。", "折扣金額 = $23,000 − $22,540 = $460(也等於 $23,000 × 2%) → 選(C)。"], "pitfalls": "付的現金是已扣完折扣的金額,要除以(1 − 折扣率)還原。", "distractors": {}}, "check": "python:22540/0.98=23000;23000-22540=460,與官方(C)相符。", "verified": true, "note": ""}, {"id": "113-3-A-19", "exam": "113-3", "paper": "A", "q": 19, "unit": "十四、證券投資", "topic": "透過損益按公允價值衡量之金融資產", "stem": "有關「透過損益按公允價值衡量之金融資產」,下列敘述何者正確?", "options": ["購入時支付的交易成本計入金融資產的成本", "收到股票股利認列為「股利收入」", "在報表表達應分類為流動資產", "將當期公允價值變動列為本期損益"], "answer": "D", "figure": null, "official": "(A)交易成本列為手續費支出;(B)收到股票股利不作分錄,只重新計算每股帳面金額;(C)依預期持有期間可分類為流動資產或非流動資產。", "explain": {"concept": "考透過損益按公允價值衡量金融資產(FVTPL)的原始認列、股利與後續評價。", "steps": ["(A)FVTPL 購入時,交易成本(手續費)直接列為費用,不算資產成本,錯。", "(B)收到股票股利只是股數增加,不作分錄(不是收益),只要重算每股成本,錯。", "(C)這類金融資產依預期持有期間,可為流動或非流動資產,並非一律流動,錯。", "(D)期末依公允價值評價,公允價值變動列入當期損益(金融資產評價損益),正確 → 選(D)。"], "pitfalls": "FVTPL 的手續費是費用;FVOCI 才計入成本。", "distractors": {"A": "把交易成本資本化(其他分類才這樣做)。", "B": "現金股利才認列收入,股票股利不作分錄。", "C": "忽略可分類為非流動資產。"}}, "check": "概念題,與官方詳解一致。", "verified": true, "note": ""}, {"id": "113-3-A-20", "exam": "113-3", "paper": "A", "q": 20, "unit": "十四、證券投資", "topic": "FVTPL 年底金額", "stem": "甲公司 X1 年初以每股$18 購入乙公司普通股 10,000 股,另支付手續費$200,分類為「透過損益按公允價值衡量之金融資產」。X2 年中收到乙公司現金股利$1,600 及股票股利 100 股。乙公司 X1 年底及 X2 年底股票之每股公允價值分別為$22 及$16。甲公司 X2 年底資產負債表之「透過損益按公允價值衡量之金融資產」列示金額為何?", "options": ["$160,000", "$161,600", "$220,000", "$222,200"], "answer": "B", "figure": null, "official": "X2 年底股數 10,000+100=10,100 股,每股公允價值 $16,列示金額 10,100×16=161,600。", "explain": {"concept": "考金融資產期末依「公允價值 × 股數」列示;股票股利只增加股數。", "steps": ["金融資產期末依公允價值衡量,所以要先算出股數、再乘每股公允價值。", "X2 年收到的股票股利 100 股只增加股數,不作分錄,股數變成 10,000 + 100 = 10,100 股。", "現金股利 $1,600 是股利收入,不影響資產列示金額;手續費 $200 已列費用,也不影響。", "X2 年底列示金額 = 10,100 股 × $16 = $161,600 → 選(B)。"], "pitfalls": "要用 X2 年底的公允價值 $16 與增加後的股數;$22 是 X1 的價格。", "distractors": {"A": "忘記股票股利的 100 股,用 10,000×16。", "C": "用 X1 年底公允價值 $22 與原股數。", "D": "用 $22 並加入股票股利股數 10,100×22。"}}, "check": "python:(10000+100)*16=161600,與官方(B)相符。", "verified": true, "note": ""}, {"id": "113-3-A-21", "exam": "113-3", "paper": "A", "q": 21, "unit": "十四、證券投資", "topic": "FVTPL 淨損益", "stem": "丙公司 X1 年初以每股$53 購入丁公司 1,000 股普通股,每股面額$10,並支付手續費$1,000。對丁公司無重大影響力、分類為持有供交易。X1/6/30 收到現金股利每股$6、股票股利每股$2。X1/12/31 丁公司認列本期淨利$800,000,股票每股公允價值$50。丙公司 X1/12/31 將丁公司股票全部出售,並支付交易成本$1,200。X1 年度有關投資丁公司股票產生之淨損益為多少?", "options": ["淨利益$12,000", "淨利益$10,800", "淨利益$800", "$0"], "answer": "B", "figure": null, "official": "手續費 −1,000;現金股利 +6,000;股票股利 2÷10=20% → 1,200 股,年底公允價值 1,200×50=60,000,評價利益 60,000−53,000=7,000;出售交易成本 −1,200;合計 10,800。", "explain": {"concept": "考 FVTPL 全年損益:手續費費用、現金股利收入、股票股利增加股數、評價損益、處分費用。", "steps": ["購入成本 = 1,000 股 × $53 = $53,000;購入手續費 $1,000 列費用 → −$1,000。", "現金股利每股 $6 × 1,000 股 = $6,000 → 股利收入 +$6,000。(丁公司淨利不影響丙公司,因為無重大影響力。)", "股票股利每股 $2,面額 $10 → 股票股利 20%,可得 1,000 × 20% = 200 股,不作分錄,但股數變 1,200 股。", "年底公允價值 = 1,200 股 × $50 = $60,000,評價利益 = $60,000 − $53,000 = +$7,000。", "出售時支付交易成本 $1,200 → −$1,200(以公允價值出售,無處分損益)。", "淨損益 = −1,000 + 6,000 + 7,000 − 1,200 = $10,800 淨利益 → 選(B)。"], "pitfalls": "股票股利要換算成股數;交易成本購入與出售各列費用。", "distractors": {"D": "忽略各項損益,以為出售按公允價值就沒有損益。"}}, "check": "python:-1000+6000+(1200*50-53000)-1200=10800,與官方(B)相符。", "verified": true, "note": ""}, {"id": "113-3-A-22", "exam": "113-3", "paper": "A", "q": 22, "unit": "十五、長期營業用資產", "topic": "不動產廠房設備成本", "stem": "下列哪幾項會增加不動產、廠房及設備的成本?\n①賒購機器的現金折扣 ②廠房除役成本的現值\n③自用乘人小汽車所支付的營業稅 ④分期付款價格中的隱含利息\n⑤因受贈取得資產所支付的相關支出,如:過戶費", "options": ["僅①、④", "僅②、③", "僅①、②、③", "僅②、③、⑤"], "answer": "B", "figure": null, "official": "①列為未享折扣損失或利息費用;④列為利息費用;⑤相關支出應列為貸方項目金額的減少。②③會增加成本。", "explain": {"concept": "考不動產、廠房及設備的原始成本包含哪些支出。", "steps": ["①賒購機器的現金折扣:是購貨折扣,應(扣減成本或)列為進貨折扣/利息費用等,不會「增加」成本。", "②廠房的除役成本:取得資產時預期將來要拆除、復原的現值,要加入資產成本(同時認列負債),會增加成本。", "③自用乘人小汽車所支付的營業稅:乘人小客車進項稅額依法不得扣抵,所以要計入資產成本,增加成本。", "④分期付款價格中的隱含利息:要用利息費用處理,不是資產成本。", "⑤受贈取得資產的過戶費:題目的官方做法列為貸方項目(受贈收益等)金額的減少,不是增加資產成本。故只有②③ → 選(B)。"], "pitfalls": "「增加成本」只看取得並使資產達可使用狀態必要的支出;利息與折扣不算。", "distractors": {"A": "把折扣、隱含利息當成成本。", "C": "多選了現金折扣①。", "D": "多選了⑤,不符合官方做法(⑤列為貸方項目減少)。"}}, "check": "概念題,與官方詳解一致;⑤的處理依官方詳解。", "verified": true, "note": ""}, {"id": "113-3-A-23", "exam": "113-3", "paper": "A", "q": 23, "unit": "十五、長期營業用資產", "topic": "變更折舊方法與處分損益", "stem": "X1 年初購入載貨卡車一部,成本$800,000,估計耐用年限為 10 年,無殘值,採直線法提列折舊。X4 年初公司決定改採年數合計法提列折舊,估計剩餘耐用年限為 3 年,殘值$20,000,則若該公司於 X5 年 7 月 1 日將該卡車以$210,000 出售,出售分錄中應認列處分損益多少?", "options": ["損失$100,000", "損失$28,000", "利益$23,333", "利益$10,000"], "answer": "D", "figure": null, "official": "X4 年初帳面 560,000;X4 折舊 270,000;X5 年前半年折舊 90,000;7/1 帳面 200,000;處分利益 210,000−200,000=10,000。", "explain": {"concept": "考會計估計變動(折舊方法變更)往後適用,及年數合計法折舊計算。", "steps": ["X1~X3 直線法:每年 $800,000 ÷ 10 = $80,000,三年累計折舊 $240,000,X4 年初帳面金額 = $800,000 − $240,000 = $560,000。", "X4 年改年數合計法(估計變動,往後適用):剩餘 3 年,年數總和 = 1+2+3 = 6,折舊基礎 = $560,000 − $20,000 = $540,000。", "X4 年折舊 = $540,000 × 3/6 = $270,000。", "X5 年折舊 = $540,000 × 2/6 = $180,000,出售日是 7/1,只提 6 個月:$180,000 × 6/12 = $90,000。", "X5/7/1 帳面金額 = $560,000 − $270,000 − $90,000 = $200,000。", "處分損益 = 售價 $210,000 − 帳面金額 $200,000 = 利益 $10,000 → 選(D)。"], "pitfalls": "年數合計法的折舊基礎要扣殘值,且出售前要補提當年折舊。", "distractors": {}}, "check": "python:X4 初帳面 560,000;270,000;90,000;帳面 200,000;利益 10,000,與官方(D)相符。", "verified": true, "note": ""}, {"id": "113-3-A-24", "exam": "113-3", "paper": "A", "q": 24, "unit": "十五、長期營業用資產", "topic": "前期錯誤更正", "stem": "小光為初任會計人員,年初誤將機器的修繕費$4,000,列為機器的成本,並採直線法,按 4 年提列折舊,殘值為零。若第二年年底調整後結帳前發現此錯誤,小光要作的更正分錄應借記為何?", "options": ["本期損益$5,000", "追溯適用及追溯重編之影響數$5,000", "累計折舊-機器設備$2,000、追溯適用及追溯重編之影響數$3,000", "折舊$2,000、追溯適用及追溯重編之影響數$3,000"], "answer": "C", "figure": null, "official": "第 1 年修繕費少計 $4,000、折舊多計 $1,000,第 1 年淨利少計 $3,000;第 2 年折舊多計 $1,000。更正:借:累計折舊 2,000、追溯適用及追溯重編之影響數 3,000;貸:折舊 1,000、機器設備 4,000。", "explain": {"concept": "考會計錯誤更正(前期錯誤追溯重編):先分年算出對淨利與帳戶的影響。", "steps": ["錯誤做法:把修繕費 $4,000 資本化為機器成本,按 4 年折舊,每年多提折舊 $4,000 ÷ 4 = $1,000。", "第 1 年:正確應全數費用化 $4,000,但只提折舊 $1,000 → 費用少計 $3,000、淨利多計 $3,000(前期錯誤,影響期初保留盈餘)。", "第 2 年(當年):多提折舊 $1,000,當年費用多計 $1,000。", "至第 2 年底累計折舊多計 $1,000 × 2 = $2,000,機器設備成本多計 $4,000。", "更正分錄:借:累計折舊-機器設備 2,000、追溯適用及追溯重編之影響數 3,000;貸:折舊 1,000、機器設備 4,000。借方就是(C)。"], "pitfalls": "前期錯誤用「追溯適用及追溯重編之影響數」;當年錯誤直接調整當年帳戶。", "distractors": {"A": "本期損益不是前期錯誤更正借記的科目。", "D": "借記折舊會使折舊更多,與應貸記折舊的方向相反。"}}, "check": "python:4,000−1,000=3,000(前期影響);累計折舊 2×1,000=2,000;借方 2,000+3,000=5,000=貸方 1,000+4,000,借貸平衡,與官方(C)相符。", "verified": true, "note": ""}, {"id": "113-3-A-25", "exam": "113-3", "paper": "A", "q": 25, "unit": "十五、長期營業用資產", "topic": "土地成本(拆除舊屋)", "stem": "錢夫人看準臺灣人口逐漸老化,於是在花蓮購買土地準備要蓋養生村,這塊土地上有一棟舊房屋,房地產共計價款$400,000,房屋公允價值$50,000、土地公允價值$450,000,購入後舊屋立即拆除,並支付拆除費$30,000,拆除後殘料售得$5,000,則以上交易合併應借記為何?", "options": ["土地成本$425,000", "土地成本$475,000、房屋及建築成本$50,000", "土地成本$390,000、房屋及建築成本$35,000", "土地成本$385,000、房屋及建築成本$40,000"], "answer": "A", "figure": null, "official": "土地成本=$400,000+$30,000−$5,000=$425,000;舊屋購入後立即拆除,不再有房屋成本。", "explain": {"concept": "考土地成本:購入土地並立即拆除舊屋時,全部價款與拆除淨成本都算土地成本。", "steps": ["買地的目的是蓋新建物,舊屋購入後馬上拆除,表示舊屋沒有使用價值,所以不必依公允價值把價款分攤給房屋,整筆 $400,000 都算土地成本。", "拆除費 $30,000 是為了讓土地可供使用的必要支出 → 加到土地成本。", "拆除後殘料售得 $5,000 → 是土地成本的減項。", "土地成本 = $400,000 + $30,000 − $5,000 = $425,000,沒有房屋成本 → 選(A)。"], "pitfalls": "題目給的公允價值是干擾資訊;舊屋立即拆除就不分攤。", "distractors": {}}, "check": "python:400,000+30,000−5,000=425,000,與官方(A)相符。", "verified": true, "note": ""}, {"id": "113-4-A-01", "exam": "113-4", "paper": "A", "q": 1, "unit": "一、會計基本概念", "topic": "會計法令適用", "stem": "華中公司是臺灣一家非公開發行公司,其實收資本額共計 3 千 5 百萬;華大股份有限公司是臺灣一家公開發行公司,有關兩家公司會計事務處理所適用之各項法令及準則,下列何者正確?", "options": ["兩家公司均應適用「證券交易法」及「公司法」", "兩家公司均應適用「公司法」及「商業會計法」", "兩家公司均應適用「證券發行人財務報告編製準則」及「商業會計處理準則」", "兩家公司一般公認會計原則均可選用金管會認可之「國際財務報導準則」或中華民國會計研究發展基金會所制定之「企業會計準則公報」"], "answer": "B", "figure": null, "official": "兩家都是公司,適用公司法與商業會計法;僅公開發行公司適用證券交易法與證券發行人財務報告編製準則;華中適用企業會計準則。", "explain": {"concept": "這題考會計相關法令與準則,哪些公司適用哪些法規。", "steps": ["先看兩家公司的共同點:都是「公司」,所以都要適用「公司法」;只要是商業(營利事業),也都要適用「商業會計法」。所以 (B) 正確。", "(A) 證券交易法只管「公開發行」公司,華中是非公開發行,不適用,所以錯。", "(C) 「證券發行人財務報告編製準則」只有公開發行公司(華大)適用,華中不適用;「商業會計處理準則」兩家都適用,但前半句已錯。", "(D) 華大(公開發行)一般公認會計原則採用金管會認可的「國際財務報導準則(IFRS)」;華中(非公開發行)則適用「企業會計準則」,並不是兩家都能任選。"], "pitfalls": "記法:公司法、商業會計法=全部公司/商業都適用;證券交易法、證券發行人財報編製準則、IFRS=公開發行才適用。", "distractors": {"A": "以為所有公司都受證券交易法規範,忽略它只管公開發行公司。", "C": "把只適用公開發行公司的編製準則當成人人適用。", "D": "忽略公開發行與非公開發行適用的會計準則不同。"}}, "check": "概念題,依官方詳解與商業會計法、公司法、證券交易法常識雙重確認。", "verified": true, "note": ""}, {"id": "113-4-A-02", "exam": "113-4", "paper": "A", "q": 2, "unit": "一、會計基本概念", "topic": "會計基本假設", "stem": "王老師運用舉例方式將會計基本假設講授完畢,接著又舉了四個例子,並請四位學生判斷,則哪一位學生的答案完全正確?\n①企業員工之士氣無法入帳,係基於「貨幣評價假設」\n②將企業的機器設備成本於耐用年限內分攤,係基於「報導期間假設」\n③服飾店老闆自商店拿取服飾自用,需要進行相關記錄,係基於「企業個體假設」\n④將企業的經營過程採曆年制劃分成段落,定期編製財務報表,係基於「繼續經營假設」", "options": ["學生甲:正確例子僅有①、③", "學生乙:正確例子僅有②、④", "學生丙:正確例子僅有①、②、③", "學生丁:正確例子僅有②、③、④"], "answer": "A", "figure": null, "official": "②應為繼續經營假設;④應為報導期間假設,故正確為①③。", "explain": {"concept": "這題考會計基本假設:企業個體、繼續經營、報導期間、貨幣評價。", "steps": ["逐一判斷四個例子。", "①員工士氣無法用貨幣衡量,所以不能入帳,依「貨幣評價假設」,正確。", "②機器成本在耐用年限內分攤(折舊),是因為假設企業會持續經營下去,所以是「繼續經營假設」,不是報導期間假設,錯誤。", "③老闆拿店裡的服飾自用,要和店的帳分開記錄(通常記為業主往來),是「企業個體假設」,正確。", "④把經營過程用曆年切成一段一段、定期編報表,是「報導期間假設」,不是繼續經營假設,錯誤。", "正確的是①③,選 (A)。"], "pitfalls": "②④兩個假設名稱容易對調:繼續經營→分攤(折舊、遞延);報導期間→定期報導。", "distractors": {"B": "把②④的假設名稱弄反,選了錯誤的例子。", "C": "誤以為②也正確,把繼續經營與報導期間混淆。", "D": "同樣誤判②④,並漏掉①。"}}, "check": "概念題,依官方詳解與會計基本假設常識確認。", "verified": true, "note": ""}, {"id": "113-4-A-03", "exam": "113-4", "paper": "A", "q": 3, "unit": "二、會計循環及會計帳簿", "topic": "交易分類與傳票", "stem": "商店以現金支付電費$6,000,其中三分之一應由業主負擔,下列敘述何者正確?", "options": ["按交易是否涉及現金分類,此交易為「混合交易」", "按涉及會計項目多寡分類,此交易為「簡單交易」", "在複式傳票三分法下,此交易應編製「現金支出傳票」", "在複式傳票四分法下,此交易應編製「現金轉帳傳票」"], "answer": "C", "figure": null, "official": "分錄:借水電瓦斯費$4,000、業主往來$2,000,貸現金$6,000。為現金交易、多項式交易,應編現金支出傳票。", "explain": {"concept": "這題考交易的分類方式與傳票種類。", "steps": ["先寫分錄:電費$6,000 的 1/3 =$2,000 由業主負擔,所以:\n借:水電瓦斯費  4,000\n  借:業主往來  2,000\n  貸:現金  6,000", "判斷分類:貸方全是現金,借方沒有現金,屬「現金交易」(不是混合交易);借方有兩個科目,屬「多項式交易」(不是簡單交易)。", "傳票:不論三分法或四分法,只要是現金「支出」且全部為現金,就編「現金支出傳票」。", "所以 (C) 正確。"], "pitfalls": "現金交易=全部涉及現金;混合交易=一部分現金、一部分轉帳。本題現金恰好全額支付,故是現金交易。", "distractors": {"A": "把借方兩個科目誤以為有一部分不是現金,就當成混合交易。", "B": "忽略借方有兩個科目,誤判為簡單交易。", "D": "以為業主負擔部分不是現金所以要轉帳傳票;但現金是全額支付,仍編現金支出傳票。"}}, "check": "分錄推理:現金貸方$6,000 全額,為現金交易;與官方詳解一致。", "verified": true, "note": "歸類在傳票(二)或分錄(四)均可,選二。"}, {"id": "113-4-A-04", "exam": "113-4", "paper": "A", "q": 4, "unit": "六、試算與試算表", "topic": "錯誤更正方法", "stem": "小明應聘擔任大方商店會計人員,於試算時發現前任會計人員有下列交易帳務處理錯誤,現欲進行更正,則下列哪幾項錯誤須採用「註銷更正法」更正?\n①賒購商品$100,000,誤記為賒銷商品$10,000\n②簽發即期支票$8,000 購買商品,貸方誤用「應付票據」項目\n③現銷商品$65,000,借方金額誤記為$56,000,貸方金額記錄正確\n④以現金預付二年保險費$24,000,過帳時誤將「現金」項目過至借方\n⑤業主代商店支付電費$4,000,誤記為借:郵電費$400、貸:現金$400", "options": ["僅③、④", "僅③、④、⑤", "僅②、③、④、⑤", "僅①、③、④、⑤"], "answer": "A", "figure": null, "official": "③單方金額誤記、④單方過帳方向錯誤,影響借貸平衡,採註銷更正;①②⑤不影響借貸平衡,採分錄更正。", "explain": {"concept": "這題考錯誤更正:何時用註銷更正法、何時用分錄更正法。口訣:影響借貸平衡 → 註銷;不影響 → 分錄。", "steps": ["先看每項錯誤會不會讓試算表借貸不平衡。", "①賒購誤記為賒銷,借貸雙方金額都記 10,000,仍平衡,採分錄更正。", "②貸方用錯會計項目(應為現金/銀行存款),金額沒錯,仍平衡,採分錄更正。", "③借方記 56,000、貸方記 65,000,借貸不平衡,採註銷更正。", "④現金該貸方卻過到借方,單方向錯誤,借貸不平衡,採註銷更正。", "⑤借貸雙方都記 400(都少記),仍平衡,採分錄更正。", "需要註銷更正的只有③④,選 (A)。"], "pitfalls": "只要「借貸雙方都錯、同額」或只是「科目用錯」,試算表仍平衡,就用分錄更正。", "distractors": {"B": "誤以為⑤也影響平衡,其實借貸都是$400,仍平衡。", "C": "把②科目誤用當成須註銷,並誤判⑤。", "D": "誤以為①會造成不平衡,其實借貸雙方金額相同。"}}, "check": "概念題,依官方詳解與更正法則常識確認。", "verified": true, "note": ""}, {"id": "113-4-A-05", "exam": "113-4", "paper": "A", "q": 5, "unit": "七、調整", "topic": "調整觀念", "stem": "有關調整之敘述,下列何者正確?", "options": ["依據商業會計法規定,交易發生時採現金收付制入帳的企業,期末可免調整", "預計項目調整後的結果會因採用應計基礎或是聯合基礎而有不同", "會計基礎是劃分資產與負債所屬報導期間之標準", "調整可允當表達企業的財務狀況與財務績效"], "answer": "D", "figure": null, "official": "(A)現金收付制企業期末應依權責發生制調整;(B)預計項目調整結果不因基礎而不同;(C)會計基礎是劃分收益與費損所屬報導期間之標準。", "explain": {"concept": "這題考調整的目的與會計基礎。", "steps": ["(D) 調整是為了讓收益與費損歸屬正確的期間,使資產負債表與綜合損益表允當表達財務狀況與財務績效,正確。", "(A) 商業會計法規定,採現金收付制的企業,期末仍須依權責發生制予以調整,所以不能免。", "(B) 預計項目(如應收利息、應付薪資)不論用應計基礎或聯合基礎,期末調整結果都相同,錯。", "(C) 會計基礎是劃分「收益與費損」所屬報導期間的標準,不是資產與負債,錯。"], "pitfalls": "商業會計法:會計基礎以權責發生制為原則,現金收付制者期末仍需調整。", "distractors": {"A": "以為現金收付制就不用調整。", "B": "以為基礎不同,預計項目調整數就不同。", "C": "把「收益與費損」誤寫成「資產與負債」。"}}, "check": "概念題,依官方詳解與商業會計法確認。", "verified": true, "note": ""}, {"id": "113-4-A-06", "exam": "113-4", "paper": "A", "q": 6, "unit": "七、調整", "topic": "預付租金調整", "stem": "和泰公司 01 年 7 月 1 日預付三年租金,01 年底調整分錄為借記:租金支出$12,000、貸記:預付租金$12,000,則 02 年底調整後「預付租金」帳戶餘額應為何?", "options": ["$18,000", "$30,000", "$36,000", "$60,000"], "answer": "C", "figure": null, "official": "$12,000÷6×18=$36,000。", "explain": {"concept": "這題考預付費用的調整與月份計算:先由已知調整數反推每月租金。", "steps": ["01 年 7/1~12/31 共 6 個月,調整費用 $12,000,所以每月租金 = $12,000 ÷ 6 = $2,000。", "預付三年共 36 個月,總額 = $2,000 × 36 = $72,000。", "到 02 年底,已經過 7/1/01~12/31/02 共 18 個月,還剩 36 − 18 = 18 個月。", "02 年底預付租金餘額 = $2,000 × 18 = $36,000,選 (C)。", "也可用:01 年底 $72,000 − $12,000 = $60,000;02 年再費用 $2,000×12 = $24,000,$60,000 − $24,000 = $36,000。"], "pitfalls": "要分清「調整前」與「調整後」,以及是剩下幾個月,不要算成已用月份。", "distractors": {"A": "可能只算 9 個月(18,000÷2,000),算錯剩餘期間。", "B": "可能少算了 02 年的 12 個月攤銷數,只扣 6 個月。", "D": "這是 01 年底調整後的餘額,忘了 02 年再攤銷一年。"}}, "check": "python:12000/6=2000;2000*18=36000,與官方相符。", "verified": true, "note": ""}, {"id": "113-4-A-07", "exam": "113-4", "paper": "A", "q": 7, "unit": "九、財務報表", "topic": "本期損益計算", "stem": "大方商店會計基礎採權責發生制,存貨採定期盤存制,01 年度相關資料如下:\n現銷商品$100,000,賒銷商品$400,000,賒銷部分本年度全數收款並給予 1%折讓;現購商品$100,000,賒購商品$240,000,並支付進貨應負擔之運費$5,000,因品質瑕疵退貨$15,000,期初存貨$20,000,期末存貨$50,000;年底與營業費用相關帳戶資料如下:\n①調整前「薪資支出」帳戶餘額為$50,000,另有本年度 12 月份薪資$10,000 尚未支付\n②調整前「用品盤存」帳戶餘額為$5,000,期末盤存尚餘$1,000\n③水電瓦斯費共計$16,000、郵電費共計$5,000\n商店無營業外收入及支出,則 01 年度大方商店本期損益金額為何?", "options": ["$84,000", "$111,000", "$114,000", "$120,000"], "answer": "B", "figure": null, "official": "銷貨淨額$496,000−銷貨成本$300,000−營業費用$85,000=$111,000。", "explain": {"concept": "這題考利用定期盤存制計算銷貨淨額、銷貨成本、營業費用,再求本期損益。", "steps": ["銷貨淨額:現銷 $100,000 + 賒銷 $400,000 − 銷貨折讓(1%)$400,000×1% $4,000 = $496,000。", "進貨淨額:現購 $100,000 + 賒購 $240,000 + 進貨運費 $5,000 − 進貨退出 $15,000 = $330,000。", "銷貨成本 = 期初存貨 $20,000 + 進貨淨額 $330,000 − 期末存貨 $50,000 = $300,000。", "營業費用:薪資 $50,000 + 應付未付 $10,000 = $60,000;用品費用 = $5,000 − $1,000 = $4,000;水電瓦斯費 $16,000;郵電費 $5,000;合計 $60,000+$4,000+$16,000+$5,000 = $85,000。", "本期損益 = $496,000 − $300,000 − $85,000 = $111,000,選 (B)。"], "pitfalls": "折讓只扣賒銷 $400,000 的 1%,不是全部銷貨;用品要用「調整前餘額 − 期末盤存」。", "distractors": {"A": "可能多扣了費用(如多算用品$5,000,或重複計入未付薪資)。", "C": "可能漏算了部分費用或進貨運費,使損益偏高。", "D": "可能忘了扣銷貨折讓或把用品全額當成未使用。"}}, "check": "python 逐項計算:銷貨淨額496,000、銷貨成本300,000、營業費用85,000、損益111,000,與官方相符。", "verified": true, "note": "與財報計算相關,也可歸四或十三,選九。"}, {"id": "113-4-A-08", "exam": "113-4", "paper": "A", "q": 8, "unit": "九、財務報表", "topic": "流動比率與速動比率", "stem": "流動比率及速動比率代表企業短期償債能力的高低,比率越高表示短期償債能力越強。下列有兩家同產業別之企業,01 年 12 月 31 日相關資料如下:\n①甲公司原流動資產$100,000(包含現金$50,000、應收帳款$30,000、存貨$20,000)、流動負債$50,000,發現漏計客戶以現金$10,000 清償貨欠\n②乙公司原流動資產$200,000(包含現金$120,000、應收帳款$50,000、存貨$20,000、用品盤存$10,000)、流動負債$100,000,發現漏計本公司以現金$50,000 預付商品之訂金\n請根據兩家公司更正後資料,判斷下列敘述何者錯誤?", "options": ["甲公司流動比率為 2", "乙公司速動比率為 1.2", "若以速動比率判斷短期償債能力甲公司優於乙公司", "若以流動比率判斷短期償債能力甲公司優於乙公司"], "answer": "D", "figure": null, "official": "更正後甲流動比率 2、速動比率 1.6;乙流動比率 2、速動比率 1.2。流動比率相同,短期償債能力相同。", "explain": {"concept": "這題考更正漏記交易後,重算流動比率(流動資產÷流動負債)與速動比率(速動資產÷流動負債)。", "steps": ["甲公司更正:收到現金 $10,000(現金 +10,000),應收帳款減少 $10,000。流動資產仍 $100,000;流動比率 = 100,000 ÷ 50,000 = 2。速動資產 = 現金 60,000 + 應收帳款 20,000 = 80,000;速動比率 = 80,000 ÷ 50,000 = 1.6。", "乙公司更正:支付現金 $50,000 預付訂金(現金 −50,000,預付貨款 +50,000,預付貨款仍是流動資產)。流動資產 = $200,000 仍不變;流動比率 = 200,000 ÷ 100,000 = 2。", "乙速動資產 = 現金 (120,000 − 50,000) + 應收帳款 50,000 = 120,000;速動比率 = 120,000 ÷ 100,000 = 1.2。", "比較:速動比率甲 1.6 > 乙 1.2,甲較優;流動比率甲乙都是 2,一樣高,所以不能說甲優於乙。", "題目問「錯誤」,故選 (D)。"], "pitfalls": "速動資產只含現金、短期投資、應收款項,不含存貨、預付、用品。預付貨款不是速動資產。", "distractors": {"A": "此敘述正確(流動比率為 2),不是答案。", "B": "此敘述正確(速動比率 1.2),不是答案。", "C": "此敘述正確(1.6 > 1.2),不是答案。"}}, "check": "python:甲2、1.6;乙2、1.2,與官方相符。", "verified": true, "note": ""}, {"id": "113-4-A-09", "exam": "113-4", "paper": "A", "q": 9, "unit": "十、加值型營業稅會計實務", "topic": "營業稅申報", "stem": "大方公司為適用加值型營業稅的企業,01 年 7 月初帳載累積留抵稅額$50,000,01 年 7 月及 8 月發生了下列交易(以下金額均未含營業稅):國內銷貨金額$4,000,000 為外銷金額的 4 倍;進貨$2,000,000;購買設備金額$4,000,000(其中包含五人座自用乘用小汽車$600,000);營業費用支出$660,000(包含贈送客戶禮品$40,000、勞軍$10,000 及向小規模營業人購買文具用品$10,000)。營業稅稅率 5%皆為外加,9 月申報 7、8 月份營業稅時,「營業人銷售額與稅額申報書」中之金額,下列何者正確?", "options": ["本期銷項稅額合計$250,000", "得扣抵進項稅額合計$300,000", "本期累積留抵稅額$0", "本期應退稅額$220,000"], "answer": "C", "figure": null, "official": "銷項稅額$200,000;得扣抵進項稅額$300,500;本期申報留抵稅額$150,500;得退稅限額$220,000,取小者可全數退回,故累積留抵稅額$0。", "explain": {"concept": "這題考加值型營業稅:銷項稅額、不得扣抵的進項、留抵稅額及外銷、設備的退稅限額。", "steps": ["銷項稅額:國內銷貨 $4,000,000 × 5% = $200,000(外銷 $1,000,000 零稅率,無銷項稅額)。所以 (A) $250,000 錯。", "可扣抵進項稅額的基礎:進貨 $2,000,000 + 設備 $4,000,000 − 自用乘人小汽車 $600,000(不得扣抵)+ 營業費用 $660,000 − 不得扣抵的項目 $40,000(贈送客戶禮品)與 $10,000(官方式列此一筆),再乘 5%:($2,000,000 + $4,000,000 − $600,000 + $660,000 − $40,000 − $10,000) × 5% = $6,010,000 × 5% = $300,500。所以 (B) $300,000 錯。", "本期申報留抵稅額 = (進項 $300,500 + 期初留抵 $50,000) − 銷項 $200,000 = $150,500。", "得退稅限額 = (外銷 $1,000,000 + 設備 $3,400,000) × 5% = $220,000(設備扣除自用小汽車 $600,000)。留抵稅額 $150,500 < $220,000,取較小者,$150,500 可全數退回,所以應退稅額為 $150,500,(D) $220,000 錯;退稅後累積留抵稅額為 $0。", "所以只有 (C) 正確。"], "pitfalls": "退稅額=留抵稅額與得退稅限額「取小」;小客車與贈送禮品進項不得扣抵。", "distractors": {"A": "銷項稅額應為 $4,000,000 × 5% = $200,000,外銷是零稅率,不是 $250,000。", "B": "進項稅額精算是 $300,500,不是整數 $300,000。", "D": "把得退稅限額 $220,000 當成應退稅額,沒有與留抵稅額 $150,500 取小。"}}, "check": "python:(2000000+4000000-600000+660000-40000-10000)*0.05=300500;銷項200000;留抵150500;限額220000,與官方相符。", "verified": true, "note": "題幹營業費用中另有勞軍 $10,000 與向小規模營業人購買文具 $10,000,官方式只扣 $40,000 與 $10,000 共 $50,000;本人無法確認官方 −$10,000 對應哪一項,結果與官方一致($300,500),答案以官方為準。"}, {"id": "113-4-A-10", "exam": "113-4", "paper": "A", "q": 10, "unit": "十一、現金及內部控制", "topic": "零用金撥補", "stem": "大方公司設置定額零用金為$4,000,並於每月月底報銷撥補,已知本月份支付水電費$2,500、文具$600 及電話費$850,本月底盤點手存零用金餘額為$60,今開立即期支票撥補,並同時將零用金定額提高至$6,000。則下列敘述何者正確?", "options": ["應撥補之「銀行存款」共$5,940", "應認列費損總金額為$3,940", "撥補後「零用金」帳戶餘額為$4,000", "撥補零用金時應借記:現金短溢$10"], "answer": "A", "figure": null, "official": "借:水電瓦斯費$2,500、文具用品$600、郵電費$850、零用金$2,000;貸:銀行存款$5,940、現金短溢$10。", "explain": {"concept": "這題考定額零用金撥補,同時調高定額與現金短溢的處理。", "steps": ["先算已支用:$2,500 + $600 + $850 = $3,950。", "應有餘額 = 定額 $4,000 − 已支用 $3,950 = $50;實際手存 $60,多了 $10,是「現金溢」,記在貸方「現金短溢」$10。", "零用金定額由 $4,000 提高到 $6,000,要增加「零用金」$2,000。", "分錄:\n借:水電瓦斯費  2,500\n  借:文具用品  600\n  借:郵電費  850\n  借:零用金  2,000\n  貸:銀行存款  5,940\n  貸:現金短溢  10", "銀行存款 = 借方合計 $5,950 − 現金溢 $10 = $5,940,選 (A)。", "檢查其他:(B) 費損 $3,950 不是 $3,940;(C) 撥補後零用金餘額 $6,000;(D) 現金溢應「貸」記。"], "pitfalls": "手存比應有餘額多→現金溢(貸);少→現金短(借)。定額提高要另外加記零用金。", "distractors": {"B": "少算 $10 或把現金溢直接沖費用,但費損總額仍是 $3,950。", "C": "忘了提高定額到 $6,000,仍用原定額 $4,000。", "D": "把現金溢誤當成現金短,借貸方向弄反。"}}, "check": "python:3950、短溢=60-(4000-3950)=+10(溢),銀行存款=3950+2000-10=5940,與官方相符。", "verified": true, "note": ""}, {"id": "113-4-A-11", "exam": "113-4", "paper": "A", "q": 11, "unit": "十二、應收款項", "topic": "現金折扣與淨額法", "stem": "大方公司於 01 年 3 月 1 日賒銷商品一批$500,000 給忠泰公司,因為是老顧客故給予 9 折優惠價成交,現金折扣為 2/10,1/20,n/30。忠泰公司於 3 月 9 日交來現金$196,000、3 月 18 日交來現金$148,500,並於 3 月 30 日還清剩餘貨款。若大方公司按「淨有權收取的對價」入帳,則下列敘述何者正確?", "options": ["3 月 1 日應貸記:銷貨收入$450,000", "3 月 9 日應貸記:銷貨收入$4,000", "3 月 18 日應貸記:銷貨收入$1,500", "3 月 30 日應貸記:銷貨收入$1,000"], "answer": "C", "figure": null, "official": "3/1 銷貨$441,000;3/9 無銷貨收入;3/18 銷貨收入$1,500;3/30 銷貨收入$2,000。", "explain": {"concept": "這題考淨額法(淨有權收取對價):先扣最大折扣入帳,超過折扣期限才多認列銷貨收入。", "steps": ["先算成交價:$500,000 × 0.9 = $450,000(9 折是商業折扣,直接扣除)。淨額法以最高折扣(2%)入帳:$450,000 × 0.98 = $441,000。\n借:應收帳款  441,000\n  貸:銷貨收入  441,000", "3/9 在 10 天內,享 2% 折扣,付 $196,000:$196,000 就是 $200,000×98%,沖銷應收帳款 $196,000,沒有銷貨收入。", "3/18 在 11~20 天,只享 1% 折扣,付 $148,500:對應原價 $148,500 ÷ 99% = $150,000;原以 98% 入帳的應收帳款 = $150,000 × 0.98 = $147,000;多收 $148,500 − $147,000 = $1,500 貸記銷貨收入。\n借:現金  148,500\n  貸:應收帳款  147,000\n  貸:銷貨收入  1,500", "3/30 剩餘應收帳款 = $441,000 − $196,000 − $147,000 = $98,000;超過折扣期須付全額 = $98,000 ÷ 98% = $100,000,貸記銷貨收入 $2,000。", "所以只有 (C) 正確。"], "pitfalls": "淨額法:先按最大折扣入帳,折扣沒享到的部分才是之後多收的銷貨收入。", "distractors": {"A": "忘了先乘 0.98(只算 9 折),銷貨收入是 $441,000。", "B": "3/9 享滿折扣,沒有額外銷貨收入。", "D": "3/30 應多收 $2,000(不是 $1,000),可能把折扣率當成 1%。"}}, "check": "python:441000, 148500/.99*.98=147000, 剩餘98000, 98000/.98=100000,與官方相符。", "verified": true, "note": ""}, {"id": "113-4-A-12", "exam": "113-4", "paper": "A", "q": 12, "unit": "十二、應收款項", "topic": "應收票據貼現", "stem": "有關應收票據貼現之敘述,下列何者正確?", "options": ["「應收票據貼現負債」為資產之抵減項目", "公司持應收票據向銀行貼現,貼現日應貸記「應收票據」", "「應收票據貼現負債折價」已過期部分,應轉列為「利息收入」", "附息票據到期若發票人拒付,貼現人按票據到期值加拒絕證書費借記「催收款項」"], "answer": "D", "figure": null, "official": "(A)為負債;(B)貼現日貸記「應收票據貼現負債」;(C)已過期部分應轉列為「利息費用」。", "explain": {"concept": "這題考應收票據貼現(附追索權):貼現日、到期日的科目及拒付處理。", "steps": ["(A) 「應收票據貼現負債」是「負債」項目,不是資產抵減,錯。", "(B) 貼現後票據仍可能被追索,所以貼現日貸記「應收票據貼現負債」,不是直接貸記應收票據,錯。", "(C) 「應收票據貼現負債折價」是貼現息的遞延,已過期部分轉為「利息費用」,不是利息收入,錯。", "(D) 到期發票人拒付,貼現人須付銀行票據到期值及拒絕證書費,並對發票人求償,借記「催收款項」(金額為到期值加拒絕證書費),正確。"], "pitfalls": "貼現時是借「現金、利息費用或折價」,貸「應收票據貼現負債」;拒付時才轉為催收款項。", "distractors": {"A": "把「負債」誤當資產的減項。", "B": "忽略貼現有或有負債,直接除列應收票據。", "C": "貼現息是費用,不是收入。"}}, "check": "概念題,依官方詳解與應收票據貼現會計處理確認。", "verified": true, "note": ""}, {"id": "113-4-A-13", "exam": "113-4", "paper": "A", "q": 13, "unit": "十三、存貨", "topic": "存貨成本流動假設", "stem": "01 年因國際發生戰爭致使全球原物料短缺以及通貨膨脹,導致大方公司的進貨成本持續上升,若期末尚有商品未售出,則有關存貨成本公式(又稱成本流動假設)之敘述,01 年採用方法比較之敘述,下列哪幾項正確?\n①採用「先進先出法」之本期損益較「平均法」高\n②採用「先進先出法」之銷貨成本較「平均法」高\n③採用「先進先出法」之所得稅負擔較「平均法」高\n④採用「先進先出法」之期末存貨成本較「平均法」高", "options": ["僅②、④", "僅③、④", "僅①、②、③", "僅①、③、④"], "answer": "D", "figure": null, "official": "物價上漲時,先進先出法:期末存貨最高、銷貨成本最低、損益最高、所得稅最高。故①③④正確。", "explain": {"concept": "這題考物價上漲時,先進先出法(FIFO)與平均法對損益的影響。", "steps": ["物價上漲時,先進貨的成本較低、後進貨成本較高。", "先進先出法:先進的(低成本)先轉為銷貨成本,所以銷貨成本較低,②錯。", "銷貨成本低 → 毛利、本期損益較高,①正確。", "本期損益高 → 所得稅負擔較高,③正確。", "最新進貨(高成本)留在期末存貨,所以期末存貨成本較高,④正確。", "正確為①③④,選 (D)。"], "pitfalls": "物價上漲:FIFO 銷貨成本低、存貨高、損益高、稅高;平均法介於 FIFO 與 LIFO 之間。", "distractors": {"A": "以為 FIFO 銷貨成本較高(把先進先出方向想反),並漏了①③。", "B": "漏掉①,可能只記得稅與存貨。", "C": "誤以為②正確,混淆了 FIFO 銷貨成本高低。"}}, "check": "概念題,依官方詳解與存貨成本流動假設常識確認。", "verified": true, "note": ""}, {"id": "113-4-A-14", "exam": "113-4", "paper": "A", "q": 14, "unit": "十三、存貨", "topic": "存貨成本與淨變現價值孰低", "stem": "大華公司成立於 01 年初,存貨採定期盤存制,期末以成本與淨變現價值孰低法進行衡量,02、03 年期末存貨資料如下:\n\n| 年底 | 成本 | 淨變現價值 |\n|---|---|---|\n| 02 年底 | $48,000 | $45,000 |\n| 03 年底 | $60,000 | $58,000 |\n\n已知 01 年調整後「備抵存貨跌價」帳戶餘額為$2,000,03 年期末存貨衡量前「銷貨成本」為$750,000,則期末存貨衡量後,下列敘述何者正確?", "options": ["02 年底資產負債表中,存貨金額為$48,000", "03 年度綜合損益表中銷貨成本金額為$749,000", "02 年期末存貨衡量分錄,應貸記:備抵存貨跌價$3,000", "03 年期末存貨衡量分錄,應借記:備抵存貨跌價$3,000"], "answer": "B", "figure": null, "official": "02 年底補提$1,000;03 年底備抵由$3,000 降為$2,000,迴轉$1,000,銷貨成本$750,000−$1,000=$749,000。", "explain": {"concept": "這題考存貨跌價損失與迴轉利益:備抵存貨跌價要調整到「成本−淨變現價值」。", "steps": ["02 年底:成本 $48,000 > 淨變現價值 $45,000,應有備抵 = $3,000;原餘額 $2,000,補提 $1,000:\n借:銷貨成本  1,000\n  貸:備抵存貨跌價  1,000\n資產負債表存貨以 $45,000 列示。", "03 年底:成本 $60,000 > 淨變現價值 $58,000,應有備抵 $2,000;原餘額 $3,000,多了 $1,000,應迴轉:\n借:備抵存貨跌價  1,000\n  貸:銷貨成本  1,000", "03 年銷貨成本 = $750,000 − $1,000 = $749,000,選 (B)。", "其他選項:(A) 應為 $45,000;(C) 02 年只貸記 $1,000;(D) 03 年只借記 $1,000。"], "pitfalls": "備抵是「調整到應有餘額」,看的是「差額」,不是整個金額。", "distractors": {"A": "忘了孰低法:應以淨變現價值 $45,000 列示。", "C": "把備抵應有餘額 $3,000 當成要補提的金額,忽略原有 $2,000。", "D": "把 03 年應有餘額與 $3,000 混淆,實際只迴轉 $1,000。"}}, "check": "python:749000;備抵 3000-2000=1000(02年補提)、3000-2000=1000(03年迴轉),與官方相符。", "verified": true, "note": ""}, {"id": "113-4-A-15", "exam": "113-4", "paper": "A", "q": 15, "unit": "十四、證券投資", "topic": "透過損益按公允價值衡量之金融資產", "stem": "大明公司若將購入股票投資分類為「透過損益按公允價值衡量之金融資產」,則下列敘述何者正確?", "options": ["對被投資公司有重大影響力", "收到股票股利,分錄應貸記「股利收入」", "「透過損益按公允價值衡量之金融資產損失」在財務報表中應列為營業費用", "期末資產負債表中「透過損益按公允價值衡量之金融資產」金額為期末投資股票之公允價值"], "answer": "D", "figure": null, "official": "(A)無重大影響力;(B)股票股利不作分錄,僅註明股數;(C)應列為營業外支出。", "explain": {"concept": "這題考透過損益按公允價值衡量之金融資產(FVTPL)的基本特性與表達。", "steps": ["(D) FVTPL 期末按公允價值衡量並列示,正確。", "(A) 有重大影響力是權益法的投資,FVTPL 屬於無重大影響力,錯。", "(B) 收到股票股利只增加股數,不作分錄(重新計算每股帳面金額),不能貸記股利收入,錯。", "(C) 金融資產評價損失屬於營業外支出(其他利益及損失),不是營業費用,錯。"], "pitfalls": "股票股利不是收入,只在備忘錄註明股數增加。", "distractors": {"A": "把重大影響力(權益法)與 FVTPL 混淆。", "B": "誤把股票股利當成收益入帳。", "C": "誤把評價損失歸為營業費用。"}}, "check": "概念題,依官方詳解與 IFRS 9 常識確認。", "verified": true, "note": ""}, {"id": "113-4-A-16", "exam": "113-4", "paper": "A", "q": 16, "unit": "十四、證券投資", "topic": "透過損益按公允價值衡量之金融資產", "stem": "大方公司於 01 年 3 月 1 日以每股$45 購入 2,000 股大德公司普通股股票,手續費$1,000,作為透過損益按公允價值衡量之金融資產,7 月 1 日收到 10%股票股利及每股現金股利$2,01 年 12 月 31 日大德公司普通股每股公允價值為$44,則有關該投資的敘述,下列何者正確?(依金融監督管理委員會認可之國際財務報導準則第 9 號「金融工具」之會計處理)", "options": ["01 年 7 月 1 日應貸記:股利收入$4,400", "01 年度對大德公司之股票投資全部相關交易應認列之淨損益為利益$9,800", "01 年 3 月 1 日投資分錄應借記:強制透過損益按公允價值衡量之金融資產$91,000", "01 年 12 月 31 日期末衡量應借記:透過損益按公允價值衡量之金融資產損失$2,000"], "answer": "B", "figure": null, "official": "手續費$1,000 費用+股利收入$4,000+衡量利益$6,800=利益$9,800。", "explain": {"concept": "這題考 FVTPL 的取得、股利與期末衡量:手續費記費用、股票股利不作分錄。", "steps": ["3/1 購入:2,000 股 × $45 = $90,000(手續費 $1,000 不計入成本,直接當費用)。\n借:強制透過損益按公允價值衡量之金融資產  90,000\n  借:手續費  1,000\n  貸:現金  91,000", "7/1:現金股利 = 2,000 股 × $2 = $4,000,貸記股利收入 $4,000;10% 股票股利不作分錄,股數變為 2,000 × 1.1 = 2,200 股。", "12/31:公允價值 = 2,200 股 × $44 = $96,800;帳面金額 $90,000,評價利益 = $96,800 − $90,000 = $6,800。", "全年淨損益 = −手續費 $1,000 + 股利收入 $4,000 + 評價利益 $6,800 = 利益 $9,800,選 (B)。", "其他:(A) 股利收入應為 $4,000;(C) 投資成本是 $90,000;(D) 應是利益 $6,800,不是損失。"], "pitfalls": "FVTPL 取得時的手續費當作費用;股票股利使股數增加,但單位成本下降,總成本不變,期末評價用「新股數」計算。", "distractors": {"A": "把 10% 股票股利也算進現金股利(2,200 股 × $2 = $4,400)。", "C": "把手續費 $1,000 加進投資成本。", "D": "忘了股票股利使股數增為 2,200 股,用 2,000 股 × ($45−$44) 算成損失。"}}, "check": "python:-1000+4000+(2200*44-90000)=9800,與官方相符。", "verified": true, "note": ""}, {"id": "113-4-A-17", "exam": "113-4", "paper": "A", "q": 17, "unit": "十五、長期營業用資產", "topic": "折舊方法變更(估計變動)", "stem": "大德公司於 01 年初取得機器設備$800,000,預估耐用年限為 8 年,殘值為$80,000,採用年數合計法提列折舊,公司於 03 年底調整前評估,發現該機器可再使用 9 年,估計殘值改變為$50,000,同時決定變更折舊方法為直線法,則公司 04 年度應提列多少折舊費用?", "options": ["$37,000", "$45,000", "$50,000", "$57,000"], "answer": "B", "figure": null, "official": "03/1/1 帳面金額=$800,000−$300,000=$500,000;04 年折舊=($500,000−$50,000)÷(9+1)=$45,000。", "explain": {"concept": "這題考折舊估計變動:未來期間以「帳面金額 − 新殘值」除以「剩餘年限」。", "steps": ["年數合計法的年數總和 = 8+7+6+5+4+3+2+1 = 36。", "01、02 兩年累計折舊 = ($800,000 − $80,000) × (8+7) ÷ 36 = $720,000 × 15/36 = $300,000。", "03/1/1 帳面金額 = $800,000 − $300,000 = $500,000。", "03 年底「調整前」才發現可再使用 9 年,代表 03 年初起的剩餘壽命是 9 + 1(03 年)= 10 年,殘值改為 $50,000,改用直線法。", "每年折舊 = ($500,000 − $50,000) ÷ 10 = $45,000。03 年與 04 年相同,所以 04 年折舊 $45,000,選 (B)。"], "pitfalls": "發現估計改變是在 03 年底「調整前」,所以 03 年的折舊也要用新方法,剩餘年限要加上 03 年共 10 年。", "distractors": {}}, "check": "python:(800000-80000)*15/36=300000;(500000-50000)/10=45000,與官方相符。", "verified": true, "note": "distractors 不確定錯誤來源,故省略。"}, {"id": "113-4-A-18", "exam": "113-4", "paper": "A", "q": 18, "unit": "十五、長期營業用資產", "topic": "無形資產(研究發展)", "stem": "流行服飾公司在 01 年為降低人工成本,提高管理及服務顧客效能,開始自行研發可協助顧客選配穿搭之 AI 軟體,並擬於技術可行後申請智慧財產權專利。請根據下列研究發展期間公司所發生之相關支出,計算此無形資產應認列之成本為何?\n①01 年度屬於研究階段,研發支出共計$600,000\n②02 年度屬於發展階段,研發支出共計$900,000,其中 70%符合所有資本化條件\n③03 年初研發成功,並申請專利,支付登記規費共計$3,000\n④為推廣該技術所進行的宣傳支出,共計$15,000", "options": ["$3,000", "$630,000", "$633,000", "$648,000"], "answer": "C", "figure": null, "official": "$900,000×70%+$3,000=$633,000。", "explain": {"concept": "這題考自行發展無形資產:研究階段費用化、發展階段符合條件才資本化。", "steps": ["①研究階段支出一律當費用,不列入無形資產成本。", "②發展階段只有符合資本化條件的才能列入成本:$900,000 × 70% = $630,000。", "③取得專利的登記規費 $3,000 屬於使資產達可使用狀態的必要支出,列入成本。", "④宣傳(廣告)支出是費用,不列成本。", "無形資產成本 = $630,000 + $3,000 = $633,000,選 (C)。"], "pitfalls": "研究→費用;發展符合條件→資產;廣告宣傳→費用。", "distractors": {"A": "只算了專利登記費,忽略資本化的發展支出。", "B": "只算 $630,000,漏了登記規費 $3,000。", "D": "把宣傳費 $15,000 也列入成本。"}}, "check": "python:900000*.7+3000=633000,與官方相符。", "verified": true, "note": ""}, {"id": "113-4-A-19", "exam": "113-4", "paper": "A", "q": 19, "unit": "十七、權益", "topic": "累積全部參加特別股股利", "stem": "大方公司 02 年初有下列資訊:每股面值$10,流通在外之普通股 500,000 股;6%累積、全部參加、每股面值$10 之特別股 200,000 股,且尚積欠特別股一年股利。02 年度因景氣看好,盈餘倍增,分配現金股利時,特別股股東共收到的股利總金額為$320,000,則 02 年度普通股可收到的股利總金額為何?", "options": ["$500,000", "$800,000", "$1,000,000", "$1,100,000"], "answer": "A", "figure": null, "official": "積欠股利$120,000;平均股利率=($320,000−$120,000)÷$2,000,000=10%;普通股股利=$5,000,000×10%=$500,000。", "explain": {"concept": "這題考累積、全部參加特別股的股利分配:欠股利 → 當年基本股利 → 與普通股依同一股利率參加。", "steps": ["特別股股本 = 200,000 股 × $10 = $2,000,000;每年基本股利 = $2,000,000 × 6% = $120,000。", "尚積欠一年股利 $120,000,先全數補發給特別股。", "特別股共收到 $320,000,扣除積欠 $120,000,02 年度所得股利 = $200,000。", "全部參加:特別股與普通股用同一個股利率分配。特別股股利率 = $200,000 ÷ $2,000,000 = 10%。", "普通股股本 = 500,000 股 × $10 = $5,000,000;普通股股利 = $5,000,000 × 10% = $500,000,選 (A)。"], "pitfalls": "全部參加:先分基本股利(含欠),再讓普通股拿到相同股利率,最後兩者按同一率參加。", "distractors": {}}, "check": "python:(320000-120000)/2000000=0.10;5000000*0.10=500000,與官方相符。", "verified": true, "note": "distractors 不確定錯誤來源,故省略。"}, {"id": "113-4-A-20", "exam": "113-4", "paper": "A", "q": 20, "unit": "十七、權益", "topic": "權益內容", "stem": "有關權益內容,下列敘述何者錯誤?", "options": ["應收股款、庫藏股票均列為權益之減項", "法定盈餘公積、未分配盈餘均屬於保留盈餘項目", "受領股東贈與、特別盈餘公積均屬於資本公積項目", "已認普通股股本、待分配股票股利均屬於股本項目"], "answer": "C", "figure": null, "official": "「受領股東贈與」屬於資本公積項目,「特別盈餘公積」屬保留盈餘項目。", "explain": {"concept": "這題考權益各項目的分類:股本、資本公積、保留盈餘、權益減項。", "steps": ["(A) 應收股款(認股未收)、庫藏股票都是權益的減項,正確。", "(B) 法定盈餘公積、特別盈餘公積、未分配盈餘都屬保留盈餘,正確。", "(C) 受領股東贈與屬資本公積;但特別盈餘公積屬「保留盈餘」,不是資本公積,這句錯誤。", "(D) 已認普通股股本與待分配股票股利都屬「股本」,正確。", "題目問「錯誤」,選 (C)。"], "pitfalls": "盈餘公積(法定、特別)是保留盈餘;資本公積來源是股本溢價、受贈等。", "distractors": {"A": "此敘述正確,不是答案。", "B": "此敘述正確,不是答案。", "D": "此敘述正確,不是答案。"}}, "check": "概念題,依官方詳解與權益分類常識確認。", "verified": true, "note": ""}, {"id": "113-4-A-21", "exam": "113-4", "paper": "A", "q": 21, "unit": "十七、權益", "topic": "加權平均流通在外股數", "stem": "大方公司 01 年初有每股面額$10 之流通在外普通股若干股,6%累積非參加每股面額$10 之特別股 20,000 股,當年度普通股相關交易如下:4 月 1 日發放 10%股票股利及每股$1 之現金股利,6 月 1 日增資發行普通股 60,000 股,7 月 1 日股票分割 1 股分為 2 股,9 月 1 日買回本公司流通在外普通股 30,000 股。本公司 01 年度稅後淨利$612,000,01 年底普通股每股公允價值為$20,01 年度每股盈餘為$1.2,則 01 年 1 月 1 日帳列流通在外普通股應為多少股?", "options": ["200,000 股", "220,000 股", "440,000 股", "500,000 股"], "answer": "A", "figure": null, "official": "加權平均流通在外股數=($612,000−$200,000×6%)÷$1.2=500,000 股,設 1/1 為 X 解方程式得 X=200,000 股。", "explain": {"concept": "這題考每股盈餘:先由 EPS 反推加權平均股數,再依股票股利、股票分割追溯調整,倒推期初股數。", "steps": ["特別股股利 = 20,000 股 × $10 × 6% = $12,000(官方詳解算式寫 $200,000×6%,結果同為 $12,000)。", "加權平均股數 = (稅後淨利 $612,000 − 特別股股利 $12,000) ÷ EPS $1.2 = 500,000 股。", "設 1/1 流通在外 X 股。股票股利、股票分割要「追溯」到年初,所以期初股數 × 1.1(股票股利)× 2(分割)= 2.2X。", "6/1 增資 60,000 股,期間 7 個月(6/1~12/31),並因 7/1 分割要 ×2:60,000 × 7/12 × 2 = 70,000。", "9/1 買回 30,000 股(已是分割後股數),期間 4 個月,要扣掉:30,000 × 4/12 = 10,000。", "列式:2.2X + 70,000 − 10,000 = 500,000,2.2X = 440,000,X = 200,000 股,選 (A)。"], "pitfalls": "股票股利與股票分割要追溯調整全年;現金股利、公允價值與股數無關(干擾條件)。", "distractors": {"C": "把 2.2X 的結果 440,000 當成 X(忘了除以 2.2)。", "D": "把加權平均股數 500,000 直接當成期初股數。"}}, "check": "python:(612000-12000)/1.2=500000;(500000-70000+10000)/2.2=200000,與官方相符。", "verified": true, "note": "官方詳解特別股股利算式寫 $200,000×6%,實際特別股面額總額為 20,000×$10=$200,000,結果 $12,000 正確。"}, {"id": "113-4-A-22", "exam": "113-4", "paper": "A", "q": 22, "unit": "十七、權益", "topic": "盈餘分配與未分配盈餘", "stem": "大德公司 01 年期初累積虧損$100,000,01 年度已扣除員工酬勞及董監事酬勞之稅前淨利為$800,000,所得稅稅率 20%。01 年度依公司章程規定估列現金分派員工酬勞為$60,000、董監事酬勞為$40,000。若 02 年股東會決議 01 年度盈餘分配案,同意上述員工和董監事酬勞金額,並決議盈餘分配如下:①彌補以前年度虧損、②依法提撥法定盈餘公積、③配發現金股利$150,000,則大德公司 01 年期末未分配盈餘為多少?", "options": ["$254,000", "$264,000", "$326,000", "$336,000"], "answer": "D", "figure": null, "official": "稅後淨利$640,000;法定盈餘公積$54,000;期末未分配盈餘=−$100,000+$640,000−$54,000−$150,000=$336,000。", "explain": {"concept": "這題考稅後淨利、彌補虧損後提列 10%法定盈餘公積,以及期末未分配盈餘計算。", "steps": ["題目已說明「稅前淨利 $800,000 是已扣除員工酬勞及董監事酬勞」,所以不用再扣 $60,000、$40,000。", "稅後淨利 = $800,000 × (1 − 20%) = $640,000。", "法定盈餘公積 = (稅後淨利 − 彌補虧損) × 10% = ($640,000 − $100,000) × 10% = $54,000。", "期末未分配盈餘 = 期初 −$100,000 + 稅後淨利 $640,000 − 法定盈餘公積 $54,000 − 現金股利 $150,000 = $336,000,選 (D)。"], "pitfalls": "提列法定盈餘公積前要先彌補虧損,基數是「稅後淨利 − 彌補虧損」,不是只看稅後淨利。", "distractors": {}}, "check": "python:640000;54000;-100000+640000-54000-150000=336000,與官方相符。", "verified": true, "note": "distractors 不確定錯誤來源,故省略。"}, {"id": "113-4-A-23", "exam": "113-4", "paper": "A", "q": 23, "unit": "十五、長期營業用資產", "topic": "生物資產(IAS 41)", "stem": "▲閱讀下文,回答第 23-24 題\n大德原任職於科技業,因感父母年邁,故回鄉協助經營農場。該農產原種植有葡萄樹、高麗菜、玉米等蔬果,大德擬增加經營項目,故於 01 年新增蛋雞、肉雞之飼養。大德回鄉後農場相關會計帳務即依據國際會計準則第 41 號將生物資產採公允價值模式處理。01 年新增蛋雞、肉雞飼養之相關支出如下:\n01 年 1 月 3 日購入小母雞 200 隻,準備飼養成熟後生雞蛋,每隻交易價格$150,另支付運送至農場運費$2,000 及其他交易成本$1,000。若將這批小母雞立即出售,估計需支付運送至市場運費$1,500 及出售成本$1,000。\n01 年 10 月 1 日再購入小母雞 300 隻,準備飼養成熟後作為肉雞宰殺後出售,每隻交易價格$100,另支付運送至農場運費$3,000 及其他交易成本$1,000。若將這批小母雞立即出售,估計需支付運送至市場運費$2,000 及出售成本$1,000。01 年度投入飼料成本$30,000、工資費用$20,000。\n\n依據國際會計準則,下列敘述有哪幾項正確?\n①01 年 1 月 3 日應借記:生產性生物資產$27,500\n②01 年 10 月 1 日應借記:原始認列生物資產及農產品之損失$3,000\n③蛋雞所生產未售出之「雞蛋」,期末應以「公允價值模式」衡量\n④所採收之「葡萄」,收成時應以「公允價值模式」衡量\n⑤該農場養殖之蛋雞、肉雞,及種植之葡萄樹、高麗菜、玉米均分類為「生物資產」", "options": ["僅①、④", "僅①、②、③", "僅②、③、④、⑤", "①、②、③、④、⑤"], "answer": "A", "figure": null, "official": "①正確(200×$150−$1,500−$1,000=$27,500);②應為$7,000;③雞蛋為農業產品屬存貨,以成本與淨變現價值孰低衡量;⑤葡萄樹為不動產、廠房及設備。故僅①④。", "explain": {"concept": "這題考 IAS 41 生物資產:原始認列以「公允價值減出售成本」衡量,農業產品收成時亦以公允價值減出售成本衡量,之後屬存貨。", "steps": ["①1/3 購入小母雞:原始認列按公允價值減出售成本 = 200 × $150 − $1,500 − $1,000 = $27,500,借記「生產性生物資產」$27,500,正確。", "②10/1 購入肉雞:公允價值減出售成本 = 300 × $100 − $2,000 − $1,000 = $27,000;實際付出 = $30,000 + $3,000 + $1,000 = $34,000,原始認列損失 = $34,000 − $27,000 = $7,000(即 $3,000 + $1,000 + $2,000 + $1,000),不是 $3,000,錯誤。", "③雞蛋是蛋雞所生產的「農產品」,收成後依存貨處理,期末以「成本與淨變現價值孰低」衡量,不是公允價值模式,錯誤。", "④葡萄是葡萄樹(生產性植物)所採收的農產品,收成時以公允價值減出售成本衡量,正確。", "⑤蛋雞、肉雞、高麗菜、玉米是生物資產,但葡萄樹屬「生產性植物」,應分類為「不動產、廠房及設備」,不是生物資產,錯誤。", "正確為①④,選 (A)。"], "pitfalls": "生物資產→公允價值減出售成本;農產品收成後→存貨;生產性植物(如葡萄樹)→不動產、廠房及設備。", "distractors": {"B": "誤把②的損失當成 $3,000,也誤認雞蛋用公允價值衡量。", "C": "漏掉①並誤判②③⑤。", "D": "全選,沒有分辨農產品與生產性植物。"}}, "check": "python:200*150-1500-1000=27500;損失3000+1000+2000+1000=7000,與官方相符。", "verified": true, "note": "單元歸類無完全貼切者(IAS 41 農業),暫歸十五。"}, {"id": "113-4-A-24", "exam": "113-4", "paper": "A", "q": 24, "unit": "十五、長期營業用資產", "topic": "生物資產衡量(IAS 41)", "stem": "假設至 01 年期末雞隻均未折損,期末估計若將蛋雞及肉雞出售,每隻蛋雞價格為$200,肉雞價格為$150,估計共需支付運送至市場運費$3,000 及出售成本$1,500。則 01 年底資產負債表中「生物資產」金額為何?", "options": ["$72,500", "$80,500", "$89,500", "$117,000"], "answer": "B", "figure": null, "official": "200隻×$200+300隻×$150−$3,000−$1,500=$80,500。", "explain": {"concept": "這題考生物資產期末以「公允價值減出售成本」衡量。", "steps": ["蛋雞 200 隻 × $200 = $40,000。", "肉雞 300 隻 × $150 = $45,000。", "合計公允價值 = $40,000 + $45,000 = $85,000。", "扣除出售成本:運費 $3,000 + 出售成本 $1,500 = $4,500。", "生物資產金額 = $85,000 − $4,500 = $80,500,選 (B)。"], "pitfalls": "生物資產期末要「減出售成本」;飼料、工資是費用,不加入生物資產。", "distractors": {}}, "check": "python:200*200+300*150-3000-1500=80500,與官方相符。", "verified": true, "note": "distractors 不確定錯誤來源,故省略。單元歸類同第 23 題。"}, {"id": "113-5-A-01", "exam": "113-5", "paper": "A", "q": 1, "unit": "一、會計基本概念", "topic": "企業個體與會計處理", "stem": "「小明獨資$1,000,000 設立公仔專賣商店,經營客製化公仔模型的製作與銷售,請來最信任的爸爸負責管理帳務與現金收支,以節省人事成本。因業務量少,因此委託記帳士代為記帳與報稅。小明的爸爸常常將店裡收到的貨款拿回家裡存放,也會將店裡的水電單據順手用家裡的錢支付。小明的爸爸對於各項收支單據並未妥善保管,除了可兌獎的統一發票,其餘單據散落未整理。公仔專賣店成立一個月後,小明想要知道一個月營業額多少?店裡剩餘多少錢?賺錢或賠錢?每天在店裡忙進忙出的爸爸卻一問三不知……」,上述公仔專賣商店其帳務處理與現金收支,下列哪幾項處理不適當?\n①交由爸爸管錢又管帳  ②企業與個人家庭資金混用\n③未適當取得及保管會計憑證  ④委託記帳士記帳及報稅", "options": ["①④", "①②③", "①③④", "②③④"], "answer": "B", "figure": null, "official": "①管錢又管帳違反內部牽制;②公私資金混用違反會計個體(企業個體)假設;③未妥善取得保管憑證不當;④委託記帳士是合法做法。", "explain": {"concept": "考企業個體假設與內部控制(職務分工)的基本觀念,並判斷哪些做法不適當。", "steps": ["先看題目要選『不適當』的項目。", "①爸爸『管錢又管帳』:出納與記帳由同一人負責,沒有互相牽制,違反內部控制的職務分離,不適當。", "②把店裡貨款拿回家存放、用家裡的錢付店裡水電:企業資金和個人家庭資金混在一起,違反『企業個體(會計個體)假設』,不適當。", "③單據散落未整理、沒有妥善取得保管會計憑證,帳務就沒有依據,不適當。", "④商店業務量少,委託記帳士(合法的記帳及報稅代理業務)處理帳務,是合理且合法的做法,所以適當,不選。", "不適當的是①②③,答案選(B)。"], "pitfalls": "容易看到『委託別人記帳』就以為不好;其實記帳士是合法的專業代理人。", "distractors": {"A": "把④誤當成不適當,而且漏掉②。", "C": "同樣誤選④,漏掉②。", "D": "漏掉①(管錢又管帳),而且誤選④。"}}, "check": "逐項判斷:①✗適當 ②✗ ③✗ ④✓適當;不適當=①②③,與官方答案B相符。", "verified": true, "note": ""}, {"id": "113-5-A-02", "exam": "113-5", "paper": "A", "q": 2, "unit": "十、加值型營業稅會計實務", "topic": "營業稅登記與統一發票", "stem": "臺灣新創競爭力十足,很多年輕人喜歡自己創業。下列4個年輕人創業時的營業稅處理,哪幾人違反加值型及非加值型營業稅法的規定?\n①甲君在臉書社群網站建立粉絲團銷售個性文具,平均每月銷售額10萬元,未辦理稅籍登記,未繳納營業稅\n②乙君透過Yahoo、Line及蝦皮等網站平台銷售貨物,平均每月銷售額30萬元,沒有在實體店面銷售,因此並未開立統一發票\n③丙君自國外進口大量韓系衣服,在自己經營的實體店面銷售給非營業人的消費者,開立二聯式收銀機統一發票,稅額內含於統一發票之中,但申報統一發票銷售額\n④丁君設立獨資商店,本年3月購買冷氣機,放置於丁君家裡供家人使用,丁君將該統一發票作為商店的支出憑證,並於當期扣抵銷項稅額", "options": ["甲、乙", "乙、丁", "甲、乙、丁", "甲、丙、丁"], "answer": "C", "figure": null, "official": "①應辦理稅籍登記,應繳納營業稅;②網站平台銷售貨物平均每月銷售額30萬元已超過20萬元,應開立統一發票;④冷氣機放置於家裡供家人使用,不得作為商店支出憑證,不得扣抵銷項稅額。", "explain": {"concept": "考營業稅法:什麼情形要辦稅籍登記、開統一發票、哪些進項稅額不能扣抵。", "steps": ["先逐項判斷有沒有違法。", "①甲君有銷售行為就應辦理稅籍登記並繳納營業稅(官方認定違反),所以①違規。", "②乙君用網路平台銷售,每月銷售額30萬元,已超過小規模(每月20萬元)的門檻,應開立統一發票;未開立就是違規,②違規。", "③丙君開二聯式發票給非營業人消費者,稅額內含,且依規定申報銷售額,做法符合規定,③沒問題。", "④冷氣機放在家裡給家人用,不是營業用,不能當作商店的支出憑證去扣抵銷項稅額,④違規。", "違規的是甲、乙、丁,選(C)。"], "pitfalls": "容易以為網路銷售不用開發票;也容易忽略『非營業用的進項稅額不得扣抵』。", "distractors": {"A": "漏掉④,以為進項發票只要有拿到就能扣抵。", "B": "漏掉①,以為小額銷售不必登記。", "D": "誤把③(合規)當成違規,漏掉②。"}}, "check": "①②④違規、③合規,與官方答案C相符。(法規題,依官方詳解確認)", "verified": true, "note": ""}, {"id": "113-5-A-03", "exam": "113-5", "paper": "A", "q": 3, "unit": "十二、應收款項", "topic": "應收票據貼現", "stem": "永達公司因為美國港口罷工,導致銷售到美國的商品運送延遲,運輸成本提高,引發公司的資金周轉緊繃,庫存現金及營運資金不足,總經理心急如焚,召集財務會計人員開會,研商如何能快速取得資金。會計小聰向總經理提出一個短期融資的救急方法,就是將本日因銷貨取得的3個月後到期的一張不附息應收票據向銀行辦理貼現,這項方案獲得總經理的同意,並於會議當天執行,貼現的應收票據面額$1,000,000,銀行貼現率年息4%,當天順利獲得現金。有關永達公司「貼現日」的交易,下列敘述何者正確?(融資資金成本率請計算至百分比小數點後第2位四捨五入)", "options": ["貼現日交易導致流動負債增加$990,000", "貼現日應收票據的帳面金額減少$1,000,000", "貼現日認列利息費用$10,000", "此交易融資資金成本率為4.00%"], "answer": "A", "figure": null, "official": "貼現日取得現金$990,000,認列『應收票據貼現負債』(流動負債)增加$990,000;應收票據帳面金額不變;貼現折價$10,000是『應收票據貼現負債折價』,不是利息費用;融資資金成本率=4.04%。", "explain": {"concept": "新制(IFRS)下附追索權的應收票據貼現視為『以票據擔保的借款』,票據仍留在帳上,另認列負債。", "steps": ["算貼現息:$1,000,000×4%×3/12=$10,000。", "貼現所得現金=$1,000,000-$10,000=$990,000。", "分錄:借:現金 990,000、應收票據貼現負債折價 10,000;貸:應收票據貼現負債 1,000,000。所以流動負債(淨額)增加$990,000,(A)正確。", "(B)錯:票據仍在帳上,帳面金額沒有減少。", "(C)錯:$10,000先記在『應收票據貼現負債折價』,之後隨時間才轉為利息費用,貼現日不認列。", "(D)錯:實際借到$990,000,3個月付$10,000利息,成本率=$10,000÷$990,000×12/3=4.04%,不是4.00%。"], "pitfalls": "把『貼現率』當成『融資成本率』;兩者分母不同(貼現率以到期值為基礎、成本率以實際借到的金額為基礎)。", "distractors": {"B": "以為貼現就是把票據賣掉而除列,但新制是借款觀點,票據不除列。", "C": "把折價直接當成利息費用,忽略它要隨時間攤銷。", "D": "直接拿貼現率4%當成本率,沒有用實得金額$990,000當分母。"}}, "check": "python:1,000,000-1,000,000×4%×3/12=990,000;10,000/990,000×4=4.04%。與官方A相符。", "verified": true, "note": ""}, {"id": "113-5-A-04", "exam": "113-5", "paper": "A", "q": 4, "unit": "十六、負債", "topic": "複利現值與年金現值", "stem": "小美北漂後在外租房,認真工作並省吃儉用,利用手機每日記帳,嚴格管控支出,最大的希望就是能夠成為有殼一族,擁有自己的小套房。多年來存下的積蓄仍不夠繳納購買小套房的頭期款,於是向土地銀行借款,在借款合約中載明10年後到期一次還款$2,000,000,借款期間不必另外支付任何款項。若土地銀行借款年利率為4%,現值表如表(一),則小美的借款,現在能向土地銀行借到多少金額?\n\n表(一)\n\n| n \\ i | 4% | 8% |\n|---|---|---|\n| 5 | 0.822 | 0.681 |\n| 10 | 0.676 | 0.463 |\n\n(上表為『n期利率為i之$1的複利現值』)\n\n| n \\ i | 4% | 8% |\n|---|---|---|\n| 5 | 4.452 | 3.993 |\n| 10 | 8.111 | 6.710 |\n\n(上表為『n期利率為i每期$1的年金現值』)", "options": ["$463,000", "$676,000", "$926,000", "$1,352,000"], "answer": "D", "figure": null, "official": "10年後一次還$2,000,000,屬單一金額,用4%、10期的複利現值0.676:$2,000,000×0.676=$1,352,000。", "explain": {"concept": "期間內不用付利息、只在到期一次還本,屬於『一次給付』,要用複利現值(不是年金現值)。", "steps": ["先判斷現金流量型態:10年後一次還$2,000,000,中間沒有其他付款,所以是單一金額,用『複利現值表』。", "查表:n=10、i=4%,複利現值係數=0.676。", "現值=$2,000,000×0.676=$1,352,000,所以現在能借到$1,352,000,選(D)。"], "pitfalls": "看到表有兩張就選錯:年金現值表用於『每期固定金額』的付款,這題中間沒付款。", "distractors": {"A": "用8%、10期的0.463去乘$1,000,000得$463,000之類,利率或金額用錯。", "B": "只乘到$1,000,000(0.676×$1,000,000),少乘了2倍。", "C": "用了8%的複利現值0.463(2,000,000×0.463=926,000),利率看錯。"}}, "check": "python:2,000,000×0.676=1,352,000,與官方D相符。", "verified": true, "note": ""}, {"id": "113-5-A-05", "exam": "113-5", "paper": "A", "q": 5, "unit": "十七、權益", "topic": "員工酬勞與股利", "stem": "大海一早醒來被錢砸醒,他所處的幸福企業甲公司,將員工酬勞(員工分紅)轉入員工的存款帳戶了。但在乙公司上班的大正,卻高興不起來,大正任職的公司處於創業初期,公司還在燒錢,營運至今3年以來連續虧損,都沒有發放員工酬勞。小雪是丙公司的股東,不必辛苦上班,因為購買丙公司股票,最近就開開心心拿到一筆現金股利。以下是大海、大正和小雪三位好朋友的對話,何者正確?\n大海說:公司有賺錢,我領的員工酬勞是根據公司章程訂定當年度獲利狀況之比率,依稅後淨利扣除累積虧損後所分派\n大正說:公司的累積虧損尚未彌補,無法分派員工酬勞,所以我和公司得再努力再等等\n小雪說:我領到的現金股利,屬於公司的營業費用,公司有盈餘時可能給予現金或股票股利", "options": ["大海", "大正", "大正、小雪", "大海、大正、小雪"], "answer": "B", "figure": null, "official": "大海錯:員工酬勞是根據『稅前』淨利提撥,屬提供勞務當年度之營業費用,並不是盈餘分配;小雪錯:現金股利不屬於營業費用,而是盈餘之分配。", "explain": {"concept": "員工酬勞是費用(稅前淨利提撥),股利是盈餘分配(不是費用)。", "steps": ["員工酬勞:依公司法,公司章程要訂明『當年度獲利狀況』(稅前利益,扣除員工酬勞前)的一定比率;但若有累積虧損,應先彌補虧損。它是勞務成本,記為營業費用。", "大海說『依稅後淨利』提撥,錯,應是稅前。", "大正說有累積虧損尚未彌補,無法分派員工酬勞,符合官方認定,正確。", "小雪說現金股利是營業費用,錯。股利是把盈餘分配給股東,不是費用,會減少保留盈餘。", "只有大正正確,選(B)。"], "pitfalls": "容易混淆員工酬勞(費用)與股利(盈餘分配),也容易忽略『前/後』稅的差別。", "distractors": {"A": "只看大海的說法『依比率分派』覺得合理,忽略官方指出是依稅前淨利。", "C": "把小雪的現金股利誤當成營業費用。", "D": "三人都選,漏判大海與小雪的錯誤。"}}, "check": "概念題:依官方詳解與公司法員工酬勞規定(稅前利益、費用化)確認,答案B。", "verified": true, "note": ""}, {"id": "113-5-A-06", "exam": "113-5", "paper": "A", "q": 6, "unit": "二、會計循環及會計帳簿", "topic": "會計帳簿與會計程序", "stem": "有關會計帳簿及會計程序,下列何者錯誤?", "options": ["只要日記簿記載正確詳實,得免設總分類帳", "餘額式試算表的表首日期是表達交易資料的截止日期", "會計帳簿及財務報表除永久保存或未結會計事項外,應至少保存10年", "依照我國商業會計法,會計基礎採用權責發生制,在平時採用現金收付者,決算時應照權責發生制予以調整"], "answer": "A", "figure": null, "official": "(A)不可以免設總分類帳(總分類帳是必備主要帳簿)。", "explain": {"concept": "考商業會計法與帳簿的基本規定。", "steps": ["題目要選『錯誤』的敘述。", "(A)日記簿和總分類帳都是必備的主要帳簿,不能因為日記簿正確就省略總分類帳,所以錯誤。", "(B)試算表的表首日期是交易資料的截止日期,正確。", "(C)帳簿與報表保存10年(永久保存或未結會計事項除外),正確。", "(D)商業會計法規定採權責發生制,平時用現金收付者,決算時要依權責發生制調整,正確。", "所以選(A)。"], "pitfalls": "記不清楚帳簿哪些是『必備』;日記簿與總分類帳都要設。", "distractors": {"B": "此為正確敘述,誤選者可能不熟試算表日期的意義。", "C": "此為正確敘述,誤選者可能記成保存5年。", "D": "此為正確敘述,誤選者可能不知決算時需調整成權責基礎。"}}, "check": "概念題:依官方詳解與商業會計法確認,答案A。", "verified": true, "note": ""}, {"id": "113-5-A-07", "exam": "113-5", "paper": "A", "q": 7, "unit": "一、會計基本概念", "topic": "會計方程式與本期損益", "stem": "崇光商店採曆年制一年決算一次,本年度業主曾發生下列交易:業主增資$51,000、業主提取現金$2,000、業主代墊本店電話費$1,000,年底結帳前資產$1,000,000、權益$450,000,結帳後負債與權益比為2:3,本年度收益為費損的2倍,則本年度收益為何?", "options": ["$150,000", "$300,000", "$650,000", "$1,000,000"], "answer": "B", "figure": null, "official": "結帳後資產=結帳前資產=$1,000,000;負債:權益=2:3→權益=$600,000;本期損益=$600,000-$450,000=$150,000;收益R、費損E,R=2E,R-E=$150,000→R=$300,000。", "explain": {"concept": "資產=負債+權益;結帳只是把損益轉入權益,資產總額不變。", "steps": ["結帳只做損益轉入資本,不影響資產,所以結帳後資產仍是$1,000,000。", "設結帳後權益=3份、負債=2份,資產=負債+權益=5份=$1,000,000,每份$200,000,權益=$600,000。", "結帳前權益$450,000已經含增資、提取、代墊電話費的影響(這些是干擾資訊),所以本期損益=結帳後權益$600,000-結帳前權益$450,000=$150,000。", "設收益為R、費損為E,R=2E,所以R-E=2E-E=E=$150,000,R=$300,000。", "答案選(B)。"], "pitfalls": "把增資$51,000、提取$2,000、代墊電話費$1,000再重複加減;題目說明年底結帳前權益已經包含它們。", "distractors": {"A": "算到本期淨利$150,000(R-E)就停了,忘記題目問的是收益,不是淨利。"}}, "check": "python:R-E=600000-450000=150000且R=2E→R=300000,與官方B相符。", "verified": true, "note": ""}, {"id": "113-5-A-08", "exam": "113-5", "paper": "A", "q": 8, "unit": "四、分錄與日記簿", "topic": "各類交易分錄", "stem": "下列事項的分錄,哪幾項敘述正確?\n①某一客戶的帳款,確認已無法收回,分錄借記「備抵損失-應收帳款」\n②3月1日收到客戶交來發票日為3月11日的支票,分錄借記「應收票據」\n③商品採定期盤存制,購買商品所支付的運費,起運點交貨,分錄借記「運費」\n④本日向銀行借入款項$100,000,借款期間一年,銀行利率為年息3%,本日分錄借記「利息費用$3,000」", "options": ["①②", "②③", "①②③", "①③④"], "answer": "A", "figure": null, "official": "③分錄借記「進貨費用」;④本日分錄借記「現金或銀行存款」,利息費用隨時間經過才認列。", "explain": {"concept": "考沖銷壞帳、遠期支票、進貨運費與借款利息的分錄。", "steps": ["①確認無法收回:借:備抵損失-應收帳款;貸:應收帳款,正確。", "②3/1收到發票日為3/11的支票(遠期支票),還沒到期不能當現金,所以借記『應收票據』,正確。", "③定期盤存制下,起運點交貨的運費是買方負擔,屬於購貨成本的一部分,應借記『進貨費用』(不是運費),錯誤。", "④借款當天只是借到現金:借:現金 100,000;貸:應付票據(或借款) 100,000;利息要隨時間經過才認列,不能當天借記利息費用$3,000,錯誤。", "①②正確,選(A)。"], "pitfalls": "③容易直接記『運費』;其實買方負擔的進貨運費要記『進貨費用』(進貨的一部分)。", "distractors": {"B": "②正確但③錯。", "C": "同樣誤把③當正確。", "D": "漏掉②,又誤選③④。"}}, "check": "①②對,③④錯,與官方A相符。(概念題)", "verified": true, "note": ""}, {"id": "113-5-A-09", "exam": "113-5", "paper": "A", "q": 9, "unit": "五、過帳與分類帳", "topic": "總分類帳與明細分類帳", "stem": "有關過帳與分類帳,下列哪幾項敘述正確?\n①總分類帳是按第三級會計項目設置的帳戶\n②分類帳可以了解個別會計項目的增減變化及餘額\n③總分類帳的日頁與日記簿的類頁,兩者登錄的頁次應完全相同\n④應收帳款統制帳的餘額,必定等於應收帳款各明細分類帳餘額的總和", "options": ["①②", "②③", "②④", "①③④"], "answer": "C", "figure": null, "official": "①總分類帳是按第『四』級會計項目設置的帳戶;③總分類帳的日頁應與日記簿的類頁互註,但登錄的頁次不應完全相同。", "explain": {"concept": "考總分類帳與日記簿頁次互註、統制帳與明細帳關係。", "steps": ["①總分類帳依第四級會計項目(科目)設置帳戶,說第三級是錯的。", "②分類帳可以看到某一會計項目的增減變化和餘額,正確。", "③過帳時,分類帳的日頁和日記簿的類頁要『互相註明』,但兩者頁次並不會完全相同,錯誤。", "④統制帳戶與其明細分類帳:統制帳餘額=各明細分類帳餘額合計,正確。", "②④正確,選(C)。"], "pitfalls": "『互註』不等於『頁次相同』。", "distractors": {"A": "誤信①。", "B": "誤信③。", "D": "同時選了錯的①③,漏掉②。"}}, "check": "②④對,與官方C相符。(概念題)", "verified": true, "note": ""}, {"id": "113-5-A-10", "exam": "113-5", "paper": "A", "q": 10, "unit": "六、試算與試算表", "topic": "錯誤更正與試算表", "stem": "會計人員查核試算表時發現下列錯誤:(1)取得銷貨折讓$3,000,過帳時銷貨折讓過錯借貸方向,(2)現購商品$2,000,分錄誤記為賒銷商品$20,000。若採餘額式試算表,更正前借方餘額合計為$400,000,則更正前的貸方餘額合計為多少?", "options": ["$386,000", "$397,000", "$403,000", "$406,000"], "answer": "D", "figure": null, "official": "更正後借、貸方合計相等($386,000)。更正前貸方=$386,000+$20,000=$406,000。", "explain": {"concept": "更正後借貸要平衡;先算出更正後的合計,再反推更正前的貸方。", "steps": ["先看(1):銷貨折讓是借方科目,應借記$3,000,卻誤記在貸方。這樣借方少了$3,000、貸方多了$3,000,更正時借方要加$6,000(借方補上$3,000,另外貸方的$3,000要移走,所以借方餘額合計差距是2倍)。", "(2)正確分錄:借:進貨 2,000;貸:現金 2,000。錯誤分錄:借:應收帳款 20,000;貸:銷貨收入 20,000。更正後:進貨(借)加$2,000、現金(借)減$2,000、應收帳款(借)減$20,000、銷貨收入(貸)減$20,000。", "借方更正後=$400,000+$6,000+$2,000-$2,000-$20,000=$386,000。", "借貸平衡,所以更正後貸方=$386,000。", "貸方更正時只有銷貨收入減$20,000,所以更正前貸方=$386,000+$20,000=$406,000,選(D)。"], "pitfalls": "(1)折讓過錯方向,餘額差額是『2倍』,容易只算1倍;(2)別忘了銷貨收入要從貸方減。", "distractors": {"A": "這是更正『後』的合計,不是更正『前』。"}}, "check": "python:400,000+6,000+2,000-2,000-20,000=386,000;386,000+20,000=406,000,與官方D相符。", "verified": true, "note": ""}, {"id": "113-5-A-11", "exam": "113-5", "paper": "A", "q": 11, "unit": "七、調整", "topic": "預付費用漏調整的影響", "stem": "巧兔公司X1年7月1日支付二年租金$240,000,當時以「租金支出」入帳,會計人員於X1年底至X3年7月1日到期日,此期間內均未對此交易作任何相關分錄,則上述錯誤對各年相關影響為何?", "options": ["X2年度的本期淨利低估$120,000", "X3年度本期淨利無影響", "X1年底資產高估$180,000", "X2年底保留盈餘低估$60,000"], "answer": "D", "figure": null, "official": "X1:費用多記$180,000→淨利低估、資產低估$180,000;X2:費用少記$120,000→淨利高估$120,000;X3:費用少記$60,000→淨利高估$60,000。X2年底保留盈餘:-$180,000累積+$120,000=低估$60,000。", "explain": {"concept": "預付費用當期應調整的分錄漏做,會讓費用和資產出現『先錯後補』的影響。", "steps": ["每月租金=$240,000÷24個月=$10,000。X1年7~12月6個月=$60,000;X2年12個月=$120,000;X3年1~6月6個月=$60,000。", "X1年:全額$240,000當費用,應只有$60,000,多記費用$180,000→X1淨利低估$180,000,年底資產(預付租金)低估$180,000(選項C寫『高估』是錯的)。", "X2年:沒有認列費用,應有$120,000→費用少記,淨利高估$120,000(選項A寫『低估』是錯的)。", "X3年:應認列$60,000費用但沒有→淨利高估$60,000(選項B說無影響錯)。", "X2年底保留盈餘累計影響=-$180,000+$120,000=-$60,000→低估$60,000,選(D)。(此時還剩X3年$60,000未認列,所以還沒完全抵銷)"], "pitfalls": "方向最容易搞反:費用少記→淨利『高估』;費用多記→淨利『低估』。", "distractors": {"A": "方向搞反:X2年費用少記應為高估,不是低估。", "B": "以為錯誤只影響X1,但X3年6個月的費用也被漏掉了。", "C": "方向搞反:X1年底預付租金漏記,資產應為低估。"}}, "check": "python:240,000/24×6=60,000;X1低估180,000、X2高估120,000、X3高估60,000;X2年底累計低估60,000,與官方D相符。", "verified": true, "note": ""}, {"id": "113-5-A-12", "exam": "113-5", "paper": "A", "q": 12, "unit": "七、調整", "topic": "遞延項目虛轉實法(用品盤存)", "stem": "本店的遞延項目採記虛轉實法記帳,去年底有尚未使用的文具$100,本年度購入文具$3,000,年底盤點文具尚存$500,則下列敘述何者正確?", "options": ["本年底「用品盤存」帳戶餘額為$100", "本年度實際耗用文具用品共計$3,100", "本年底調整整分錄借記「用品盤存」$400", "「用品盤存」屬於速動資產"], "answer": "C", "figure": null, "official": "(A)年底『用品盤存』餘額為$500;(B)本年度耗用=$100+$3,000-$500=$2,600;(C)調整金額=期末餘額$500-期初餘額$100=$400,借記『用品盤存』$400;(D)『用品盤存』不屬於速動資產。", "explain": {"concept": "『記虛轉實法』:購入時記費用(用品費用),期末依盤點把未用的部分轉回資產(用品盤存)。", "steps": ["『記虛』:購入文具$3,000時,借記『用品費用』(費用科目)。", "期初『用品盤存』$100,期末盤點尚存$500,所以期末『用品盤存』應調整為$500。", "調整分錄:借:用品盤存 400(=$500-$100);貸:用品費用 400。(C)正確。", "本年度實際耗用=期初$100+購入$3,000-期末$500=$2,600。(B)寫$3,100是錯的。", "(A)期末餘額應為$500,不是$100;(D)用品盤存不是速動資產(速動資產指現金、短期投資、應收款項這類很快可變現的資產)。"], "pitfalls": "『調整金額』是差額($400),不是期末餘額($500)。", "distractors": {"A": "把期初餘額$100當成年底餘額,忘記調整後變$500。", "B": "把期初$100加購入$3,000,忘了減期末盤存$500。", "D": "誤以為用品盤存是流動資產就是速動資產。"}}, "check": "python:100+3000-500=2600;調整=500-100=400,與官方C相符。", "verified": true, "note": "原題選項(C)印有『調整整分錄』,為原卷用字。"}, {"id": "113-5-A-13", "exam": "113-5", "paper": "A", "q": 13, "unit": "八、結帳", "topic": "結帳程序", "stem": "有關結帳的敘述,下列何者正確?", "options": ["結帳後的「銷貨成本」帳戶為借方餘額", "結帳分錄可不必記入日記簿", "結帳後試算表可編製綜合損益表", "調整程序之後不一定需要做結帳分錄,即可先編製財務報表"], "answer": "D", "figure": null, "official": "(A)結帳後『銷貨成本』已結清歸零;(B)結帳分錄一定要記入日記簿;(C)結帳後試算表沒有收益、費損,無法編製綜合損益表。", "explain": {"concept": "結帳的目的是把暫時性帳戶(收益、費損)結清歸零,並轉入權益。", "steps": ["(A)銷貨成本是費損類暫時性帳戶,結帳後餘額為零,不是借方餘額,錯。", "(B)結帳分錄和其他分錄一樣,要先記入日記簿再過帳,錯。", "(C)結帳後試算表只剩資產、負債、權益,沒有收益、費損科目,所以無法用它編綜合損益表(要用調整後試算表),錯。", "(D)調整完就可以先編財務報表,結帳分錄之後再做也可以,不一定先結帳,正確。", "選(D)。"], "pitfalls": "以為結帳後試算表還可以編綜合損益表。", "distractors": {"A": "忘記暫時性帳戶結帳後歸零。", "B": "以為結帳只是整理帳簿,不用走日記簿程序。", "C": "混淆調整後試算表與結帳後試算表。"}}, "check": "概念題:官方詳解與會計循環常識確認,答案D。", "verified": true, "note": ""}, {"id": "113-5-A-14", "exam": "113-5", "paper": "A", "q": 14, "unit": "九、財務報表", "topic": "錯誤對財務報表的影響", "stem": "連美公司經營手機銷售,商品採永續盤存制,年底會計師查帳時發現下列事項:\n①運送寄銷手機給承銷商,成本$10,000、售價$12,000,誤以賒銷入帳,期末盤點存貨時也漏列該商品\n②營業產生的應收票據,漏提列預期信用減損損失$20,000\n③盤點現金,實際金額$120,000,帳上餘額$119,000,帳上漏未調整\n④存放銀行的活期存款利息$4,000,誤列為租金收入$4,000\n以上錯誤,對連美公司財務報表的影響為何?", "options": ["資產高估$23,000", "營業毛利高估$12,000", "營業利益高估$22,000", "稅前淨利低估$19,000"], "answer": "C", "figure": null, "official": "①資產高估$2,000、毛利高估$2,000、營業利益高估$2,000、稅前淨利高估$2,000;②資產高估$20,000、營業利益高估$20,000、稅前淨利高估$20,000;③資產低估$1,000、稅前淨利低估$1,000(營業外收入少計);④利息收入、租金收入都是營業外收入,無影響。合計:資產高估$21,000、毛利高估$2,000、營業利益高估$22,000、稅前淨利高估$21,000。", "explain": {"concept": "逐項找出錯誤對『資產、營業毛利、營業利益、稅前淨利』的影響,再合計。", "steps": ["①寄銷不是銷貨:誤記賒銷$12,000,應收帳款高估$12,000、銷貨收入高估$12,000;銷貨成本高估$10,000;存貨(寄銷品仍屬公司存貨)漏列→存貨低估$10,000。資產=+12,000-10,000=高估$2,000;毛利=12,000-10,000=高估$2,000;營業利益、稅前淨利同樣高估$2,000。", "②漏提預期信用減損損失$20,000:應收票據(資產)高估$20,000;費用少記→營業利益、稅前淨利高估$20,000;不影響毛利。", "③現金實際比帳上多$1,000,漏記→資產低估$1,000,應認列『營業外收入』$1,000→稅前淨利低估$1,000,不影響營業利益。", "④利息收入與租金收入同屬營業外收入,只是分類錯誤,金額無影響。", "合計:資產=2,000+20,000-1,000=高估$21,000;毛利=高估$2,000;營業利益=2,000+20,000=高估$22,000;稅前淨利=2,000+20,000-1,000=高估$21,000。(C)正確。"], "pitfalls": "①的存貨漏列要記得扣掉;③是營業外收入,不影響營業利益。", "distractors": {"A": "資產合計是$21,000;可能漏了③現金低估要減$1,000,或其他項目多算。", "B": "毛利只高估$2,000(銷貨收入高估$12,000、銷貨成本也高估$10,000),不是$12,000。", "D": "稅前淨利是『高估』$21,000,不是低估。"}}, "check": "python:資產 12000-10000+20000-1000=21000;營業利益 2000+20000=22000;與官方C相符。", "verified": true, "note": ""}, {"id": "113-5-A-15", "exam": "113-5", "paper": "A", "q": 15, "unit": "十一、現金及內部控制", "topic": "銀行存款調節表", "stem": "大洋公司編製銀行存款調節表時,發現公司本月開出一張即期支票$53,000支付貨款,本公司帳上誤記為$83,000,則下列敘述何者正確?", "options": ["編製銀行存款調節表,由銀行對帳單餘額調至公司帳面存款餘額時,該項錯誤應列為加項", "編製銀行存款調節表,以正確餘額法編製時,該項錯誤應作為公司帳面存款餘額的加項", "大洋公司應立即通知銀行,請銀行改正錯誤", "大洋公司補正(更正)分錄應借記:應付帳款$30,000、貸記:銀行存款$30,000"], "answer": "B", "figure": null, "official": "(A)此格式,該項錯誤應列為『減』項;(C)是公司帳上自己的錯誤,不必通知銀行;(D)補正分錄應借記銀行存款$30,000、貸記應付帳款$30,000。", "explain": {"concept": "公司帳上多記支出(多減少存款)$30,000,代表帳面存款被少算,要加回。", "steps": ["先看錯誤:支票實際$53,000,公司帳上記$83,000(貸記銀行存款多了$30,000),所以公司帳面存款『少』了$30,000。", "正確餘額法(兩邊各調成『正確餘額』):公司帳面存款餘額要『加』$30,000,(B)正確。", "(A)由銀行餘額調到公司帳面餘額的格式,是把公司帳面餘額往回推,所以該項錯誤要『減』$30,000,(A)錯。", "(C)錯誤出在公司自己的帳,不是銀行錯,不必通知銀行。", "(D)補正分錄:借:銀行存款 30,000;貸:應付帳款 30,000。題目寫的方向相反,錯。"], "pitfalls": "補正分錄借貸方向最容易寫反:帳上少記存款,就要借記銀行存款。", "distractors": {"A": "以為要加;但此格式是把帳面往回推,應是減。", "C": "誤以為是銀行的錯。", "D": "借貸方向相反。"}}, "check": "帳上少算存款$30,000→帳面餘額加$30,000;補正分錄借:銀行存款30,000、貸:應付帳款30,000。與官方B相符。", "verified": true, "note": ""}, {"id": "113-5-A-16", "exam": "113-5", "paper": "A", "q": 16, "unit": "十二、應收款項", "topic": "銷貨折扣(淨額法)", "stem": "榮光公司4月15日賒銷商品一批,折扣條件為?/10,n/30,採淨價(淨額法)處理,認列應收帳款$709,200。客戶於4月24日以現金償還三分之一的貨款,餘款於5月12日償還。這批銷貨共收取現金$716,400,試計算這批銷貨之現金折扣率為何?", "options": ["1.5%", "2%", "2.5%", "3%"], "answer": "A", "figure": null, "official": "4月24日(折扣期內)還1/3淨額:$709,200÷3=$236,400;5月12日逾折扣期,還餘款時須按原價(失去折扣):$716,400-$236,400=$480,000,其中$472,800是淨額、$7,200是顧客未享折扣。現金折扣率=$7,200÷$480,000=1.5%。", "explain": {"concept": "淨額法:應收帳款先按扣掉折扣後金額記,逾期付款多收的差額就是『顧客未享折扣』。", "steps": ["先抓關鍵:淨額法下,逾折扣期付款要多付現金,多的就是『顧客未享折扣』。", "4/24(在10天內)還1/3:$709,200÷3=$236,400(全額折扣期內,只收淨額)。", "剩下2/3的淨額應收=$709,200×2/3=$472,800。", "5/12已超過10天折扣期,客戶要付毛額。全部收現$716,400,所以5/12收了$716,400-$236,400=$480,000。", "未享折扣=$480,000-$472,800=$7,200。", "現金折扣率=$7,200÷$480,000=1.5%,選(A)。(驗:毛額$720,000×(1-1.5%)=$709,200,正好等於一開始的淨額應收帳款。)"], "pitfalls": "折扣率的分母是『毛額』($480,000),不是淨額$472,800。", "distractors": {}}, "check": "python:709,200×2/3=472,800;716,400-236,400=480,000;(480,000-472,800)/480,000=1.5%,與官方A相符。", "verified": true, "note": ""}, {"id": "113-5-A-17", "exam": "113-5", "paper": "A", "q": 17, "unit": "十二、應收款項", "topic": "期末衡量對收益的影響", "stem": "美麗公司資產的期末衡量項目如下:\n①營業產生的應收帳款項目,衡量前「備抵損失-應收帳款」貸方餘額$1,500、衡量後該帳戶貸方餘額$1,000\n②存貨項目,衡量前「備抵存貨跌價」貸方餘額$2,000、衡量後該帳戶貸方餘額$1,700\n③透過損益按公允價值衡量之金融資產項目,衡量前「強制透過損益按公允價值衡量之金融資產評價調整」借方餘額$2,000、衡量後該帳戶借方餘額$3,000\n④消耗性生物資產項目,衡量前「消耗性生物資產公允價值減出售成本累計變動數」借方餘額$2,000、衡量後該帳戶貸方餘額$300\n以上四項期末衡量,將導致財務報表中「收益」增加之金額為何?", "options": ["$1,000", "$3,000", "$3,300", "$4,100"], "answer": "A", "figure": null, "official": "①衡量分錄借:備抵損失$500、貸:預期信用減損利益$500,資產增加、營業費用減少;②備抵存貨跌價$300轉回,資產增加、營業成本減少;③評價利益$1,000,資產增加、收益增加;④損失$2,300,費用增加。只有③導致『收益』增加$1,000。", "explain": {"concept": "分清楚『費用減少』和『收益增加』不同:收益是利益(如評價利益)才算。", "steps": ["①備抵損失從貸$1,500降到貸$1,000,要沖回$500:借:備抵損失 500;貸:預期信用減損利益 500。官方將它視為『營業費用減少』,不是收益增加。", "②備抵存貨跌價從貸$2,000降到貸$1,700,沖回$300:借:備抵存貨跌價 300;貸:銷貨成本 300,是『營業成本減少』,不是收益。", "③評價調整借方餘額由$2,000增為$3,000,表示公允價值上升:借:評價調整 1,000;貸:透過損益按公允價值衡量之金融資產利益 1,000,是『收益增加』$1,000。", "④公允價值減出售成本累計變動數從借$2,000變貸$300,等於變動$2,300損失:借:生物資產當期公允價值減出售成本之變動損失 2,300;貸:累計變動數 2,300,是費用增加。", "只有③使收益增加$1,000,選(A)。"], "pitfalls": "①②雖然讓利潤變好,但官方分類是『費用/成本減少』,不是『收益增加』;題目問的是收益。", "distractors": {}}, "check": "逐項分類:僅③為收益(利益)$1,000,與官方A相符。(依官方分類判斷)", "verified": true, "note": ""}, {"id": "113-5-A-18", "exam": "113-5", "paper": "A", "q": 18, "unit": "十三、存貨", "topic": "永續盤存制與存貨成本公式", "stem": "強棒公司銷售文具,商品為可替代的大量文具。2月初成立,2月份進、銷貨資料如下:\n\n進貨\n\n| 日期 | 數量 | 單價 |\n|---|---|---|\n| 2/1 | 100 | 100 |\n| 2/10 | 300 | 120 |\n| 2/27 | 200 | 140 |\n\n銷貨\n\n| 日期 | 數量 | 售價 |\n|---|---|---|\n| 2/18 | 200 | 200 |\n\n公司商品採用永續盤存制,則下列敘述哪幾項正確?\n①強棒公司的存貨成本公式,不得採用個別認定法\n②若存貨成本公式採移動平均法,則2月18日的銷貨成本為$23,000\n③若存貨成本公式採先進先出法,則2月18日的銷貨成本小於採移動平均法的銷貨成本\n④若強棒公司2月底實際盤點商品為396件,則調整分錄將導致2月份銷貨成本增加", "options": ["①②", "③④", "①②④", "①②③④"], "answer": "D", "figure": null, "official": "四項皆正確。", "explain": {"concept": "可替代的大量商品不可用個別認定法;永續盤存制下移動平均法每次進貨後重算單位成本。", "steps": ["①商品是可替代的大量文具,不得採個別認定法(個別認定法適用於不可替代、特定專案之商品),正確。", "②移動平均法:2/10進貨後存貨=100+300=400件,成本=$10,000+$36,000=$46,000,平均單位成本=$46,000÷400=$115。2/18賣200件,銷貨成本=200×$115=$23,000,正確。", "③先進先出法:2/18賣200件,先賣2/1的100件($100)+2/10的100件($120)=$10,000+$12,000=$22,000,小於$23,000(因為進貨價格上漲),正確。", "④帳上存貨=400件(2/18存貨200+2/27購200=400件),實際盤點396件→盤損4件,借:銷貨成本(存貨盤損);貸:商品存貨,使銷貨成本增加,正確。", "四項都對,選(D)。"], "pitfalls": "①很多同學以為『一定可以用個別認定法』;可替代的大量商品不行。", "distractors": {"A": "漏掉③④。", "B": "漏掉①②,以為②的移動平均要看期末全期。", "C": "漏掉③,可能沒算先進先出的成本。"}}, "check": "python:FIFO 100×100+100×120=22,000;移動平均 (10,000+36,000)/400×200=23,000;22,000<23,000;400-396=4件盤損。①②③④皆對,與官方D相符。", "verified": true, "note": ""}, {"id": "113-5-A-19", "exam": "113-5", "paper": "A", "q": 19, "unit": "十四、證券投資", "topic": "透過損益按公允價值衡量之金融資產", "stem": "富霸公司X1年8月1日購買甲公司股票,不具重大影響力,持有供交易,股票成交價格$200,000,手續費$200。X1年9月1日收到甲公司的現金股利共$20,000,X1年底認列「透過損益按公允價值衡量之金融資產損失」$13,000,X2年2月1日出售全部持有的股票,認列「透過損益按公允價值衡量之金融資產利益」$22,000,並支付交易成本$1,000,則該金融資產出售日的公允價值為何?", "options": ["$208,000", "$209,000", "$210,000", "$229,000"], "answer": "B", "figure": null, "official": "出售日公允價值=$200,000-$13,000+$22,000=$209,000。", "explain": {"concept": "透過損益按公允價值衡量:取得成本(不含手續費)+評價調整=公允價值;手續費記費用,股利記收入。", "steps": ["取得成本=成交價格$200,000(手續費$200記費用,不計入成本;股利$20,000是收益,與成本無關)。", "X1年底評價損失$13,000→帳面(公允價值)=$200,000-$13,000=$187,000。", "X2年出售日認列利益$22,000,表示公允價值比X1年底的帳面價值$187,000多$22,000(出售利益是以上期期末公允價值為基礎)。", "出售日公允價值=$187,000+$22,000=$209,000,選(B)。", "(出售時支付的交易成本$1,000只是出售費用,不影響公允價值。)"], "pitfalls": "拿手續費、股利去加減成本;這些都不影響公允價值。", "distractors": {"D": "把股利$20,000加進去(誤把股利當成公允價值的一部分)。"}}, "check": "python:200,000-13,000+22,000=209,000,與官方B相符。", "verified": true, "note": ""}, {"id": "113-5-A-20", "exam": "113-5", "paper": "A", "q": 20, "unit": "十五、長期營業用資產", "topic": "不動產成本與除役負債", "stem": "天一公司於X1年底購買實驗室,買價$1,000,000,另付營業稅$50,000、實驗室規劃與建置服務$200,000,另付營業稅$10,000,並估計10年後需花費除役、復原及修復支出$121,900,該支出的現值為$100,000。實驗室估計耐用年限10年,殘值$40,000。天一公司於X12年初報廢該實驗室並完成修復。有關該實驗室之敘述,下列哪幾項正確?\n①入帳成本為$1,250,000\n②可折舊成本為$1,260,000\n③X11年底實驗室調整後帳面金額為$40,000\n④X11年底此實驗室相關之「除役、復原及修復成本之長期負債準備」帳戶餘額為$100,000", "options": ["①③", "①④", "②③", "②③④"], "answer": "C", "figure": null, "official": "①入帳成本=$1,000,000+$200,000+$100,000=$1,300,000;②可折舊成本=$1,300,000-$40,000=$1,260,000;③X11年底耐用年限屆滿,帳面金額=殘值=$40,000;④X11年底累計的負債準備餘額=$121,900。", "explain": {"concept": "不動產成本包含買價、可直接歸屬的建置成本及除役成本現值;營業稅(進項稅額)不計入成本。", "steps": ["①成本=買價$1,000,000+規劃建置服務$200,000+除役成本現值$100,000=$1,300,000(營業稅$50,000、$10,000為進項稅額,不計入成本),所以①的$1,250,000錯。", "②可折舊成本=成本-殘值=$1,300,000-$40,000=$1,260,000,正確。", "③X1年底購入,使用10年到X11年底耐用年限屆滿,累計折舊=$1,260,000,帳面金額=$1,300,000-$1,260,000=$40,000(殘值),正確。", "④除役負債每年要累積利息費用,到第10年底(X11年底)會增加到$121,900(=要付出的金額),不是$100,000,錯誤。", "②③正確,選(C)。"], "pitfalls": "①把營業稅算進成本;④誤以為負債準備不會增加(沒有考慮每年利息累積)。", "distractors": {"A": "①誤把成本算成$1,250,000(漏了除役成本現值$100,000,多算進營業稅等)。", "B": "①、④都錯。", "D": "④誤信負債準備餘額仍為$100,000。"}}, "check": "python:1,000,000+200,000+100,000=1,300,000;-40,000=1,260,000;X11年底帳面=40,000;與官方C相符。", "verified": true, "note": ""}, {"id": "113-5-A-21", "exam": "113-5", "paper": "A", "q": 21, "unit": "十五、長期營業用資產", "topic": "無形資產-專利權攤銷", "stem": "台甲公司X1年初開始進行AI系統的研發。當年1月1日~6月30日屬於研究階段,共支付$800,000,當年7月1日~9月30日屬於發展階段,符合資本化條件支出為$500,000。台甲公司完成AI系統設計,並於X1年10月1日支付相關模型及規費共$100,000取得專利權,經濟效益年限5年,法定年限10年,採直線法攤銷成本。X3年底結帳後發現因產業競爭,此專利權估計年限僅剩2年,則X4年度專利權提列的攤銷費用為何?", "options": ["$80,000", "$110,000", "$137,500", "$165,000"], "answer": "D", "figure": null, "official": "專利權成本=$500,000+$100,000=$600,000;X4年初累計攤銷=$600,000÷5×2又3/12年=$270,000;X4年初帳面金額=$330,000;X4年度攤銷=$330,000÷2年=$165,000。", "explain": {"concept": "研究階段支出費用化;發展階段資本化支出+專利取得成本=專利權成本。估計年限改變,是會計估計變動,按『未攤銷餘額÷剩餘年限』推延調整。", "steps": ["先分階段:研究階段$800,000→當期費用(不是資產)。發展階段符合資本化$500,000→無形資產。取得專利權另付$100,000→也計入成本。", "專利權成本=$500,000+$100,000=$600,000。", "攤銷年限取經濟效益年限5年與法定年限10年之較短者=5年。X1/10/1~X3/12/31共2又3/12年。", "累計攤銷=$600,000÷5×(2+3/12)=$120,000×2.25=$270,000。", "X4年初帳面金額=$600,000-$270,000=$330,000。", "估計年限改為剩2年(會計估計變動,往後調整):X4年攤銷=$330,000÷2=$165,000,選(D)。"], "pitfalls": "忘了研究階段費用不計入成本,也忘了成本要加上$100,000;另外原年限5年不是按10年。", "distractors": {}}, "check": "python:600,000/5×2.25=270,000;(600,000-270,000)/2=165,000,與官方D相符。", "verified": true, "note": ""}, {"id": "113-5-A-22", "exam": "113-5", "paper": "A", "q": 22, "unit": "十五、長期營業用資產", "topic": "IAS 41 農業", "stem": "根據國際會計準則第41號「農業」,有關農業產品的敘述,下列何者正確?", "options": ["出售時以「公允價值減出售成本」衡量", "期末以「公允價值減出售成本」衡量", "「農業產品」不得採用成本模式", "「農業產品」列於生物資產項下"], "answer": "C", "figure": null, "official": "(A)『收成』時以公允價值減出售成本衡量;(B)期末以『成本與淨變現價值孰低法』衡量;(D)『農業產品』於存貨項下。", "explain": {"concept": "農業產品(收成後的產品)是存貨,收成當時以公允價值減出售成本衡量,之後依存貨(IAS 2)處理。", "steps": ["先分清楚:『生物資產』(活的動植物)期末以公允價值減出售成本衡量;『農業產品』是從生物資產收成的產品,屬於存貨。", "(A)收成時才以公允價值減出售成本衡量,『出售時』不是,錯。", "(B)農業產品收成後屬於存貨,期末用『成本與淨變現價值孰低』,不是公允價值減出售成本,錯。", "(D)農業產品列於存貨,不是生物資產,錯。", "(C)官方認定正確,選(C)。"], "pitfalls": "生物資產與農業產品容易混淆:一個是活的、一個是收成後的產品。", "distractors": {"A": "把收成時的衡量誤當出售時。", "B": "把生物資產的期末衡量方法誤套用在農業產品。", "D": "把農業產品與生物資產混為一談。"}}, "check": "概念題:依官方詳解確認,答案C。(IAS 41 原文中『農業產品』收成時以公允價值減出售成本衡量。)", "verified": true, "note": "官方詳解僅說明A、B、D錯誤,C依官方答案為正確。"}, {"id": "113-5-A-23", "exam": "113-5", "paper": "A", "q": 23, "unit": "十六、負債", "topic": "公司債利息費用(有效利息法)", "stem": "大展公司X1年1月1日發行票面利率12%之六年期公司債,每年12月31日付息,有效利率為10%,已知X1年12月31日的付息分錄如下:借:利息費用$108,700、應付公司債溢價$11,300,貸:現金$120,000,試計算該項應付公司債的X2年度利息費用為何?", "options": ["$107,570", "$108,700", "$109,830", "$120,000"], "answer": "A", "figure": null, "official": "發行價格=$108,700÷10%=$1,087,000;X1年底帳面金額=$1,087,000-$11,300=$1,075,700;X2年度利息費用=$1,075,700×10%=$107,570。", "explain": {"concept": "有效利息法:利息費用=期初帳面金額×有效利率。", "steps": ["X1年利息費用=發行價格×有效利率10%=$108,700,所以發行價格=$108,700÷10%=$1,087,000。", "X1年底帳面金額=期初$1,087,000-本年溢價攤銷$11,300=$1,075,700。", "X2年利息費用=$1,075,700×10%=$107,570,選(A)。", "(驗:票面利息$120,000=$1,000,000×12%,溢價攤銷=$120,000-$107,570=$12,430。)"], "pitfalls": "X2年利息費用要用『X1年底的帳面金額』(不是發行價格)去乘。", "distractors": {"B": "把X1年的利息費用直接當作X2年。", "D": "把現金付息$120,000(票面利息)當成利息費用。"}}, "check": "python:發行價1,087,000;X1底1,075,700;×10%=107,570,與官方A相符。", "verified": true, "note": ""}, {"id": "113-5-A-24", "exam": "113-5", "paper": "A", "q": 24, "unit": "十七、權益", "topic": "加權平均流通在外股數與股本", "stem": "富田公司發行普通股,每股面額$10,本年度普通股發行資料如下:1月1日流通在外普通股10,000股,4月1日發放股票股利每股1元,8月1日以每股$12現金增資發行股數若干,9月1日購回庫藏股票3,000股,12月1日出售庫藏股票1,200股,已知當年度普通股流通在外加權平均股數為12,600股,則8月1日現金增資發行後富田公司「普通股股本」帳戶餘額為何?", "options": ["$60,000", "$160,000", "$170,000", "$182,000"], "answer": "C", "figure": null, "official": "股票股利每股1元(面額$10)=10%,10,000×1.1=11,000股。設現金增資x股:11,000+x×5/12-3,000×4/12+1,200×1/12=12,600,x=6,000股。8月1日後普通股股本=$10×11,000+$10×6,000=$170,000。", "explain": {"concept": "加權平均股數=各期間股數×流通月份/12;股票股利要追溯調整(視為年初就已發放);庫藏股買回則不影響股本帳戶。", "steps": ["股票股利每股$1,面額$10,所以股票股利率=1÷10=10%,股數追溯調整:10,000×(1+10%)=11,000股(從年初就算)。", "設8/1現金增資發行x股,流通5個月(8~12月)。庫藏股9/1購回3,000股,影響4個月(減);12/1出售1,200股,影響1個月(加)。", "列式:11,000+x×5/12-3,000×4/12+1,200×1/12=12,600。", "11,000+5x/12-1,000+100=12,600→5x/12=2,500→x=6,000股。", "8月1日增資後普通股股數=11,000+6,000=17,000股,股本=17,000×$10=$170,000(庫藏股是買回後另列,不減少股本帳戶),選(C)。"], "pitfalls": "股本要用『面額』乘『發行股數』,不是用現金增資的發行價$12;庫藏股交易不影響普通股股本。", "distractors": {"A": "只算增資的$60,000(6,000股×$10)。", "B": "只算10,000+6,000=16,000股,忘了股票股利1,000股。", "D": "可能用$12發行價算增資部分($110,000+$72,000)。"}}, "check": "python:11,000+6,000×5/12-3,000×4/12+1,200/12=12,600;股本=10×17,000=170,000,與官方C相符。", "verified": true, "note": ""}, {"id": "114-1-A-01", "exam": "114-1", "paper": "A", "q": 1, "unit": "一、會計基本概念", "topic": "會計資訊用途與準則", "stem": "下列敘述何者錯誤?", "options": ["債權人可藉由會計資訊衡量企業之償債能力,以決定是否貸放款項", "當稅法與一般公認會計原則有差異時,企業的帳載記錄應遵循一般公認會計原則,報稅時為符合稅法之規定,再於申報時作帳外調整", "會計研究發展基金會係採用營利事業會計", "企業內部管理人員可藉會計資訊了解經營狀況,以規劃未來經營策略"], "answer": "C", "figure": null, "official": "會計研究發展基金會係採非營利事業會計。", "explain": {"concept": "題目問「錯誤」的敘述,要逐項檢查會計資訊使用者、稅法與會計準則差異,以及基金會的會計制度。", "steps": ["先看題目問的是「錯誤」,所以要找出說錯的那一項。", "(A) 債權人(銀行)看財報評估企業還不還得起錢,正確。", "(B) 稅法和會計準則不同時,帳上照會計準則記,報稅時再做帳外調整,正確。", "(C) 會計研究發展基金會是財團法人(非營利組織),採用的是非營利事業會計,不是營利事業會計,所以這句是錯的。", "(D) 管理人員用會計資訊做內部決策,正確。"], "pitfalls": "看到「錯誤」要選說錯的,別誤選正確的敘述。", "distractors": {"A": "此敘述正確,是債權人使用財報的目的,不是答案。", "B": "此敘述正確,帳務遵循準則、報稅時才調整。", "D": "此敘述正確,屬管理會計的用途。"}}, "check": "概念題:對照官方詳解與商業會計常識,(C)為錯誤敘述,與答案相符。", "verified": true, "note": ""}, {"id": "114-1-A-02", "exam": "114-1", "paper": "A", "q": 2, "unit": "一、會計基本概念", "topic": "會計基本假設", "stem": "有關會計基本假設,下列敘述何者錯誤?", "options": ["依據「財務報導之觀念架構」,財務報表之基本假設為繼續經營假設", "在幣值波動嚴重時,貨幣評價假設最易遭到質疑", "員工士氣是很有價值的人力資源,基於貨幣評價假設不能入帳", "企業個體假設為會計上流動與非流動項目之劃分提供理論基礎"], "answer": "D", "figure": null, "official": "繼續經營假設為會計上流動與非流動項目之劃分提供理論基礎。", "explain": {"concept": "分辨各會計假設(企業個體、繼續經營、會計期間、貨幣評價)各自的作用。", "steps": ["題目問「錯誤」。", "(A) 觀念架構規定財報基本假設是繼續經營假設,正確。", "(B) 貨幣評價假設假設幣值穩定,通貨膨脹嚴重時最容易被質疑,正確。", "(C) 員工士氣無法用金錢衡量,所以不入帳,正確。", "(D) 把資產負債分成流動與非流動,是因為假設企業會繼續經營下去(例如「一年內」變現才有意義),所以基礎是繼續經營假設,不是企業個體假設。企業個體假設是指企業與業主要分開記帳。所以 (D) 錯。"], "pitfalls": "企業個體假設(企業與業主分開)和繼續經營假設(企業會持續營運)容易搞混。", "distractors": {"A": "此敘述正確。", "B": "此敘述正確。", "C": "此敘述正確。"}}, "check": "概念題:對照官方詳解與觀念架構,(D)為錯誤敘述。", "verified": true, "note": ""}, {"id": "114-1-A-03", "exam": "114-1", "paper": "A", "q": 3, "unit": "二、會計循環及會計帳簿", "topic": "商業會計法與帳簿", "stem": "下列敘述何者正確?", "options": ["我國《商業會計法》所規定必須設置的帳簿為普通序時帳簿和總分類帳簿", "會計循環就是營業循環,期間通常為一年", "我國《商業會計法》規定會計事項應按發生次序逐日登帳,至遲不得超過一個月", "用以記載過帳的帳簿為日記簿"], "answer": "A", "figure": null, "official": "(B) 營業循環為現金→進貨→銷貨→應收帳款→現金;(C) 至遲不得超過二個月;(D) 記載分錄的帳簿為日記簿。", "explain": {"concept": "考商業會計法規定的必備帳簿與登帳期限,以及會計循環與營業循環的差別。", "steps": ["(A) 商業會計法規定必須設置的帳簿是「序時帳簿」(普通日記簿)與「分類帳簿」(總分類帳),正確。", "(B) 會計循環是分錄、過帳、試算、調整、結帳、編表六大程序;營業循環是現金→進貨→銷貨→應收帳款→現金,兩者不同。", "(C) 登帳最遲不得超過二個月,不是一個月。", "(D) 日記簿是記「分錄」的帳簿;記載「過帳」的是分類帳。"], "pitfalls": "把會計循環和營業循環當成同一件事;登帳期限記成一個月。", "distractors": {"B": "誤以為會計循環等於營業循環。", "C": "記錯期限,法條是二個月。", "D": "把日記簿記分錄、分類帳記過帳的分工弄反。"}}, "check": "概念題:對照官方詳解與商業會計法,(A)正確。", "verified": true, "note": ""}, {"id": "114-1-A-04", "exam": "114-1", "paper": "A", "q": 4, "unit": "二、會計循環及會計帳簿", "topic": "會計循環與帳簿", "stem": "學習會計必須先認識會計循環及會計帳簿,下列敘述哪幾項錯誤?\n①複式簿記是依據借貸平衡原理和借貸法則,交易事項對財務報表五大要素共有 25 種增減變化組合\n②營業循環是指分錄、過帳、試算、調整、結帳及編表六大程序\n③除未結會計事項外,會計帳簿及財務報表,應於年度決算程序辦理終了後,至少保存十年\n④我國《商業會計法》規定,企業之會計年度一律採用曆年制\n⑤財務會計最主要的目的是強化內部控制與防止舞弊", "options": ["①③", "①②④", "②④⑤", "②③④⑤"], "answer": "C", "figure": null, "official": "②該程序為會計循環;④商業以曆年制為原則,但法律另有規定或營業上有特殊需要者不在此限;⑤財務會計最主要目的是提供財務資訊給企業外部使用者作決策參考。", "explain": {"concept": "逐一判斷五項敘述真假,選出錯的有哪幾項。", "steps": ["①五大要素(資產、負債、權益、收入、費用)增減組合共 25 種,正確。", "②分錄、過帳、試算、調整、結帳、編表是「會計循環」,不是營業循環,錯誤。", "③帳簿與報表至少保存十年,正確。", "④法令是「原則」採曆年制,但有例外(例如另有規定或特殊營業需要),說「一律」就錯了。", "⑤財務會計主要目的是提供資訊給外部使用者做決策,不是內控防弊,錯誤。", "錯誤的是②④⑤,所以選 (C)。"], "pitfalls": "「一律」、「最主要」這類絕對字眼常是陷阱。", "distractors": {"A": "把正確的①③當成錯誤,且漏掉②④⑤。", "B": "誤以為①錯、漏掉⑤。", "D": "誤把正確的③也當成錯誤。"}}, "check": "概念題:五項逐一對照官方詳解,錯誤為②④⑤,與答案 C 相符。", "verified": true, "note": ""}, {"id": "114-1-A-05", "exam": "114-1", "paper": "A", "q": 5, "unit": "一、會計基本概念", "topic": "會計恆等式與損益", "stem": "年底結帳前負債為$210,000,資產:權益=3:1。本年度業主增資$20,000、提取商品$2,000,結帳後資產為$360,000,若本期收益$500,000,則本期費損為多少?", "options": ["$30,000", "$470,000", "$530,000", "$540,000"], "answer": "B", "figure": null, "official": "結帳前權益=$360,000÷3=$120,000;本期損益$30,000;費損=$500,000−$30,000=$470,000。", "explain": {"concept": "用會計恆等式 資產=負債+權益,先求本期損益,再由 淨利=收益−費損 求費損。", "steps": ["結帳只是把損益轉入權益,不會改變資產總額,所以結帳前資產也是$360,000。", "題目說結帳前 資產:權益=3:1,所以結帳前權益=$360,000÷3=$120,000(這是結帳前、尚未加入本期損益的權益)。", "增資$20,000、提取$2,000 在結帳前已經記入權益,是干擾資訊,不用再加減。", "結帳後權益=資產−負債=$360,000−$210,000=$150,000。", "本期損益=結帳後權益−結帳前權益=$150,000−$120,000=$30,000(淨利)。", "淨利=收益−費損,所以費損=$500,000−$30,000=$470,000。"], "pitfalls": "把增資、提取再加減一次而算錯;或把淨利$30,000 誤當成費損。", "distractors": {"A": "把本期淨利$30,000 當成答案,忘了要求的是費損。", "C": "用 $500,000+$30,000 把淨利加上去。", "D": "把增資、提取等干擾資料誤加減後所得。"}}, "check": "python: 權益前=360000/3=120000; 後權益=360000-210000=150000; 淨利=30000; 費損=500000-30000=470000,與答案相符。", "verified": true, "note": ""}, {"id": "114-1-A-06", "exam": "114-1", "paper": "A", "q": 6, "unit": "四、分錄與日記簿", "topic": "交易種類與傳票", "stem": "基隆商店購入商品一批$15,000,貨款的三分之一付現、三分之一以五個月期的票據支付、餘款暫欠,則此交易種類為何以及在複式傳票四分法應編製哪一種傳票?", "options": ["轉帳交易;分錄轉帳傳票", "轉帳交易;現金轉帳傳票", "混合交易;分錄轉帳傳票", "混合交易;現金轉帳傳票"], "answer": "D", "figure": null, "official": "分錄:借進貨$15,000,貸現金$5,000、應付票據$5,000、應付帳款$5,000;為混合交易,四分法需編製現金轉帳傳票。", "explain": {"concept": "交易有部分現金、部分非現金為混合交易;四分法的混合交易用「現金轉帳傳票」。", "steps": ["分錄:借:進貨 15,000;貸:現金 5,000、應付票據 5,000、應付帳款 5,000。", "有一部分現金(付現$5,000),另一部分沒動到現金(票據、賒欠),所以是「混合交易」。", "混合交易在四分法下,先把交易拆成現金部分和轉帳部分,編「現金轉帳傳票」(現金收入/支出傳票只用於全部現金交易)。", "所以答案是混合交易;現金轉帳傳票。"], "pitfalls": "全部是非現金才叫轉帳交易;有現金又有非現金就是混合交易。", "distractors": {"A": "沒看到有付現,誤判成轉帳交易。", "B": "同樣誤判為轉帳交易。", "C": "交易種類對,但傳票誤選分錄轉帳傳票。"}}, "check": "概念題:對照官方詳解,混合交易→現金轉帳傳票,與答案相符。", "verified": true, "note": ""}, {"id": "114-1-A-07", "exam": "114-1", "paper": "A", "q": 7, "unit": "二、會計循環及會計帳簿", "topic": "日記簿與分類帳", "stem": "下列敘述何者正確?", "options": ["日記簿又稱分類帳,為原始帳簿", "日記簿是以交易事項為主體的原始記錄簿", "分類帳主要功能為明瞭各交易的整體情形", "日記簿可瞭解每一會計項目的增減變動情形及餘額"], "answer": "B", "figure": null, "official": "(A) 日記簿又稱分錄簿,為原始記錄簿;(C) 日記簿主要功能為明瞭各交易的整體情形;(D) 分類帳可瞭解每一會計項目的增減變動情形及餘額。", "explain": {"concept": "區分日記簿(以交易為主、序時記錄)與分類帳(以會計項目為主、彙總餘額)的功能。", "steps": ["日記簿:按時間先後記分錄,以「交易」為單位,所以能看到每筆交易的整體樣貌,是原始記錄簿。", "分類帳:按「會計項目」分戶,能看到各科目的增減與餘額。", "(B) 符合日記簿的特性,正確。", "(A) 日記簿又稱「分錄簿」,不是分類帳。", "(C)(D) 兩者功能被對調了。"], "pitfalls": "日記簿看交易、分類帳看科目,別弄反。", "distractors": {"A": "日記簿的別名是分錄簿,不是分類帳。", "C": "這是日記簿的功能,被誤說成分類帳。", "D": "這是分類帳的功能,被誤說成日記簿。"}}, "check": "概念題:對照官方詳解,(B)正確。", "verified": true, "note": ""}, {"id": "114-1-A-08", "exam": "114-1", "paper": "A", "q": 8, "unit": "六、試算與試算表", "topic": "試算與錯誤更正", "stem": "下列敘述哪幾項正確?\n①一筆分錄借方或貸方其中一方重複過帳,此錯誤不會影響試算表借貸平衡\n②試算是基於借貸平衡原理,用以檢查分錄與過帳的工作有無錯誤的驗證程序\n③不影響借貸平衡之錯誤,其更正方法須視其過帳與否而有所差別\n④簽發一個月期支票誤為簽發即期支票,更正分錄為借:銀行存款,貸:應付票據", "options": ["②③④", "①②③", "①③④", "③④"], "answer": "A", "figure": null, "official": "①一筆分錄借方或貸方其中一方重複過帳,此錯誤會影響試算表借貸平衡。", "explain": {"concept": "判斷哪些錯誤會讓試算表不平衡,以及錯誤更正分錄的寫法。", "steps": ["①只重複過帳借方或貸方其中一邊,借貸合計就不相等,會使試算表不平衡,所以①錯。", "②試算就是利用借貸平衡原理檢查分錄與過帳,正確。", "③不影響平衡的錯誤(例如記錯科目),更正方式要看有沒有過帳:未過帳可直接塗改,已過帳要編更正分錄,正確。", "④一個月期支票是遠期支票,應記「應付票據」;誤當即期支票則記成貸:銀行存款。更正要把貸銀行存款沖回,借:銀行存款,貸:應付票據,正確。", "正確的是②③④,選 (A)。"], "pitfalls": "「只過一邊」會不平衡;「兩邊都過但科目錯」才不影響平衡。", "distractors": {"B": "誤認①正確。", "C": "誤認①正確且漏掉②。", "D": "漏選②,以為只有③④。"}}, "check": "概念題:逐項對照官方詳解與更正分錄邏輯(誤貸銀行存款→借銀行存款、貸應付票據),②③④正確。", "verified": true, "note": ""}, {"id": "114-1-A-09", "exam": "114-1", "paper": "A", "q": 9, "unit": "六、試算與試算表", "topic": "錯誤與試算平衡", "stem": "下列哪一個會計錯誤事項會使餘額式試算表借貸仍然平衡?", "options": ["償還賒欠$400,過帳時借:應收帳款$400,貸:現金$400", "業主提取現金$450,分錄誤記為借:業主往來$450,貸:現金$540", "現購文具用品$1,000,過帳時借:文具用品$1,000,貸:現金$100", "現購文具用品$300,過帳時誤將現金項目過帳至借方$300"], "answer": "A", "figure": null, "official": "(A) 有借方金額、有貸方金額且借貸金額相同,故仍然平衡;(B)(C) 借貸不同;(D) 使餘額式試算表借方多計$600。", "explain": {"concept": "找出借貸金額仍相等的錯誤:只是科目錯誤、方向正確,借貸金額不變。", "steps": ["(A) 應該是借:應付帳款、貸:現金,卻誤借應收帳款$400、貸現金$400;借貸金額都是$400,仍平衡(只是科目錯)。", "(B) 借$450、貸$540,金額不同,不平衡。", "(C) 借$1,000、貸$100,不平衡。", "(D) 現金應過在貸方,誤過到借方$300:借方多$300、貸方少$300,借方比貸方多$600,不平衡。", "所以選 (A)。"], "pitfalls": "看「借貸金額是否相等」,不是看科目對不對。", "distractors": {"B": "借$450 貸$540,數字順序顛倒造成不平衡。", "C": "借$1,000 貸$100,漏了一個零,不平衡。", "D": "過錯方向會讓借方多$600,不平衡。"}}, "check": "逐項計算借貸差:A 0;B 90;C 900;D 600。僅A平衡,與答案相符。", "verified": true, "note": ""}, {"id": "114-1-A-10", "exam": "114-1", "paper": "A", "q": 10, "unit": "七、調整", "topic": "調整事項影響", "stem": "下列敘述何者正確?", "options": ["如果平時帳務處理皆正確,省略期末調整程序並不影響報表的正確", "年底少提列應付利息會使負債及淨利均多計", "年底少提預期信用減損損失會使權益多計", "調整後試算表上不會出現收益和費損的會計項目"], "answer": "C", "figure": null, "official": "(A) 省略期末調整程序會影響報表的正確;(B) 利息費用少計淨利多計,應付利息少計負債少計;(D) 調整後試算表會出現收益和費損的會計項目。", "explain": {"concept": "調整漏列時,對費用/收入、資產/負債與淨利、權益的影響方向。", "steps": ["(A) 平時記帳再正確,應收應付、折舊等仍需期末調整,不調整報表就不正確。", "(B) 少提應付利息:費用少記 → 淨利多計;負債也少記 → 負債少計。說「負債多計」是錯的。", "(C) 少提預期信用減損損失:費用少記 → 淨利多計 → 權益多計,正確。", "(D) 調整後試算表仍列出所有收益費損科目(結帳後才會消失)。"], "pitfalls": "漏提費用:淨利多、權益多;但漏提負債,負債是少計。", "distractors": {"A": "以為平時記對就不需調整。", "B": "忘了漏提應付利息會讓負債「少」計。", "D": "誤以為調整後收益費損科目消失,其實結帳後才歸零。"}}, "check": "概念題:漏提費用→淨利多計→權益多計,與官方詳解一致。", "verified": true, "note": ""}, {"id": "114-1-A-11", "exam": "114-1", "paper": "A", "q": 11, "unit": "七、調整", "topic": "預付租金調整", "stem": "潤全、福全兩家商店同時於 08 年某月 1 日,向甲公司租用攤位,當時預付租金一年,兩家商店所付的租金均相同,但入帳基礎不同。08 年底兩家商店所作的調整分錄如下:\n\n潤全:\n借:租金支出  $150,000\n  貸:預付租金  $150,000\n\n福全:\n借:預付租金  $210,000\n  貸:租金支出  $210,000\n\n則兩家商店自哪一個月份開始租用?", "options": ["6月", "7月", "8月", "9月"], "answer": "C", "figure": null, "official": "每月租金=($150,000+$210,000)÷12=$30,000;潤全08年度認列租金支出增加$150,000,代表已過期:$150,000÷$30,000=5個月,故為8/1起租用。", "explain": {"concept": "預付租金兩種入帳基礎(資產法/費用法)的調整分錄方向不同,可由調整金額反推已過月數。", "steps": ["潤全調整「借:租金支出、貸:預付租金」,表示付款時記在預付租金(資產法),年底把已到期的部分轉成費用,所以$150,000 是已過期的租金。", "福全調整「借:預付租金、貸:租金支出」,表示付款時全記租金支出(費用法),年底把未到期的部分轉回資產,所以$210,000 是未到期的租金。", "兩者合起來就是一年租金:$150,000+$210,000=$360,000。", "每月租金=$360,000÷12=$30,000(福全未到期7個月、潤全已過5個月,5+7=12,互相吻合)。", "已過月數=$150,000÷$30,000=5 個月,到 12 月底共租 5 個月,所以是 8、9、10、11、12 月,從 8 月 1 日起租。"], "pitfalls": "資產法與費用法的調整分錄方向相反;潤全調整的是已過期、福全調整的是未到期。", "distractors": {"A": "拿福全的 7 個月當已過期月數(12−7+1=6月),把未到期誤當已過期。"}}, "check": "python: 360000/12=30000; 潤全150000/30000=5個月已過→8月起; 福全210000/30000=7個月未到期,5+7=12,與答案相符。", "verified": true, "note": ""}, {"id": "114-1-A-12", "exam": "114-1", "paper": "A", "q": 12, "unit": "七、調整", "topic": "期末調整對淨利", "stem": "文文為甲公司新任會計人員,因初任無經驗於期末漏作下列調整分錄,已知甲公司對預計項目採權責基礎:\n①運輸設備當年度應提列折舊$6,000  ②應付未付佣金$4,500\n③用品盤存經盤點得知當期耗用共$2,400  ④預收佣金已實現部分$8,000\n⑤應收未收利息$7,000\n若調整前淨利為$50,000,則調整後淨利為多少?", "options": ["$36,100", "$45,100", "$46,700", "$52,100"], "answer": "D", "figure": null, "official": "$50,000−折舊$6,000−佣金支出$4,500−文具用品$2,400+佣金收入$8,000+利息收入$7,000=$52,100。", "explain": {"concept": "漏作調整,要把漏掉的費用扣除、漏掉的收入加回,求調整後淨利。", "steps": ["費用類調整(會使淨利減少):①折舊$6,000、②應付佣金(佣金費用)$4,500、③用品耗用$2,400,合計$12,900。", "收入類調整(會使淨利增加):④預收佣金已實現$8,000、⑤應收利息$7,000,合計$15,000。", "調整後淨利=調整前淨利−費用+收入=$50,000−$12,900+$15,000=$52,100。"], "pitfalls": "預收收入的「已實現部分」是收入增加,不要誤當成減少。", "distractors": {}}, "check": "python: 50000-6000-4500-2400+8000+7000=52100,與答案相符。", "verified": true, "note": ""}, {"id": "114-1-A-13", "exam": "114-1", "paper": "A", "q": 13, "unit": "八、結帳", "topic": "結帳程序敘述", "stem": "有關結帳的敘述,下列正確者有幾項?\n①將所有虛帳戶的餘額結轉下期繼續記錄\n②結帳分錄乃用以記錄企業之結束營運\n③實帳戶的結帳方法包括英美式結轉法與大陸式結轉法\n④實帳戶之結轉若採大陸式結轉法,此法又稱為分錄結轉法,須於日記簿作結帳分錄與開帳分錄\n⑤不需要作結帳分錄,即可編製財務報表\n⑥虛帳戶結帳後沒有餘額,所以結帳分錄不必過帳", "options": ["二項", "三項", "四項", "五項"], "answer": "B", "figure": null, "official": "正確者:③、④、⑤,共三項。①實帳戶結轉下期;②結帳分錄為結清虛帳戶、實帳戶結轉下期;⑥結帳分錄須過帳。", "explain": {"concept": "逐項判斷結帳程序的敘述真假。", "steps": ["①結轉下期繼續記錄的是「實帳戶」,虛帳戶結帳後歸零,錯。", "②結帳分錄是為了結清虛帳戶、把實帳戶餘額結轉下期,不是結束營運,錯。", "③實帳戶結轉有英美式(不作分錄,直接在帳上結轉)與大陸式(用分錄結轉)兩種,正確。", "④大陸式即分錄結轉法,要在日記簿作結帳分錄與開帳分錄,正確。", "⑤編財報不需先作結帳分錄(結帳前即可用調整後試算表編製),正確。", "⑥結帳分錄一樣要過帳到分類帳,錯。", "正確共 ③④⑤ 三項。"], "pitfalls": "結帳分錄也要過帳;虛帳戶才歸零,實帳戶是結轉下期。", "distractors": {"A": "少算一項。", "C": "多算一項,誤以為①或②或⑥正確。", "D": "多算兩項。"}}, "check": "概念題:逐項對照官方詳解,正確③④⑤共三項。", "verified": true, "note": ""}, {"id": "114-1-A-14", "exam": "114-1", "paper": "A", "q": 14, "unit": "十三、存貨", "topic": "現金折扣", "stem": "昕昕公司賒銷商品乙批,現金折扣條件為 2/10,1/20,n/30。下列為買方的付款情形,何者可使昕昕公司收取現金總額最多?", "options": ["成交後第 9 天支付一半款項,成交後第 25 天支付另一半款項", "成交後第 10 天支付一半款項,成交後第 19 天支付另一半款項", "成交後第 11 天支付一半款項,成交後第 21 天支付另一半款項", "成交後第 21 天支付一半款項,成交後第 30 天支付另一半款項"], "answer": "D", "figure": null, "official": "假設賒銷商品$100:(A) $99;(B) $98.5;(C) $99.5;(D) $100。", "explain": {"concept": "2/10,1/20,n/30:10 天內付款折 2%,11~20 天折 1%,超過 20 天無折扣。折扣越多,賣方收到的現金越少。", "steps": ["先假設賒銷$100,每半就是$50。", "(A) 第 9 天(折 2%)付$50×98%=$49,第 25 天(逾 20 天無折扣)付$50,共$99。", "(B) 第 10 天(折 2%)付$49,第 19 天(折 1%)付$49.5,共$98.5。", "(C) 第 11 天(折 1%)付$49.5,第 21 天(無折扣)付$50,共$99.5。", "(D) 第 21 天與第 30 天都沒折扣,共$100。", "賣方收到現金最多的是沒有折扣的 (D)。"], "pitfalls": "題目問賣方收現最多,不是買方省最多,折扣越少賣方收越多。", "distractors": {"A": "2%折扣一半+無折扣一半=$99。", "B": "折扣最多,賣方收最少。", "C": "1%折扣一半+無折扣一半=$99.5,仍少於(D)。"}}, "check": "python: A=49+50=99; B=49+49.5=98.5; C=49.5+50=99.5; D=100; 最大D,與答案相符。", "verified": true, "note": ""}, {"id": "114-1-A-15", "exam": "114-1", "paper": "A", "q": 15, "unit": "四、分錄與日記簿", "topic": "各類交易分錄", "stem": "下列為酷酷餐飲集團的各筆交易分錄,何者錯誤?", "options": ["推出聖誕節特惠活動,吸引了不少的顧客預先訂購商品並收取訂金$200,000,其分錄為借:現金$200,000,貸:預收貨款$200,000", "向中華電信租用市內電話話機一台,支付保證金$1,000,簽發彰銀即期支票一張支付,其分錄為借:存出保證金$1,000,貸:應付票據$1,000", "因減醣料理風行,集團聘請了專任營養師,每月底支付薪水$100,000,其支薪分錄為借:薪資支出$100,000,貸:現金$100,000", "賒銷禮盒$30,000給東東公司,酷酷餐飲集團開出匯票請求東東公司承兌,其分錄為借:應收帳款$30,000,貸:銷貨收入$30,000"], "answer": "B", "figure": null, "official": "(B) 其分錄應為借:存出保證金$1,000,貸:銀行存款$1,000。", "explain": {"concept": "簽發即期支票=現金性質,貸銀行存款(或現金),不是應付票據。", "steps": ["(A) 收到訂金→預收貨款(負債),正確。", "(B) 簽發的是「即期支票」,等於立即從銀行存款扣款,應貸:銀行存款,不是應付票據(遠期票據才用應付票據),所以 (B) 錯。", "(C) 付薪水借薪資支出貸現金,正確。", "(D) 賒銷並開匯票請對方承兌,對方承兌前還是記應收帳款,正確。"], "pitfalls": "即期支票記銀行存款;遠期支票(票據)才記應付票據。", "distractors": {"A": "此分錄正確。", "C": "此分錄正確。", "D": "賒銷時先記應收帳款,承兌後才轉應收票據,此分錄正確。"}}, "check": "概念題:對照官方詳解,(B)為錯誤分錄。", "verified": true, "note": ""}, {"id": "114-1-A-16", "exam": "114-1", "paper": "A", "q": 16, "unit": "一、會計基本概念", "topic": "會計準則發布與適用", "stem": "有關會計準則的發布及適用,下列敘述何者正確?", "options": ["我國制定企業會計準則公報的組織是金融監督管理委員會證券期貨局", "我國發布證券發行人財務報告編製準則的機構是會計研究發展基金會", "我國公開發行公司其會計事務處理之各項法令及準則的適用位階為:證券交易法>公司法>商業會計法>證券發行人財務報告編製準則>商業會計處理準則>國際財務報導準則", "我國非公開發行公司其會計事務處理之各項法令及準則的適用位階為:公司法>企業會計準則公報>商業會計處理準則"], "answer": "C", "figure": null, "official": "(A) 制定企業會計準則公報的是會計研究發展基金會;(B) 發布證券發行人財務報告編製準則的是金融監督管理委員會證券期貨局;(D) 非公開發行公司的位階為公司法>商業會計處理準則>企業會計準則公報。", "explain": {"concept": "區分會計準則的制定機構與各法令準則的適用位階。", "steps": ["(A)(B) 兩個機構被對調:會計準則公報由會計研究發展基金會制定,證券發行人財報編製準則由金管會證期局發布。", "(C) 公開發行公司適用順序為證券交易法>公司法>商業會計法>證券發行人財務報告編製準則>商業會計處理準則>國際財務報導準則,正確。", "(D) 非公開發行公司的順序應是公司法>商業會計處理準則>企業會計準則公報,不是題目所寫。"], "pitfalls": "發布機構別對調;位階順序要按法律層級背熟。", "distractors": {"A": "機構對調,制定者是會計研究發展基金會。", "B": "機構對調,發布者是金管會證期局。", "D": "位階順序中,商業會計處理準則高於企業會計準則公報。"}}, "check": "概念題:對照官方詳解,(C)正確。", "verified": true, "note": ""}, {"id": "114-1-A-17", "exam": "114-1", "paper": "A", "q": 17, "unit": "六、試算與試算表", "topic": "試算表錯誤調整", "stem": "小銘於年底查核餘額式試算表時發現下列錯誤:\n①現銷商品$5,000,誤記為賒銷商品\n②有一筆交易事項,借:應收帳款$3,000、貸:銷貨收入$3,000,過帳時發生借貸方向相反錯誤\n小銘由錯誤試算表計算正確的餘額式試算表合計數時,應如何處理?", "options": ["借貸方總額各減$8,000", "借方總額減$6,000,貸方總額加$6,000", "借貸方總額各加$3,000", "借貸方總額各加$6,000"], "answer": "D", "figure": null, "official": "①應收帳款與現金都是借餘的會計項目,錯誤會抵銷;②採餘額式試算表下,該帳戶過錯方向,金額差異 2 倍,因此應收帳款借方餘額低列$6,000;銷貨收入貸方餘額低列 2 倍,即$6,000,故應各加$6,000。", "explain": {"concept": "餘額式試算表只看科目餘額。方向過反會讓餘額差 2 倍。", "steps": ["①現銷誤為賒銷:應借現金卻借了應收帳款,兩者同為借方,借方總額不變,不用調整。", "②借應收帳款$3,000 應記在借方,卻過到貸方:應收帳款餘額應為借$3,000 卻變成貸$3,000,借方少了$3,000 還多了貸方$3,000,差距為 2×$3,000=$6,000,所以借方合計少了$6,000。", "同理銷貨收入應貸$3,000,卻過到借方,貸方少了$6,000。", "所以正確合計數要「借方、貸方總額各加$6,000」。"], "pitfalls": "過錯方向的差距是 2 倍金額,不是 1 倍。", "distractors": {"A": "把兩個錯誤金額加起來再各減,觀念錯誤。", "B": "借貸方向調反,且變成借貸不平衡。", "C": "只考慮 1 倍金額,忘了方向相反差 2 倍。"}}, "check": "python: 方向相反的差額=2*3000=6000;①無影響;借貸各加6000,與答案相符。", "verified": true, "note": ""}, {"id": "114-1-A-18", "exam": "114-1", "paper": "A", "q": 18, "unit": "七、調整", "topic": "調整與錯誤影響", "stem": "大銘是晶晶公司的會計人員,他正在進行調整程序、計算並判斷錯誤造成的影響,下列敘述何者錯誤?", "options": ["公司 01/7/1 購買辦公設備,買價$200,000,另支付運費(起運點交貨)$2,000、安裝費$8,000,預計可使用 10 年,殘值$20,000,按直線法提列折舊,05 年初辦公設備的帳面金額為$143,500", "「應收帳款」年初餘額$100,000、「備抵損失-應收帳款」$1,500,本年底「應收帳款」餘額$180,000,當年度確定無法收回之帳款$28,000,去年已沖銷的帳款於今年收回$5,000。損失率與去年底相同,則年底應提列之預期信用減損損失金額為$29,200", "採聯合基礎,本年年中已支付一年期租金,本年年底漏作預付租金之調整分錄,則本期淨利低估", "本年初修繕費誤記為機器成本,則下年度淨利低估"], "answer": "B", "figure": null, "official": "(B) 損失率=$1,500÷$100,000×100%=1.5%,年底應有備抵損失為$180,000×1.5%=$2,700,年初$1,500+收回$5,000−沖銷$28,000+年底提列=$2,700,年底提列$24,200。", "explain": {"concept": "考折舊帳面金額、備抵損失 T 字帳推算,以及錯誤對淨利的影響。", "steps": ["(A) 成本=200,000+2,000+8,000=$210,000;每年折舊=(210,000−20,000)÷10=$19,000。01/7/1~04/12/31 共 3.5 年,累計折舊=$66,500;帳面金額=210,000−66,500=$143,500,正確。(官方算式 $200,000+2,000+8,000−20,000 同。)", "(B) 損失率=1,500÷100,000=1.5%;年底備抵損失應有餘額=180,000×1.5%=$2,700。", "備抵損失 T 字帳:期初貸$1,500+已沖銷收回貸$5,000−沖銷借$28,000+本期提列=期末貸$2,700,所以提列=2,700−1,500−5,000+28,000=$24,200,不是$29,200,所以 (B) 錯。", "(C) 已付租金記費用(聯合基礎)但未調整預付租金,費用多計,淨利低估,正確。", "(D) 修繕費誤記為機器成本,本年費用少計(淨利高估),下年度折舊多計,淨利低估,正確。"], "pitfalls": "備抵損失:收回已沖銷要先加回,再與沖銷對沖,最後算補提。", "distractors": {"A": "此敘述正確。", "C": "此敘述正確。", "D": "此敘述正確。"}}, "check": "python: 提列=2700-(1500+5000-28000)=24200;累折=(210000-20000)/10*3.5=66500;帳面=143500。B 的 29,200 不等於 24,200,B 敘述錯誤,與答案相符。", "verified": true, "note": "此題橫跨折舊、備抵損失、調整錯誤影響,單元歸類可歸七或十二/十五。"}, {"id": "114-1-A-19", "exam": "114-1", "paper": "A", "q": 19, "unit": "八、結帳", "topic": "結帳敘述", "stem": "有關結帳的敘述,下列何者正確?", "options": ["買賣業的結帳採本期損益法,商品帳戶結帳後,本期損益若有貸餘,表示有營業毛利", "結帳後試算表會出現「利息費用」的金額", "某公司課稅所得額(P) $200,000,按現行《所得稅法》,免徵營利事業所得稅", "結帳採銷貨成本法時,銷貨成本相關帳戶包括「運費」這個會計項目"], "answer": "A", "figure": null, "official": "(B) 結帳後試算表只有實帳戶,不會出現虛帳戶;(C) 營利事業所得稅起徵額及稅率:P在$120,000以下免徵;$120,000<P≤$200,000,T=(P−$120,000)×1/2;P超過$200,000,T=P×20%;P=$200,000 應納稅額=($200,000−$120,000)×1/2=$40,000;(D)「運費」屬營業費用,不是銷貨成本相關帳戶。", "explain": {"concept": "考買賣業結帳(本期損益法)、結帳後試算表、營所稅速算、銷貨成本相關帳戶。", "steps": ["(A) 本期損益法下,商品相關帳戶(進貨、存貨、銷貨成本等)結入「本期損益」,結帳後本期損益若有貸餘,代表銷貨收入大於銷貨成本,即有營業毛利,正確。", "(B) 結帳後試算表只剩實帳戶,利息費用是虛帳戶,不會出現。", "(C) 課稅所得額$200,000 落在$120,000~$200,000 區間,要課稅:($200,000−$120,000)×1/2=$40,000,不是免稅。", "(D) 運費(銷貨運費)是營業費用,不屬於銷貨成本相關帳戶。"], "pitfalls": "結帳後試算表只有實帳戶;所得稅各區間公式要記得。", "distractors": {"B": "誤以為虛帳戶結帳後仍有餘額。", "C": "忘了$120,000以上就要課稅。", "D": "把運費當成銷貨成本的一部分。"}}, "check": "python: 營所稅(200000-120000)*0.5=40000>0,故C錯;其餘依官方詳解,A正確。", "verified": true, "note": ""}, {"id": "114-1-A-20", "exam": "114-1", "paper": "A", "q": 20, "unit": "九、財務報表", "topic": "財務報表敘述", "stem": "下列敘述何者正確?", "options": ["所得稅費用會出現於獨資企業的綜合損益表", "資產負債表是表達特定期間的財務狀況", "公開發行公司的財務報表須經會計師查核簽證", "租金支出漏記,僅影響綜合損益表的正確性"], "answer": "C", "figure": null, "official": "(A) 獨資或合夥企業須辦理營利事業所得稅結算申報,但無須繳納營利事業所得稅,而是將其所得列入個人營利所得,申報個人綜合所得稅;(B) 資產負債表是表達特定日期的財務狀況;(D) 綜合損益表費損少計,淨利多計,資產負債表的權益也會多計。", "explain": {"concept": "考不同企業組織的所得稅處理、報表表達的時間基礎、報表查核及漏記費用的影響。", "steps": ["(A) 獨資企業不繳營利事業所得稅(所得併入業主個人綜合所得稅),所以綜合損益表沒有所得稅費用。", "(B) 資產負債表表達的是「特定日期」的財務狀況,綜合損益表才是「特定期間」。", "(C) 公開發行公司財報須經會計師查核簽證,正確。", "(D) 租金支出漏記→費用少計→淨利多計→權益(保留盈餘)多計,連資產負債表也受影響。"], "pitfalls": "資產負債表看「日期」、損益表看「期間」。", "distractors": {"A": "忘了獨資不繳營所稅。", "B": "把「特定日期」誤為「特定期間」。", "D": "漏記費用會影響淨利、進而影響權益。"}}, "check": "概念題:對照官方詳解,(C)正確。", "verified": true, "note": ""}, {"id": "114-1-A-21", "exam": "114-1", "paper": "A", "q": 21, "unit": "九、財務報表", "topic": "買賣業損益項目", "stem": "下列何者不屬於買賣業的損益項目?", "options": ["進貨時所支付的營業稅", "無形資產所作的成本分攤", "購買運輸設備試車時的超速罰單", "定期盤存制下現購商品,交貨條件為起運點交貨之運費"], "answer": "A", "figure": null, "official": "進貨時所支付的營業稅為進項稅額,屬於資產。", "explain": {"concept": "分辨哪些支出是費用(損益項目),哪些是資產(進項稅額)。", "steps": ["(A) 進貨時支付的營業稅是「進項稅額」(可扣抵銷項稅額),屬資產,不是損益項目,是答案。", "(B) 無形資產攤銷是費用,屬損益項目。", "(C) 超速罰單是罰款支出(費損),屬損益項目。", "(D) 定期盤存制下起運點交貨的運費記「進貨運費」,是進貨成本的一部分,最終影響銷貨成本,屬損益項目。"], "pitfalls": "可扣抵的進項稅額是資產,不是費用。", "distractors": {"B": "攤銷屬於費用,是損益項目。", "C": "罰單屬於費損(罰款支出)。", "D": "進貨費用最終轉入銷貨成本,屬於損益項目。"}}, "check": "概念題:對照官方詳解,進項稅額為資產,(A)不屬於損益項目。", "verified": true, "note": ""}, {"id": "114-1-A-22", "exam": "114-1", "paper": "A", "q": 22, "unit": "十三、存貨", "topic": "可售商品總額", "stem": "芯芯商店 01 年度有關商品帳戶資料如下:\n\n| 項目 | 金額 | 項目 | 金額 | 項目 | 金額 |\n|---|---|---|---|---|---|\n| 進貨 | $230,000 | 銷貨淨額 | $360,000 | 進貨費用 | $9,000 |\n| 進貨折讓 | $5,000 | 期末存貨 | $24,000 | | |\n\n假設毛利率為 30%,則 01 年度的可售商品總額為多少?", "options": ["$204,000", "$228,000", "$276,000", "$280,000"], "answer": "C", "figure": null, "official": "銷貨成本=$360,000×(1−30%)=$252,000;可售商品總額=$252,000+$24,000=$276,000。", "explain": {"concept": "毛利率=毛利÷銷貨淨額,所以銷貨成本=銷貨淨額×(1−毛利率);可售商品總額=銷貨成本+期末存貨。", "steps": ["毛利率30%,表示銷貨成本占銷貨淨額 70%。", "銷貨成本=$360,000×(1−30%)=$252,000。", "銷貨成本=可售商品總額−期末存貨,所以可售商品總額=銷貨成本+期末存貨=$252,000+$24,000=$276,000。", "進貨、進貨費用、進貨折讓是干擾資料,因為已經給了毛利率,可直接推算。"], "pitfalls": "不要被進貨、進貨折讓等數字帶偏,公式一步到位。", "distractors": {"B": "把期末存貨減掉($252,000−$24,000=$228,000),加減方向弄反。"}}, "check": "python: 360000*0.7=252000; +24000=276000,與答案相符。", "verified": true, "note": ""}, {"id": "114-1-A-23", "exam": "114-1", "paper": "A", "q": 23, "unit": "十、加值型營業稅會計實務", "topic": "營業稅法規", "stem": "下列敘述何者正確?", "options": ["銷售貨物給一般消費者,所開立的收銀機發票種類及稅額情形為二聯式統一發票,營業稅外加", "我國《加值型及非加值型營業稅法》規定,出售土地,免徵營業稅", "營業人適用免稅的銷售貨物或勞務不用繳納銷項稅額,其銷售貨物或勞務所支付的進項稅額可扣抵或退稅", "「不可扣抵的進項稅額」是指不須繳交進項稅額"], "answer": "B", "figure": null, "official": "(A) 銷售貨物給一般消費者,所開立的收銀機發票種類及稅額情形為二聯式統一發票,營業稅內含;(C) 營業人適用免稅的銷售貨物或勞務不用繳納銷項稅額,所支付的進項稅額不得扣抵或退稅;(D)「不可扣抵的進項稅額」是指仍需繳交進項稅額,但不得扣抵銷項稅額。", "explain": {"concept": "考發票種類與稅額含/外加、免稅項目、進項稅額扣抵規定。", "steps": ["(A) 賣給一般消費者(非營業人)開二聯式,營業稅「內含」,不是外加。", "(B) 土地出售免徵營業稅(土地不是營業稅課稅對象的免稅項目),正確。", "(C) 免稅的營業人不用收銷項稅額,所以進項稅額「不得」扣抵或退稅。", "(D) 不可扣抵進項稅額,是「仍然要付給賣方」,只是不能抵銷項稅額。"], "pitfalls": "二聯式=稅額內含;三聯式=稅額外加。免稅→進項不能扣抵。", "distractors": {"A": "二聯式發票營業稅是內含,不是外加。", "C": "免稅營業人的進項稅額不得扣抵或退稅。", "D": "不可扣抵仍須支付,只是不能扣抵銷項稅額。"}}, "check": "概念題:對照官方詳解與營業稅法常識,(B)正確。", "verified": true, "note": ""}, {"id": "114-1-A-24", "exam": "114-1", "paper": "A", "q": 24, "unit": "十、加值型營業稅會計實務", "topic": "營業稅會計項目與稅率", "stem": "有關加值型營業稅及其使用的會計項目分類的敘述,下列何者正確?", "options": ["應收退稅款、銷項稅額均為流動資產的會計項目", "應付營業稅、留抵稅額均為流動負債的會計項目", "加值型營業稅之稅率一律為 5%", "加值型營業稅對外銷貨物或勞務適用稅率為 0%"], "answer": "D", "figure": null, "official": "(A) 應收退稅款為流動資產、銷項稅額為流動負債;(B) 應付營業稅為流動負債、留抵稅額為流動資產;(C) 加值型營業稅之稅率有一般 5%、零稅率 0%及免稅。", "explain": {"concept": "營業稅會計科目的分類(資產或負債)及稅率類型。", "steps": ["進項稅額、留抵稅額、應收退稅款→流動資產;銷項稅額、應付營業稅→流動負債。", "(A) 銷項稅額是負債,不是資產,錯。", "(B) 留抵稅額是資產,不是負債,錯。", "(C) 稅率有一般 5%、零稅率 0%(例如外銷)及免稅,不是一律 5%,錯。", "(D) 外銷適用零稅率 0%,正確。"], "pitfalls": "進項→資產;銷項→負債;「一律」又是絕對字眼。", "distractors": {"A": "把銷項稅額誤當成資產。", "B": "把留抵稅額誤當成負債。", "C": "忘了零稅率與免稅。"}}, "check": "概念題:對照官方詳解,(D)正確。", "verified": true, "note": ""}, {"id": "114-1-A-25", "exam": "114-1", "paper": "A", "q": 25, "unit": "十、加值型營業稅會計實務", "topic": "營業稅申報書(401)", "stem": "信信公司為適用一般稅率之加值型營業人,自 114 年 5 月開始營業,114 年 5 月及 6 月銷貨及進貨資料如下表(表中各項金額皆為未含稅):\n\n| 銷項 | 金額 | 進項 | 金額 | 進、銷項扣抵聯種類 |\n|---|---|---|---|---|\n| 內銷 | $300,000 | 進貨 | $250,000 | 統一發票 |\n| 外銷 | $150,000 | 費用 | $50,000 | 三聯式收銀機發票 |\n| 銷貨退回及折讓(內銷) | $25,000 | 載貨用卡車 | $100,000 | 統一發票 |\n\n信信公司填具 114 年 5-6 月營業人銷售額與稅額申報書(401),下列何者正確?\n\n(A) 銷項:\n\n| 項目 | 應稅銷售額 | 應稅稅額 | 零稅率銷貨額 |\n|---|---|---|---|\n| 三聯式發票 | 300,000 | 15,000 | 150,000 |\n| 減:退回及折讓 | 25,000 | 1,250 | 0 |\n| 合計 | 275,000 | 13,750 | 150,000 |\n\n(B) 進項:\n\n| 項目 | 類別 | 金額 | 稅額 |\n|---|---|---|---|\n| 三聯式收銀機發票 | 進貨及費用 | 300,000 | 15,000 |\n| 三聯式收銀機發票 | 固定資產 | 100,000 | 5,000 |\n\n(C) 稅額計算:\n\n| 代號 | 項目 | 稅額 |\n|---|---|---|\n| 1 | 本期(月)銷項稅額合計 | 13,750 |\n| 7 | 得扣抵進項稅額合計 | 17,500 |\n\n(D) 稅額計算:\n\n| 代號 | 項目 | 稅額 |\n|---|---|---|\n| 13 | 得退稅限額合計 | 12,500 |\n| 14 | 本期(月)應退稅額 | 12,500 |", "options": ["銷項申報(A)", "進項申報(B)", "稅額計算(C)", "稅額計算(D)"], "answer": "A", "figure": null, "official": "答案表為 A。詳解:進項為統一發票 進貨及費用$250,000/稅$12,500、固定資產$100,000/$5,000;三聯式收銀機發票進貨及費用$50,000/$2,500;得扣抵進項稅額合計$20,000(非$17,500);本期應申報留抵稅額$6,250;得退稅限額=$150,000×5%+$5,000=$12,500,但應退稅額為 0 /留抵$6,250,(D)錯誤。", "explain": {"concept": "401 申報書:銷項稅額、進項稅額(依發票種類與是否固定資產分列)、零稅率退稅限額與留抵稅額計算。", "steps": ["銷項稅額:內銷$300,000×5%=$15,000;銷貨退回$25,000×5%=$1,250,所以淨銷項稅額=$13,750;外銷零稅率,銷售額$150,000,稅額 0。(A) 與此相符。", "進項稅額:統一發票進貨及費用$250,000×5%=$12,500、固定資產$100,000×5%=$5,000;收銀機發票費用$50,000×5%=$2,500;合計得扣抵進項稅額=$12,500+$5,000+$2,500=$20,000。", "(B) 進項分類錯(把$300,000 全歸收銀機發票)。", "(C) 得扣抵進項稅額合計應為$20,000,不是$17,500。", "(D) 本期銷項$13,750<進項$20,000,留抵稅額=$6,250;得退稅限額=外銷$150,000×5%+固定資產進項$5,000=$12,500,但實際應退稅額是留抵$6,250 與限額取小,為$6,250,不是$12,500。", "所以只有 (A) 正確。"], "pitfalls": "進項稅額要依發票種類與固定資產分開;應退稅額=min(留抵稅額, 退稅限額)。", "distractors": {"B": "進項發票種類及金額分類錯。", "C": "進項稅額合計少算(應為$20,000)。", "D": "應退稅額應取留抵$6,250 與退稅限額$12,500 的較小者。"}}, "check": "python: 銷項=300000*.05-25000*.05=13750; 進項=(250000+100000)*.05+50000*.05=20000; 留抵=6250; 限額=150000*.05+5000=12500; 應退=min(6250,12500)=6250。A 正確,與答案表相符。", "verified": true, "note": "官方詳解頁寫「25.(B)」,但該段是在說明 B 選項錯誤並列出正確進項表;答案表第 25 題為 A,依答案表。"}, {"id": "114-2-A-01", "exam": "114-2", "paper": "A", "q": 1, "unit": "一、會計基本概念", "topic": "會計種類與法令位階", "stem": "老歐、老洵、小軾、小轍共同出資成立一間非公開發行股份有限公司,經營各項公共工程建設。公司會計人員美琪剛從大學畢業,由於工作經驗不足在處理會計事務時,應先適用哪一些法令及準則位階常搞不清楚,所以公司四位前輩給美琪的建議,有關公司採用之會計種類及適用位階的順序,下列何者正確?", "options": ["老歐:本公司為「收支會計」,適用位階順序:證券交易法>商業會計處理準則>企業會計準則", "老洵:本公司為「商業會計」,適用位階順序:公司法>商業會計處理準則>企業會計準則", "小軾:本公司為「營利會計」,適用位階順序:商業會計處理準則>商業會計法>金管會認可之 IFRSs", "小轍:本公司為「營利會計」,適用位階順序:金管會認可之 IFRSs>商業會計法>商業會計處理準則"], "answer": "B", "figure": null, "official": "非公開發行公司適用「商業會計」、「營利會計」,法令及準則先後順序為:公司法、商業會計法(法律)→商業會計處理準則(行政命令)→企業會計準則(GAAP)。", "explain": {"concept": "考會計種類(營利會計)以及非公開發行公司適用的法令位階:法律>行政命令>會計準則。", "steps": ["先判斷公司性質:股份有限公司以營利為目的,所以是「營利會計」(也叫商業會計),不是政府或非營利機構用的收支會計。又是「非公開發行」,不必適用證券交易法。", "再看位階:法律最大。公司法、商業會計法都是法律,位階最高;其次是行政命令「商業會計處理準則」;最後才是「企業會計準則(GAAP)」。", "所以順序是 公司法、商業會計法 > 商業會計處理準則 > 企業會計準則。", "逐項比對:A 說是收支會計且套用證券交易法,錯;C 把行政命令放在法律前面,錯;D 的 IFRSs 是公開發行公司才強制適用,且放在最前面,也錯;只有 B 符合。"], "pitfalls": "容易把「商業會計處理準則」放在「商業會計法」前面,或忘記法律位階高於行政命令。", "distractors": {"A": "以為民營公司是收支會計,又誤用公開發行公司才適用的證券交易法。", "C": "把行政命令(處理準則)排在法律(商業會計法)之前,位階顛倒。", "D": "把公開發行公司適用的 IFRSs 當成最優先,且未把公司法放最前面。"}}, "check": "概念題:對照官方詳解與商業會計法位階(法律>行政命令>準則),B 正確。", "verified": true, "note": ""}, {"id": "114-2-A-02", "exam": "114-2", "paper": "A", "q": 2, "unit": "二、會計循環及會計帳簿", "topic": "會計處理程序與帳簿", "stem": "一般會計處理程序與營業循環,下列敘述哪幾項正確?\n①序時帳簿係按交易發生順序,以第四級會計項目記錄之帳簿\n②過帳係將分類帳的餘額抄入試算表的程序\n③試算係表達本期營業結果之程序\n④調整係於結帳前將各帳戶加以整理、修正,使其帳面金額能與實際情況相符\n⑤依《商業會計法》規定,商業必須設置之會計帳簿為特種序時帳簿及總分類帳簿\n⑥營業循環是由現金、進貨、銷貨,再回至現金之循環,其所需時間稱營業週期", "options": ["①②③", "①③⑥", "①④⑥", "③⑤⑥"], "answer": "C", "figure": null, "official": "②過帳是將日記簿各分錄的會計項目及金額,按原來借貸方向及金額,分別記至各會計項目所設之帳戶;③試算是將分類帳各帳戶金額彙總列表,確認是否平衡;⑤商業必須設置的是普通序時帳簿及總分類帳簿。", "explain": {"concept": "考會計處理程序各步驟(過帳、試算、調整)的定義,以及商業會計法規定必須設置的帳簿。", "steps": ["①序時帳簿(日記簿)按日期先後記錄分錄,用第四級會計項目,正確。", "②過帳是把「日記簿的分錄」抄到「分類帳」各帳戶,不是把分類帳餘額抄入試算表(那是試算),所以②錯。", "③試算是檢查借貸是否平衡,不是表達營業結果(營業結果是綜合損益表),所以③錯。", "④調整是在結帳前把帳戶金額整理到符合實際,正確。", "⑤商業會計法規定必須設置「普通序時帳簿」與「總分類帳簿」,特種序時帳簿是可以視需要設置,所以⑤錯。", "⑥營業循環:現金→進貨→銷貨→再收回現金,這段時間叫營業週期,正確。", "正確的是①④⑥,選 C。"], "pitfalls": "②與③很像,常把「過帳」「試算」功能搞混;⑤容易把「普通」看成「特種」。", "distractors": {"A": "認為②③正確,混淆了過帳與試算的意義。", "B": "誤認③(試算)可表達營業結果。", "D": "③⑤皆錯,且漏掉正確的①④。"}}, "check": "逐項判斷:①④⑥正確,與官方答案 C 一致。", "verified": true, "note": ""}, {"id": "114-2-A-03", "exam": "114-2", "paper": "A", "q": 3, "unit": "一、會計基本概念", "topic": "會計假設與基礎", "stem": "下列敘述何者錯誤?", "options": ["根據「財務報導之觀念架構」,財務報表的基本假設是繼續經營假設", "商店代墊老闆自用的電話費仍需記帳,但不列為商店之費用,是依據應計基礎", "交易應於發生時予以認列,而不是現金收付時,是依據應計基礎", "資產之評價及成本攤分的理論基礎是繼續經營假設"], "answer": "B", "figure": null, "official": "(B)是依據「企業個體假設」。", "explain": {"concept": "考會計基本假設:企業個體、繼續經營、會計期間、貨幣單位,以及應計基礎。", "steps": ["先分清楚:應計基礎=「交易發生時就認列,不等收付現金」。企業個體假設=「企業與業主要分開記帳」。", "B 說代墊老闆私人電話費要記帳但不算商店費用,重點是商店與業主分開,這是「企業個體假設」,不是應計基礎,所以 B 敘述錯誤。", "C 交易發生時認列,正是應計基礎,正確。", "A、D:繼續經營假設是假設企業會持續營運,所以資產可以用成本評價、分攤(折舊),正確。", "題目問「錯誤」,答案選 B。"], "pitfalls": "題目問錯誤的,要選「敘述不對」的那個,別被正確的選項帶走。", "distractors": {"A": "此敘述是正確的(繼續經營是基本假設),不是答案。", "C": "此敘述是正確的(應計基礎),不是答案。", "D": "此敘述是正確的(繼續經營假設),不是答案。"}}, "check": "概念題:對照官方詳解,B 屬企業個體假設,答案 B。", "verified": true, "note": ""}, {"id": "114-2-A-04", "exam": "114-2", "paper": "A", "q": 4, "unit": "九、財務報表", "topic": "資產負債表項目分類", "stem": "阿涵、阿玲、阿漢、阿步四人,正在圖書館準備會計檢定,他們要將以下第四級會計項目分類為第三級會計項目後編製資產負債表,下列哪一人分類正確?\n\n| ①代付款 | ⑤應收票據折價 | ⑨預收租金 | ⑬暫付款 |\n|---|---|---|---|\n| ②銷項稅額 | ⑥應付公司債 | ⑩累計折舊 | ⑭專利權 |\n| ③暫收款 | ⑦應收票據貼現負債 | ⑪存入保證金 | ⑮償債基金 |\n| ④預付貨款 | ⑧存出保證金 | ⑫銀行透支 | ⑯代收款 |", "options": ["阿涵說:合約負債有④⑨⑫;其他應付款有②⑥", "阿玲說:應收票據有⑤⑦;其他流動資產有③⑯", "阿漢說:其他流動負債有①⑬;不動產、廠房及設備有⑩⑭", "阿步說:其他非流動資產有⑧⑮;其他非流動負債有⑪"], "answer": "D", "figure": null, "official": "依官方分類:應收票據⑤;預付款項④;其他流動資產①⑬;不動產廠房及設備⑩;無形資產⑭;其他非流動資產⑧⑮;短期借款⑫;合約負債⑨;其他應付款②;其他流動負債③⑦⑯;應付公司債⑥;其他非流動負債⑪。", "explain": {"concept": "考資產負債表第三級項目的歸類(要先看這個科目是資產還是負債、流動還是非流動)。", "steps": ["先把16個科目各歸到資產/負債與流動/非流動。", "資產面:⑤應收票據折價→應收票據(抵減);④預付貨款→預付款項;①代付款、⑬暫付款→其他流動資產;⑩累計折舊→不動產、廠房及設備;⑭專利權→無形資產;⑧存出保證金、⑮償債基金→其他非流動資產。", "負債面:⑫銀行透支→短期借款;⑨預收租金→合約負債;②銷項稅額→其他應付款;③暫收款、⑦應收票據貼現負債、⑯代收款→其他流動負債;⑥應付公司債→應付公司債;⑪存入保證金→其他非流動負債。", "逐位檢查:阿涵把④預付貨款放負債、⑫放合約負債,錯;阿玲把⑦放應收票據、③⑯放資產,錯;阿漢把⑭專利權放不動產廠房,且①⑬是資產,錯;阿步「其他非流動資產⑧⑮;其他非流動負債⑪」完全正確。", "所以選 D。"], "pitfalls": "預付貨款是資產、預收租金才是負債(合約負債);暫收款、代收款是負債,暫付款、代付款是資產。", "distractors": {"A": "④預付貨款是資產(預付款項),⑫銀行透支是短期借款,⑥應付公司債是非流動負債。", "B": "⑦應收票據貼現負債屬負債(其他流動負債);③暫收款、⑯代收款是負債,不是資產。", "C": "①代付款、⑬暫付款是資產(其他流動資產),⑭專利權是無形資產,不是不動產廠房及設備。"}}, "check": "概念題:逐科目比對官方詳解之分類表,D 正確。", "verified": true, "note": "官方分類表中 ⑩累計折舊歸入不動產、廠房及設備(抵減項)。"}, {"id": "114-2-A-05", "exam": "114-2", "paper": "A", "q": 5, "unit": "一、會計基本概念", "topic": "會計恆等式", "stem": "彰化商店 X1 年初資產總額是負債總額 2 倍少$6,000,淨值則為負債的三分之一。若 X1 年中本店曾代業主支付其私人住宅之租金,X1 年度收益$100,000,費損$50,000,已知 X1 年底彰化商店的資產總額是負債總額 2.5 倍少$9,000,淨值比負債多$10,000,則業主私人住宅租金為何?", "options": ["$5,000", "$6,000", "$7,000", "$8,000"], "answer": "A", "figure": null, "official": "期初:A=2L-6,000,C=L/3,得L=9,000,A=12,000,C=3,000。期末:A=2.5L-9,000,C=L+10,000,得L=38,000,C=48,000。48,000=3,000+(100,000-50,000)-代付租金,代付租金=$5,000。", "explain": {"concept": "用會計恆等式 資產=負債+業主權益,先求期初、期末權益,再用「期末權益=期初權益+淨利-業主提取」求出業主提取(代付私人租金)。", "steps": ["期初:設負債為 L,資產 A=2L-6,000,權益 C=L/3。恆等式 A=L+C,所以 2L-6,000=L+L/3,整理 (2/3)L=6,000,得 L=9,000。", "期初權益 C=9,000÷3=$3,000(此時資產=12,000)。", "期末:A=2.5L-9,000,C=L+10,000。代入 A=L+C:2.5L-9,000=L+L+10,000,0.5L=19,000,L=38,000。", "期末權益 C=38,000+10,000=$48,000。", "本期淨利=收益-費損=100,000-50,000=$50,000。", "權益變動:期末權益=期初權益+淨利-業主提取,48,000=3,000+50,000-提取,提取=$5,000。", "代業主支付私人租金就是業主提取(借:業主往來),所以租金為 $5,000,選 A。"], "pitfalls": "容易忘記「代付私人租金」要從權益扣掉(是業主提取,不是店的費用)。", "distractors": {"B": "可能把期初權益或提取的計算多算了 $1,000,算錯方程式。", "C": "計算過程中符號或係數誤差,未用 期末權益=期初權益+淨利-提取。", "D": "同上,代入數字時算錯。"}}, "check": "python:期初L=9,000、A=12,000、C=3,000;期末L=38,000、A=86,000、C=48,000;提取=3,000+50,000-48,000=5,000,與官方 A 相符。", "verified": true, "note": ""}, {"id": "114-2-A-06", "exam": "114-2", "paper": "A", "q": 6, "unit": "二、會計循環及會計帳簿", "topic": "憑證種類與保存", "stem": "下列敘述何者正確?", "options": ["員工出差支付計程車費所填寫之支出證明單屬於記帳憑證,應至少保存 5 年", "顧客開來的訂購單是對外憑證;發給供貨商的訂購單是外來憑證", "記帳憑證是用以證明會計人員責任的憑證", "複式傳票制度下,每一個會計項目編製一張傳票"], "answer": "C", "figure": null, "official": "(A)支出證明單是用來取代外來憑證之原始憑證;(B)顧客開來的訂購單是外來憑證,發給供貨商的訂購單是對外憑證;(D)複式傳票制度下,每一筆交易編製一張傳票。", "explain": {"concept": "考憑證分類(原始憑證/記帳憑證、外來/對外/內部)與傳票制度。", "steps": ["先分兩大類:原始憑證(證明交易發生)與記帳憑證(證明會計人員記帳責任)。", "A:支出證明單是取代外來憑證的「原始憑證」,不是記帳憑證,錯。", "B:別人給我們的是「外來」,我們開給別人的是「對外」。顧客開來的訂購單=外來;我們發給供貨商的=對外。B 說反了,錯。", "D:複式傳票是「一筆交易一張傳票」,單式傳票才是「一個會計項目一張」,錯。", "C:記帳憑證是會計人員據以記帳,用以證明會計人員責任,正確,選 C。"], "pitfalls": "外來與對外容易顛倒;複式與單式傳票容易搞混。", "distractors": {"A": "把支出證明單誤認為記帳憑證,實際是原始憑證。", "B": "外來/對外方向顛倒。", "D": "把單式傳票(一項目一張)的規則套到複式傳票。"}}, "check": "概念題:對照官方詳解與商業會計法對憑證之分類,C 正確。", "verified": true, "note": ""}, {"id": "114-2-A-07", "exam": "114-2", "paper": "A", "q": 7, "unit": "二、會計循環及會計帳簿", "topic": "複式傳票四分法與三分法", "stem": "下列敘述何者正確?", "options": ["企業以現金支付租金$80,000,其中四分之一屬於業主私人應負擔,則複式傳票四分法應編製分錄轉帳傳票", "收到顧客交來已承兌匯票,則複式傳票四分法應編製分錄轉帳傳票", "在折扣期限內以現金支付貨款,採總額法處理現金折扣,則複式傳票三分法應編製現金支出傳票", "與客戶簽訂銷售契約,則複式傳票三分法應編製現金收入傳票"], "answer": "B", "figure": null, "official": "(A)應編製現金支出傳票;(C)應編製轉帳傳票(借:應付帳款,貸:進貨折讓、現金);(D)簽訂契約屬非交易,不作分錄。", "explain": {"concept": "考傳票的選擇:四分法(現金收入、現金支出、分錄轉帳、…);三分法(現金收入、現金支出、轉帳)。", "steps": ["先記規則:四分法中,收付現金且「全部」是現金的,用現金收入/支出傳票;不涉及現金用「分錄轉帳」;部分現金部分轉帳用「現金傳票+分錄轉帳」。", "A:分錄為借租金支出60,000、業主往來20,000,貸現金80,000,全額涉及現金→編現金支出傳票,A 錯。", "B:應收票據/應收帳款,完全不涉及現金→分錄轉帳傳票,正確。", "C:付款時分錄為借應付帳款、貸進貨折扣、現金,三分法中涉及現金部分與轉帳混合,需拆開來,不是單純現金支出傳票,錯。", "D:簽訂契約不是會計交易(未使財務要素增減變動),不作分錄,也無傳票,錯。", "選 B。"], "pitfalls": "簽約不是交易;分錄中只要有現金就會牽涉到現金傳票。", "distractors": {"A": "有現金支出就得用現金支出傳票,不是分錄轉帳傳票。", "C": "總額法折扣屬轉帳與現金混合,不是單純現金支出傳票。", "D": "簽約屬非交易,不會編製任何傳票。"}}, "check": "概念題:B 與官方詳解一致。", "verified": true, "note": ""}, {"id": "114-2-A-08", "exam": "114-2", "paper": "A", "q": 8, "unit": "五、過帳與分類帳", "topic": "帳簿特性與過帳", "stem": "下列敘述何者錯誤?", "options": ["分類帳係以交易為主體之帳簿", "統制帳的「餘額」,必定等於各明細帳「餘額」之和", "統制帳的「借餘」,不一定等於各借餘明細帳之和", "過帳時互記日記簿頁次與分類帳頁次,可避免漏記或重複過帳的錯誤"], "answer": "A", "figure": null, "official": "(A)分類帳係以會計項目為主體之帳簿。", "explain": {"concept": "考日記簿與分類帳的差別、統制帳與明細帳的關係。", "steps": ["日記簿以「交易」為主體(按日期先後記);分類帳以「會計項目(帳戶)」為主體。A 把兩者混淆,所以 A 錯。", "B:統制帳(總帳)的餘額=各明細帳餘額合計,正確。", "C:同一統制帳下,各明細帳可能有借餘也有貸餘,所以統制帳「借餘」不一定等於各「借餘」明細帳的合計,正確。", "D:過帳時在日記簿註記分類帳頁次、分類帳註記日記簿頁次(過帳備註),方便查對,避免漏記與重複過帳,正確。", "題目問錯誤,選 A。"], "pitfalls": "B、C 看似矛盾,其實 B 看「淨餘額」,C 看「只算借餘的明細帳」,要看清楚。", "distractors": {"B": "此敘述正確,不是答案。", "C": "此敘述正確,不是答案。", "D": "此敘述正確,不是答案。"}}, "check": "概念題:A 錯誤與官方一致。", "verified": true, "note": ""}, {"id": "114-2-A-09", "exam": "114-2", "paper": "A", "q": 9, "unit": "六、試算與試算表", "topic": "試算與錯誤更正", "stem": "有關試算的敘述,下列何者正確?", "options": ["借貸雙方皆重複過帳時,將會影響試算表借貸平衡", "餘額式試算表依據原理為「等量加等量其和必相等」", "企業經營發生淨損,試算表會產生借貸不平衡", "不影響借貸平衡的錯誤,若會影響總數且已過帳,則發現時應採分錄更正法"], "answer": "D", "figure": null, "official": "(A)借貸雙方皆重複過帳時,不影響借貸平衡;(B)總額式試算表依據原理為「等量加等量其和必相等」;餘額式試算表依據「等量減等量其差必相等」;(C)企業經營發生淨損,試算表仍然平衡。", "explain": {"concept": "考試算表的原理與錯誤更正方法。", "steps": ["A:借方和貸方都重複過帳,借貸等額增加,試算表仍平衡,A 錯。", "B:總額式試算表依「等量加等量其和必相等」;餘額式依「等量減等量其差必相等」,所以 B 把兩者弄反,錯。", "C:虧損只是帳戶餘額改變,借貸仍相等,試算表還是平衡,C 錯。", "D:錯誤若不影響借貸平衡(例如記錯科目)、且影響總數並已過帳,用「分錄更正法」(補作更正分錄)來更正,正確。", "選 D。"], "pitfalls": "試算表平衡≠沒有錯誤;很多錯誤試算表查不出來。", "distractors": {"A": "以為重複過帳就會不平衡,但借貸同時重複,仍然平衡。", "B": "總額式與餘額式原理弄反。", "C": "以為虧損會造成不平衡,其實借貸仍相等。"}}, "check": "概念題:D 與官方詳解一致。", "verified": true, "note": ""}, {"id": "114-2-A-10", "exam": "114-2", "paper": "A", "q": 10, "unit": "六、試算與試算表", "topic": "過帳錯誤對試算表影響", "stem": "在過帳時,將貸記:進貨折讓$300,誤記到銷貨折讓的借方,則對餘額式試算表之影響為何?", "options": ["借方少計$300,貸方正確", "借方正確,貸方少計$300", "借方多計$300,貸方少計$300", "借方少計$300,貸方少計$300"], "answer": "C", "figure": null, "official": "正確:進貨折讓貸方餘額 $300(貸方列示$300);錯誤:銷貨折讓借方餘額$300,故借方多計$300,貸方少計$300。", "explain": {"concept": "餘額式試算表只列各帳戶餘額,所以要看錯誤使各帳戶餘額方向如何改變。", "steps": ["正確過帳:進貨折讓貸方記 $300 → 餘額式試算表在「貸方」列示 $300。", "錯誤過帳:把這筆貸方記成銷貨折讓借方 $300 → 銷貨折讓借餘 $300,在「借方」列示 $300。", "與正確相比:借方多出 $300(多計),貸方少了 $300(少計)。", "所以影響為「借方多計$300,貸方少計$300」,選 C(此時借貸差額為 $600,試算表不平衡)。"], "pitfalls": "只要看「試算表上」兩邊各列了多少,不要被科目名稱混淆。", "distractors": {"A": "忽略了銷貨折讓借餘 $300 會使借方多計。", "B": "忽略借方多計 $300。", "D": "借方方向判斷錯誤(以為借方少計)。"}}, "check": "自行推演:借方 +300、貸方 -300,與官方 C 相符。", "verified": true, "note": ""}, {"id": "114-2-A-11", "exam": "114-2", "paper": "A", "q": 11, "unit": "七、調整", "topic": "調整觀念", "stem": "有關調整的敘述,下列何者錯誤?", "options": ["調整後試算表包含實帳戶、虛帳戶及混合帳戶", "混合帳戶一定要調整,但要調整的帳戶不一定是混合帳戶", "調整之目的是為了配合報導期間之劃分,以正確計算損益", "先虛後實法與先實後虛法,會計處理方式不同,但帳務結果相同"], "answer": "A", "figure": null, "official": "(A)調整後試算表不包含混合帳戶。", "explain": {"concept": "考調整的意義、混合帳戶(兼具實帳戶與虛帳戶性質)的處理。", "steps": ["混合帳戶(如預付保險費中同時含有資產與費用性質的帳戶)在期末一定要調整,拆成實帳戶與虛帳戶。", "調整完成後,混合帳戶已被拆成實帳戶與虛帳戶,所以「調整後試算表」只剩實帳戶與虛帳戶,不含混合帳戶。A 錯。", "B:混合帳戶一定要調整;但要調整的帳戶很多(如應計項目)並不一定是混合帳戶,正確。", "C:調整是為了配合會計期間的劃分,正確計算損益,正確。", "D:先虛後實/先實後虛只是記帳方式不同,調整後帳務結果相同,正確。", "題目問錯誤,選 A。"], "pitfalls": "混合帳戶調整前存在,調整後就不存在了。", "distractors": {"B": "此敘述正確,不是答案。", "C": "此敘述正確,不是答案。", "D": "此敘述正確,不是答案。"}}, "check": "概念題:A 錯誤與官方一致。", "verified": true, "note": ""}, {"id": "114-2-A-12", "exam": "114-2", "paper": "A", "q": 12, "unit": "七、調整", "topic": "權責基礎與現金基礎轉換", "stem": "X2 年度權責基礎下之進貨餘額為$53,000,其他資料如下,則 X2 年度現金基礎下之銷貨成本為何?\n\n| 帳戶名稱 | X1 年底餘額 | X2 年底餘額 |\n|---|---|---|\n| 存貨 | $23,000 | $32,000 |\n| 預付貨款 | 31,000 | 28,000 |\n| 預收貨款 | 27,000 | 21,000 |\n| 應付帳款 | 33,000 | 38,000 |", "options": ["$63,000", "$62,000", "$54,000", "$45,000"], "answer": "D", "figure": null, "official": "現金基礎進貨=現金基礎銷貨成本=$53,000+($28,000-$31,000)-($38,000-$33,000)=$45,000。", "explain": {"concept": "權責基礎進貨轉現金基礎:考慮預付貨款(影響現金先付)與應付帳款(尚未付現)的增減;現金基礎沒有存貨,所以進貨即銷貨成本。", "steps": ["現金基礎只看現金收付,不認列存貨;所以「現金基礎銷貨成本」=「現金基礎進貨(付現)」。", "從權責進貨 $53,000 開始調整。預付貨款減少(31,000→28,000)表示本期把以前預付的貨款用掉了,這部分本期沒有付現,所以要「減少」:+(28,000-31,000)=-3,000。", "應付帳款增加(33,000→38,000)表示有 $5,000 的進貨尚未付現,所以也要減少:-(38,000-33,000)=-5,000。", "現金基礎進貨=53,000-3,000-5,000=$45,000。", "存貨與預收貨款屬銷貨/存貨面的資料,此題用不到。答案 D。"], "pitfalls": "一定要判斷「增加」或「減少」對付現的影響方向;存貨在現金基礎下不調整。", "distractors": {}}, "check": "python:53,000+(28,000-31,000)-(38,000-33,000)=45,000,與官方 D 相符。", "verified": true, "note": "存貨與預收貨款為干擾資料。"}, {"id": "114-2-A-13", "exam": "114-2", "paper": "A", "q": 13, "unit": "六、試算與試算表", "topic": "錯誤對損益與保留盈餘影響", "stem": "會計師事務所受客戶委託查公司帳務,發現 X1 年至 X3 年之部分帳務處理錯誤如下,會計師請四位組員幫忙計算錯誤對 X1 至 X3 年度淨利及各年底保留盈餘有何影響,則哪一位組員算出的答案正確?\n\n| | X1 年 | X2 年 | X3 年 |\n|---|---|---|---|\n| 預付佣金 | 高估$100 | — | 高估$220 |\n| 存貨(期末) | 低估 230 | 低估$420 | 低估 130 |\n| 各項攤提 | 高估 30 | 高估 30 | 高估 30 |", "options": ["甲組員:X1 年至 X3 年底保留盈餘依序為低估$160、低估$480、無影響", "乙組員:X1 年至 X3 年底保留盈餘依序為高估$160、高估$480、無影響", "丙組員:X1 年至 X3 年度淨利依序為低估$160、低估$120、低估$480", "丁組員:X1 年至 X3 年度淨利依序為高估$160、高估$120、高估$480"], "answer": "A", "figure": null, "official": "淨利影響:X1 -160、X2 -320、X3 +480;保留盈餘年底:X1 -160、X2 -480、X3 無影響。", "explain": {"concept": "考錯誤對各年度淨利與保留盈餘的影響:預付費用高估→費用少列→淨利高估;期末存貨低估→銷貨成本多列→淨利低估,但次年會迴轉;各項攤提高估→費用多列→淨利低估(不迴轉)。", "steps": ["先定方向。預付佣金高估:資產多列,費用少列,淨利高估;這是遞延項目,下年度費用就補上,所以次年迴轉。", "期末存貨低估:本年銷貨成本多列,淨利低估;下一年的期初存貨也低估,銷貨成本少列,淨利高估(迴轉)。", "各項攤提高估:費用多列,淨利每年都低估$30;它是累積在保留盈餘上,不會自動迴轉。", "X1 年淨利影響=+100(預付)-230(存貨)-30(攤提)=-160(低估$160)。", "X2 年淨利影響=-100(預付迴轉)+230(期初存貨迴轉)-420(期末存貨)-30=-320(低估$320)。", "X3 年淨利影響=+220(預付)+420(期初存貨迴轉)-130(期末存貨)-30=+480(高估$480)。", "保留盈餘年底累計:X1 -160;X2 -160-320=-480;X3 -480+480=0(無影響)。所以甲組員正確(保留盈餘低估160、低估480、無影響),選 A。"], "pitfalls": "要注意迴轉:前一年的錯誤會影響當年淨利,但累計到保留盈餘是「兩年相互抵消」。", "distractors": {"B": "方向反了(把低估看成高估)。", "C": "淨利只算到 X2 為低估$120(漏算迴轉),與實際低估$320 不符。", "D": "淨利方向與數字皆不符。"}}, "check": "python:淨利影響 X1=100-230-30=-160;X2=-100+230-420-30=-320;X3=220+420-130-30=480;累計保留盈餘 -160、-480、0,與官方 A 相符。", "verified": true, "note": ""}, {"id": "114-2-A-14", "exam": "114-2", "paper": "A", "q": 14, "unit": "八、結帳", "topic": "結帳分錄", "stem": "有關結帳的敘述,下列何者正確?", "options": ["結帳分錄主要目的,係將實帳戶結清歸零", "結帳時,銷貨折讓應轉入「本期損益」之貸方", "若發生淨利,公司結帳時應借記:本期損益,貸記:業主往來", "存貨採定期盤存制,商品結帳採銷貨成本法,應借記:存貨(期末)、銷貨成本,貸記:存貨(期初)、進貨"], "answer": "D", "figure": null, "official": "(A)結帳是將虛帳戶結轉到下期;(B)銷貨折讓應轉入本期損益借方;(C)公司結轉本期淨利分錄為借:本期損益,貸:累積盈虧。", "explain": {"concept": "考結帳目的、結帳分錄,以及定期盤存制下的商品結帳(銷貨成本法)。", "steps": ["A:結帳是把「虛帳戶」(收益、費損)結清歸零,實帳戶是結轉到下期,A 錯。", "B:銷貨折讓是銷貨收入的減項,有借餘,結帳時要轉入「本期損益」的借方,不是貸方,B 錯。", "C:「業主往來」是獨資/合夥的用語;題目說「公司」,應借:本期損益,貸:累積盈虧,C 錯。", "D:定期盤存制銷貨成本法:借存貨(期末)、借銷貨成本;貸存貨(期初)、貸進貨(及進貨相關科目),正確。", "選 D。"], "pitfalls": "獨資用業主資本,公司用累積盈虧(保留盈餘);要看題目是哪種組織。", "distractors": {"A": "結帳是結清虛帳戶,實帳戶不結清。", "B": "銷貨折讓是借方餘額,應轉入借方。", "C": "組織為公司,結轉淨利應貸記累積盈虧而非業主往來。"}}, "check": "概念題:D 與官方一致。", "verified": true, "note": ""}, {"id": "114-2-A-15", "exam": "114-2", "paper": "A", "q": 15, "unit": "八、結帳", "topic": "本期損益與結帳", "stem": "公司年底調整後帳載有租金支出$14,000,文具用品$2,000,銷貨成本$64,000,預付租金$27,000,用品盤存$6,000,預收收入$11,000,銷貨收入$84,000,利息收入$5,000,在不考慮所得稅下的結帳敘述,下列何者正確?", "options": ["本期損益借餘$13,000", "本期損益貸餘$9,000", "全部收益結清時貸方之本期損益為$100,000", "全部收益結清時借方之本期損益為$113,000"], "answer": "B", "figure": null, "official": "本期損益借方$80,000、貸方$89,000,貸餘$9,000。全部收益結清:借:銷貨收入84,000、利息收入5,000,貸:本期損益89,000;全部費損結清:借:本期損益80,000,貸:租金支出14,000、文具用品2,000、銷貨成本64,000。", "explain": {"concept": "考虛帳戶(收益與費損)結帳,資產負債類(預付租金、用品盤存、預收收入)不屬於結帳範圍。", "steps": ["先分類:虛帳戶有 租金支出14,000、文具用品(費用)2,000、銷貨成本64,000(費損),銷貨收入84,000、利息收入5,000(收益)。", "預付租金、用品盤存是資產,預收收入是負債,都是實帳戶,不要結入本期損益(是干擾項)。", "費損合計=14,000+2,000+64,000=$80,000(借方);收益合計=84,000+5,000=$89,000(貸方)。", "本期損益=貸方89,000-借方80,000=貸餘 $9,000(淨利)。", "檢查選項:A 借餘13,000 錯;B 貸餘9,000 對;C 收益結清貸方應為89,000 非100,000;D 費損結清借方應為80,000 非113,000。選 B。"], "pitfalls": "預付租金、預收收入、用品盤存都是實帳戶,別當費用或收益加進去。", "distractors": {"A": "可能是把租金/文具用品混進資產負債項目算錯。", "C": "把預收收入11,000加入收益(84,000+5,000+11,000=100,000),但預收收入是負債。", "D": "把預付租金27,000與用品6,000當費損加入(80,000+27,000+6,000=113,000)。"}}, "check": "python:費損=14,000+2,000+64,000=80,000;收益=84,000+5,000=89,000;淨利9,000,與官方 B 相符。", "verified": true, "note": "官方詳解標示(A)(B),但答案表為 B;依答案表。"}, {"id": "114-2-A-16", "exam": "114-2", "paper": "A", "q": 16, "unit": "九、財務報表", "topic": "財務報表概念", "stem": "有關財務報表的敘述,下列何者錯誤?", "options": ["財務報表包括綜合損益表、資產負債表、權益變動表、現金流量表,以上各表之附註說明及附表", "資產負債表可反應一個企業的償債能力", "綜合損益表普遍採性質別表達", "綜合損益表採功能別表達需列出營業成本"], "answer": "C", "figure": null, "official": "(C)綜合損益表普遍採用「功能別」表達。", "explain": {"concept": "考財務報表的組成與綜合損益表費用的表達方式(性質別 vs 功能別)。", "steps": ["A:完整財務報表包含四大報表+附註與附表,正確。", "B:資產負債表顯示資產與負債,可觀察償債能力,正確。", "C:綜合損益表費用有「性質別」(依薪資、租金等性質)與「功能別」(依銷貨成本、營業費用等功能),實務上普遍採「功能別」,C 錯。", "D:功能別需列出營業成本,正確。", "題目問錯誤,選 C。"], "pitfalls": "功能別=依用途分類(營業成本、營業費用);性質別=依費用性質分類。", "distractors": {"A": "此敘述正確。", "B": "此敘述正確。", "D": "此敘述正確。"}}, "check": "概念題:C 錯誤與官方一致。", "verified": true, "note": ""}, {"id": "114-2-A-17", "exam": "114-2", "paper": "A", "q": 17, "unit": "九、財務報表", "topic": "流動比率與速動比率", "stem": "公司營運資金$28,000,速動比率 1.2,流動資產中除速動資產外,尚有存貨$4,000,進項稅額$2,000,無其他流動資產,則下列何者正確?", "options": ["流動資產為$148,000", "流動負債為$110,000", "速動資產為$144,000", "流動比率約為 1.23"], "answer": "B", "figure": null, "official": "設流動資產 x,流動負債 x-28,000,速動資產 x-6,000;(x-6,000)/(x-28,000)=1.2,得 x=138,000;流動負債=110,000,速動資產=132,000,流動比率=1.25。", "explain": {"concept": "用營運資金、速動比率、速動資產=流動資產-存貨-進項稅額 列方程式求解。", "steps": ["營運資金=流動資產-流動負債=28,000,設流動資產=x,則流動負債=x-28,000。", "速動資產=流動資產-存貨-進項稅額=x-4,000-2,000=x-6,000(存貨與進項稅額不是速動資產)。", "速動比率=速動資產÷流動負債=1.2:(x-6,000)/(x-28,000)=1.2。", "整理:x-6,000=1.2x-33,600,0.2x=27,600,x=138,000。", "流動負債=138,000-28,000=110,000;速動資產=138,000-6,000=132,000。", "流動比率=138,000÷110,000≈1.25。對照選項只有 B 正確。"], "pitfalls": "速動資產要扣除存貨、預付費用、進項稅額等;別忘了進項稅額。", "distractors": {"A": "流動資產為138,000,不是148,000。", "C": "速動資產為132,000,不是144,000。", "D": "流動比率應為1.25,不是1.23。"}}, "check": "python:x=138,000,流動負債110,000,速動資產132,000,速動比率=1.2,流動比率=1.2545,與官方 B 相符。", "verified": true, "note": ""}, {"id": "114-2-A-18", "exam": "114-2", "paper": "A", "q": 18, "unit": "十、加值型營業稅會計實務", "topic": "營業稅基本觀念", "stem": "有關營業稅的敘述,下列何者錯誤?", "options": ["特種統一發票專供總額課徵營業稅的營業人使用", "加值型營業稅稅率分為一般、外銷及免稅等三大類", "我國營業稅法規定,除本法另有規定外,一般營業稅最高稅率 10%,最低稅率 5%", "目前我國加值型營業稅係採「稅基相減法」"], "answer": "D", "figure": null, "official": "(D)目前我國加值型營業稅係採「稅額相減法」。", "explain": {"concept": "考營業稅制度:加值型營業稅採稅額相減法(銷項稅額-進項稅額),以及稅率規定。", "steps": ["A:特種統一發票給銀行、保險、特種飲食等「總額型」營業人使用,正確。", "B:稅率分一般(5%)、零稅率(外銷)與免稅,正確。", "C:營業稅法規定一般稅率最低5%,最高10%,正確。", "D:我國加值型營業稅是「稅額相減法」:應納稅額=銷項稅額-進項稅額,不是稅基相減法,所以 D 錯誤。", "選 D。"], "pitfalls": "稅額相減法與稅基相減法名稱相近。", "distractors": {"A": "正確敘述。", "B": "正確敘述。", "C": "正確敘述。"}}, "check": "概念題:D 錯誤與官方一致。", "verified": true, "note": ""}, {"id": "114-2-A-19", "exam": "114-2", "paper": "A", "q": 19, "unit": "十、加值型營業稅會計實務", "topic": "營業稅申報與留抵", "stem": "公司為加值型營業人,適用營業稅率 5%,上期累計留抵稅額$2,500,5、6 月份資料如下(下列金額皆未含營業稅):總銷項交易金額為$98,000,總進項交易金額為$136,000。經查詢得知,本期無外銷收入,銷項交易中包含已開立發票的預收貨款$8,000,而進項交易中包含購買機器設備$22,000、進貨訂金$1,200、購買郵票$500、一台經理專用小客車$8,500、預付經理宿舍一年之租金$1,200,則 7 月初申報營業稅後,留抵稅額之餘額為何?", "options": ["$2,790", "$3,190", "$3,215", "$3,250"], "answer": "A", "figure": null, "official": "進項稅額=($136,000-$500-$8,500-$1,200)×5%=$6,290;銷項稅額=$98,000×5%=$4,900;$2,500+$6,290=$8,790>$4,900,溢付稅額$3,890;退稅上限=$22,000×5%=$1,100;故應退稅款$1,100;留抵稅額=$2,500+$6,290-$4,900-$1,100=$2,790。", "explain": {"concept": "營業稅計算:銷項稅額-進項稅額-上期留抵;不得扣抵項目(郵票、小客車、交際等);有溢付稅額時,退稅限於購買固定資產(機器設備)的進項稅額,其餘留抵。", "steps": ["先算銷項稅額:本期銷項交易金額98,000(已含預收貨款已開發票的8,000,不用重複),×5%=$4,900。", "再算可扣抵進項:136,000 要扣掉不得扣抵的項目:購買郵票500(無進項稅額)、自用乘人小客車8,500(不得扣抵)、預付一年租金1,200(經理宿舍,員工福利,依題意視為不得扣抵);(136,000-500-8,500-1,200)=125,800,×5%=$6,290。", "把上期留抵加進來:2,500+6,290=8,790,大於銷項4,900,所以有溢付稅額 8,790-4,900=$3,890。", "退稅規定:溢付稅額中只有購買「固定資產(機器設備)」的進項稅額可以退稅:22,000×5%=1,100。溢付3,890與退稅上限1,100取較小者,應退稅款$1,100。", "其餘部分留抵下期:留抵稅額=3,890-1,100=$2,790。", "分錄:借:銷項稅額4,900、應退稅款1,100、留抵稅額290,貸:進項稅額6,290;原有留抵2,500 + 新增290=$2,790,選 A。"], "pitfalls": "郵票、自用小客車、員工福利等屬於不得扣抵進項;退稅有固定資產上限。", "distractors": {}}, "check": "python:進項稅額6,290;銷項4,900;溢付3,890;退稅限1,100;留抵=2,500+(6,290-4,900-1,100)=2,790,與官方 A 相符。", "verified": true, "note": "官方詳解未說明預付經理宿舍租金不得扣抵之理由,此為依詳解算式(排除1,200)推得。"}, {"id": "114-2-A-20", "exam": "114-2", "paper": "A", "q": 20, "unit": "十一、現金及內部控制", "topic": "現金及約當現金", "stem": "公司的會計人員小新、小葵於 X1 年底將以下資料全部包含在「現金及約當現金」項目,會計師說明「約當現金」是指短期並具高度流動性的定期存款或投資,同時具備可隨時轉成定額現金且價值變動風險甚小。聽完會計師的說明後,小新和小葵重新計算並作更正分錄,則小新、小葵對以下資料做出會計處理,下列哪一些選項正確?\n\n| 項目 | 金額 | 項目 | 金額 |\n|---|---|---|---|\n| 中信銀行活期存款 | $84,000 | 庫存現金(其中有一張$1,000 偽鈔) | $9,000 |\n| 保付支票 | 13,000 | X2 年 1 月底到期支票 | 3,200 |\n| 員工借條 | 5,300 | 2 個月期銀行承兌匯票 | 24,000 |\n| 全聯商品禮券(贈送員工用) | 6,000 | X1 年底購入的 X2 年 2 月底到期國庫券 | 7,000 |\n| 銀行本票 | 3,000 | 臺灣銀行 6 個月期定期存單 | 5,000 |\n| 客戶未承兌匯票 | 1,800 | 富邦銀行支票存款帳戶 | 16,000 |\n\n①小新:「約當現金」金額為$31,000\n②小葵:「約當現金」金額為$36,000\n③小新:資產負債表中「現金及約當現金」金額為$155,000\n④小葵:資產負債表中「現金及約當現金」金額為$163,200\n⑤小新:更正分錄\n借記:按攤銷後成本衡量之金融資產  $5,000\n  應收帳款  10,300\n  其他損失  1,000\n  職工福利  6,000\n  貸記:現金  $22,300\n⑥小葵:更正分錄\n借記:應收帳款  $1,800\n  其他損失  1,000\n  職工福利  6,000\n  其他應收款  5,300\n  貸記:現金  $14,100", "options": ["①③", "④⑥", "①③⑤", "②④⑥"], "answer": "A", "figure": null, "official": "約當現金=$24,000+$7,000=$31,000;現金及約當現金=$84,000+$13,000+$3,000+($9,000-$1,000)+$24,000+$7,000+$16,000=$155,000;更正分錄:借:其他應收款5,300、職工福利6,000、應收帳款1,800、其他損失1,000、應收票據3,200、按攤銷後成本衡量之金融資產5,000,貸:現金22,300。", "explain": {"concept": "判斷哪些項目屬於現金(庫存現金、活存、保付支票、銀行本票、支票存款等),哪些屬約當現金(自取得日起3個月內到期的投資),哪些不是現金要更正分錄。", "steps": ["先挑出「現金」:活期存款84,000、保付支票13,000、銀行本票3,000、庫存現金扣掉偽鈔後8,000(9,000-1,000)、支票存款16,000。", "約當現金:取得日起3個月內到期的短期投資:2個月期銀行承兌匯票24,000、X1年底購入的2月底到期國庫券7,000,合計=$31,000(①對、②錯)。", "6個月期定期存單5,000不符合3個月內,應列「按攤銷後成本衡量之金融資產」。", "現金及約當現金=84,000+13,000+3,000+8,000+24,000+7,000+16,000=$155,000(③對、④錯)。", "不屬於現金的要更正:X2年1月底到期支票3,200(遠期支票,應收票據)、員工借條5,300(其他應收款)、商品禮券6,000(職工福利)、客戶未承兌匯票1,800(應收帳款)、偽鈔1,000(其他損失)、6個月定存5,000(按攤銷後成本衡量之金融資產)。", "合計=3,200+5,300+6,000+1,800+1,000+5,000=$22,300。⑤小新的分錄把應收帳款寫10,300(其實應為1,800+3,200票據+5,300其他應收款拆開),科目錯誤;⑥小葵金額只有14,100,漏列;皆錯。", "所以正確的是①③,選 A。"], "pitfalls": "遠期支票(未到期)不是現金;約當現金只看「取得日起3個月內到期」。", "distractors": {"B": "④金額163,200錯誤,⑥分錄金額與科目不符。", "C": "⑤分錄中科目歸類不正確(應收帳款不可為10,300)。", "D": "②金額36,000是把6個月定存5,000也算入約當現金,錯。"}}, "check": "python:約當現金=24,000+7,000=31,000;現金及約當現金=155,000;更正合計=22,300,與官方 A 相符。", "verified": true, "note": "⑤⑥分錄與官方更正分錄比對後判定皆不正確;D 選項中②金額差額$5,000 為推測(誤將定存列入)。"}, {"id": "114-2-A-21", "exam": "114-2", "paper": "A", "q": 21, "unit": "十一、現金及內部控制", "topic": "零用金撥補", "stem": "公司定額零用金為$16,500,已支付水電費$7,500、文具用品$2,600,盤點手存零用金尚餘$6,600,其中包含一張佰元偽鈔,則撥補日之分錄將使淨利減少多少?", "options": ["$9,900", "$10,000", "$10,100", "$10,200"], "answer": "B", "figure": null, "official": "分錄:借:水電瓦斯費7,500、文具用品2,600、其他損失100,貸:現金短溢200、現金10,000;費損增加$10,200→淨利減少$10,200;收益增加$200→淨利增加$200;結論:淨利減少$10,000。", "explain": {"concept": "定額零用金撥補:補回的金額=定額-實際剩餘真鈔;差異記「現金短溢」;偽鈔當作其他損失。", "steps": ["實際剩餘真鈔=6,600-100(偽鈔)=6,500。", "應有的剩餘=16,500-(7,500+2,600)=6,400。實際真鈔比應有多100,表示現金溢餘100;又偽鈔損失100。依官方詳解處理為:現金短溢貸方200、其他損失借方100。", "撥補金額(貸記現金)=16,500-6,500=10,000。", "分錄:借:水電瓦斯費7,500、文具用品2,600、其他損失100,貸:現金短溢200、現金10,000(借貸各10,200)。", "對淨利的影響:費損增加7,500+2,600+100=10,200,收益(現金短溢)增加200,淨利淨減少10,200-200=$10,000。", "選 B。"], "pitfalls": "偽鈔不是現金,要當作損失;零用金溢缺列「現金短溢」(收益/損失)。", "distractors": {"A": "只減去現金短溢200,沒有認列偽鈔損失100。", "C": "只考慮費用與偽鈔,忽略現金短溢。", "D": "沒有把現金短溢(收益)抵減,直接把費損10,200當淨利減少。"}}, "check": "python:7,500+2,600+100-200=10,000,與官方 B 相符。", "verified": true, "note": "現金短溢$200 係依官方詳解之分錄(6,600-6,400)。"}, {"id": "114-2-A-22", "exam": "114-2", "paper": "A", "q": 22, "unit": "十一、現金及內部控制", "topic": "銀行存款調節表", "stem": "公司帳列 5 月份存款增加記錄共$46,000、支票及支出記錄共$45,500,5 月底銀行對帳單餘額為$26,000,經核對發現有下列不符事項,則公司 5 月初之帳上銀行存款餘額為何?\n①銀行代繳水費$600,公司尚未入帳\n②5 月底公司送存$4,200,銀行尚未入帳\n③5 月底尚有未兌現支票共計$3,200(其中有一張$1,300 為 3 月份所簽發之支票)\n④銀行存款利息$50,公司尚未入帳", "options": ["$28,850", "$28,300", "$27,550", "$27,050"], "answer": "D", "figure": null, "official": "正確餘額$27,000;5 月底帳面餘額=x=$27,550;5 月初帳面餘額=x+5 月支出$45,500-5 月存入$46,000=$27,050。", "explain": {"concept": "先用銀行調節表求 5 月底公司帳面餘額,再往回推 5 月初餘額(期末=期初+存入-支出)。", "steps": ["編調節表:銀行對帳單餘額26,000,加在途存款4,200,減未兌現支票3,200,正確餘額=26,000+4,200-3,200=$27,000。", "公司帳面餘額調整:帳面餘額x,減銀行代繳水費600(公司未入帳),加存款利息50,正確餘額=x-600+50=27,000,所以x=27,550(5月底帳面餘額)。", "③中的3月份支票已在3月入帳,但仍未兌現,屬於「未兌現支票」,全數3,200都要減,不需另外調整。", "回推期初:期末帳面餘額=期初+5月存入-5月支出,27,550=期初+46,000-45,500,期初=27,550-500=$27,050。", "選 D。"], "pitfalls": "題目問的是「5月初」,不是5月底;不要停在27,550。", "distractors": {"A": "在27,550上加上3月份支票1,300(誤以為要再調整),且忽略往回推期初。", "C": "算到5月底帳面餘額27,550就停了,忘記往回推到5月初。"}}, "check": "python:26,000+4,200-3,200=27,000;x=27,550;期初=27,550-46,000+45,500=27,050,與官方 D 相符。", "verified": true, "note": ""}, {"id": "114-2-A-23", "exam": "114-2", "paper": "A", "q": 23, "unit": "十二、應收款項", "topic": "應收款項相關觀念", "stem": "下列敘述何者正確?", "options": ["採淨價法收取的對價記錄現金折扣時,顧客未享之折扣列為營業外收入", "交貨條件為目的地交貨,由買方支付運費時,則賣方貸記「應收帳款」", "收回已沖銷應收帳款,對應收帳款之淨變現價值無影響", "企業簽發本票辦理貼現,應貸記「應收票據貼現負債」"], "answer": "B", "figure": null, "official": "(A)採淨價法收取的對價記錄現金折扣時,顧客未享之折扣應列營業收入;(C)收回已沖銷應收帳款,借:應收帳款,貸:備抵損失;借:現金,貸:應收帳款;故應收帳款淨變現價值減少;(D)貸記「應付票據」。", "explain": {"concept": "考現金折扣淨價法、運費處理、已沖銷帳款收回、票據貼現。", "steps": ["A:淨價法下顧客未享受折扣,多收的折扣金額列「銷貨折扣損失/營業收入」(營業收入),不是營業外,A 錯。", "B:目的地交貨:運費由賣方負擔。若買方代付運費,賣方應借:應收帳款(把運費視為應向買方收取)...但若買方支付運費,賣方貸記「應收帳款」(減少應收)。因此賣方貸記應收帳款,B 正確。", "C:收回已沖銷帳款:先轉回(借應收帳款、貸備抵損失),再收現(借現金、貸應收帳款);應收帳款減少而現金增加,應收帳款淨變現價值減少,C 錯。", "D:「簽發本票」是自己欠人家錢,是應付票據;貼現的是收到別人的票據,才有應收票據貼現負債,D 錯。", "選 B。"], "pitfalls": "簽發的票據=應付票據,收到的票據=應收票據。", "distractors": {"A": "淨價法的折扣損失屬營業收入而非營業外收入。", "C": "收回已沖銷帳款後,應收帳款淨變現價值並非無影響(因為收現)。", "D": "簽發本票應貸記應付票據,應收票據貼現負債是貼現他人票據才有。"}}, "check": "概念題:對照官方詳解,B 為正確。", "verified": false, "note": "官方詳解未直接解說(B)為何正確,B 理由為依會計常識推得(買方代付運費→賣方貸應收帳款);請複核。"}, {"id": "114-2-A-24", "exam": "114-2", "paper": "A", "q": 24, "unit": "十二、應收款項", "topic": "應收票據貼現", "stem": "屏東公司因積欠員工工薪水好幾個月,財務長 X1 年 5 月 1 日決定將從客戶收來的不附息票據拿到銀行貼息取現。該票據發票日為 X1 年 2 月 1 日,票據期間 7 個月,銀行給予貼現金額$174,000,貼現息$6,000。財務長想知道該票據貼現率應為多少?", "options": ["8%", "9%", "10%", "11%"], "answer": "C", "figure": null, "official": "不附息票據到期值=貼現金額+貼現息=$174,000+$6,000=$180,000;貼現期間 5/1~9/1 共 4 個月;貼現息=到期值×貼現率×4/12=$6,000,貼現率=10%。", "explain": {"concept": "不附息票據貼現:貼現息=到期值×貼現率×貼現期間,不附息票據到期值=面額。", "steps": ["不附息票據:票據到期值就是面額。到期值-貼現息=貼現金額,所以到期值=174,000+6,000=$180,000。", "找貼現期間:票據 2/1 發票、期間7個月,到期日9/1;5/1 貼現,距離到期還有 5/1~9/1=4 個月(貼現期間)。", "貼現息公式:到期值×貼現率×貼現期間=貼現息。", "代入:180,000×貼現率×4/12=6,000 → 60,000×貼現率=6,000 → 貼現率=10%。", "選 C。"], "pitfalls": "貼現期間是「貼現日到到期日」,不是票據全期或持有期間。", "distractors": {"A": "可能把貼現期間誤算成5個月:180,000×5/12=75,000,6,000÷75,000=8%。"}}, "check": "python:180,000×4/12=60,000;6,000÷60,000=10%,與官方 C 相符。", "verified": true, "note": ""}, {"id": "114-2-A-25", "exam": "114-2", "paper": "A", "q": 25, "unit": "十二、應收款項", "topic": "備抵損失與預期信用減損損失", "stem": "期末公司帳冊因電腦中毒,部份資料不見,目前已知年中曾經被甲客戶倒帳$12,000,後因甲客戶良心不安,勉強東湊西湊歸還$2,000。經過電腦工程師搶救,從殘餘的分類帳冊中得知期初備抵損失-應收帳款貸餘$6,000,年底調整前應收帳款帳戶餘額$42,300。另外,已知年底調整後應收帳款之淨變現價值為$39,500,則期末所提列預期信用減損損失金額為何?", "options": ["$2,800", "$4,800", "$6,800", "$8,800"], "answer": "C", "figure": null, "official": "備抵損失 T 字帳:期初貸餘6,000、沖銷借12,000、收回貸2,000,調整前借餘$4,000;期末備抵損失=$42,300-$39,500=$2,800;提列金額=$2,800+$4,000=$6,800。", "explain": {"concept": "用備抵損失 T 字帳求調整前餘額,再算要提列多少才能把餘額補到期末應有的貸餘。", "steps": ["先畫備抵損失-應收帳款 T 字帳。期初貸餘6,000;沖銷壞帳12,000 → 借方;收回2,000 → 貸方(借:應收帳款 貸:備抵損失,再借現金 貸應收帳款)。", "調整前餘額=6,000-12,000+2,000=-4,000,即借餘 $4,000(備抵損失變成借方餘額)。", "期末應有的備抵損失:應收帳款42,300-淨變現價值39,500=$2,800(貸餘)。", "要把借餘4,000補成貸餘2,800,需要貸記4,000+2,800=$6,800,這就是本期預期信用減損損失。", "分錄:借:預期信用減損損失6,800,貸:備抵損失-應收帳款6,800。選 C。"], "pitfalls": "調整前備抵損失是「借餘」,所以要補的金額比期末餘額大。", "distractors": {"A": "只把期末備抵損失2,800當提列數,忽略調整前的借餘4,000。", "D": "沒加入收回的2,000(借餘變成6,000):6,000+2,800=8,800。"}}, "check": "python:6,000-12,000+2,000=-4,000;42,300-39,500=2,800;提列=2,800+4,000=6,800,與官方 C 相符。", "verified": true, "note": ""}, {"id": "114-3-A-01", "exam": "114-3", "paper": "A", "q": 1, "unit": "一、會計基本概念", "topic": "會計準則制定機構", "stem": "小蕨是一位勤奮學習的技術型高中商科學生,在校不論學業、活動參與,都是相當認真負責且表現優異,在學業表現上對專業科目會計學更是熱愛,上課認真學習之外,也會將老師授課後的會計課程內容,依照時間先後順序做成詳細條列式的重點複習筆記。小蕨把國內外致力於發展會計原則之相關團體,整理成筆記,下列敘述何者錯誤?", "options": ["「國際財務報導準則」是由國際會計準則理事會制定並發布", "我國中小企業適用之「企業會計準則公報」是由金管會證期局所制定", "美國「財務會計準則公報」是由美國財務會計準則委員會制定及發布", "我國公開發行公司所適用一般公認會計原則之「國際財務報導準則」正體中文版是由中華民國會計研究發展基金會所翻譯"], "answer": "B", "figure": null, "official": "企業會計準則公報是由中華民國會計研究發展基金會制定,不是金管會證期局。", "explain": {"concept": "考會計準則的制定單位:國際、美國、我國各由哪個機構制定。", "steps": ["題目要找「錯誤」的敘述,所以要把四個選項逐一判斷,挑出說錯的那個。", "(A) IFRS 由國際會計準則理事會(IASB)制定,正確。", "(B) 我國中小企業適用的「企業會計準則公報」,是由中華民國會計研究發展基金會制定,不是金管會證期局,所以這句錯誤。", "(C) 美國財務會計準則公報由 FASB(財務會計準則委員會)制定,正確。", "(D) 我國公開發行公司適用 IFRS,其正體中文版由中華民國會計研究發展基金會翻譯,正確。", "所以錯誤的是 (B)。"], "pitfalls": "容易把「制定」和「監督/認可」的機構搞混,金管會是主管機關,不是中小企業準則的制定者。", "distractors": {"A": "此句正確,不是錯誤選項。", "C": "此句正確,FASB 確實制定美國準則。", "D": "此句正確,翻譯單位就是會計研究發展基金會。"}}, "check": "概念題:對照官方詳解(B)與我國準則制定機構常識,一致。", "verified": true, "note": ""}, {"id": "114-3-A-02", "exam": "114-3", "paper": "A", "q": 2, "unit": "一、會計基本概念", "topic": "會計事項的定義", "stem": "下列何者屬於會計事項?", "options": ["向供應商訂購商品", "與貨運公司簽訂運送契約", "向代銷商承諾銷售完成時給佣金", "因火災所造成辦公設備毀損"], "answer": "D", "figure": null, "official": "會計事項指造成資產、負債、權益、收益及費損發生增減變動之事項,(D)火災毀損使資產減少、費損增加,符合定義。", "explain": {"concept": "會計事項(會計交易)的判斷:必須造成資產、負債、權益、收益、費損其中之一發生增減變動。", "steps": ["先記住判斷標準:有沒有讓資產、負債、權益、收益、費損「數字變動」?只簽約、訂購、承諾,錢和財產都還沒動,就不是會計事項。", "(A) 向供應商訂購商品:只是下訂單,還沒收貨也沒付款,帳上沒有變動。", "(B) 與貨運公司簽訂運送契約:只是簽約,尚未發生運費。", "(C) 向代銷商承諾銷售完成時給佣金:只是承諾,等銷售完成才會有佣金費用。", "(D) 火災毀損辦公設備:資產減少、費損(損失)增加,有實際的增減變動,是會計事項。"], "pitfalls": "「訂購、簽約、承諾」這類契約行為在還沒有履行前,不須入帳,別誤選。", "distractors": {"A": "訂購尚未交貨付款,資產負債沒變。", "B": "簽約只是約定,尚未發生費用。", "C": "只是承諾未來給佣金,銷售完成前不入帳。"}}, "check": "概念題:與官方詳解及會計事項定義一致。", "verified": true, "note": ""}, {"id": "114-3-A-03", "exam": "114-3", "paper": "A", "q": 3, "unit": "四、分錄與日記簿", "topic": "銷貨折扣與銷貨退回分錄", "stem": "小程商店於民國 114 年 9 月份以總額法記帳之銷貨相關交易如下:\n①9/15 賒銷商品一批,定價$200,000,以七五折成交,付款條件 2/10,n/30\n②9/18 三天前賒銷商品中,因顧客發現瑕疵,遭客戶退回商品成交價$30,000\n③9/24 收到 9/15 半數貨款\n④9/30 收到 9/15 剩餘貨款\n則有關①~④交易所作之分錄,下列何者正確?", "options": ["9/15 借:應收帳款$200,000,貸:銷貨收入$200,000", "9/18 借:應收帳款$30,000,貸:銷貨退回$30,000", "9/24 借:現金$73,500、銷貨折讓$1,500,貸:應收帳款$75,000", "9/30 借:現金$60,000,貸:應收帳款$60,000"], "answer": "D", "figure": null, "official": "①借應收帳款150,000貸銷貨收入150,000;②借銷貨退回30,000貸應收帳款30,000;③借現金58,800、銷貨折讓1,200貸應收帳款60,000;④借現金60,000貸應收帳款60,000。", "explain": {"concept": "總額法下,銷貨按「成交價」入帳;退回要扣掉,折扣只對尚未付款且在折扣期間內付款的部分計算。", "steps": ["七五折成交,成交價=$200,000×75%=$150,000。9/15 分錄:借 應收帳款 150,000,貸 銷貨收入 150,000。", "9/18 客戶退回成交價 $30,000:借 銷貨退回 30,000,貸 應收帳款 30,000。此時應收帳款剩 150,000-30,000=$120,000。", "9/24 收到「半數」貨款:120,000×1/2=$60,000。付款條件 2/10,9/15 到 9/24 是第 9 天,在 10 天折扣期內,折扣=60,000×2%=$1,200,實收現金=60,000-1,200=$58,800。分錄:借 現金 58,800、銷貨折讓 1,200,貸 應收帳款 60,000。", "9/30 收到剩餘 $60,000:已超過 10 天折扣期,無折扣。分錄:借 現金 60,000,貸 應收帳款 60,000,所以 (D) 正確。"], "pitfalls": "最容易漏掉的是「七五折」要先打折才是入帳金額,以及退回後的應收帳款只剩一部分,折扣要以實際收款額算。", "distractors": {"A": "沒有把七五折算進去,把定價 $200,000 當成交價。", "B": "退回的方向寫反了,應該借銷貨退回、貸應收帳款,不是借應收帳款。", "C": "把 150,000 的一半(75,000)當收款額,忘了先扣退回的 30,000,折扣也算成 1,500。"}}, "check": "python:150000;150000-30000=120000;半數60000;折扣1200;現金58800;與官方相符。", "verified": true, "note": "單元歸類可能有爭議(銷貨折扣/退回分錄,無對應單元,歸四;亦可歸十二)。"}, {"id": "114-3-A-04", "exam": "114-3", "paper": "A", "q": 4, "unit": "六、試算與試算表", "topic": "試算表的意義與格式", "stem": "試算表是運用借貸平衡原理,檢驗分錄與過帳是否正確無誤的會計處理程序,有關試算表之敘述,下列何者正確?", "options": ["試算表之表首日期應為交易資料截止日", "試算表屬於企業正式的財務報表", "試算表之表身包括摘要、會計項目、金額欄位", "餘額式試算表又稱合計式試算表,是根據「等量加等量,其和必相等」的原理所編製"], "answer": "A", "figure": null, "official": "(B)試算表屬非正式財務報表;(C)表身包括類號、會計項目及金額欄位;(D)餘額式試算表又稱差額式試算表,依「等量減等量,其差必相等」編製。", "explain": {"concept": "認識試算表的性質、格式與兩種編法(合計式、餘額式)。", "steps": ["試算表是為了檢查借方總額是否等於貸方總額,不是對外報告用的正式報表,所以 (B) 錯。", "表身欄位是「類號、會計項目、金額(借方、貸方)」,不是摘要,所以 (C) 錯。", "合計式試算表依「等量加等量,其和必相等」;餘額式(差額式)依「等量減等量,其差必相等」,(D) 把兩種搞混,錯。", "(A) 試算表的表首日期是「交易資料截止日」(例如 X1 年 12 月 31 日),正確。"], "pitfalls": "合計式和餘額式的原理名稱容易互換;表身欄位是「類號」不是「摘要」。", "distractors": {"B": "試算表是內部檢查用的非正式報表,不是正式財務報表。", "C": "表身是類號、會計項目、金額,不含摘要(摘要是日記簿、分類帳的欄位)。", "D": "餘額式試算表是「差額式」,原理是等量減等量其差必相等;「等量加等量其和必相等」是合計式。"}}, "check": "概念題:與官方詳解一致。", "verified": true, "note": ""}, {"id": "114-3-A-05", "exam": "114-3", "paper": "A", "q": 5, "unit": "一、會計基本概念", "topic": "權責發生制與現金基礎比較", "stem": "在權責發生基礎下,會使收入增加,但是在現金基礎下,卻不會增加收入的交易為何?", "options": ["預收貨款", "現銷商品", "賒銷商品", "收到客戶償還貨款"], "answer": "C", "figure": null, "official": "僅(C)賒銷商品符合:權責基礎資產增加、收入增加;現金基礎不作分錄。", "explain": {"concept": "比較權責發生基礎(賺得即認列收入)和現金基礎(收到現金才認列收入)。", "steps": ["先釐清:權責基礎「賺到就認列收入」,現金基礎「收到現金才認列收入」。我們要找的是「權責基礎有收入,但現金基礎沒收入」。", "(A) 預收貨款:權責基礎還沒賺到,記負債;現金基礎一收現金就算收入,剛好相反。", "(B) 現銷商品:兩種基礎都收到現金也賺到,都增加收入。", "(C) 賒銷商品:權責基礎已賺得,借應收帳款、貸銷貨收入;現金基礎還沒收到現金,不作分錄。符合題意。", "(D) 收到客戶償還貨款:權責基礎只是應收帳款減少,沒有收入;現金基礎才認列收入,也相反。"], "pitfalls": "別把預收和收回應收帳款弄反;它們是「現金基礎有、權責基礎沒有」。", "distractors": {"A": "預收貨款是權責基礎不增加收入、現金基礎增加收入,方向相反。", "B": "現銷兩種基礎都增加收入。", "D": "收回應收帳款只在現金基礎下增加收入,權責基礎早已在賒銷時認列。"}}, "check": "概念題:與官方比較表一致。", "verified": true, "note": "單元歸類可能有爭議(權責與現金基礎歸一,亦可歸七)。"}, {"id": "114-3-A-06", "exam": "114-3", "paper": "A", "q": 6, "unit": "七、調整", "topic": "聯合基礎用品盤存調整", "stem": "小慈公司採用聯合基礎作為交易入帳依據,本年初公司「用品盤存」帳戶餘額為$8,400,年中新購入一批辦公用文具$36,000,期末盤點尚有$20,000 文具未耗用,則期末調整分錄之借方為何?", "options": ["用品盤存$24,400", "文具用品$11,600", "文具用品$24,400", "用品盤存$11,600"], "answer": "D", "figure": null, "official": "採聯合基礎,新購文具記入虛帳戶「文具用品」,年底調整:借 用品盤存 11,600,貸 文具用品 11,600。", "explain": {"concept": "聯合基礎:購入時記費用(虛帳戶),期末再把未用完的部分調整回資產(用品盤存)。", "steps": ["聯合基礎的特色:購入文具時借「文具用品」(虛帳戶)36,000,不記資產。", "期末盤點還有 $20,000 沒用完,所以期末「用品盤存」應該是 $20,000。", "「用品盤存」帳上原有 $8,400,要調到 $20,000,需增加 20,000-8,400=$11,600。", "調整分錄:借 用品盤存 11,600,貸 文具用品 11,600。借方是「用品盤存 $11,600」,選 D。", "驗算:文具用品費用=8,400+36,000-20,000=$24,400,也就是 36,000-11,600=24,400,相符。"], "pitfalls": "要用「期末盤存-期初盤存」算調整數,不是直接拿用掉的金額當借方。", "distractors": {"A": "把用掉的 24,400 當成用品盤存借方,忘了用品盤存只需調整增減數。", "B": "借貸方向寫反,借成文具用品。", "C": "24,400 是本期耗用的文具用品費用,而且科目也錯了。"}}, "check": "python:20000-8400=11600,與官方 D 相符。", "verified": true, "note": ""}, {"id": "114-3-A-07", "exam": "114-3", "paper": "A", "q": 7, "unit": "八、結帳", "topic": "實帳戶與虛帳戶", "stem": "下列哪一個帳戶之期末餘額需結轉至下期?", "options": ["預期信用減損利益", "備抵損失", "銷貨折讓", "進貨費用"], "answer": "B", "figure": null, "official": "結帳時損益類虛帳戶歸零,實帳戶(資產、負債、權益)餘額結轉下期。備抵損失屬資產(抵銷)帳戶。", "explain": {"concept": "實帳戶(資產、負債、權益)餘額結轉下期;虛帳戶(收益、費損)要結清歸零。", "steps": ["結帳的規則:收益、費損這些「虛帳戶」要結轉到本期損益,結清歸零;資產、負債、權益這些「實帳戶」餘額留到下期。", "(A) 預期信用減損利益:屬收益(損益)帳戶,結帳時結清。", "(B) 備抵損失:是應收帳款的抵銷(資產)帳戶,屬實帳戶,餘額要結轉到下期。", "(C) 銷貨折讓:屬收益帳戶(銷貨收入的減項),要結清。", "(D) 進貨費用:屬費損帳戶,結清。", "所以選 (B)。"], "pitfalls": "「備抵」兩個字看起來像費用,但它是資產的減項,屬實帳戶。", "distractors": {"A": "屬損益帳戶,結帳時結清。", "C": "屬收益(損益)帳戶,結帳時結清。", "D": "屬費損帳戶,結帳時結清。"}}, "check": "概念題:與官方詳解一致。", "verified": true, "note": ""}, {"id": "114-3-A-08", "exam": "114-3", "paper": "A", "q": 8, "unit": "九、財務報表", "topic": "綜合損益表淨利計算", "stem": "大翔公司 113 年度相關損益資料如下:銷貨淨額$800,000,銷貨成本為銷貨淨額之 60%,推銷費用$40,000,管理費用$23,000,預期信用減損損失$6,400,營業外收入$16,000,營業外支出$2,300,所得稅率 20%,則本期淨利應為多少?", "options": ["$211,440", "$291,400", "$339,440", "$428,900"], "answer": "A", "figure": null, "official": "銷貨成本=480,000;稅前淨利=800,000-480,000-40,000-23,000-6,400+16,000-2,300=264,300;所得稅=52,860;淨利=211,440。", "explain": {"concept": "依綜合損益表順序:銷貨毛利→營業利益→稅前淨利→扣所得稅→本期淨利。", "steps": ["先算銷貨成本=800,000×60%=$480,000。", "銷貨毛利=800,000-480,000=$320,000。", "營業費用=推銷 40,000+管理 23,000+預期信用減損損失 6,400=$69,400,營業利益=320,000-69,400=$250,600。", "加營業外收入 16,000、減營業外支出 2,300:稅前淨利=250,600+16,000-2,300=$264,300。", "所得稅費用=264,300×20%=$52,860。", "本期淨利=264,300-52,860=$211,440,選 A。"], "pitfalls": "最容易忘記扣所得稅,或把預期信用減損損失漏掉。", "distractors": {}}, "check": "python:稅前264,300;淨利=264,300×0.8=211,440,與官方 A 相符。", "verified": true, "note": ""}, {"id": "114-3-A-09", "exam": "114-3", "paper": "A", "q": 9, "unit": "九、財務報表", "topic": "速動比率", "stem": "大衛公司本年底資產負債表部分資料如下:資產總額$6,400,000,流動資產$2,840,000,流動資產中包括約當現金$1,200,000、應收帳款$800,000、存貨$440,000、預付款項$400,000,流動負債$1,000,000,則大衛公司衡量短期償債能力之速動比率應為多少?", "options": ["1.5", "1.8", "2.0", "2.4"], "answer": "C", "figure": null, "official": "速動資產=$1,200,000+$800,000=$2,000,000;速動比率=2,000,000÷1,000,000=2.0。", "explain": {"concept": "速動比率=速動資產÷流動負債,速動資產只含現金及約當現金、短期投資、應收款項,不含存貨與預付款項。", "steps": ["速動資產是「很快能變現」的資產:現金及約當現金、應收帳款(題目沒有短期投資)。存貨和預付款項不算。", "速動資產=1,200,000+800,000=$2,000,000。", "速動比率=速動資產÷流動負債=2,000,000÷1,000,000=2.0,選 C。"], "pitfalls": "不要把存貨、預付款項放進速動資產;也不要把流動資產總額 2,840,000 拿去除(那是流動比率)。", "distractors": {"D": "2.4=(1,200,000+800,000+400,000)÷1,000,000,把預付款項也算進速動資產。"}}, "check": "python:(1200000+800000)/1000000=2.0,與官方相符。", "verified": true, "note": ""}, {"id": "114-3-A-10", "exam": "114-3", "paper": "A", "q": 10, "unit": "十、加值型營業稅會計實務", "topic": "營業稅申報:應退稅額", "stem": "小喬公司為適用一般稅率之加值型營業人,5、6 月份交易資料如下:(營業稅 5%皆為外加)\n①銷貨總額$5,000,000,其中包括外銷$1,000,000\n②購入機器設備$500,000 及營業用貨車$400,000\n③進貨總額$3,000,000\n④上期留抵稅額$70,000\n有關本期結算後應申報之營業稅項目及金額,下列敘述何者正確?", "options": ["銷項稅額$250,000", "進項稅額$265,000", "應收退稅款$65,000", "累積留抵稅額$70,000"], "answer": "C", "figure": null, "official": "銷項稅額=(5,000,000-1,000,000)×5%=200,000;進項稅額=(500,000+400,000+3,000,000)×5%=195,000;應退稅限額=95,000;留抵稅額=195,000+70,000-200,000=65,000;取較小者65,000為應退稅額,累積留抵稅額0。", "explain": {"concept": "外銷零稅率;進項稅額 + 上期留抵 - 銷項稅額 = 本期留抵,應退稅額取「留抵稅額」與「退稅限額」較小者。", "steps": ["銷項稅額:外銷適用零稅率不收稅,只有內銷 5,000,000-1,000,000=$4,000,000 要收稅,銷項稅額=4,000,000×5%=$200,000。", "進項稅額:機器設備、營業用貨車、進貨都可扣抵,(500,000+400,000+3,000,000)×5%=$195,000。", "本期留抵稅額=進項 195,000+上期留抵 70,000-銷項 200,000=$65,000。", "退稅限額(外銷、購入固定資產可退):(外銷銷售額 1,000,000+固定資產 500,000+400,000)×5%=$95,000。", "應退稅額取兩者較小:留抵 65,000 與限額 95,000 → $65,000。因為全部都退了,累積留抵稅額為 0。所以選 (C)。"], "pitfalls": "外銷是零稅率,銷項稅額要先扣掉;應退稅額要比較「留抵稅額」和「退稅限額」兩者取小。", "distractors": {"A": "250,000=5,000,000×5%,沒扣掉外銷零稅率部分。", "B": "265,000=195,000+70,000,把上期留抵誤加進進項稅額。", "D": "留抵 65,000 已全額退稅,累積留抵為 0;70,000 是上期留抵稅額。"}}, "check": "python:銷項200,000;進項195,000;195,000+70,000-200,000=65,000;限額95,000;退稅65,000,與官方 C 相符。", "verified": true, "note": ""}, {"id": "114-3-A-11", "exam": "114-3", "paper": "A", "q": 11, "unit": "十一、現金及內部控制", "topic": "現金及約當現金內容", "stem": "下列何者應包含於資產負債表中「現金及約當現金」項目?", "options": ["郵政匯票", "償債基金", "客戶存款不足遭退票", "印花稅票"], "answer": "A", "figure": null, "official": "償債基金列於其他非流動資產;客戶存款不足遭退票列於應收帳款;印花稅票列於預付款項。", "explain": {"concept": "認識哪些項目屬於現金(庫存現金、銀行存款、郵政匯票等隨時可使用的支付工具)。", "steps": ["現金包含通貨與可隨時當成支付工具、存款的項目,例如銀行存款、銀行匯票、郵政匯票、到期公債息票等。", "(A) 郵政匯票:可立即兌現,屬現金,正確。", "(B) 償債基金:專款專用、非隨時可動用,列「其他非流動資產」。", "(C) 客戶存款不足遭退票:錢沒收到,變回應收帳款。", "(D) 印花稅票:屬預付款項(用品性質),不是現金。"], "pitfalls": "遠期支票、存款不足退票、印花稅票、郵票都不是現金,要記住。", "distractors": {"B": "償債基金限定用途,不能隨時支付,不屬於現金。", "C": "遭退票表示沒收到現金,轉為應收帳款。", "D": "印花稅票是預付款項,不是支付工具。"}}, "check": "概念題:與官方詳解一致。", "verified": true, "note": ""}, {"id": "114-3-A-12", "exam": "114-3", "paper": "A", "q": 12, "unit": "十一、現金及內部控制", "topic": "定額零用金撥補", "stem": "小新公司設置定額零用金$5,000。零用金管理員申報本月各項支出如:郵票$1,200、電費$1,900 及電話費$1,000,手存零用金尚餘$800,簽發支票撥補,則零用金撥補分錄應為何?", "options": ["貸記:銀行存款$4,100", "借記:現金短溢$900", "貸記:銀行存款$4,300", "借記:現金短溢$100"], "answer": "D", "figure": null, "official": "撥補金額=5,000-800=4,200;借 郵電費 2,200、水電瓦斯費 1,900、現金短溢 100,貸 銀行存款 4,200。", "explain": {"concept": "定額零用金撥補數=定額-手存現金;單據支出合計若與撥補數不等,差額記「現金短溢」。", "steps": ["定額零用金每次補回到定額 $5,000,現在手上只剩 $800,所以要撥補 5,000-800=$4,200(支票金額)。", "單據支出合計=1,200+1,900+1,000=$4,100(郵票+電話費=2,200 記郵電費,電費 1,900)。", "實際少了 4,200 但單據只有 4,100,差 $100 是短少,借「現金短溢」100。", "分錄:借 郵電費 2,200、水電瓦斯費 1,900、現金短溢 100,貸 銀行存款 4,200。題目問的借方科目是 (D)「現金短溢 $100」。"], "pitfalls": "撥補金額要用「定額-手存」算,不是直接用單據合計 4,100;差額才是現金短溢。", "distractors": {"A": "用單據支出合計 4,100 當撥補金額,忘了要以「定額-手存」計算。", "B": "把 5,000-4,100=900 當成短溢,忘了手存 800 還在。", "C": "4,300 是把 4,200 再多加 100,短溢的方向算反。"}}, "check": "python:5000-800=4200;單據1200+1900+1000=4100;差額100為短少,與官方 D 相符。", "verified": true, "note": ""}, {"id": "114-3-A-13", "exam": "114-3", "paper": "A", "q": 13, "unit": "十二、應收款項", "topic": "備抵法對應收帳款帳面金額的影響", "stem": "小劉公司採用備抵法處理應收帳款可能發生之減損損失,則①收回以前年度已沖銷之應收帳款,以及②本年年末提列預期信用減損損失。上述兩項交易對應收帳款帳面金額之影響,下列敘述何者正確?", "options": ["不變;減少", "減少;減少", "不變;不變", "減少;不變"], "answer": "B", "figure": null, "official": "①借應收帳款、貸備抵損失;借現金、貸應收帳款,使應收帳款帳面金額減少;②借預期信用減損損失、貸備抵損失,使應收帳款帳面金額減少。", "explain": {"concept": "應收帳款帳面金額=應收帳款-備抵損失。判斷各分錄使它增加或減少。", "steps": ["帳面金額=應收帳款-備抵損失。", "①收回已沖銷帳款分兩步:(1)借 應收帳款、貸 備抵損失(兩邊同增,帳面金額不變);(2)借 現金、貸 應收帳款(應收帳款減少,備抵損失不變),帳面金額減少。", "②提列預期信用減損損失:借 預期信用減損損失、貸 備抵損失,備抵損失增加,帳面金額減少。", "兩項都減少,選 B。"], "pitfalls": "回收已沖銷帳款的第一步使帳面金額不變,但整個交易完成後(收到現金)帳面金額是減少的。", "distractors": {"A": "以為①收回已沖銷帳款不影響帳面金額,忘了第二步現金收回使應收帳款減少。", "C": "忽略兩個分錄最後都使「應收帳款-備抵損失」變小。", "D": "忘了②提列預期信用減損損失使備抵損失增加,帳面金額減少。"}}, "check": "以T字帳演算:①淨效果應收帳款帳面金額-x(轉為現金);②備抵損失增加;與官方 B 一致。", "verified": true, "note": ""}, {"id": "114-3-A-14", "exam": "114-3", "paper": "A", "q": 14, "unit": "十二、應收款項", "topic": "信用卡銷貨分錄", "stem": "小勐公司提供顧客使用信用卡交易,若顧客使用信用卡至小勐公司消費$8,000,已知銀行會向小勐公司收取 1.5%之信用卡手續費,則小勐公司此筆交易記錄應為何?", "options": ["借:應收帳款$7,880、信用卡費用$120,貸:銷貨收入$8,000", "借:應收帳款$7,880,貸:銷貨收入$7,880", "借:應收帳款$8,000、信用卡費用$120,貸:銷貨收入$8,120", "借:應收帳款$8,120,貸:銷貨收入$8,120"], "answer": "A", "figure": null, "official": "信用卡手續費是銀行向商家收取;手續費=8,000×1.5%=120;借 應收帳款 7,880、信用卡費用 120,貸 銷貨收入 8,000。", "explain": {"concept": "信用卡銷貨:銷貨收入照售價記錄,銀行手續費記費用,應收銀行款項為扣除手續費後的淨額。", "steps": ["銷貨收入就是商品售價 $8,000(客人付的價錢)。", "銀行向商家收 1.5% 手續費:8,000×1.5%=$120,記「信用卡費用」借方。", "公司之後實際能向銀行收到的錢=8,000-120=$7,880,記「應收帳款」借方。", "分錄:借 應收帳款 7,880、信用卡費用 120,貸 銷貨收入 8,000。借貸合計都是 8,000,平衡。選 A。"], "pitfalls": "手續費是商家付給銀行的,不會增加銷貨收入,也不能加在應收帳款上。", "distractors": {"B": "沒有把手續費記成費用,銷貨收入直接寫成淨額 7,880,收入被少報。", "C": "把手續費當成顧客額外付的,銷貨收入加成 8,120,方向錯。", "D": "同樣把手續費加在顧客身上,應收與銷貨都變 8,120。"}}, "check": "python:8000×0.015=120;8000-120=7880;借貸平衡,與官方 A 相符。", "verified": true, "note": ""}, {"id": "114-3-A-15", "exam": "114-3", "paper": "A", "q": 15, "unit": "十二、應收款項", "topic": "附息票據貼現", "stem": "小梁公司於民國 114 年 4 月 1 日收到面額為$260,000,附息 4%半年期票據向銀行貼現。銀行貼現率 6%,並收到現金$259,896,則小梁公司票據貼現日期為何?", "options": ["114 年 5 月 1 日", "114 年 6 月 1 日", "114 年 7 月 1 日", "114 年 8 月 1 日"], "answer": "B", "figure": null, "official": "到期值=260,000×(1+4%×6/12)=265,200;貼現息=265,200-259,896=5,304;265,200×6%×貼現期間=5,304,貼現期間=4/12;持有 2 個月,貼現日為 114 年 6 月 1 日。", "explain": {"concept": "附息票據貼現:貼現息=到期值×貼現率×貼現期間;由貼現息反推貼現期間,再推貼現日。", "steps": ["先算到期值:附息票據到期值=面額+利息=260,000×(1+4%×6/12)=$265,200。", "貼現息=到期值-貼現所得現金=265,200-259,896=$5,304。", "貼現息=到期值×貼現率×貼現期間 → 265,200×6%×t=5,304,所以 t=5,304÷15,912=1/3 年=4 個月。", "票據共 6 個月,貼現期間(剩餘)4 個月,代表持有 6-4=2 個月。", "4/1 加 2 個月=6/1,所以貼現日是 114 年 6 月 1 日,選 B。"], "pitfalls": "貼現期間是「貼現日到到期日」的剩餘期間,不是持有期間,要用 6 個月減掉剩餘 4 個月才是持有 2 個月。", "distractors": {"A": "持有 1 個月,貼現期間會是 5 個月,貼現息應為 265,200×6%×5/12=6,630,與題目不符。", "C": "持有 3 個月,貼現期間會是 3 個月,貼現息=3,978,與題目不符。", "D": "持有 4 個月,貼現期間 2 個月,貼現息=2,652,與題目不符;容易把貼現期間 4 個月誤當持有期間。"}}, "check": "python:到期值265,200;貼現息5,304;t=5304/(265200×0.06)=0.3333年=4個月;持有2個月→6/1,與官方 B 相符。", "verified": true, "note": ""}, {"id": "114-3-A-16", "exam": "114-3", "paper": "A", "q": 16, "unit": "十三、存貨", "topic": "期末存貨範圍", "stem": "小朵公司於民國 114 年底有各項存貨資料,下列項目何者不應包括在期末存貨中?", "options": ["購入起運點交貨之在途商品,期末尚未抵達本公司", "寄銷在他公司之未出售寄銷品", "存放於本公司倉庫內的承銷品", "銷售目的地交貨之在途商品,期末尚未抵達買方公司"], "answer": "C", "figure": null, "official": "存放於本公司倉庫內的承銷品,商品所有權屬於寄銷人,故不屬於本公司所擁有之存貨。", "explain": {"concept": "存貨範圍看「所有權」:所有權屬於本公司者,就算不在倉庫也要列入;不屬於本公司的,就算在倉庫也不列入。", "steps": ["判斷標準是「商品所有權」。", "(A) 起運點交貨:貨一出賣方的門,所有權就歸買方,在途也是買方存貨,應包括。", "(B) 寄銷品(寄在別人那邊):所有權還是本公司的,應包括。", "(C) 承銷品:本公司是代人家賣,所有權屬於寄銷人,本公司不能列為存貨。這就是答案。", "(D) 目的地交貨:貨到目的地才轉移所有權,在途中仍是賣方(本公司)的,應包括。"], "pitfalls": "「放在我倉庫」不等於「是我的存貨」,要看所有權在誰手上。", "distractors": {"A": "起運點交貨,所有權已歸本公司,應包括。", "B": "寄銷品所有權仍屬本公司,應包括。", "D": "目的地交貨,所有權仍在賣方(本公司),應包括。"}}, "check": "概念題:與官方詳解及存貨所有權原則一致。", "verified": true, "note": ""}, {"id": "114-3-A-17", "exam": "114-3", "paper": "A", "q": 17, "unit": "十三、存貨", "topic": "先進先出法期末存貨成本", "stem": "小桃公司民國 114 年期初存貨成本$1,000(250 件),年中共進貨三次,第一次進貨 350 件@$5,第二次進貨 400 件@$6,第三次進貨 200 件@$7,本年度共銷售 900 件商品,有關存貨成本流動假設採先進先出法計算,若本年無商品盈虧且不考慮後續衡量情況下,則期末存貨金額為何?", "options": ["$1,550", "$1,637", "$1,650", "$2,000"], "answer": "D", "figure": null, "official": "期末存貨數量=250+350+400+200-900=300 件;先進先出,期末存貨為最後進貨者:100×$6+200×$7=$2,000。", "explain": {"concept": "先進先出法(FIFO):先買的先賣掉,所以期末剩下的是「最近買的」。", "steps": ["先算期末存貨數量=期初 250+進貨 350+400+200-銷貨 900=300 件。", "FIFO 先賣最早的貨,所以期末的 300 件是最後進的貨:先取最後一批 200 件@$7,再從第二批取 100 件@$6。", "期末存貨金額=200×7+100×6=1,400+600=$2,000,選 D。"], "pitfalls": "FIFO 期末存貨用「最新進價」,別拿最早的(期初、@5)來算。", "distractors": {"B": "1,637 約為加權平均法:總成本 6,550÷1,200 件≈5.46,再乘 300 件,不是先進先出。"}}, "check": "python:數量300;100×6+200×7=2,000,與官方 D 相符。", "verified": true, "note": ""}, {"id": "114-3-A-18", "exam": "114-3", "paper": "A", "q": 18, "unit": "十三、存貨", "topic": "成本與淨變現價值孰低法", "stem": "小蘇公司成立於民國 113 年初,113~114 年底存貨成本與淨變現價值資料如下:\n\n| 日期 | 成本 | 淨變現價值 |\n|---|---|---|\n| 113 年 12 月 31 日 | $150,000 | $145,000 |\n| 114 年 12 月 31 日 | $192,000 | $190,000 |\n\n若以「成本與淨變現價值孰低法」衡量期末存貨,則民國 114 年底存貨評價分錄應借記為何?", "options": ["備抵存貨跌價$3,000", "銷貨成本$3,000", "備抵存貨跌價$5,000", "銷貨成本$5,000"], "answer": "A", "figure": null, "official": "113 年底備抵存貨跌價餘額 5,000;114 年底應有 2,000;調整減少 3,000:借 備抵存貨跌價 3,000,貸 銷貨成本 3,000。", "explain": {"concept": "成本與淨變現價值孰低法:期末應有的備抵存貨跌價=成本-淨變現價值,和帳上舊餘額比較,差額為本期調整數。", "steps": ["113 年底:成本 150,000>淨變現價值 145,000,存貨跌價 5,000,備抵存貨跌價期末餘額 $5,000(貸方)。", "114 年底:成本 192,000>淨變現價值 190,000,應有備抵存貨跌價=192,000-190,000=$2,000。", "帳上已有 5,000,應有 2,000,要減少 5,000-2,000=$3,000(回升)。", "要把貸方餘額減少,就要借記備抵存貨跌價 3,000;對方貸記銷貨成本 3,000(跌價回升使成本減少)。", "所以借記的是「備抵存貨跌價 $3,000」,選 A。"], "pitfalls": "要看前一年已提列的備抵餘額,只算本年差額,不是直接認列 2,000 或 5,000。", "distractors": {"B": "借銷貨成本 3,000 是方向錯誤;回升時銷貨成本是貸方。", "C": "以 113 年的 5,000 當本期調整數,忘了 114 年底應有 2,000。", "D": "同 C,且科目也錯。"}}, "check": "python:5,000-2,000=3,000(借備抵存貨跌價),與官方 A 相符。", "verified": true, "note": ""}, {"id": "114-3-A-19", "exam": "114-3", "paper": "A", "q": 19, "unit": "十四、證券投資", "topic": "透過損益按公允價值衡量之金融資產", "stem": "小衍公司將股票投資分類為透過損益按公允價值衡量之金融資產,有關此類股票投資之敘述,下列何者正確?", "options": ["對被投資公司不具重大影響力,則期末應採權益法衡量", "屬於權益證券投資,收到現金股利,應貸記:股利收入", "購買股票投資時的手續費,應計入金融資產的成本", "此股票投資若預計於一年以內出售,則列為非流動資產"], "answer": "B", "figure": null, "official": "(A)不具重大影響力,期末應採公允價值法衡量;(C)購買手續費應認列為手續費支出;(D)預計一年內出售則列為流動資產。", "explain": {"concept": "透過損益按公允價值衡量(FVTPL)金融資產的衡量與表達:期末按公允價值、交易成本費用化、股利記收入。", "steps": ["(A) 此類投資期末本來就是按公允價值衡量,權益法是用於有重大影響力(持股約 20%以上)的情況,所以錯。", "(B) 收到現金股利:借 現金,貸 股利收入,正確。", "(C) FVTPL 的交易手續費不計入成本,直接記「手續費支出」,所以錯。", "(D) 預計一年內出售屬流動資產,不是非流動,所以錯。", "因此選 (B)。"], "pitfalls": "FVTPL 的手續費是當期費用,不要加進投資成本(這與透過其他綜合損益按公允價值衡量不同)。", "distractors": {"A": "權益法是用於有重大影響力的投資;FVTPL 期末採公允價值。", "C": "手續費要費用化(手續費支出)。", "D": "一年內要處分,列為流動資產。"}}, "check": "概念題:與官方詳解及 IFRS 9 的處理一致。", "verified": true, "note": ""}, {"id": "114-3-A-20", "exam": "114-3", "paper": "A", "q": 20, "unit": "十四、證券投資", "topic": "FVTPL 股票投資淨損益", "stem": "大福公司民國 114 年初以每股$30 購入小島公司所發行普通股 5,000 股,大福公司持有股票投資分類為持有供交易目的,且對被投資公司不具重大影響力,購入時支付手續費$3,000,年中曾收到 10%股票股利,年底以每股$24 將小島公司股票全部出售,並支付手續費$2,000,本年度投資股票所產生之淨損益金額共計多少?", "options": ["費損$23,000", "費損$10,000", "費損$5,000", "$0"], "answer": "A", "figure": null, "official": "購入手續費3,000記費用;股票股利不作分錄只記備忘股數,5,500股;年底評價損失=5,500×24-150,000=-18,000;處分手續費2,000;淨損益=-3,000-18,000-2,000=-23,000。", "explain": {"concept": "持有供交易目的股票:購入手續費費用化;股票股利不作分錄但股數增加、每股成本降低;期末(出售前)按公允價值評價。", "steps": ["購入成本=5,000股×$30=$150,000,手續費 $3,000 直接記費用。", "收到 10% 股票股利:不作分錄,只備忘股數增為 5,000×1.1=5,500 股,總成本仍是 $150,000。", "年底以每股 24 賣出,出售前先評價:公允價值=5,500×24=$132,000,與帳面 150,000 比,損失=150,000-132,000=$18,000。", "出售時支付手續費 $2,000,也記費用。", "本年度淨損益=-3,000(購入手續費)-18,000(評價損失)-2,000(出售手續費)=-$23,000,是「費損 $23,000」,選 A。"], "pitfalls": "股票股利不是收益,但股數變多;別忘了購入與出售兩次手續費都要算。", "distractors": {"C": "只算了手續費 3,000+2,000=5,000,漏掉股價下跌的評價損失 18,000。"}}, "check": "python:5,500×24=132,000;150,000-132,000=18,000;-3,000-18,000-2,000=-23,000,與官方 A 相符。", "verified": true, "note": ""}, {"id": "114-3-A-21", "exam": "114-3", "paper": "A", "q": 21, "unit": "十五、長期營業用資產", "topic": "土地取得成本", "stem": "纍纍與兩位合夥人經營後決定放棄承租店面,改以現金$2,000,000 購入一筆房地產做為營業用店面,另支付仲介佣金$8,000,隨即再給付$40,000 拆除舊屋費用以便重蓋房屋作為新店使用,舊屋無殘料收入,則土地入帳成本為何?", "options": ["$1,968,000", "$2,008,000", "$2,040,000", "$2,048,000"], "answer": "D", "figure": null, "official": "土地成本=2,000,000+8,000+40,000=2,048,000。", "explain": {"concept": "不動產取得成本=購價+使資產達可使用狀態的必要支出;買地後拆舊屋的費用要加在土地成本。", "steps": ["購入房地產現金價款 $2,000,000,是土地成本的基礎。", "仲介佣金 $8,000:取得土地的必要支出,加入土地成本。", "拆除舊屋費用 $40,000:是為了重蓋新屋才拆,舊屋沒有殘料收入可抵,拆除費用加入土地成本。", "土地入帳成本=2,000,000+8,000+40,000=$2,048,000,選 D。"], "pitfalls": "買地後為了蓋新屋而拆舊屋的費用,算土地成本,不是費用,也不是房屋成本。", "distractors": {"B": "只加了仲介佣金 8,000,漏掉拆除舊屋費用 40,000。", "C": "只加了拆除費用 40,000,漏掉仲介佣金 8,000。", "A": "把 8,000 與 40,000 當成減項,加減方向錯。"}}, "check": "python:2,000,000+8,000+40,000=2,048,000,與官方 D 相符。", "verified": true, "note": ""}, {"id": "114-3-A-22", "exam": "114-3", "paper": "A", "q": 22, "unit": "十五、長期營業用資產", "topic": "自建資產與減損", "stem": "纍纍計算自建營業用店面,共耗費直接材料$800,000、直接人工$1,000,000、其他製造費用$500,000 及建造期間資本化利息$20,000。若可回收金額為$2,000,000,則應認列自建資產損益為下列何者?", "options": ["自建利益$320,000", "減損損失$320,000", "自建利益$400,000", "減損損失$400,000"], "answer": "B", "figure": null, "official": "自建成本=800,000+1,000,000+500,000+20,000=2,320,000;大於可回收金額2,000,000,故認列減損損失320,000。", "explain": {"concept": "自建資產成本包含直接材料、人工、製造費用及建造期間資本化利息;若帳面金額高於可回收金額,要認列減損損失。", "steps": ["先算自建資產成本=800,000+1,000,000+500,000+20,000=$2,320,000(利息在建造期間可資本化,要加進去)。", "比較可回收金額:2,320,000 > 2,000,000,資產「價值縮水」,要認列減損。", "減損損失=2,320,000-2,000,000=$320,000,選 B。", "注意:自建資產不會有「自建利益」,因為成本就是入帳基礎,不能自己認列利潤。"], "pitfalls": "自建資產以成本入帳,不認列利益;資本化利息要加入成本,漏加會算成 300,000。", "distractors": {"A": "自建資產以成本入帳,不會認列「自建利益」;成本高於可回收金額應是減損損失。", "C": "同 A,自建資產不認列利益;400,000 也不是正確的差額。"}}, "check": "python:800,000+1,000,000+500,000+20,000=2,320,000;2,320,000-2,000,000=320,000,與官方 B 相符。", "verified": true, "note": ""}, {"id": "114-3-A-23", "exam": "114-3", "paper": "A", "q": 23, "unit": "十五、長期營業用資產", "topic": "多項設備折舊(平均法與年數合計法)", "stem": "纍纍負責阿拉纍幸福早午餐店的財務管理工作,對公司內不同種類的不動產廠房及設備擬定不同折舊計算政策,每月 15 日以前購入,當月折舊全部計算;每月 16 日後購入,當月折舊不予計入,阿拉纍幸福早午餐店內各種設備資料及採用的折舊方法如表(一),則 113 年度阿拉纍幸福早午餐店設備應提列折舊共計多少?\n\n表(一)\n\n| 名稱 | 烹調設備 | 飲料製作設備 | 用餐設備 | 儲存設備 | 其他設備 |\n|---|---|---|---|---|---|\n| 購入日期 | 112.10.1 | 112.11.1 | 112.12.24 | 112.12.26 | 112.12.28 |\n| 成本 | $250,000 | $130,000 | $200,000 | $150,000 | $90,000 |\n| 殘值 | 無殘值 | $10,000 | 無殘值 | 無殘值 | 無殘值 |\n| 耐用年限 | 10 年 | 6 年 | 4 年 | 5 年 | 6 年 |\n| 折舊方法 | 平均法 | 平均法 | 年數合計法 | 年數合計法 | 平均法 |", "options": ["$135,000", "$158,000", "$190,000", "$200,000"], "answer": "C", "figure": null, "official": "烹調25,000;飲料20,000;用餐200,000×4/10=80,000;儲存150,000×5/15=50,000;其他15,000;合計190,000。", "explain": {"concept": "各設備 113 年均為完整一年;平均法每年折舊=(成本-殘值)÷年限;年數合計法第一年用「耐用年限÷年數總和」。", "steps": ["112 年底前購入的設備,到 113 年都已使用整整一年,所以 113 年全年折舊。其中 112.12.24、26、28 都是 16 日後購入,112 年不提折舊,所以 113 年是第一個折舊年度(年數合計法第 1 年)。", "烹調設備(平均法):(250,000-0)÷10=$25,000。", "飲料設備(平均法):(130,000-10,000)÷6=$20,000。", "用餐設備(年數合計法,4 年):年數總和=4+3+2+1=10,第 1 年=200,000×4/10=$80,000。", "儲存設備(年數合計法,5 年):年數總和=15,第 1 年=150,000×5/15=$50,000。", "其他設備(平均法):90,000÷6=$15,000。", "合計=25,000+20,000+80,000+50,000+15,000=$190,000,選 C。"], "pitfalls": "年數合計法第一年用最大的分子(年限本身),不是最小;也要注意年數合計法是用「成本-殘值」去乘分數。", "distractors": {}}, "check": "python:25,000+20,000+80,000+50,000+15,000=190,000,與官方 C 相符。", "verified": true, "note": ""}, {"id": "114-3-A-24", "exam": "114-3", "paper": "A", "q": 24, "unit": "十五、長期營業用資產", "topic": "設備處分與折舊方法變更", "stem": "拉拉負責店內新商品菜色餐點的研發,近來發現店內健康蔬果餐深受顧客喜愛,新鮮蔬果進貨量也日益增加,需要更大的儲存設備供蔬果儲存保鮮,原儲存設備於 114 年初估計剩餘耐用年限 4 年,無殘值,並改採直線法提列折舊,但因原本的設備儲存空間不足,故提早於 114 年 7 月 1 日以$100,000 出售並更換大型儲存設備,則出售儲存設備處分損益金額為何?\n\n(原題屬第 21~24 題題組,儲存設備資料見第 23 題表(一):112.12.26 購入、成本$150,000、無殘值、耐用 5 年、年數合計法。)", "options": ["損失$15,000", "損失$18,000", "利益$12,500", "利益$20,000"], "answer": "C", "figure": null, "official": "113 年折舊 150,000×5/15=50,000;114 年初帳面金額 100,000,剩餘耐用年限 4 年,改採直線法,114/1/1~7/1 折舊=100,000/4×6/12=12,500;累計折舊=62,500,帳面金額 87,500;處分利益=100,000-87,500=12,500。", "explain": {"concept": "處分利益(損失)=處分價款-處分日帳面金額;要先把出售前的折舊補提到處分日。", "steps": ["題目資料(接 23 題的儲存設備):成本 $150,000,無殘值,5 年,年數合計法,112.12.26 購入。113 年折舊 150,000×5/15=$50,000。", "114 年初帳面金額=150,000-50,000=$100,000。", "題目說 114 年初估計剩餘耐用年限 4 年、無殘值,改採直線法,所以 114 年每年折舊=100,000÷4=$25,000。", "處分日是 7/1,要先補提 114 年 1/1~7/1 共 6 個月折舊=25,000×6/12=$12,500。", "處分日累計折舊=50,000+12,500=$62,500;帳面金額=150,000-62,500=$87,500。", "處分損益=售價 100,000-帳面金額 87,500=$12,500(利益),選 C。"], "pitfalls": "出售前一定要先提列當年度到處分日的折舊;會計估計變更用「剩餘帳面金額÷剩餘年限」往後計算。", "distractors": {"D": "繼續用年數合計法算 114 年折舊:150,000×4/15×6/12=20,000,累計折舊 70,000,帳面 80,000,利益 20,000;但題目已說明 114 年初改採直線法。"}}, "check": "python:113年50,000;114/1/1帳面100,000;100,000/4×6/12=12,500;帳面87,500;利益12,500,與官方 C 相符。", "verified": true, "note": "本題接第23題儲存設備資料,已在題幹末補註說明(原題未重複列出);單元歸十五。"}, {"id": "114-4-A-01", "exam": "114-4", "paper": "A", "q": 1, "unit": "一、會計基本概念", "topic": "商業會計法規與準則", "stem": "大洋股份有限公司已成立 2 年,主要營業項目為 AR 智慧眼鏡製造與銷售,其主管機關為經濟部。該公司的下列帳務處理,哪幾項處理不符合我國目前商業會計法規及會計準則?\n①委託記帳士記帳,並請該記帳士簽證財務報表\n②財務報表的格式,採二年度對照方式編製\n③會計憑證與交易記錄完整,會計帳簿僅需設置普通日記簿,得省略總分類帳\n④賒購 AR 智慧眼鏡研發設備$1,500,000,以新臺幣現鈔一次償還,以便取得現金折扣", "options": ["僅①②", "僅②③", "僅①③④", "僅②③④"], "answer": "C", "figure": null, "official": "①記帳士無簽證財務報表資格;③不能省略總分類帳;④超過$1,000,000 不得以新臺幣現鈔支付。②二年度對照式正確。", "explain": {"concept": "考商業會計法的基本規定:誰能簽證、帳簿一定要有哪些、現金支付的金額上限。", "steps": ["先看①:股份有限公司若非公開發行,有些情況可由會計師簽證,但『記帳士』只能代為記帳,不能簽證財務報表,所以①不符合。", "看②:財務報表採「本年度與上年度對照」的二年度對照方式,這是正確的,符合規定。", "看③:帳簿一定要有「日記簿」和「總分類帳」兩種主要帳簿,不能只設普通日記簿而省略總分類帳,所以③不符合。", "看④:商業會計法規定,超過 $1,000,000 的交易不能用新臺幣現鈔支付(要用支票、匯款等),所以以現鈔一次償還 $1,500,000 不符合。", "不符合的是①③④,答案選 (C)。"], "pitfalls": "記帳士和會計師的權限容易搞混:記帳士只能記帳、不能簽證。另外二年度對照式是正確的,別因為看起來特別就誤判成錯。", "distractors": {"A": "把②當成錯誤,且漏掉③④,對財報二年度對照格式不熟。", "B": "誤把②當錯,且漏掉①④。", "D": "把②當錯誤,又漏掉①(不知道記帳士不能簽證)。"}}, "check": "逐項對照官方詳解:①③④ 不符合、② 符合,與答案 C 一致。", "verified": true, "note": ""}, {"id": "114-4-A-02", "exam": "114-4", "paper": "A", "q": 2, "unit": "一、會計基本概念", "topic": "會計基本假設", "stem": "有關會計基本假設,下列敘述哪幾項正確?\n①興台公司新聘很有管理聲望的總經理,會計帳上無法將此人力資源的提升予以入帳\n②旺台公司營業用土地期末應以清算價值列示其帳面金額,以顯示土地的真實價值\n③臺灣的台棒公司商品全部銷往美國,財務報表應以美元列示\n④春嬌獨資的商店,由業主自負盈虧,因此業主自商店提領商品回家自用時,不必入帳", "options": ["僅①", "僅②④", "僅③④", "①②③"], "answer": "A", "figure": null, "official": "②根據繼續經營假設,營業用土地不以清算價值列示;③財務報表應以新臺幣列示(貨幣單位假設);④企業個體假設,業主與企業交易仍應入帳。", "explain": {"concept": "考會計基本假設:企業個體、繼續經營、會計期間、貨幣計量(貨幣單位)。", "steps": ["①:人力資源的價值無法用貨幣客觀衡量,依貨幣計量假設,不入帳,所以正確。", "②:依「繼續經營假設」,企業會一直經營下去,營業用土地用成本(帳面金額)列示,不是用清算價值,所以錯誤。", "③:我國企業財務報表要以新臺幣列示,不能因為銷往美國就改用美元,所以錯誤。", "④:依「企業個體假設」,企業和業主是分開的個體,業主提領商品自用要入帳(如:借 業主往來/資本,貸 進貨/存貨),所以錯誤。", "只有①正確,答案選 (A)。"], "pitfalls": "獨資業主雖然自負盈虧,但會計上仍把企業與業主分開看,提領要入帳。", "distractors": {"B": "認為清算價值才是真實價值,且認為獨資提領不必入帳,混淆繼續經營與企業個體假設。", "C": "以為外銷就用美元列示,且誤以為獨資不必入帳。", "D": "相信②③,忽略繼續經營假設與新臺幣列示的規定。"}}, "check": "概念題,對照官方詳解與會計基本假設,結果一致。", "verified": true, "note": ""}, {"id": "114-4-A-03", "exam": "114-4", "paper": "A", "q": 3, "unit": "四、分錄與日記簿", "topic": "傳票與交易判斷", "stem": "小明設立漂漂公司,經營美妝商品的銷售,商品盤存制度採永續盤存制,傳票採複式傳票三分法,下列敘述哪幾項正確?\n①業務部門經審核後,本日自倉庫提領一批試用品,沿街發送給遊客,不屬於交易不必編製傳票\n②5 日前賒購商品,本日以現金支付款項,取得 1%現金折扣,本日編製轉帳傳票\n③顧客大興商店交來訂金,訂購 100 瓶美妝商品,此交易導致資產增加、合約負債增加\n④公司遭逢水災,盤點倉庫的原料、物料,因泡水喪失 50%價值,導致權益增加、資產減少", "options": ["僅①③", "僅②③", "僅②④", "僅①③④"], "answer": "B", "figure": null, "official": "①應編製轉帳傳票(借:廣告費、貸:存貨);②借:應付帳款、貸:存貨、現金,應編轉帳傳票;③借:現金、貸:預收貨款(合約負債),資產增加、負債增加;④水災損失使費損增加、權益減少、資產減少。", "explain": {"concept": "考「傳票三分法」(現金收入、現金支出、轉帳傳票)與交易對會計等式的影響。", "steps": ["①:提領試用品發送給遊客,存貨減少、廣告費增加,是交易,要編轉帳傳票(借:廣告費,貸:存貨),所以①錯誤。", "②:賒購時是借存貨、貸應付帳款;5 日後付款並取得折扣,借:應付帳款,貸:現金及存貨(進貨折扣)。這筆同時有現金與非現金科目,依三分法屬於轉帳傳票,所以②正確。", "③:顧客交訂金,借:現金,貸:預收貨款(合約負債),資產增加、負債增加,所以③正確。", "④:水災損失,借:水災損失(其他損失),貸:存貨,費損增加導致權益『減少』、資產減少,不是權益增加,所以④錯誤。", "正確的是②③,答案選 (B)。"], "pitfalls": "發送試用品別以為『沒收錢就不是交易』,只要資產減少、費用增加就是交易。損失會讓權益減少。", "distractors": {"A": "認為①不是交易,實際上提領試用品要轉為廣告費。", "C": "②對,但把水災損失當成權益增加,方向看反了。", "D": "同時誤判①④。"}}, "check": "逐項分析分錄,與官方答案 B 一致。", "verified": true, "note": ""}, {"id": "114-4-A-04", "exam": "114-4", "paper": "A", "q": 4, "unit": "六、試算與試算表", "topic": "錯誤對餘額式試算表影響", "stem": "會計主管查核試算表時發現下列錯誤:\n①現收利息$1,000,日記簿上誤記為現收佣金$100\n②償還商品的帳款$4,000,分錄正確但過帳時會計項目借貸方向相反\n以上兩項錯誤對餘額式試算表的影響為何?", "options": ["借貸方餘額合計均無影響", "借貸方餘額合計均多計$7,100", "借貸方餘額合計均多計$8,000", "借貸方餘額合計均多計$8,900"], "answer": "B", "figure": null, "official": "逐科目比較正確與錯誤餘額後,借方與貸方各多計 $7,100。", "explain": {"concept": "餘額式試算表比較各帳戶『餘額』。錯誤使某些帳戶餘額改變,要把每一個帳戶的影響算出來,再加總借方與貸方。", "steps": ["先看①(正確 vs 錯誤):正確是借:現金 1,000、貸:利息收入 1,000;錯誤是借:現金 100、貸:佣金收入 100。所以現金(借方餘額)少計 $900,利息收入(貸方餘額)少計 $1,000,佣金收入(貸方餘額)多計 $100。", "再看②:正確是借:應付帳款 4,000、貸:現金 4,000;過帳方向相反成了貸:應付帳款 4,000、借:現金 4,000。每個帳戶相對正確數相差 $8,000(從少4,000變成多4,000):應付帳款貸方餘額多計 $8,000,現金借方餘額多計 $8,000。", "借方餘額合計影響 = 現金 少計 900 + 現金 多計 8,000 = 多計 $7,100。", "貸方餘額合計影響 = 利息收入 少計 1,000 + 佣金收入 多計 100 + 應付帳款 多計 8,000 = 多計 $7,100。", "借貸各多計 $7,100,仍然平衡,答案選 (B)。"], "pitfalls": "『借貸方向相反』的錯誤影響是兩倍金額(8,000,不是 4,000),很多人只算 4,000。", "distractors": {"A": "以為借貸對稱錯誤就不影響合計,但其實餘額的合計金額已經改變(只是仍平衡)。", "C": "只算②的 $8,000,忽略①的影響。", "D": "①的影響方向算反:$8,000 + $900 = $8,900。"}}, "check": "python 計算:借方 -900+8000=7100;貸方 -1000+100+8000=7100。與答案相符。", "verified": true, "note": ""}, {"id": "114-4-A-05", "exam": "114-4", "paper": "A", "q": 5, "unit": "七、調整", "topic": "前期錯誤對損益及保留盈餘影響", "stem": "天地公司商品盤存制度採定期盤存制,會計人員發現 X1 年度及 X2 年底調整後帳務有下列錯誤:\n\n| 項目 | X1 年底 | X2 年底 |\n|---|---|---|\n| ①預收租金 | 低估 $2,000 | 高估 $700 |\n| ②期末存貨 | 低估 3,000 | 高估 4,000 |\n| ③折舊 | 低估 100 | 低估 300 |\n\n以上三項錯誤對 X2 年度本期淨利及 X2 年底保留盈餘的影響,下列何者正確?", "options": ["X2 年度本期淨利高估$3,600", "X2 年度本期淨利低估$9,400", "X2 年底保留盈餘高估$4,600", "X2 年底保留盈餘高估$3,700"], "answer": "D", "figure": null, "official": "三項錯誤合計:X2 本期淨利高估 $4,600;X2 年底保留盈餘高估 $3,700。", "explain": {"concept": "跨年度錯誤:去年底的錯誤會影響今年期初;今年淨利=今年底錯誤的影響 - 去年底錯誤的影響。年底保留盈餘則只看累積效果。", "steps": ["①預收租金(負債):X1 年底低估 $2,000→X1 收入多算 $2,000(淨利高估);X2 年期初負債少,X2 淨利低估 $2,000。X2 年底高估 $700→X2 收入少算 $700,淨利低估 $700。X2 淨利影響 = -2,000 -700 = 低估 $2,700;X2 年底保留盈餘 = 負債高估 $700 → 低估 $700。", "②期末存貨:X1 年底低估 $3,000→X2 期初存貨少,X2 銷貨成本少算 → X2 淨利高估 $3,000。X2 年底高估 $4,000→X2 銷貨成本少算 → 淨利高估 $4,000。X2 淨利影響 = 高估 $7,000;X2 年底保留盈餘 = 存貨高估 $4,000 → 高估 $4,000。", "③折舊(費用)低估:每年費用少算只影響當年淨利。X2 淨利高估 $300(X1 的 $100 只影響 X1)。到 X2 年底,累計少提 $100+$300,保留盈餘高估 $400。", "加總 X2 本期淨利:-2,700 + 7,000 + 300 = 高估 $4,600。", "加總 X2 年底保留盈餘:-700 + 4,000 + 400 = 高估 $3,700,答案選 (D)。"], "pitfalls": "期末存貨的錯誤有『兩年影響會抵銷』的特性,別把淨利和保留盈餘搞混。預收租金是負債,高估負債 → 收入少 → 淨利低估。", "distractors": {"A": "沒算出 $4,600 的正確淨利影響。", "B": "方向或項目算錯(如把預收租金方向看反)。", "C": "把『淨利高估 $4,600』誤當成保留盈餘的影響,混淆兩個問題。"}}, "check": "python 驗算:淨利 -2700+7000+300=+4600;保留盈餘 -700+4000+400=+3700,與官方表一致。", "verified": true, "note": ""}, {"id": "114-4-A-06", "exam": "114-4", "paper": "A", "q": 6, "unit": "七、調整", "topic": "漏記調整分錄對流動資產影響", "stem": "風信商店屬於買賣業,記帳基礎採記虛轉實,本年底漏做下列四項調整分錄:①12 月份應付員工薪資$50,000、②應收帳款之預期信用減損損失$20,000、③專利權攤銷$3,000、④去年底盤點尚未使用之文具用品金額為$300,本年度共購入文具用品$1,000,本年底盤點尚未使用之文具用品金額為$500。補作以上四項調整分錄後,對本年底流動資產總額的影響金額為何?", "options": ["減少$19,800", "減少$20,200", "減少$23,200", "減少$73,200"], "answer": "A", "figure": null, "official": "①無影響;②減少$20,000;③無影響;④增加$200;合計減少$19,800。", "explain": {"concept": "調整分錄只有動到『流動資產科目』才會影響流動資產總額。要逐項看調整分錄的借貸科目。", "steps": ["①應付薪資:借:薪資支出 50,000、貸:應付薪資 50,000,只動費用與負債,對流動資產沒有影響。", "②預期信用減損:借:預期信用減損損失 20,000、貸:備抵損失-應收帳款 20,000,備抵損失是應收帳款的減項,使流動資產減少 $20,000。", "③專利權攤銷:借:各項攤銷 3,000、貸:累計攤銷-專利權 3,000,專利權是非流動資產,對流動資產無影響。", "④文具用品採記虛轉實(購買時記費用):期末應有盤存 $500,而帳上有去年底的 $300,所以只需補增加 $200。分錄:借:用品盤存 200、貸:文具用品 200,流動資產增加 $200。", "合計:0 - 20,000 + 0 + 200 = 減少 $19,800,答案選 (A)。"], "pitfalls": "④要扣掉帳上原有的期初盤存 $300,只調整差額 $200,不是 $500。", "distractors": {"B": "把④當成減少 $200,符號反了。", "C": "把③攤銷 $3,000 也算進流動資產。", "D": "把①應付薪資 $50,000 也算進流動資產減少。"}}, "check": "-20,000 + (500-300) = -19,800,與官方相符。", "verified": true, "note": ""}, {"id": "114-4-A-07", "exam": "114-4", "paper": "A", "q": 7, "unit": "八、結帳", "topic": "結帳程序", "stem": "有關結帳之會計程序,下列敘述何者正確?", "options": ["完成結帳程序之後,才能進行調整程序", "「預收租金」項目會出現在結帳後試算表", "虛帳戶以及實帳戶的結帳,必定在日記簿做成結帳分錄", "將「銷貨成本」項目轉入「本期損益」的結帳分錄,應借:「銷貨成本」、貸:「本期損益」"], "answer": "B", "figure": null, "official": "(A)先調整後結帳;(C)實帳戶可採分錄結帳或在分類帳上採英式結轉;(D)應借:本期損益、貸:銷貨成本。", "explain": {"concept": "考結帳的順序與分錄方向:先調整、再結帳;虛帳戶結清,實帳戶結轉餘額。", "steps": ["(A):順序是先調整、再結帳,不是反過來,所以錯。", "(B):預收租金是負債(實帳戶),結帳後不會被結清,所以會出現在結帳後試算表,正確。", "(C):虛帳戶一定要用結帳分錄結清,但實帳戶可以用分錄結帳,也可以在分類帳上直接用英式結轉(不一定要分錄),所以『必定』太絕對,錯。", "(D):銷貨成本是費損類,結帳時要貸記它使餘額歸零,借記本期損益,所以方向是借:本期損益、貸:銷貨成本,原敘述相反。", "答案選 (B)。"], "pitfalls": "結帳分錄方向:費損類要『貸』才能結清;收入類要『借』才能結清。", "distractors": {"A": "順序顛倒。", "C": "沒注意實帳戶可以用英式結轉不必做分錄。", "D": "費用類科目結帳要貸記,不是借記,方向看反。"}}, "check": "概念題,與官方詳解一致。", "verified": true, "note": ""}, {"id": "114-4-A-08", "exam": "114-4", "paper": "A", "q": 8, "unit": "九、財務報表", "topic": "綜合損益表項目計算", "stem": "大名獨資經營名興商店,屬於買賣業,X2 年度銷貨毛利率為 40%,損益各帳戶餘額如下:\n\n| 項目 | 金額 | 項目 | 金額 |\n|---|---|---|---|\n| 銷貨收入 | $800,000 | 銷貨成本 | $ ? |\n| 薪資支出 | 100,000 | 水電瓦斯費 | 48,000 |\n| 文具用品 | 2,000 | 運費 | 4,000 |\n| 其他費用 | 6,000 | 其他損失 | 1,000 |\n| 預期信用減損利益 | 2,000 | 利息收入 | 9,000 |\n\n名興商店編製的 X2 年度綜合損益表之項目金額,下列何者正確?", "options": ["銷貨成本$320,000", "營業費用$162,000", "營業利益$162,000", "所得稅費用$25,000"], "answer": "C", "figure": null, "official": "銷貨成本=$480,000;營業費用=$158,000;營業利益=$162,000;獨資企業不計所得稅費用。", "explain": {"concept": "毛利率=毛利÷銷貨收入。營業利益=毛利-營業費用。獨資不繳營利事業所得稅。預期信用減損『利益』是營業費用的減項。", "steps": ["銷貨成本 = 銷貨收入 ×(1 - 毛利率)= $800,000 ×(1 - 40%)= $480,000。", "營業費用(薪資、水電、文具用品、運費、其他費用都是營業費用;預期信用減損利益是減項,要扣掉):$100,000 + $48,000 + $2,000 + $4,000 + $6,000 - $2,000 = $158,000。", "營業毛利 = $800,000 × 40% = $320,000。", "營業利益 = $320,000 - $158,000 = $162,000,所以 (C) 正確。", "其他損失與利息收入屬營業外項目,不影響營業利益。獨資企業沒有所得稅費用,所以 (D) 錯。"], "pitfalls": "預期信用減損利益是『減項』;(A) 的 $320,000 是毛利,不是銷貨成本。", "distractors": {"A": "把毛利 $320,000 誤當成銷貨成本。", "B": "把預期信用減損利益加進營業費用(100,000+48,000+2,000+4,000+6,000+2,000=162,000),符號弄反。", "D": "忘了獨資不用繳營利事業所得稅。"}}, "check": "python 驗算:COGS=480000;營業費用=158000;營業利益=800000*0.4-158000=162000,相符。", "verified": true, "note": ""}, {"id": "114-4-A-09", "exam": "114-4", "paper": "A", "q": 9, "unit": "十、加值型營業稅會計實務", "topic": "營業稅額計算", "stem": "竹光公司屬於加值型營業人,適用 5%營業稅稅率,會計阿文每 2 個月到國稅局申報營業稅。本期交易資料如下:三聯式發票銷售額$3,000,000(包含預收訂金$20,000),稅額$150,000。二聯式發票銷售額$189,000(含稅)。經海關出口外銷銷售額$630,000。進貨$2,250,000,稅額$112,500。另有交際費$36,000,稅額$1,800。購置機器設備$816,000,稅額$40,800;購置員工九人座交通車$600,000,稅額$30,000。銷貨退回及折讓$60,000,稅額$3,000。進貨退出及折讓$46,000,稅額$2,300。上期累積留抵稅額$100,000。會計阿文應填具的營業人銷售額與稅額申報書(401),有關稅額計算部分,如表(一)。則稅額計算的項目金額,下列何者正確?\n\n表(一)\n\n| 項目 | 稅額 |\n|---|---|\n| 本期(月)銷項稅額合計 | (A) |\n| 得扣抵進項稅額合計 | |\n| 上期(月)累積留抵稅額 | 100,000 |\n| 小計 | |\n| 本期(月)應實繳稅額 | 0 |\n| 本期(月)申報留抵稅額 | (B) |\n| 得退稅限額合計 | (C) |\n| 本期(月)應退稅額 | |\n| 本期(月)累積留抵稅額 | (D) |", "options": ["本期(月)銷項稅額合計$159,000", "本期(月)申報留抵稅額$95,000", "得退稅限額合計$102,300", "本期(月)累積留抵稅額$0"], "answer": "B", "figure": null, "official": "(A)=$156,000;(B)=$95,000;(C)=$72,300;(D)=$22,700。", "explain": {"concept": "營業稅:銷項稅額 - 進項稅額(可扣抵部分)- 留抵。交際費、九人座以下小客車的進項稅額不得扣抵;外銷零稅率;得退稅限額=零稅率銷售額×5% + 固定資產進項稅額。", "steps": ["銷項稅額(A):三聯式 $150,000 + 二聯式含稅 $189,000 ÷ 1.05 × 5% = $9,000,再減銷貨退回折讓稅額 $3,000,外銷為零稅率不計稅:$150,000 + $9,000 - $3,000 = $156,000。", "得扣抵進項稅額:進貨 $112,500 + 機器設備 $40,800 - 進貨退出 $2,300 = $151,000。交際費($1,800)與九人座小客車($30,000)的進項稅額依法不得扣抵。", "申報留抵稅額(B):進項扣抵 + 上期留抵 - 銷項 = $151,000 + $100,000 - $156,000 = $95,000(進項合計超過銷項,所以這期應實繳為 0,產生留抵 $95,000)。", "得退稅限額(C):外銷零稅率銷售額 $630,000 × 5% + 購置機器設備進項稅額 $40,800 = $31,500 + $40,800 = $72,300。", "累積留抵稅額(D):申報留抵稅額 $95,000 - 應退稅額 $72,300 = $22,700。", "所以只有 (B) 正確。"], "pitfalls": "不得扣抵進項(交際費、九人座以下小客車)很容易被誤加;得退稅限額只算零稅率與固定資產兩項。", "distractors": {"A": "$159,000 = $150,000 + $9,000,忘了減銷貨退回折讓稅額 $3,000。", "C": "$102,300 = $72,300 + $30,000,誤把不得扣抵的交通車進項稅額 $30,000 算進得退稅限額。", "D": "以為留抵稅額全部退完。實際上限額只有 $72,300,剩下 $22,700 繼續留抵。"}}, "check": "python 驗算:銷項156000;進項151000;留抵95000;退稅限額72300;累積留抵22700,與官方一致。", "verified": true, "note": ""}, {"id": "114-4-A-10", "exam": "114-4", "paper": "A", "q": 10, "unit": "十一、現金及內部控制", "topic": "現金與內部控制", "stem": "有關公司的現金及內部控制,下列哪幾項錯誤?\n①銀行存給公司的銀行存款對帳單上,銀行將未兌現支票列為銀行存款餘額的減項\n②採零用金制度,每次報銷費用並撥補零用金時,將導致「零用金」帳戶餘額減少\n③公司會計部門將應收帳款及應付帳款明細分類帳,都交由同一會計人員負責記帳\n④9 月 1 日存入的定期存款,在 12 月 31 日有 2 個月到期,此存款列於「按攤銷後成本衡量之金融資產」", "options": ["僅①②", "僅①④", "僅②④", "僅③④"], "answer": "A", "figure": null, "official": "①銀行對帳單上不會出現未兌現支票(它在公司的銀行存款調節表上作為銀行餘額減項);②定額零用金制度下,撥補時零用金帳戶餘額不變。", "explain": {"concept": "考銀行存款調節表與零用金制度(定額預付制)的基本觀念,以及現金約當物的判斷。", "steps": ["①:未兌現支票是公司已開出、銀行尚未付款的支票,銀行還不知道,所以銀行寄來的對帳單上不會出現;它是在公司編製的『銀行存款調節表』上,從銀行對帳單餘額中減除。因此①敘述錯誤。", "②:定額零用金制度下,『零用金』帳戶餘額平常固定不動,撥補時是借:各項費用、貸:現金,零用金帳戶不變,所以『導致零用金餘額減少』錯誤。", "③:題目認為應收帳款與應付帳款明細帳由同一人負責記帳,沒有造成不相容職務(兩者非同一資金流向的收付保管),官方判定屬正確敘述。", "④:9/1 存入的定期存款,到 12/31 還有 2 個月到期,表示總期間是 6 個月,超過 3 個月,不是現金約當物,應列為按攤銷後成本衡量之金融資產,所以正確。", "錯誤的是①②,答案選 (A)。"], "pitfalls": "零用金『定額』制度,零用金帳戶餘額平時不變,別以為報銷就會減少。", "distractors": {"B": "把④當錯,是不熟現金約當物的判斷(原始到期日 3 個月內才算約當現金)。", "C": "沒發現①錯,且誤判④。", "D": "把③當成內控缺失,但官方認為該敘述正確。"}}, "check": "依官方詳解與內部控制/零用金常識確認;③的判斷以官方為準。", "verified": true, "note": ""}, {"id": "114-4-A-11", "exam": "114-4", "paper": "A", "q": 11, "unit": "十二、應收款項", "topic": "現金折扣(淨額法)銷貨收入認列", "stem": "北光公司 5 月份銷貨資料如下:\n5/1 賒銷一批商品$125,000 給新南公司,八折成交,付款條件:3/15,1/20,n/30。5/16 新南公司交來現金以償還半數貨款。5/21 收到現金$24,750,並認列「銷貨收入」$500。5/31 新南公司還清剩餘欠款。則北光公司這批銷貨共應認列「銷貨收入」金額為何?", "options": ["$96,500", "$97,000", "$97,500", "$98,250"], "answer": "D", "figure": null, "official": "5/1 認列 $97,000;5/21 認列 $500;5/31 再認列 $750,合計 $98,250。", "explain": {"concept": "淨額法:銷貨時先扣掉最大折扣(這裡是 3%)入帳;之後若享有的折扣較小或放棄折扣,差額補認列銷貨收入。", "steps": ["先算八折後的貨款:$125,000 × 80% = $100,000。", "5/1 賒銷依淨額法(扣最大折扣 3%)入帳:$100,000 - $100,000 × 3% = $97,000。", "5/16 付半數貨款(在 15 天折扣期內):享有 3% 折扣,與入帳的淨額相同,不用補認列。", "5/21 付款 $24,750:相當於 $25,000 享有 1% 折扣,$25,000 ×(1 - 1%)= $24,750。入帳時是 $25,000 × 97% = $24,250,所以補認列銷貨收入 $24,750 - $24,250 = $500,也就是 $25,000 ×(3% - 1%)。", "5/31 付最後一筆 $25,000(已無折扣):$25,000 -$25,000 × 97% = $750,也就是 $25,000 ×(3% - 0%),補認列銷貨收入 $750。", "合計:$97,000 + $500 + $750 = $98,250,答案選 (D)。"], "pitfalls": "要先算『八折』;折扣用的是淨額法,不要用總額法。最後一筆還清日是放棄折扣,要補認列。", "distractors": {"A": "沒算出正確的補認列金額。", "B": "只算 5/1 當天的淨額入帳 $97,000,沒加補認列。"}}, "check": "python 驗算:125000*0.8=100000;97000+500+750=98250,相符。", "verified": true, "note": "本題答案為 98,250;選項C 97,500 的成因無法確定。"}, {"id": "114-4-A-12", "exam": "114-4", "paper": "A", "q": 12, "unit": "十二、應收款項", "topic": "應收票據與利息收入調整", "stem": "小和公司 X5 年 11 月 1 日共有下列 4 筆交易,哪幾項於 X5 年 12 月 31 日調整時,將導致「利息收入」增加?\n①銷貨收到 3 個月後到期的本票,該票據附息年息 1%\n②將銷貨所收到 3 個月後到期的不附息應收票據,持向銀行辦理貼現,銀行具有追索權\n③出售長期營業用的設備,收到 2 年後到期的不附息商業本票\n④出售商品,收到 18 個月後到期的不附息商業本票", "options": ["僅①", "僅①②", "僅①③④", "僅②③④"], "answer": "C", "figure": null, "official": "②因銷貨所收到 3 個月後到期的不附息應收票據,年底不必調整利息收入;持向銀行貼現且有追索權,是借:利息費用,貸:應收票據貼現負債。其他情況都應調整貸記利息收入。", "explain": {"concept": "帶息票據年底要應計利息收入;長期不附息票據要以現值入帳,期末攤銷折價為利息收入;3 個月內不附息票據通常不折現。", "steps": ["①:附息票據,年底應計到期前尚未收款的利息,借:應收利息、貸:利息收入,利息收入增加。", "②:不附息票據持向銀行貼現(有追索權),屬於借款性質,貼現時的差額是利息費用,而且貼現後不再調整利息收入。所以不會增加利息收入,②不選。", "③:長期設備賣出收到 2 年後到期的不附息票據,要以現值(票面減折價)入帳,期末調整:借:應收票據折價、貸:利息收入,利息收入增加。", "④:18 個月後到期的不附息票據,到期期間超過一年,要折現,年底調整:借:應收票據折價、貸:利息收入,所以增加利息收入。", "因此選 ①③④,答案選 (C)。"], "pitfalls": "3 個月到期的短期不附息票據通常不折現,所以不調整。貼現的票據利息是費用,不是收入。", "distractors": {"A": "只考慮附息票據,忽略長期不附息票據折價攤銷也會產生利息收入。", "B": "把②當成產生利息收入,混淆貼現的利息性質(應為利息費用)。", "D": "把②當成會增加利息收入,並漏掉①。"}}, "check": "概念題,依官方詳解與票據折價攤銷觀念確認。", "verified": true, "note": ""}, {"id": "114-4-A-13", "exam": "114-4", "paper": "A", "q": 13, "unit": "十二、應收款項", "topic": "資產減項與負債減項", "stem": "下列項目哪幾項屬於資產的減項?\n①應收票據折價\n②備抵損失-應收票據\n③應收票據貼現負債折價\n④應收帳款明細帳貸餘\n⑤備抵存貨跌價\n⑥累計折舊-機器設備\n⑦消耗性生物資產公允價值減出售成本累計變動數(借餘)\n⑧強制透過損益按公允價值衡量之金融資產評價調整(貸餘)", "options": ["①、②、⑤、⑥、⑧", "①、③、④、⑤、⑥", "①、③、⑤、⑥、⑧", "②、③、④、⑦、⑧"], "answer": "A", "figure": null, "official": "③應收票據貼現負債折價屬負債的減項;④應收帳款明細帳貸餘屬負債;⑦消耗性生物資產公允價值減出售成本累計變動數(借餘)屬資產的加項。", "explain": {"concept": "判斷每個科目的性質:資產的減項(貸方餘額的資產備抵科目)、資產的加項、負債項目。", "steps": ["①應收票據折價:應收票據的備抵(減項),屬資產減項。", "②備抵損失:應收票據的減項,資產減項。", "③應收票據貼現負債折價:是『應收票據貼現負債』的減項,屬負債的減項,不是資產的減項。", "④應收帳款明細帳貸餘(客戶多付):是預收性質,屬負債,不是資產減項。", "⑤備抵存貨跌價:存貨的減項,資產減項。", "⑥累計折舊:設備的減項,資產減項。", "⑦借餘的公允價值累計變動數,是加到生物資產上,屬資產加項。⑧貸餘的評價調整,是金融資產的減項,屬資產減項。", "資產減項為 ①②⑤⑥⑧,答案選 (A)。"], "pitfalls": "看餘額方向:『借餘』的評價調整是資產加項,『貸餘』才是減項。『貼現負債折價』要連著負債看。", "distractors": {"B": "把③(負債減項)與④(負債)當資產減項。", "C": "把③當資產減項,漏掉②。", "D": "把負債與資產加項當成資產減項。"}}, "check": "逐項分類後對照官方詳解,一致。", "verified": true, "note": ""}, {"id": "114-4-A-14", "exam": "114-4", "paper": "A", "q": 14, "unit": "十三、存貨", "topic": "永續盤存制移動平均法", "stem": "東風公司於 4 月初成立,商品盤存採永續盤存制,存貨成本公式採均價法,4 月份進、銷貨資料如下:\n\n| 進貨日期 | 數量 | 單價 |\n|---|---|---|\n| 4/1 | 250 | $40 |\n| 4/20 | 400 | $51 |\n\n| 銷貨日期 | 數量 | 單位售價 |\n|---|---|---|\n| 4/10 | 100 | $60 |\n| 4/25 | 250 | $60 |\n\n則 4 月 25 日當日銷貨交易對流動資產的影響為何?", "options": ["增加$3,000", "增加$5,000", "增加$12,000", "增加$16,000"], "answer": "A", "figure": null, "official": "4/25 銷貨收入 $15,000 增加現金或應收帳款,存貨減少 $12,000,流動資產淨增 $3,000。", "explain": {"concept": "永續盤存制 + 均價法(移動加權平均):每次進貨後重算平均單位成本,出售時用當時的單位成本計算銷貨成本。", "steps": ["4/1 進貨:250 單位 × $40 = $10,000。", "4/10 銷貨 100 單位:單位成本 $40,存貨剩 150 單位 × $40 = $6,000。", "4/20 進貨 400 單位 × $51 = $20,400,存貨合計 550 單位,金額 $6,000 + $20,400 = $26,400,新的平均單價 = $26,400 ÷ 550 = $48。", "4/25 銷貨 250 單位,單位成本 $48,銷貨成本 = 250 × $48 = $12,000(存貨減少 $12,000)。", "銷貨收入 = 250 × $60 = $15,000,現金或應收帳款增加 $15,000。", "流動資產變動 = +$15,000 - $12,000 = 增加 $3,000,答案選 (A)。"], "pitfalls": "流動資產包含現金/應收帳款和存貨,要『收入增加的資產』減掉『存貨減少』,不是只看銷貨成本或收入。", "distractors": {"C": "只看存貨減少 $12,000,忘了現金/應收帳款增加。"}}, "check": "python 驗算:250*60-250*48=3000,相符。", "verified": true, "note": ""}, {"id": "114-4-A-15", "exam": "114-4", "paper": "A", "q": 15, "unit": "十四、證券投資", "topic": "股票投資購入處理", "stem": "阿德是南新公司的財務長,阿德將公司的閒錢資金於 X1 年 7 月 15 日以銀行存款購買上市公司紅河公司股票 4 張,每股成交金額$100、每股面額$10,並支付給證券商手續費 1.425‰,預計將該股票一年內出售,該投資對紅河公司無重大影響力且持有供交易為目的。紅河公司的除息日為 X1 年 7 月 15 日,並於 X1 年 8 月 15 日支付現金股利每股$2。有關南新公司購買股票的處理,下列敘述何者正確?", "options": ["購入紅河公司股票的交易平台為櫃檯買賣中心", "X1 年 7 月 15 日非流動資產減少$570", "X1 年 7 月 15 日認列「手續費支出」$570", "X1 年 8 月 15 日認列「股利收入」$8,000"], "answer": "C", "figure": null, "official": "X1/7/15:借:強制透過損益按公允價值衡量之金融資產 $400,000、手續費支出 $570、貸:銀行存款 $400,570。", "explain": {"concept": "持有供交易的股票歸類為『強制透過損益按公允價值衡量之金融資產』,交易成本直接費用化。購買日在除息日(含)之後,買不到股利。", "steps": ["1 張 = 1,000 股,4 張 = 4,000 股。成交金額 = 4,000 × $100 = $400,000。", "手續費 = $400,000 × 1.425‰ = $570。因為是強制透過損益按公允價值衡量,手續費不併入成本,直接認列費用。", "分錄:借:強制透過損益按公允價值衡量之金融資產 $400,000、手續費支出 $570,貸:銀行存款 $400,570。所以 (C) 正確。", "(A):上市股票的交易平台是證券交易所,櫃檯買賣中心是上櫃股票,所以錯。", "(B):預計一年內出售,資產列為流動資產,不是非流動資產,所以錯。", "(D):除息日為 7/15,購買日(含)以後買入不能享有股利分配權,8/15 不會收到股利,也不認列股利收入,所以錯。"], "pitfalls": "『除息日當天(含)買進』不能領到股利。手續費在 FVTPL 是費用,不是成本。", "distractors": {"A": "混淆交易所與櫃檯買賣中心(上市=證交所,上櫃=櫃買中心)。", "B": "把『一年內出售』誤認為非流動,且金額方向錯。", "D": "忽略除息日是 7/15,不能領股利。"}}, "check": "python 驗算:4000*100*1.425/1000=570,與官方相符。", "verified": true, "note": ""}, {"id": "114-4-A-16", "exam": "114-4", "paper": "A", "q": 16, "unit": "十四、證券投資", "topic": "FVTPL 股票投資對稅前淨利影響", "stem": "天方公司 X3 年初以現金購買地圓公司 20,000 股普通股,面額每股$10,成交價每股$20,另支付手續費$500,該投資無重大影響力且持有供交易為目的。當年 4 月 1 日收到地圓公司股票股利每股$1、10 月 1 日收到現金股利每股$2。天方公司 X3 年底將持有地圓公司的半數股票出售,成交價每股$25,手續費及證券交易稅共$1,000。此項投資對於 X3 年度稅前淨利的增加金額為何?", "options": ["$117,500", "$138,500", "$188,500", "$192,500"], "answer": "D", "figure": null, "official": "稅前淨利增加=-手續費$500+股利收入$44,000+出售一半股票之利益$75,000-手續費及交易稅$1,000+剩餘股票評價利益$75,000=$192,500。", "explain": {"concept": "持有供交易的股票以公允價值衡量,評價損益及處分損益都影響淨利;股票股利只增加股數,不認列收入。", "steps": ["期初購入:成本 20,000 × $20 = $400,000,手續費 $500 直接費用(淨利 -$500)。", "4/1 股票股利每股 $1 ÷ 面額 $10 = 10% → 增加 20,000 × 10% = 2,000 股,只備忘記錄,不入帳,持股變 22,000 股。", "10/1 現金股利 $2 × 22,000 股 = $44,000,認列股利收入(+$44,000)。", "年底出售一半股票:11,000 股 × $25 = $275,000;帳面金額 $400,000 × 1/2 = $200,000;出售當天先評價:評價調整與處分合起來利益 = $275,000 - $200,000 = $75,000;再扣手續費及證券交易稅 $1,000。", "剩餘 11,000 股 12/31 按公允價值評價:11,000 × $25 - $200,000 = $75,000 評價利益。", "合計:-500 + 44,000 + 75,000 - 1,000 + 75,000 = $192,500,答案選 (D)。"], "pitfalls": "股票股利不入帳,但股數增加會使現金股利變多,成本不變。", "distractors": {"A": "漏掉剩餘股票的評價利益 $75,000:$44,000 + $75,000 - $500 - $1,000 = $117,500。"}}, "check": "python 驗算:-500+44000+75000-1000+75000=192500,相符。", "verified": true, "note": ""}, {"id": "114-4-A-17", "exam": "114-4", "paper": "A", "q": 17, "unit": "十五、長期營業用資產", "topic": "不動產廠房設備", "stem": "有關企業的不動產、廠房及設備,下列敘述何者錯誤?", "options": ["企業供收成芒果所種植的芒果樹,屬於不動產、廠房及設備", "自建營業用廠房耗費的總成本高於可回收金額時,應認列減損損失", "接受政府無條件補助研究設備(預計使用年限 5 年),接受補助當日應列記資產、收益", "賒購營業用機器設備成交價$100,000,付款條件:2/10,n/60,於成交後第 60 天才付款,則機器設備的入帳成本為$98,000"], "answer": "C", "figure": null, "official": "(C)接受政府無條件補助研究設備,接受補助當日應列記資產、負債:借:設備(資產+)、貸:遞延政府補助之利益(負債+)。", "explain": {"concept": "政府補助設備:先列資產與遞延利益(負債),之後隨折舊分期轉為收益,不是一次認列收益。", "steps": ["(A):結果的植物(如芒果樹)供收成果實,屬於『生產性植物』,依 IAS 16 屬不動產、廠房及設備,敘述正確。", "(B):資產成本高於可回收金額,要認列減損損失,正確。", "(C):政府補助的設備,應借:設備、貸:遞延政府補助之利益(負債),之後隨設備折舊分期認列收益。不是一次認列收益,所以此敘述錯誤。", "(D):採淨額法入帳,機器成本 = $100,000 ×(1 - 2%)= $98,000;放棄折扣時,另認列利息費用 $2,000,所以成本為 $98,000,正確。", "題目問『錯誤』,答案選 (C)。"], "pitfalls": "政府補助不是馬上認列收益,而是以遞延負債處理再分期轉收益。放棄現金折扣的金額是利息費用,不是成本。", "distractors": {"A": "此敘述是正確的(生產性植物屬 PPE)。", "B": "此敘述是正確的(成本高於可回收金額要減損)。", "D": "此敘述正確(淨額法 $98,000,放棄折扣另認利息費用)。"}}, "check": "概念題,與官方詳解一致。", "verified": true, "note": ""}, {"id": "114-4-A-18", "exam": "114-4", "paper": "A", "q": 18, "unit": "十五、長期營業用資產", "topic": "資本支出誤列費用與折舊", "stem": "台旺公司於 X1 年 1 月 1 日購入機器設備,成交價$180,000,當天將支付該設備的運費$6,000 認列為「運費」$6,000。公司對該機器採直線法提列折舊,估計耐用年數 5 年,估計殘值為成本的六分之一。X5 年年初發現錯誤,則下列敘述何者正確?", "options": ["X1 年度費用高估$6,000", "X2 年度本期稅前淨利低估$1,000", "X3 年底資產低估$3,000", "X5 年年初更正分錄應貸:「追溯適用及追溯重編之影響數」$3,000"], "answer": "C", "figure": null, "official": "X1 運費高估 $6,000、折舊低估 $1,000,費用共高估 $5,000;X3 年底成本低估 $6,000、累計折舊低估 $3,000,資產低估 $3,000。", "explain": {"concept": "運費是使資產達可使用狀態的成本,要資本化(計入設備成本)並分年折舊。誤列費用會使費用高估、資產低估、之後折舊低估。", "steps": ["正確做法:運費 $6,000 應計入設備成本。這部分的殘值為 $6,000 × 1/6 = $1,000,每年折舊 = ($6,000 - $1,000)÷ 5 年 = $1,000。", "(A):X1 年運費費用高估 $6,000,但折舊低估 $1,000,淨費用高估 $5,000,不是 $6,000,錯。", "(B):X2 年少提折舊 $1,000,費用低估,所以稅前淨利『高估』$1,000,不是低估,錯。", "(C):X3 年底:設備成本低估 $6,000,累計折舊低估 3 年 × $1,000 = $3,000,資產淨額低估 $6,000 - $3,000 = $3,000,正確。", "(D):到 X5 年初,前 4 年累積淨利低估 $6,000 - $4,000 = $2,000,所以更正分錄是貸『追溯適用及追溯重編之影響數』$2,000(借:機器設備成本 $6,000、貸:累計折舊 $4,000、追溯影響數 $2,000),不是 $3,000,錯。", "答案選 (C)。"], "pitfalls": "『資本支出誤列費用』:當年費用高估,但之後每年折舊低估,淨利要看累積。", "distractors": {"A": "忘了折舊低估 $1,000 的抵銷,淨費用高估只有 $5,000。", "B": "折舊低估應使淨利高估,方向看反。", "D": "累積影響到 X5 年初是 $2,000,不是 $3,000(誤用 3 年而非 4 年折舊)。"}}, "check": "python 驗算:折舊=(6000-1000)/5=1000;X3 底資產低估=6000-3000=3000;X5 初累積=6000-4000=2000。與官方相符。", "verified": true, "note": ""}, {"id": "114-4-A-19", "exam": "114-4", "paper": "A", "q": 19, "unit": "十五、長期營業用資產", "topic": "無形資產", "stem": "有關無形資產的敘述,下列何者正確?", "options": ["企業內部不得自行產生無形資產", "專利權屬於無實體形式的貨幣性資產,能個別處分", "企業透過內部網路問卷取得的客戶名單應列為無形資產", "非公開發行公司帳上的商譽,期末得選擇攤銷或不攤銷"], "answer": "D", "figure": null, "official": "(A)企業內部研發無形資產,發展階段且符合資本化條件,得認列為無形資產;(B)專利權屬於無實體形式的『非』貨幣性資產;(C)企業透過內部網路問卷取得的客戶名單,不得列為無形資產。", "explain": {"concept": "無形資產的定義、可認列條件,與商譽的處理(非公開發行公司可選擇攤銷)。", "steps": ["(A):內部產生的無形資產,研究階段全部費用化,但發展階段若符合資本化條件可認列為無形資產,所以『不得』太絕對,錯。", "(B):專利權是無實體形式的『非貨幣性』資產,不是貨幣性資產,錯。", "(C):自行透過內部網路問卷取得的客戶名單,屬內部產生的客戶名單,不得認列為無形資產,錯。", "(D):非公開發行公司(適用企業會計準則)的商譽,期末可選擇攤銷或不攤銷(只做減損測試),正確。", "答案選 (D)。"], "pitfalls": "內部產生的商譽/客戶名單不能認列,但發展階段支出可資本化。貨幣性資產是指現金、應收款等固定金額的資產。", "distractors": {"A": "忽略發展階段符合條件可資本化。", "B": "專利權是非貨幣性資產。", "C": "內部產生的客戶名單不能認列。"}}, "check": "概念題,對照官方詳解一致。", "verified": true, "note": ""}, {"id": "114-4-A-20", "exam": "114-4", "paper": "A", "q": 20, "unit": "十五、長期營業用資產", "topic": "消耗性生物資產(公允價值模式)", "stem": "呱呱呱公司本年初購入一批小鴨,公開市場交易價格$20,000,準備飼養以供未來出售鴨肉之用,並支付相關運費及佣金共$2,500,公司估計若立即將該批小鴨運往市場出售,需付運費$1,500、交易規費$300 及經銷商的佣金$200。本年度支付飼養費用共$4,500,年底時該批小鴨公允價值$42,000、出售成本$2,000,若會計處理以公允價值模式衡量,飼養支出以飼養費用入帳,則該批小鴨相關交易對於當年度稅前淨利的增加金額為何?", "options": ["$11,000", "$13,000", "$13,500", "$22,000"], "answer": "B", "figure": null, "official": "購入時認列損失 $4,500;飼養費用 $4,500;年底利益 $22,000;稅前淨利增加 = -4,500 - 4,500 + 22,000 = $13,000。", "explain": {"concept": "生物資產以『公允價值 - 出售成本』衡量。購入時若實付總額與衡量值不同,差額列損失;期末再評價產生利益。", "steps": ["購入日衡量額 = 公允價值 - 出售成本 = ($20,000 - $1,500)-($300 + $200)= $18,000。(公允價值取市價 $20,000 減運費 $1,500 後得 $18,500,再減交易規費與佣金 $500。)", "實際支付 = $20,000 + $2,500 = $22,500,與衡量值 $18,000 的差額 $4,500(=$2,500 + $1,500 + $300 + $200)認列『原始認列生物資產及農產品之損失』$4,500(淨利 -$4,500)。", "飼養費用 $4,500 直接認列費用(淨利 -$4,500)。", "年底衡量額 = $42,000 - $2,000 = $40,000,比購入時衡量額 $18,000 增加 $22,000,認列『生物資產當期公允價值減出售成本之變動利益』$22,000(淨利 +$22,000)。", "稅前淨利增加 = -$4,500 - $4,500 + $22,000 = $13,000,答案選 (B)。"], "pitfalls": "購入時的損失與費用都要算;期末的利益是和購入時的衡量額(不是和實付成本)比較。", "distractors": {"D": "只算年底利益 $22,000,漏掉原始損失和飼養費用。"}}, "check": "python 驗算:-4500-4500+22000=13000,相符。", "verified": true, "note": ""}, {"id": "114-4-A-21", "exam": "114-4", "paper": "A", "q": 21, "unit": "十七、權益", "topic": "權益項目", "stem": "有關公司組織的項目,下列敘述何者錯誤?", "options": ["「強制贖回特別股」屬於負債類", "「資本公積」是指公司因股本交易所產生的權益", "「保留盈餘」是指由營業結果所產生的權益", "「其他權益」屬於權益類的減項"], "answer": "D", "figure": null, "official": "(D)其他權益屬於權益類的增減項(可能為加項也可能為減項)。", "explain": {"concept": "權益的分類:股本、資本公積、保留盈餘、其他權益、庫藏股票。", "steps": ["(A):強制贖回特別股,公司有義務在特定日期贖回,屬於負債,正確。", "(B):資本公積來自股本交易(例如股票溢價、庫藏股票交易),正確。", "(C):保留盈餘是由營業結果產生並保留在公司的權益,正確。", "(D):其他權益(如國外營運機構財務報表換算之兌換差額、透過其他綜合損益按公允價值衡量之金融資產未實現評價損益)可能是正數也可能是負數,所以是權益的『增減項』,而不是只有減項,此敘述錯誤。", "題目問錯誤,答案選 (D)。"], "pitfalls": "『其他權益』可借可貸,不是專門的減項(庫藏股票才是專門的權益減項)。", "distractors": {"A": "此敘述正確,強制贖回特別股屬負債。", "B": "此敘述正確。", "C": "此敘述正確。"}}, "check": "概念題,與官方詳解一致。", "verified": true, "note": ""}, {"id": "114-4-A-22", "exam": "114-4", "paper": "A", "q": 22, "unit": "十七、權益", "topic": "員工酬勞與法定盈餘公積", "stem": "欣欣股份有限公司每年分派一次盈餘,X4 年期初累積虧損$100,000,X4 年度扣除員工及董監事酬勞前之稅前淨利$1,000,000,依章程按淨利提撥 5%員工酬勞、2%董監事酬勞,所得稅稅率為 20%。公司 X4 年度依公司法提撥法定盈餘公積 10%的金額為何?", "options": ["$64,960", "$74,000", "$74,400", "$74,960"], "answer": "A", "figure": null, "official": "員工酬勞及董監事酬勞=($1,000,000-$100,000)×(5%+2%)=$63,000;稅後淨利=($1,000,000-$63,000)×(1-20%)=$749,600;法定盈餘公積=($749,600-$100,000)×10%=$64,960。", "explain": {"concept": "員工酬勞與董監事酬勞按『彌補虧損後』的稅前淨利計算,是費用;法定盈餘公積要先彌補虧損後再提 10%。", "steps": ["先彌補累積虧損後的基數:$1,000,000 - $100,000 = $900,000(章程提撥酬勞時,基數須先彌補虧損)。", "員工酬勞及董監事酬勞 = $900,000 ×(5% + 2%)= $63,000(列為費用)。", "稅前淨利(扣除酬勞後)= $1,000,000 - $63,000 = $937,000。", "稅後淨利 = $937,000 ×(1 - 20%)= $749,600。", "法定盈餘公積要先彌補虧損:($749,600 - $100,000)× 10% = $649,600 × 10% = $64,960,答案選 (A)。"], "pitfalls": "兩個地方要扣累積虧損:提撥酬勞的基數、提法定盈餘公積的基數。常見錯誤是沒先彌補虧損。", "distractors": {"D": "$74,960 = $749,600 × 10%,沒先彌補虧損 $100,000。"}}, "check": "python 驗算:63000;749600;64960,與官方相符。", "verified": true, "note": ""}, {"id": "114-4-A-23", "exam": "114-4", "paper": "A", "q": 23, "unit": "十七、權益", "topic": "股票股利、股票分割與股本", "stem": "有關股份有限公司與權益相關的會計處理,下列敘述何者正確?", "options": ["宣告及發放股票股利之後,導致股本總額不變、權益總額不變", "發行無面額的普通股時,所得股款全部記入「普通股股本」項目", "股票股利與股票分割兩者皆使流通在外股數增加、每股面額減少", "特別盈餘公積主要用途是彌補虧損,無虧損時得依股東會決議發放股利"], "answer": "B", "figure": null, "official": "(A)宣告及發放股票股利之後,累積盈虧減少、股本總額增加、權益總額不變;(C)股票股利每股面額不變,股票分割每股面額減少;(D)特別盈餘公積主要用途是分配盈餘時將保留盈餘加以限制。", "explain": {"concept": "股票股利:保留盈餘轉成股本;股票分割:只改面額與股數,不入帳。", "steps": ["(A):股票股利是把保留盈餘轉成股本(借:保留盈餘、貸:普通股股本),股本增加、保留盈餘減少,權益總額不變,所以『股本總額不變』錯。", "(B):無面額股票發行所得全部記入股本,不產生資本公積,正確。", "(C):股票股利後流通股數增加,每股面額不變;股票分割股數增加、面額按比例減少,所以『皆使每股面額減少』錯。", "(D):特別盈餘公積是『限制』盈餘的分配(如提列特別盈餘公積後才能分配),不是用來彌補虧損,錯。", "答案選 (B)。"], "pitfalls": "股票股利和股票分割最大差別:股票股利動到帳(保留盈餘→股本),每股面額不變;分割不動帳,面額變小。", "distractors": {"A": "以為股票股利『不影響權益』就連股本也不變,但股本實際上增加。", "C": "混淆股票股利與股票分割的面額變化。", "D": "特別盈餘公積是限制分配,不是彌補虧損用。"}}, "check": "概念題,與官方詳解一致。", "verified": true, "note": ""}, {"id": "114-4-A-24", "exam": "114-4", "paper": "A", "q": 24, "unit": "十七、權益", "topic": "每股盈餘與加權平均流通在外股數", "stem": "向榮股份有限公司本年度稅前淨利$912,500,所得稅稅率為 20%,股份資料如下:\n特別股:每股面額$10,累積非參加特別股,股利率 5%,流通在外 80,000 股\n普通股:\n\n| 日期 | 事項 |\n|---|---|\n| 1/1 | 流通在外共 120,000 股 |\n| 3/1 | 現購庫藏股票,共 24,000 股 |\n| 5/1 | 發放 20%股票股利 |\n| 7/1 | 出售庫藏股票,共 24,000 股 |\n| 9/1 | 股票分割 1 股分為 2 股 |\n| 11/1 | 現金增資 72,000 股 |\n\n向榮股份有限公司的特別股預計本年度股利不發放。下列敘述何者正確?", "options": ["積欠累積特別股未發放的股利,應列為流動負債", "購入的庫藏股票使公司已發行股票股數減少", "本年度普通股加權平均流通在外股數為 276,000 股", "本年度每股盈餘為$2.64"], "answer": "C", "figure": null, "official": "(C)加權平均流通在外股數:288,000 - 48,000 + 24,000 + 12,000 = 276,000 股。", "explain": {"concept": "EPS=(稅後淨利 - 特別股股利)÷ 普通股加權平均流通在外股數。股票股利與股票分割要追溯調整。", "steps": ["股票股利、股票分割視同期初就已發生,須追溯調整:1/1 流通 120,000 股 × 1.2 × 2 = 288,000 股,全年 12/12:288,000。", "3/1 買庫藏股 24,000 股,需減少(也受股票股利、分割調整):(24,000)× 1.2 × 2 × 10/12 = (48,000)。", "7/1 出售庫藏股 24,000 股,發生在股票股利之後、分割之前,只受分割影響:24,000 × 2 × 6/12 = 24,000。", "11/1 現金增資 72,000 股(分割後):72,000 × 2/12 = 12,000。", "加權平均 = 288,000 - 48,000 + 24,000 + 12,000 = 276,000 股,所以 (C) 正確。", "(D) 驗算 EPS:稅後淨利 $912,500 ×(1 - 20%)= $730,000;特別股股利 $10 × 80,000 × 5% = $40,000;EPS =($730,000 - $40,000)÷ 276,000 = $2.50,不是 $2.64。"], "pitfalls": "EPS 要先扣特別股股利(累積特別股即使不發放也要扣);股票股利和分割要追溯調整。", "distractors": {"A": "積欠累積特別股股利不是負債(公司尚未宣告),只須在附註說明。", "B": "庫藏股是『已發行但被收回』的股票,已發行股數不變,減少的是流通在外股數。", "D": "$2.64 = $730,000 ÷ 276,000,沒扣特別股股利 $40,000。"}}, "check": "python 驗算:加權平均 276,000;EPS=(730000-40000)/276000=2.50;$2.64=730000/276000。與官方相符。", "verified": true, "note": ""}, {"id": "114-5-A-01", "exam": "114-5", "paper": "A", "q": 1, "unit": "一、會計基本概念", "topic": "會計制度與財務會計概念", "stem": "章老師想藉由互動方式引起學生的會計學習動機,所以教完一段落課程後,設計了下列的問題,請同學搶答有哪幾項是對的,完全答對者可以加平時分數。\n①我國實務上需要會計師進行財務報表簽證的僅有公開發行公司\n②政府機構、消費者文教基金會、公用事業所採用之會計均屬非營利事業會計\n③財務會計主要係將企業之各項會計資訊,提供給外部使用者,協助其制定相關決策\n④會計人員在處理商店會計事務時,若《商業會計法》、《企業會計準則公報》二者不同時,應優先遵循《商業會計法》\n下列 4 位學生之回答,哪一位學生可以被加分?", "options": ["小明說:僅有①、②項正確", "小華說:僅有③、④項正確", "小蘭說:僅有①、②、③項正確", "小雨說:僅有②、③、④項正確"], "answer": "B", "figure": null, "official": "①簽證範圍不只公開發行公司(還有實收資本額 3 千萬以上等);②公用事業採營利事業會計,故②錯;③④正確。", "explain": {"concept": "這題要逐項判斷四句話對不對,再找出「完全答對」的組合:考會計簽證範圍、營利/非營利會計、財務會計的目的、法令位階。", "steps": ["先看①:需要會計師簽證財務報表的,不只公開發行公司,還包括實收資本額 3 千萬以上的公司、向銀行融資超過一定金額的公司等,所以「僅有公開發行公司」是錯的。", "再看②:政府機構、消費者文教基金會是非營利會計沒錯,但公用事業(像水、電、瓦斯)是以營利為目的,採營利事業會計,所以②錯。", "看③:財務會計就是把資訊提供給外部使用者(股東、債權人等)做決策,正確。", "看④:法律位階比準則高,《商業會計法》與《企業會計準則公報》不同時,優先遵循《商業會計法》,正確。", "所以正確的是③、④,對應選項 B。"], "pitfalls": "容易把公用事業當成非營利事業,也容易以為只有公開發行公司才要會計師簽證。", "distractors": {"A": "以為①②正確,忽略簽證範圍較廣、公用事業屬營利事業。", "C": "以為①②正確,同樣犯了①②的錯,又漏掉④。", "D": "相信②正確(公用事業誤當非營利),漏了②的錯誤。"}}, "check": "概念題:對照官方詳解與商業會計法,只有③④正確,B。", "verified": true, "note": ""}, {"id": "114-5-A-02", "exam": "114-5", "paper": "A", "q": 2, "unit": "一、會計基本概念", "topic": "會計事務處理與帳簿保存", "stem": "有關會計事務處理之敘述,下列何者正確?", "options": ["結清虛帳戶、結轉實帳戶的工作,稱為調整", "會計人員依法處理會計事務,其離職或變更職務時,應於 10 日內辦理交代", "我國《商業會計法》規定會計事項應按發生次序逐日登帳,至遲不得超過一個月", "我國《商業會計法》規定會計帳簿,除有尚未結束事項外,應於年度決算程序終了,至少保存 10 年"], "answer": "D", "figure": null, "official": "(A)應稱結帳;(B)應於 5 日內辦理交代;(C)至遲不得超過二個月;(D)帳簿至少保存 10 年,正確。", "explain": {"concept": "考結帳的定義與《商業會計法》對交代期限、登帳期限、帳簿保存年限的規定。", "steps": ["A 項:把虛帳戶結清、實帳戶結轉到下期,這是「結帳」,「調整」是期末把應計、遞延項目調成正確金額,所以 A 錯。", "B 項:會計人員離職或調職,依法應在 5 日內辦理交代,不是 10 日,B 錯。", "C 項:會計事項應按發生次序逐日登帳,至遲不得超過二個月,不是一個月,C 錯。", "D 項:會計帳簿(除有未結束事項外)要在年度決算程序終了後至少保存 10 年(憑證則是 5 年),D 正確。"], "pitfalls": "數字很容易記混:交代 5 日、登帳 2 個月、帳簿 10 年、憑證 5 年。", "distractors": {"A": "把「結帳」與「調整」的名稱搞混。", "B": "把交代期限 5 日記成 10 日。", "C": "把登帳期限 2 個月記成 1 個月。"}}, "check": "概念題:對照商業會計法條文與官方詳解,D 正確。", "verified": true, "note": ""}, {"id": "114-5-A-03", "exam": "114-5", "paper": "A", "q": 3, "unit": "三、會計基本法則", "topic": "會計項目分類(第四級)", "stem": "有關第四級會計項目之敘述,下列何者錯誤?", "options": ["暫收款、代收款、存入保證金均為其他流動負債", "銷貨收入、銷貨退回、銷貨折讓、勞務收入均為營業收入", "各項攤提、預期信用減損損失、研究發展費用均為營業費用", "預付保險費、用品盤存、進項稅額、留抵稅額均包含於財務報表第三級會計項目預付款項中"], "answer": "A", "figure": null, "official": "暫收款、代收款為其他流動負債,存入保證金為其他非流動負債,故(A)錯誤。", "explain": {"concept": "考會計項目的分類:存入保證金屬於「其他非流動負債」,不是流動負債。", "steps": ["題目問「錯誤」的選項,要逐項檢查。", "A 項:暫收款、代收款是其他流動負債沒錯;但存入保證金(押金,通常要等契約結束才退還)是其他「非流動」負債,所以 A 錯。", "B、C、D 項依官方詳解均屬正確分類,所以答案選 A。"], "pitfalls": "看到「錯誤」要選錯的;存入保證金容易被當成流動負債。", "distractors": {"B": "此項分類正確,不是答案。", "C": "此項分類正確,不是答案。", "D": "此項分類正確,不是答案。"}}, "check": "概念題:對照官方詳解會計項目表,存入保證金為其他非流動負債,A 錯誤。", "verified": true, "note": ""}, {"id": "114-5-A-04", "exam": "114-5", "paper": "A", "q": 4, "unit": "四、分錄與日記簿", "topic": "交易種類與傳票(複式傳票四分法)", "stem": "大方商店 5 月 15 日賒購商品一批$50,000,付款條件為 2/10、n/30,於 5 月 25 日簽發三個月的票據償還貨欠,則 5 月 25 日交易種類及在複式傳票四分法下應編製的傳票分別為何?", "options": ["混合交易;現金轉帳傳票", "混合交易;分錄轉帳傳票", "轉帳交易;現金轉帳傳票", "轉帳交易;分錄轉帳傳票"], "answer": "D", "figure": null, "official": "分錄為借:應付帳款 50,000 貸:應付票據 50,000,不涉及現金,屬轉帳交易,應編分錄轉帳傳票。", "explain": {"concept": "交易分成現金交易、轉帳交易、混合交易;複式傳票四分法有收入、支出、轉帳(分錄轉帳)三種傳票之分,「現金轉帳傳票」是用於混合交易的。", "steps": ["先寫分錄:簽發票據償還貨欠,借:應付帳款 50,000,貸:應付票據 50,000。", "這筆分錄完全沒有現金科目,所以是「轉帳交易」(有現金進出才是現金交易,同時有現金與非現金才是混合交易)。", "轉帳交易用「分錄轉帳傳票」,所以選 D。"], "pitfalls": "看到「付款」就以為有現金;其實簽發票據只是負債形式改變,沒有現金流出。", "distractors": {"A": "誤以為有付款=混合交易,且用現金轉帳傳票。", "B": "交易種類誤判為混合交易(沒有現金)。", "C": "交易種類對了,但現金轉帳傳票是混合交易用的。"}}, "check": "概念題:分錄無現金科目,轉帳交易、分錄轉帳傳票,D。", "verified": true, "note": ""}, {"id": "114-5-A-05", "exam": "114-5", "paper": "A", "q": 5, "unit": "五、過帳與分類帳", "topic": "日記簿與分類帳的轉頁、統制帳戶", "stem": "小明與小華是會計學習上的好夥伴,小明對於帳簿的會計相關處理,有一些觀念模糊不清,故就以下 4 個觀念詢問小華,請小華幫忙釐清,則下列哪幾項觀念錯誤,小華須協助導正?\n①餘額式分類帳記滿一頁轉換新頁時,須將前頁之借、貸方合計數及餘額結轉於次頁,所以日記簿也應該一致性處理\n②統制帳戶的餘額必等於其明細分類帳各子項目餘額的合計,所以資產負債表中應付帳款的餘額必為其統制帳戶的餘額\n③為避免交易遺漏或重複過帳及有利於交易相互勾稽索引,所以在日記簿設有類頁欄位,在分類帳中設有日頁欄位\n④過帳是將日記簿內各分錄的會計項目與金額,按其借貸方轉記至分類帳的相關帳戶中,所以總分類帳中各帳戶名稱與日記簿中第四級會計項目名稱應該一致", "options": ["僅①、②項", "僅③、④項", "僅①、②、④項", "僅①、③、④項"], "answer": "A", "figure": null, "official": "①日記簿轉頁只需將每頁合計數轉次頁,不需結轉餘額;②資產負債表中應付帳款的餘額為其明細分類帳貸餘者之合計金額,故①②錯誤。", "explain": {"concept": "考日記簿與分類帳轉頁方式、統制帳戶與明細帳戶的關係(資產負債表列示)。", "steps": ["①:餘額式分類帳換頁要把前頁借、貸合計和餘額結轉;但日記簿沒有「餘額」欄,只要把每頁合計數轉次頁,所以不必一致處理,①錯。", "②:統制帳戶餘額確實等於明細帳合計,但資產負債表的應付帳款,是把明細帳中「貸餘」的合計列為負債,借餘的要另列為預付款項,不能直接用統制帳戶餘額,②錯。", "③:日記簿有「類頁」(記分類帳頁次)、分類帳有「日頁」(記日記簿頁次),互相索引勾稽,正確。", "④:過帳依會計項目轉記,總分類帳戶名稱與日記簿第四級會計項目一致,正確。", "題目問「錯誤」,故①②錯,選 A。"], "pitfalls": "②很容易漏看:資產負債表列示的是「貸餘明細合計」,不是單純統制帳戶餘額。", "distractors": {"B": "以為③④錯,但③④其實是正確的觀念。", "C": "多選了④,④是正確的。", "D": "漏掉②,又多選了③④。"}}, "check": "概念題:對照官方詳解,①②錯誤,A。", "verified": true, "note": ""}, {"id": "114-5-A-06", "exam": "114-5", "paper": "A", "q": 6, "unit": "六、試算與試算表", "topic": "餘額式試算表平衡之錯誤", "stem": "有關會計處理之錯誤,哪幾項不影響餘額式試算表之平衡?\n①賒購商品,遺漏過帳\n②以現金償還貨欠,借方誤過入「應收帳款」項目\n③賒銷商品,過帳時漏過該交易之借方項目\n④出售商品收到即期支票乙紙,借方誤記為「應收票據」\n⑤以現金償還銀行借款,過帳時誤將銀行借款項目過至貸方", "options": ["僅①、④項", "僅③、⑤項", "僅①、②、④項", "僅②、③、⑤項"], "answer": "C", "figure": null, "official": "①同時漏借貸、②借方誤過入應收帳款(誤過科目)、④誤用科目,均不影響平衡;③單方漏過帳、⑤單方過錯方向,會使試算表不平衡。", "explain": {"concept": "餘額式試算表只檢查借餘合計=貸餘合計。借貸同時少計、同時多計,或只記錯「科目」(金額方向都對),都不會影響平衡;只有單方漏記或借貸方向弄反才會不平衡。", "steps": ["①賒購商品遺漏過帳:借方(進貨)與貸方(應付帳款)都漏,借貸同時少,仍平衡。", "②還貨欠本應借「應付帳款」,卻誤過入「應收帳款」的借方:只是借方科目選錯,借方金額仍在,借貸仍相等,不影響平衡(官方:誤過會計項目,借貸方均多計)。", "③賒銷漏過借方(應收帳款):只少借方,借貸不等,不平衡。", "④支票是即期支票,應借「現金」,誤記「應收票據」:只是借方科目錯,金額仍相等,平衡。", "⑤償還銀行借款應借「銀行借款」,誤過到貸方:本來借餘變成貸餘,借貸差 2 倍金額,不平衡。", "所以不影響平衡的是①②④,選 C。"], "pitfalls": "關鍵是分清「科目錯」(不影響)與「漏單邊/方向反」(影響)。", "distractors": {"A": "漏掉②,②雖然科目有誤,但借貸均衡,也不影響平衡。", "B": "③⑤正是會影響平衡的錯誤,選反了。", "D": "把②當不影響沒錯,但③⑤是會造成不平衡的錯誤。"}}, "check": "概念題:逐項看借貸是否仍相等,①②④不影響,C。", "verified": true, "note": ""}, {"id": "114-5-A-07", "exam": "114-5", "paper": "A", "q": 7, "unit": "七、調整", "topic": "預付保險費與預收租金調整", "stem": "大力公司會計基礎採用應計基礎記帳,X1 年 7 月 1 日預付一年期保險費$60,000,並於 9 月 1 日預收為期一年半的租金$360,000。12 月 31 日完成以上兩項調整分錄後,則公司 X1 年度稅前淨利增加數為何?", "options": ["$50,000", "$80,000", "$150,000", "$300,000"], "answer": "A", "figure": null, "official": "預收租金調整:租金收入 4 個月 $360,000÷18×4=$80,000;保險費 6 個月 $30,000;淨增 $80,000−$30,000=$50,000。", "explain": {"concept": "期末調整:預付費用要轉成費用(減少利益),預收收入要轉成收入(增加利益)。", "steps": ["保險費:一年期 $60,000,X1 年 7/1~12/31 共 6 個月,已耗用 $60,000×6/12=$30,000。調整分錄:借:保險費 30,000 貸:預付保險費 30,000。費用增加,稅前淨利減少 $30,000。", "租金:一年半=18 個月,$360,000÷18=每月 $20,000;9/1~12/31 共 4 個月,已賺 $20,000×4=$80,000。調整分錄:借:預收租金 80,000 貸:租金收入 80,000。收入增加,稅前淨利增加 $80,000。", "合併影響:$80,000−$30,000=$50,000(增加)。"], "pitfalls": "容易把租金當成 12 個月算成 $120,000,忘了是一年半;或忘記保險費是減項。", "distractors": {"B": "只算租金增加 $80,000,忘了扣保險費。", "C": "把租金當成一年的 $120,000,再加上保險費 $30,000 得 $150,000(保險費應是減項,且租金期間為 18 個月)。", "D": "把預收租金 $360,000 全數當收入,或沒按月份比例攤算。"}}, "check": "python 驗算:80,000−30,000=50,000,與官方相符。", "verified": true, "note": ""}, {"id": "114-5-A-08", "exam": "114-5", "paper": "A", "q": 8, "unit": "十二、應收款項", "topic": "備抵損失提列與無法收回金額", "stem": "大利公司期初「應收帳款」餘額$300,000,期初「備抵損失-應收帳款」餘額$6,000,本期期末「應收帳款」餘額$400,000,該公司採單一損失率法提列備抵損失,且損失率與上期相同,已知期末調整時認列之「預期信用減損損失」金額為$12,000,且本期未發生已沖銷帳款再回收,則本期實際發生帳款無法收回之金額為何?", "options": ["$8,000", "$10,000", "$12,000", "$14,000"], "answer": "B", "figure": null, "official": "損失率 $6,000÷$300,000=2%;期末備抵損失應為 $400,000×2%=$8,000;$6,000+$12,000−X=$8,000,X=$10,000。", "explain": {"concept": "備抵損失的 T 字帳:期初餘額 + 本期提列 − 沖銷 = 期末餘額。", "steps": ["先求損失率:期初備抵損失 $6,000÷期初應收帳款 $300,000=2%(本期損失率與上期相同)。", "求期末備抵損失應有餘額:$400,000×2%=$8,000。", "備抵損失 T 字帳:貸方有期初 $6,000、本期提列 $12,000;借方是沖銷帳款 X;期末貸餘 $8,000。", "列式:$6,000+$12,000−X=$8,000,X=$10,000,即本期無法收回而沖銷的金額。"], "pitfalls": "容易把本期提列的 $12,000 或期末餘額 $8,000 誤當成沖銷金額。", "distractors": {"A": "把期末備抵損失餘額 $8,000 當成沖銷金額。", "C": "把本期提列的預期信用減損損失 $12,000 當沖銷。", "D": "算式中把沖銷方向弄反(如 $6,000+$8,000)。"}}, "check": "python 驗算:6,000+12,000−8,000=10,000,與官方相符。", "verified": true, "note": ""}, {"id": "114-5-A-09", "exam": "114-5", "paper": "A", "q": 9, "unit": "九、財務報表", "topic": "營利事業所得稅結算申報", "stem": "大河企業本年度之損益資料計有銷貨收入$500,000、銷貨成本$250,000、營業費用$100,000、營業外收入$50,000 及營業外支出$20,000。有關營利事業所得稅之申報,依現行法規,下列敘述何者正確?", "options": ["大河企業若為獨資組織,不須辦理結算申報,營利事業所得稅額為$0", "大河企業若為獨資組織,應辦理結算申報,營利事業所得稅額為$30,000", "大河企業若為公司組織,應辦理結算申報,營利事業所得稅額為$36,000", "大河企業若為公司組織,應辦理結算申報,營利事業所得稅額為$30,000"], "answer": "D", "figure": null, "official": "稅前淨利 $180,000;獨資應辦理結算申報,營利事業所得稅額為 $0(所得併入業主綜合所得);公司組織:($180,000−$120,000)÷2=$30,000。", "explain": {"concept": "考營利事業所得稅:獨資、合夥不繳營利事業所得稅(併入個人綜所稅);公司組織有 $120,000 以下免稅、超過部分減半課徵的規定(此題的當年度稅制)。", "steps": ["先算稅前淨利:$500,000−$250,000−$100,000+$50,000−$20,000=$180,000。", "獨資(或合夥)組織:仍要辦理結算申報,但營利事業所得額要列入業主的營利所得,課徵個人綜合所得稅,所以營利事業所得稅額為 $0,A、B 都不對(A 說不須申報錯,B 稅額錯)。", "公司組織:依官方詳解,營利事業所得稅額=($180,000−$120,000)÷2=$30,000。", "對照 C、D:$30,000 才是官方答案,選 D。"], "pitfalls": "獨資「要申報但不用繳營所稅」兩件事容易搞混。", "distractors": {"A": "說獨資不須申報:錯,獨資仍須辦理結算申報,只是稅額為 $0。", "B": "以為獨資要繳 $30,000:其實所得併入業主綜所稅。"}}, "check": "python 驗算:(180,000−120,000)÷2=30,000,與官方相符。", "verified": true, "note": "單元歸類可能有爭議(所得稅申報,無對應單元,暫歸九)。"}, {"id": "114-5-A-10", "exam": "114-5", "paper": "A", "q": 10, "unit": "九、財務報表", "topic": "賒銷利潤對短期償債能力的影響", "stem": "大裕公司對存貨數量衡量方法採永續盤存制,認列一筆有利潤的賒銷,有關此交易對短期償債能力分析的影響,下列敘述何者正確?", "options": ["營運資金不變", "速動比率不變", "流動比率提高", "速動資產增加小於流動資產增加"], "answer": "C", "figure": null, "official": "賒銷有利潤:應收帳款增加(銷貨收入)大於存貨減少(銷貨成本),流動資產淨增加,流動負債不變,流動比率提高。", "explain": {"concept": "流動比率=流動資產÷流動負債;營運資金=流動資產−流動負債;速動資產不含存貨。", "steps": ["分錄:借:應收帳款(售價)貸:銷貨收入;借:銷貨成本 貸:存貨(成本)。因有利潤,售價>成本。", "流動資產:應收帳款增加(售價),存貨減少(成本),淨增加「售價−成本」>0。流動負債不變。", "營運資金增加(A 錯);流動比率=流動資產↑÷不變的流動負債,提高(C 對)。", "速動資產:應收帳款增加(售價)、存貨不算速動資產故不減,速動資產增加=售價,比流動資產增加(售價−成本)更多,所以 D 錯;速動比率也提高,B 錯。"], "pitfalls": "忘了存貨不是速動資產,以為速動資產跟流動資產增加一樣多。", "distractors": {"A": "忘了流動資產增加,營運資金會增加。", "B": "速動資產增加而流動負債不變,速動比率會提高。", "D": "方向弄反:速動資產增加(售價)大於流動資產增加(售價−成本)。"}}, "check": "概念題:代入假設數字(售價 150、成本 100)驗證,流動比率、速動比率均提高。", "verified": true, "note": ""}, {"id": "114-5-A-11", "exam": "114-5", "paper": "A", "q": 11, "unit": "十、加值型營業稅會計實務", "topic": "營業稅申報、留抵稅額與得退稅限額", "stem": "大川公司為適用一般稅率之加值型營業人,曉娟為該公司新任之會計人員,前任會計人員交接有關 X1 年 1 至 2 月份申報營業稅之資料如下:X1 年 1 月 1 日「留抵稅額」餘額$60,000,1、2 月份有以下交易,金額均未含營業稅:銷貨收入$6,000,000(其中外銷$2,000,000)、預收貨款$500,000;進貨$3,000,000、進貨退出及折讓$50,000、購買一筆不動產$5,000,000(其中房屋$2,000,000,土地$3,000,000)、營業費用支出$600,000(其中包含五人座自用乘人小汽車修理費$50,000、宴請客戶$80,000 及向小規模營業人購買文具用品$20,000),曉娟因為是第一次進行營業稅申報,計算出下列申報之金額後,請教你這位專業人員,下列有哪幾項金額需要修正?\n①銷項稅額為$200,000  ②進項稅額為$270,000  ③申報留抵稅額$107,500\n④得退稅限額$200,000  ⑤累積留抵稅額$0", "options": ["僅①、②項", "僅④、⑤項", "僅①、②、③項", "僅③、④、⑤項"], "answer": "A", "figure": null, "official": "銷項稅額=($4,000,000+$500,000)×5%=$225,000;進項稅額=$272,500;申報留抵=$107,500;得退稅限額=$200,000;應退=$107,500,累積留抵=$0。所以①、②要修正。", "explain": {"concept": "營業稅:銷項稅額 = 內銷銷售額×5%(外銷零稅率,預收貨款也要開發票課稅);進項稅額不含土地、交際應酬、無憑證等不得扣抵項目;留抵稅額、得退稅限額(外銷+購買固定資產)。", "steps": ["銷項稅額:內銷=$6,000,000−$2,000,000(外銷零稅率)=$4,000,000,再加預收貨款 $500,000(已開立發票),合計 $4,500,000×5%=$225,000。曉娟寫 $200,000,漏了預收貨款,①要修正。", "進項稅額:可扣抵的進項金額=進貨 $3,000,000−退出折讓 $50,000+房屋 $2,000,000(土地不課稅,$3,000,000 不算)+營業費用 $600,000−宴請客戶 $80,000(交際應酬不得扣抵)−小規模營業人文具 $20,000(無進項稅額)。=$5,450,000×5%=$272,500。曉娟寫 $270,000,②要修正。", "本期申報留抵稅額:進項 $272,500+期初留抵 $60,000−銷項 $225,000=$107,500,③正確。", "得退稅限額:(外銷銷售額 $2,000,000+購買固定資產(房屋)$2,000,000)×5%=$200,000,④正確。", "應退稅額取留抵稅額 $107,500 與限額 $200,000 較小者=$107,500,全數退還,累積留抵稅額=$107,500−$107,500=$0,⑤正確。", "需修正的是①②,選 A。"], "pitfalls": "關鍵:預收貨款要計入銷項;土地不能算進項;宴請客戶(交際應酬)不得扣抵。", "distractors": {"B": "以為④⑤錯,但限額與累積留抵都正確。", "C": "多算③,③的 $107,500 是正確的(題目寫的與官方答案相同)。", "D": "③④⑤皆正確,不需修正。"}}, "check": "python 驗算:銷項 225,000、進項 272,500、留抵 107,500、限額 200,000、累積留抵 0,與官方相符;①②需修正。", "verified": false, "note": "官方計算進項時把五人座自用乘人小汽車修理費 $50,000 視為可扣抵(僅扣宴請與小規模文具);我的驗算依官方同一口徑得到相同結果,但此處是否合乎現行營業稅法對自用乘人小汽車修理費的規定尚待人工複核。"}, {"id": "114-5-A-12", "exam": "114-5", "paper": "A", "q": 12, "unit": "十一、現金及內部控制", "topic": "定額零用金撥補與減設", "stem": "大擎公司於 X1 年 1 月 1 日設置定額零用金$10,000,並於每月底定期撥補,1 月底零用金保管員提出以下單據請求撥補:郵票$1,000、文具用品$800、報費$300、旅費$2,150、交際費$1,500、零用金短少了$10,同時減設零用金$2,000,則下列敘述何者正確?", "options": ["撥補金額為$5,760", "1 月底撥補前手存現金為$4,240", "撥補後的「零用金」餘額為$10,000", "撥補分錄應認列費損金額共計$5,750"], "answer": "B", "figure": null, "official": "費損合計 $5,760(含短少 $10),減設 $2,000,撥補現金 $5,760−$2,000=$3,760;撥補前手存現金 =($10,000−$2,000)−$3,760=$4,240;撥補後零用金 $8,000。", "explain": {"concept": "定額零用金:撥補前「手存現金+單據」= 定額。減設時,零用金科目減少,所需補現金的金額就變少。", "steps": ["先算單據合計:$1,000+$800+$300+$2,150+$1,500=$5,750,另外零用金短少 $10(現金短溢,算費損),費損共 $5,760。", "撥補前手存現金 = 原定額 $10,000−單據 $5,750−短少 $10 = $4,240。", "減設零用金 $2,000,定額變成 $8,000,所以需要補到 $8,000:撥補現金 = $8,000−$4,240 = $3,760。", "分錄:借:郵電費(及各費用)等費損 $5,760;貸:零用金 $2,000;貸:現金 $3,760。", "逐項看:A 撥補金額是 $3,760,錯;B 撥補前手存現金 $4,240,對;C 撥補後零用金是 $8,000,錯;D 費損共計是 $5,760(含短少 $10),錯。"], "pitfalls": "減設零用金時,撥補現金金額要少掉減設的部分;短少的 $10 也要算費損。", "distractors": {"A": "忘了減設,直接用費損 $5,760 當撥補金額。", "C": "以為撥補後恢復 $10,000,忽略減設 $2,000。", "D": "漏算零用金短少 $10。"}}, "check": "python 驗算:費損 5,760;撥補 3,760;手存現金 4,240;與官方相符。", "verified": true, "note": ""}, {"id": "114-5-A-13", "exam": "114-5", "paper": "A", "q": 13, "unit": "十二、應收款項", "topic": "銷貨折扣、退回與現金折扣", "stem": "大銘公司 X1 年 9 月 10 日賒銷一批商品,並按定價打九折成交,付款條件為 2/10,n/30。客戶於 X1 年 9 月 15 日按定價退貨$10,000,並於 9 月 20 日還來現金$98,000,餘款則在月底付訖。大銘公司該筆交易共計收到現金$178,000,則大銘公司 X1 年 9 月 10 日所銷售商品的定價為多少?", "options": ["$180,000", "$190,000", "$200,000", "$210,000"], "answer": "D", "figure": null, "official": "設定價為 X。月底收現金 $178,000−$98,000=$80,000。(X−$10,000)×0.9−($98,000÷0.98)=$80,000,X=$210,000。", "explain": {"concept": "商業折扣(九折)直接打在定價上;現金折扣 2/10 只對在 10 天內的付款扣 2%。10 天內付的 $98,000 是淨額,相當於貨款 $98,000÷0.98=$100,000。", "steps": ["設定價為 X。九折成交,實際售價=0.9X。", "9/15 按定價退貨 $10,000,對應的實際金額=$10,000×0.9=$9,000(退貨也要打九折)。", "9/20 在 10 天內付款,享有 2% 現金折扣:付現 $98,000,對應貨款=$98,000÷0.98=$100,000。", "月底收到的現金=$178,000−$98,000=$80,000(超過折扣期,不能再折)。", "列式:0.9X−$9,000−$100,000=$80,000 → 0.9X=$189,000 → X=$210,000。", "驗算:(210,000−10,000)×0.9=180,000;180,000−100,000=80,000 ✓。"], "pitfalls": "容易忘了退貨也要乘 0.9,或把 $98,000 直接當貨款。", "distractors": {}}, "check": "python 驗算:(80,000+100,000)/0.9+10,000=210,000,與官方相符。", "verified": true, "note": "單元歸類可能有爭議(銷貨折扣/退回,歸十二)。"}, {"id": "114-5-A-14", "exam": "114-5", "paper": "A", "q": 14, "unit": "十二、應收款項", "topic": "附息票據貼現", "stem": "大山公司於 X1 年 3 月 1 日賒銷商品一批$500,000,收到附息 5%、6 個月期票據乙紙。因大山公司急需用錢,等不到票據到期,所以於 X1 年 5 月 1 日將該票據轉讓給彰化銀行貼付利息以提早取得現金,銀行之貼現利率為 6%。彰化銀行依票據法要求大山公司進行「背書」以利日後可行使追索權,若發票人拒付,須另付拒絕證書費$200。有關上述大山公司應收票據貼現交易之敘述,下列何者錯誤?", "options": ["貼現日可借到之現金為$502,250", "若到期日發票人未如期付款,應借記:催收款項$512,700", "票據到期日,應認列「利息收入」$12,500 及「利息費用」$10,250", "因貼現日票據風險未移轉,故應另認列負債,貸記:應收票據貼現負債$502,250"], "answer": "D", "figure": null, "official": "到期值=$500,000+$500,000×5%×6/12=$512,500;貼現息=$512,500×6%×4/12=$10,250;現金=$502,250;貼現時貸記「應收票據貼現負債」為到期值 $512,500,不是 $502,250。", "explain": {"concept": "附息票據貼現:到期值→貼現息→貼現可得現金。票據貼現附追索權(風險未移轉),貼現時另認負債。", "steps": ["到期值=本金+利息=$500,000+$500,000×5%×6/12=$512,500。", "貼現期間 5/1 到 9/1(到期日)共 4 個月,貼現息=$512,500×6%×4/12=$10,250。", "貼現可得現金=$512,500−$10,250=$502,250,A 正確。", "若到期發票人拒付:要付拒絕證書費 $200,應收回金額=$512,500+$200=$512,700,借:催收款項 $512,700,B 正確。", "整個票據期間 6 個月的利息收入=$500,000×5%×6/12=$12,500;貼現 4 個月的利息費用=$10,250(貼現息),C 正確。", "D 錯:風險未移轉,貸記「應收票據貼現負債」的金額是票據到期值 $512,500,而非現金 $502,250。題目問錯誤,選 D。"], "pitfalls": "貼現負債的金額是到期值,不是貼現取得的現金;貼現息要用到期值計算。", "distractors": {}}, "check": "python 驗算:到期值 512,500;貼現息 10,250;現金 502,250;催收款項 512,700;利息收入 12,500,與官方相符。", "verified": true, "note": ""}, {"id": "114-5-A-15", "exam": "114-5", "paper": "A", "q": 15, "unit": "十三、存貨", "topic": "永續盤存制移動平均法", "stem": "大月公司為音響專賣商,存貨數量衡量方法採永續盤存制,X1 年 1 月 1 日音響存貨成本為$300,000(共 10 臺),X1 年 2 月 1 日進貨 30 臺,每臺成本$25,000、7 月 1 日進貨 40 臺,每臺成本$28,000。若 X1 年 5 月 1 日售出 20 臺,每臺售價$45,000,則依平均法計算之 X1 年 5 月 1 日銷貨成本應為多少?", "options": ["$500,000", "$525,000", "$550,000", "$900,000"], "answer": "B", "figure": null, "official": "永續盤存制平均法(移動平均):($300,000+30×$25,000)÷40 臺×20 臺=$525,000。", "explain": {"concept": "永續盤存制下,每次進貨後要重新計算平均單位成本(移動平均),出貨時用當時的平均成本。5/1 還沒有 7/1 的進貨。", "steps": ["5/1 以前的存貨:期初 10 臺 $300,000(每臺 $30,000)+2/1 進貨 30 臺 $750,000(30×$25,000)。", "合計 40 臺、成本 $1,050,000,平均單位成本=$1,050,000÷40=$26,250。", "5/1 出售 20 臺,銷貨成本=20×$26,250=$525,000。", "注意:7/1 進貨發生在 5/1 之後,永續盤存制不能用。"], "pitfalls": "容易把 7/1 的進貨也算進平均(那是定期盤存制的加權平均算法)。", "distractors": {"A": "可能只用 2/1 進貨單價 $25,000×20 臺,忽略期初存貨成本較高。", "C": "可能用期初單價 $30,000 與 $25,000 簡單平均 $27,500×20 臺。"}}, "check": "python 驗算:(300,000+750,000)/40*20=525,000,與官方相符。", "verified": true, "note": ""}, {"id": "114-5-A-16", "exam": "114-5", "paper": "A", "q": 16, "unit": "十三、存貨", "topic": "期末存貨錯誤的影響", "stem": "有四位學生就今天課堂上老師所教授之期末存貨錯誤對財務報表之影響進行討論,有關存貨盤存制度採定期盤存制下,期末存貨錯誤影響之觀念,下列幾位同學的說法正確?\n趙生:「期末存貨的錯誤,影響兩期損益,所以對下期保留盈餘就沒有影響了」\n錢生:「起運點交貨的進貨未入帳,期末盤點存貨也沒有列入,所以本期淨利會少計」\n孫生:「代別家商店銷售但尚未出售之商品,期末盤點存貨將之列入,會造成下期淨利少計」\n李生:「目的地交貨的銷貨,因在運送途中,期末盤點存貨漏列入,會造成本期銷貨成本多計」", "options": ["僅趙生、錢生正確", "僅錢生、孫生、李生正確", "僅趙生、孫生、李生正確", "趙生、錢生、孫生、李生均正確"], "answer": "C", "figure": null, "official": "錢生錯:進貨未入帳且存貨也未列入,不影響銷貨成本與損益;趙、孫、李正確。", "explain": {"concept": "期末存貨錯誤:本期期末存貨多(少)計→本期銷貨成本少(多)計→本期淨利多(少)計;下期期初存貨也相同錯誤→下期淨利相反;兩期合計互相抵銷,期末保留盈餘正確。", "steps": ["趙生:期末存貨錯誤,本期損益錯、下期損益反向錯,兩期互相抵銷,所以下期期末的保留盈餘沒有影響,正確。", "錢生:起運點交貨,貨物運送中,所有權已屬於買方(本公司)。進貨未入帳、存貨也沒列入,兩邊都漏,進貨與期末存貨同時少計,銷貨成本不變,淨利不受影響,所以「淨利會少計」是錯的。", "孫生:代銷品(寄銷品)屬於別家商店,不應列入本店存貨;錯列入→本期期末存貨多計→本期銷貨成本少計、淨利多計;下期期初存貨多計→下期銷貨成本多計、淨利少計,正確。", "李生:目的地交貨,運送途中所有權仍屬賣方(本公司),應列入存貨。漏列入→期末存貨少計→本期銷貨成本多計,正確。", "正確為趙、孫、李,選 C。"], "pitfalls": "進貨與存貨「同時漏記」會互相抵銷,對銷貨成本沒有影響。", "distractors": {"A": "認為錢生正確(進貨與存貨同時漏記其實互相抵銷、不影響淨利)且漏判孫生、李生。", "B": "誤信錢生,又漏掉趙生也正確(兩期損益會互相抵銷)。", "D": "錢生的說法不成立,不可能四人都對。"}}, "check": "概念題:代入數字推演各情況對銷貨成本與淨利的影響,趙孫李正確,C。", "verified": true, "note": ""}, {"id": "114-5-A-17", "exam": "114-5", "paper": "A", "q": 17, "unit": "十四、證券投資", "topic": "透過損益按公允價值衡量之金融資產", "stem": "大日公司 X1 年 4 月 1 日以現金購買大新公司 5,000 股普通股,作為透過損益按公允價值衡量之金融資產,成交價每股$50,另支付$1,000 的手續費。當年度 6 月 1 日收到大新公司 20%股票股利及每股$1 的現金股利。X1 年 8 月 1 日將持有大新公司股票全數出售,當日每股公允價值$45,並支付手續費$1,500。此項投資對於 X1 年度稅前淨利之影響,下列何者正確?", "options": ["稅前淨利增加$22,500", "稅前淨利增加$25,000", "稅前淨利減少$22,500", "稅前淨利減少$25,000"], "answer": "A", "figure": null, "official": "−$1,000(購入手續費)+$5,000(現金股利)−$1,500(出售手續費)+$20,000(衡量利益)=+$22,500。", "explain": {"concept": "FVTPL 金融資產:取得手續費直接當費用;現金股利為收入;股票股利只增加股數、不入帳;出售前以公允價值衡量,差額計入損益。", "steps": ["4/1 購入:成本=5,000 股×$50=$250,000;手續費 $1,000 當費用(淨利 −$1,000)。", "6/1 收到現金股利:$1×5,000 股=$5,000(股利收入,淨利 +$5,000)。股票股利 20% 只增加股數(5,000→6,000 股),不認列收入。", "8/1 出售前先衡量:6,000 股×$45=$270,000;與成本 $250,000 比,評價利益 $20,000(淨利 +$20,000)。", "出售手續費 $1,500(淨利 −$1,500)。", "合計:−$1,000+$5,000+$20,000−$1,500=+$22,500(淨利增加)。"], "pitfalls": "股票股利不是收入;股數變 6,000 股要用新股數乘公允價值;手續費兩次都要減。", "distractors": {"B": "可能把兩筆手續費($1,000、$1,500)忽略不計,得 $25,000。", "C": "把符號整個弄反。", "D": "符號弄反又把手續費當加項。"}}, "check": "python 驗算:−1,000+5,000−1,500+(270,000−250,000)=22,500,與官方相符。", "verified": true, "note": ""}, {"id": "114-5-A-18", "exam": "114-5", "paper": "A", "q": 18, "unit": "十五、長期營業用資產", "topic": "無形資產", "stem": "有關無形資產之敘述,下列哪幾項正確?\n①專利權成本應按法定年限或估計經濟年限兩者取較短者進行攤銷\n②非確定耐用年限之無形資產如廣播執照,不論在任何情況下,均不須攤銷\n③公開發行公司之商譽及非確定耐用年限的無形資產得選擇攤銷或不攤銷處理\n④專利權因侵權發生訴訟,不論因勝訴或敗訴所發生之訴訟支出均應認列為費用\n⑤公司自行研發之無形資產若無法區分屬於研究階段還是發展階段,相關支出一律認列為營業費用", "options": ["僅①、②、③正確", "僅①、④、⑤正確", "僅①、③、④、⑤正確", "僅②、③、④、⑤正確"], "answer": "B", "figure": null, "official": "①④⑤正確。②若廣播執照到期不申請換發新執照,應視為會計估計值變動,按剩餘年限攤銷;③公開發行公司商譽及非確定耐用年限的無形資產不得攤銷。", "explain": {"concept": "考無形資產攤銷與研發支出的處理:專利權取較短年限攤銷;非確定耐用年限不攤銷,但條件改變要攤銷;商譽(公開發行公司)不攤銷;研發階段區分。", "steps": ["①專利權有法定年限與經濟年限,取較短者攤銷,正確。", "②非確定耐用年限的無形資產(如廣播執照)通常不攤銷,但「不論任何情況」太絕對:若到期不申請換發,視為估計變動,要按剩餘年限攤銷,所以②錯。", "③公開發行公司的商譽與非確定耐用年限無形資產(依 IAS 38 與證券發行人財報編製準則第 9 條)不得攤銷,不可選擇,③錯。", "④專利權侵權訴訟支出,不論勝敗,均認列為費用(官方詳解視為正確),④正確。", "⑤研究與發展階段無法區分時,視為全部是研究階段,支出費用化,⑤正確。", "正確為①④⑤,選 B。"], "pitfalls": "「不論任何情況」「得選擇」這類絕對用語通常是陷阱。", "distractors": {"A": "以為②③正確,忽略廣播執照可能需攤銷、公開發行公司商譽不得攤銷。", "C": "多選了③,公開發行公司不得選擇攤銷。", "D": "多選②③,且漏掉①。"}}, "check": "概念題:對照官方詳解與 IAS 38,①④⑤正確,B。", "verified": true, "note": ""}, {"id": "114-5-A-19", "exam": "114-5", "paper": "A", "q": 19, "unit": "十五、長期營業用資產", "topic": "折舊方法變更與處分", "stem": "大新公司於 X1 年 7 月 1 日購買機器一部,成本$440,000,估計耐用年限 6 年,估計殘值$20,000,採年數合計法提列折舊。X3 年底為能更公允表達目前之經濟現況,故於調整前決定改採直線法提列折舊,經評估耐用年限剩餘 4 年,殘值不變。X5 年 7 月 1 日因考量此機器已無法應付現在產能,故決定另行購置,並將原有機器予以出售,售價為$100,000。有關此機器設備會計處理的敘述,下列何者正確?", "options": ["機器設備 X2 年度的「折舊」金額為$100,000", "機器設備 X3 年度的「折舊」金額為$62,500", "當機器設備除列時,借記:累計折舊-機器設備$295,000", "當機器設備除列時,借記:處分不動產、廠房及設備損失$25,000"], "answer": "C", "figure": null, "official": "X2 折舊 $110,000;X3 年 1/1 累計折舊 $170,000,帳面金額 $270,000,X3 起直線法每年($270,000−$20,000)÷5=$50,000;X5/7/1 累計折舊 $295,000;處分損失 $100,000−$145,000=$45,000。", "explain": {"concept": "年數合計法:折舊額=(成本−殘值)×剩餘年數÷年數合計;變更為直線法是會計估計變動,從變更當年起推延適用,以帳面金額為基礎重算。", "steps": ["可折舊成本=$440,000−$20,000=$420,000;6 年的年數合計=6+5+4+3+2+1=21。", "第一個折舊年度(X1/7/1~X2/6/30)折舊=$420,000×6/21=$120,000;第二年=$420,000×5/21=$100,000。", "X1 年(半年)=$120,000×1/2=$60,000;X2 年=$120,000×1/2+$100,000×1/2=$110,000(A 的 $100,000 錯)。", "X3 年 1/1 累計折舊=$60,000+$110,000=$170,000;帳面金額=$440,000−$170,000=$270,000。", "變更為直線法:官方以(帳面 $270,000−殘值 $20,000)÷(剩餘 4 年+1 年)=$50,000/年(題意為 X3 年底調整前決定改,所以 X3 全年也按新法)。B 的 $62,500 是 $250,000÷4,錯。", "X5/7/1 累計折舊=$170,000+$50,000×2.5=$295,000。", "除列分錄:借:現金 $100,000、借:累計折舊 $295,000、借:處分損失 $45,000;貸:機器設備 $440,000。所以 C 正確、D 的 $25,000 錯($145,000 帳面金額−$100,000 售價=$45,000)。"], "pitfalls": "變更折舊方法時,是用帳面金額重新攤提;剩餘年限要看是從哪一年開始計算。", "distractors": {"A": "漏算上、下兩個折舊年度的重疊(X2 年實為 $110,000)。", "B": "用 $250,000÷4 年,但官方的剩餘年限為 X3 年初起算的 5 年。", "D": "損失金額算成 $25,000(可能只算 X5 年上半年折舊),實為 $45,000。"}}, "check": "python 驗算:X2 折舊 110,000;累計折舊 295,000;損失 45,000,與官方相符。", "verified": true, "note": ""}, {"id": "114-5-A-20", "exam": "114-5", "paper": "A", "q": 20, "unit": "十五、長期營業用資產", "topic": "生物資產之衡量", "stem": "有關公允價值能可靠衡量之生物資產及其衡量模式之敘述,下列何者正確?", "options": ["購買生物資產所支付之運費,基於成本原則,應作為生物資產成本之增加", "該項生物資產其原始認列及續後評價,均應以「公允價值減出售成本」衡量", "生產葡萄之葡萄樹因與農業活動有關,且為具生命的植物,所以應列為生物資產", "所收成的農業產品,其於收成點及續後評價,均應以「公允價值減出售成本」衡量"], "answer": "B", "figure": null, "official": "(A)運費屬出售成本,非成本增加;(C)生產性植物(葡萄樹)屬不動產、廠房及設備;(D)收成點以公允價值減出售成本,續後比照存貨以成本與淨變現價值孰低衡量。", "explain": {"concept": "IAS 41:生物資產(能可靠衡量時)原始認列及每一報導期間結束日都以公允價值減出售成本衡量;生產性植物(如葡萄樹、茶樹)改適用 IAS 16;收成後的農產品之後適用存貨。", "steps": ["B:生物資產(如豬、牛、樹苗)原始認列與續後評價都以「公允價值減出售成本」衡量,正確。", "A:購買生物資產所支付的運費屬於「出售成本」的一部分(依官方詳解,購買運費不屬於資產成本),錯。", "C:葡萄樹可重複生產,屬「生產性植物」,應列為不動產、廠房及設備,而非生物資產,錯。", "D:農業產品在收成點以公允價值減出售成本認列,之後作為存貨,按「成本與淨變現價值孰低」衡量,錯。"], "pitfalls": "生產性植物(葡萄樹)與其結的果實(葡萄)是兩回事,樹是 PPE,果實才是農業產品。", "distractors": {"A": "以為購買運費要資本化;但生物資產以公允價值減出售成本衡量,運費屬出售成本。", "C": "看到「植物」就以為是生物資產,忽略生產性植物改適用 IAS 16。", "D": "混淆收成點與續後評價的衡量方式。"}}, "check": "概念題:官方詳解與 IAS 41/IAS 16 對照,B 正確。", "verified": true, "note": ""}, {"id": "114-5-A-21", "exam": "114-5", "paper": "A", "q": 21, "unit": "十五、長期營業用資產", "topic": "購入自用小客車與無息票據", "stem": "大芳公司於 X1 年 10 月 1 日購入供總經理使用之五人座自用乘人小汽車一部,營業稅稅率 5%,含稅現金價共計$1,050,000,簽發 6 個月期不附息票據乙紙付訖,若當時有效利率 6%,則下列敘述何者正確?", "options": ["運輸設備入帳成本為$1,000,000", "X2 年 4 月 1 日應償還現金$1,050,000", "X1 年 10 月 1 日應認列進項稅額$50,000", "X1 年 12 月 31 日應付票據帳面金額為$1,065,750"], "answer": "D", "figure": null, "official": "(A)自用乘人小汽車進項稅額不得扣抵,入帳成本為含稅價$1,050,000;(B)到期值=$1,050,000+$1,050,000×6%×6/12=$1,081,500;(C)進項稅額不得扣抵,要計入成本;(D)帳面金額=$1,050,000+$1,050,000×6%×3/12=$1,065,750。", "explain": {"concept": "購買自用乘人小汽車,進項稅額不得扣抵,要併入成本;不附息票據以「現金價」入帳,差額為應付票據折價,逐期攤銷利息。", "steps": ["含稅現金價 $1,050,000 = 價款 $1,000,000 + 營業稅 $50,000。自用乘人小汽車的進項稅額不得扣抵,所以入帳成本=$1,050,000,A、C 錯。", "簽發 6 個月不附息票據,實質上包含利息:到期應償還=$1,050,000×(1+6%×6/12)=$1,081,500,B 的 $1,050,000 錯。", "分錄:借:運輸設備 1,050,000、借:應付票據折價 31,500;貸:應付票據 1,081,500。", "12/31 已經過 3 個月(10/1~12/31),攤銷利息=$1,050,000×6%×3/12=$15,750,帳面金額=$1,050,000+$15,750=$1,065,750,D 正確。"], "pitfalls": "自用乘人小汽車進項稅額不可扣抵;不附息票據的面額要加上利息。", "distractors": {"A": "以為進項稅額可扣抵,成本只有 $1,000,000。", "B": "忽略不附息票據含有隱含利息,到期要還面額 $1,081,500。", "C": "自用乘人小汽車的進項稅額不得扣抵,不能認列進項稅額。"}}, "check": "python 驗算:到期值 1,081,500;12/31 帳面 1,065,750,與官方相符。", "verified": true, "note": "單元歸類可能有爭議(涉及營業稅、票據與固定資產成本,暫歸十五)。"}, {"id": "114-5-A-22", "exam": "114-5", "paper": "A", "q": 22, "unit": "十六、負債", "topic": "公司債折價發行與有效利率法", "stem": "大器股份有限公司因有擴建廠房之需求,經董事會決議以發行公司債籌措資金,故向金融監督管理委員會證券期貨局申報生效後,委由證券承銷商經銷。X1 年 1 月 1 日公司發行 10 年期、面額$5,000,000、票面利率 5%、有效利率 6%之公司債,該公司債每年 12 月 31 日支付利息,該公司以有效利率法攤銷折溢價。有關該公司債的敘述,下列何者正確?", "options": ["該公司債係採溢價發行", "該公司債每年底付現之利息逐期遞增", "該公司債每年底之帳面金額逐期遞增", "該公司債發行時所產生之會計師簽證費,應借記:手續費支出"], "answer": "C", "figure": null, "official": "票面 5%<有效 6% → 折價發行;每年付現利息固定($5,000,000×5%);折價逐年攤銷,帳面金額逐期遞增至面額;發行成本應借記應付公司債折價。", "explain": {"concept": "票面利率與有效利率比較:票面<有效→折價;票面>有效→溢價。折價發行的帳面金額逐期增加到面額。", "steps": ["A:票面利率 5% 低於市場有效利率 6%,投資人要求更高報酬,所以公司債以低於面額(折價)發行,A 錯。", "B:每年付現利息=面額×票面利率=$5,000,000×5%=$250,000,每年相同,B 錯。", "C:折價每期攤銷,應付公司債折價餘額逐期減少,帳面金額(面額−未攤銷折價)逐期增加到面額,C 正確。", "D:公司債的發行成本(如簽證費、承銷費)要減少公司債帳面金額,借記「應付公司債折價」,不是手續費支出,D 錯。"], "pitfalls": "付現利息固定看票面利率;利息費用才用有效利率,逐期變動。", "distractors": {"A": "把票面利率低於市場利率誤判為溢價。", "B": "把利息費用(逐期遞增)與付現利息(固定)混淆。", "D": "以為發行成本是當期費用。"}}, "check": "概念題:票面 5%<有效 6% 為折價;官方詳解對照,C 正確。", "verified": true, "note": ""}, {"id": "114-5-A-23", "exam": "114-5", "paper": "A", "q": 23, "unit": "十六、負債", "topic": "流動負債金額計算", "stem": "大業股份有限公司 X1 年底有下列事項:\n(1) X1 年應付股利$50,000,待分配股票股利$100,000\n(2) X1 年 9 月 1 日購入商品簽發六個月之不附息票據$61,800(有效利率 6%)\n(3) 應付帳款統制帳貸餘$80,000,其中應付帳款明細帳借餘者合計為$10,000\n(4) 在彰化銀行有「銀行存款」$900,000、「銀行透支」$100,000(銀行透支是企業整體現金管理的一部分)\n(5) 11 月及 12 月份之進項稅額$30,000、銷項稅額$50,000,上期無留抵稅額,年底已完成結算分錄\n(6) 本公司被控告侵權,律師評估很有可能敗訴,且於一年內須完成賠償,賠償金額$1,000,000 發生的機率為 30%,賠償金額$600,000 發生的機率為 70%\n則 X1 年底財務報表上之流動負債之金額為多少?", "options": ["$821,800", "$851,800", "$941,200", "$971,200"], "answer": "A", "figure": null, "official": "流動負債=$50,000+$61,800+$90,000+$20,000+$600,000=$821,800。", "explain": {"concept": "逐項判斷是否為流動負債:應付股利是;待分配股票股利是權益;無息票據以到期面額列帳(短期不折現);應付帳款明細帳貸餘合計才是負債;銀行透支屬現金管理、與存款互抵;應付營業稅=銷項−進項;很可能敗訴且金額為一範圍,取單一事件最可能金額。", "steps": ["(1) 應付股利 $50,000 是流動負債;待分配股票股利 $100,000 屬權益,不是負債。流動負債 +$50,000。", "(2) 購貨簽發六個月不附息票據,一年內到期,按面額 $61,800 列流動負債(短期票據不折現)。+$61,800。", "(3) 應付帳款統制帳貸餘 $80,000,其中有明細帳借餘 $10,000;貸餘明細合計=$80,000+$10,000=$90,000 才是應付帳款;借餘 $10,000 屬預付款項(資產)。+$90,000。", "(4) 銀行透支是企業整體現金管理的一部分,與銀行存款互抵:$900,000−$100,000=$800,000 屬資產(現金),不是負債。+$0。", "(5) 銷項稅額 $50,000−進項稅額 $30,000=應付營業稅 $20,000(流動負債)。+$20,000。", "(6) 很可能敗訴且須一年內賠償,單一事件以「發生機率最大者」$600,000(70%)認列負債。+$600,000。", "合計:$50,000+$61,800+$90,000+$20,000+$600,000=$821,800。"], "pitfalls": "應付帳款明細借餘要加回再算;股票股利不是負債;或有負債單一事件用最可能金額,不用期望值。", "distractors": {}}, "check": "python 驗算:50,000+61,800+90,000+20,000+600,000=821,800,與官方相符。", "verified": true, "note": ""}, {"id": "114-5-A-24", "exam": "114-5", "paper": "A", "q": 24, "unit": "十七、權益", "topic": "每股盈餘之流通在外股數與加權平均股數", "stem": "大統股份有限公司 X1 年普通股之相關資料如下:1 月 1 日流通在外 100,000 股普通股,3 月 1 日現金增資發行 20,000 股,5 月 1 日發放 20%股票股利,7 月 1 日購買庫藏股票 5,000 股,11 月 1 日普通股 1 股分割為 2 股。則大統股份有限公司 X1 年底「普通股流通在外股數」及 X1 年度「普通股流通在外加權平均股數」分別為多少股?\n\n| | 普通股流通在外股數 | 普通股流通在外加權平均股數 |\n|---|---|---|\n| (A) | 298,000 股 | 285,000 股 |\n| (B) | 285,000 股 | 298,000 股 |\n| (C) | 278,000 股 | 275,000 股 |\n| (D) | 275,000 股 | 278,000 股 |", "options": ["298,000 股;285,000 股", "285,000 股;298,000 股", "278,000 股;275,000 股", "275,000 股;278,000 股"], "answer": "C", "figure": null, "official": "年底流通在外=100,000×1.2×2+20,000×1.2×2−5,000×2=278,000 股;加權平均=100,000×1.2×2+20,000×1.2×2×10/12−5,000×2×6/12=275,000 股。", "explain": {"concept": "股票股利與股票分割要追溯調整(視為年初就發行,不按時間加權);現金增資、庫藏股按流通月數加權。", "steps": ["先把「股票股利 20%」和「股票分割 1 變 2」這兩個追溯調整的因素算出來:股票股利 ×1.2,分割 ×2,兩者都要回溯到之前的股數。", "年底流通在外股數:期初 100,000 股→×1.2×2=240,000 股;3/1 增資 20,000 股→×1.2×2=48,000 股;庫藏股 5,000 股(7/1 買,在股票分割 11/1 前)→×2=10,000 股,要減掉。=240,000+48,000−10,000=278,000 股。", "加權平均:期初 240,000 股流通整年(12/12)=240,000;現金增資 48,000 股從 3/1 起流通 10 個月=48,000×10/12=40,000;庫藏股 10,000 股(5,000×2)7/1 起減少 6 個月=10,000×6/12=5,000(減項)。", "合計:240,000+40,000−5,000=275,000 股。所以選 C(278,000;275,000)。"], "pitfalls": "股票股利、分割不按時間加權(追溯調整),現金增資與庫藏股才加權;庫藏股也要因為後來的分割而 ×2。", "distractors": {"D": "兩欄數字弄反(275,000 與 278,000):年底流通在外股數不按月數加權,所以是 278,000。"}}, "check": "python 驗算:278,000 與 275,000,與官方相符。", "verified": true, "note": ""}];